-- ============================================================
-- 圣经全文（新改訳2017）· 数据文件 6/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5087 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '路加福音', 42, 24, 19, 'イエスが「どんなことですか」と言われると、二人は答えた。「ナザレ人イエス様のことです。この方は、神と民全体の前で、行いにもことばにも力のある預言者でした。'),
('JPN', '路加福音', 42, 24, 20, 'それなのに、私たちの祭司長たちや議員たちは、この方を死刑にするために引き渡して、十字架につけてしまいました。'),
('JPN', '路加福音', 42, 24, 21, '私たちは、この方こそイスラエルを解放する方だ、と望みをかけていました。実際、そればかりではありません。そのことがあってから三日目になりますが、'),
('JPN', '路加福音', 42, 24, 22, '仲間の女たちの何人かが、私たちを驚かせました。彼女たちは朝早く墓に行きましたが、'),
('JPN', '路加福音', 42, 24, 23, 'イエス様のからだが見当たらず、戻って来ました。そして、自分たちは御使いたちの幻を見た、彼らはイエス様が生きておられると告げた、と言うのです。'),
('JPN', '路加福音', 42, 24, 24, 'それで、仲間の何人かが墓に行ってみたのですが、まさしく彼女たちの言ったとおりで、あの方は見当たりませんでした。」'),
('JPN', '路加福音', 42, 24, 25, 'そこでイエスは彼らに言われた。「ああ、愚かな者たち。心が鈍くて、預言者たちの言ったことすべてを信じられない者たち。'),
('JPN', '路加福音', 42, 24, 26, 'キリストは必ずそのような苦しみを受け、それから、その栄光に入るはずだったのではありませんか。」'),
('JPN', '路加福音', 42, 24, 27, 'それからイエスは、モーセやすべての預言者たちから始めて、ご自分について聖書全体に書いてあることを彼らに説き明かされた。'),
('JPN', '路加福音', 42, 24, 28, '彼らは目的の村の近くに来たが、イエスはもっと先まで行きそうな様子であった。'),
('JPN', '路加福音', 42, 24, 29, '彼らが、「一緒にお泊まりください。そろそろ夕刻になりますし、日もすでに傾いています」と言って強く勧めたので、イエスは彼らとともに泊まるため、中に入られた。'),
('JPN', '路加福音', 42, 24, 30, 'そして彼らと食卓に着くと、イエスはパンを取って神をほめたたえ、裂いて彼らに渡された。'),
('JPN', '路加福音', 42, 24, 31, 'すると彼らの目が開かれ、イエスだと分かったが、その姿は見えなくなった。'),
('JPN', '路加福音', 42, 24, 32, '二人は話し合った。「道々お話しくださる間、私たちに聖書を説き明かしてくださる間、私たちの心は内で燃えていたではないか。」'),
('JPN', '路加福音', 42, 24, 33, '二人はただちに立ち上がり、エルサレムに戻った。すると、十一人とその仲間が集まって、'),
('JPN', '路加福音', 42, 24, 34, '「本当に主はよみがえって、シモンに姿を現された」と話していた。'),
('JPN', '路加福音', 42, 24, 35, 'そこで二人も、道中で起こったことや、パンを裂かれたときにイエスだと分かった次第を話した。'),
('JPN', '路加福音', 42, 24, 36, 'これらのことを話していると、イエスご自身が彼らの真ん中に立ち、「平安があなたがたにあるように」と言われた。'),
('JPN', '路加福音', 42, 24, 37, '彼らはおびえて震え上がり、幽霊を見ているのだと思った。'),
('JPN', '路加福音', 42, 24, 38, 'そこで、イエスは言われた。「なぜ取り乱しているのですか。どうして心に疑いを抱くのですか。'),
('JPN', '路加福音', 42, 24, 39, 'わたしの手やわたしの足を見なさい。まさしくわたしです。わたしにさわって、よく見なさい。幽霊なら肉や骨はありません。見て分かるように、わたしにはあります。」'),
('JPN', '路加福音', 42, 24, 40, 'こう言って、イエスは彼らに手と足を見せられた。'),
('JPN', '路加福音', 42, 24, 41, '彼らが喜びのあまりまだ信じられず、不思議がっていたので、イエスは、「ここに何か食べ物がありますか」と言われた。'),
('JPN', '路加福音', 42, 24, 42, 'そこで、焼いた魚を一切れ差し出すと、'),
('JPN', '路加福音', 42, 24, 43, 'イエスはそれを取って、彼らの前で召し上がった。'),
('JPN', '路加福音', 42, 24, 44, 'そしてイエスは言われた。「わたしがまだあなたがたと一緒にいたころ、あなたがたに話したことばはこうです。わたしについて、モーセの律法と預言者たちの書と詩篇に書いてあることは、すべて成就しなければなりません。」'),
('JPN', '路加福音', 42, 24, 45, 'それからイエスは、聖書を悟らせるために彼らの心を開いて、'),
('JPN', '路加福音', 42, 24, 46, 'こう言われた。「次のように書いてあります。『キリストは苦しみを受け、三日目に死人の中からよみがえり、'),
('JPN', '路加福音', 42, 24, 47, 'その名によって、罪の赦しを得させる悔い改めが、あらゆる国の人々に宣べ伝えられる。』エルサレムから開始して、'),
('JPN', '路加福音', 42, 24, 48, 'あなたがたは、これらのことの証人となります。'),
('JPN', '路加福音', 42, 24, 49, '見よ。わたしは、わたしの父が約束されたものをあなたがたに送ります。あなたがたは、いと高き所から力を着せられるまでは、都にとどまっていなさい。」'),
('JPN', '路加福音', 42, 24, 50, 'それからイエスは、弟子たちをベタニアの近くまで連れて行き、手を上げて祝福された。'),
('JPN', '路加福音', 42, 24, 51, 'そして、祝福しながら彼らから離れて行き、天に上げられた。'),
('JPN', '路加福音', 42, 24, 52, '彼らはイエスを礼拝した後、大きな喜びとともにエルサレムに帰り、'),
('JPN', '路加福音', 42, 24, 53, 'いつも宮にいて神をほめたたえていた。'),
('JPN', '约翰福音', 43, 1, 1, '初めにことばがあった。ことばは神とともにあった。ことばは神であった。'),
('JPN', '约翰福音', 43, 1, 2, 'この方は、初めに神とともにおられた。'),
('JPN', '约翰福音', 43, 1, 3, 'すべてのものは、この方によって造られた。造られたもので、この方によらずにできたものは一つもなかった。'),
('JPN', '约翰福音', 43, 1, 4, 'この方にはいのちがあった。このいのちは人の光であった。'),
('JPN', '约翰福音', 43, 1, 5, '光は闇の中に輝いている。闇はこれに打ち勝たなかった。'),
('JPN', '约翰福音', 43, 1, 6, '神から遣わされた一人の人が現れた。その名はヨハネであった。'),
('JPN', '约翰福音', 43, 1, 7, 'この人は証しのために来た。光について証しするためであり、彼によってすべての人が信じるためであった。'),
('JPN', '约翰福音', 43, 1, 8, '彼は光ではなかった。ただ光について証しするために来たのである。'),
('JPN', '约翰福音', 43, 1, 9, 'すべての人を照らすそのまことの光が、世に来ようとしていた。'),
('JPN', '约翰福音', 43, 1, 10, 'この方はもとから世におられ、世はこの方によって造られたのに、世はこの方を知らなかった。'),
('JPN', '约翰福音', 43, 1, 11, 'この方はご自分のところに来られたのに、ご自分の民はこの方を受け入れなかった。'),
('JPN', '约翰福音', 43, 1, 12, 'しかし、この方を受け入れた人々、すなわち、その名を信じた人々には、神の子どもとなる特権をお与えになった。'),
('JPN', '约翰福音', 43, 1, 13, 'この人々は、血によってではなく、肉の望むところでも人の意志によってでもなく、ただ、神によって生まれたのである。'),
('JPN', '约翰福音', 43, 1, 14, 'ことばは人となって、私たちの間に住まわれた。私たちはこの方の栄光を見た。父のみもとから来られたひとり子としての栄光である。この方は恵みとまことに満ちておられた。'),
('JPN', '约翰福音', 43, 1, 15, 'ヨハネはこの方について証しして、こう叫んだ。「『私の後に来られる方は、私にまさる方です。私より先におられたからです』と私が言ったのは、この方のことです。」'),
('JPN', '约翰福音', 43, 1, 16, '私たちはみな、この方の満ち満ちた豊かさの中から、恵みの上にさらに恵みを受けた。'),
('JPN', '约翰福音', 43, 1, 17, '律法はモーセによって与えられ、恵みとまことはイエス・キリストによって実現したからである。'),
('JPN', '约翰福音', 43, 1, 18, 'いまだかつて神を見た者はいない。父のふところにおられるひとり子の神が、神を説き明かされたのである。'),
('JPN', '约翰福音', 43, 1, 19, 'さて、ヨハネの証しはこうである。ユダヤ人たちが、祭司たちとレビ人たちをエルサレムから遣わして、「あなたはどなたですか」と尋ねたとき、'),
('JPN', '约翰福音', 43, 1, 20, 'ヨハネはためらうことなく告白し、「私はキリストではありません」と明言した。'),
('JPN', '约翰福音', 43, 1, 21, '彼らはヨハネに尋ねた。「それでは、何者なのですか。あなたはエリヤですか。」ヨハネは「違います」と言った。「では、あの預言者ですか。」ヨハネは「違います」と答えた。'),
('JPN', '约翰福音', 43, 1, 22, 'それで、彼らはヨハネに言った。「あなたはだれですか。私たちを遣わした人たちに返事を伝えたいのですが、あなたは自分を何だと言われるのですか。」'),
('JPN', '约翰福音', 43, 1, 23, 'ヨハネは言った。「私は、預言者イザヤが言った、『主の道をまっすぐにせよ、と荒野で叫ぶ者の声』です。」'),
('JPN', '约翰福音', 43, 1, 24, '彼らは、パリサイ人から遣わされて来ていた。'),
('JPN', '约翰福音', 43, 1, 25, '彼らはヨハネに尋ねた。「キリストでもなく、エリヤでもなく、あの預言者でもないなら、なぜ、あなたはバプテスマを授けているのですか。」'),
('JPN', '约翰福音', 43, 1, 26, 'ヨハネは彼らに答えた。「私は水でバプテスマを授けていますが、あなたがたの中に、あなたがたの知らない方が立っておられます。'),
('JPN', '约翰福音', 43, 1, 27, 'その方は私の後に来られる方で、私にはその方の履き物のひもを解く値打ちもありません。」'),
('JPN', '约翰福音', 43, 1, 28, 'このことがあったのは、ヨルダンの川向こうのベタニアであった。ヨハネはそこでバプテスマを授けていたのである。'),
('JPN', '约翰福音', 43, 1, 29, 'その翌日、ヨハネは自分の方にイエスが来られるのを見て言った。「見よ、世の罪を取り除く神の子羊。'),
('JPN', '约翰福音', 43, 1, 30, '『私の後に一人の人が来られます。その方は私にまさる方です。私より先におられたからです』と私が言ったのは、この方のことです。'),
('JPN', '约翰福音', 43, 1, 31, '私自身もこの方を知りませんでした。しかし、私が来て水でバプテスマを授けているのは、この方がイスラエルに明らかにされるためです。」'),
('JPN', '约翰福音', 43, 1, 32, 'そして、ヨハネはこのように証しした。「御霊が鳩のように天から降って、この方の上にとどまるのを私は見ました。'),
('JPN', '约翰福音', 43, 1, 33, '私自身もこの方を知りませんでした。しかし、水でバプテスマを授けるようにと私を遣わした方が、私に言われました。『御霊が、ある人の上に降って、その上にとどまるのをあなたが見たら、その人こそ、聖霊によってバプテスマを授ける者である。』'),
('JPN', '约翰福音', 43, 1, 34, '私はそれを見ました。それで、この方が神の子であると証しをしているのです。」'),
('JPN', '约翰福音', 43, 1, 35, 'その翌日、ヨハネは再び二人の弟子とともに立っていた。'),
('JPN', '约翰福音', 43, 1, 36, 'そしてイエスが歩いて行かれるのを見て、「見よ、神の子羊」と言った。'),
('JPN', '约翰福音', 43, 1, 37, '二人の弟子は、彼がそう言うのを聞いて、イエスについて行った。'),
('JPN', '约翰福音', 43, 1, 38, 'イエスは振り向いて、彼らがついて来るのを見て言われた。「あなたがたは何を求めているのですか。」彼らは言った。「ラビ（訳すと、先生）、どこにお泊まりですか。」'),
('JPN', '约翰福音', 43, 1, 39, 'イエスは彼らに言われた。「来なさい。そうすれば分かります。」そこで、彼らはついて行って、イエスが泊まっておられるところを見た。そしてその日、イエスのもとにとどまった。時はおよそ第十の時であった。'),
('JPN', '约翰福音', 43, 1, 40, 'ヨハネから聞いてイエスについて行った二人のうちの一人は、シモン・ペテロの兄弟アンデレであった。'),
('JPN', '约翰福音', 43, 1, 41, '彼はまず自分の兄弟シモンを見つけて、「私たちはメシア（訳すと、キリスト）に会った」と言った。'),
('JPN', '约翰福音', 43, 1, 42, '彼はシモンをイエスのもとに連れて来た。イエスはシモンを見つめて言われた。「あなたはヨハネの子シモンです。あなたはケファ（言い換えれば、ペテロ）と呼ばれます。」'),
('JPN', '约翰福音', 43, 1, 43, 'その翌日、イエスはガリラヤに行こうとされた。そして、ピリポを見つけて、「わたしに従って来なさい」と言われた。'),
('JPN', '约翰福音', 43, 1, 44, '彼はベツサイダの人で、アンデレやペテロと同じ町の出身であった。'),
('JPN', '约翰福音', 43, 1, 45, 'ピリポはナタナエルを見つけて言った。「私たちは、モーセが律法の中に書き、預言者たちも書いている方に会いました。ナザレの人で、ヨセフの子イエスです。」'),
('JPN', '约翰福音', 43, 1, 46, 'ナタナエルは彼に言った。「ナザレから何か良いものが出るだろうか。」ピリポは言った。「来て、見なさい。」'),
('JPN', '约翰福音', 43, 1, 47, 'イエスはナタナエルが自分の方に来るのを見て、彼について言われた。「見なさい。まさにイスラエル人です。この人には偽りがありません。」'),
('JPN', '约翰福音', 43, 1, 48, 'ナタナエルはイエスに言った。「どうして私をご存じなのですか。」イエスは答えられた。「ピリポがあなたを呼ぶ前に、あなたがいちじくの木の下にいるのを見ました。」'),
('JPN', '约翰福音', 43, 1, 49, 'ナタナエルは答えた。「先生、あなたは神の子です。あなたはイスラエルの王です。」'),
('JPN', '约翰福音', 43, 1, 50, 'イエスは答えられた。「あなたがいちじくの木の下にいるのを見た、とわたしが言ったから信じるのですか。それよりも大きなことを、あなたは見ることになります。」'),
('JPN', '约翰福音', 43, 1, 51, 'そして言われた。「まことに、まことに、あなたがたに言います。天が開けて、神の御使いたちが人の子の上を上り下りするのを、あなたがたは見ることになります。」'),
('JPN', '约翰福音', 43, 2, 1, 'それから三日目に、ガリラヤのカナで婚礼があり、そこにイエスの母がいた。'),
('JPN', '约翰福音', 43, 2, 2, 'イエスも弟子たちも、その婚礼に招かれていた。'),
('JPN', '约翰福音', 43, 2, 3, 'ぶどう酒がなくなると、母はイエスに向かって「ぶどう酒がありません」と言った。'),
('JPN', '约翰福音', 43, 2, 4, 'すると、イエスは母に言われた。「女の方、あなたはわたしと何の関係がありますか。わたしの時はまだ来ていません。」'),
('JPN', '约翰福音', 43, 2, 5, '母は給仕の者たちに言った。「あの方が言われることは、何でもしてください。」'),
('JPN', '约翰福音', 43, 2, 6, 'そこには、ユダヤ人のきよめのしきたりによって、石の水がめが六つ置いてあった。それぞれ、二あるいは三メトレテス入りのものであった。'),
('JPN', '约翰福音', 43, 2, 7, 'イエスは給仕の者たちに言われた。「水がめを水でいっぱいにしなさい。」彼らは水がめを縁までいっぱいにした。'),
('JPN', '约翰福音', 43, 2, 8, 'イエスは彼らに言われた。「さあ、それを汲んで、宴会の世話役のところに持って行きなさい。」彼らは持って行った。'),
('JPN', '约翰福音', 43, 2, 9, '宴会の世話役は、すでにぶどう酒になっていたその水を味見した。汲んだ給仕の者たちはそれがどこから来たのかを知っていたが、世話役は知らなかった。それで、花婿を呼んで、'),
('JPN', '约翰福音', 43, 2, 10, 'こう言った。「みな、初めに良いぶどう酒を出して、酔いが回ったころに悪いのを出すものだが、あなたは良いぶどう酒を今まで取っておきました。」'),
('JPN', '约翰福音', 43, 2, 11, 'イエスはこれを最初のしるしとしてガリラヤのカナで行い、ご自分の栄光を現された。それで、弟子たちはイエスを信じた。'),
('JPN', '约翰福音', 43, 2, 12, 'その後イエスは、母と弟たち、そして弟子たちとともにカペナウムに下って行き、長い日数ではなかったが、そこに滞在された。'),
('JPN', '约翰福音', 43, 2, 13, 'さて、ユダヤ人の過越の祭りが近づき、イエスはエルサレムに上られた。'),
('JPN', '约翰福音', 43, 2, 14, 'そして、宮の中で、牛や羊や鳩を売っている者たちと、座って両替をしている者たちを見て、'),
('JPN', '约翰福音', 43, 2, 15, '細縄でむちを作って、羊も牛もみな宮から追い出し、両替人の金を散らして、その台を倒し、'),
('JPN', '约翰福音', 43, 2, 16, '鳩を売っている者たちに言われた。「それをここから持って行け。わたしの父の家を商売の家にしてはならない。」'),
('JPN', '约翰福音', 43, 2, 17, '弟子たちは、「あなたの家を思う熱心が私を食い尽くす」と書いてあるのを思い起こした。'),
('JPN', '约翰福音', 43, 2, 18, 'すると、ユダヤ人たちがイエスに対して言った。「こんなことをするからには、どんなしるしを見せてくれるのか。」'),
('JPN', '约翰福音', 43, 2, 19, 'イエスは彼らに答えられた。「この神殿を壊してみなさい。わたしは、三日でそれをよみがえらせる。」'),
('JPN', '约翰福音', 43, 2, 20, 'そこで、ユダヤ人たちは言った。「この神殿は建てるのに四十六年かかった。あなたはそれを三日でよみがえらせるのか。」'),
('JPN', '约翰福音', 43, 2, 21, 'しかし、イエスはご自分のからだという神殿について語られたのであった。'),
('JPN', '约翰福音', 43, 2, 22, 'それで、イエスが死人の中からよみがえられたとき、弟子たちは、イエスがこのように言われたことを思い起こして、聖書とイエスが言われたことばを信じた。'),
('JPN', '约翰福音', 43, 2, 23, '過越の祭りの祝いの間、イエスがエルサレムにおられたとき、多くの人々がイエスの行われたしるしを見て、その名を信じた。'),
('JPN', '约翰福音', 43, 2, 24, 'しかし、イエスご自身は、彼らに自分をお任せにならなかった。すべての人を知っていたので、'),
('JPN', '约翰福音', 43, 2, 25, '人についてだれの証言も必要とされなかったからである。イエスは、人のうちに何があるかを知っておられたのである。'),
('JPN', '约翰福音', 43, 3, 1, 'さて、パリサイ人の一人で、ニコデモという名の人がいた。ユダヤ人の議員であった。'),
('JPN', '约翰福音', 43, 3, 2, 'この人が、夜、イエスのもとに来て言った。「先生。私たちは、あなたが神のもとから来られた教師であることを知っています。神がともにおられなければ、あなたがなさっているこのようなしるしは、だれも行うことができません。」'),
('JPN', '约翰福音', 43, 3, 3, 'イエスは答えられた。「まことに、まことに、あなたに言います。人は、新しく生まれなければ、神の国を見ることはできません。」'),
('JPN', '约翰福音', 43, 3, 4, 'ニコデモはイエスに言った。「人は、老いていながら、どうやって生まれることができますか。もう一度、母の胎に入って生まれることなどできるでしょうか。」'),
('JPN', '约翰福音', 43, 3, 5, 'イエスは答えられた。「まことに、まことに、あなたに言います。人は、水と御霊によって生まれなければ、神の国に入ることはできません。'),
('JPN', '约翰福音', 43, 3, 6, '肉によって生まれた者は肉です。御霊によって生まれた者は霊です。'),
('JPN', '约翰福音', 43, 3, 7, 'あなたがたは新しく生まれなければならない、とわたしが言ったことを不思議に思ってはなりません。'),
('JPN', '约翰福音', 43, 3, 8, '風は思いのままに吹きます。その音を聞いても、それがどこから来てどこへ行くのか分かりません。御霊によって生まれた者もみな、それと同じです。」'),
('JPN', '约翰福音', 43, 3, 9, 'ニコデモは答えた。「どうして、そのようなことがあり得るでしょうか。」'),
('JPN', '约翰福音', 43, 3, 10, 'イエスは答えられた。「あなたはイスラエルの教師なのに、そのことが分からないのですか。'),
('JPN', '约翰福音', 43, 3, 11, 'まことに、まことに、あなたに言います。わたしたちは知っていることを話し、見たことを証ししているのに、あなたがたはわたしたちの証しを受け入れません。'),
('JPN', '约翰福音', 43, 3, 12, 'わたしはあなたがたに地上のことを話しましたが、あなたがたは信じません。それなら、天上のことを話して、どうして信じるでしょうか。'),
('JPN', '约翰福音', 43, 3, 13, 'だれも天に上った者はいません。しかし、天から下って来た者、人の子は別です。'),
('JPN', '约翰福音', 43, 3, 14, 'モーセが荒野で蛇を上げたように、人の子も上げられなければなりません。'),
('JPN', '约翰福音', 43, 3, 15, 'それは、信じる者がみな、人の子にあって永遠のいのちを持つためです。」'),
('JPN', '约翰福音', 43, 3, 16, '神は、実に、そのひとり子をお与えになったほどに世を愛された。それは御子を信じる者が、一人として滅びることなく、永遠のいのちを持つためである。'),
('JPN', '约翰福音', 43, 3, 17, '神が御子を世に遣わされたのは、世をさばくためではなく、御子によって世が救われるためである。'),
('JPN', '约翰福音', 43, 3, 18, '御子を信じる者はさばかれない。信じない者はすでにさばかれている。神のひとり子の名を信じなかったからである。'),
('JPN', '约翰福音', 43, 3, 19, 'そのさばきとは、光が世に来ているのに、自分の行いが悪いために、人々が光よりも闇を愛したことである。'),
('JPN', '约翰福音', 43, 3, 20, '悪を行う者はみな、光を憎み、その行いが明るみに出されることを恐れて、光の方に来ない。'),
('JPN', '约翰福音', 43, 3, 21, 'しかし、真理を行う者は、その行いが神にあってなされたことが明らかになるように、光の方に来る。'),
('JPN', '约翰福音', 43, 3, 22, 'その後、イエスは弟子たちとユダヤの地に行き、彼らとともにそこに滞在して、バプテスマを授けておられた。'),
('JPN', '约翰福音', 43, 3, 23, '一方ヨハネも、サリムに近いアイノンでバプテスマを授けていた。そこには水が豊かにあったからである。人々はやって来て、バプテスマを受けていた。'),
('JPN', '约翰福音', 43, 3, 24, 'ヨハネは、まだ投獄されていなかった。'),
('JPN', '约翰福音', 43, 3, 25, 'ところで、ヨハネの弟子の何人かが、あるユダヤ人ときよめについて論争をした。'),
('JPN', '约翰福音', 43, 3, 26, '彼らはヨハネのところに来て言った。「先生。ヨルダンの川向こうで先生と一緒にいて、先生が証しされたあの方が、なんと、バプテスマを授けておられます。そして、皆があの方のほうに行っています。」'),
('JPN', '约翰福音', 43, 3, 27, 'ヨハネは答えた。「人は、天から与えられるのでなければ、何も受けることができません。'),
('JPN', '约翰福音', 43, 3, 28, '『私はキリストではありません。むしろ、その方の前に私は遣わされたのです』と私が言ったことは、あなたがた自身が証ししてくれます。'),
('JPN', '约翰福音', 43, 3, 29, '花嫁を迎えるのは花婿です。そばに立って花婿が語ることに耳を傾けている友人は、花婿の声を聞いて大いに喜びます。ですから、私もその喜びに満ちあふれています。'),
('JPN', '约翰福音', 43, 3, 30, 'あの方は盛んになり、私は衰えなければなりません。」'),
('JPN', '约翰福音', 43, 3, 31, '上から来られる方は、すべてのものの上におられる。地から出る者は地に属し、地のことを話す。天から来られる方は、すべてのものの上におられる。'),
('JPN', '约翰福音', 43, 3, 32, 'この方は見たこと、聞いたことを証しされるが、だれもその証しを受け入れない。'),
('JPN', '约翰福音', 43, 3, 33, 'その証しを受け入れた者は、神が真実であると認める印を押したのである。'),
('JPN', '约翰福音', 43, 3, 34, '神が遣わした方は、神のことばを語られる。神が御霊を限りなくお与えになるからである。'),
('JPN', '约翰福音', 43, 3, 35, '父は御子を愛しておられ、その手にすべてをお与えになった。'),
('JPN', '约翰福音', 43, 3, 36, '御子を信じる者は永遠のいのちを持っているが、御子に聞き従わない者はいのちを見ることがなく、神の怒りがその上にとどまる。'),
('JPN', '约翰福音', 43, 4, 1, 'パリサイ人たちは、イエスがヨハネよりも多くの弟子を作ってバプテスマを授けている、と伝え聞いた。それを知るとイエスは、'),
('JPN', '约翰福音', 43, 4, 2, '──バプテスマを授けていたのはイエスご自身ではなく、弟子たちであったのだが──'),
('JPN', '约翰福音', 43, 4, 3, 'ユダヤを去って、再びガリラヤへ向かわれた。'),
('JPN', '约翰福音', 43, 4, 4, 'しかし、サマリアを通って行かなければならなかった。'),
('JPN', '约翰福音', 43, 4, 5, 'それでイエスは、ヤコブがその子ヨセフに与えた地所に近い、スカルというサマリアの町に来られた。'),
('JPN', '约翰福音', 43, 4, 6, 'そこにはヤコブの井戸があった。イエスは旅の疲れから、その井戸の傍らに、ただ座っておられた。時はおよそ第六の時であった。'),
('JPN', '约翰福音', 43, 4, 7, '一人のサマリアの女が、水を汲みに来た。イエスは彼女に、「わたしに水を飲ませてください」と言われた。'),
('JPN', '约翰福音', 43, 4, 8, '弟子たちは食物を買いに、町へ出かけていた。'),
('JPN', '约翰福音', 43, 4, 9, 'そのサマリアの女は言った。「あなたはユダヤ人なのに、どうしてサマリアの女の私に、飲み水をお求めになるのですか。」ユダヤ人はサマリア人と付き合いをしなかったのである。'),
('JPN', '约翰福音', 43, 4, 10, 'イエスは答えられた。「もしあなたが神の賜物を知り、また、水を飲ませてくださいとあなたに言っているのがだれなのかを知っていたら、あなたのほうからその人に求めていたでしょう。そして、その人はあなたに生ける水を与えたことでしょう。」'),
('JPN', '约翰福音', 43, 4, 11, 'その女は言った。「主よ。あなたは汲む物を持っておられませんし、この井戸は深いのです。その生ける水を、どこから手に入れられるのでしょうか。'),
('JPN', '约翰福音', 43, 4, 12, 'あなたは、私たちの父ヤコブより偉いのでしょうか。ヤコブは私たちにこの井戸を下さって、彼自身も、その子たちも家畜も、この井戸から飲みました。」'),
('JPN', '约翰福音', 43, 4, 13, 'イエスは答えられた。「この水を飲む人はみな、また渇きます。'),
('JPN', '约翰福音', 43, 4, 14, 'しかし、わたしが与える水を飲む人は、いつまでも決して渇くことがありません。わたしが与える水は、その人の内で泉となり、永遠のいのちへの水が湧き出ます。」'),
('JPN', '约翰福音', 43, 4, 15, '彼女はイエスに言った。「主よ。私が渇くことのないように、ここに汲みに来なくてもよいように、その水を私に下さい。」'),
('JPN', '约翰福音', 43, 4, 16, 'イエスは彼女に言われた。「行って、あなたの夫をここに呼んで来なさい。」'),
('JPN', '约翰福音', 43, 4, 17, '彼女は答えた。「私には夫がいません。」イエスは言われた。「自分には夫がいない、と言ったのは、そのとおりです。'),
('JPN', '约翰福音', 43, 4, 18, 'あなたには夫が五人いましたが、今一緒にいるのは夫ではないのですから。あなたは本当のことを言いました。」'),
('JPN', '约翰福音', 43, 4, 19, '彼女は言った。「主よ。あなたは預言者だとお見受けします。'),
('JPN', '约翰福音', 43, 4, 20, '私たちの先祖はこの山で礼拝しましたが、あなたがたは、礼拝すべき場所はエルサレムにあると言っています。」'),
('JPN', '约翰福音', 43, 4, 21, 'イエスは彼女に言われた。「女の人よ、わたしを信じなさい。この山でもなく、エルサレムでもないところで、あなたがたが父を礼拝する時が来ます。'),
('JPN', '约翰福音', 43, 4, 22, '救いはユダヤ人から出るのですから、わたしたちは知って礼拝していますが、あなたがたは知らないで礼拝しています。'),
('JPN', '约翰福音', 43, 4, 23, 'しかし、まことの礼拝者たちが、御霊と真理によって父を礼拝する時が来ます。今がその時です。父はそのような人たちを、ご自分を礼拝する者として求めておられるのです。'),
('JPN', '约翰福音', 43, 4, 24, '神は霊ですから、神を礼拝する人は、御霊と真理によって礼拝しなければなりません。」'),
('JPN', '约翰福音', 43, 4, 25, '女はイエスに言った。「私は、キリストと呼ばれるメシアが来られることを知っています。その方が来られるとき、一切のことを私たちに知らせてくださるでしょう。」'),
('JPN', '约翰福音', 43, 4, 26, 'イエスは言われた。「あなたと話しているこのわたしがそれです。」'),
('JPN', '约翰福音', 43, 4, 27, 'そのとき、弟子たちが戻って来て、イエスが女の人と話しておられるのを見て驚いた。だが、「何をお求めですか」「なぜ彼女と話しておられるのですか」と言う人はだれもいなかった。'),
('JPN', '约翰福音', 43, 4, 28, '彼女は、自分の水がめを置いたまま町へ行き、人々に言った。'),
('JPN', '约翰福音', 43, 4, 29, '「来て、見てください。私がしたことを、すべて私に話した人がいます。もしかすると、この方がキリストなのでしょうか。」'),
('JPN', '约翰福音', 43, 4, 30, 'そこで、人々は町を出て、イエスのもとにやって来た。'),
('JPN', '约翰福音', 43, 4, 31, 'その間、弟子たちはイエスに「先生、食事をしてください」と勧めていた。'),
('JPN', '约翰福音', 43, 4, 32, 'ところが、イエスは彼らに言われた。「わたしには、あなたがたが知らない食べ物があります。」'),
('JPN', '约翰福音', 43, 4, 33, 'そこで、弟子たちは互いに言った。「だれかが食べる物を持って来たのだろうか。」'),
('JPN', '约翰福音', 43, 4, 34, 'イエスは彼らに言われた。「わたしの食べ物とは、わたしを遣わされた方のみこころを行い、そのわざを成し遂げることです。'),
('JPN', '约翰福音', 43, 4, 35, 'あなたがたは、『まだ四か月あって、それから刈り入れだ』と言ってはいませんか。しかし、あなたがたに言います。目を上げて畑を見なさい。色づいて、刈り入れるばかりになっています。'),
('JPN', '约翰福音', 43, 4, 36, 'すでに、刈る者は報酬を受け、永遠のいのちに至る実を集めています。それは蒔く者と刈る者がともに喜ぶためです。'),
('JPN', '约翰福音', 43, 4, 37, 'ですから、『一人が種を蒔き、ほかの者が刈り入れる』ということばはまことです。'),
('JPN', '约翰福音', 43, 4, 38, 'わたしはあなたがたを、自分たちが労苦したのでないものを刈り入れるために遣わしました。ほかの者たちが労苦し、あなたがたがその労苦の実にあずかっているのです。」'),
('JPN', '约翰福音', 43, 4, 39, 'さて、その町の多くのサマリア人が、「あの方は、私がしたことをすべて私に話した」と証言した女のことばによって、イエスを信じた。'),
('JPN', '约翰福音', 43, 4, 40, 'それで、サマリア人たちはイエスのところに来て、自分たちのところに滞在してほしいと願った。そこでイエスは、二日間そこに滞在された。'),
('JPN', '约翰福音', 43, 4, 41, 'そして、さらに多くの人々が、イエスのことばによって信じた。'),
('JPN', '约翰福音', 43, 4, 42, '彼らはその女に言った。「もう私たちは、あなたが話したことによって信じているのではありません。自分で聞いて、この方が本当に世の救い主だと分かったのです。」'),
('JPN', '约翰福音', 43, 4, 43, 'さて、二日後に、イエスはそこを去ってガリラヤに行かれた。'),
('JPN', '约翰福音', 43, 4, 44, 'イエスご自身、「預言者は自分の故郷では尊ばれない」と証言なさっていた。'),
('JPN', '约翰福音', 43, 4, 45, 'それで、ガリラヤに入られたとき、ガリラヤの人たちはイエスを歓迎したが、それは、イエスが祭りの間にエルサレムで行ったことを、すべて見ていたからであった。彼らもその祭りに行っていたのである。'),
('JPN', '约翰福音', 43, 4, 46, 'イエスは再びガリラヤのカナに行かれた。イエスが水をぶどう酒にされた場所である。さてカペナウムに、ある王室の役人がいて、その息子が病気であった。'),
('JPN', '约翰福音', 43, 4, 47, 'この人は、イエスがユダヤからガリラヤに来られたと聞いて、イエスのところに行った。そして、下って来て息子を癒やしてくださるように願った。息子が死にかかっていたのである。'),
('JPN', '约翰福音', 43, 4, 48, 'イエスは彼に言われた。「あなたがたは、しるしと不思議を見ないかぎり、決して信じません。」'),
('JPN', '约翰福音', 43, 4, 49, '王室の役人はイエスに言った。「主よ。どうか子どもが死なないうちに、下って来てください。」'),
('JPN', '约翰福音', 43, 4, 50, 'イエスは彼に言われた。「行きなさい。あなたの息子は治ります。」その人はイエスが語ったことばを信じて、帰って行った。'),
('JPN', '约翰福音', 43, 4, 51, '彼が下って行く途中、しもべたちが彼を迎えに来て、彼の息子が治ったことを告げた。'),
('JPN', '约翰福音', 43, 4, 52, '子どもが良くなった時刻を尋ねると、彼らは「昨日の第七の時に熱がひきました」と言った。'),
('JPN', '约翰福音', 43, 4, 53, '父親は、その時刻が、「あなたの息子は治る」とイエスが言われた時刻だと知り、彼自身も家の者たちもみな信じた。'),
('JPN', '约翰福音', 43, 4, 54, 'イエスはユダヤを去ってガリラヤに来てから、これを第二のしるしとして行われた。'),
('JPN', '约翰福音', 43, 5, 1, 'その後、ユダヤ人の祭りがあって、イエスはエルサレムに上られた。'),
('JPN', '约翰福音', 43, 5, 2, 'エルサレムには、羊の門の近くに、ヘブル語でベテスダと呼ばれる池があり、五つの回廊がついていた。'),
('JPN', '约翰福音', 43, 5, 3, 'その中には、病人、目の見えない人、足の不自由な人、からだに麻痺のある人たちが大勢、横になっていた。（彼らは水が動くのを待っていた。'),
('JPN', '约翰福音', 43, 5, 4, 'それは、主の使いが時々この池に降りて来て水を動かすのだが、水が動かされてから最初に入った者が、どのような病気にかかっている者でも癒やされたからである。）'),
('JPN', '约翰福音', 43, 5, 5, 'そこに、三十八年も病気にかかっている人がいた。'),
('JPN', '约翰福音', 43, 5, 6, 'イエスは彼が横になっているのを見て、すでに長い間そうしていることを知ると、彼に言われた。「良くなりたいか。」'),
('JPN', '约翰福音', 43, 5, 7, '病人は答えた。「主よ。水がかき回されたとき、池の中に入れてくれる人がいません。行きかけると、ほかの人が先に下りて行きます。」'),
('JPN', '约翰福音', 43, 5, 8, 'イエスは彼に言われた。「起きて床を取り上げ、歩きなさい。」'),
('JPN', '约翰福音', 43, 5, 9, 'すると、すぐにその人は治って、床を取り上げて歩き出した。ところが、その日は安息日であった。'),
('JPN', '约翰福音', 43, 5, 10, 'そこでユダヤ人たちは、その癒やされた人に、「今日は安息日だ。床を取り上げることは許されていない」と言った。'),
('JPN', '约翰福音', 43, 5, 11, 'しかし、その人は彼らに答えた。「私を治してくださった方が、『床を取り上げて歩け』と私に言われたのです。」'),
('JPN', '约翰福音', 43, 5, 12, '彼らは尋ねた。「『取り上げて歩け』とあなたに言った人はだれなのか。」'),
('JPN', '约翰福音', 43, 5, 13, 'しかし、癒やされた人は、それがだれであるかを知らなかった。群衆がそこにいる間に、イエスは立ち去られたからである。'),
('JPN', '约翰福音', 43, 5, 14, '後になって、イエスは宮の中で彼を見つけて言われた。「見なさい。あなたは良くなった。もう罪を犯してはなりません。そうでないと、もっと悪いことがあなたに起こるかもしれない。」'),
('JPN', '约翰福音', 43, 5, 15, 'その人は行って、ユダヤ人たちに、自分を治してくれたのはイエスだと伝えた。'),
('JPN', '约翰福音', 43, 5, 16, 'そのためユダヤ人たちは、イエスを迫害し始めた。イエスが、安息日にこのようなことをしておられたからである。'),
('JPN', '约翰福音', 43, 5, 17, 'イエスは彼らに答えられた。「わたしの父は今に至るまで働いておられます。それでわたしも働いているのです。」'),
('JPN', '约翰福音', 43, 5, 18, 'そのためユダヤ人たちは、ますますイエスを殺そうとするようになった。イエスが安息日を破っていただけでなく、神をご自分の父と呼び、ご自分を神と等しくされたからである。'),
('JPN', '约翰福音', 43, 5, 19, 'イエスは彼らに答えて言われた。「まことに、まことに、あなたがたに言います。子は、父がしておられることを見て行う以外には、自分から何も行うことはできません。すべて父がなさることを、子も同様に行うのです。'),
('JPN', '约翰福音', 43, 5, 20, 'それは、父が子を愛し、ご自分がすることをすべて、子にお示しになるからです。また、これよりも大きなわざを子にお示しになるので、あなたがたは驚くことになります。'),
('JPN', '约翰福音', 43, 5, 21, '父が死人をよみがえらせ、いのちを与えられるように、子もまた、与えたいと思う者にいのちを与えます。'),
('JPN', '约翰福音', 43, 5, 22, 'また、父はだれをもさばかず、すべてのさばきを子に委ねられました。'),
('JPN', '约翰福音', 43, 5, 23, 'それは、すべての人が、父を敬うのと同じように、子を敬うようになるためです。子を敬わない者は、子を遣わされた父も敬いません。'),
('JPN', '约翰福音', 43, 5, 24, 'まことに、まことに、あなたがたに言います。わたしのことばを聞いて、わたしを遣わされた方を信じる者は、永遠のいのちを持ち、さばきにあうことがなく、死からいのちに移っています。'),
('JPN', '约翰福音', 43, 5, 25, 'まことに、まことに、あなたがたに言います。死人が神の子の声を聞く時が来ます。今がその時です。それを聞く者は生きます。'),
('JPN', '约翰福音', 43, 5, 26, 'それは、父がご自分のうちにいのちを持っておられるように、子にも、自分のうちにいのちを持つようにしてくださったからです。'),
('JPN', '约翰福音', 43, 5, 27, 'また父は、さばきを行う権威を子に与えてくださいました。子は人の子だからです。'),
('JPN', '约翰福音', 43, 5, 28, 'このことに驚いてはなりません。墓の中にいる者がみな、子の声を聞く時が来るのです。'),
('JPN', '约翰福音', 43, 5, 29, 'そのとき、善を行った者はよみがえっていのちを受けるために、悪を行った者はよみがえってさばきを受けるために出て来ます。'),
('JPN', '约翰福音', 43, 5, 30, 'わたしは、自分からは何も行うことができません。ただ聞いたとおりにさばきます。そして、わたしのさばきは正しいのです。わたしは自分の意志ではなく、わたしを遣わされた方のみこころを求めるからです。'),
('JPN', '约翰福音', 43, 5, 31, 'もしわたし自身について証しをするのがわたしだけなら、わたしの証言は真実ではありません。'),
('JPN', '约翰福音', 43, 5, 32, 'わたしについては、ほかにも証しをする方がおられます。そして、その方がわたしについて証しする証言が真実であることを、わたしは知っています。'),
('JPN', '约翰福音', 43, 5, 33, 'あなたがたはヨハネのところに人を遣わしました。そして彼は真理について証ししました。'),
('JPN', '约翰福音', 43, 5, 34, 'わたしは人からの証しを受けませんが、あなたがたが救われるために、これらのことを言うのです。'),
('JPN', '约翰福音', 43, 5, 35, 'ヨハネは燃えて輝くともしびであり、あなたがたはしばらくの間、その光の中で大いに喜ぼうとしました。'),
('JPN', '约翰福音', 43, 5, 36, 'しかし、わたしにはヨハネの証しよりもすぐれた証しがあります。わたしが成し遂げるようにと父が与えてくださったわざが、すなわち、わたしが行っているわざそのものが、わたしについて、父がわたしを遣わされたことを証ししているのです。'),
('JPN', '约翰福音', 43, 5, 37, 'また、わたしを遣わされた父ご自身が、わたしについて証しをしてくださいました。あなたがたは、まだ一度もその御声を聞いたことも、御姿を見たこともありません。'),
('JPN', '约翰福音', 43, 5, 38, 'また、そのみことばを自分たちのうちにとどめてもいません。父が遣わされた者を信じないからです。'),
('JPN', '约翰福音', 43, 5, 39, 'あなたがたは、聖書の中に永遠のいのちがあると思って、聖書を調べています。その聖書は、わたしについて証ししているものです。'),
('JPN', '约翰福音', 43, 5, 40, 'それなのに、あなたがたは、いのちを得るためにわたしのもとに来ようとはしません。'),
('JPN', '约翰福音', 43, 5, 41, 'わたしは人からの栄誉は受けません。'),
('JPN', '约翰福音', 43, 5, 42, 'しかし、わたしは知っています。あなたがたのうちに神への愛がないことを。'),
('JPN', '约翰福音', 43, 5, 43, 'わたしは、わたしの父の名によって来たのに、あなたがたはわたしを受け入れません。もしほかの人がその人自身の名で来れば、あなたがたはその人を受け入れます。'),
('JPN', '约翰福音', 43, 5, 44, '互いの間では栄誉を受けても、唯一の神からの栄誉を求めないあなたがたが、どうして信じることができるでしょうか。'),
('JPN', '约翰福音', 43, 5, 45, 'わたしが、父の前にあなたがたを訴えると思ってはなりません。あなたがたを訴えるのは、あなたがたが望みを置いているモーセです。'),
('JPN', '约翰福音', 43, 5, 46, 'もしも、あなたがたがモーセを信じているのなら、わたしを信じたはずです。モーセが書いたのはわたしのことなのですから。'),
('JPN', '约翰福音', 43, 5, 47, 'しかし、モーセが書いたものをあなたがたが信じていないのなら、どうしてわたしのことばを信じるでしょうか。」'),
('JPN', '约翰福音', 43, 6, 1, 'その後、イエスはガリラヤの湖、すなわち、ティベリアの湖の向こう岸に行かれた。'),
('JPN', '约翰福音', 43, 6, 2, '大勢の群衆がイエスについて行った。イエスが病人たちになさっていたしるしを見たからであった。'),
('JPN', '约翰福音', 43, 6, 3, 'イエスは山に登り、弟子たちとともにそこに座られた。'),
('JPN', '约翰福音', 43, 6, 4, 'ユダヤ人の祭りである過越が近づいていた。'),
('JPN', '约翰福音', 43, 6, 5, 'イエスは目を上げて、大勢の群衆がご自分の方に来るのを見て、ピリポに言われた。「どこからパンを買って来て、この人たちに食べさせようか。」'),
('JPN', '约翰福音', 43, 6, 6, 'イエスがこう言われたのは、ピリポを試すためであり、ご自分が何をしようとしているのかを、知っておられた。'),
('JPN', '约翰福音', 43, 6, 7, 'ピリポはイエスに答えた。「一人ひとりが少しずつ取るにしても、二百デナリのパンでは足りません。」'),
('JPN', '约翰福音', 43, 6, 8, '弟子の一人、シモン・ペテロの兄弟アンデレがイエスに言った。'),
('JPN', '约翰福音', 43, 6, 9, '「ここに、大麦のパン五つと、魚二匹を持っている少年がいます。でも、こんなに大勢の人々では、それが何になるでしょう。」'),
('JPN', '约翰福音', 43, 6, 10, 'イエスは言われた。「人々を座らせなさい。」その場所には草がたくさんあったので、男たちは座った。その数はおよそ五千人であった。'),
('JPN', '约翰福音', 43, 6, 11, 'そうして、イエスはパンを取り、感謝の祈りをささげてから、座っている人たちに分け与えられた。魚も同じようにして、彼らが望むだけ与えられた。'),
('JPN', '约翰福音', 43, 6, 12, '彼らが十分食べたとき、イエスは弟子たちに言われた。「一つも無駄にならないように、余ったパン切れを集めなさい。」'),
('JPN', '约翰福音', 43, 6, 13, 'そこで彼らが集めると、大麦のパン五つを食べて余ったパン切れで、十二のかごがいっぱいになった。'),
('JPN', '约翰福音', 43, 6, 14, '人々はイエスがなさったしるしを見て、「まことにこの方こそ、世に来られるはずの預言者だ」と言った。'),
('JPN', '约翰福音', 43, 6, 15, 'イエスは、人々がやって来て、自分を王にするために連れて行こうとしているのを知り、再びただ一人で山に退かれた。'),
('JPN', '约翰福音', 43, 6, 16, '夕方になって、弟子たちは湖畔に下りて行った。'),
('JPN', '约翰福音', 43, 6, 17, 'そして、舟に乗り込み、カペナウムの方へと湖を渡って行った。すでにあたりは暗く、イエスはまだ彼らのところに来ておられなかった。'),
('JPN', '约翰福音', 43, 6, 18, '強風が吹いて湖は荒れ始めた。'),
('JPN', '约翰福音', 43, 6, 19, 'そして、二十五ないし三十スタディオンほど漕ぎ出したころ、弟子たちは、イエスが湖の上を歩いて舟に近づいて来られるのを見て恐れた。'),
('JPN', '约翰福音', 43, 6, 20, 'しかし、イエスは彼らに言われた。「わたしだ。恐れることはない。」'),
('JPN', '约翰福音', 43, 6, 21, 'それで彼らは、イエスを喜んで舟に迎えた。すると、舟はすぐに目的地に着いた。'),
('JPN', '约翰福音', 43, 6, 22, 'その翌日、湖の向こう岸にとどまっていた群衆は、前にはそこに小舟が一艘しかなく、その舟にイエスは弟子たちと一緒には乗らずに、弟子たちが自分たちだけで立ち去ったことに気づいた。'),
('JPN', '约翰福音', 43, 6, 23, 'すると、主が感謝をささげて人々がパンを食べた場所の近くに、ティベリアから小舟が数艘やって来た。'),
('JPN', '约翰福音', 43, 6, 24, '群衆は、イエスも弟子たちもそこにいないことを知ると、自分たちもそれらの小舟に乗り込んで、イエスを捜しにカペナウムに向かった。'),
('JPN', '约翰福音', 43, 6, 25, 'そして、湖の反対側でイエスを見つけると、彼らはイエスに言った。「先生、いつここにおいでになったのですか。」'),
('JPN', '约翰福音', 43, 6, 26, 'イエスは彼らに答えられた。「まことに、まことに、あなたがたに言います。あなたがたがわたしを捜しているのは、しるしを見たからではなく、パンを食べて満腹したからです。'),
('JPN', '约翰福音', 43, 6, 27, 'なくなってしまう食べ物のためではなく、いつまでもなくならない、永遠のいのちに至る食べ物のために働きなさい。それは、人の子が与える食べ物です。この人の子に、神である父が証印を押されたのです。」'),
('JPN', '约翰福音', 43, 6, 28, 'すると、彼らはイエスに言った。「神のわざを行うためには、何をすべきでしょうか。」'),
('JPN', '约翰福音', 43, 6, 29, 'イエスは答えられた。「神が遣わした者をあなたがたが信じること、それが神のわざです。」'),
('JPN', '约翰福音', 43, 6, 30, 'それで、彼らはイエスに言った。「それでは、私たちが見てあなたを信じられるように、どんなしるしを行われるのですか。何をしてくださいますか。'),
('JPN', '约翰福音', 43, 6, 31, '私たちの先祖は、荒野でマナを食べました。『神は彼らに、食べ物として天からのパンを与えられた』と書いてあるとおりです。」'),
('JPN', '约翰福音', 43, 6, 32, 'それで、イエスは彼らに言われた。「まことに、まことに、あなたがたに言います。モーセがあなたがたに天からのパンを与えたのではありません。わたしの父が、あなたがたに天からのまことのパンを与えてくださるのです。'),
('JPN', '约翰福音', 43, 6, 33, '神のパンは、天から下って来て、世にいのちを与えるものなのです。」'),
('JPN', '约翰福音', 43, 6, 34, 'そこで、彼らはイエスに言った。「主よ、そのパンをいつも私たちにお与えください。」'),
('JPN', '约翰福音', 43, 6, 35, 'イエスは言われた。「わたしがいのちのパンです。わたしのもとに来る者は決して飢えることがなく、わたしを信じる者はどんなときにも、決して渇くことがありません。'),
('JPN', '约翰福音', 43, 6, 36, 'しかし、あなたがたに言ったように、あなたがたはわたしを見たのに信じません。'),
('JPN', '约翰福音', 43, 6, 37, '父がわたしに与えてくださる者はみな、わたしのもとに来ます。そして、わたしのもとに来る者を、わたしは決して外に追い出したりはしません。'),
('JPN', '约翰福音', 43, 6, 38, 'わたしが天から下って来たのは、自分の思いを行うためではなく、わたしを遣わされた方のみこころを行うためです。'),
('JPN', '约翰福音', 43, 6, 39, 'わたしを遣わされた方のみこころは、わたしに与えてくださったすべての者を、わたしが一人も失うことなく、終わりの日によみがえらせることです。'),
('JPN', '约翰福音', 43, 6, 40, 'わたしの父のみこころは、子を見て信じる者がみな永遠のいのちを持ち、わたしがその人を終わりの日によみがえらせることなのです。」'),
('JPN', '约翰福音', 43, 6, 41, 'ユダヤ人たちは、イエスが「わたしは天から下って来たパンです」と言われたので、イエスについて小声で文句を言い始めた。'),
('JPN', '约翰福音', 43, 6, 42, '彼らは言った。「あれは、ヨセフの子イエスではないか。私たちは父親と母親を知っている。どうして今、『わたしは天から下って来た』と言ったりするのか。」'),
('JPN', '约翰福音', 43, 6, 43, 'イエスは彼らに答えられた。「自分たちの間で小声で文句を言うのはやめなさい。'),
('JPN', '约翰福音', 43, 6, 44, 'わたしを遣わされた父が引き寄せてくださらなければ、だれもわたしのもとに来ることはできません。わたしはその人を終わりの日によみがえらせます。'),
('JPN', '约翰福音', 43, 6, 45, '預言者たちの書に、『彼らはみな、神によって教えられる』と書かれています。父から聞いて学んだ者はみな、わたしのもとに来ます。'),
('JPN', '约翰福音', 43, 6, 46, '父を見た者はだれもいません。ただ神から出た者だけが、父を見たのです。'),
('JPN', '约翰福音', 43, 6, 47, 'まことに、まことに、あなたがたに言います。信じる者は永遠のいのちを持っています。'),
('JPN', '约翰福音', 43, 6, 48, 'わたしはいのちのパンです。'),
('JPN', '约翰福音', 43, 6, 49, 'あなたがたの先祖たちは荒野でマナを食べたが、死にました。'),
('JPN', '约翰福音', 43, 6, 50, 'しかし、これは天から下って来たパンで、それを食べると死ぬことがありません。'),
('JPN', '约翰福音', 43, 6, 51, 'わたしは、天から下って来た生けるパンです。だれでもこのパンを食べるなら、永遠に生きます。そして、わたしが与えるパンは、世のいのちのための、わたしの肉です。」'),
('JPN', '约翰福音', 43, 6, 52, 'それで、ユダヤ人たちは、「この人は、どうやって自分の肉を、私たちに与えて食べさせることができるのか」と互いに激しい議論を始めた。'),
('JPN', '约翰福音', 43, 6, 53, 'イエスは彼らに言われた。「まことに、まことに、あなたがたに言います。人の子の肉を食べ、その血を飲まなければ、あなたがたのうちに、いのちはありません。'),
('JPN', '约翰福音', 43, 6, 54, 'わたしの肉を食べ、わたしの血を飲む者は、永遠のいのちを持っています。わたしは終わりの日にその人をよみがえらせます。'),
('JPN', '约翰福音', 43, 6, 55, 'わたしの肉はまことの食べ物、わたしの血はまことの飲み物なのです。'),
('JPN', '约翰福音', 43, 6, 56, 'わたしの肉を食べ、わたしの血を飲む者は、わたしのうちにとどまり、わたしもその人のうちにとどまります。'),
('JPN', '约翰福音', 43, 6, 57, '生ける父がわたしを遣わし、わたしが父によって生きているように、わたしを食べる者も、わたしによって生きるのです。'),
('JPN', '约翰福音', 43, 6, 58, 'これは天から下って来たパンです。先祖が食べて、なお死んだようなものではありません。このパンを食べる者は永遠に生きます。」'),
('JPN', '约翰福音', 43, 6, 59, 'これが、イエスがカペナウムで教えられたとき、会堂で話されたことである。'),
('JPN', '约翰福音', 43, 6, 60, 'これを聞いて、弟子たちのうちの多くの者が言った。「これはひどい話だ。だれが聞いていられるだろうか。」'),
('JPN', '约翰福音', 43, 6, 61, 'しかしイエスは、弟子たちがこの話について、小声で文句を言っているのを知って、彼らに言われた。「わたしの話があなたがたをつまずかせるのか。'),
('JPN', '约翰福音', 43, 6, 62, 'それなら、人の子がかつていたところに上るのを見たら、どうなるのか。'),
('JPN', '约翰福音', 43, 6, 63, 'いのちを与えるのは御霊です。肉は何の益ももたらしません。わたしがあなたがたに話してきたことばは、霊であり、またいのちです。'),
('JPN', '约翰福音', 43, 6, 64, 'けれども、あなたがたの中に信じない者たちがいます。」信じない者たちがだれか、ご自分を裏切る者がだれか、イエスは初めから知っておられたのである。'),
('JPN', '约翰福音', 43, 6, 65, 'そしてイエスは言われた。「ですから、わたしはあなたがたに、『父が与えてくださらないかぎり、だれもわたしのもとに来ることはできない』と言ったのです。」'),
('JPN', '约翰福音', 43, 6, 66, 'こういうわけで、弟子たちのうちの多くの者が離れ去り、もはやイエスとともに歩もうとはしなくなった。'),
('JPN', '约翰福音', 43, 6, 67, 'それで、イエスは十二人に、「あなたがたも離れて行きたいのですか」と言われた。'),
('JPN', '约翰福音', 43, 6, 68, 'すると、シモン・ペテロが答えた。「主よ、私たちはだれのところに行けるでしょうか。あなたは、永遠のいのちのことばを持っておられます。'),
('JPN', '约翰福音', 43, 6, 69, '私たちは、あなたが神の聖者であると信じ、また知っています。」'),
('JPN', '约翰福音', 43, 6, 70, 'イエスは彼らに答えられた。「わたしがあなたがた十二人を選んだのではありませんか。しかし、あなたがたのうちの一人は悪魔です。」'),
('JPN', '约翰福音', 43, 6, 71, 'イエスはイスカリオテのシモンの子ユダのことを言われたのであった。このユダは十二人の一人であったが、イエスを裏切ろうとしていた。'),
('JPN', '约翰福音', 43, 7, 1, 'その後、イエスはガリラヤを巡り続けられた。ユダヤ人たちがイエスを殺そうとしていたので、ユダヤを巡ろうとはされなかったからである。'),
('JPN', '约翰福音', 43, 7, 2, '時に、仮庵の祭りというユダヤ人の祭りが近づいていた。'),
('JPN', '约翰福音', 43, 7, 3, 'そこで、イエスの兄弟たちがイエスに言った。「ここを去ってユダヤに行きなさい。そうすれば、弟子たちもあなたがしている働きを見ることができます。'),
('JPN', '约翰福音', 43, 7, 4, '自分で公の場に出ることを願いながら、隠れて事を行う人はいません。このようなことを行うのなら、自分を世に示しなさい。」'),
('JPN', '约翰福音', 43, 7, 5, '兄弟たちもイエスを信じていなかったのである。'),
('JPN', '约翰福音', 43, 7, 6, 'そこで、イエスは彼らに言われた。「わたしの時はまだ来ていません。しかし、あなたがたの時はいつでも用意ができています。'),
('JPN', '约翰福音', 43, 7, 7, '世はあなたがたを憎むことができないが、わたしのことは憎んでいます。わたしが世について、その行いが悪いことを証ししているからです。'),
('JPN', '约翰福音', 43, 7, 8, 'あなたがたは祭りに上って行きなさい。わたしはこの祭りに上って行きません。わたしの時はまだ満ちていないのです。」'),
('JPN', '约翰福音', 43, 7, 9, 'こう言って、イエスはガリラヤにとどまられた。'),
('JPN', '约翰福音', 43, 7, 10, 'しかし、兄弟たちが祭りに上って行った後で、イエスご自身も、表立ってではなく、いわば内密に上って行かれた。'),
('JPN', '约翰福音', 43, 7, 11, 'ユダヤ人たちは祭りの場で、「あの人はどこにいるのか」と言って、イエスを捜していた。'),
('JPN', '约翰福音', 43, 7, 12, '群衆はイエスについて、小声でいろいろと話をしていた。ある人たちは「良い人だ」と言い、別の人たちは「違う。群衆を惑わしているのだ」と言っていた。'),
('JPN', '约翰福音', 43, 7, 13, 'しかし、ユダヤ人たちを恐れたため、イエスについて公然と語る者はだれもいなかった。'),
('JPN', '约翰福音', 43, 7, 14, '祭りもすでに半ばになったころ、イエスは宮に上って教え始められた。'),
('JPN', '约翰福音', 43, 7, 15, 'ユダヤ人たちは驚いて言った。「この人は学んだこともないのに、どうして学問があるのか。」'),
('JPN', '约翰福音', 43, 7, 16, 'そこで、イエスは彼らに答えられた。「わたしの教えは、わたしのものではなく、わたしを遣わされた方のものです。'),
('JPN', '约翰福音', 43, 7, 17, 'だれでも神のみこころを行おうとするなら、その人には、この教えが神から出たものなのか、わたしが自分から語っているのかが分かります。'),
('JPN', '约翰福音', 43, 7, 18, '自分から語る人は自分の栄誉を求めます。しかし、自分を遣わされた方の栄誉を求める人は真実で、その人には不正がありません。'),
('JPN', '约翰福音', 43, 7, 19, 'モーセはあなたがたに律法を与えたではありませんか。それなのに、あなたがたはだれも律法を守っていません。あなたがたは、なぜわたしを殺そうとするのですか。」'),
('JPN', '约翰福音', 43, 7, 20, '群衆は答えた。「あなたは悪霊につかれている。だれがあなたを殺そうとしているのか。」'),
('JPN', '约翰福音', 43, 7, 21, 'イエスは彼らに答えられた。「わたしが一つのわざを行い、それで、あなたがたはみな驚いています。'),
('JPN', '约翰福音', 43, 7, 22, 'モーセはあなたがたに割礼を与えました。それはモーセからではなく、父祖たちから始まったことです。そして、あなたがたは安息日にも人に割礼を施しています。'),
('JPN', '约翰福音', 43, 7, 23, 'モーセの律法を破らないようにと、人は安息日にも割礼を受けるのに、わたしが安息日に人の全身を健やかにしたということで、あなたがたはわたしに腹を立てるのですか。'),
('JPN', '约翰福音', 43, 7, 24, 'うわべで人をさばかないで、正しいさばきを行いなさい。」'),
('JPN', '约翰福音', 43, 7, 25, 'さて、エルサレムのある人たちは、こう言い始めた。「この人は、彼らが殺そうとしている人ではないか。'),
('JPN', '约翰福音', 43, 7, 26, '見なさい。この人は公然と語っているのに、彼らはこの人に何も言わない。もしかしたら議員たちは、この人がキリストであると、本当に認めたのではないか。'),
('JPN', '约翰福音', 43, 7, 27, 'しかし、私たちはこの人がどこから来たのか知っている。キリストが来られるときには、どこから来るのかだれも知らないはずだ。」'),
('JPN', '约翰福音', 43, 7, 28, 'イエスは宮で教えていたとき、大きな声で言われた。「あなたがたはわたしを知っており、わたしがどこから来たかも知っています。しかし、わたしは自分で来たのではありません。わたしを遣わされた方は真実です。その方を、あなたがたは知りません。'),
('JPN', '约翰福音', 43, 7, 29, 'わたしはその方を知っています。なぜなら、わたしはその方から出たのであり、その方がわたしを遣わされたからです。」'),
('JPN', '约翰福音', 43, 7, 30, 'そこで人々はイエスを捕らえようとしたが、だれもイエスに手をかける者はいなかった。イエスの時がまだ来ていなかったからである。'),
('JPN', '约翰福音', 43, 7, 31, '群衆のうちにはイエスを信じる人が多くいて、「キリストが来られるとき、この方がなさったよりも多くのしるしを行うだろうか」と言い合った。'),
('JPN', '约翰福音', 43, 7, 32, 'パリサイ人たちは、群衆がイエスについて、このようなことを小声で話しているのを耳にした。それで祭司長たちとパリサイ人たちは、イエスを捕らえようとして下役たちを遣わした。'),
('JPN', '约翰福音', 43, 7, 33, 'そこで、イエスは言われた。「もう少しの間、わたしはあなたがたとともにいて、それから、わたしを遣わされた方のもとに行きます。'),
('JPN', '约翰福音', 43, 7, 34, 'あなたがたはわたしを捜しますが、見つけることはありません。わたしがいるところに来ることはできません。」'),
('JPN', '约翰福音', 43, 7, 35, 'すると、ユダヤ人たちは互いに言った。「私たちには見つからないとは、あの人はどこへ行くつもりなのか。まさか、ギリシア人の中に離散している人々のところに行って、ギリシア人を教えるつもりではあるまい。'),
('JPN', '约翰福音', 43, 7, 36, '『あなたがたはわたしを捜しますが、見つけることはありません。わたしがいるところに来ることはできません』とあの人が言ったこのことばは、どういう意味だろうか。」'),
('JPN', '约翰福音', 43, 7, 37, 'さて、祭りの終わりの大いなる日に、イエスは立ち上がり、大きな声で言われた。「だれでも渇いているなら、わたしのもとに来て飲みなさい。'),
('JPN', '约翰福音', 43, 7, 38, 'わたしを信じる者は、聖書が言っているとおり、その人の心の奥底から、生ける水の川が流れ出るようになります。」'),
('JPN', '约翰福音', 43, 7, 39, 'イエスは、ご自分を信じる者が受けることになる御霊について、こう言われたのである。イエスはまだ栄光を受けておられなかったので、御霊はまだ下っていなかったのである。'),
('JPN', '约翰福音', 43, 7, 40, 'このことばを聞いて、群衆の中には、「この方は、確かにあの預言者だ」と言う人たちがいた。'),
('JPN', '约翰福音', 43, 7, 41, '別の人たちは「この方はキリストだ」と言った。しかし、このように言う人たちもいた。「キリストはガリラヤから出るだろうか。'),
('JPN', '约翰福音', 43, 7, 42, 'キリストはダビデの子孫から、ダビデがいた村、ベツレヘムから出ると、聖書は言っているではないか。」'),
('JPN', '约翰福音', 43, 7, 43, 'こうして、イエスのことで群衆の間に分裂が生じた。'),
('JPN', '约翰福音', 43, 7, 44, '彼らの中にはイエスを捕らえたいと思う人たちもいたが、だれもイエスに手をかける者はいなかった。'),
('JPN', '约翰福音', 43, 7, 45, 'さて、祭司長たちとパリサイ人たちは、下役たちが自分たちのところに戻って来たとき、彼らに言った。「なぜあの人を連れて来なかったのか。」'),
('JPN', '约翰福音', 43, 7, 46, '下役たちは答えた。「これまで、あの人のように話した人はいませんでした。」'),
('JPN', '约翰福音', 43, 7, 47, 'そこで、パリサイ人たちは答えた。「おまえたちまで惑わされているのか。'),
('JPN', '约翰福音', 43, 7, 48, '議員やパリサイ人の中で、だれかイエスを信じた者がいたか。'),
('JPN', '约翰福音', 43, 7, 49, 'それにしても、律法を知らないこの群衆はのろわれている。」'),
('JPN', '约翰福音', 43, 7, 50, '彼らのうちの一人で、イエスのもとに来たことのあるニコデモが彼らに言った。'),
('JPN', '约翰福音', 43, 7, 51, '「私たちの律法は、まず本人から話を聞き、その人が何をしているのかを知ったうえでなければ、さばくことをしないのではないか。」'),
('JPN', '约翰福音', 43, 7, 52, '彼らはニコデモに答えて言った。「あなたもガリラヤの出なのか。よく調べなさい。ガリラヤから預言者は起こらないことが分かるだろう。」'),
('JPN', '约翰福音', 43, 7, 53, '〔人々はそれぞれ家に帰って行った。'),
('JPN', '约翰福音', 43, 8, 1, 'イエスはオリーブ山に行かれた。'),
('JPN', '约翰福音', 43, 8, 2, 'そして朝早く、イエスは再び宮に入られた。人々はみな、みもとに寄って来た。イエスは腰を下ろして、彼らに教え始められた。'),
('JPN', '约翰福音', 43, 8, 3, 'すると、律法学者とパリサイ人が、姦淫の場で捕らえられた女を連れて来て、真ん中に立たせ、'),
('JPN', '约翰福音', 43, 8, 4, 'イエスに言った。「先生、この女は姦淫の現場で捕らえられました。'),
('JPN', '约翰福音', 43, 8, 5, 'モーセは律法の中で、こういう女を石打ちにするよう私たちに命じています。あなたは何と言われますか。」'),
('JPN', '约翰福音', 43, 8, 6, '彼らはイエスを告発する理由を得ようと、イエスを試みてこう言ったのであった。だが、イエスは身をかがめて、指で地面に何か書いておられた。'),
('JPN', '约翰福音', 43, 8, 7, 'しかし、彼らが問い続けるので、イエスは身を起こして言われた。「あなたがたの中で罪のない者が、まずこの人に石を投げなさい。」'),
('JPN', '约翰福音', 43, 8, 8, 'そしてイエスは、再び身をかがめて、地面に何かを書き続けられた。'),
('JPN', '约翰福音', 43, 8, 9, '彼らはそれを聞くと、年長者たちから始まり、一人、また一人と去って行き、真ん中にいた女とともに、イエスだけが残された。'),
('JPN', '约翰福音', 43, 8, 10, 'イエスは身を起こして、彼女に言われた。「女の人よ、彼らはどこにいますか。だれもあなたにさばきを下さなかったのですか。」'),
('JPN', '约翰福音', 43, 8, 11, '彼女は言った。「はい、主よ。だれも。」イエスは言われた。「わたしもあなたにさばきを下さない。行きなさい。これからは、決して罪を犯してはなりません。」〕'),
('JPN', '约翰福音', 43, 8, 12, 'イエスは再び人々に語られた。「わたしは世の光です。わたしに従う者は、決して闇の中を歩むことがなく、いのちの光を持ちます。」'),
('JPN', '约翰福音', 43, 8, 13, 'すると、パリサイ人はイエスに言った。「あなたは自分で自分のことを証ししています。だから、あなたの証しは真実ではありません。」'),
('JPN', '约翰福音', 43, 8, 14, 'イエスは彼らに答えられた。「たとえ、わたしが自分自身について証しをしても、わたしの証しは真実です。わたしは自分がどこから来たのか、また、どこへ行くのかを知っているのですから。しかしあなたがたは、わたしがどこから来て、どこへ行くのかを知りません。'),
('JPN', '约翰福音', 43, 8, 15, 'あなたがたは肉によってさばきますが、わたしはだれもさばきません。'),
('JPN', '约翰福音', 43, 8, 16, 'たとえ、わたしがさばくとしても、わたしのさばきは真実です。わたしは一人ではなく、わたしとわたしを遣わした父がさばくからです。'),
('JPN', '约翰福音', 43, 8, 17, 'あなたがたの律法にも、二人の人による証しは真実であると書かれています。'),
('JPN', '约翰福音', 43, 8, 18, 'わたしは自分について証しする者です。またわたしを遣わした父が、わたしについて証ししておられます。」'),
('JPN', '约翰福音', 43, 8, 19, 'すると、彼らはイエスに言った。「あなたの父はどこにいるのですか。」イエスは答えられた。「あなたがたは、わたしも、わたしの父も知りません。もし、わたしを知っていたら、わたしの父をも知っていたでしょう。」'),
('JPN', '约翰福音', 43, 8, 20, 'イエスは、宮で教えていたとき、献金箱の近くでこのことを話された。しかし、だれもイエスを捕らえなかった。イエスの時がまだ来ていなかったからである。'),
('JPN', '约翰福音', 43, 8, 21, 'イエスは再び彼らに言われた。「わたしは去って行きます。あなたがたはわたしを捜しますが、自分の罪の中で死にます。わたしが行くところに、あなたがたは来ることができません。」'),
('JPN', '约翰福音', 43, 8, 22, 'そこで、ユダヤ人たちは言った。「『わたしが行くところに、あなたがたは来ることができません』と言うが、まさか自殺するつもりではないだろう。」'),
('JPN', '约翰福音', 43, 8, 23, 'イエスは彼らに言われた。「あなたがたは下から来た者ですが、わたしは上から来た者です。あなたがたはこの世の者ですが、わたしはこの世の者ではありません。'),
('JPN', '约翰福音', 43, 8, 24, 'それで、あなたがたは自分の罪の中で死ぬと、あなたがたに言ったのです。わたしが『わたしはある』であることを信じなければ、あなたがたは、自分の罪の中で死ぬことになるからです。」'),
('JPN', '约翰福音', 43, 8, 25, 'そこで、彼らはイエスに言った。「あなたはだれなのですか。」イエスは言われた。「それこそ、初めからあなたがたに話していることではありませんか。'),
('JPN', '约翰福音', 43, 8, 26, 'わたしには、あなたがたについて言うべきこと、さばくべきことがたくさんあります。しかし、わたしを遣わされた方は真実であって、わたしはその方から聞いたことを、そのまま世に対して語っているのです。」'),
('JPN', '约翰福音', 43, 8, 27, '彼らは、イエスが父について語っておられることを理解していなかった。'),
('JPN', '约翰福音', 43, 8, 28, 'そこで、イエスは言われた。「あなたがたが人の子を上げたとき、そのとき、わたしが『わたしはある』であること、また、わたしが自分からは何もせず、父がわたしに教えられたとおりに、これらのことを話していたことを、あなたがたは知るようになります。'),
('JPN', '约翰福音', 43, 8, 29, 'わたしを遣わした方は、わたしとともにおられます。わたしを一人残されることはありません。わたしは、その方が喜ばれることをいつも行うからです。」'),
('JPN', '约翰福音', 43, 8, 30, 'イエスがこれらのことを話されると、多くの者がイエスを信じた。'),
('JPN', '约翰福音', 43, 8, 31, 'イエスは、ご自分を信じたユダヤ人たちに言われた。「あなたがたは、わたしのことばにとどまるなら、本当にわたしの弟子です。'),
('JPN', '约翰福音', 43, 8, 32, 'あなたがたは真理を知り、真理はあなたがたを自由にします。」'),
('JPN', '约翰福音', 43, 8, 33, '彼らはイエスに答えた。「私たちはアブラハムの子孫であって、今までだれの奴隷になったこともありません。どうして、『あなたがたは自由になる』と言われるのですか。」'),
('JPN', '约翰福音', 43, 8, 34, 'イエスは彼らに答えられた。「まことに、まことに、あなたがたに言います。罪を行っている者はみな、罪の奴隷です。'),
('JPN', '约翰福音', 43, 8, 35, '奴隷はいつまでも家にいるわけではありませんが、息子はいつまでもいます。'),
('JPN', '约翰福音', 43, 8, 36, 'ですから、子があなたがたを自由にするなら、あなたがたは本当に自由になるのです。'),
('JPN', '约翰福音', 43, 8, 37, 'わたしは、あなたがたがアブラハムの子孫であることを知っています。しかし、あなたがたはわたしを殺そうとしています。わたしのことばが、あなたがたのうちに入っていないからです。'),
('JPN', '约翰福音', 43, 8, 38, 'わたしは父のもとで見たことを話しています。あなたがたは、あなたがたの父から聞いたことを行っています。」'),
('JPN', '约翰福音', 43, 8, 39, '彼らはイエスに答えて言った。「私たちの父はアブラハムです。」イエスは彼らに言われた。「あなたがたがアブラハムの子どもなら、アブラハムのわざを行うはずです。'),
('JPN', '约翰福音', 43, 8, 40, 'ところが今あなたがたは、神から聞いた真理をあなたがたに語った者であるわたしを、殺そうとしています。アブラハムはそのようなことをしませんでした。'),
('JPN', '约翰福音', 43, 8, 41, 'あなたがたは、あなたがたの父がすることを行っているのです。」すると、彼らは言った。「私たちは淫らな行いによって生まれた者ではありません。私たちにはひとりの父、神がいます。」'),
('JPN', '约翰福音', 43, 8, 42, 'イエスは言われた。「神があなたがたの父であるなら、あなたがたはわたしを愛するはずです。わたしは神のもとから来てここにいるからです。わたしは自分で来たのではなく、神がわたしを遣わされたのです。'),
('JPN', '约翰福音', 43, 8, 43, 'あなたがたは、なぜわたしの話が分からないのですか。それは、わたしのことばに聞き従うことができないからです。'),
('JPN', '约翰福音', 43, 8, 44, 'あなたがたは、悪魔である父から出た者であって、あなたがたの父の欲望を成し遂げたいと思っています。悪魔は初めから人殺しで、真理に立っていません。彼のうちには真理がないからです。悪魔は、偽りを言うとき、自分の本性から話します。なぜなら彼は偽り者、また偽りの父だからです。'),
('JPN', '约翰福音', 43, 8, 45, 'しかし、このわたしは真理を話しているので、あなたがたはわたしを信じません。'),
('JPN', '约翰福音', 43, 8, 46, 'あなたがたのうちのだれが、わたしに罪があると責めることができますか。わたしが真理を話しているなら、なぜわたしを信じないのですか。'),
('JPN', '约翰福音', 43, 8, 47, '神から出た者は、神のことばに聞き従います。ですから、あなたがたが聞き従わないのは、あなたがたが神から出た者でないからです。」'),
('JPN', '约翰福音', 43, 8, 48, 'ユダヤ人たちはイエスに答えて言った。「あなたはサマリア人で悪霊につかれている、と私たちが言うのも当然ではないか。」'),
('JPN', '约翰福音', 43, 8, 49, 'イエスは答えられた。「わたしは悪霊につかれてはいません。むしろ、わたしの父を敬っているのに、あなたがたはわたしを卑しめています。'),
('JPN', '约翰福音', 43, 8, 50, 'わたしは自分の栄光を求めません。それを求め、さばきをなさる方がおられます。'),
('JPN', '约翰福音', 43, 8, 51, 'まことに、まことに、あなたがたに言います。だれでもわたしのことばを守るなら、その人はいつまでも決して死を見ることがありません。」'),
('JPN', '约翰福音', 43, 8, 52, 'ユダヤ人たちはイエスに言った。「あなたが悪霊につかれていることが、今分かった。アブラハムは死に、預言者たちも死んだ。それなのにあなたは、『だれでもわたしのことばを守るなら、その人はいつまでも決して死を味わうことがない』と言う。'),
('JPN', '约翰福音', 43, 8, 53, 'あなたは、私たちの父アブラハムよりも偉大なのか。アブラハムは死んだ。預言者たちも死んだ。あなたは、自分を何者だと言うのか。」'),
('JPN', '约翰福音', 43, 8, 54, 'イエスは答えられた。「わたしがもし自分自身に栄光を帰するなら、わたしの栄光は空しい。わたしに栄光を与える方は、わたしの父です。この方を、あなたがたは『私たちの神である』と言っています。'),
('JPN', '约翰福音', 43, 8, 55, 'あなたがたはこの方を知らないが、わたしは知っています。もしわたしがこの方を知らないと言うなら、わたしもあなたがたと同様に偽り者となるでしょう。しかし、わたしはこの方を知っていて、そのみことばを守っています。'),
('JPN', '约翰福音', 43, 8, 56, 'あなたがたの父アブラハムは、わたしの日を見るようになることを、大いに喜んでいました。そして、それを見て、喜んだのです。」'),
('JPN', '约翰福音', 43, 8, 57, 'そこで、ユダヤ人たちはイエスに向かって言った。「あなたはまだ五十歳になっていないのに、アブラハムを見たのか。」'),
('JPN', '约翰福音', 43, 8, 58, 'イエスは彼らに言われた。「まことに、まことに、あなたがたに言います。アブラハムが生まれる前から、『わたしはある』なのです。」'),
('JPN', '约翰福音', 43, 8, 59, 'すると彼らは、イエスに投げつけようと石を取った。しかし、イエスは身を隠して、宮から出て行かれた。'),
('JPN', '约翰福音', 43, 9, 1, 'さて、イエスは通りすがりに、生まれたときから目の見えない人をご覧になった。'),
('JPN', '约翰福音', 43, 9, 2, '弟子たちはイエスに尋ねた。「先生。この人が盲目で生まれたのは、だれが罪を犯したからですか。この人ですか。両親ですか。」'),
('JPN', '约翰福音', 43, 9, 3, 'イエスは答えられた。「この人が罪を犯したのでもなく、両親でもありません。この人に神のわざが現れるためです。'),
('JPN', '约翰福音', 43, 9, 4, 'わたしたちは、わたしを遣わされた方のわざを、昼のうちに行わなければなりません。だれも働くことができない夜が来ます。'),
('JPN', '约翰福音', 43, 9, 5, 'わたしが世にいる間は、わたしが世の光です。」'),
('JPN', '约翰福音', 43, 9, 6, 'イエスはこう言ってから、地面に唾をして、その唾で泥を作られた。そして、その泥を彼の目に塗って、'),
('JPN', '约翰福音', 43, 9, 7, '「行って、シロアム（訳すと、遣わされた者）の池で洗いなさい」と言われた。そこで、彼は行って洗った。すると、見えるようになり、帰って行った。'),
('JPN', '约翰福音', 43, 9, 8, '近所の人たちや、彼が物乞いであったのを前に見ていた人たちが言った。「これは座って物乞いをしていた人ではないか。」'),
('JPN', '约翰福音', 43, 9, 9, 'ある者たちは、「そうだ」と言い、ほかの者たちは「違う。似ているだけだ」と言った。当人は、「私がその人です」と言った。'),
('JPN', '约翰福音', 43, 9, 10, 'そこで、彼らは言った。「では、おまえの目はどのようにして開いたのか。」'),
('JPN', '约翰福音', 43, 9, 11, '彼は答えた。「イエスという方が泥を作って、私の目に塗り、『シロアムの池に行って洗いなさい』と言われました。それで、行って洗うと、見えるようになりました。」'),
('JPN', '约翰福音', 43, 9, 12, '彼らが「その人はどこにいるのか」と言うと、彼は「知りません」と答えた。'),
('JPN', '约翰福音', 43, 9, 13, '人々は、前に目の見えなかったその人を、パリサイ人たちのところに連れて行った。'),
('JPN', '约翰福音', 43, 9, 14, 'イエスが泥を作って彼の目を開けたのは、安息日であった。'),
('JPN', '约翰福音', 43, 9, 15, 'こういうわけで再び、パリサイ人たちも、どのようにして見えるようになったのか、彼に尋ねた。彼は、「あの方が私の目に泥を塗り、私が洗いました。それで今は見えるのです」と答えた。'),
('JPN', '约翰福音', 43, 9, 16, 'すると、パリサイ人のうちのある者たちは、「その人は安息日を守らないのだから、神のもとから来た者ではない」と言った。ほかの者たちは「罪人である者に、どうしてこのようなしるしを行うことができるだろうか」と言った。そして、彼らの間に分裂が生じた。'),
('JPN', '约翰福音', 43, 9, 17, 'そこで、彼らは再び、目の見えなかった人に言った。「おまえは、あの人についてどう思うか。あの人に目を開けてもらったのだから。」彼は「あの方は預言者です」と答えた。'),
('JPN', '约翰福音', 43, 9, 18, 'ユダヤ人たちはこの人について、目が見えなかったのに見えるようになったことを信じず、ついには、目が見えるようになった人の両親を呼び出して、'),
('JPN', '约翰福音', 43, 9, 19, '尋ねた。「この人は、あなたがたの息子か。盲目で生まれたとあなたがたが言っている者か。そうだとしたら、どうして今は見えるのか。」'),
('JPN', '约翰福音', 43, 9, 20, 'そこで、両親は答えた。「これが私たちの息子で、盲目で生まれたことは知っています。'),
('JPN', '约翰福音', 43, 9, 21, 'しかし、どうして今見えているのかは知りません。だれが息子の目を開けてくれたのかも知りません。本人に聞いてください。もう大人です。自分のことは自分で話すでしょう。」'),
('JPN', '约翰福音', 43, 9, 22, '彼の両親がこう言ったのは、ユダヤ人たちを恐れたからであった。すでにユダヤ人たちは、イエスをキリストであると告白する者がいれば、会堂から追放すると決めていた。'),
('JPN', '约翰福音', 43, 9, 23, 'そのために彼の両親は、「もう大人ですから、息子に聞いてください」と言ったのである。'),
('JPN', '约翰福音', 43, 9, 24, 'そこで彼らは、目の見えなかったその人をもう一度呼び出して言った。「神に栄光を帰しなさい。私たちはあの人が罪人であることを知っているのだ。」'),
('JPN', '约翰福音', 43, 9, 25, '彼は答えた。「あの方が罪人かどうか私は知りませんが、一つのことは知っています。私は盲目であったのに、今は見えるということです。」'),
('JPN', '约翰福音', 43, 9, 26, '彼らは言った。「あの人はおまえに何をしたのか。どのようにしておまえの目を開けたのか。」'),
('JPN', '约翰福音', 43, 9, 27, '彼は答えた。「すでに話しましたが、あなたがたは聞いてくれませんでした。なぜもう一度聞こうとするのですか。あなたがたも、あの方の弟子になりたいのですか。」'),
('JPN', '约翰福音', 43, 9, 28, '彼らは彼をののしって言った。「おまえはあの者の弟子だが、私たちはモーセの弟子だ。'),
('JPN', '约翰福音', 43, 9, 29, '神がモーセに語られたということを私たちは知っている。しかし、あの者については、どこから来たのか知らない。」'),
('JPN', '约翰福音', 43, 9, 30, 'その人は彼らに答えた。「これは驚きです。あの方がどこから来られたのか、あなたがたが知らないとは。あの方は私の目を開けてくださったのです。'),
('JPN', '约翰福音', 43, 9, 31, '私たちは知っています。神は、罪人たちの言うことはお聞きになりませんが、神を敬い、神のみこころを行う者がいれば、その人の言うことはお聞きくださいます。'),
('JPN', '约翰福音', 43, 9, 32, '盲目で生まれた者の目を開けた人がいるなどと、昔から聞いたことがありません。'),
('JPN', '约翰福音', 43, 9, 33, 'あの方が神から出ておられるのでなかったら、何もできなかったはずです。」'),
('JPN', '约翰福音', 43, 9, 34, '彼らは答えて言った。「おまえは全く罪の中に生まれていながら、私たちを教えるのか。」そして、彼を外に追い出した。'),
('JPN', '约翰福音', 43, 9, 35, 'イエスは、ユダヤ人たちが彼を外に追い出したことを聞き、彼を見つけ出して言われた。「あなたは人の子を信じますか。」'),
('JPN', '约翰福音', 43, 9, 36, 'その人は答えた。「主よ、私が信じることができるように教えてください。その人はどなたですか。」'),
('JPN', '约翰福音', 43, 9, 37, 'イエスは彼に言われた。「あなたはその人を見ています。あなたと話しているのが、その人です。」'),
('JPN', '约翰福音', 43, 9, 38, '彼は「主よ、信じます」と言って、イエスを礼拝した。'),
('JPN', '约翰福音', 43, 9, 39, 'そこで、イエスは言われた。「わたしはさばきのためにこの世に来ました。目の見えない者が見えるようになり、見える者が盲目となるためです。」'),
('JPN', '约翰福音', 43, 9, 40, 'パリサイ人の中でイエスとともにいた者たちが、このことを聞いて、イエスに言った。「私たちも盲目なのですか。」'),
('JPN', '约翰福音', 43, 9, 41, 'イエスは彼らに言われた。「もしあなたがたが盲目であったなら、あなたがたに罪はなかったでしょう。しかし、今、『私たちは見える』と言っているのですから、あなたがたの罪は残ります。」'),
('JPN', '约翰福音', 43, 10, 1, '「まことに、まことに、あなたがたに言います。羊たちの囲いに、門から入らず、ほかのところを乗り越えて来る者は、盗人であり強盗です。'),
('JPN', '约翰福音', 43, 10, 2, 'しかし、門から入るのは羊たちの牧者です。'),
('JPN', '约翰福音', 43, 10, 3, '門番は牧者のために門を開き、羊たちはその声を聞き分けます。牧者は自分の羊たちを、それぞれ名を呼んで連れ出します。'),
('JPN', '约翰福音', 43, 10, 4, '羊たちをみな外に出すと、牧者はその先頭に立って行き、羊たちはついて行きます。彼の声を知っているからです。'),
('JPN', '约翰福音', 43, 10, 5, 'しかし、ほかの人には決してついて行かず、逃げて行きます。ほかの人たちの声は知らないからです。」'),
('JPN', '约翰福音', 43, 10, 6, 'イエスはこの比喩を彼らに話されたが、彼らは、イエスが話されたことが何のことなのか、分からなかった。'),
('JPN', '约翰福音', 43, 10, 7, 'そこで、再びイエスは言われた。「まことに、まことに、あなたがたに言います。わたしは羊たちの門です。'),
('JPN', '约翰福音', 43, 10, 8, 'わたしの前に来た者たちはみな、盗人であり強盗です。羊たちは彼らの言うことを聞きませんでした。'),
('JPN', '约翰福音', 43, 10, 9, 'わたしは門です。だれでも、わたしを通って入るなら救われます。また出たり入ったりして、牧草を見つけます。'),
('JPN', '约翰福音', 43, 10, 10, '盗人が来るのは、盗んだり、殺したり、滅ぼしたりするためにほかなりません。わたしが来たのは、羊たちがいのちを得るため、それも豊かに得るためです。'),
('JPN', '约翰福音', 43, 10, 11, 'わたしは良い牧者です。良い牧者は羊たちのためにいのちを捨てます。'),
('JPN', '约翰福音', 43, 10, 12, '牧者でない雇い人は、羊たちが自分のものではないので、狼が来るのを見ると、置き去りにして逃げてしまいます。それで、狼は羊たちを奪ったり散らしたりします。'),
('JPN', '约翰福音', 43, 10, 13, '彼は雇い人で、羊たちのことを心にかけていないからです。'),
('JPN', '约翰福音', 43, 10, 14, 'わたしは良い牧者です。わたしはわたしのものを知っており、わたしのものは、わたしを知っています。'),
('JPN', '约翰福音', 43, 10, 15, 'ちょうど、父がわたしを知っておられ、わたしが父を知っているのと同じです。また、わたしは羊たちのために自分のいのちを捨てます。'),
('JPN', '约翰福音', 43, 10, 16, 'わたしにはまた、この囲いに属さないほかの羊たちがいます。それらも、わたしは導かなければなりません。その羊たちはわたしの声に聞き従います。そして、一つの群れ、一人の牧者となるのです。'),
('JPN', '约翰福音', 43, 10, 17, 'わたしが再びいのちを得るために自分のいのちを捨てるからこそ、父はわたしを愛してくださいます。'),
('JPN', '约翰福音', 43, 10, 18, 'だれも、わたしからいのちを取りません。わたしが自分からいのちを捨てるのです。わたしには、それを捨てる権威があり、再び得る権威があります。わたしはこの命令を、わたしの父から受けたのです。」'),
('JPN', '约翰福音', 43, 10, 19, 'これらのことばのために、ユダヤ人たちの間に再び分裂が生じた。'),
('JPN', '约翰福音', 43, 10, 20, '彼らのうちの多くの人が言った。「彼は悪霊につかれておかしくなっている。どうしてあなたがたは、彼の言うことを聞くのか。」'),
('JPN', '约翰福音', 43, 10, 21, 'ほかの者たちは言った。「これは悪霊につかれた人のことばではない。見えない人の目を開けることを、悪霊ができるというのか。」'),
('JPN', '约翰福音', 43, 10, 22, 'そのころ、エルサレムで宮きよめの祭りがあった。時は冬であった。'),
('JPN', '约翰福音', 43, 10, 23, 'イエスは宮の中で、ソロモンの回廊を歩いておられた。'),
('JPN', '约翰福音', 43, 10, 24, 'ユダヤ人たちは、イエスを取り囲んで言った。「あなたは、いつまで私たちに気をもませるのですか。あなたがキリストなら、はっきりと言ってください。」'),
('JPN', '约翰福音', 43, 10, 25, 'イエスは彼らに答えられた。「わたしは話したのに、あなたがたは信じません。わたしが父の名によって行うわざが、わたしについて証ししているのに、'),
('JPN', '约翰福音', 43, 10, 26, 'あなたがたは信じません。あなたがたがわたしの羊の群れに属していないからです。'),
('JPN', '约翰福音', 43, 10, 27, 'わたしの羊たちはわたしの声を聞き分けます。わたしもその羊たちを知っており、彼らはわたしについて来ます。'),
('JPN', '约翰福音', 43, 10, 28, 'わたしは彼らに永遠のいのちを与えます。彼らは永遠に、決して滅びることがなく、また、だれも彼らをわたしの手から奪い去りはしません。'),
('JPN', '约翰福音', 43, 10, 29, 'わたしの父がわたしに与えてくださった者は、すべてにまさって大切です。だれも彼らを、父の手から奪い去ることはできません。'),
('JPN', '约翰福音', 43, 10, 30, 'わたしと父とは一つです。」'),
('JPN', '约翰福音', 43, 10, 31, 'ユダヤ人たちは、イエスを石打ちにしようとして、再び石を取り上げた。'),
('JPN', '约翰福音', 43, 10, 32, 'イエスは彼らに答えられた。「わたしは、父から出た多くの良いわざを、あなたがたに示しました。そのうちのどのわざのために、わたしを石打ちにしようとするのですか。」'),
('JPN', '约翰福音', 43, 10, 33, 'ユダヤ人たちはイエスに答えた。「あなたを石打ちにするのは良いわざのためではなく、冒瀆のためだ。あなたは人間でありながら、自分を神としているからだ。」'),
('JPN', '约翰福音', 43, 10, 34, 'イエスは彼らに答えられた。「あなたがたの律法に、『わたしは言った。「おまえたちは神々だ」』と書かれていないでしょうか。'),
('JPN', '约翰福音', 43, 10, 35, '神のことばを受けた人々を神々と呼んだのなら、聖書が廃棄されることはあり得ないのだから、'),
('JPN', '约翰福音', 43, 10, 36, '『わたしは神の子である』とわたしが言ったからといって、どうしてあなたがたは、父が聖なる者とし、世に遣わした者について、『神を冒瀆している』と言うのですか。'),
('JPN', '约翰福音', 43, 10, 37, 'もしわたしが、わたしの父のみわざを行っていないのなら、わたしを信じてはなりません。'),
('JPN', '约翰福音', 43, 10, 38, 'しかし、行っているのなら、たとえわたしが信じられなくても、わたしのわざを信じなさい。それは、父がわたしにおられ、わたしも父にいることを、あなたがたが知り、また深く理解するようになるためです。」'),
('JPN', '约翰福音', 43, 10, 39, 'そこで、彼らは再びイエスを捕らえようとしたが、イエスは彼らの手から逃れられた。'),
('JPN', '约翰福音', 43, 10, 40, 'そして、イエスは再びヨルダンの川向こう、ヨハネが初めにバプテスマを授けていた場所に行き、そこに滞在された。'),
('JPN', '约翰福音', 43, 10, 41, '多くの人々がイエスのところに来た。彼らは「ヨハネは何もしるしを行わなかったが、この方についてヨハネが話したことはすべて真実であった」と言った。'),
('JPN', '约翰福音', 43, 10, 42, 'そして、その地で多くの人々がイエスを信じた。'),
('JPN', '约翰福音', 43, 11, 1, 'さて、ある人が病気にかかっていた。ベタニアのラザロである。ベタニアはマリアとその姉妹マルタの村であった。'),
('JPN', '约翰福音', 43, 11, 2, 'このマリアは、主に香油を塗り、自分の髪で主の足をぬぐったマリアで、彼女の兄弟ラザロが病んでいたのである。'),
('JPN', '约翰福音', 43, 11, 3, '姉妹たちは、イエスのところに使いを送って言った。「主よ、ご覧ください。あなたが愛しておられる者が病気です。」'),
('JPN', '约翰福音', 43, 11, 4, 'これを聞いて、イエスは言われた。「この病気は死で終わるものではなく、神の栄光のためのものです。それによって神の子が栄光を受けることになります。」'),
('JPN', '约翰福音', 43, 11, 5, 'イエスはマルタとその姉妹とラザロを愛しておられた。'),
('JPN', '约翰福音', 43, 11, 6, 'しかし、イエスはラザロが病んでいると聞いてからも、そのときいた場所に二日とどまられた。'),
('JPN', '约翰福音', 43, 11, 7, 'それからイエスは、「もう一度ユダヤに行こう」と弟子たちに言われた。'),
('JPN', '约翰福音', 43, 11, 8, '弟子たちはイエスに言った。「先生。ついこの間ユダヤ人たちがあなたを石打ちにしようとしたのに、またそこにおいでになるのですか。」'),
('JPN', '约翰福音', 43, 11, 9, 'イエスは答えられた。「昼間は十二時間あるではありませんか。だれでも昼間歩けば、つまずくことはありません。この世の光を見ているからです。'),
('JPN', '约翰福音', 43, 11, 10, 'しかし、夜歩けばつまずきます。その人のうちに光がないからです。」'),
('JPN', '约翰福音', 43, 11, 11, 'イエスはこのように話し、それから弟子たちに言われた。「わたしたちの友ラザロは眠ってしまいました。わたしは彼を起こしに行きます。」'),
('JPN', '约翰福音', 43, 11, 12, '弟子たちはイエスに言った。「主よ。眠っているのなら、助かるでしょう。」'),
('JPN', '约翰福音', 43, 11, 13, 'イエスは、ラザロの死のことを言われたのだが、彼らは睡眠の意味での眠りを言われたものと思ったのである。'),
('JPN', '约翰福音', 43, 11, 14, 'そこで、イエスは弟子たちに、今度ははっきりと言われた。「ラザロは死にました。'),
('JPN', '约翰福音', 43, 11, 15, 'あなたがたのため、あなたがたが信じるためには、わたしがその場に居合わせなかったことを喜んでいます。さあ、彼のところへ行きましょう。」'),
('JPN', '约翰福音', 43, 11, 16, 'そこで、デドモと呼ばれるトマスが仲間の弟子たちに言った。「私たちも行って、主と一緒に死のうではないか。」'),
('JPN', '约翰福音', 43, 11, 17, 'イエスがおいでになると、ラザロは墓の中に入れられて、すでに四日たっていた。'),
('JPN', '约翰福音', 43, 11, 18, 'ベタニアはエルサレムに近く、十五スタディオンほど離れたところにあった。'),
('JPN', '约翰福音', 43, 11, 19, 'マルタとマリアのところには、兄弟のことで慰めようと、大勢のユダヤ人が来ていた。'),
('JPN', '约翰福音', 43, 11, 20, 'マルタは、イエスが来られたと聞いて、出迎えに行った。マリアは家で座っていた。'),
('JPN', '约翰福音', 43, 11, 21, 'マルタはイエスに言った。「主よ。もしここにいてくださったなら、私の兄弟は死ななかったでしょうに。'),
('JPN', '约翰福音', 43, 11, 22, 'しかし、あなたが神にお求めになることは何でも、神があなたにお与えになることを、私は今でも知っています。」'),
('JPN', '约翰福音', 43, 11, 23, 'イエスは彼女に言われた。「あなたの兄弟はよみがえります。」'),
('JPN', '约翰福音', 43, 11, 24, 'マルタはイエスに言った。「終わりの日のよみがえりの時に、私の兄弟がよみがえることは知っています。」'),
('JPN', '约翰福音', 43, 11, 25, 'イエスは彼女に言われた。「わたしはよみがえりです。いのちです。わたしを信じる者は死んでも生きるのです。'),
('JPN', '约翰福音', 43, 11, 26, 'また、生きていてわたしを信じる者はみな、永遠に決して死ぬことがありません。あなたは、このことを信じますか。」'),
('JPN', '约翰福音', 43, 11, 27, '彼女はイエスに言った。「はい、主よ。私は、あなたが世に来られる神の子キリストであると信じております。」'),
('JPN', '约翰福音', 43, 11, 28, 'マルタはこう言ってから、帰って行って姉妹のマリアを呼び、そっと伝えた。「先生がお見えになり、あなたを呼んでおられます。」'),
('JPN', '约翰福音', 43, 11, 29, 'マリアはそれを聞くと、すぐに立ち上がって、イエスのところに行った。'),
('JPN', '约翰福音', 43, 11, 30, 'イエスはまだ村に入らず、マルタが出迎えた場所におられた。'),
('JPN', '约翰福音', 43, 11, 31, 'マリアとともに家にいて、彼女を慰めていたユダヤ人たちは、マリアが急いで立ち上がって出て行くのを見て、墓に泣きに行くのだろうと思い、ついて行った。'),
('JPN', '约翰福音', 43, 11, 32, 'マリアはイエスがおられるところに来た。そしてイエスを見ると、足もとにひれ伏して言った。「主よ。もしここにいてくださったなら、私の兄弟は死ななかったでしょうに。」'),
('JPN', '约翰福音', 43, 11, 33, 'イエスは、彼女が泣き、一緒に来たユダヤ人たちも泣いているのをご覧になった。そして、霊に憤りを覚え、心を騒がせて、'),
('JPN', '约翰福音', 43, 11, 34, '「彼をどこに置きましたか」と言われた。彼らはイエスに「主よ、来てご覧ください」と言った。'),
('JPN', '约翰福音', 43, 11, 35, 'イエスは涙を流された。'),
('JPN', '约翰福音', 43, 11, 36, 'ユダヤ人たちは言った。「ご覧なさい。どんなにラザロを愛しておられたことか。」'),
('JPN', '约翰福音', 43, 11, 37, 'しかし、彼らのうちのある者たちは、「見えない人の目を開けたこの方も、ラザロが死なないようにすることはできなかったのか」と言った。'),
('JPN', '约翰福音', 43, 11, 38, 'イエスは再び心のうちに憤りを覚えながら、墓に来られた。墓は洞穴で、石が置かれてふさがれていた。'),
('JPN', '约翰福音', 43, 11, 39, 'イエスは言われた。「その石を取りのけなさい。」死んだラザロの姉妹マルタは言った。「主よ、もう臭くなっています。四日になりますから。」'),
('JPN', '约翰福音', 43, 11, 40, 'イエスは彼女に言われた。「信じるなら神の栄光を見る、とあなたに言ったではありませんか。」'),
('JPN', '约翰福音', 43, 11, 41, 'そこで、彼らは石を取りのけた。イエスは目を上げて言われた。「父よ、わたしの願いを聞いてくださったことを感謝します。'),
('JPN', '约翰福音', 43, 11, 42, 'あなたはいつでもわたしの願いを聞いてくださると、わたしは知っておりましたが、周りにいる人たちのために、こう申し上げました。あなたがわたしを遣わされたことを、彼らが信じるようになるために。」'),
('JPN', '约翰福音', 43, 11, 43, 'そう言ってから、イエスは大声で叫ばれた。「ラザロよ、出て来なさい。」'),
('JPN', '约翰福音', 43, 11, 44, 'すると、死んでいた人が、手と足を長い布で巻かれたまま出て来た。彼の顔は布で包まれていた。イエスは彼らに言われた。「ほどいてやって、帰らせなさい。」'),
('JPN', '约翰福音', 43, 11, 45, 'マリアのところに来ていて、イエスがなさったことを見たユダヤ人の多くが、イエスを信じた。'),
('JPN', '约翰福音', 43, 11, 46, 'しかし、何人かはパリサイ人たちのところに行って、イエスがなさったことを伝えた。'),
('JPN', '约翰福音', 43, 11, 47, '祭司長たちとパリサイ人たちは最高法院を召集して言った。「われわれは何をしているのか。あの者が多くのしるしを行っているというのに。'),
('JPN', '约翰福音', 43, 11, 48, 'あの者をこのまま放っておけば、すべての人があの者を信じるようになる。そうなると、ローマ人がやって来て、われわれの土地も国民も取り上げてしまうだろう。」'),
('JPN', '约翰福音', 43, 11, 49, 'しかし、彼らのうちの一人で、その年の大祭司であったカヤパが、彼らに言った。「あなたがたは何も分かっていない。'),
('JPN', '约翰福音', 43, 11, 50, '一人の人が民に代わって死んで、国民全体が滅びないですむほうが、自分たちにとって得策だということを、考えてもいない。」'),
('JPN', '约翰福音', 43, 11, 51, 'このことは、彼が自分から言ったのではなかった。彼はその年の大祭司であったので、イエスが国民のために死のうとしておられること、'),
('JPN', '约翰福音', 43, 11, 52, 'また、ただ国民のためだけでなく、散らされている神の子らを一つに集めるためにも死のうとしておられることを、預言したのである。'),
('JPN', '约翰福音', 43, 11, 53, 'その日以来、彼らはイエスを殺そうと企んだ。'),
('JPN', '约翰福音', 43, 11, 54, 'そのために、イエスはもはやユダヤ人たちの間を公然と歩くことをせず、そこから荒野に近い地方に去って、エフライムという町に入り、弟子たちとともにそこに滞在された。'),
('JPN', '约翰福音', 43, 11, 55, 'さて、ユダヤ人の過越の祭りが近づいた。多くの人々が、身を清めるため、過越の祭りの前に地方からエルサレムに上って来た。'),
('JPN', '约翰福音', 43, 11, 56, '彼らはイエスを捜し、宮の中に立って互いに話していた。「どう思うか。あの方は祭りに来られないのだろうか。」'),
('JPN', '约翰福音', 43, 11, 57, '祭司長たち、パリサイ人たちはイエスを捕らえるために、イエスがどこにいるかを知っている者は報告するように、という命令を出していた。'),
('JPN', '约翰福音', 43, 12, 1, 'さて、イエスは過越の祭りの六日前にベタニアに来られた。そこには、イエスが死人の中からよみがえらせたラザロがいた。'),
('JPN', '约翰福音', 43, 12, 2, '人々はイエスのために、そこに夕食を用意した。マルタは給仕し、ラザロは、イエスとともに食卓に着いていた人たちの中にいた。'),
('JPN', '约翰福音', 43, 12, 3, '一方マリアは、純粋で非常に高価なナルドの香油を一リトラ取って、イエスの足に塗り、自分の髪でその足をぬぐった。家は香油の香りでいっぱいになった。'),
('JPN', '约翰福音', 43, 12, 4, '弟子の一人で、イエスを裏切ろうとしていたイスカリオテのユダが言った。'),
('JPN', '约翰福音', 43, 12, 5, '「どうして、この香油を三百デナリで売って、貧しい人々に施さなかったのか。」'),
('JPN', '约翰福音', 43, 12, 6, '彼がこう言ったのは、貧しい人々のことを心にかけていたからではなく、彼が盗人で、金入れを預かりながら、そこに入っているものを盗んでいたからであった。'),
('JPN', '约翰福音', 43, 12, 7, 'イエスは言われた。「そのままさせておきなさい。マリアは、わたしの葬りの日のために、それを取っておいたのです。'),
('JPN', '约翰福音', 43, 12, 8, '貧しい人々は、いつもあなたがたと一緒にいますが、わたしはいつも一緒にいるわけではありません。」'),
('JPN', '约翰福音', 43, 12, 9, 'すると、大勢のユダヤ人の群衆が、そこにイエスがおられると知って、やって来た。イエスに会うためだけではなく、イエスが死人の中からよみがえらせたラザロを見るためでもあった。'),
('JPN', '约翰福音', 43, 12, 10, '祭司長たちはラザロも殺そうと相談した。'),
('JPN', '约翰福音', 43, 12, 11, '彼のために多くのユダヤ人が去って行き、イエスを信じるようになったからである。'),
('JPN', '约翰福音', 43, 12, 12, 'その翌日、祭りに来ていた大勢の群衆は、イエスがエルサレムに来られると聞いて、'),
('JPN', '约翰福音', 43, 12, 13, 'なつめ椰子の枝を持って迎えに出て行き、こう叫んだ。「ホサナ。祝福あれ、主の御名によって来られる方に。イスラエルの王に。」'),
('JPN', '约翰福音', 43, 12, 14, 'イエスはろばの子を見つけて、それに乗られた。次のように書かれているとおりである。'),
('JPN', '约翰福音', 43, 12, 15, '「恐れるな、娘シオン。見よ、あなたの王が来られる。ろばの子に乗って。」'),
('JPN', '约翰福音', 43, 12, 16, 'これらのことは、初め弟子たちには分からなかった。しかし、イエスが栄光を受けられた後、これがイエスについて書かれていたことで、それを人々がイエスに行ったのだと、彼らは思い起こした。'),
('JPN', '约翰福音', 43, 12, 17, 'さて、イエスがラザロを墓から呼び出して、死人の中からよみがえらせたときにイエスと一緒にいた群衆は、そのことを証しし続けていた。'),
('JPN', '约翰福音', 43, 12, 18, '群衆がイエスを出迎えたのは、イエスがこのしるしを行われたことを聞いたからであった。'),
('JPN', '约翰福音', 43, 12, 19, 'それで、パリサイ人たちは互いに言った。「見てみなさい。何一つうまくいっていない。見なさい。世はこぞってあの人の後について行ってしまった。」'),
('JPN', '约翰福音', 43, 12, 20, 'さて、祭りで礼拝のために上って来た人々の中に、ギリシア人が何人かいた。'),
('JPN', '约翰福音', 43, 12, 21, 'この人たちは、ガリラヤのベツサイダ出身のピリポのところに来て、「お願いします。イエスにお目にかかりたいのです」と頼んだ。'),
('JPN', '约翰福音', 43, 12, 22, 'ピリポは行ってアンデレに話し、アンデレとピリポは行って、イエスに話した。'),
('JPN', '约翰福音', 43, 12, 23, 'すると、イエスは彼らに答えられた。「人の子が栄光を受ける時が来ました。'),
('JPN', '约翰福音', 43, 12, 24, 'まことに、まことに、あなたがたに言います。一粒の麦は、地に落ちて死ななければ、一粒のままです。しかし、死ぬなら、豊かな実を結びます。'),
('JPN', '约翰福音', 43, 12, 25, '自分のいのちを愛する者はそれを失い、この世で自分のいのちを憎む者は、それを保って永遠のいのちに至ります。'),
('JPN', '约翰福音', 43, 12, 26, 'わたしに仕えるというのなら、その人はわたしについて来なさい。わたしがいるところに、わたしに仕える者もいることになります。わたしに仕えるなら、父はその人を重んじてくださいます。」'),
('JPN', '约翰福音', 43, 12, 27, '「今わたしの心は騒いでいる。何と言おうか。『父よ、この時からわたしをお救いください』と言おうか。いや、このためにこそ、わたしはこの時に至ったのだ。'),
('JPN', '约翰福音', 43, 12, 28, '父よ、御名の栄光を現してください。」すると、天から声が聞こえた。「わたしはすでに栄光を現した。わたしは再び栄光を現そう。」'),
('JPN', '约翰福音', 43, 12, 29, 'そばに立っていてそれを聞いた群衆は、「雷が鳴ったのだ」と言った。ほかの人々は、「御使いがあの方に話しかけたのだ」と言った。'),
('JPN', '约翰福音', 43, 12, 30, 'イエスは答えられた。「この声が聞こえたのは、わたしのためではなく、あなたがたのためです。'),
('JPN', '约翰福音', 43, 12, 31, '今、この世に対するさばきが行われ、今、この世を支配する者が追い出されます。'),
('JPN', '约翰福音', 43, 12, 32, 'わたしが地上から上げられるとき、わたしはすべての人を自分のもとに引き寄せます。」'),
('JPN', '约翰福音', 43, 12, 33, 'これは、ご自分がどのような死に方で死ぬことになるかを示して、言われたのである。'),
('JPN', '约翰福音', 43, 12, 34, 'そこで、群衆はイエスに答えた。「私たちは律法によって、キリストはいつまでも生きると聞きましたが、あなたはどうして、人の子は上げられなければならないと言われるのですか。その人の子とはだれですか。」'),
('JPN', '约翰福音', 43, 12, 35, 'そこで、イエスは彼らに言われた。「もうしばらく、光はあなたがたの間にあります。闇があなたがたを襲うことがないように、あなたがたは光があるうちに歩きなさい。闇の中を歩く者は、自分がどこに行くのか分かりません。'),
('JPN', '约翰福音', 43, 12, 36, '自分に光があるうちに、光の子どもとなれるように、光を信じなさい。」イエスは、これらのことを話すと、立ち去って彼らから身を隠された。'),
('JPN', '约翰福音', 43, 12, 37, 'イエスがこれほど多くのしるしを彼らの目の前で行われたのに、彼らはイエスを信じなかった。'),
('JPN', '约翰福音', 43, 12, 38, 'それは、預言者イザヤのことばが成就するためであった。彼はこう言っている。「主よ。私たちが聞いたことを、だれが信じたか。主の御腕はだれに現れたか。」'),
('JPN', '约翰福音', 43, 12, 39, 'イザヤはまた次のように言っているので、彼らは信じることができなかったのである。'),
('JPN', '约翰福音', 43, 12, 40, '「主は彼らの目を見えないようにされた。また、彼らの心を頑なにされた。彼らがその目で見ることも、心で理解することも、立ち返ることもないように。そして、わたしが彼らを癒やすこともないように。」'),
('JPN', '约翰福音', 43, 12, 41, 'イザヤがこう言ったのは、イエスの栄光を見たからであり、イエスについて語ったのである。'),
('JPN', '约翰福音', 43, 12, 42, 'しかし、それにもかかわらず、議員たちの中にもイエスを信じた者が多くいた。ただ、会堂から追放されないように、パリサイ人たちを気にして、告白しなかった。'),
('JPN', '约翰福音', 43, 12, 43, '彼らは、神からの栄誉よりも、人からの栄誉を愛したのである。'),
('JPN', '约翰福音', 43, 12, 44, 'イエスは大きな声でこう言われた。「わたしを信じる者は、わたしではなく、わたしを遣わされた方を信じるのです。'),
('JPN', '约翰福音', 43, 12, 45, 'また、わたしを見る者は、わたしを遣わされた方を見るのです。'),
('JPN', '约翰福音', 43, 12, 46, 'わたしは光として世に来ました。わたしを信じる者が、だれも闇の中にとどまることのないようにするためです。'),
('JPN', '约翰福音', 43, 12, 47, 'だれか、わたしのことばを聞いてそれを守らない者がいても、わたしはその人をさばきません。わたしが来たのは世をさばくためではなく、世を救うためだからです。'),
('JPN', '约翰福音', 43, 12, 48, 'わたしを拒み、わたしのことばを受け入れない者には、その人をさばくものがあります。わたしが話したことば、それが、終わりの日にその人をさばきます。'),
('JPN', '约翰福音', 43, 12, 49, 'わたしは自分から話したのではなく、わたしを遣わされた父ご自身が、言うべきこと、話すべきことを、わたしにお命じになったのだからです。'),
('JPN', '约翰福音', 43, 12, 50, 'わたしは、父の命令が永遠のいのちであることを知っています。ですから、わたしが話していることは、父がわたしに言われたとおりを、そのまま話しているのです。」'),
('JPN', '约翰福音', 43, 13, 1, 'さて、過越の祭りの前のこと、イエスは、この世を去って父のみもとに行く、ご自分の時が来たことを知っておられた。そして、世にいるご自分の者たちを愛してきたイエスは、彼らを最後まで愛された。'),
('JPN', '约翰福音', 43, 13, 2, '夕食の間のこと、悪魔はすでにシモンの子イスカリオテのユダの心に、イエスを裏切ろうという思いを入れていた。'),
('JPN', '约翰福音', 43, 13, 3, 'イエスは、父が万物をご自分の手に委ねてくださったこと、またご自分が神から出て、神に帰ろうとしていることを知っておられた。'),
('JPN', '约翰福音', 43, 13, 4, 'イエスは夕食の席から立ち上がって、上着を脱ぎ、手ぬぐいを取って腰にまとわれた。'),
('JPN', '约翰福音', 43, 13, 5, 'それから、たらいに水を入れて、弟子たちの足を洗い、腰にまとっていた手ぬぐいでふき始められた。'),
('JPN', '约翰福音', 43, 13, 6, 'こうして、イエスがシモン・ペテロのところに来られると、ペテロはイエスに言った。「主よ、あなたが私の足を洗ってくださるのですか。」'),
('JPN', '约翰福音', 43, 13, 7, 'イエスは彼に答えられた。「わたしがしていることは、今は分からなくても、後で分かるようになります。」'),
('JPN', '约翰福音', 43, 13, 8, 'ペテロはイエスに言った。「決して私の足を洗わないでください。」イエスは答えられた。「わたしがあなたを洗わなければ、あなたはわたしと関係ないことになります。」'),
('JPN', '约翰福音', 43, 13, 9, 'シモン・ペテロは言った。「主よ、足だけでなく、手も頭も洗ってください。」'),
('JPN', '约翰福音', 43, 13, 10, 'イエスは彼に言われた。「水浴した者は、足以外は洗う必要がありません。全身がきよいのです。あなたがたはきよいのですが、皆がきよいわけではありません。」'),
('JPN', '约翰福音', 43, 13, 11, 'イエスはご自分を裏切る者を知っておられた。それで、「皆がきよいわけではない」と言われたのである。'),
('JPN', '约翰福音', 43, 13, 12, 'イエスは彼らの足を洗うと、上着を着て再び席に着き、彼らに言われた。「わたしがあなたがたに何をしたのか分かりますか。'),
('JPN', '约翰福音', 43, 13, 13, 'あなたがたはわたしを『先生』とか『主』とか呼んでいます。そう言うのは正しいことです。そのとおりなのですから。'),
('JPN', '约翰福音', 43, 13, 14, '主であり、師であるこのわたしが、あなたがたの足を洗ったのであれば、あなたがたもまた、互いに足を洗い合わなければなりません。'),
('JPN', '约翰福音', 43, 13, 15, 'わたしがあなたがたにしたとおりに、あなたがたもするようにと、あなたがたに模範を示したのです。'),
('JPN', '约翰福音', 43, 13, 16, 'まことに、まことに、あなたがたに言います。しもべは主人にまさらず、遣わされた者は遣わした者にまさりません。'),
('JPN', '约翰福音', 43, 13, 17, 'これらのことが分かっているなら、そして、それを行うなら、あなたがたは幸いです。'),
('JPN', '约翰福音', 43, 13, 18, 'わたしは、あなたがたすべてについて言っているのではありません。わたしは、自分が選んだ者たちを知っています。けれども、聖書に『わたしのパンを食べている者が、わたしに向かって、かかとを上げます』と書いてあることは成就するのです。'),
('JPN', '约翰福音', 43, 13, 19, '事が起こる前に、今からあなたがたに言っておきます。起こったときに、わたしが『わたしはある』であることを、あなたがたが信じるためです。'),
('JPN', '约翰福音', 43, 13, 20, 'まことに、まことに、あなたがたに言います。わたしが遣わす者を受け入れる者は、わたしを受け入れるのです。そして、わたしを受け入れる者は、わたしを遣わされた方を受け入れるのです。」'),
('JPN', '约翰福音', 43, 13, 21, 'イエスは、これらのことを話されたとき、心が騒いだ。そして証しされた。「まことに、まことに、あなたがたに言います。あなたがたのうちの一人が、わたしを裏切ります。」'),
('JPN', '约翰福音', 43, 13, 22, '弟子たちは、だれのことを言われたのか分からず当惑し、互いに顔を見合わせていた。'),
('JPN', '约翰福音', 43, 13, 23, '弟子の一人がイエスの胸のところで横になっていた。イエスが愛しておられた弟子である。'),
('JPN', '约翰福音', 43, 13, 24, 'そこで、シモン・ペテロは彼に、だれのことを言われたのか尋ねるように合図した。'),
('JPN', '约翰福音', 43, 13, 25, 'その弟子はイエスの胸元に寄りかかったまま、イエスに言った。「主よ、それはだれのことですか。」'),
('JPN', '约翰福音', 43, 13, 26, 'イエスは答えられた。「わたしがパン切れを浸して与える者が、その人です。」それからイエスはパン切れを浸して取り、イスカリオテのシモンの子ユダに与えられた。'),
('JPN', '约翰福音', 43, 13, 27, 'ユダがパン切れを受け取ると、そのとき、サタンが彼に入った。すると、イエスは彼に言われた。「あなたがしようとしていることを、すぐしなさい。」'),
('JPN', '约翰福音', 43, 13, 28, '席に着いていた者で、なぜイエスがユダにそう言われたのか、分かった者はだれもいなかった。'),
('JPN', '约翰福音', 43, 13, 29, 'ある者たちは、ユダが金入れを持っていたので、「祭りのために必要な物を買いなさい」とか、貧しい人々に何か施しをするようにとか、イエスが言われたのだと思っていた。'),
('JPN', '约翰福音', 43, 13, 30, 'ユダはパン切れを受けると、すぐに出て行った。時は夜であった。'),
('JPN', '约翰福音', 43, 13, 31, 'ユダが出て行ったとき、イエスは言われた。「今、人の子は栄光を受け、神も人の子によって栄光をお受けになりました。'),
('JPN', '约翰福音', 43, 13, 32, '神が、人の子によって栄光をお受けになったのなら、神も、ご自分で人の子に栄光を与えてくださいます。しかも、すぐに与えてくださいます。'),
('JPN', '约翰福音', 43, 13, 33, '子どもたちよ、わたしはもう少しの間あなたがたとともにいます。あなたがたはわたしを捜すことになります。ユダヤ人たちに言ったように、今あなたがたにも言います。わたしが行くところに、あなたがたは来ることができません。'),
('JPN', '约翰福音', 43, 13, 34, 'わたしはあなたがたに新しい戒めを与えます。互いに愛し合いなさい。わたしがあなたがたを愛したように、あなたがたも互いに愛し合いなさい。'),
('JPN', '约翰福音', 43, 13, 35, '互いの間に愛があるなら、それによって、あなたがたがわたしの弟子であることを、すべての人が認めるようになります。」'),
('JPN', '约翰福音', 43, 13, 36, 'シモン・ペテロがイエスに言った。「主よ、どこにおいでになるのですか。」イエスは答えられた。「わたしが行くところに、あなたは今ついて来ることができません。しかし後にはついて来ます。」'),
('JPN', '约翰福音', 43, 13, 37, 'ペテロはイエスに言った。「主よ、なぜ今ついて行けないのですか。あなたのためなら、いのちも捨てます。」'),
('JPN', '约翰福音', 43, 13, 38, 'イエスは答えられた。「わたしのためにいのちも捨てるのですか。まことに、まことに、あなたに言います。鶏が鳴くまでに、あなたは三度わたしを知らないと言います。」'),
('JPN', '约翰福音', 43, 14, 1, '「あなたがたは心を騒がせてはなりません。神を信じ、またわたしを信じなさい。'),
('JPN', '约翰福音', 43, 14, 2, 'わたしの父の家には住む所がたくさんあります。そうでなかったら、あなたがたのために場所を用意しに行く、と言ったでしょうか。'),
('JPN', '约翰福音', 43, 14, 3, 'わたしが行って、あなたがたに場所を用意したら、また来て、あなたがたをわたしのもとに迎えます。わたしがいるところに、あなたがたもいるようにするためです。'),
('JPN', '约翰福音', 43, 14, 4, 'わたしがどこに行くのか、その道をあなたがたは知っています。」'),
('JPN', '约翰福音', 43, 14, 5, 'トマスはイエスに言った。「主よ、どこへ行かれるのか、私たちには分かりません。どうしたら、その道を知ることができるでしょうか。」'),
('JPN', '约翰福音', 43, 14, 6, 'イエスは彼に言われた。「わたしが道であり、真理であり、いのちなのです。わたしを通してでなければ、だれも父のみもとに行くことはできません。'),
('JPN', '约翰福音', 43, 14, 7, 'あなたがたがわたしを知っているなら、わたしの父をも知ることになります。今から父を知るのです。いや、すでにあなたがたは父を見たのです。」'),
('JPN', '约翰福音', 43, 14, 8, 'ピリポはイエスに言った。「主よ、私たちに父を見せてください。そうすれば満足します。」'),
('JPN', '约翰福音', 43, 14, 9, 'イエスは彼に言われた。「ピリポ、こんなに長い間、あなたがたと一緒にいるのに、わたしを知らないのですか。わたしを見た人は、父を見たのです。どうしてあなたは、『私たちに父を見せてください』と言うのですか。'),
('JPN', '约翰福音', 43, 14, 10, 'わたしが父のうちにいて、父がわたしのうちにおられることを、信じていないのですか。わたしがあなたがたに言うことばは、自分から話しているのではありません。わたしのうちにおられる父が、ご自分のわざを行っておられるのです。'),
('JPN', '约翰福音', 43, 14, 11, 'わたしが父のうちにいて、父がわたしのうちにおられると、わたしが言うのを信じなさい。信じられないのなら、わざのゆえに信じなさい。'),
('JPN', '约翰福音', 43, 14, 12, 'まことに、まことに、あなたがたに言います。わたしを信じる者は、わたしが行うわざを行い、さらに大きなわざを行います。わたしが父のもとに行くからです。'),
('JPN', '约翰福音', 43, 14, 13, 'またわたしは、あなたがたがわたしの名によって求めることは、何でもそれをしてあげます。父が子によって栄光をお受けになるためです。'),
('JPN', '约翰福音', 43, 14, 14, 'あなたがたが、わたしの名によって何かをわたしに求めるなら、わたしがそれをしてあげます。'),
('JPN', '约翰福音', 43, 14, 15, 'もしわたしを愛しているなら、あなたがたはわたしの戒めを守るはずです。'),
('JPN', '约翰福音', 43, 14, 16, 'そしてわたしが父にお願いすると、父はもう一人の助け主をお与えくださり、その助け主がいつまでも、あなたがたとともにいるようにしてくださいます。'),
('JPN', '约翰福音', 43, 14, 17, 'この方は真理の御霊です。世はこの方を見ることも知ることもないので、受け入れることができません。あなたがたは、この方を知っています。この方はあなたがたとともにおられ、また、あなたがたのうちにおられるようになるのです。'),
('JPN', '约翰福音', 43, 14, 18, 'わたしは、あなたがたを捨てて孤児にはしません。あなたがたのところに戻って来ます。'),
('JPN', '约翰福音', 43, 14, 19, 'あと少しで、世はもうわたしを見なくなります。しかし、あなたがたはわたしを見ます。わたしが生き、あなたがたも生きることになるからです。'),
('JPN', '约翰福音', 43, 14, 20, 'その日には、わたしが父のうちに、あなたがたがわたしのうちに、そしてわたしがあなたがたのうちにいることが、あなたがたに分かります。'),
('JPN', '约翰福音', 43, 14, 21, 'わたしの戒めを保ち、それを守る人は、わたしを愛している人です。わたしを愛している人はわたしの父に愛され、わたしもその人を愛し、わたし自身をその人に現します。」'),
('JPN', '约翰福音', 43, 14, 22, 'イスカリオテでないほうのユダがイエスに言った。「主よ。私たちにはご自分を現そうとなさるのに、世にはそうなさらないのは、どうしてですか。」'),
('JPN', '约翰福音', 43, 14, 23, 'イエスは彼に答えられた。「だれでもわたしを愛する人は、わたしのことばを守ります。そうすれば、わたしの父はその人を愛し、わたしたちはその人のところに来て、その人とともに住みます。'),
('JPN', '约翰福音', 43, 14, 24, 'わたしを愛さない人は、わたしのことばを守りません。あなたがたが聞いていることばは、わたしのものではなく、わたしを遣わされた父のものです。'),
('JPN', '约翰福音', 43, 14, 25, 'これらのことを、わたしはあなたがたと一緒にいる間に話しました。'),
('JPN', '约翰福音', 43, 14, 26, 'しかし、助け主、すなわち、父がわたしの名によってお遣わしになる聖霊は、あなたがたにすべてのことを教え、わたしがあなたがたに話したすべてのことを思い起こさせてくださいます。'),
('JPN', '约翰福音', 43, 14, 27, 'わたしはあなたがたに平安を残します。わたしの平安を与えます。わたしは、世が与えるのと同じようには与えません。あなたがたは心を騒がせてはなりません。ひるんではなりません。'),
('JPN', '约翰福音', 43, 14, 28, '『わたしは去って行くが、あなたがたのところに戻って来る』とわたしが言ったのを、あなたがたは聞きました。わたしを愛しているなら、わたしが父のもとに行くことを、あなたがたは喜ぶはずです。父はわたしよりも偉大な方だからです。'),
('JPN', '约翰福音', 43, 14, 29, '今わたしは、それが起こる前にあなたがたに話しました。それが起こったとき、あなたがたが信じるためです。'),
('JPN', '约翰福音', 43, 14, 30, 'わたしはもう、あなたがたに多くを話しません。この世を支配する者が来るからです。彼はわたしに対して何もすることができません。'),
('JPN', '约翰福音', 43, 14, 31, 'それは、わたしが父を愛していて、父が命じられたとおりに行っていることを、世が知るためです。立ちなさい。さあ、ここから行くのです。'),
('JPN', '约翰福音', 43, 15, 1, 'わたしはまことのぶどうの木、わたしの父は農夫です。'),
('JPN', '约翰福音', 43, 15, 2, 'わたしの枝で実を結ばないものはすべて、父がそれを取り除き、実を結ぶものはすべて、もっと多く実を結ぶように、刈り込みをなさいます。'),
('JPN', '约翰福音', 43, 15, 3, 'あなたがたは、わたしがあなたがたに話したことばによって、すでにきよいのです。'),
('JPN', '约翰福音', 43, 15, 4, 'わたしにとどまりなさい。わたしもあなたがたの中にとどまります。枝がぶどうの木にとどまっていなければ、自分では実を結ぶことができないのと同じように、あなたがたもわたしにとどまっていなければ、実を結ぶことはできません。'),
('JPN', '约翰福音', 43, 15, 5, 'わたしはぶどうの木、あなたがたは枝です。人がわたしにとどまり、わたしもその人にとどまっているなら、その人は多くの実を結びます。わたしを離れては、あなたがたは何もすることができないのです。'),
('JPN', '约翰福音', 43, 15, 6, 'わたしにとどまっていなければ、その人は枝のように投げ捨てられて枯れます。人々がそれを集めて火に投げ込むので、燃えてしまいます。'),
('JPN', '约翰福音', 43, 15, 7, 'あなたがたがわたしにとどまり、わたしのことばがあなたがたにとどまっているなら、何でも欲しいものを求めなさい。そうすれば、それはかなえられます。'),
('JPN', '约翰福音', 43, 15, 8, 'あなたがたが多くの実を結び、わたしの弟子となることによって、わたしの父は栄光をお受けになります。'),
('JPN', '约翰福音', 43, 15, 9, '父がわたしを愛されたように、わたしもあなたがたを愛しました。わたしの愛にとどまりなさい。'),
('JPN', '约翰福音', 43, 15, 10, 'わたしがわたしの父の戒めを守って、父の愛にとどまっているのと同じように、あなたがたもわたしの戒めを守るなら、わたしの愛にとどまっているのです。'),
('JPN', '约翰福音', 43, 15, 11, 'わたしの喜びがあなたがたのうちにあり、あなたがたが喜びで満ちあふれるようになるために、わたしはこれらのことをあなたがたに話しました。'),
('JPN', '约翰福音', 43, 15, 12, 'わたしがあなたがたを愛したように、あなたがたも互いに愛し合うこと、これがわたしの戒めです。'),
('JPN', '约翰福音', 43, 15, 13, '人が自分の友のためにいのちを捨てること、これよりも大きな愛はだれも持っていません。'),
('JPN', '约翰福音', 43, 15, 14, 'わたしが命じることを行うなら、あなたがたはわたしの友です。'),
('JPN', '约翰福音', 43, 15, 15, 'わたしはもう、あなたがたをしもべとは呼びません。しもべなら主人が何をするのか知らないからです。わたしはあなたがたを友と呼びました。父から聞いたことをすべて、あなたがたには知らせたからです。'),
('JPN', '约翰福音', 43, 15, 16, 'あなたがたがわたしを選んだのではなく、わたしがあなたがたを選び、あなたがたを任命しました。それは、あなたがたが行って実を結び、その実が残るようになるため、また、あなたがたがわたしの名によって父に求めるものをすべて、父が与えてくださるようになるためです。'),
('JPN', '约翰福音', 43, 15, 17, 'あなたがたが互いに愛し合うこと、わたしはこれを、あなたがたに命じます。'),
('JPN', '约翰福音', 43, 15, 18, '世があなたがたを憎むなら、あなたがたよりも先にわたしを憎んだことを知っておきなさい。'),
('JPN', '约翰福音', 43, 15, 19, 'もしあなたがたがこの世のものであったら、世は自分のものを愛したでしょう。しかし、あなたがたは世のものではありません。わたしが世からあなたがたを選び出したのです。そのため、世はあなたがたを憎むのです。'),
('JPN', '约翰福音', 43, 15, 20, 'しもべは主人にまさるものではない、とわたしがあなたがたに言ったことばを覚えておきなさい。人々がわたしを迫害したのであれば、あなたがたも迫害します。彼らがわたしのことばを守ったのであれば、あなたがたのことばも守ります。'),
('JPN', '约翰福音', 43, 15, 21, 'しかし彼らは、これらのことをすべて、わたしの名のゆえにあなたがたに対して行います。わたしを遣わされた方を知らないからです。'),
('JPN', '约翰福音', 43, 15, 22, 'もしわたしが来て彼らに話さなかったら、彼らに罪はなかったでしょう。けれども今では、彼らの罪について弁解の余地はありません。'),
('JPN', '约翰福音', 43, 15, 23, 'わたしを憎んでいる者は、わたしの父をも憎んでいます。'),
('JPN', '约翰福音', 43, 15, 24, 'もしわたしが、ほかのだれも行ったことのないわざを、彼らの間で行わなかったら、彼らに罪はなかったでしょう。けれども今や、彼らはそのわざを見て、そのうえでわたしとわたしの父を憎みました。'),
('JPN', '约翰福音', 43, 15, 25, 'これは、『彼らはゆえもなくわたしを憎んだ』と、彼らの律法に書かれていることばが成就するためです。'),
('JPN', '约翰福音', 43, 15, 26, 'わたしが父のもとから遣わす助け主、すなわち、父から出る真理の御霊が来るとき、その方がわたしについて証ししてくださいます。'),
('JPN', '约翰福音', 43, 15, 27, 'あなたがたも証しします。初めからわたしと一緒にいたからです。'),
('JPN', '约翰福音', 43, 16, 1, 'わたしがこれらのことをあなたがたに話したのは、あなたがたがつまずくことのないためです。'),
('JPN', '约翰福音', 43, 16, 2, '人々はあなたがたを会堂から追放するでしょう。実際、あなたがたを殺す者がみな、自分は神に奉仕していると思う時が来ます。'),
('JPN', '约翰福音', 43, 16, 3, '彼らがそういうことを行うのは、父もわたしも知らないからです。'),
('JPN', '约翰福音', 43, 16, 4, 'これらのことをあなたがたに話したのは、その時が来たとき、わたしがそれについて話したことを、あなたがたが思い出すためです。わたしは初めからこれらのことを話すことはしませんでした。それはあなたがたとともにいたからです。'),
('JPN', '约翰福音', 43, 16, 5, 'しかし今、わたしは、わたしを遣わされた方のもとに行こうとしています。けれども、あなたがたのうちだれも、『どこに行くのですか』と尋ねません。'),
('JPN', '约翰福音', 43, 16, 6, 'むしろ、わたしがこれらのことを話したため、あなたがたの心は悲しみでいっぱいになっています。'),
('JPN', '约翰福音', 43, 16, 7, 'しかし、わたしは真実を言います。わたしが去って行くことは、あなたがたの益になるのです。去って行かなければ、あなたがたのところに助け主はおいでになりません。でも、行けば、わたしはあなたがたのところに助け主を遣わします。'),
('JPN', '约翰福音', 43, 16, 8, 'その方が来ると、罪について、義について、さばきについて、世の誤りを明らかになさいます。'),
('JPN', '约翰福音', 43, 16, 9, '罪についてというのは、彼らがわたしを信じないからです。'),
('JPN', '约翰福音', 43, 16, 10, '義についてとは、わたしが父のもとに行き、あなたがたがもはやわたしを見なくなるからです。'),
('JPN', '约翰福音', 43, 16, 11, 'さばきについてとは、この世を支配する者がさばかれたからです。'),
('JPN', '约翰福音', 43, 16, 12, 'あなたがたに話すことはまだたくさんありますが、今あなたがたはそれに耐えられません。'),
('JPN', '约翰福音', 43, 16, 13, 'しかし、その方、すなわち真理の御霊が来ると、あなたがたをすべての真理に導いてくださいます。御霊は自分から語るのではなく、聞いたことをすべて語り、これから起こることをあなたがたに伝えてくださいます。'),
('JPN', '约翰福音', 43, 16, 14, '御霊はわたしの栄光を現されます。わたしのものを受けて、あなたがたに伝えてくださるのです。'),
('JPN', '约翰福音', 43, 16, 15, '父が持っておられるものはすべて、わたしのものです。ですからわたしは、御霊がわたしのものを受けて、あなたがたに伝えると言ったのです。'),
('JPN', '约翰福音', 43, 16, 16, 'しばらくすると、あなたがたはもうわたしを見なくなりますが、またしばらくすると、わたしを見ます。」'),
('JPN', '约翰福音', 43, 16, 17, 'そこで、弟子たちのうちのある者たちは互いに言った。「『しばらくすると、あなたがたはわたしを見なくなるが、またしばらくすると、わたしを見る』、また『わたしは父のもとに行くからだ』と言われるのは、どういうことなのだろうか。」'),
('JPN', '约翰福音', 43, 16, 18, 'こうして、彼らは「しばらくすると、と言われるのは何のことだろうか。何を話しておられるのか私たちには分からない」と言った。'),
('JPN', '约翰福音', 43, 16, 19, 'イエスは、彼らが何かを尋ねたがっているのに気づいて、彼らに言われた。「『しばらくすると、あなたがたはわたしを見なくなるが、またしばらくすると、わたしを見る』と、わたしが言ったことについて、互いに論じ合っているのですか。'),
('JPN', '约翰福音', 43, 16, 20, 'まことに、まことに、あなたがたに言います。あなたがたは泣き、嘆き悲しむが、世は喜びます。あなたがたは悲しみます。しかし、あなたがたの悲しみは喜びに変わります。'),
('JPN', '约翰福音', 43, 16, 21, '女は子を産むとき、苦しみます。自分の時が来たからです。しかし、子を産んでしまうと、一人の人が世に生まれた喜びのために、その激しい痛みをもう覚えていません。'),
('JPN', '约翰福音', 43, 16, 22, 'あなたがたも今は悲しんでいます。しかし、わたしは再びあなたがたに会います。そして、あなたがたの心は喜びに満たされます。その喜びをあなたがたから奪い去る者はありません。'),
('JPN', '约翰福音', 43, 16, 23, 'その日には、あなたがたはわたしに何も尋ねません。まことに、まことに、あなたがたに言います。わたしの名によって父に求めるものは何でも、父はあなたがたに与えてくださいます。'),
('JPN', '约翰福音', 43, 16, 24, '今まで、あなたがたは、わたしの名によって何も求めたことがありません。求めなさい。そうすれば受けます。あなたがたの喜びが満ちあふれるようになるためです。'),
('JPN', '约翰福音', 43, 16, 25, 'わたしはこれらのことを、あなたがたにたとえで話しました。もはやたとえで話すのではなく、はっきりと父について伝える時が来ます。'),
('JPN', '约翰福音', 43, 16, 26, 'その日には、あなたがたはわたしの名によって求めます。あなたがたに代わってわたしが父に願う、と言うのではありません。'),
('JPN', '约翰福音', 43, 16, 27, '父ご自身があなたがたを愛しておられるのです。あなたがたがわたしを愛し、わたしが神のもとから出て来たことを信じたからです。'),
('JPN', '约翰福音', 43, 16, 28, 'わたしは父のもとから出て、世に来ましたが、再び世を去って、父のもとに行きます。」'),
('JPN', '约翰福音', 43, 16, 29, '弟子たちは言った。「本当に、今あなたははっきりとお話しくださり、何もたとえでは語られません。'),
('JPN', '约翰福音', 43, 16, 30, 'あなたがすべてをご存じであり、だれかがあなたにお尋ねする必要もないことが、今、分かりました。ですから私たちは、あなたが神から来られたことを信じます。」'),
('JPN', '约翰福音', 43, 16, 31, 'イエスは彼らに答えられた。「あなたがたは今、信じているのですか。'),
('JPN', '约翰福音', 43, 16, 32, '見なさい。その時が来ます。いや、すでに来ています。あなたがたはそれぞれ散らされて自分のところに帰り、わたしを一人残します。しかし、父がわたしとともにおられるので、わたしは一人ではありません。'),
('JPN', '约翰福音', 43, 16, 33, 'これらのことをあなたがたに話したのは、あなたがたがわたしにあって平安を得るためです。世にあっては苦難があります。しかし、勇気を出しなさい。わたしはすでに世に勝ちました。」'),
('JPN', '约翰福音', 43, 17, 1, 'これらのことを話してから、イエスは目を天に向けて言われた。「父よ、時が来ました。子があなたの栄光を現すために、子の栄光を現してください。'),
('JPN', '约翰福音', 43, 17, 2, 'あなたは子に、すべての人を支配する権威を下さいました。それは、あなたが下さったすべての人に、子が永遠のいのちを与えるためです。'),
('JPN', '约翰福音', 43, 17, 3, '永遠のいのちとは、唯一のまことの神であるあなたと、あなたが遣わされたイエス・キリストを知ることです。'),
('JPN', '约翰福音', 43, 17, 4, 'わたしが行うようにと、あなたが与えてくださったわざを成し遂げて、わたしは地上であなたの栄光を現しました。'),
('JPN', '约翰福音', 43, 17, 5, '父よ、今、あなたご自身が御前でわたしの栄光を現してください。世界が始まる前に一緒に持っていたあの栄光を。'),
('JPN', '约翰福音', 43, 17, 6, 'あなたが世から選び出して与えてくださった人たちに、わたしはあなたの御名を現しました。彼らはあなたのものでしたが、あなたはわたしに委ねてくださいました。そして彼らはあなたのみことばを守りました。'),
('JPN', '约翰福音', 43, 17, 7, 'あなたがわたしに下さったものはすべて、あなたから出ていることを、今彼らは知っています。'),
('JPN', '约翰福音', 43, 17, 8, 'あなたがわたしに下さったみことばを、わたしが彼らに与えたからです。彼らはそれを受け入れ、わたしがあなたのもとから出て来たことを本当に知り、あなたがわたしを遣わされたことを信じました。'),
('JPN', '约翰福音', 43, 17, 9, 'わたしは彼らのためにお願いします。世のためにではなく、あなたがわたしに下さった人たちのためにお願いします。彼らはあなたのものですから。'),
('JPN', '约翰福音', 43, 17, 10, 'わたしのものはすべてあなたのもの、あなたのものはわたしのものです。わたしは彼らによって栄光を受けました。'),
('JPN', '约翰福音', 43, 17, 11, 'わたしはもう世にいなくなります。彼らは世にいますが、わたしはあなたのもとに参ります。聖なる父よ、わたしに下さったあなたの御名によって、彼らをお守りください。わたしたちと同じように、彼らが一つになるためです。'),
('JPN', '约翰福音', 43, 17, 12, '彼らとともにいたとき、わたしはあなたが下さったあなたの御名によって、彼らを守りました。わたしが彼らを保ったので、彼らのうちだれも滅びた者はなく、ただ滅びの子が滅びました。それは、聖書が成就するためでした。'),
('JPN', '约翰福音', 43, 17, 13, 'わたしは今、あなたのもとに参ります。世にあってこれらのことを話しているのは、わたしの喜びが彼らのうちに満ちあふれるためです。'),
('JPN', '约翰福音', 43, 17, 14, 'わたしは彼らにあなたのみことばを与えました。世は彼らを憎みました。わたしがこの世のものでないように、彼らもこの世のものではないからです。'),
('JPN', '约翰福音', 43, 17, 15, 'わたしがお願いすることは、あなたが彼らをこの世から取り去ることではなく、悪い者から守ってくださることです。'),
('JPN', '约翰福音', 43, 17, 16, 'わたしがこの世のものでないように、彼らもこの世のものではありません。'),
('JPN', '约翰福音', 43, 17, 17, '真理によって彼らを聖別してください。あなたのみことばは真理です。'),
('JPN', '约翰福音', 43, 17, 18, 'あなたがわたしを世に遣わされたように、わたしも彼らを世に遣わしました。'),
('JPN', '约翰福音', 43, 17, 19, 'わたしは彼らのため、わたし自身を聖別します。彼ら自身も真理によって聖別されるためです。'),
('JPN', '约翰福音', 43, 17, 20, 'わたしは、ただこの人々のためだけでなく、彼らのことばによってわたしを信じる人々のためにも、お願いします。'),
('JPN', '约翰福音', 43, 17, 21, '父よ。あなたがわたしのうちにおられ、わたしがあなたのうちにいるように、すべての人を一つにしてください。彼らもわたしたちのうちにいるようにしてください。あなたがわたしを遣わされたことを、世が信じるようになるためです。'),
('JPN', '约翰福音', 43, 17, 22, 'またわたしは、あなたが下さった栄光を彼らに与えました。わたしたちが一つであるように、彼らも一つになるためです。'),
('JPN', '约翰福音', 43, 17, 23, 'わたしは彼らのうちにいて、あなたはわたしのうちにおられます。彼らが完全に一つになるためです。また、あなたがわたしを遣わされたことと、わたしを愛されたように彼らも愛されたことを、世が知るためです。'),
('JPN', '约翰福音', 43, 17, 24, '父よ。わたしに下さったものについてお願いします。わたしがいるところに、彼らもわたしとともにいるようにしてください。わたしの栄光を、彼らが見るためです。世界の基が据えられる前からわたしを愛されたゆえに、あなたがわたしに下さった栄光を。'),
('JPN', '约翰福音', 43, 17, 25, '正しい父よ。この世はあなたを知りませんが、わたしはあなたを知っています。また、この人々は、あなたがわたしを遣わされたことを知っています。'),
('JPN', '约翰福音', 43, 17, 26, 'わたしは彼らにあなたの御名を知らせました。また、これからも知らせます。あなたがわたしを愛してくださった愛が彼らのうちにあり、わたしも彼らのうちにいるようにするためです。」'),
('JPN', '约翰福音', 43, 18, 1, 'これらのことを話してから、イエスは弟子たちとともに、キデロンの谷の向こうに出て行かれた。そこには園があり、イエスと弟子たちは中に入られた。'),
('JPN', '约翰福音', 43, 18, 2, '一方、イエスを裏切ろうとしていたユダもその場所を知っていた。イエスが弟子たちと、たびたびそこに集まっておられたからである。'),
('JPN', '约翰福音', 43, 18, 3, 'それでユダは、一隊の兵士と、祭司長たちやパリサイ人たちから送られた下役たちを連れ、明かりとたいまつと武器を持って、そこにやって来た。'),
('JPN', '约翰福音', 43, 18, 4, 'イエスはご自分に起ころうとしていることをすべて知っておられたので、進み出て、「だれを捜しているのか」と彼らに言われた。'),
('JPN', '约翰福音', 43, 18, 5, '彼らは「ナザレ人イエスを」と答えた。イエスは彼らに「わたしがそれだ」と言われた。イエスを裏切ろうとしていたユダも彼らと一緒に立っていた。'),
('JPN', '约翰福音', 43, 18, 6, 'イエスが彼らに「わたしがそれだ」と言われたとき、彼らは後ずさりし、地に倒れた。'),
('JPN', '约翰福音', 43, 18, 7, 'イエスがもう一度、「だれを捜しているのか」と問われると、彼らは「ナザレ人イエスを」と言った。'),
('JPN', '约翰福音', 43, 18, 8, 'イエスは答えられた。「わたしがそれだ、と言ったではないか。わたしを捜しているのなら、この人たちは去らせなさい。」'),
('JPN', '约翰福音', 43, 18, 9, 'これは、「あなたが下さった者たちのうち、わたしは一人も失わなかった」と、イエスが言われたことばが成就するためであった。'),
('JPN', '约翰福音', 43, 18, 10, 'シモン・ペテロは剣を持っていたので、それを抜いて、大祭司のしもべに切りかかり、右の耳を切り落とした。そのしもべの名はマルコスであった。'),
('JPN', '约翰福音', 43, 18, 11, 'イエスはペテロに言われた。「剣をさやに収めなさい。父がわたしに下さった杯を飲まずにいられるだろうか。」'),
('JPN', '约翰福音', 43, 18, 12, '一隊の兵士と千人隊長、それにユダヤ人の下役たちは、イエスを捕らえて縛り、'),
('JPN', '约翰福音', 43, 18, 13, 'まずアンナスのところに連れて行った。彼が、その年の大祭司であったカヤパのしゅうとだったからである。'),
('JPN', '约翰福音', 43, 18, 14, 'カヤパは、一人の人が民に代わって死ぬほうが得策である、とユダヤ人に助言した人である。'),
('JPN', '约翰福音', 43, 18, 15, 'シモン・ペテロともう一人の弟子はイエスについて行った。この弟子は大祭司の知り合いだったので、イエスと一緒に大祭司の家の中庭に入ったが、'),
('JPN', '约翰福音', 43, 18, 16, 'ペテロは外で門のところに立っていた。それで、大祭司の知り合いだったもう一人の弟子が出て来て、門番の女に話し、ペテロを中に入れた。'),
('JPN', '约翰福音', 43, 18, 17, 'すると、門番をしていた召使いの女がペテロに、「あなたも、あの人の弟子ではないでしょうね」と言った。ペテロは「違う」と言った。'),
('JPN', '约翰福音', 43, 18, 18, 'しもべたちや下役たちは、寒かったので炭火を起こし、立って暖まっていた。ペテロも彼らと一緒に立って暖まっていた。'),
('JPN', '约翰福音', 43, 18, 19, '大祭司はイエスに、弟子たちのことや教えについて尋問した。'),
('JPN', '约翰福音', 43, 18, 20, 'イエスは彼に答えられた。「わたしは世に対して公然と話しました。いつでも、ユダヤ人がみな集まる会堂や宮で教えました。何も隠れて話してはいません。'),
('JPN', '约翰福音', 43, 18, 21, 'なぜ、わたしに尋ねるのですか。わたしが人々に何を話したかは、それを聞いた人たちに尋ねなさい。その人たちなら、わたしが話したことを知っています。」'),
('JPN', '约翰福音', 43, 18, 22, 'イエスがこう言われたとき、そばに立っていた下役の一人が、「大祭司にそのような答え方をするのか」と言って、平手でイエスを打った。'),
('JPN', '约翰福音', 43, 18, 23, 'イエスは彼に答えられた。「わたしの言ったことが悪いのなら、悪いという証拠を示しなさい。正しいのなら、なぜ、わたしを打つのですか。」'),
('JPN', '约翰福音', 43, 18, 24, 'アンナスは、イエスを縛ったまま大祭司カヤパのところに送った。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '约翰福音', 43, 18, 25, 'さて、シモン・ペテロは立ったまま暖まっていた。すると、人々は彼に「あなたもあの人の弟子ではないだろうね」と言った。ペテロは否定して、「弟子ではない」と言った。'),
('JPN', '约翰福音', 43, 18, 26, '大祭司のしもべの一人で、ペテロに耳を切り落とされた人の親類が言った。「あなたが園であの人と一緒にいるのを見たと思うが。」'),
('JPN', '约翰福音', 43, 18, 27, 'ペテロは再び否定した。すると、すぐに鶏が鳴いた。'),
('JPN', '约翰福音', 43, 18, 28, 'さて、彼らはイエスをカヤパのもとから総督官邸に連れて行った。明け方のことであった。彼らは、過越の食事が食べられるようにするため、汚れを避けようとして、官邸の中には入らなかった。'),
('JPN', '约翰福音', 43, 18, 29, 'それで、ピラトは外に出て、彼らのところに来て言った。「この人に対して何を告発するのか。」'),
('JPN', '约翰福音', 43, 18, 30, '彼らは答えた。「この人が悪いことをしていなければ、あなたに引き渡したりはしません。」'),
('JPN', '约翰福音', 43, 18, 31, 'そこで、ピラトは言った。「おまえたちがこの人を引き取り、自分たちの律法にしたがってさばくがよい。」ユダヤ人たちは言った。「私たちはだれも死刑にすることが許されていません。」'),
('JPN', '约翰福音', 43, 18, 32, 'これは、イエスがどのような死に方をするかを示して言われたことばが、成就するためであった。'),
('JPN', '约翰福音', 43, 18, 33, 'そこで、ピラトは再び総督官邸に入り、イエスを呼んで言った。「あなたはユダヤ人の王なのか。」'),
('JPN', '约翰福音', 43, 18, 34, 'イエスは答えられた。「あなたは、そのことを自分で言っているのですか。それともわたしのことを、ほかの人々があなたに話したのですか。」'),
('JPN', '约翰福音', 43, 18, 35, 'ピラトは答えた。「私はユダヤ人なのか。あなたの同胞と祭司長たちが、あなたを私に引き渡したのだ。あなたは何をしたのか。」'),
('JPN', '约翰福音', 43, 18, 36, 'イエスは答えられた。「わたしの国はこの世のものではありません。もしこの世のものであったら、わたしのしもべたちが、わたしをユダヤ人に渡さないように戦ったでしょう。しかし、事実、わたしの国はこの世のものではありません。」'),
('JPN', '约翰福音', 43, 18, 37, 'そこで、ピラトはイエスに言った。「それでは、あなたは王なのか。」イエスは答えられた。「わたしが王であることは、あなたの言うとおりです。わたしは、真理について証しするために生まれ、そのために世に来ました。真理に属する者はみな、わたしの声に聞き従います。」'),
('JPN', '约翰福音', 43, 18, 38, 'ピラトはイエスに言った。「真理とは何なのか。」こう言ってから、再びユダヤ人たちのところに出て行って、彼らに言った。「私はあの人に何の罪も認めない。'),
('JPN', '约翰福音', 43, 18, 39, '過越の祭りでは、だれか一人をおまえたちのために釈放する慣わしがある。おまえたちは、ユダヤ人の王を釈放することを望むか。」'),
('JPN', '约翰福音', 43, 18, 40, 'すると、彼らは再び大声をあげて、「その人ではなく、バラバを」と言った。バラバは強盗であった。'),
('JPN', '约翰福音', 43, 19, 1, 'それでピラトは、イエスを捕らえてむちで打った。'),
('JPN', '约翰福音', 43, 19, 2, '兵士たちは、茨で冠を編んでイエスの頭にかぶらせ、紫色の衣を着せた。'),
('JPN', '约翰福音', 43, 19, 3, '彼らはイエスに近寄り、「ユダヤ人の王様、万歳」と言って、顔を平手でたたいた。'),
('JPN', '约翰福音', 43, 19, 4, 'ピラトは、再び外に出て来て彼らに言った。「さあ、あの人をおまえたちのところに連れて来る。そうすれば、私にはあの人に何の罪も見出せないことが、おまえたちに分かるだろう。」'),
('JPN', '约翰福音', 43, 19, 5, 'イエスは、茨の冠と紫色の衣を着けて、出て来られた。ピラトは彼らに言った。「見よ、この人だ。」'),
('JPN', '约翰福音', 43, 19, 6, '祭司長たちと下役たちはイエスを見ると、「十字架につけろ。十字架につけろ」と叫んだ。ピラトは彼らに言った。「おまえたちがこの人を引き取り、十字架につけよ。私にはこの人に罪を見出せない。」'),
('JPN', '约翰福音', 43, 19, 7, 'ユダヤ人たちは彼に答えた。「私たちには律法があります。その律法によれば、この人は死に当たります。自分を神の子としたのですから。」'),
('JPN', '约翰福音', 43, 19, 8, 'ピラトは、このことばを聞くと、ますます恐れを覚えた。'),
('JPN', '约翰福音', 43, 19, 9, 'そして、再び総督官邸に入り、イエスに「あなたはどこから来たのか」と言った。しかし、イエスは何もお答えにならなかった。'),
('JPN', '约翰福音', 43, 19, 10, 'そこで、ピラトはイエスに言った。「私に話さないのか。私にはあなたを釈放する権威があり、十字架につける権威もあることを、知らないのか。」'),
('JPN', '约翰福音', 43, 19, 11, 'イエスは答えられた。「上から与えられていなければ、あなたにはわたしに対して何の権威もありません。ですから、わたしをあなたに引き渡した者に、もっと大きな罪があるのです。」'),
('JPN', '约翰福音', 43, 19, 12, 'ピラトはイエスを釈放しようと努力したが、ユダヤ人たちは激しく叫んだ。「この人を釈放するのなら、あなたはカエサルの友ではありません。自分を王とする者はみな、カエサルに背いています。」'),
('JPN', '约翰福音', 43, 19, 13, 'ピラトは、これらのことばを聞いて、イエスを外に連れ出し、敷石、ヘブル語でガバタと呼ばれる場所で、裁判の席に着いた。'),
('JPN', '约翰福音', 43, 19, 14, 'その日は過越の備え日で、時はおよそ第六の時であった。ピラトはユダヤ人たちに言った。「見よ、おまえたちの王だ。」'),
('JPN', '约翰福音', 43, 19, 15, '彼らは叫んだ。「除け、除け、十字架につけろ。」ピラトは言った。「おまえたちの王を私が十字架につけるのか。」祭司長たちは答えた。「カエサルのほかには、私たちに王はありません。」'),
('JPN', '约翰福音', 43, 19, 16, 'ピラトは、イエスを十字架につけるため彼らに引き渡した。彼らはイエスを引き取った。'),
('JPN', '约翰福音', 43, 19, 17, 'イエスは自分で十字架を負って、「どくろの場所」と呼ばれるところに出て行かれた。そこは、ヘブル語ではゴルゴタと呼ばれている。'),
('JPN', '约翰福音', 43, 19, 18, '彼らはその場所でイエスを十字架につけた。また、イエスを真ん中にして、こちら側とあちら側に、ほかの二人の者を一緒に十字架につけた。'),
('JPN', '约翰福音', 43, 19, 19, 'ピラトは罪状書きも書いて、十字架の上に掲げた。それには「ユダヤ人の王、ナザレ人イエス」と書かれていた。'),
('JPN', '约翰福音', 43, 19, 20, 'イエスが十字架につけられた場所は都に近かったので、多くのユダヤ人がこの罪状書きを読んだ。それはヘブル語、ラテン語、ギリシア語で書かれていた。'),
('JPN', '约翰福音', 43, 19, 21, 'そこで、ユダヤ人の祭司長たちはピラトに、「ユダヤ人の王と書かないで、この者はユダヤ人の王と自称したと書いてください」と言った。'),
('JPN', '约翰福音', 43, 19, 22, 'ピラトは答えた。「私が書いたものは、書いたままにしておけ。」'),
('JPN', '约翰福音', 43, 19, 23, 'さて、兵士たちはイエスを十字架につけると、その衣を取って四つに分け、各自に一つずつ渡るようにした。また下着も取ったが、それは上から全部一つに織った、縫い目のないものであった。'),
('JPN', '约翰福音', 43, 19, 24, 'そのため、彼らは互いに言った。「これは裂かないで、だれの物になるか、くじを引こう。」これは、「彼らは私の衣服を分け合い、私の衣をくじ引きにします」とある聖書が成就するためであった。それで、兵士たちはそのように行った。'),
('JPN', '约翰福音', 43, 19, 25, 'イエスの十字架のそばには、イエスの母とその姉妹、そしてクロパの妻マリアとマグダラのマリアが立っていた。'),
('JPN', '约翰福音', 43, 19, 26, 'イエスは、母とそばに立っている愛する弟子を見て、母に「女の方、ご覧なさい。あなたの息子です」と言われた。'),
('JPN', '约翰福音', 43, 19, 27, 'それから、その弟子に「ご覧なさい。あなたの母です」と言われた。その時から、この弟子は彼女を自分のところに引き取った。'),
('JPN', '约翰福音', 43, 19, 28, 'それから、イエスはすべてのことが完了したのを知ると、聖書が成就するために、「わたしは渇く」と言われた。'),
('JPN', '约翰福音', 43, 19, 29, '酸いぶどう酒がいっぱい入った器がそこに置いてあったので、兵士たちは、酸いぶどう酒を含んだ海綿をヒソプの枝に付けて、イエスの口もとに差し出した。'),
('JPN', '约翰福音', 43, 19, 30, 'イエスは酸いぶどう酒を受けると、「完了した」と言われた。そして、頭を垂れて霊をお渡しになった。'),
('JPN', '约翰福音', 43, 19, 31, 'その日は備え日であり、翌日の安息日は大いなる日であったので、ユダヤ人たちは、安息日に死体が十字架の上に残らないようにするため、その脚を折って取り降ろしてほしいとピラトに願い出た。'),
('JPN', '约翰福音', 43, 19, 32, 'そこで、兵士たちが来て、イエスと一緒に十字架につけられた一人目の者と、もう一人の者の脚を折った。'),
('JPN', '约翰福音', 43, 19, 33, 'イエスのところに来ると、すでに死んでいるのが分かったので、その脚を折らなかった。'),
('JPN', '约翰福音', 43, 19, 34, 'しかし兵士の一人は、イエスの脇腹を槍で突き刺した。すると、すぐに血と水が出て来た。'),
('JPN', '约翰福音', 43, 19, 35, 'これを目撃した者が証ししている。それは、あなたがたも信じるようになるためである。その証しは真実であり、その人は自分が真実を話していることを知っている。'),
('JPN', '约翰福音', 43, 19, 36, 'これらのことが起こったのは、「彼の骨は、一つも折られることはない」とある聖書が成就するためであり、'),
('JPN', '约翰福音', 43, 19, 37, 'また聖書の別のところで、「彼らは自分たちが突き刺した方を仰ぎ見る」と言われているからである。'),
('JPN', '约翰福音', 43, 19, 38, 'その後で、イエスの弟子であったが、ユダヤ人を恐れてそれを隠していたアリマタヤのヨセフが、イエスのからだを取り降ろすことをピラトに願い出た。ピラトは許可を与えた。そこで彼はやって来て、イエスのからだを取り降ろした。'),
('JPN', '约翰福音', 43, 19, 39, '以前、夜イエスのところに来たニコデモも、没薬と沈香を混ぜ合わせたものを、百リトラほど持ってやって来た。'),
('JPN', '约翰福音', 43, 19, 40, '彼らはイエスのからだを取り、ユダヤ人の埋葬の習慣にしたがって、香料と一緒に亜麻布で巻いた。'),
('JPN', '约翰福音', 43, 19, 41, 'イエスが十字架につけられた場所には園があり、そこに、まだだれも葬られたことのない新しい墓があった。'),
('JPN', '约翰福音', 43, 19, 42, 'その日はユダヤ人の備え日であり、その墓が近かったので、彼らはそこにイエスを納めた。'),
('JPN', '约翰福音', 43, 20, 1, 'さて、週の初めの日、朝早くまだ暗いうちに、マグダラのマリアは墓にやって来て、墓から石が取りのけられているのを見た。'),
('JPN', '约翰福音', 43, 20, 2, 'それで、走って、シモン・ペテロと、イエスが愛されたもう一人の弟子のところに行って、こう言った。「だれかが墓から主を取って行きました。どこに主を置いたのか、私たちには分かりません。」'),
('JPN', '约翰福音', 43, 20, 3, 'そこで、ペテロともう一人の弟子は外に出て、墓へ行った。'),
('JPN', '约翰福音', 43, 20, 4, '二人は一緒に走ったが、もう一人の弟子がペテロよりも速かったので、先に墓に着いた。'),
('JPN', '约翰福音', 43, 20, 5, 'そして、身をかがめると、亜麻布が置いてあるのが見えたが、中に入らなかった。'),
('JPN', '约翰福音', 43, 20, 6, '彼に続いてシモン・ペテロも来て、墓に入り、亜麻布が置いてあるのを見た。'),
('JPN', '约翰福音', 43, 20, 7, 'イエスの頭を包んでいた布は亜麻布と一緒にはなく、離れたところに丸めてあった。'),
('JPN', '约翰福音', 43, 20, 8, 'そのとき、先に墓に着いたもう一人の弟子も入って来た。そして見て、信じた。'),
('JPN', '约翰福音', 43, 20, 9, '彼らは、イエスが死人の中からよみがえらなければならないという聖書を、まだ理解していなかった。'),
('JPN', '约翰福音', 43, 20, 10, 'それで、弟子たちは再び自分たちのところに帰って行った。'),
('JPN', '约翰福音', 43, 20, 11, '一方、マリアは墓の外にたたずんで泣いていた。そして、泣きながら、からだをかがめて墓の中をのぞき込んだ。'),
('JPN', '约翰福音', 43, 20, 12, 'すると、白い衣を着た二人の御使いが、イエスのからだが置かれていた場所に、一人は頭のところに、一人は足のところに座っているのが見えた。'),
('JPN', '约翰福音', 43, 20, 13, '彼らはマリアに言った。「女の方、なぜ泣いているのですか。」彼女は言った。「だれかが私の主を取って行きました。どこに主を置いたのか、私には分かりません。」'),
('JPN', '约翰福音', 43, 20, 14, '彼女はこう言ってから、うしろを振り向いた。そして、イエスが立っておられるのを見たが、それがイエスであることが分からなかった。'),
('JPN', '约翰福音', 43, 20, 15, 'イエスは彼女に言われた。「なぜ泣いているのですか。だれを捜しているのですか。」彼女は、彼が園の管理人だと思って言った。「あなたがあの方を運び去ったのでしたら、どこに置いたのか教えてください。私が引き取ります。」'),
('JPN', '约翰福音', 43, 20, 16, 'イエスは彼女に言われた。「マリア。」彼女は振り向いて、ヘブル語で「ラボニ」、すなわち「先生」とイエスに言った。'),
('JPN', '约翰福音', 43, 20, 17, 'イエスは彼女に言われた。「わたしにすがりついていてはいけません。わたしはまだ父のもとに上っていないのです。わたしの兄弟たちのところに行って、『わたしは、わたしの父であり、あなたがたの父である方、わたしの神であり、あなたがたの神である方のもとに上る』と伝えなさい。」'),
('JPN', '约翰福音', 43, 20, 18, 'マグダラのマリアは行って、弟子たちに「私は主を見ました」と言い、主が自分にこれらのことを話されたと伝えた。'),
('JPN', '约翰福音', 43, 20, 19, 'その日、すなわち週の初めの日の夕方、弟子たちがいたところでは、ユダヤ人を恐れて戸に鍵がかけられていた。すると、イエスが来て彼らの真ん中に立ち、こう言われた。「平安があなたがたにあるように。」'),
('JPN', '约翰福音', 43, 20, 20, 'こう言って、イエスは手と脇腹を彼らに示された。弟子たちは主を見て喜んだ。'),
('JPN', '约翰福音', 43, 20, 21, 'イエスは再び彼らに言われた。「平安があなたがたにあるように。父がわたしを遣わされたように、わたしもあなたがたを遣わします。」'),
('JPN', '约翰福音', 43, 20, 22, 'こう言ってから、彼らに息を吹きかけて言われた。「聖霊を受けなさい。'),
('JPN', '约翰福音', 43, 20, 23, 'あなたがたがだれかの罪を赦すなら、その人の罪は赦されます。赦さずに残すなら、そのまま残ります。」'),
('JPN', '约翰福音', 43, 20, 24, '十二弟子の一人で、デドモと呼ばれるトマスは、イエスが来られたとき、彼らと一緒にいなかった。'),
('JPN', '约翰福音', 43, 20, 25, 'そこで、ほかの弟子たちは彼に「私たちは主を見た」と言った。しかし、トマスは彼らに「私は、その手に釘の跡を見て、釘の跡に指を入れ、その脇腹に手を入れてみなければ、決して信じません」と言った。'),
('JPN', '约翰福音', 43, 20, 26, '八日後、弟子たちは再び家の中におり、トマスも彼らと一緒にいた。戸には鍵がかけられていたが、イエスがやって来て、彼らの真ん中に立ち、「平安があなたがたにあるように」と言われた。'),
('JPN', '约翰福音', 43, 20, 27, 'それから、トマスに言われた。「あなたの指をここに当てて、わたしの手を見なさい。手を伸ばして、わたしの脇腹に入れなさい。信じない者ではなく、信じる者になりなさい。」'),
('JPN', '约翰福音', 43, 20, 28, 'トマスはイエスに答えた。「私の主、私の神よ。」'),
('JPN', '约翰福音', 43, 20, 29, 'イエスは彼に言われた。「あなたはわたしを見たから信じたのですか。見ないで信じる人たちは幸いです。」'),
('JPN', '约翰福音', 43, 20, 30, 'イエスは弟子たちの前で、ほかにも多くのしるしを行われたが、それらはこの書には書かれていない。'),
('JPN', '约翰福音', 43, 20, 31, 'これらのことが書かれたのは、イエスが神の子キリストであることを、あなたがたが信じるためであり、また信じて、イエスの名によっていのちを得るためである。'),
('JPN', '约翰福音', 43, 21, 1, 'その後、イエスはティベリア湖畔で、再び弟子たちにご自分を現された。現された次第はこうであった。'),
('JPN', '约翰福音', 43, 21, 2, 'シモン・ペテロ、デドモと呼ばれるトマス、ガリラヤのカナ出身のナタナエル、ゼベダイの子たち、そして、ほかに二人の弟子が同じところにいた。'),
('JPN', '约翰福音', 43, 21, 3, 'シモン・ペテロが彼らに「私は漁に行く」と言った。すると、彼らは「私たちも一緒に行く」と言った。彼らは出て行って、小舟に乗り込んだが、その夜は何も捕れなかった。'),
('JPN', '约翰福音', 43, 21, 4, '夜が明け始めていたころ、イエスは岸辺に立たれた。けれども弟子たちには、イエスであることが分からなかった。'),
('JPN', '约翰福音', 43, 21, 5, 'イエスは彼らに言われた。「子どもたちよ、食べる魚がありませんね。」彼らは答えた。「ありません。」'),
('JPN', '约翰福音', 43, 21, 6, 'イエスは彼らに言われた。「舟の右側に網を打ちなさい。そうすれば捕れます。」そこで、彼らは網を打った。すると、おびただしい数の魚のために、もはや彼らには網を引き上げることができなかった。'),
('JPN', '约翰福音', 43, 21, 7, 'それで、イエスが愛されたあの弟子が、ペテロに「主だ」と言った。シモン・ペテロは「主だ」と聞くと、裸に近かったので上着をまとい、湖に飛び込んだ。'),
('JPN', '约翰福音', 43, 21, 8, '一方、ほかの弟子たちは、魚の入った網を引いて小舟で戻って行った。陸地から遠くなく、二百ペキスほどの距離だったからである。'),
('JPN', '约翰福音', 43, 21, 9, 'こうして彼らが陸地に上がると、そこには炭火がおこされていて、その上には魚があり、またパンがあるのが見えた。'),
('JPN', '约翰福音', 43, 21, 10, 'イエスは彼らに「今捕った魚を何匹か持って来なさい」と言われた。'),
('JPN', '约翰福音', 43, 21, 11, 'シモン・ペテロは舟に乗って、網を陸地に引き上げた。網は百五十三匹の大きな魚でいっぱいであった。それほど多かったのに、網は破れていなかった。'),
('JPN', '约翰福音', 43, 21, 12, 'イエスは彼らに言われた。「さあ、朝の食事をしなさい。」弟子たちは、主であることを知っていたので、だれも「あなたはどなたですか」とあえて尋ねはしなかった。'),
('JPN', '约翰福音', 43, 21, 13, 'イエスは来てパンを取り、彼らにお与えになった。また、魚も同じようにされた。'),
('JPN', '约翰福音', 43, 21, 14, 'イエスが死人の中からよみがえって、弟子たちにご自分を現されたのは、これですでに三度目である。'),
('JPN', '约翰福音', 43, 21, 15, '彼らが食事を済ませたとき、イエスはシモン・ペテロに言われた。「ヨハネの子シモン。あなたは、この人たちが愛する以上に、わたしを愛していますか。」ペテロは答えた。「はい、主よ。私があなたを愛していることは、あなたがご存じです。」イエスは彼に言われた。「わたしの子羊を飼いなさい。」'),
('JPN', '约翰福音', 43, 21, 16, 'イエスは再び彼に「ヨハネの子シモン。あなたはわたしを愛していますか」と言われた。ペテロは答えた。「はい、主よ。私があなたを愛していることは、あなたがご存じです。」イエスは彼に言われた。「わたしの羊を牧しなさい。」'),
('JPN', '约翰福音', 43, 21, 17, 'イエスは三度目もペテロに、「ヨハネの子シモン。あなたはわたしを愛していますか」と言われた。ペテロは、イエスが三度目も「あなたはわたしを愛していますか」と言われたので、心を痛めてイエスに言った。「主よ、あなたはすべてをご存じです。あなたは、私があなたを愛していることを知っておられます。」イエスは彼に言われた。「わたしの羊を飼いなさい。'),
('JPN', '约翰福音', 43, 21, 18, 'まことに、まことに、あなたに言います。あなたは若いときには、自分で帯をして、自分の望むところを歩きました。しかし年をとると、あなたは両手を伸ばし、ほかの人があなたに帯をして、望まないところに連れて行きます。」'),
('JPN', '约翰福音', 43, 21, 19, 'イエスは、ペテロがどのような死に方で神の栄光を現すかを示すために、こう言われたのである。こう話してから、ペテロに言われた。「わたしに従いなさい。」'),
('JPN', '约翰福音', 43, 21, 20, 'ペテロは振り向いて、イエスが愛された弟子がついて来るのを見た。この弟子は、夕食の席でイエスの胸元に寄りかかり、「主よ、あなたを裏切るのはだれですか」と言った者である。'),
('JPN', '约翰福音', 43, 21, 21, 'ペテロは彼を見て、「主よ、この人はどうなのですか」とイエスに言った。'),
('JPN', '约翰福音', 43, 21, 22, 'イエスはペテロに言われた。「わたしが来るときまで彼が生きるように、わたしが望んだとしても、あなたに何の関わりがありますか。あなたは、わたしに従いなさい。」'),
('JPN', '约翰福音', 43, 21, 23, 'それで、その弟子は死なないという話が兄弟たちの間に広まった。しかし、イエスはペテロに、その弟子は死なないと言われたのではなく、「わたしが来るときまで彼が生きるように、わたしが望んだとしても、あなたに何の関わりがありますか」と言われたのである。'),
('JPN', '约翰福音', 43, 21, 24, 'これらのことについて証しし、これらのことを書いた者は、その弟子である。私たちは、彼の証しが真実であることを知っている。'),
('JPN', '约翰福音', 43, 21, 25, 'イエスが行われたことは、ほかにもたくさんある。その一つ一つを書き記すなら、世界もその書かれた書物を収められないと、私は思う。'),
('JPN', '使徒行传', 44, 1, 1, 'テオフィロ様。私は前の書で、イエスが行い始め、また教え始められたすべてのことについて書き記しました。'),
('JPN', '使徒行传', 44, 1, 2, 'それは、お選びになった使徒たちに聖霊によって命じた後、天に上げられた日までのことでした。'),
('JPN', '使徒行传', 44, 1, 3, 'イエスは苦しみを受けた後、数多くの確かな証拠をもって、ご自分が生きていることを使徒たちに示された。四十日にわたって彼らに現れ、神の国のことを語られた。'),
('JPN', '使徒行传', 44, 1, 4, '使徒たちと一緒にいるとき、イエスは彼らにこう命じられた。「エルサレムを離れないで、わたしから聞いた父の約束を待ちなさい。'),
('JPN', '使徒行传', 44, 1, 5, 'ヨハネは水でバプテスマを授けましたが、あなたがたは間もなく、聖霊によるバプテスマを授けられるからです。」'),
('JPN', '使徒行传', 44, 1, 6, 'そこで使徒たちは、一緒に集まったとき、イエスに尋ねた。「主よ。イスラエルのために国を再興してくださるのは、この時なのですか。」'),
('JPN', '使徒行传', 44, 1, 7, 'イエスは彼らに言われた。「いつとか、どんな時とかいうことは、あなたがたの知るところではありません。それは、父がご自分の権威をもって定めておられることです。'),
('JPN', '使徒行传', 44, 1, 8, 'しかし、聖霊があなたがたの上に臨むとき、あなたがたは力を受けます。そして、エルサレム、ユダヤとサマリアの全土、さらに地の果てまで、わたしの証人となります。」'),
('JPN', '使徒行传', 44, 1, 9, 'こう言ってから、イエスは使徒たちが見ている間に上げられた。そして雲がイエスを包み、彼らの目には見えなくなった。'),
('JPN', '使徒行传', 44, 1, 10, 'イエスが上って行かれるとき、使徒たちは天を見つめていた。すると見よ、白い衣を着た二人の人が、彼らのそばに立っていた。'),
('JPN', '使徒行传', 44, 1, 11, 'そしてこう言った。「ガリラヤの人たち、どうして天を見上げて立っているのですか。あなたがたを離れて天に上げられたこのイエスは、天に上って行くのをあなたがたが見たのと同じ有様で、またおいでになります。」'),
('JPN', '使徒行传', 44, 1, 12, 'そこで、使徒たちはオリーブという山からエルサレムに帰った。この山はエルサレムに近く、安息日に歩くことが許される道のりのところにあった。'),
('JPN', '使徒行传', 44, 1, 13, '彼らは町に入ると、泊まっている屋上の部屋に上がった。この人たちは、ペテロとヨハネとヤコブとアンデレ、ピリポとトマス、バルトロマイとマタイ、アルパヨの子ヤコブと熱心党員シモンとヤコブの子ユダであった。'),
('JPN', '使徒行传', 44, 1, 14, '彼らはみな、女たちとイエスの母マリア、およびイエスの兄弟たちとともに、いつも心を一つにして祈っていた。'),
('JPN', '使徒行传', 44, 1, 15, 'そのころ、百二十人ほどの人々が一つになって集まっていたが、ペテロがこれらの兄弟たちの中に立って、こう言った。'),
('JPN', '使徒行传', 44, 1, 16, '「兄弟たち。イエスを捕らえた者たちを手引きしたユダについては、聖霊がダビデの口を通して前もって語った聖書のことばが、成就しなければなりませんでした。'),
('JPN', '使徒行传', 44, 1, 17, 'ユダは私たちの仲間として数えられていて、その務めを割り当てられていました。'),
('JPN', '使徒行传', 44, 1, 18, '（このユダは、不義の報酬で地所を手に入れたが、真っ逆さまに落ちて、からだが真っ二つに裂け、はらわたがすべて飛び出してしまった。'),
('JPN', '使徒行传', 44, 1, 19, 'このことは、エルサレムの全住民に知れ渡り、その地所は彼らの国のことばでアケルダマ、すなわち『血の地所』と呼ばれるようになっていた。）'),
('JPN', '使徒行传', 44, 1, 20, '詩篇にはこう書いてあります。『彼の宿営が荒れ果て、そこから住む者が絶えますように。』また、『彼の務めは、ほかの人が取るように。』'),
('JPN', '使徒行传', 44, 1, 21, 'ですから、主イエスが私たちと一緒に生活しておられた間、'),
('JPN', '使徒行传', 44, 1, 22, 'すなわち、ヨハネのバプテスマから始まって、私たちを離れて天に上げられた日までの間、いつも私たちと行動をともにした人たちの中から、だれか一人が、私たちとともにイエスの復活の証人とならなければなりません。」'),
('JPN', '使徒行传', 44, 1, 23, 'そこで彼らは、バルサバと呼ばれ、別名をユストというヨセフと、マッティアの二人を立てた。'),
('JPN', '使徒行传', 44, 1, 24, 'そしてこう祈った。「すべての人の心をご存じである主よ。この二人のうち、あなたがお選びになった一人をお示しください。'),
('JPN', '使徒行传', 44, 1, 25, 'ユダが自分の場所へ行くために離れてしまった、この奉仕の場、使徒職に就くためです。」'),
('JPN', '使徒行传', 44, 1, 26, 'そして、二人のためにくじを引くと、くじはマッティアに当たったので、彼が十一人の使徒たちの仲間に加えられた。'),
('JPN', '使徒行传', 44, 2, 1, '五旬節の日になって、皆が同じ場所に集まっていた。'),
('JPN', '使徒行传', 44, 2, 2, 'すると天から突然、激しい風が吹いて来たような響きが起こり、彼らが座っていた家全体に響き渡った。'),
('JPN', '使徒行传', 44, 2, 3, 'また、炎のような舌が分かれて現れ、一人ひとりの上にとどまった。'),
('JPN', '使徒行传', 44, 2, 4, 'すると皆が聖霊に満たされ、御霊が語らせるままに、他国のいろいろなことばで話し始めた。'),
('JPN', '使徒行传', 44, 2, 5, 'さて、エルサレムには、敬虔なユダヤ人たちが、天下のあらゆる国々から来て住んでいたが、'),
('JPN', '使徒行传', 44, 2, 6, 'この物音がしたため、大勢の人々が集まって来た。彼らは、それぞれ自分の国のことばで弟子たちが話すのを聞いて、呆気にとられてしまった。'),
('JPN', '使徒行传', 44, 2, 7, '彼らは驚き、不思議に思って言った。「見なさい。話しているこの人たちはみな、ガリラヤの人ではないか。'),
('JPN', '使徒行传', 44, 2, 8, 'それなのに、私たちそれぞれが生まれた国のことばで話を聞くとは、いったいどうしたことか。'),
('JPN', '使徒行传', 44, 2, 9, '私たちは、パルティア人、メディア人、エラム人、またメソポタミア、ユダヤ、カパドキア、ポントスとアジア、'),
('JPN', '使徒行传', 44, 2, 10, 'フリュギアとパンフィリア、エジプト、クレネに近いリビア地方などに住む者、また滞在中のローマ人で、'),
('JPN', '使徒行传', 44, 2, 11, 'ユダヤ人もいれば改宗者もいる。またクレタ人とアラビア人もいる。それなのに、あの人たちが、私たちのことばで神の大きなみわざを語るのを聞くとは。」'),
('JPN', '使徒行传', 44, 2, 12, '人々はみな驚き当惑して、「いったい、これはどうしたことか」と言い合った。'),
('JPN', '使徒行传', 44, 2, 13, 'だが、「彼らは新しいぶどう酒に酔っているのだ」と言って、嘲る者たちもいた。'),
('JPN', '使徒行传', 44, 2, 14, 'ペテロは十一人とともに立って、声を張り上げ、人々に語りかけた。「ユダヤの皆さん、ならびにエルサレムに住むすべての皆さん、あなたがたにこのことを知っていただきたい。私のことばに耳を傾けていただきたい。'),
('JPN', '使徒行传', 44, 2, 15, '今は朝の九時ですから、この人たちは、あなたがたが思っているように酔っているのではありません。'),
('JPN', '使徒行传', 44, 2, 16, 'これは、預言者ヨエルによって語られたことです。'),
('JPN', '使徒行传', 44, 2, 17, '『神は言われる。終わりの日に、わたしはすべての人にわたしの霊を注ぐ。あなたがたの息子や娘は預言し、青年は幻を見、老人は夢を見る。'),
('JPN', '使徒行传', 44, 2, 18, 'その日わたしは、わたしのしもべにも、はしためにも、わたしの霊を注ぐ。すると彼らは預言する。'),
('JPN', '使徒行传', 44, 2, 19, 'また、わたしは上は天に不思議を、下は地にしるしを現れさせる。それは血と火と立ち上る煙。'),
('JPN', '使徒行传', 44, 2, 20, '主の大いなる輝かしい日が来る前に、太陽は闇に、月は血に変わる。'),
('JPN', '使徒行传', 44, 2, 21, 'しかし、主の御名を呼び求める者はみな救われる。』'),
('JPN', '使徒行传', 44, 2, 22, 'イスラエルの皆さん、これらのことばを聞いてください。神はナザレ人イエスによって、あなたがたの間で力あるわざと不思議としるしを行い、それによって、あなたがたにこの方を証しされました。それは、あなたがた自身がご承知のことです。'),
('JPN', '使徒行传', 44, 2, 23, '神が定めた計画と神の予知によって引き渡されたこのイエスを、あなたがたは律法を持たない人々の手によって十字架につけて殺したのです。'),
('JPN', '使徒行传', 44, 2, 24, 'しかし神は、イエスを死の苦しみから解き放って、よみがえらせました。この方が死につながれていることなど、あり得なかったからです。'),
('JPN', '使徒行传', 44, 2, 25, 'ダビデは、この方について次のように言っています。『私はいつも、主を前にしています。主が私の右におられるので、私は揺るがされることはありません。'),
('JPN', '使徒行传', 44, 2, 26, 'それゆえ、私の心は喜び、私の舌は喜びにあふれます。私の身も、望みの中に住まいます。'),
('JPN', '使徒行传', 44, 2, 27, 'あなたは、私のたましいをよみに捨て置かず、あなたにある敬虔な者に滅びをお見せにならないからです。'),
('JPN', '使徒行传', 44, 2, 28, 'あなたは私に、いのちの道を知らせてくださいます。あなたの御前で、私を喜びで満たしてくださいます。』'),
('JPN', '使徒行传', 44, 2, 29, '兄弟たち。父祖ダビデについては、あなたがたに確信をもって言うことができます。彼は死んで葬られ、その墓は今日に至るまで私たちの間にあります。'),
('JPN', '使徒行传', 44, 2, 30, '彼は預言者でしたから、自分の子孫の一人を自分の王座に就かせると、神が誓われたことを知っていました。'),
('JPN', '使徒行传', 44, 2, 31, 'それで、後のことを予見し、キリストの復活について、『彼はよみに捨て置かれず、そのからだは朽ちて滅びることがない』と語ったのです。'),
('JPN', '使徒行传', 44, 2, 32, 'このイエスを、神はよみがえらせました。私たちはみな、そのことの証人です。'),
('JPN', '使徒行传', 44, 2, 33, 'ですから、神の右に上げられたイエスが、約束された聖霊を御父から受けて、今あなたがたが目にし、耳にしている聖霊を注いでくださったのです。'),
('JPN', '使徒行传', 44, 2, 34, 'ダビデが天に上ったのではありません。彼自身こう言っています。『主は、私の主に言われた。あなたは、わたしの右の座に着いていなさい。'),
('JPN', '使徒行传', 44, 2, 35, 'わたしがあなたの敵をあなたの足台とするまで。』'),
('JPN', '使徒行传', 44, 2, 36, 'ですから、イスラエルの全家は、このことをはっきりと知らなければなりません。神が今や主ともキリストともされたこのイエスを、あなたがたは十字架につけたのです。」'),
('JPN', '使徒行传', 44, 2, 37, '人々はこれを聞いて心を刺され、ペテロとほかの使徒たちに、「兄弟たち、私たちはどうしたらよいでしょうか」と言った。'),
('JPN', '使徒行传', 44, 2, 38, 'そこで、ペテロは彼らに言った。「それぞれ罪を赦していただくために、悔い改めて、イエス・キリストの名によってバプテスマを受けなさい。そうすれば、賜物として聖霊を受けます。'),
('JPN', '使徒行传', 44, 2, 39, 'この約束は、あなたがたに、あなたがたの子どもたちに、そして遠くにいるすべての人々に、すなわち、私たちの神である主が召される人ならだれにでも、与えられているのです。」'),
('JPN', '使徒行传', 44, 2, 40, 'ペテロは、ほかにも多くのことばをもって証しをし、「この曲がった時代から救われなさい」と言って、彼らに勧めた。'),
('JPN', '使徒行传', 44, 2, 41, '彼のことばを受け入れた人々はバプテスマを受けた。その日、三千人ほどが仲間に加えられた。'),
('JPN', '使徒行传', 44, 2, 42, '彼らはいつも、使徒たちの教えを守り、交わりを持ち、パンを裂き、祈りをしていた。'),
('JPN', '使徒行传', 44, 2, 43, 'すべての人に恐れが生じ、使徒たちによって多くの不思議としるしが行われていた。'),
('JPN', '使徒行传', 44, 2, 44, '信者となった人々はみな一つになって、一切の物を共有し、'),
('JPN', '使徒行传', 44, 2, 45, '財産や所有物を売っては、それぞれの必要に応じて、皆に分配していた。'),
('JPN', '使徒行传', 44, 2, 46, 'そして、毎日心を一つにして宮に集まり、家々でパンを裂き、喜びと真心をもって食事をともにし、'),
('JPN', '使徒行传', 44, 2, 47, '神を賛美し、民全体から好意を持たれていた。主は毎日、救われる人々を加えて一つにしてくださった。'),
('JPN', '使徒行传', 44, 3, 1, 'ペテロとヨハネは、午後三時の祈りの時間に宮に上って行った。'),
('JPN', '使徒行传', 44, 3, 2, 'すると、生まれつき足の不自由な人が運ばれて来た。この人は、宮に入る人たちから施しを求めるために、毎日「美しの門」と呼ばれる宮の門に置いてもらっていた。'),
('JPN', '使徒行传', 44, 3, 3, '彼は、ペテロとヨハネが宮に入ろうとするのを見て、施しを求めた。'),
('JPN', '使徒行传', 44, 3, 4, 'ペテロは、ヨハネとともにその人を見つめて、「私たちを見なさい」と言った。'),
('JPN', '使徒行传', 44, 3, 5, '彼は何かもらえると期待して、二人に目を注いだ。'),
('JPN', '使徒行传', 44, 3, 6, 'すると、ペテロは言った。「金銀は私にはない。しかし、私にあるものをあげよう。ナザレのイエス・キリストの名によって立ち上がり、歩きなさい。」'),
('JPN', '使徒行传', 44, 3, 7, 'そして彼の右手を取って立たせた。するとたちまち、彼の足とくるぶしが強くなり、'),
('JPN', '使徒行传', 44, 3, 8, '躍り上がって立ち、歩き出した。そして、歩いたり飛び跳ねたりしながら、神を賛美しつつ二人と一緒に宮に入って行った。'),
('JPN', '使徒行传', 44, 3, 9, '人々はみな、彼が歩きながら神を賛美しているのを見た。'),
('JPN', '使徒行传', 44, 3, 10, 'そしてそれが、宮の美しの門のところで施しを求めて座っていた人だと分かると、彼の身に起こったことに、ものも言えないほど驚いた。'),
('JPN', '使徒行传', 44, 3, 11, 'この人がペテロとヨハネにつきまとっているうちに、非常に驚いた人々がみな、「ソロモンの回廊」と呼ばれる場所にいた彼らのところに、一斉に駆け寄って来た。'),
('JPN', '使徒行传', 44, 3, 12, 'これを見たペテロは、人々に向かって言った。「イスラエルの皆さん、どうしてこのことに驚いているのですか。どうして、私たちが自分の力や敬虔さによって彼を歩かせたかのように、私たちを見つめるのですか。'),
('JPN', '使徒行传', 44, 3, 13, 'アブラハム、イサク、ヤコブの神、すなわち私たちの父祖たちの神は、そのしもべイエスに栄光をお与えになりました。あなたがたはこの方を引き渡し、ピラトが釈放すると決めたのに、その面前でこの方を拒みました。'),
('JPN', '使徒行传', 44, 3, 14, 'あなたがたは、この聖なる正しい方を拒んで、人殺しの男を赦免するように要求し、'),
('JPN', '使徒行传', 44, 3, 15, 'いのちの君を殺したのです。しかし、神はこのイエスを死者の中からよみがえらせました。私たちはそのことの証人です。'),
('JPN', '使徒行传', 44, 3, 16, 'このイエスの名が、その名を信じる信仰のゆえに、あなたがたが今見て知っているこの人を強くしました。イエスによって与えられる信仰が、この人を皆さんの前で、このとおり完全なからだにしたのです。'),
('JPN', '使徒行传', 44, 3, 17, 'さて兄弟たち。あなたがたが、自分たちの指導者たちと同様に、無知のためにあのような行いをしたことを、私は知っています。'),
('JPN', '使徒行传', 44, 3, 18, 'しかし神は、すべての預言者たちの口を通してあらかじめ告げておられたこと、すなわち、キリストの受難をこのように実現されました。'),
('JPN', '使徒行传', 44, 3, 19, 'ですから、悔い改めて神に立ち返りなさい。そうすれば、あなたがたの罪はぬぐい去られます。'),
('JPN', '使徒行传', 44, 3, 20, 'そうして、主の御前から回復の時が来て、あなたがたのためにあらかじめキリストとして定められていたイエスを、主は遣わしてくださいます。'),
('JPN', '使徒行传', 44, 3, 21, 'このイエスは、神が昔からその聖なる預言者たちの口を通して語られた、万物が改まる時まで、天にとどまっていなければなりません。'),
('JPN', '使徒行传', 44, 3, 22, 'モーセはこう言いました。『あなたがたの神、主は、あなたがたの同胞の中から、私のような一人の預言者をあなたがたのために起こされる。彼があなたがたに告げることすべてに聞き従わなければならない。'),
('JPN', '使徒行传', 44, 3, 23, 'その預言者に聞き従わない者はだれでも、自分の民から断ち切られる。』'),
('JPN', '使徒行传', 44, 3, 24, 'また、サムエルをはじめ、彼に続いて語った預言者たちもみな、今の時について告げ知らせました。'),
('JPN', '使徒行传', 44, 3, 25, 'あなたがたは預言者たちの子であり、契約の子です。この契約は、神がアブラハムに『あなたの子孫によって、地のすべての民族は祝福を受けるようになる』と言って、あなたがたの父祖たちと結ばれたものです。'),
('JPN', '使徒行传', 44, 3, 26, '神はまず、そのしもべを立てて、あなたがたに遣わされました。その方が、あなたがた一人ひとりを悪から立ち返らせて、祝福にあずからせてくださるのです。」'),
('JPN', '使徒行传', 44, 4, 1, 'ペテロとヨハネが民に話していると、祭司たち、宮の守衛長、サドカイ人たちが二人のところにやって来た。'),
('JPN', '使徒行传', 44, 4, 2, '彼らは、二人が民を教え、イエスを例にあげて死者の中からの復活を宣べ伝えていることに苛立ち、'),
('JPN', '使徒行传', 44, 4, 3, '二人に手をかけて捕らえた。そして、翌日まで留置することにした。すでに夕方だったからである。'),
('JPN', '使徒行传', 44, 4, 4, 'しかし、話を聞いた人々のうち大勢が信じ、男の数が五千人ほどになった。'),
('JPN', '使徒行传', 44, 4, 5, '翌日、民の指導者たち、長老たち、律法学者たちは、エルサレムに集まった。'),
('JPN', '使徒行传', 44, 4, 6, '大祭司アンナス、カヤパ、ヨハネ、アレクサンドロと、大祭司の一族もみな出席した。'),
('JPN', '使徒行传', 44, 4, 7, '彼らは二人を真ん中に立たせて、「おまえたちは何の権威によって、また、だれの名によってあのようなことをしたのか」と尋問した。'),
('JPN', '使徒行传', 44, 4, 8, 'そのとき、ペテロは聖霊に満たされて、彼らに言った。「民の指導者たち、ならびに長老の方々。'),
('JPN', '使徒行传', 44, 4, 9, '私たちが今日取り調べを受けているのが、一人の病人に対する良いわざと、その人が何によって癒やされたのかということのためなら、'),
('JPN', '使徒行传', 44, 4, 10, '皆さんも、またイスラエルのすべての民も、知っていただきたい。この人が治ってあなたがたの前に立っているのは、あなたがたが十字架につけ、神が死者の中からよみがえらせたナザレ人イエス・キリストの名によることです。'),
('JPN', '使徒行传', 44, 4, 11, '『あなたがた家を建てる者たちに捨てられた石、それが要の石となった』というのは、この方のことです。'),
('JPN', '使徒行传', 44, 4, 12, 'この方以外には、だれによっても救いはありません。天の下でこの御名のほかに、私たちが救われるべき名は人間に与えられていないからです。」'),
('JPN', '使徒行传', 44, 4, 13, '彼らはペテロとヨハネの大胆さを見、また二人が無学な普通の人であるのを知って驚いた。また、二人がイエスとともにいたのだということも分かってきた。'),
('JPN', '使徒行传', 44, 4, 14, 'そして、癒やされた人が二人と一緒に立っているのを見ては、返すことばもなかった。'),
('JPN', '使徒行传', 44, 4, 15, '彼らは二人に議場の外に出るように命じ、協議して言った。'),
('JPN', '使徒行传', 44, 4, 16, '「あの者たちをどうしようか。あの者たちによって著しいしるしが行われたことは、エルサレムのすべての住民に知れ渡っていて、われわれはそれを否定しようもない。'),
('JPN', '使徒行传', 44, 4, 17, 'しかし、これ以上民の間に広まらないように、今後だれにもこの名によって語ってはならない、と彼らを脅しておこう。」'),
('JPN', '使徒行传', 44, 4, 18, 'そこで、彼らは二人を呼んで、イエスの名によって語ることも教えることも、いっさいしてはならないと命じた。'),
('JPN', '使徒行传', 44, 4, 19, 'しかし、ペテロとヨハネは彼らに答えた。「神に聞き従うよりも、あなたがたに聞き従うほうが、神の御前に正しいかどうか、判断してください。'),
('JPN', '使徒行传', 44, 4, 20, '私たちは、自分たちが見たことや聞いたことを話さないわけにはいきません。」'),
('JPN', '使徒行传', 44, 4, 21, 'そこで彼らは、二人をさらに脅したうえで釈放した。それは、皆の者がこの出来事のゆえに神をあがめていたので、人々の手前、二人を罰する術がなかったからである。'),
('JPN', '使徒行传', 44, 4, 22, 'このしるしによって癒やされた人は、四十歳を過ぎていた。'),
('JPN', '使徒行传', 44, 4, 23, 'さて、釈放された二人は仲間のところに行き、祭司長たちや長老たちが彼らに言ったことを残らず報告した。'),
('JPN', '使徒行传', 44, 4, 24, 'これを聞いた人々は心を一つにして、神に向かって声をあげた。「主よ。あなたは天と地と海、またそれらの中のすべてのものを造られた方です。'),
('JPN', '使徒行传', 44, 4, 25, 'あなたは聖霊によって、あなたのしもべであり私たちの父であるダビデの口を通して、こう言われました。『なぜ、異邦人たちは騒ぎ立ち、もろもろの国民はむなしいことを企むのか。'),
('JPN', '使徒行传', 44, 4, 26, '地の王たちは立ち構え、君主たちは相ともに集まるのか、主と、主に油注がれた者に対して。』'),
('JPN', '使徒行传', 44, 4, 27, '事実、ヘロデとポンティオ・ピラトは、異邦人たちやイスラエルの民とともに、あなたが油を注がれた、あなたの聖なるしもべイエスに逆らってこの都に集まり、'),
('JPN', '使徒行传', 44, 4, 28, 'あなたの御手とご計画によって、起こるように前もって定められていたことすべてを行いました。'),
('JPN', '使徒行传', 44, 4, 29, '主よ。今、彼らの脅かしをご覧になって、しもべたちにあなたのみことばを大胆に語らせてください。'),
('JPN', '使徒行传', 44, 4, 30, 'また、御手を伸ばし、あなたの聖なるしもべイエスの名によって、癒やしとしるしと不思議を行わせてください。」'),
('JPN', '使徒行传', 44, 4, 31, '彼らが祈り終えると、集まっていた場所が揺れ動き、一同は聖霊に満たされ、神のことばを大胆に語り出した。'),
('JPN', '使徒行传', 44, 4, 32, 'さて、信じた大勢の人々は心と思いを一つにして、だれ一人自分が所有しているものを自分のものと言わず、すべてを共有していた。'),
('JPN', '使徒行传', 44, 4, 33, '使徒たちは、主イエスの復活を大きな力をもって証しし、大きな恵みが彼ら全員の上にあった。'),
('JPN', '使徒行传', 44, 4, 34, '彼らの中には、一人も乏しい者がいなかった。地所や家を所有している者はみな、それを売り、その代金を持って来て、'),
('JPN', '使徒行传', 44, 4, 35, '使徒たちの足もとに置いた。その金が、必要に応じてそれぞれに分け与えられたのであった。'),
('JPN', '使徒行传', 44, 4, 36, 'キプロス生まれのレビ人で、使徒たちにバルナバ（訳すと、慰めの子）と呼ばれていたヨセフも、'),
('JPN', '使徒行传', 44, 4, 37, '所有していた畑を売り、その代金を持って来て、使徒たちの足もとに置いた。'),
('JPN', '使徒行传', 44, 5, 1, 'ところが、アナニアという人は、妻のサッピラとともに土地を売り、'),
('JPN', '使徒行传', 44, 5, 2, '妻も承知のうえで、代金の一部を自分のために取っておき、一部だけを持って来て、使徒たちの足もとに置いた。'),
('JPN', '使徒行传', 44, 5, 3, 'すると、ペテロは言った。「アナニア。なぜあなたはサタンに心を奪われて聖霊を欺き、地所の代金の一部を自分のために取っておいたのか。'),
('JPN', '使徒行传', 44, 5, 4, '売らないでおけば、あなたのものであり、売った後でも、あなたの自由になったではないか。どうして、このようなことを企んだのか。あなたは人を欺いたのではなく、神を欺いたのだ。」'),
('JPN', '使徒行传', 44, 5, 5, 'このことばを聞くと、アナニアは倒れて息が絶えた。これを聞いたすべての人たちに、大きな恐れが生じた。'),
('JPN', '使徒行传', 44, 5, 6, '若者たちは立ち上がって彼のからだを包み、運び出して葬った。'),
('JPN', '使徒行传', 44, 5, 7, 'さて、三時間ほどたって、アナニアの妻がこの出来事を知らずに入って来た。'),
('JPN', '使徒行传', 44, 5, 8, 'ペテロは彼女に言った。「あなたがたは地所をこの値段で売ったのか。私に言いなさい。」彼女は「はい、その値段です」と言った。'),
('JPN', '使徒行传', 44, 5, 9, 'そこでペテロは彼女に言った。「なぜあなたがたは、心を合わせて主の御霊を試みたのか。見なさい。あなたの夫を葬った人たちの足が戸口まで来ている。彼らがあなたを運び出すことになる。」'),
('JPN', '使徒行传', 44, 5, 10, 'すると、即座に彼女はペテロの足もとに倒れて、息絶えた。入って来た若者たちは、彼女が死んでいるのを見て運び出し、夫のそばに葬った。'),
('JPN', '使徒行传', 44, 5, 11, 'そして、教会全体と、このことを聞いたすべての人たちに、大きな恐れが生じた。'),
('JPN', '使徒行传', 44, 5, 12, 'さて、使徒たちの手により、多くのしるしと不思議が人々の間で行われた。皆は心を一つにしてソロモンの回廊にいた。'),
('JPN', '使徒行传', 44, 5, 13, 'ほかの人たちはだれもあえて彼らの仲間に加わろうとはしなかったが、民は彼らを尊敬していた。'),
('JPN', '使徒行传', 44, 5, 14, 'そして、主を信じる者たちはますます増え、男も女も大勢になった。'),
('JPN', '使徒行传', 44, 5, 15, 'そしてついには、病人を大通りへ運び出し、寝台や寝床の上に寝かせて、ペテロが通りかかるときには、せめてその影だけでも、病人のだれかにかかるようにするほどになった。'),
('JPN', '使徒行传', 44, 5, 16, 'また、エルサレム付近の町々から大勢の人が、病人や、汚れた霊に苦しめられている人々を連れて集まって来た。その人々はみな癒やされた。'),
('JPN', '使徒行传', 44, 5, 17, 'そこで、大祭司とその仲間たち、すなわちサドカイ派の者たちはみな、ねたみに燃えて立ち上がり、'),
('JPN', '使徒行传', 44, 5, 18, '使徒たちに手をかけて捕らえ、彼らを公の留置場に入れた。'),
('JPN', '使徒行传', 44, 5, 19, 'ところが、夜、主の使いが牢の戸を開け、彼らを連れ出し、'),
('JPN', '使徒行传', 44, 5, 20, '「行って宮の中に立ち、人々にこのいのちのことばをすべて語りなさい」と言った。'),
('JPN', '使徒行传', 44, 5, 21, '彼らはこれを聞くと、夜明けごろ宮に入って教え始めた。一方、大祭司とその仲間たちは集まって、最高法院、すなわちイスラエルの子らの全長老会を召集し、使徒たちを引き出して来させるために、人を牢獄に遣わした。'),
('JPN', '使徒行传', 44, 5, 22, 'ところが、下役たちが行ってみると、牢の中に彼らはいなかった。それで引き返して、こう報告した。'),
('JPN', '使徒行传', 44, 5, 23, '「牢獄は完全に鍵がかかっていて、番人たちが戸口に立っていました。しかし、開けてみると、中にはだれもいませんでした。」'),
('JPN', '使徒行传', 44, 5, 24, '宮の守衛長や祭司長たちは、このことばを聞くと、いったいどうなることかと、使徒たちのことで当惑した。'),
('JPN', '使徒行传', 44, 5, 25, 'そこへ、ある人がやって来て、「ご覧ください。あなたがたが牢に入れた者たちが、宮の中に立って人々を教えています」と告げた。'),
('JPN', '使徒行传', 44, 5, 26, 'そこで、宮の守衛長は下役たちと一緒に出て行き、使徒たちを連れて来たが、手荒なことはしなかった。人々に石で打たれるのを恐れたのである。'),
('JPN', '使徒行传', 44, 5, 27, '彼らが使徒たちを連れて来て最高法院の中に立たせると、大祭司は使徒たちを尋問した。'),
('JPN', '使徒行传', 44, 5, 28, '「あの名によって教えてはならないと厳しく命じておいたではないか。それなのに、何ということだ。おまえたちはエルサレム中に自分たちの教えを広めてしまった。そして、あの人の血の責任をわれわれに負わせようとしている。」'),
('JPN', '使徒行传', 44, 5, 29, 'しかし、ペテロと使徒たちは答えた。「人に従うより、神に従うべきです。'),
('JPN', '使徒行传', 44, 5, 30, '私たちの父祖の神は、あなたがたが木にかけて殺したイエスを、よみがえらせました。'),
('JPN', '使徒行传', 44, 5, 31, '神は、イスラエルを悔い改めさせ、罪の赦しを与えるために、このイエスを導き手、また救い主として、ご自分の右に上げられました。'),
('JPN', '使徒行传', 44, 5, 32, '私たちはこれらのことの証人です。神がご自分に従う者たちにお与えになった聖霊も証人です。」'),
('JPN', '使徒行传', 44, 5, 33, 'これを聞いて、彼らは怒り狂い、使徒たちを殺そうと考えた。'),
('JPN', '使徒行传', 44, 5, 34, 'ところが、民全体に尊敬されている律法の教師で、ガマリエルというパリサイ人が議場に立ち、使徒たちをしばらく外に出すように命じ、'),
('JPN', '使徒行传', 44, 5, 35, 'それから議員たちに向かってこう言った。「イスラエルの皆さん、この者たちをどう扱うか、よく気をつけてください。'),
('JPN', '使徒行传', 44, 5, 36, '先ごろテウダが立ち上がって、自分を何か偉い者のように言い、彼に従った男の数が四百人ほどになりました。しかし彼は殺され、従った者たちはみな散らされて、跡形もなくなりました。'),
('JPN', '使徒行传', 44, 5, 37, '彼の後、住民登録の時に、ガリラヤ人のユダが立ち上がり、民をそそのかして反乱を起こしましたが、彼も滅び、彼に従った者たちもみな散らされてしまいました。'),
('JPN', '使徒行传', 44, 5, 38, 'そこで今、私はあなたがたに申し上げたい。この者たちから手を引き、放っておきなさい。もしその計画や行動が人間から出たものなら、自滅するでしょう。'),
('JPN', '使徒行传', 44, 5, 39, 'しかし、もしそれが神から出たものなら、彼らを滅ぼすことはできないでしょう。もしかすると、あなたがたは神に敵対する者になってしまいます。」議員たちは彼の意見に従い、'),
('JPN', '使徒行传', 44, 5, 40, '使徒たちを呼び入れて、むちで打ち、イエスの名によって語ってはならないと命じたうえで、釈放した。'),
('JPN', '使徒行传', 44, 5, 41, '使徒たちは、御名のために辱められるに値する者とされたことを喜びながら、最高法院から出て行った。'),
('JPN', '使徒行传', 44, 5, 42, 'そして毎日、宮や家々でイエスがキリストであると教え、宣べ伝えることをやめなかった。'),
('JPN', '使徒行传', 44, 6, 1, 'そのころ、弟子の数が増えるにつれて、ギリシア語を使うユダヤ人たちから、ヘブル語を使うユダヤ人たちに対して苦情が出た。彼らのうちのやもめたちが、毎日の配給においてなおざりにされていたからである。'),
('JPN', '使徒行传', 44, 6, 2, 'そこで、十二人は弟子たち全員を呼び集めてこう言った。「私たちが神のことばを後回しにして、食卓のことに仕えるのは良くありません。'),
('JPN', '使徒行传', 44, 6, 3, 'そこで、兄弟たち。あなたがたの中から、御霊と知恵に満ちた、評判の良い人たちを七人選びなさい。その人たちにこの務めを任せることにして、'),
('JPN', '使徒行传', 44, 6, 4, '私たちは祈りと、みことばの奉仕に専念します。」'),
('JPN', '使徒行传', 44, 6, 5, 'この提案を一同はみな喜んで受け入れた。そして彼らは、信仰と聖霊に満ちた人ステパノ、およびピリポ、プロコロ、ニカノル、ティモン、パルメナ、そしてアンティオキアの改宗者ニコラオを選び、'),
('JPN', '使徒行传', 44, 6, 6, 'この人たちを使徒たちの前に立たせた。使徒たちは祈って、彼らの上に手を置いた。'),
('JPN', '使徒行传', 44, 6, 7, 'こうして、神のことばはますます広まっていき、エルサレムで弟子の数が非常に増えていった。また、祭司たちが大勢、次々と信仰に入った。'),
('JPN', '使徒行传', 44, 6, 8, 'さて、ステパノは恵みと力に満ち、人々の間で大いなる不思議としるしを行っていた。'),
('JPN', '使徒行传', 44, 6, 9, 'ところが、リベルテンと呼ばれる会堂に属する人々、クレネ人、アレクサンドリア人、またキリキアやアジアから来た人々が立ち上がって、ステパノと議論した。'),
('JPN', '使徒行传', 44, 6, 10, 'しかし、彼が語るときの知恵と御霊に対抗することはできなかった。'),
('JPN', '使徒行传', 44, 6, 11, 'そこで、彼らはある人たちをそそのかして、「私たちは、彼がモーセと神を冒瀆することばを語るのを聞いた」と言わせた。'),
('JPN', '使徒行传', 44, 6, 12, 'また、民衆と長老たちと律法学者たちを扇動し、ステパノを襲って捕らえ、最高法院に引いて行った。'),
('JPN', '使徒行传', 44, 6, 13, 'そして偽りの証人たちを立てて言わせた。「この人は、この聖なる所と律法に逆らうことばを語るのをやめません。'),
('JPN', '使徒行传', 44, 6, 14, '『あのナザレ人イエスは、この聖なる所を壊し、モーセが私たちに伝えた慣習を変える』と彼が言うのを、私たちは聞きました。」'),
('JPN', '使徒行传', 44, 6, 15, '最高法院で席に着いていた人々が、みなステパノに目を注ぐと、彼の顔は御使いの顔のように見えた。'),
('JPN', '使徒行传', 44, 7, 1, '大祭司は、「そのとおりなのか」と尋ねた。'),
('JPN', '使徒行传', 44, 7, 2, 'するとステパノは言った。「兄弟ならびに父である皆さん、聞いてください。私たちの父アブラハムがハランに住む以前、まだメソポタミアにいたとき、栄光の神が彼に現れ、'),
('JPN', '使徒行传', 44, 7, 3, '『あなたの土地、あなたの親族を離れて、わたしが示す地へ行きなさい』と言われました。'),
('JPN', '使徒行传', 44, 7, 4, 'そこで、アブラハムはカルデア人の地を出て、ハランに住みました。そして父の死後、神はそこから彼を、今あなたがたが住んでいるこの地に移されましたが、'),
('JPN', '使徒行传', 44, 7, 5, 'ここでは、足の踏み場となる土地さえも、相続財産として彼にお与えになりませんでした。しかし神は、まだ子がいなかった彼に対して、この地を彼とその後の子孫に所有地として与えることを約束されました。'),
('JPN', '使徒行传', 44, 7, 6, 'また、神は次のように言われました。『彼の子孫は他国の地で寄留者となり、四百年の間、奴隷となって苦しめられる。』'),
('JPN', '使徒行传', 44, 7, 7, 'また、神は言われました。『彼らが奴隷として仕えるその国民を、わたしはさばく。それから彼らは出て来て、この場所でわたしに仕えるようになる。』'),
('JPN', '使徒行传', 44, 7, 8, 'そして、神はアブラハムに割礼の契約を与えられました。こうして、アブラハムはイサクを生み、八日目にその子に割礼を施しました。それからイサクはヤコブを、ヤコブは十二人の族長たちを生みました。'),
('JPN', '使徒行传', 44, 7, 9, '族長たちはヨセフをねたんで、彼をエジプトに売りとばしました。しかし、神は彼とともにおられ、'),
('JPN', '使徒行传', 44, 7, 10, 'あらゆる苦難から彼を救い出し、エジプト王ファラオの前で恵みと知恵を与えられたので、ファラオは彼をエジプトと王の全家を治める高官に任じました。'),
('JPN', '使徒行传', 44, 7, 11, 'すると、エジプトとカナンの全地に飢饉が起こり、大きな苦難が襲って来たので、私たちの父祖たちは食べ物を手に入れることができなくなりました。'),
('JPN', '使徒行传', 44, 7, 12, 'しかし、ヤコブはエジプトに穀物があると聞いて、まず私たちの父祖たちを遣わしました。'),
('JPN', '使徒行传', 44, 7, 13, '二度目のとき、ヨセフは兄弟たちに自分のことを打ち明け、ヨセフの家族のことがファラオに明らかになりました。'),
('JPN', '使徒行传', 44, 7, 14, 'そこで、ヨセフは人を遣わして、自分の父ヤコブと七十五人の親族全員を呼び寄せました。'),
('JPN', '使徒行传', 44, 7, 15, 'こうして、ヤコブはエジプトに下り、そこで彼も私たちの父祖たちも死にました。'),
('JPN', '使徒行传', 44, 7, 16, '彼らはシェケムに運ばれ、かつてアブラハムがいくらかの銀でシェケムのハモルの子らから買っておいた墓に、葬られました。'),
('JPN', '使徒行传', 44, 7, 17, 'さて、神がアブラハムになされた約束の時が近づくにしたがい、民はエジプトで大いに数が増え、'),
('JPN', '使徒行传', 44, 7, 18, 'ヨセフのことを知らない別の王がエジプトに起こる時まで続きました。'),
('JPN', '使徒行传', 44, 7, 19, 'この王は、私たちの同胞に対して策略をめぐらし、私たちの先祖たちを苦しめて幼子を捨てさせ、生かしておけないようにしました。'),
('JPN', '使徒行传', 44, 7, 20, 'モーセが生まれたのは、このような時でした。彼は神の目にかなった、かわいい子で、三か月の間、父の家で育てられましたが、'),
('JPN', '使徒行传', 44, 7, 21, 'ついに捨てられたのをファラオの娘が拾い上げ、自分の子として育てました。'),
('JPN', '使徒行传', 44, 7, 22, 'モーセは、エジプト人のあらゆる学問を教え込まれ、ことばにも行いにも力がありました。'),
('JPN', '使徒行传', 44, 7, 23, 'モーセが四十歳になったとき、自分の同胞であるイスラエルの子らを顧みる思いが、その心に起こりました。'),
('JPN', '使徒行传', 44, 7, 24, 'そして、同胞の一人が虐待されているのを見て、その人をかばい、エジプト人を打ち殺して、ひどい目にあっていた人のために仕返しをしました。'),
('JPN', '使徒行传', 44, 7, 25, 'モーセは、自分の手によって神が同胞に救いを与えようとしておられることを、皆が理解してくれるものと思っていましたが、彼らは理解しませんでした。'),
('JPN', '使徒行传', 44, 7, 26, '翌日、モーセは同胞たちが争っているところに現れ、和解させようとして言いました。『あなたがたは兄弟だ。どうして互いに傷つけ合うのか。』'),
('JPN', '使徒行传', 44, 7, 27, 'すると、隣人を傷つけていた者が、モーセを押しのけながら言いました。『だれがおまえを、指導者やさばき人として私たちの上に任命したのか。'),
('JPN', '使徒行传', 44, 7, 28, '昨日エジプト人を殺したように、私も殺すつもりか。』'),
('JPN', '使徒行传', 44, 7, 29, 'このことばを聞いたモーセは逃げて、ミディアンの地で寄留者となり、そこで男の子を二人もうけました。'),
('JPN', '使徒行传', 44, 7, 30, '四十年たったとき、シナイ山の荒野において、柴の茂みの燃える炎の中で、御使いがモーセに現れました。'),
('JPN', '使徒行传', 44, 7, 31, 'その光景を見たモーセは驚き、それをよく見ようとして近寄ったところ、主の御声が聞こえました。'),
('JPN', '使徒行传', 44, 7, 32, '『わたしは、あなたの父祖たちの神、アブラハム、イサク、ヤコブの神である。』モーセは震え上がり、あえて見ようとはしませんでした。'),
('JPN', '使徒行传', 44, 7, 33, 'すると、主は彼にこう言われました。『あなたの履き物を脱げ。あなたの立っている場所は聖なる地である。'),
('JPN', '使徒行传', 44, 7, 34, 'わたしは、エジプトにいるわたしの民の苦しみを確かに見た。また彼らのうめきを聞いた。だから、彼らを救い出すために下って来たのだ。今、行け。わたしは、あなたをエジプトに遣わす。』'),
('JPN', '使徒行传', 44, 7, 35, '『だれがおまえを、指導者やさばき人として任命したのか』と言って人々が拒んだこのモーセを、神は、柴の茂みの中で彼に現れた御使いの手によって、指導者また解放者として遣わされたのです。'),
('JPN', '使徒行传', 44, 7, 36, 'この人が人々を導き出し、エジプトの地で、紅海で、また四十年の間荒野で、不思議としるしを行いました。'),
('JPN', '使徒行传', 44, 7, 37, 'このモーセが、イスラエルの子らにこう言ったのです。『神は、あなたがたの同胞の中から、私のような一人の預言者をあなたがたのために起こされる。』'),
('JPN', '使徒行传', 44, 7, 38, 'また、モーセは、シナイ山で彼に語った御使いや私たちの先祖たちとともに、荒野の集会にいて、私たちに与えるための生きたみことばを授かりました。'),
('JPN', '使徒行传', 44, 7, 39, 'ところが私たちの先祖たちは、彼に従うことを好まず、かえって彼を退け、エジプトをなつかしく思って、'),
('JPN', '使徒行传', 44, 7, 40, 'アロンに言いました。『われわれに先立って行く神々を、われわれのために造ってほしい。われわれをエジプトの地から導き出した、あのモーセがどうなったのか、分からないから。』'),
('JPN', '使徒行传', 44, 7, 41, '彼らが子牛を造ったのはそのころで、彼らはこの偶像にいけにえを献げ、自分たちの手で造った物を楽しんでいました。'),
('JPN', '使徒行传', 44, 7, 42, 'そこで、神は彼らに背を向け、彼らが天の万象に仕えるに任せられました。預言者たちの書に書いてあるとおりです。『イスラエルの家よ。あなたがたは荒野にいた四十年の間に、いけにえとささげ物を、わたしのところに携えて来たことがあったか。'),
('JPN', '使徒行传', 44, 7, 43, 'あなたがたは、モレクの幕屋と神ライパンの星を担いでいた。それらは、あなたがたが拝むために造った像ではないか。わたしはあなたがたを、バビロンのかなたへ捕らえ移す。』'),
('JPN', '使徒行传', 44, 7, 44, '私たちの先祖たちのためには、荒野にあかしの幕屋がありました。それは、見たとおりの形に造れとモーセに言われた方の命令どおりのものでした。'),
('JPN', '使徒行传', 44, 7, 45, '私たちの先祖たちは、この幕屋を受け継いで、神が自分たちの前から追い払ってくださった異邦の民の所有地に、ヨシュアとともにそれを運び入れ、ダビデの時代に至りました。'),
('JPN', '使徒行传', 44, 7, 46, 'ダビデは神の前に恵みをいただき、ヤコブの家のために、幕屋のとどまるところを求めました。'),
('JPN', '使徒行传', 44, 7, 47, 'そして、ソロモンが神のために家を建てました。'),
('JPN', '使徒行传', 44, 7, 48, 'しかし、いと高き方は、手で造った家にはお住みになりません。預言者が語っているとおりです。'),
('JPN', '使徒行传', 44, 7, 49, '『天はわたしの王座、地はわたしの足台。あなたがたは、わたしのためにどのような家を建てようとするのか。──主のことば──わたしの安息の場は、いったいどこにあるのか。'),
('JPN', '使徒行传', 44, 7, 50, 'これらすべては、わたしの手が造ったものではないか。』'),
('JPN', '使徒行传', 44, 7, 51, 'うなじを固くする、心と耳に割礼を受けていない人たち。あなたがたは、いつも聖霊に逆らっています。あなたがたの先祖たちが逆らったように、あなたがたもそうしているのです。'),
('JPN', '使徒行传', 44, 7, 52, 'あなたがたの先祖たちが迫害しなかった預言者が、だれかいたでしょうか。彼らは、正しい方が来られることを前もって告げた人たちを殺しましたが、今はあなたがたが、この正しい方を裏切る者、殺す者となりました。'),
('JPN', '使徒行传', 44, 7, 53, 'あなたがたは御使いたちを通して律法を受けたのに、それを守らなかったのです。」'),
('JPN', '使徒行传', 44, 7, 54, '人々はこれを聞いて、はらわたが煮え返る思いで、ステパノに向かって歯ぎしりしていた。'),
('JPN', '使徒行传', 44, 7, 55, 'しかし、聖霊に満たされ、じっと天を見つめていたステパノは、神の栄光と神の右に立っておられるイエスを見て、'),
('JPN', '使徒行传', 44, 7, 56, '「見なさい。天が開けて、人の子が神の右に立っておられるのが見えます」と言った。'),
('JPN', '使徒行传', 44, 7, 57, '人々は大声で叫びながら、耳をおおい、一斉にステパノに向かって殺到した。'),
('JPN', '使徒行传', 44, 7, 58, 'そして彼を町の外に追い出して、石を投げつけた。証人たちは、自分たちの上着をサウロという青年の足もとに置いた。'),
('JPN', '使徒行传', 44, 7, 59, 'こうして彼らがステパノに石を投げつけていると、ステパノは主を呼んで言った。「主イエスよ、私の霊をお受けください。」'),
('JPN', '使徒行传', 44, 7, 60, 'そして、ひざまずいて大声で叫んだ。「主よ、この罪を彼らに負わせないでください。」こう言って、彼は眠りについた。'),
('JPN', '使徒行传', 44, 8, 1, 'サウロは、ステパノを殺すことに賛成していた。その日、エルサレムの教会に対する激しい迫害が起こり、使徒たち以外はみな、ユダヤとサマリアの諸地方に散らされた。'),
('JPN', '使徒行传', 44, 8, 2, '敬虔な人たちはステパノを葬り、彼のためにたいへん悲しんだ。'),
('JPN', '使徒行传', 44, 8, 3, 'サウロは家から家に押し入って、教会を荒らし、男も女も引きずり出して、牢に入れた。'),
('JPN', '使徒行传', 44, 8, 4, '散らされた人たちは、みことばの福音を伝えながら巡り歩いた。'),
('JPN', '使徒行传', 44, 8, 5, 'ピリポはサマリアの町に下って行き、人々にキリストを宣べ伝えた。'),
('JPN', '使徒行传', 44, 8, 6, '群衆はピリポの話を聞き、彼が行っていたしるしを見て、彼が語ることに、そろって関心を抱くようになった。'),
('JPN', '使徒行传', 44, 8, 7, '汚れた霊につかれた多くの人たちから、その霊が大声で叫びながら出て行き、中風の人や足の不自由な人が数多く癒やされたからである。'),
('JPN', '使徒行传', 44, 8, 8, 'その町には、大きな喜びがあった。'),
('JPN', '使徒行传', 44, 8, 9, 'ところで、以前からその町にはシモンという名の人がいた。彼は魔術を行ってサマリアの人々を驚かせ、自分は偉大な者だと話していた。'),
('JPN', '使徒行传', 44, 8, 10, '小さい者から大きい者まで、すべての人々が彼に関心を抱き、「この人こそ、『大能』と呼ばれる、神の力だ」と言っていた。'),
('JPN', '使徒行传', 44, 8, 11, '人々が彼に関心を抱いていたのは、長い間その魔術に驚かされていたからであった。'),
('JPN', '使徒行传', 44, 8, 12, 'しかし人々は、ピリポが神の国とイエス・キリストの名について宣べ伝えたことを信じて、男も女もバプテスマを受けた。'),
('JPN', '使徒行传', 44, 8, 13, 'シモン自身も信じてバプテスマを受けると、いつもピリポにつき従って、しるしと大いなる奇跡が行われるのを見ては驚いていた。'),
('JPN', '使徒行传', 44, 8, 14, 'エルサレムにいる使徒たちは、サマリアの人々が神のことばを受け入れたと聞いて、ペテロとヨハネを彼らのところに遣わした。'),
('JPN', '使徒行传', 44, 8, 15, '二人は下って行って、彼らが聖霊を受けるように祈った。'),
('JPN', '使徒行传', 44, 8, 16, '彼らは主イエスの名によってバプテスマを受けていただけで、聖霊はまだ、彼らのうちのだれにも下っていなかったからであった。'),
('JPN', '使徒行传', 44, 8, 17, 'そこで二人が彼らの上に手を置くと、彼らは聖霊を受けた。'),
('JPN', '使徒行传', 44, 8, 18, 'シモンは、使徒たちが手を置くことで御霊が与えられるのを見て、使徒たちのところに金を持って来て、'),
('JPN', '使徒行传', 44, 8, 19, '「私が手を置く者がだれでも聖霊を受けられるように、その権威を私にも下さい」と言った。'),
('JPN', '使徒行传', 44, 8, 20, 'しかし、ペテロは彼に言った。「おまえの金は、おまえとともに滅びるがよい。おまえが金で神の賜物を手に入れようと思っているからだ。'),
('JPN', '使徒行传', 44, 8, 21, 'おまえは、このことに何の関係もないし、あずかることもできない。おまえの心が神の前に正しくないからだ。'),
('JPN', '使徒行传', 44, 8, 22, 'だから、この悪事を悔い改めて、主に祈れ。もしかしたら、心に抱いた思いが赦されるかもしれない。'),
('JPN', '使徒行传', 44, 8, 23, 'おまえが苦い悪意と、不義の束縛の中にいることが、私には見えるのだ。」'),
('JPN', '使徒行传', 44, 8, 24, 'シモンは答えた。「あなたがたが言ったことが何一つ私の身に起こらないように、私のために主に祈ってください。」'),
('JPN', '使徒行传', 44, 8, 25, 'こうして、使徒たちは証しをし、主のことばを語った後、エルサレムに戻って行った。彼らはサマリア人の多くの村で福音を宣べ伝えた。'),
('JPN', '使徒行传', 44, 8, 26, 'さて、主の使いがピリポに言った。「立って南へ行き、エルサレムからガザに下る道に出なさい。」そこは荒野である。'),
('JPN', '使徒行传', 44, 8, 27, 'そこで、ピリポは立って出かけた。すると見よ。そこに、エチオピア人の女王カンダケの高官で、女王の全財産を管理していた宦官のエチオピア人がいた。彼は礼拝のためエルサレムに上り、'),
('JPN', '使徒行传', 44, 8, 28, '帰る途中であった。彼は馬車に乗って、預言者イザヤの書を読んでいた。'),
('JPN', '使徒行传', 44, 8, 29, '御霊がピリポに「近寄って、あの馬車と一緒に行きなさい」と言われた。'),
('JPN', '使徒行传', 44, 8, 30, 'そこでピリポが走って行くと、預言者イザヤの書を読んでいるのが聞こえたので、「あなたは、読んでいることが分かりますか」と言った。'),
('JPN', '使徒行传', 44, 8, 31, 'するとその人は、「導いてくれる人がいなければ、どうして分かるでしょうか」と答えた。そして、馬車に乗って一緒に座るよう、ピリポに頼んだ。'),
('JPN', '使徒行传', 44, 8, 32, '彼が読んでいた聖書の箇所には、こうあった。「屠り場に引かれて行く羊のように、毛を刈る者の前で黙っている子羊のように、彼は口を開かない。'),
('JPN', '使徒行传', 44, 8, 33, '彼は卑しめられ、さばきは行われなかった。彼の時代のことを、だれが語れるだろう。彼のいのちは地上から取り去られたのである。」'),
('JPN', '使徒行传', 44, 8, 34, '宦官はピリポに向かって言った。「お尋ねしますが、預言者はだれについてこう言っているのですか。自分についてですか。それとも、だれかほかの人についてですか。」'),
('JPN', '使徒行传', 44, 8, 35, 'ピリポは口を開き、この聖書の箇所から始めて、イエスの福音を彼に伝えた。'),
('JPN', '使徒行传', 44, 8, 36, '道を進んで行くうちに、水のある場所に来たので、宦官は言った。「見てください。水があります。私がバプテスマを受けるのに、何か妨げがあるでしょうか。」'),
('JPN', '使徒行传', 44, 8, 37, 'そこでピリポは言った。「もしあなたが心底から信じるならば、よいのです。」すると彼は答えて言った。「私は、イエス・キリストが神の御子であると信じます。」'),
('JPN', '使徒行传', 44, 8, 38, 'そして、馬車を止めるように命じた。ピリポと宦官は二人とも水の中に降りて行き、ピリポが宦官にバプテスマを授けた。'),
('JPN', '使徒行传', 44, 8, 39, '二人が水から上がって来たとき、主の霊がピリポを連れ去られた。宦官はもはやピリポを見ることはなかったが、喜びながら帰って行った。'),
('JPN', '使徒行传', 44, 8, 40, 'それからピリポはアゾトに現れた。そして、すべての町を通って福音を宣べ伝え、カイサリアに行った。'),
('JPN', '使徒行传', 44, 9, 1, 'さて、サウロはなおも主の弟子たちを脅かして殺害しようと息巻き、大祭司のところに行って、'),
('JPN', '使徒行传', 44, 9, 2, 'ダマスコの諸会堂宛ての手紙を求めた。それは、この道の者であれば男でも女でも見つけ出し、縛り上げてエルサレムに引いて来るためであった。'),
('JPN', '使徒行传', 44, 9, 3, 'ところが、サウロが道を進んでダマスコの近くまで来たとき、突然、天からの光が彼の周りを照らした。'),
('JPN', '使徒行传', 44, 9, 4, '彼は地に倒れて、自分に語りかける声を聞いた。「サウロ、サウロ、なぜわたしを迫害するのか。」'),
('JPN', '使徒行传', 44, 9, 5, '彼が「主よ、あなたはどなたですか」と言うと、答えがあった。「わたしは、あなたが迫害しているイエスである。'),
('JPN', '使徒行传', 44, 9, 6, '立ち上がって、町に入りなさい。そうすれば、あなたがしなければならないことが告げられる。」'),
('JPN', '使徒行传', 44, 9, 7, '同行していた人たちは、声は聞こえてもだれも見えないので、ものも言えずに立っていた。'),
('JPN', '使徒行传', 44, 9, 8, 'サウロは地面から立ち上がった。しかし、目を開けていたものの、何も見えなかった。それで人々は彼の手を引いて、ダマスコに連れて行った。'),
('JPN', '使徒行传', 44, 9, 9, '彼は三日間、目が見えず、食べることも飲むこともしなかった。'),
('JPN', '使徒行传', 44, 9, 10, 'さて、ダマスコにアナニアという名の弟子がいた。主が幻の中で「アナニアよ」と言われたので、彼は「主よ、ここにおります」と答えた。'),
('JPN', '使徒行传', 44, 9, 11, 'すると、主はこう言われた。「立って、『まっすぐ』と呼ばれる通りに行き、ユダの家にいるサウロという名のタルソ人を訪ねなさい。彼はそこで祈っています。'),
('JPN', '使徒行传', 44, 9, 12, '彼は幻の中で、アナニアという名の人が入って来て、自分の上に手を置き、再び見えるようにしてくれるのを見たのです。」'),
('JPN', '使徒行传', 44, 9, 13, 'しかし、アナニアは答えた。「主よ。私は多くの人たちから、この人がエルサレムで、あなたの聖徒たちにどんなにひどいことをしたかを聞きました。'),
('JPN', '使徒行传', 44, 9, 14, '彼はここでも、あなたの名を呼ぶ者たちをみな捕縛する権限を、祭司長たちから与えられています。」'),
('JPN', '使徒行传', 44, 9, 15, 'しかし、主はアナニアに言われた。「行きなさい。あの人はわたしの名を、異邦人、王たち、イスラエルの子らの前に運ぶ、わたしの選びの器です。'),
('JPN', '使徒行传', 44, 9, 16, '彼がわたしの名のためにどんなに苦しまなければならないかを、わたしは彼に示します。」'),
('JPN', '使徒行传', 44, 9, 17, 'そこでアナニアは出かけて行って、その家に入り、サウロの上に手を置いて言った。「兄弟サウロ。あなたが来る途中であなたに現れた主イエスが、私を遣わされました。あなたが再び見えるようになり、聖霊に満たされるためです。」'),
('JPN', '使徒行传', 44, 9, 18, 'するとただちに、サウロの目から鱗のような物が落ちて、目が見えるようになった。そこで、彼は立ち上がってバプテスマを受け、'),
('JPN', '使徒行传', 44, 9, 19, '食事をして元気になった。サウロは数日の間、ダマスコの弟子たちとともにいて、'),
('JPN', '使徒行传', 44, 9, 20, 'ただちに諸会堂で、「この方こそ神の子です」とイエスのことを宣べ伝え始めた。'),
('JPN', '使徒行传', 44, 9, 21, 'これを聞いた人々はみな驚いて言った。「この人はエルサレムで、この名を呼ぶ人たちを滅ぼした者ではないか。ここへやって来たのも、彼らを縛って、祭司長たちのところへ引いて行くためではなかったか。」'),
('JPN', '使徒行传', 44, 9, 22, 'しかし、サウロはますます力を増し、イエスがキリストであることを証明して、ダマスコに住むユダヤ人たちをうろたえさせた。'),
('JPN', '使徒行传', 44, 9, 23, 'かなりの日数がたち、ユダヤ人たちはサウロを殺す相談をしたが、'),
('JPN', '使徒行传', 44, 9, 24, '彼らの陰謀はサウロの知るところとなった。彼らはサウロを殺そうと、昼も夜も町の門を見張っていた。'),
('JPN', '使徒行传', 44, 9, 25, 'そこで、彼の弟子たちは夜の間に彼を連れ出し、籠に乗せて町の城壁伝いにつり降ろした。'),
('JPN', '使徒行传', 44, 9, 26, 'エルサレムに着いて、サウロは弟子たちの仲間に入ろうと試みたが、みな、彼が弟子であるとは信じず、彼を恐れていた。'),
('JPN', '使徒行传', 44, 9, 27, 'しかし、バルナバはサウロを引き受けて、使徒たちのところに連れて行き、彼がダマスコへ行く途中で主を見た様子や、主が彼に語られたこと、また彼がダマスコでイエスの名によって大胆に語った様子を彼らに説明した。'),
('JPN', '使徒行传', 44, 9, 28, 'サウロはエルサレムで使徒たちと自由に行き来し、主の御名によって大胆に語った。'),
('JPN', '使徒行传', 44, 9, 29, 'また、ギリシア語を使うユダヤ人たちと語ったり、論じたりしていたが、彼らはサウロを殺そうと狙っていた。'),
('JPN', '使徒行传', 44, 9, 30, 'それを知った兄弟たちは、彼をカイサリアに連れて下り、タルソへ送り出した。'),
('JPN', '使徒行传', 44, 9, 31, 'こうして、教会はユダヤ、ガリラヤ、サマリアの全地にわたり築き上げられて平安を得た。主を恐れ、聖霊に励まされて前進し続け、信者の数が増えていった。'),
('JPN', '使徒行传', 44, 9, 32, 'さて、ペテロがあらゆるところを巡回していたときのことであった。彼は、リダに住む聖徒たちのところにも下って行った。'),
('JPN', '使徒行传', 44, 9, 33, 'そこで彼は、アイネアという名で、八年間床についている人に出会った。彼は中風であった。'),
('JPN', '使徒行传', 44, 9, 34, 'ペテロは彼に言った。「アイネア、イエス・キリストがあなたを癒やしてくださいます。立ち上がりなさい。そして自分で床を整えなさい。」すると、彼はただちに立ち上がった。'),
('JPN', '使徒行传', 44, 9, 35, 'リダとシャロンに住む人々はみなアイネアを見て、主に立ち返った。'),
('JPN', '使徒行传', 44, 9, 36, 'またヤッファに、その名をタビタ、ギリシア語に訳せばドルカスという女の弟子がいた。彼女は多くの良いわざと施しをしていた。'),
('JPN', '使徒行传', 44, 9, 37, 'ところが、そのころ彼女は病気になって死んだ。人々は遺体を洗って、屋上の部屋に安置した。'),
('JPN', '使徒行传', 44, 9, 38, 'リダはヤッファに近かったので、ペテロがそこにいると聞いた弟子たちは、人を二人、彼のところに遣わして、「私たちのところまで、すぐ来てください」と頼んだ。'),
('JPN', '使徒行传', 44, 9, 39, 'そこで、ペテロは立って二人と一緒に出かけた。ペテロが到着すると、彼らはペテロを屋上の部屋に案内した。やもめたちはみな彼のところに来て、泣きながら、ドルカスが一緒にいたころ作ってくれた下着や上着の数々を見せるのであった。'),
('JPN', '使徒行传', 44, 9, 40, 'ペテロは皆を外に出し、ひざまずいて祈った。そして、遺体の方を向いて、「タビタ、起きなさい」と言った。すると彼女は目を開け、ペテロを見て起き上がった。'),
('JPN', '使徒行传', 44, 9, 41, 'そこで、ペテロは手を貸して彼女を立たせた。そして聖徒たちとやもめたちを呼んで、生きている彼女を見せた。'),
('JPN', '使徒行传', 44, 9, 42, 'このことがヤッファ中に知れ渡り、多くの人々が主を信じた。'),
('JPN', '使徒行传', 44, 9, 43, 'ペテロはかなりの期間、ヤッファで、シモンという皮なめし職人のところに滞在した。'),
('JPN', '使徒行传', 44, 10, 1, 'さて、カイサリアにコルネリウスという名の人がいた。イタリア隊という部隊の百人隊長であった。'),
('JPN', '使徒行传', 44, 10, 2, '彼は敬虔な人で、家族全員とともに神を恐れ、民に多くの施しをし、いつも神に祈りをささげていた。'),
('JPN', '使徒行传', 44, 10, 3, 'ある日の午後三時ごろ、彼は幻の中で、はっきりと神の御使いを見た。その御使いは彼のところに来て、「コルネリウス」と呼びかけた。'),
('JPN', '使徒行传', 44, 10, 4, '彼は御使いを見つめていたが、恐ろしくなって言った。「主よ、何でしょうか。」すると御使いは言った。「あなたの祈りと施しは神の御前に上って、覚えられています。'),
('JPN', '使徒行传', 44, 10, 5, 'さあ今、ヤッファに人を遣わして、ペテロと呼ばれているシモンという人を招きなさい。'),
('JPN', '使徒行传', 44, 10, 6, 'その人は、シモンという皮なめし職人のところに泊まっています。その家は海辺にあります。」'),
('JPN', '使徒行传', 44, 10, 7, '御使いが彼にこう語って立ち去ると、コルネリウスはしもべたちのうち二人と、彼の側近の部下のうち敬虔な兵士一人を呼び、'),
('JPN', '使徒行传', 44, 10, 8, 'すべてのことを説明して、彼らをヤッファに遣わした。'),
('JPN', '使徒行传', 44, 10, 9, '翌日、この人たちが旅を続けて、町の近くまで来たころ、ペテロは祈るために屋上に上った。昼の十二時ごろであった。'),
('JPN', '使徒行传', 44, 10, 10, '彼は空腹を覚え、何か食べたいと思った。ところが、人々が食事の用意をしているうちに、彼は夢心地になった。'),
('JPN', '使徒行传', 44, 10, 11, 'すると天が開け、大きな敷布のような入れ物が、四隅をつるされて地上に降りて来るのが見えた。'),
('JPN', '使徒行传', 44, 10, 12, 'その中には、あらゆる四つ足の動物、地を這うもの、空の鳥がいた。'),
('JPN', '使徒行传', 44, 10, 13, 'そして彼に、「ペテロよ、立ち上がり、屠って食べなさい」という声が聞こえた。'),
('JPN', '使徒行传', 44, 10, 14, 'しかし、ペテロは言った。「主よ、そんなことはできません。私はまだ一度も、きよくない物や汚れた物を食べたことがありません。」'),
('JPN', '使徒行传', 44, 10, 15, 'すると、もう一度、声が聞こえた。「神がきよめた物を、あなたがきよくないと言ってはならない。」'),
('JPN', '使徒行传', 44, 10, 16, 'このようなことが三回あってから、すぐにその入れ物は天に引き上げられた。'),
('JPN', '使徒行传', 44, 10, 17, 'ペテロが、今見た幻はいったいどういうことだろうか、と一人で思い惑っていると、なんと、コルネリウスから遣わされた人たちがシモンの家を捜し当てて、その門口に立ち、'),
('JPN', '使徒行传', 44, 10, 18, '声をかけて、「ペテロと呼ばれているシモンはここに泊まっていますか」と尋ねていた。'),
('JPN', '使徒行传', 44, 10, 19, 'ペテロは幻について思い巡らしていたが、御霊が彼に言われた。「見なさい。三人の人があなたを訪ねて来ています。'),
('JPN', '使徒行传', 44, 10, 20, 'さあ、下に降りて行き、ためらわずに彼らと一緒に行きなさい。わたしが彼らを遣わしたのです。」'),
('JPN', '使徒行传', 44, 10, 21, 'そこでペテロは、その人たちのところに降りて行って、言った。「あなたがたが探しているのは、この私です。どんなご用でおいでになったのですか。」'),
('JPN', '使徒行传', 44, 10, 22, 'すると、彼らは言った。「正しい人で、神を恐れ、ユダヤの民全体に評判が良い百人隊長コルネリウスが、あなたを自分の家に招いて、あなたから話を聞くようにと、聖なる御使いから示されました。」'),
('JPN', '使徒行传', 44, 10, 23, 'それでペテロは、彼らを迎え入れて泊まらせた。翌日、ペテロは立って、彼らと一緒に出かけた。ヤッファの兄弟たちも数人同行した。'),
('JPN', '使徒行传', 44, 10, 24, 'そして次の日、ペテロはカイサリアに着いた。コルネリウスは、親族や親しい友人たちを呼び集めて、彼らを待っていた。'),
('JPN', '使徒行传', 44, 10, 25, 'ペテロが着くと、コルネリウスは迎えに出て、足もとにひれ伏して拝んだ。'),
('JPN', '使徒行传', 44, 10, 26, 'するとペテロは彼を起こして、「お立ちください。私も同じ人間です」と言った。'),
('JPN', '使徒行传', 44, 10, 27, 'そして、コルネリウスとことばを交わしながら家に入り、多くの人が集まっているのを見て、'),
('JPN', '使徒行传', 44, 10, 28, 'その人たちにこう言った。「ご存じのとおり、ユダヤ人には、外国人と交わったり、外国人を訪問したりすることは許されていません。ところが、神は私に、どんな人のことも、きよくない者であるとか汚れた者であるとか言ってはならないことを、示してくださいました。'),
('JPN', '使徒行传', 44, 10, 29, 'それで、お招きを受けたとき、ためらうことなく来たのです。そこでお尋ねしますが、あなたがたは、どういうわけで私をお招きになったのですか。」'),
('JPN', '使徒行传', 44, 10, 30, 'すると、コルネリウスが言った。「四日前のこの時刻に、私が家で午後三時の祈りをしていますと、なんと、輝いた衣を着た人が私の前に立って、'),
('JPN', '使徒行传', 44, 10, 31, 'こう言いました。『コルネリウス。あなたの祈りは聞き入れられ、あなたの施しは神の前に覚えられています。'),
('JPN', '使徒行传', 44, 10, 32, 'だから、ヤッファに人を送って、ペテロと呼ばれるシモンを招きなさい。この人は海辺にある、皮なめし職人のシモンの家に泊まっています。』'),
('JPN', '使徒行传', 44, 10, 33, 'それで、私はすぐにあなたのところに人を送ったのです。ようこそおいでくださいました。今、私たちはみな、主があなたにお命じになったすべてのことを伺おうとして、神の御前に出ております。」'),
('JPN', '使徒行传', 44, 10, 34, 'そこで、ペテロは口を開いてこう言った。「これで私は、はっきり分かりました。神はえこひいきをする方ではなく、'),
('JPN', '使徒行传', 44, 10, 35, 'どこの国の人であっても、神を恐れ、正義を行う人は、神に受け入れられます。'),
('JPN', '使徒行传', 44, 10, 36, '神は、イスラエルの子らにみことばを送り、イエス・キリストによって平和の福音を宣べ伝えられました。このイエス・キリストはすべての人の主です。'),
('JPN', '使徒行传', 44, 10, 37, 'あなたがたは、ヨハネが宣べ伝えたバプテスマの後、ガリラヤから始まって、ユダヤ全土に起こった事柄をご存じです。'),
('JPN', '使徒行传', 44, 10, 38, 'それは、ナザレのイエスのことです。神はこのイエスに聖霊と力によって油を注がれました。イエスは巡り歩いて良いわざを行い、悪魔に虐げられている人たちをみな癒やされました。それは神がイエスとともにおられたからです。'),
('JPN', '使徒行传', 44, 10, 39, '私たちは、イエスがユダヤ人の地とエルサレムで行われた、すべてのことの証人です。人々はこのイエスを木にかけて殺しましたが、'),
('JPN', '使徒行传', 44, 10, 40, '神はこの方を三日目によみがえらせ、現れさせてくださいました。'),
('JPN', '使徒行传', 44, 10, 41, '民全体にではなく、神によって前もって選ばれた証人である私たちに現れたのです。私たちは、イエスが死者の中からよみがえられた後、一緒に食べたり飲んだりしました。'),
('JPN', '使徒行传', 44, 10, 42, 'そしてイエスは、ご自分が、生きている者と死んだ者のさばき主として神が定めた方であることを、人々に宣べ伝え、証しするように、私たちに命じられました。'),
('JPN', '使徒行传', 44, 10, 43, '預言者たちもみなイエスについて、この方を信じる者はだれでも、その名によって罪の赦しが受けられると、証ししています。」'),
('JPN', '使徒行传', 44, 10, 44, 'ペテロがなおもこれらのことを話し続けていると、みことばを聞いていたすべての人々に、聖霊が下った。'),
('JPN', '使徒行传', 44, 10, 45, '割礼を受けている信者で、ペテロと一緒に来た人たちは、異邦人にも聖霊の賜物が注がれたことに驚いた。'),
('JPN', '使徒行传', 44, 10, 46, '彼らが異言を語り、神を賛美するのを聞いたからである。するとペテロは言った。'),
('JPN', '使徒行传', 44, 10, 47, '「この人たちが水でバプテスマを受けるのを、だれが妨げることができるでしょうか。私たちと同じように聖霊を受けたのですから。」'),
('JPN', '使徒行传', 44, 10, 48, 'ペテロはコルネリウスたちに命じて、イエス・キリストの名によってバプテスマを受けさせた。それから、彼らはペテロに願って、何日か滞在してもらった。'),
('JPN', '使徒行传', 44, 11, 1, 'さて、使徒たちとユダヤにいる兄弟たちは、異邦人たちも神のことばを受け入れたことを耳にした。'),
('JPN', '使徒行传', 44, 11, 2, 'そこで、ペテロがエルサレムに上って来たとき、割礼を受けている者たちが、彼を非難して、'),
('JPN', '使徒行传', 44, 11, 3, '「あなたは割礼を受けていない者たちのところに行って、彼らと一緒に食事をした」と言った。'),
('JPN', '使徒行传', 44, 11, 4, 'そこで、ペテロは彼らに事の次第を順序立てて説明した。'),
('JPN', '使徒行传', 44, 11, 5, '「私はヤッファの町で祈っていました。すると、夢心地になり、幻を見ました。大きな敷布のような入れ物が、四隅をつり下げられ、天から降りて来て、私のところに届いたのです。'),
('JPN', '使徒行传', 44, 11, 6, 'その中をよく見ると、地の四つ足の動物、獣、這うもの、空の鳥が見えました。'),
('JPN', '使徒行传', 44, 11, 7, 'そして、『ペテロよ、さあ、屠って食べなさい』と言う声を聞きました。'),
('JPN', '使徒行传', 44, 11, 8, 'しかし私は、『主よ、そんなことはできません。私は、きよくない物や汚れた物を、まだ一度も口に入れたことがありません』と言いました。'),
('JPN', '使徒行传', 44, 11, 9, 'すると、もう一度天から声が返って来ました。『神がきよめた物を、あなたがきよくないと言ってはならない。』'),
('JPN', '使徒行传', 44, 11, 10, 'このようなことが三回あって、すべての物が再び天に引き上げられました。'),
('JPN', '使徒行传', 44, 11, 11, 'すると、なんとちょうどそのとき、三人の人が私たちがいた家の前に立っていたのです。カイサリアから私のところに遣わされた人たちでした。'),
('JPN', '使徒行传', 44, 11, 12, 'そして御霊は私に、ためらわずにその人たちと一緒に行くように言われました。そこで、ここにいる六人の兄弟たちも同行して、私たちはその人の家に入りました。'),
('JPN', '使徒行传', 44, 11, 13, 'すると、その人は、御使いが自分の家の中に立っているのを見たこと、そして次のように語ったことを私たちに話してくれました。『ヤッファに人を遣わして、ペテロと呼ばれるシモンを招きなさい。'),
('JPN', '使徒行传', 44, 11, 14, 'その人が、あなたとあなたの家の者たち全員を救うことばを、あなたに話してくれます。』'),
('JPN', '使徒行传', 44, 11, 15, 'そこで、私が話し始めると、聖霊が初めに私たちの上に下ったのと同じように、彼らの上に下ったのです。'),
('JPN', '使徒行传', 44, 11, 16, '私は主が、『ヨハネは水でバプテスマを授けたが、あなたがたは聖霊によるバプテスマを授けられる』と言われたことばを思い起こしました。'),
('JPN', '使徒行传', 44, 11, 17, 'ですから、神が、私たちが主イエス・キリストを信じたときに私たちに下さったのと同じ賜物を、彼らにもお授けになったのなら、どうして私などが、神がなさることを妨げることができるでしょうか。」'),
('JPN', '使徒行传', 44, 11, 18, '人々はこれを聞いて沈黙した。そして「それでは神は、いのちに至る悔い改めを異邦人にもお与えになったのだ」と言って、神をほめたたえた。'),
('JPN', '使徒行传', 44, 11, 19, 'さて、ステパノのことから起こった迫害により散らされた人々は、フェニキア、キプロス、アンティオキアまで進んで行ったが、ユダヤ人以外の人には、だれにもみことばを語らなかった。'),
('JPN', '使徒行传', 44, 11, 20, 'ところが、彼らの中にキプロス人とクレネ人が何人かいて、アンティオキアに来ると、ギリシア語を話す人たちにも語りかけ、主イエスの福音を宣べ伝えた。'),
('JPN', '使徒行传', 44, 11, 21, 'そして、主の御手が彼らとともにあったので、大勢の人が信じて主に立ち返った。'),
('JPN', '使徒行传', 44, 11, 22, 'この知らせがエルサレムにある教会の耳に入ったので、彼らはバルナバをアンティオキアに遣わした。'),
('JPN', '使徒行传', 44, 11, 23, 'バルナバはそこに到着し、神の恵みを見て喜んだ。そして、心を堅く保っていつも主にとどまっているようにと、皆を励ました。'),
('JPN', '使徒行传', 44, 11, 24, '彼は立派な人物で、聖霊と信仰に満ちている人であった。こうして、大勢の人たちが主に導かれた。'),
('JPN', '使徒行传', 44, 11, 25, 'それから、バルナバはサウロを捜しにタルソに行き、'),
('JPN', '使徒行传', 44, 11, 26, '彼を見つけて、アンティオキアに連れて来た。彼らは、まる一年の間教会に集い、大勢の人たちを教えた。弟子たちは、アンティオキアで初めて、キリスト者と呼ばれるようになった。'),
('JPN', '使徒行传', 44, 11, 27, 'そのころ、預言者たちがエルサレムからアンティオキアに下って来た。'),
('JPN', '使徒行传', 44, 11, 28, 'その中の一人で名をアガボという人が立って、世界中に大飢饉が起こると御霊によって預言し、それがクラウディウス帝の時に起こった。'),
('JPN', '使徒行传', 44, 11, 29, '弟子たちは、それぞれの力に応じて、ユダヤに住んでいる兄弟たちに救援の物を送ることに決めた。'),
('JPN', '使徒行传', 44, 11, 30, '彼らはそれを実行し、バルナバとサウロの手に託して長老たちに送った。'),
('JPN', '使徒行传', 44, 12, 1, 'そのころ、ヘロデ王は、教会の中のある人たちを苦しめようとしてその手を伸ばし、'),
('JPN', '使徒行传', 44, 12, 2, 'ヨハネの兄弟ヤコブを剣で殺した。'),
('JPN', '使徒行传', 44, 12, 3, 'それがユダヤ人に喜ばれたのを見て、さらにペテロも捕らえにかかった。それは、種なしパンの祭りの時期であった。'),
('JPN', '使徒行传', 44, 12, 4, 'ヘロデはペテロを捕らえて牢に入れ、四人一組の兵士四組に引き渡して監視させた。過越の祭りの後に、彼を民衆の前に引き出すつもりでいたのである。'),
('JPN', '使徒行传', 44, 12, 5, 'こうしてペテロは牢に閉じ込められていたが、教会は彼のために、熱心な祈りを神にささげていた。'),
('JPN', '使徒行传', 44, 12, 6, 'ヘロデが彼を引き出そうとしていた日の前夜、ペテロは二本の鎖につながれて、二人の兵士の間で眠っていた。戸口では番兵たちが牢を監視していた。'),
('JPN', '使徒行传', 44, 12, 7, 'すると見よ。主の使いがそばに立ち、牢の中を光が照らした。御使いはペテロの脇腹を突いて彼を起こし、「急いで立ち上がりなさい」と言った。すると、鎖が彼の手から外れ落ちた。'),
('JPN', '使徒行传', 44, 12, 8, '御使いは彼に言った。「帯を締めて、履き物をはきなさい。」ペテロがそのとおりにすると、御使いはまた言った。「上着を着て、私について来なさい。」'),
('JPN', '使徒行传', 44, 12, 9, 'そこでペテロは外に出て、御使いについて行った。彼には御使いがしていることが現実とは思えず、幻を見ているのだと思っていた。'),
('JPN', '使徒行传', 44, 12, 10, '彼らが、第一、第二の衛所を通り、町に通じる鉄の門まで来ると、門がひとりでに開いた。彼らは外に出て、一つの通りを進んで行った。すると、すぐに御使いは彼から離れた。'),
('JPN', '使徒行传', 44, 12, 11, 'そのとき、ペテロは我に返って言った。「今、本当のことが分かった。主が御使いを遣わして、ヘロデの手から、またユダヤの民のすべてのもくろみから、私を救い出してくださったのだ。」'),
('JPN', '使徒行传', 44, 12, 12, 'それが分かったので、ペテロは、マルコと呼ばれているヨハネの母マリアの家に行った。そこには多くの人々が集まって、祈っていた。'),
('JPN', '使徒行传', 44, 12, 13, '彼が門の戸をたたくと、ロデという名の召使いが応対に出て来た。'),
('JPN', '使徒行传', 44, 12, 14, 'そして、ペテロの声だと分かると、喜びのあまり門を開けもせずに奥に駆け込み、ペテロが門の前に立っていることを知らせた。'),
('JPN', '使徒行传', 44, 12, 15, '人々は彼女に「あなたは気が変になっている」と言ったが、彼女は本当だと言い張った。それで彼らは「それはペテロの御使いだ」と言った。'),
('JPN', '使徒行传', 44, 12, 16, 'だが、ペテロは門をたたき続けていた。彼らが開けると、そこにペテロがいたので非常に驚いた。'),
('JPN', '使徒行传', 44, 12, 17, 'ペテロは静かにするように手で彼らを制してから、主がどのようにして自分を牢から救い出してくださったかを彼らに説明し、「このことをヤコブと兄弟たちに知らせてください」と言った。そして、そこを出て、ほかの場所へ行った。'),
('JPN', '使徒行传', 44, 12, 18, '朝になると、ペテロはどうなったのかと、兵士たちの間で大変な騒ぎになった。'),
('JPN', '使徒行传', 44, 12, 19, 'ヘロデはペテロを捜したが見つからないので、番兵たちを取り調べ、彼らを処刑するように命じた。そしてユダヤからカイサリアに下って行き、そこに滞在した。'),
('JPN', '使徒行传', 44, 12, 20, 'さて、ヘロデはツロとシドンの人々に対してひどく腹を立てていた。そこで、その人々はそろって王を訪ね、王の侍従ブラストに取り入って和解を願い出た。彼らの地方は王の国から食糧を得ていたからである。'),
('JPN', '使徒行传', 44, 12, 21, '定められた日に、ヘロデは王服をまとって王座に着き、彼らに向かって演説をした。'),
('JPN', '使徒行传', 44, 12, 22, '集まった会衆は、「神の声だ。人間の声ではない」と叫び続けた。'),
('JPN', '使徒行传', 44, 12, 23, 'すると、即座に主の使いがヘロデを打った。ヘロデが神に栄光を帰さなかったからである。彼は虫に食われて、息絶えた。'),
('JPN', '使徒行传', 44, 12, 24, '神のことばはますます盛んになり、広まっていった。'),
('JPN', '使徒行传', 44, 12, 25, 'エルサレムのための奉仕を果たしたバルナバとサウロは、マルコと呼ばれるヨハネを連れて、戻って来た。'),
('JPN', '使徒行传', 44, 13, 1, 'さて、アンティオキアには、そこにある教会に、バルナバ、ニゲルと呼ばれるシメオン、クレネ人ルキオ、領主ヘロデの乳兄弟マナエン、サウロなどの預言者や教師がいた。'),
('JPN', '使徒行传', 44, 13, 2, '彼らが主を礼拝し、断食していると、聖霊が「さあ、わたしのためにバルナバとサウロを聖別して、わたしが召した働きに就かせなさい」と言われた。'),
('JPN', '使徒行传', 44, 13, 3, 'そこで彼らは断食して祈り、二人の上に手を置いてから送り出した。'),
('JPN', '使徒行传', 44, 13, 4, '二人は聖霊によって送り出され、セレウキアに下り、そこからキプロスに向けて船出し、'),
('JPN', '使徒行传', 44, 13, 5, 'サラミスに着くとユダヤ人の諸会堂で神のことばを宣べ伝えた。彼らはヨハネも助手として連れていた。'),
('JPN', '使徒行传', 44, 13, 6, '島全体を巡回してパポスまで行ったところ、ある魔術師に出会った。バルイエスという名のユダヤ人で、偽預言者であった。'),
('JPN', '使徒行传', 44, 13, 7, 'この男は、地方総督セルギウス・パウルスのもとにいた。この総督は賢明な人で、バルナバとサウロを招いて神のことばを聞きたいと願った。'),
('JPN', '使徒行传', 44, 13, 8, 'ところが、その魔術師エリマ（その名を訳すと、魔術師）は、二人に反対して総督を信仰から遠ざけようとした。'),
('JPN', '使徒行传', 44, 13, 9, 'すると、サウロ、別名パウロは、聖霊に満たされ、彼をにらみつけて、'),
('JPN', '使徒行传', 44, 13, 10, 'こう言った。「ああ、あらゆる偽りとあらゆる悪事に満ちた者、悪魔の子、すべての正義の敵、おまえは、主のまっすぐな道を曲げることをやめないのか。'),
('JPN', '使徒行传', 44, 13, 11, '見よ、主の御手が今、おまえの上にある。おまえは盲目になって、しばらくの間、日の光を見ることができなくなる。」するとたちまち、かすみと闇が彼をおおったため、彼は手を引いてくれる人を探し回った。'),
('JPN', '使徒行传', 44, 13, 12, '総督はこの出来事を見て、主の教えに驚嘆し、信仰に入った。'),
('JPN', '使徒行传', 44, 13, 13, 'パウロの一行は、パポスから船出してパンフィリアのペルゲに渡ったが、ヨハネは一行から離れて、エルサレムに帰ってしまった。'),
('JPN', '使徒行传', 44, 13, 14, '二人はペルゲから進んで、ピシディアのアンティオキアにやって来た。そして、安息日に会堂に入って席に着いた。'),
('JPN', '使徒行传', 44, 13, 15, '律法と預言者たちの書の朗読があった後、会堂司たちは彼らのところに人を行かせて、こう言った。「兄弟たち。あなたがたに、この人たちのために何か奨励のことばがあれば、お話しください。」'),
('JPN', '使徒行传', 44, 13, 16, 'そこでパウロが立ち上がり、手振りで静かにさせてから言った。「イスラエル人の皆さん、ならびに神を恐れる方々、聞いてください。'),
('JPN', '使徒行传', 44, 13, 17, 'この民イスラエルの神は、私たちの父祖たちを選び、民がエジプトの地に滞在していた間にこれを強大にし、御腕を高く上げて、彼らをその地から導き出してくださいました。'),
('JPN', '使徒行传', 44, 13, 18, 'そして約四十年の間、荒野で彼らを耐え忍ばれ、'),
('JPN', '使徒行传', 44, 13, 19, 'カナンの地で七つの異邦の民を滅ぼした後、その地を彼らに相続財産として与えられました。'),
('JPN', '使徒行传', 44, 13, 20, '約四百五十年の間のことでした。その後、預言者サムエルの時まで、神はさばきつかさたちを与えられました。'),
('JPN', '使徒行传', 44, 13, 21, 'それから彼らが王を求めたので、神は彼らにベニヤミン族の人、キシュの子サウルを四十年間与えられました。'),
('JPN', '使徒行传', 44, 13, 22, 'そしてサウルを退けた後、神は彼らのために王としてダビデを立て、彼について証しして言われました。『わたしは、エッサイの子ダビデを見出した。彼はわたしの心にかなった者で、わたしが望むことをすべて成し遂げる。』'),
('JPN', '使徒行传', 44, 13, 23, '神は約束にしたがって、このダビデの子孫から、イスラエルに救い主イエスを送ってくださいました。'),
('JPN', '使徒行传', 44, 13, 24, 'この方が来られる前に、ヨハネがイスラエルのすべての民に、悔い改めのバプテスマをあらかじめ宣べ伝えました。'),
('JPN', '使徒行传', 44, 13, 25, 'ヨハネは、その生涯を終えようとしたとき、こう言いました。『あなたがたは、私をだれだと思っているのですか。私はその方ではありません。見なさい。その方は私の後から来られます。私には、その方の足の履き物のひもを解く値打ちもありません。』'),
('JPN', '使徒行传', 44, 13, 26, 'アブラハムの子孫である兄弟たち、ならびに、あなたがたのうちの神を恐れる方々。この救いのことばは、私たちに送られたのです。'),
('JPN', '使徒行传', 44, 13, 27, 'エルサレムに住む人々とその指導者たちは、このイエスを認めず、また安息日ごとに読まれる預言者たちのことばを理解せず、イエスを罪に定めて、預言を成就させました。'),
('JPN', '使徒行传', 44, 13, 28, 'そして、死に値する罪が何も見出せなかったのに、イエスを殺すことをピラトに求めたのです。'),
('JPN', '使徒行传', 44, 13, 29, 'こうして、彼らはイエスについて書かれていることをすべて成し終えた後、イエスを木から降ろして、墓に納めました。'),
('JPN', '使徒行传', 44, 13, 30, 'しかし、神はイエスを死者の中からよみがえらせました。'),
('JPN', '使徒行传', 44, 13, 31, 'イエスは、ご自分と一緒にガリラヤからエルサレムに上った人たちに、何日にもわたって現れました。その人たちが今、この民に対してイエスの証人となっています。'),
('JPN', '使徒行传', 44, 13, 32, '私たちもあなたがたに、神が父祖たちに約束された福音を宣べ伝えています。'),
('JPN', '使徒行传', 44, 13, 33, '神はイエスをよみがえらせ、彼らの子孫である私たちにその約束を成就してくださいました。詩篇の第二篇に、『あなたはわたしの子。わたしが今日、あなたを生んだ』と書かれているとおりです。'),
('JPN', '使徒行传', 44, 13, 34, 'そして、神がイエスを死者の中からよみがえらせて、もはや朽ちて滅びることがない方とされたことについては、こう言っておられました。『わたしはダビデへの確かで真実な約束を、あなたがたに与える。』'),
('JPN', '使徒行传', 44, 13, 35, 'ですから、ほかの箇所でもこう言っておられます。『あなたは、あなたにある敬虔な者に滅びをお見せになりません。』'),
('JPN', '使徒行传', 44, 13, 36, 'ダビデは、彼の生きた時代に神のみこころに仕えた後、死んで先祖たちの仲間に加えられ、朽ちて滅びることになりました。'),
('JPN', '使徒行传', 44, 13, 37, 'しかし、神がよみがえらせた方は、朽ちて滅びることがありませんでした。'),
('JPN', '使徒行传', 44, 13, 38, 'ですから、兄弟たち、あなたがたに知っていただきたい。このイエスを通して罪の赦しが宣べ伝えられているのです。また、モーセの律法を通しては義と認められることができなかったすべてのことについて、'),
('JPN', '使徒行传', 44, 13, 39, 'この方によって、信じる者はみな義と認められるのです。'),
('JPN', '使徒行传', 44, 13, 40, 'ですから、預言者たちの書に言われているようなことが起こらないように、気をつけなさい。'),
('JPN', '使徒行传', 44, 13, 41, '『見よ、嘲る者たち。驚け。そして消え去れ。わたしが一つの事をあなたがたの時代に行うからだ。それは、だれかが告げても、あなたがたには信じがたいことである。』」'),
('JPN', '使徒行传', 44, 13, 42, '二人が会堂を出るとき、人々は、次の安息日にも同じことについて話してくれるように頼んだ。'),
('JPN', '使徒行传', 44, 13, 43, '会堂の集会が終わってからも、多くのユダヤ人と神を敬う改宗者たちがパウロとバルナバについて来たので、二人は彼らと語り合い、神の恵みにとどまるように説得した。'),
('JPN', '使徒行传', 44, 13, 44, '次の安息日には、ほぼ町中の人々が、主のことばを聞くために集まって来た。'),
('JPN', '使徒行传', 44, 13, 45, 'しかし、この群衆を見たユダヤ人たちはねたみに燃え、パウロが語ることに反対し、口汚くののしった。'),
('JPN', '使徒行传', 44, 13, 46, 'そこで、パウロとバルナバは大胆に語った。「神のことばは、まずあなたがたに語られなければなりませんでした。しかし、あなたがたはそれを拒んで、自分自身を永遠のいのちにふさわしくない者にしています。ですから、見なさい、私たちはこれから異邦人たちの方に向かいます。'),
('JPN', '使徒行传', 44, 13, 47, '主が私たちに、こう命じておられるからです。『わたしはあなたを異邦人の光とし、地の果てにまで救いをもたらす者とする。』」'),
('JPN', '使徒行传', 44, 13, 48, '異邦人たちはこれを聞いて喜び、主のことばを賛美した。そして、永遠のいのちにあずかるように定められていた人たちはみな、信仰に入った。'),
('JPN', '使徒行传', 44, 13, 49, 'こうして主のことばは、この地方全体に広まった。'),
('JPN', '使徒行传', 44, 13, 50, 'ところが、ユダヤ人たちは、神を敬う貴婦人たちや町のおもだった人たちを扇動して、パウロとバルナバを迫害させ、二人をその地方から追い出した。'),
('JPN', '使徒行传', 44, 13, 51, '二人は彼らに対して足のちりを払い落として、イコニオンに行った。'),
('JPN', '使徒行传', 44, 13, 52, '弟子たちは喜びと聖霊に満たされていた。'),
('JPN', '使徒行传', 44, 14, 1, 'イコニオンでも、同じことが起こった。二人がユダヤ人の会堂に入って話をすると、ユダヤ人もギリシア人も大勢の人々が信じた。'),
('JPN', '使徒行传', 44, 14, 2, 'ところが、信じようとしないユダヤ人たちは、異邦人たちを扇動して、兄弟たちに対して悪意を抱かせた。'),
('JPN', '使徒行传', 44, 14, 3, 'それでも、二人は長く滞在し、主によって大胆に語った。主は彼らの手によってしるしと不思議を行わせ、その恵みのことばを証しされた。'),
('JPN', '使徒行传', 44, 14, 4, 'すると、町の人々は二派に分かれ、一方はユダヤ人の側に、もう一方は使徒たちの側についた。'),
('JPN', '使徒行传', 44, 14, 5, '異邦人とユダヤ人が彼らの指導者たちと一緒になり、二人を辱めて石打ちにしようと企てたとき、'),
('JPN', '使徒行传', 44, 14, 6, '二人はそれを知って、リカオニアの町であるリステラとデルベ、およびその付近の地方に難を避け、'),
('JPN', '使徒行传', 44, 14, 7, 'そこで福音の宣教を続けた。'),
('JPN', '使徒行传', 44, 14, 8, 'さてリステラで、足の不自由な人が座っていた。彼は生まれつき足が動かず、これまで一度も歩いたことがなかった。'),
('JPN', '使徒行传', 44, 14, 9, '彼はパウロの話すことに耳を傾けていた。パウロは彼をじっと見つめ、癒やされるにふさわしい信仰があるのを見て、'),
('JPN', '使徒行传', 44, 14, 10, '大声で「自分の足で、まっすぐに立ちなさい」と言った。すると彼は飛び上がり、歩き出した。'),
('JPN', '使徒行传', 44, 14, 11, '群衆はパウロが行ったことを見て、声を張り上げ、リカオニア語で「神々が人間の姿をとって、私たちのところにお下りになった」と言った。'),
('JPN', '使徒行传', 44, 14, 12, 'そして、バルナバをゼウスと呼び、パウロがおもに話す人だったことから、パウロをヘルメスと呼んだ。'),
('JPN', '使徒行传', 44, 14, 13, 'すると、町の入り口にあるゼウス神殿の祭司が、雄牛数頭と花輪を門のところに持って来て、群衆と一緒にいけにえを献げようとした。'),
('JPN', '使徒行传', 44, 14, 14, 'これを聞いた使徒たち、バルナバとパウロは、衣を裂いて群衆の中に飛び込んで行き、叫んだ。'),
('JPN', '使徒行传', 44, 14, 15, '「皆さん、どうしてこんなことをするのですか。私たちもあなたがたと同じ人間です。そして、あなたがたがこのような空しいことから離れて、天と地と海、またそれらの中のすべてのものを造られた生ける神に立ち返るように、福音を宣べ伝えているのです。'),
('JPN', '使徒行传', 44, 14, 16, '神は、過ぎ去った時代には、あらゆる国の人々がそれぞれ自分の道を歩むままにしておられました。'),
('JPN', '使徒行传', 44, 14, 17, 'それでも、ご自分を証ししないでおられたのではありません。あなたがたに天からの雨と実りの季節を与え、食物と喜びであなたがたの心を満たすなど、恵みを施しておられたのです。」'),
('JPN', '使徒行传', 44, 14, 18, 'こう言って二人は、群衆が自分たちにいけにえを献げるのを、かろうじてやめさせた。'),
('JPN', '使徒行传', 44, 14, 19, 'ところが、アンティオキアとイコニオンからユダヤ人たちがやって来て、群衆を抱き込み、パウロを石打ちにした。彼らはパウロが死んだものと思って、町の外に引きずり出した。'),
('JPN', '使徒行传', 44, 14, 20, 'しかし、弟子たちがパウロを囲んでいると、彼は立ち上がって町に入って行った。そして翌日、バルナバとともにデルベに向かった。'),
('JPN', '使徒行传', 44, 14, 21, '二人はこの町で福音を宣べ伝え、多くの人々を弟子としてから、リステラ、イコニオン、アンティオキアへと引き返して、'),
('JPN', '使徒行传', 44, 14, 22, '弟子たちの心を強め、信仰にしっかりとどまるように勧めて、「私たちは、神の国に入るために、多くの苦しみを経なければならない」と語った。'),
('JPN', '使徒行传', 44, 14, 23, 'また、彼らのために教会ごとに長老たちを選び、断食して祈った後、彼らをその信じている主にゆだねた。'),
('JPN', '使徒行传', 44, 14, 24, '二人はピシディアを通ってパンフィリアに着き、'),
('JPN', '使徒行传', 44, 14, 25, 'ペルゲでみことばを語ってからアタリアに下り、'),
('JPN', '使徒行传', 44, 14, 26, 'そこから船出してアンティオキアに帰った。そこは、二人が今回成し終えた働きのために、神の恵みにゆだねられて送り出された所であった。'),
('JPN', '使徒行传', 44, 14, 27, 'そこに着くと、彼らは教会の人々を集め、神が自分たちとともに行われたすべてのことと、異邦人に信仰の門を開いてくださったことを報告した。'),
('JPN', '使徒行传', 44, 14, 28, 'そして二人は、しばらくの間、弟子たちとともに過ごした。'),
('JPN', '使徒行传', 44, 15, 1, 'さて、ある人々がユダヤから下って来て、兄弟たちに「モーセの慣習にしたがって割礼を受けなければ、あなたがたは救われない」と教えていた。'),
('JPN', '使徒行传', 44, 15, 2, 'それで、パウロやバルナバと彼らの間に激しい対立と論争が生じたので、パウロとバルナバ、そのほかの何人かが、この問題について使徒たちや長老たちと話し合うために、エルサレムに上ることになった。'),
('JPN', '使徒行传', 44, 15, 3, 'こうして彼らは教会の人々に送り出され、フェニキアとサマリアを通って行った。道々、異邦人の回心について詳しく伝えたので、すべての兄弟たちに大きな喜びをもたらした。'),
('JPN', '使徒行传', 44, 15, 4, 'エルサレムに着くと、彼らは教会の人々と使徒たちと長老たちに迎えられた。それで、神が彼らとともにいて行われたことをすべて報告した。'),
('JPN', '使徒行传', 44, 15, 5, 'ところが、パリサイ派の者で信者になった人たちが立ち上がり、「異邦人にも割礼を受けさせ、モーセの律法を守るように命じるべきである」と言った。'),
('JPN', '使徒行传', 44, 15, 6, 'そこで使徒たちと長老たちは、この問題について協議するために集まった。'),
('JPN', '使徒行传', 44, 15, 7, '多くの論争があった後、ペテロが立って彼らに言った。「兄弟たち。ご存じのとおり、神は以前にあなたがたの中から私をお選びになり、異邦人が私の口から福音のことばを聞いて信じるようにされました。'),
('JPN', '使徒行传', 44, 15, 8, 'そして、人の心をご存じである神は、私たちに与えられたのと同じように、異邦人にも聖霊を与えて、彼らのために証しをされました。'),
('JPN', '使徒行传', 44, 15, 9, '私たちと彼らの間に何の差別もつけず、彼らの心を信仰によってきよめてくださったのです。'),
('JPN', '使徒行传', 44, 15, 10, 'そうであるなら、なぜ今あなたがたは、私たちの先祖たちも私たちも負いきれなかったくびきを、あの弟子たちの首に掛けて、神を試みるのですか。'),
('JPN', '使徒行传', 44, 15, 11, '私たちは、主イエスの恵みによって救われると信じていますが、あの人たちも同じなのです。」'),
('JPN', '使徒行传', 44, 15, 12, 'すると、全会衆は静かになった。そして、バルナバとパウロが、神が彼らを通して異邦人の間で行われたしるしと不思議について話すのに、耳を傾けた。'),
('JPN', '使徒行传', 44, 15, 13, '二人が話し終えると、ヤコブが応じて言った。「兄弟たち、私の言うことを聞いてください。'),
('JPN', '使徒行传', 44, 15, 14, '神が初めに、どのように異邦人を顧みて、彼らの中から御名のために民をお召しになったかについては、シメオンが説明しました。'),
('JPN', '使徒行传', 44, 15, 15, '預言者たちのことばもこれと一致していて、次のように書かれています。'),
('JPN', '使徒行传', 44, 15, 16, '『その後、わたしは倒れているダビデの仮庵を再び建て直す。その廃墟を建て直し、それを堅く立てる。'),
('JPN', '使徒行传', 44, 15, 17, 'それは、人々のうちの残りの者とわたしの名で呼ばれるすべての異邦人が、主を求めるようになるためだ。'),
('JPN', '使徒行传', 44, 15, 18, '──昔から知らされていたこと、それを行う主のことば。』'),
('JPN', '使徒行传', 44, 15, 19, 'ですから、私の判断では、異邦人の間で神に立ち返る者たちを悩ませてはいけません。'),
('JPN', '使徒行传', 44, 15, 20, 'ただ、偶像に供えて汚れたものと、淫らな行いと、絞め殺したものと、血とを避けるように、彼らに書き送るべきです。'),
('JPN', '使徒行传', 44, 15, 21, 'モーセの律法は、昔から町ごとに宣べ伝える者たちがいて、安息日ごとに諸会堂で読まれているからです。」'),
('JPN', '使徒行传', 44, 15, 22, 'そこで、使徒たちと長老たちは、全教会とともに、自分たちの中から人を選んで、パウロとバルナバと一緒にアンティオキアに送ることに決めた。選ばれたのはバルサバと呼ばれるユダとシラスで、兄弟たちの間で指導的な人であった。'),
('JPN', '使徒行传', 44, 15, 23, '彼らはこの人たちに託して、こう書き送った。「兄弟である使徒たちと長老たちは、アンティオキア、シリア、キリキアにいる異邦人の兄弟たちに、あいさつを送ります。'),
('JPN', '使徒行传', 44, 15, 24, '私たちは何も指示していないのに、私たちの中のある者たちが出て行って、いろいろなことを言ってあなたがたを混乱させ、あなたがたの心を動揺させたと聞きました。'),
('JPN', '使徒行传', 44, 15, 25, 'そこで私たちは人を選び、私たちの愛するバルナバとパウロと一緒に、あなたがたのところに送ることを、全会一致で決めました。'),
('JPN', '使徒行传', 44, 15, 26, '私たちの主イエス・キリストの名のために、いのちを献げている、バルナバとパウロと一緒にです。'),
('JPN', '使徒行传', 44, 15, 27, 'こういうわけで、私たちはユダとシラスを遣わします。彼らは口頭で同じことを伝えるでしょう。'),
('JPN', '使徒行传', 44, 15, 28, '聖霊と私たちは、次の必要なことのほかには、あなたがたに、それ以上のどんな重荷も負わせないことを決めました。'),
('JPN', '使徒行传', 44, 15, 29, 'すなわち、偶像に供えたものと、血と、絞め殺したものと、淫らな行いを避けることです。これらを避けていれば、それで結構です。祝福を祈ります。」'),
('JPN', '使徒行传', 44, 15, 30, 'さて、一行は送り出されてアンティオキアに下り、教会の会衆を集めて手紙を手渡した。'),
('JPN', '使徒行传', 44, 15, 31, '人々はそれを読んで、その励ましのことばに喜んだ。'),
('JPN', '使徒行传', 44, 15, 32, 'ユダもシラスも預言者であったので、多くのことばをもって兄弟たちを励まし、力づけた。'),
('JPN', '使徒行传', 44, 15, 33, '二人は、しばらく滞在した後、兄弟たちの平安のあいさつに送られて、自分たちを遣わした人々のところに帰って行った。'),
('JPN', '使徒行传', 44, 15, 35, 'パウロとバルナバはアンティオキアにとどまって、ほかの多くの人々とともに、主のことばを教え、福音を宣べ伝えた。'),
('JPN', '使徒行传', 44, 15, 36, 'それから数日後、パウロはバルナバに言った。「さあ、先に主のことばを宣べ伝えたすべての町で、兄弟たちがどうしているか、また行って見て来ようではありませんか。」'),
('JPN', '使徒行传', 44, 15, 37, 'バルナバは、マルコと呼ばれるヨハネを一緒に連れて行くつもりであった。'),
('JPN', '使徒行传', 44, 15, 38, 'しかしパウロは、パンフィリアで一行から離れて働きに同行しなかった者は、連れて行かないほうがよいと考えた。'),
('JPN', '使徒行传', 44, 15, 39, 'こうして激しい議論になり、その結果、互いに別行動をとることになった。バルナバはマルコを連れて、船でキプロスに渡って行き、'),
('JPN', '使徒行传', 44, 15, 40, 'パウロはシラスを選び、兄弟たちから主の恵みにゆだねられて出発した。'),
('JPN', '使徒行传', 44, 15, 41, 'そしてシリアおよびキリキアを通り、諸教会を力づけた。'),
('JPN', '使徒行传', 44, 16, 1, 'それからパウロはデルベに、そしてリステラに行った。すると、そこにテモテという弟子がいた。信者であるユダヤ人女性の子で、父親はギリシア人であった。'),
('JPN', '使徒行传', 44, 16, 2, '彼は、リステラとイコニオンの兄弟たちの間で評判の良い人であった。'),
('JPN', '使徒行传', 44, 16, 3, 'パウロは、このテモテを連れて行きたかった。それで、その地方にいるユダヤ人たちのために、彼に割礼を受けさせた。彼の父親がギリシア人であることを、皆が知っていたからである。'),
('JPN', '使徒行传', 44, 16, 4, '彼らは町々を巡り、エルサレムの使徒たちと長老たちが決めた規定を、守るべきものとして人々に伝えた。'),
('JPN', '使徒行传', 44, 16, 5, 'こうして諸教会は信仰を強められ、人数も日ごとに増えていった。'),
('JPN', '使徒行传', 44, 16, 6, 'それから彼らは、アジアでみことばを語ることを聖霊によって禁じられたので、フリュギア・ガラテヤの地方を通って行った。'),
('JPN', '使徒行传', 44, 16, 7, 'こうしてミシアの近くまで来たとき、ビティニアに進もうとしたが、イエスの御霊がそれを許されなかった。'),
('JPN', '使徒行传', 44, 16, 8, 'それでミシアを通って、トロアスに下った。'),
('JPN', '使徒行传', 44, 16, 9, 'その夜、パウロは幻を見た。一人のマケドニア人が立って、「マケドニアに渡って来て、私たちを助けてください」と懇願するのであった。'),
('JPN', '使徒行传', 44, 16, 10, 'パウロがこの幻を見たとき、私たちはただちにマケドニアに渡ることにした。彼らに福音を宣べ伝えるために、神が私たちを召しておられるのだと確信したからである。'),
('JPN', '使徒行传', 44, 16, 11, '私たちはトロアスから船出して、サモトラケに直航し、翌日ネアポリスに着いた。'),
('JPN', '使徒行传', 44, 16, 12, 'そこからピリピに行った。この町はマケドニアのこの地方の主要な町で、植民都市であった。私たちはこの町に数日滞在した。'),
('JPN', '使徒行传', 44, 16, 13, 'そして安息日に、私たちは町の門の外に出て、祈り場があると思われた川岸に行き、そこに腰を下ろして、集まって来た女たちに話をした。'),
('JPN', '使徒行传', 44, 16, 14, 'リディアという名の女の人が聞いていた。ティアティラ市の紫布の商人で、神を敬う人であった。主は彼女の心を開いて、パウロの語ることに心を留めるようにされた。'),
('JPN', '使徒行传', 44, 16, 15, 'そして、彼女とその家族の者たちがバプテスマを受けたとき、彼女は「私が主を信じる者だとお思いでしたら、私の家に来てお泊まりください」と懇願し、無理やり私たちにそうさせた。'),
('JPN', '使徒行传', 44, 16, 16, 'さて、祈り場に行く途中のことであった。私たちは占いの霊につかれた若い女奴隷に出会った。この女は占いをして、主人たちに多くの利益を得させていた。'),
('JPN', '使徒行传', 44, 16, 17, '彼女はパウロや私たちの後について来て、「この人たちは、いと高き神のしもべたちで、救いの道をあなたがたに宣べ伝えています」と叫び続けた。'),
('JPN', '使徒行传', 44, 16, 18, '何日もこんなことをするので、困り果てたパウロは、振り向いてその霊に、「イエス・キリストの名によっておまえに命じる。この女から出て行け」と言った。すると、ただちに霊は出て行った。'),
('JPN', '使徒行传', 44, 16, 19, '彼女の主人たちは、金儲けする望みがなくなったのを見て、パウロとシラスを捕らえ、広場の役人たちのところに引き立てて行った。'),
('JPN', '使徒行传', 44, 16, 20, 'そして、二人を長官たちの前に引き出して言った。「この者たちはユダヤ人で、私たちの町をかき乱し、'),
('JPN', '使徒行传', 44, 16, 21, 'ローマ人である私たちが、受け入れることも行うことも許されていない風習を宣伝しております。」'),
('JPN', '使徒行传', 44, 16, 22, '群衆も二人に反対して立ったので、長官たちは、彼らの衣をはぎ取ってむちで打つように命じた。'),
('JPN', '使徒行传', 44, 16, 23, 'そして何度もむちで打たせてから二人を牢に入れ、看守に厳重に見張るように命じた。'),
('JPN', '使徒行传', 44, 16, 24, 'この命令を受けた看守は、二人を奥の牢に入れ、足には木の足かせをはめた。'),
('JPN', '使徒行传', 44, 16, 25, '真夜中ごろ、パウロとシラスは祈りつつ、神を賛美する歌を歌っていた。ほかの囚人たちはそれに聞き入っていた。'),
('JPN', '使徒行传', 44, 16, 26, 'すると突然、大きな地震が起こり、牢獄の土台が揺れ動き、たちまち扉が全部開いて、すべての囚人の鎖が外れてしまった。'),
('JPN', '使徒行传', 44, 16, 27, '目を覚ました看守は、牢の扉が開いているのを見て、囚人たちが逃げてしまったものと思い、剣を抜いて自殺しようとした。'),
('JPN', '使徒行传', 44, 16, 28, 'パウロは大声で「自害してはいけない。私たちはみなここにいる」と叫んだ。'),
('JPN', '使徒行传', 44, 16, 29, '看守は明かりを求めてから、牢の中に駆け込み、震えながらパウロとシラスの前にひれ伏した。'),
('JPN', '使徒行传', 44, 16, 30, 'そして二人を外に連れ出して、「先生方。救われるためには、何をしなければなりませんか」と言った。'),
('JPN', '使徒行传', 44, 16, 31, '二人は言った。「主イエスを信じなさい。そうすれば、あなたもあなたの家族も救われます。」'),
('JPN', '使徒行传', 44, 16, 32, 'そして、彼と彼の家にいる者全員に、主のことばを語った。'),
('JPN', '使徒行传', 44, 16, 33, '看守はその夜、時を移さず二人を引き取り、打ち傷を洗った。そして、彼とその家の者全員が、すぐにバプテスマを受けた。'),
('JPN', '使徒行传', 44, 16, 34, 'それから二人を家に案内して、食事のもてなしをし、神を信じたことを全家族とともに心から喜んだ。'),
('JPN', '使徒行传', 44, 16, 35, '夜が明けると、長官たちは警吏たちを遣わして、「あの者たちを釈放せよ」と言った。'),
('JPN', '使徒行传', 44, 16, 36, 'そこで、看守はこのことばをパウロに伝えて、「長官たちが、あなたがたを釈放するようにと、使いをよこしました。さあ牢を出て、安心してお行きください」と言った。'),
('JPN', '使徒行传', 44, 16, 37, 'しかし、パウロは警吏たちに言った。「長官たちは、ローマ市民である私たちを、有罪判決を受けていないのに公衆の前でむち打ち、牢に入れました。それなのに、今ひそかに私たちを去らせるのですか。それはいけない。彼ら自身が来て、私たちを外に出すべきです。」'),
('JPN', '使徒行传', 44, 16, 38, '警吏たちは、このことばを長官たちに報告した。すると長官たちは、二人がローマ市民であると聞いて恐れ、'),
('JPN', '使徒行传', 44, 16, 39, '自分たちで出向いて来て、二人をなだめた。そして牢から外に出し、町から立ち去るように頼んだ。'),
('JPN', '使徒行传', 44, 16, 40, '牢を出た二人はリディアの家に行った。そして兄弟たちに会い、彼らを励ましてから立ち去った。'),
('JPN', '使徒行传', 44, 17, 1, 'パウロとシラスは、アンピポリスとアポロニアを通って、テサロニケに行った。そこにはユダヤ人の会堂があった。'),
('JPN', '使徒行传', 44, 17, 2, 'パウロは、いつものように人々のところに入って行き、三回の安息日にわたって、聖書に基づいて彼らと論じ合った。'),
('JPN', '使徒行传', 44, 17, 3, 'そして、「キリストは苦しみを受け、死者の中からよみがえらなければならなかったのです。私があなたがたに宣べ伝えている、このイエスこそキリストです」と説明し、また論証した。'),
('JPN', '使徒行传', 44, 17, 4, '彼らのうちのある者たちは納得して、パウロとシラスに従った。神を敬う大勢のギリシア人たちや、かなりの数の有力な婦人たちも同様であった。'),
('JPN', '使徒行传', 44, 17, 5, 'ところが、ユダヤ人たちはねたみに駆られ、広場にいるならず者たちを集め、暴動を起こして町を混乱させた。そしてヤソンの家を襲い、二人を捜して集まった会衆の前に引き出そうとした。'),
('JPN', '使徒行传', 44, 17, 6, 'しかし、二人が見つからないので、ヤソンと兄弟たち何人かを町の役人たちのところに引いて行き、大声で言った。「世界中を騒がせてきた者たちが、ここにも来ています。'),
('JPN', '使徒行传', 44, 17, 7, 'ヤソンが家に迎え入れたのです。彼らはみな、『イエスという別の王がいる』と言って、カエサルの詔勅に背く行いをしています。」'),
('JPN', '使徒行传', 44, 17, 8, 'これを聞いた群衆と町の役人たちは動揺した。'),
('JPN', '使徒行传', 44, 17, 9, '役人たちは、ヤソンとほかの者たちから保証金を取ったうえで釈放した。'),
('JPN', '使徒行传', 44, 17, 10, '兄弟たちはすぐ、夜のうちにパウロとシラスをベレアに送り出した。そこに着くと、二人はユダヤ人の会堂に入って行った。'),
('JPN', '使徒行传', 44, 17, 11, 'この町のユダヤ人は、テサロニケにいる者たちよりも素直で、非常に熱心にみことばを受け入れ、はたしてそのとおりかどうか、毎日聖書を調べた。'),
('JPN', '使徒行传', 44, 17, 12, 'それで彼らのうちの多くの人たちが信じた。また、ギリシアの貴婦人たち、そして男たちも少なからず信じた。'),
('JPN', '使徒行传', 44, 17, 13, 'ところが、テサロニケのユダヤ人たちが、ベレアでもパウロによって神のことばが伝えられていることを知り、そこにもやって来て、群衆を扇動して騒ぎを起こした。'),
('JPN', '使徒行传', 44, 17, 14, 'そこで兄弟たちは、すぐにパウロを送り出して海岸まで行かせたが、シラスとテモテはベレアにとどまった。'),
('JPN', '使徒行传', 44, 17, 15, 'パウロを案内した人たちは、彼をアテネまで連れて行った。そして、できるだけ早く彼のところに来るようにという、シラスとテモテに対する指示を受けて、その人たちは帰途についた。'),
('JPN', '使徒行传', 44, 17, 16, 'さて、パウロはアテネで二人を待っていたが、町が偶像でいっぱいなのを見て、心に憤りを覚えた。'),
('JPN', '使徒行传', 44, 17, 17, 'それでパウロは、会堂ではユダヤ人たちや神を敬う人たちと論じ、広場ではそこに居合わせた人たちと毎日論じ合った。'),
('JPN', '使徒行传', 44, 17, 18, 'エピクロス派とストア派の哲学者たちも何人か、パウロと議論していたが、ある者たちは「このおしゃべりは、何が言いたいのか」と言い、ほかの者たちは「彼は他国の神々の宣伝者のようだ」と言った。パウロが、イエスと復活を宣べ伝えていたからである。'),
('JPN', '使徒行传', 44, 17, 19, 'そこで彼らは、パウロをアレオパゴスに連れて行き、こう言った。「あなたが語っているその新しい教えがどんなものか、知ることができるでしょうか。'),
('JPN', '使徒行传', 44, 17, 20, '私たちには耳慣れないことを聞かせてくださるので、それがいったいどんなことなのか、知りたいのです。」'),
('JPN', '使徒行传', 44, 17, 21, 'アテネ人も、そこに滞在する他国人もみな、何か新しいことを話したり聞いたりすることだけで、日を過ごしていた。'),
('JPN', '使徒行传', 44, 17, 22, 'パウロは、アレオパゴスの中央に立って言った。「アテネの人たち。あなたがたは、あらゆる点で宗教心にあつい方々だと、私は見ております。'),
('JPN', '使徒行传', 44, 17, 23, '道を通りながら、あなたがたの拝むものをよく見ているうちに、『知られていない神に』と刻まれた祭壇があるのを見つけたからです。そこで、あなたがたが知らずに拝んでいるもの、それを教えましょう。'),
('JPN', '使徒行传', 44, 17, 24, 'この世界とその中にあるすべてのものをお造りになった神は、天地の主ですから、手で造られた宮にお住みにはなりません。'),
('JPN', '使徒行传', 44, 17, 25, 'また、何かが足りないかのように、人の手によって仕えられる必要もありません。神ご自身がすべての人に、いのちと息と万物を与えておられるのですから。'),
('JPN', '使徒行传', 44, 17, 26, '神は、一人の人からあらゆる民を造り出して、地の全面に住まわせ、それぞれに決められた時代と、住まいの境をお定めになりました。'),
('JPN', '使徒行传', 44, 17, 27, 'それは、神を求めさせるためです。もし人が手探りで求めることがあれば、神を見出すこともあるでしょう。確かに、神は私たち一人ひとりから遠く離れてはおられません。'),
('JPN', '使徒行传', 44, 17, 28, '『私たちは神の中に生き、動き、存在している』のです。あなたがたのうちのある詩人たちも、『私たちもまた、その子孫である』と言ったとおりです。'),
('JPN', '使徒行传', 44, 17, 29, 'そのように私たちは神の子孫ですから、神である方を金や銀や石、人間の技術や考えで造ったものと同じであると、考えるべきではありません。'),
('JPN', '使徒行传', 44, 17, 30, '神はそのような無知の時代を見過ごしておられましたが、今はどこででも、すべての人に悔い改めを命じておられます。'),
('JPN', '使徒行传', 44, 17, 31, 'なぜなら、神は日を定めて、お立てになった一人の方により、義をもってこの世界をさばこうとしておられるからです。神はこの方を死者の中からよみがえらせて、その確証をすべての人にお与えになったのです。」'),
('JPN', '使徒行传', 44, 17, 32, '死者の復活のことを聞くと、ある人たちはあざ笑ったが、ほかの人たちは「そのことについては、もう一度聞くことにしよう」と言った。'),
('JPN', '使徒行传', 44, 17, 33, 'こうして、パウロは彼らの中から出て行った。'),
('JPN', '使徒行传', 44, 17, 34, 'ある人々は彼につき従い、信仰に入った。その中には、アレオパゴスの裁判官ディオヌシオ、ダマリスという名の女の人、そのほかの人たちもいた。'),
('JPN', '使徒行传', 44, 18, 1, 'その後、パウロはアテネを去ってコリントに行った。'),
('JPN', '使徒行传', 44, 18, 2, 'そこで、ポントス生まれでアキラという名のユダヤ人と、彼の妻プリスキラに出会った。クラウディウス帝が、すべてのユダヤ人をローマから退去させるように命じたので、最近イタリアから来ていたのである。パウロは二人のところに行き、'),
('JPN', '使徒行传', 44, 18, 3, '自分も同業者であったので、その家に住んで一緒に仕事をした。彼らの職業は天幕作りであった。'),
('JPN', '使徒行传', 44, 18, 4, 'パウロは安息日ごとに会堂で論じ、ユダヤ人やギリシア人を説得しようとした。'),
('JPN', '使徒行传', 44, 18, 5, 'シラスとテモテがマケドニアから下って来ると、パウロはみことばを語ることに専念し、イエスがキリストであることをユダヤ人たちに証しした。'),
('JPN', '使徒行传', 44, 18, 6, 'しかし、彼らが反抗して口汚くののしったので、パウロは衣のちりを振り払って言った。「あなたがたの血は、あなたがたの頭上に降りかかれ。私には責任がない。今から私は異邦人のところに行く。」'),
('JPN', '使徒行传', 44, 18, 7, 'そして、そこを去って、ティティオ・ユストという名の、神を敬う人の家に行った。その家は会堂の隣にあった。'),
('JPN', '使徒行传', 44, 18, 8, '会堂司クリスポは、家族全員とともに主を信じた。また、多くのコリント人も聞いて信じ、バプテスマを受けた。'),
('JPN', '使徒行传', 44, 18, 9, 'ある夜、主は幻によってパウロに言われた。「恐れないで、語り続けなさい。黙ってはいけない。'),
('JPN', '使徒行传', 44, 18, 10, 'わたしがあなたとともにいるので、あなたを襲って危害を加える者はいない。この町には、わたしの民がたくさんいるのだから。」'),
('JPN', '使徒行传', 44, 18, 11, 'そこで、パウロは一年六か月の間腰を据えて、彼らの間で神のことばを教え続けた。'),
('JPN', '使徒行传', 44, 18, 12, 'ところが、ガリオがアカイアの地方総督であったとき、ユダヤ人たちは一斉にパウロに反抗して立ち上がり、彼を法廷に引いて行って、'),
('JPN', '使徒行传', 44, 18, 13, '「この人は、律法に反するやり方で神を拝むよう、人々をそそのかしています」と言った。'),
('JPN', '使徒行传', 44, 18, 14, 'パウロが口を開こうとすると、ガリオはユダヤ人に向かって言った。「ユダヤ人の諸君。不正な行為や悪質な犯罪のことであれば、私は当然あなたがたの訴えを取り上げるが、'),
('JPN', '使徒行传', 44, 18, 15, 'ことばや名称やあなたがたの律法に関する問題であれば、自分たちで解決するがよい。私はそのようなことの裁判官になりたくはない。」'),
('JPN', '使徒行传', 44, 18, 16, 'そうして彼らを法廷から追い出した。'),
('JPN', '使徒行传', 44, 18, 17, 'そこで皆は会堂司ソステネを捕らえ、法廷の前で打ちたたいた。ガリオは、そのようなことは少しも気にしなかった。'),
('JPN', '使徒行传', 44, 18, 18, 'パウロは、なおしばらく滞在してから、兄弟たちに別れを告げて、シリアへ向けて船で出発した。プリスキラとアキラも同行した。パウロは誓願を立てていたので、ケンクレアで髪を剃った。'),
('JPN', '使徒行传', 44, 18, 19, '彼らがエペソに着くと、パウロは二人を残し、自分だけ会堂に入って、ユダヤ人たちと論じ合った。'),
('JPN', '使徒行传', 44, 18, 20, '人々は、もっと長くとどまるように頼んだが、パウロは聞き入れず、'),
('JPN', '使徒行传', 44, 18, 21, '「神のみこころなら、またあなたがたのところに戻って来ます」と言って別れを告げ、エペソから船出した。'),
('JPN', '使徒行传', 44, 18, 22, 'それからカイサリアに上陸してエルサレムに上り、教会にあいさつしてからアンティオキアに下って行った。'),
('JPN', '使徒行传', 44, 18, 23, 'パウロはアンティオキアにしばらく滞在した後、また出発し、ガラテヤの地方やフリュギアを次々に巡って、すべての弟子たちを力づけた。'),
('JPN', '使徒行传', 44, 18, 24, 'さて、アレクサンドリア生まれでアポロという名の、雄弁なユダヤ人がエペソに来た。彼は聖書に通じていた。'),
('JPN', '使徒行传', 44, 18, 25, 'この人は主の道について教えを受け、霊に燃えてイエスのことを正確に語ったり教えたりしていたが、ヨハネのバプテスマしか知らなかった。'),
('JPN', '使徒行传', 44, 18, 26, '彼は会堂で大胆に語り始めた。それを聞いたプリスキラとアキラは、彼をわきに呼んで、神の道をもっと正確に説明した。'),
('JPN', '使徒行传', 44, 18, 27, 'アポロはアカイアに渡りたいと思っていたので、兄弟たちは彼を励まし、彼を歓迎してくれるようにと、弟子たちに手紙を書いた。彼はそこに着くと、恵みによって信者になっていた人たちを、大いに助けた。'),
('JPN', '使徒行传', 44, 18, 28, '聖書によってイエスがキリストであることを証明し、人々の前で力強くユダヤ人たちを論破したからである。'),
('JPN', '使徒行传', 44, 19, 1, 'アポロがコリントにいたときのことであった。パウロは内陸の地方を通ってエペソに下り、何人かの弟子たちに出会った。'),
('JPN', '使徒行传', 44, 19, 2, '彼らに「信じたとき、聖霊を受けましたか」と尋ねると、彼らは「いいえ、聖霊がおられるのかどうか、聞いたこともありません」と答えた。'),
('JPN', '使徒行传', 44, 19, 3, '「それでは、どのようなバプテスマを受けたのですか」と尋ねると、彼らは「ヨハネのバプテスマです」と答えた。'),
('JPN', '使徒行传', 44, 19, 4, 'そこでパウロは言った。「ヨハネは、自分の後に来られる方、すなわちイエスを信じるように人々に告げ、悔い改めのバプテスマを授けたのです。」'),
('JPN', '使徒行传', 44, 19, 5, 'これを聞いた彼らは、主イエスの名によってバプテスマを受けた。'),
('JPN', '使徒行传', 44, 19, 6, 'パウロが彼らの上に手を置くと、聖霊が彼らに臨み、彼らは異言を語ったり、預言したりした。'),
('JPN', '使徒行传', 44, 19, 7, 'その人たちは、全員で十二人ほどであった。'),
('JPN', '使徒行传', 44, 19, 8, 'パウロは会堂に入って、三か月の間大胆に語り、神の国について論じて、人々を説得しようと努めた。'),
('JPN', '使徒行传', 44, 19, 9, 'しかし、ある者たちが心を頑なにして聞き入れず、会衆の前でこの道のことを悪く言ったので、パウロは彼らから離れ、弟子たちも退かせて、毎日ティラノの講堂で論じた。'),
('JPN', '使徒行传', 44, 19, 10, 'これが二年続いたので、アジアに住む人々はみな、ユダヤ人もギリシア人も主のことばを聞いた。'),
('JPN', '使徒行传', 44, 19, 11, '神はパウロの手によって、驚くべき力あるわざを行われた。'),
('JPN', '使徒行传', 44, 19, 12, '彼が身に着けていた手ぬぐいや前掛けを、持って行って病人たちに当てると、病気が去り、悪霊も出て行くほどであった。'),
('JPN', '使徒行传', 44, 19, 13, 'ところが、ユダヤ人の巡回祈祷師のうちの何人かが、悪霊につかれている人たちに向かって、試しに主イエスの名を唱え、「パウロの宣べ伝えているイエスによって、おまえたちに命じる」と言ってみた。'),
('JPN', '使徒行传', 44, 19, 14, 'このようなことをしていたのは、ユダヤ人の祭司長スケワという人の七人の息子たちであった。'),
('JPN', '使徒行传', 44, 19, 15, 'すると、悪霊が彼らに答えた。「イエスのことは知っているし、パウロのこともよく知っている。しかし、おまえたちは何者だ。」'),
('JPN', '使徒行传', 44, 19, 16, 'そして、悪霊につかれている人が彼らに飛びかかり、皆を押さえつけ、打ち負かしたので、彼らは裸にされ、傷を負ってその家から逃げ出した。'),
('JPN', '使徒行传', 44, 19, 17, 'このことが、エペソに住むユダヤ人とギリシア人のすべてに知れ渡ったので、みな恐れを抱き、主イエスの名をあがめるようになった。'),
('JPN', '使徒行传', 44, 19, 18, 'そして、信仰に入った人たちが大勢やって来て、自分たちのしていた行為を告白し、明らかにした。'),
('JPN', '使徒行传', 44, 19, 19, 'また魔術を行っていた者たちが多数、その書物を持って来て、皆の前で焼き捨てた。その値段を合計すると、銀貨五万枚になった。'),
('JPN', '使徒行传', 44, 19, 20, 'こうして、主のことばは力強く広まり、勢いを得ていった。'),
('JPN', '使徒行传', 44, 19, 21, 'これらのことがあった後、パウロは御霊に示され、マケドニアとアカイアを通ってエルサレムに行くことにした。そして、「私はそこに行ってから、ローマも見なければならない」と言った。'),
('JPN', '使徒行传', 44, 19, 22, 'そこで、自分に仕えている者たちのうちの二人、テモテとエラストをマケドニアに遣わし、自分自身はなおしばらくアジアにとどまっていた。'),
('JPN', '使徒行传', 44, 19, 23, 'そのころ、この道のことで、大変な騒ぎが起こった。'),
('JPN', '使徒行传', 44, 19, 24, 'デメテリオという名の銀細工人がいて、銀でアルテミス神殿の模型を造り、職人たちにかなりの収入を得させていたが、'),
('JPN', '使徒行传', 44, 19, 25, 'その職人たちや同業の者たちを集めて、こう言ったのである。「皆さん。ご承知のとおり、私たちが繁盛しているのはこの仕事のおかげです。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '使徒行传', 44, 19, 26, 'ところが、見聞きしているように、あのパウロが、手で造った物は神ではないと言って、エペソだけでなく、アジアのほぼ全域にわたって、大勢の人々を説き伏せ、迷わせてしまいました。'),
('JPN', '使徒行传', 44, 19, 27, 'これでは、私たちの仕事の評判が悪くなる恐れがあるばかりか、偉大な女神アルテミスの神殿も軽んじられ、全アジア、全世界が拝むこの女神のご威光さえも失われそうです。」'),
('JPN', '使徒行传', 44, 19, 28, 'これを聞くと彼らは激しく怒り、「偉大なるかな、エペソ人のアルテミス」と叫び始めた。'),
('JPN', '使徒行传', 44, 19, 29, 'そして町中が大混乱に陥り、人々はパウロの同行者である、マケドニア人ガイオとアリスタルコを捕らえ、一団となって劇場になだれ込んだ。'),
('JPN', '使徒行传', 44, 19, 30, 'パウロはその集まった会衆の中に入って行こうとしたが、弟子たちがそうさせなかった。'),
('JPN', '使徒行传', 44, 19, 31, 'パウロの友人でアジア州の高官であった人たちも、パウロに使いを送り、劇場に入って行かないようにと懇願した。'),
('JPN', '使徒行传', 44, 19, 32, '人々は、それぞれ違ったことを叫んでいた。実際、集会は混乱状態で、大多数の人たちは、何のために集まったのかさえ知らなかった。'),
('JPN', '使徒行传', 44, 19, 33, '群衆のうちのある者たちは、ユダヤ人たちが前に押し出したアレクサンドロに話すよう促した。そこで、彼は手振りで静かにさせてから、集まった会衆に弁明しようとした。'),
('JPN', '使徒行传', 44, 19, 34, 'しかし、彼がユダヤ人だと分かると、みな一斉に声をあげ、「偉大なるかな、エペソ人のアルテミス」と二時間ほど叫び続けた。'),
('JPN', '使徒行传', 44, 19, 35, 'そこで、町の書記官が群衆を静めて言った。「エペソの皆さん。エペソの町が、偉大な女神アルテミスと、天から下ったご神体との守護者であることを知らない人が、だれかいるでしょうか。'),
('JPN', '使徒行传', 44, 19, 36, 'これらのことは否定できないことですから、皆さんは静かにして、決して無謀なことをしてはなりません。'),
('JPN', '使徒行传', 44, 19, 37, '皆さんは、この人たちをここに連れて来ましたが、彼らは神殿を汚した者でも、私たちの女神を冒瀆した者でもありません。'),
('JPN', '使徒行传', 44, 19, 38, 'ですから、もしデメテリオと仲間の職人たちが、だれかに対して苦情があるなら、裁判も開かれるし地方総督たちもいることですから、互いに訴え出たらよいのです。'),
('JPN', '使徒行传', 44, 19, 39, 'もし、あなたがたがこれ以上何かを要求するのなら、正式な集会で解決してもらうことになります。'),
('JPN', '使徒行传', 44, 19, 40, '今日の事件については、正当な理由がないのですから、騒乱罪に問われる恐れがあります。その点に関しては、私たちはこの騒動を弁護できません。」こう言って、その集まりを解散させた。'),
('JPN', '使徒行传', 44, 20, 1, '騒ぎが収まると、パウロは弟子たちを呼び集めて励まし、別れを告げ、マケドニアに向けて出発した。'),
('JPN', '使徒行传', 44, 20, 2, 'そして、その地方を通り、多くのことばをもって弟子たちを励まし、ギリシアに来て、'),
('JPN', '使徒行传', 44, 20, 3, 'そこで三か月を過ごした。そして、シリアに向けて船出しようとしていたときに、パウロに対するユダヤ人の陰謀があったため、彼はマケドニアを通って帰ることにした。'),
('JPN', '使徒行传', 44, 20, 4, '彼に同行していたのは、ピロの子であるベレア人ソパテロ、テサロニケ人のアリスタルコとセクンド、デルベ人のガイオ、テモテ、アジア人のティキコとトロフィモであった。'),
('JPN', '使徒行传', 44, 20, 5, 'この人たちは先に行って、トロアスで私たちを待っていた。'),
('JPN', '使徒行传', 44, 20, 6, '私たちは、種なしパンの祭りの後にピリピから船出した。五日のうちに、トロアスにいる彼らのところに行き、そこで七日間滞在した。'),
('JPN', '使徒行传', 44, 20, 7, '週の初めの日に、私たちはパンを裂くために集まった。パウロは翌日に出発することにしていたので、人々と語り合い、夜中まで語り続けた。'),
('JPN', '使徒行传', 44, 20, 8, '私たちが集まっていた屋上の間には、ともしびがたくさんついていた。'),
('JPN', '使徒行传', 44, 20, 9, 'ユテコという名の一人の青年が、窓のところに腰掛けていたが、パウロの話が長く続くので、ひどく眠気がさし、とうとう眠り込んで三階から下に落ちてしまった。抱き起こしてみると、もう死んでいた。'),
('JPN', '使徒行传', 44, 20, 10, 'しかし、パウロは降りて行って彼の上に身をかがめ、抱きかかえて、「心配することはない。まだいのちがあります」と言った。'),
('JPN', '使徒行传', 44, 20, 11, 'そして、また上がって行ってパンを裂いて食べ、明け方まで長く語り合って、それから出発した。'),
('JPN', '使徒行传', 44, 20, 12, '人々は生き返った青年を連れて帰り、ひとかたならず慰められた。'),
('JPN', '使徒行传', 44, 20, 13, '私たちは先に船に乗り込んで、アソスに向けて船出した。そこからパウロを船に乗せることになっていた。パウロ自身は陸路をとるつもりでいて、そのように決めていたのである。'),
('JPN', '使徒行传', 44, 20, 14, 'こうしてパウロはアソスで私たちと落ち合い、私たちは彼を船に乗せてミティレネに行った。'),
('JPN', '使徒行传', 44, 20, 15, '翌日そこから船出して、キオスの沖に達し、その次の日にサモスに立ち寄り、さらにその翌日にはミレトスに着いた。'),
('JPN', '使徒行传', 44, 20, 16, 'パウロは、アジアで時間を取られないようにと、エペソには寄らずに航海を続けることに決めていた。彼は、できれば五旬節の日にはエルサレムに着いていたいと、急いでいたのである。'),
('JPN', '使徒行传', 44, 20, 17, 'パウロはミレトスからエペソに使いを送って、教会の長老たちを呼び寄せた。'),
('JPN', '使徒行传', 44, 20, 18, '彼らが集まって来たとき、パウロはこう語った。「あなたがたは、私がアジアに足を踏み入れた最初の日から、いつもどのようにあなたがたと過ごしてきたか、よくご存じです。'),
('JPN', '使徒行传', 44, 20, 19, '私は、ユダヤ人の陰謀によってこの身に降りかかる数々の試練の中で、謙遜の限りを尽くし、涙とともに主に仕えてきました。'),
('JPN', '使徒行传', 44, 20, 20, '益になることは、公衆の前でも家々でも、余すところなくあなたがたに伝え、また教えてきました。'),
('JPN', '使徒行传', 44, 20, 21, 'ユダヤ人にもギリシア人にも、神に対する悔い改めと、私たちの主イエスに対する信仰を証ししてきたのです。'),
('JPN', '使徒行传', 44, 20, 22, 'ご覧なさい。私は今、御霊に縛られてエルサレムに行きます。そこで私にどんなことが起こるのか、分かりません。'),
('JPN', '使徒行传', 44, 20, 23, 'ただ、聖霊がどの町でも私に証しして言われるのは、鎖と苦しみが私を待っているということです。'),
('JPN', '使徒行传', 44, 20, 24, 'けれども、私が自分の走るべき道のりを走り尽くし、主イエスから受けた、神の恵みの福音を証しする任務を全うできるなら、自分のいのちは少しも惜しいとは思いません。'),
('JPN', '使徒行传', 44, 20, 25, '今、私には分かっています。御国を宣べ伝えてあなたがたの間を巡回した私の顔を、あなたがたはだれも二度と見ることがないでしょう。'),
('JPN', '使徒行传', 44, 20, 26, 'ですから、今日この日、あなたがたに宣言します。私は、だれの血に対しても責任がありません。'),
('JPN', '使徒行传', 44, 20, 27, '私は神のご計画のすべてを、余すところなくあなたがたに知らせたからです。'),
('JPN', '使徒行传', 44, 20, 28, 'あなたがたは自分自身と群れの全体に気を配りなさい。神がご自分の血をもって買い取られた神の教会を牧させるために、聖霊はあなたがたを群れの監督にお立てになったのです。'),
('JPN', '使徒行传', 44, 20, 29, '私は知っています。私が去った後、狂暴な狼があなたがたの中に入り込んで来て、容赦なく群れを荒らし回ります。'),
('JPN', '使徒行传', 44, 20, 30, 'また、あなたがた自身の中からも、いろいろと曲がったことを語って、弟子たちを自分のほうに引き込もうとする者たちが起こってくるでしょう。'),
('JPN', '使徒行传', 44, 20, 31, 'ですから、私が三年の間、夜も昼も、涙とともにあなたがた一人ひとりを訓戒し続けてきたことを思い起こして、目を覚ましていなさい。'),
('JPN', '使徒行传', 44, 20, 32, '今私は、あなたがたを神とその恵みのみことばにゆだねます。みことばは、あなたがたを成長させ、聖なるものとされたすべての人々とともに、あなたがたに御国を受け継がせることができるのです。'),
('JPN', '使徒行传', 44, 20, 33, '私は、人の金銀や衣服を貪ったことはありません。'),
('JPN', '使徒行传', 44, 20, 34, 'あなたがた自身が知っているとおり、私の両手は、自分の必要のためにも、ともにいる人たちのためにも働いてきました。'),
('JPN', '使徒行传', 44, 20, 35, 'このように労苦して、弱い者を助けなければならないこと、また、主イエスご自身が『受けるよりも与えるほうが幸いである』と言われたみことばを、覚えているべきだということを、私はあらゆることを通してあなたがたに示してきたのです。」'),
('JPN', '使徒行传', 44, 20, 36, 'こう言ってから、パウロは皆とともに、ひざまずいて祈った。'),
('JPN', '使徒行传', 44, 20, 37, '皆は声をあげて泣き、パウロの首を抱いて何度も口づけした。'),
('JPN', '使徒行传', 44, 20, 38, '「もう二度と私の顔を見ることがないでしょう」と言った彼のことばに、特に心を痛めたのである。それから、彼らはパウロを船まで見送った。'),
('JPN', '使徒行传', 44, 21, 1, '私たちは、彼らと別れて船出した。コスに直航し、翌日ロドスに着き、そこからパタラに渡った。'),
('JPN', '使徒行传', 44, 21, 2, 'そこにはフェニキア行きの船があったので、それに乗って出発した。'),
('JPN', '使徒行传', 44, 21, 3, 'やがてキプロスが見えてきたが、それを左にして通過し、シリアに向かって航海を続け、ツロに入港した。ここで船は積荷を降ろすことになっていた。'),
('JPN', '使徒行传', 44, 21, 4, '私たちは弟子たちを探して、そこに七日間滞在した。彼らは御霊に示されて、エルサレムには行かないようにとパウロに繰り返し言った。'),
('JPN', '使徒行传', 44, 21, 5, '滞在期間が終わると、私たちはそこを出て、また旅を続けた。彼らはみな、妻や子どもたちと一緒に町の外まで私たちを送りに来た。そして海岸でひざまずいて祈ってから、'),
('JPN', '使徒行传', 44, 21, 6, '互いに別れを告げた。私たちは船に乗り込み、彼らは自分の家に帰って行った。'),
('JPN', '使徒行传', 44, 21, 7, '私たちはツロからの航海を終えて、プトレマイスに着いた。そこの兄弟たちにあいさつをして、彼らのところに一日滞在した。'),
('JPN', '使徒行传', 44, 21, 8, '翌日そこを出発して、カイサリアに着くと、あの七人の一人である伝道者ピリポの家に行き、そこに滞在した。'),
('JPN', '使徒行传', 44, 21, 9, 'この人には、預言をする未婚の娘が四人いた。'),
('JPN', '使徒行传', 44, 21, 10, 'かなりの期間そこに滞在していると、アガボという名の預言者がユダヤから下って来た。'),
('JPN', '使徒行传', 44, 21, 11, '彼は私たちのところに来て、パウロの帯を取り、自分の両手と両足を縛って言った。「聖霊がこう言われます。『この帯の持ち主を、ユダヤ人たちはエルサレムでこのように縛り、異邦人の手に渡すことになる。』」'),
('JPN', '使徒行传', 44, 21, 12, 'これを聞いて、私たちも土地の人たちもパウロに、エルサレムには上って行かないようにと懇願した。'),
('JPN', '使徒行传', 44, 21, 13, 'すると、パウロは答えた。「あなたがたは、泣いたり私の心をくじいたりして、いったい何をしているのですか。私は主イエスの名のためなら、エルサレムで縛られるだけでなく、死ぬことも覚悟しています。」'),
('JPN', '使徒行传', 44, 21, 14, '彼が聞き入れようとしないので、私たちは「主のみこころがなりますように」と言って、口をつぐんだ。'),
('JPN', '使徒行传', 44, 21, 15, '数日後、私たちは旅支度をしてエルサレムに上って行った。'),
('JPN', '使徒行传', 44, 21, 16, 'カイサリアの弟子たちも何人か私たちに同行して、古くからの弟子である、キプロス人ムナソンのところに案内してくれた。私たちはそこに泊まることになっていたのである。'),
('JPN', '使徒行传', 44, 21, 17, '私たちがエルサレムに着くと、兄弟たちは喜んで迎えてくれた。'),
('JPN', '使徒行传', 44, 21, 18, '翌日、パウロは私たちを連れて、ヤコブを訪問した。そこには長老たちがみな集まっていた。'),
('JPN', '使徒行传', 44, 21, 19, '彼らにあいさつしてから、パウロは自分の奉仕を通して神が異邦人の間でなさったことを、一つ一つ説明した。'),
('JPN', '使徒行传', 44, 21, 20, '彼らはこれを聞いて神をほめたたえ、パウロに言った。「兄弟よ。ご覧のとおり、ユダヤ人の中で信仰に入っている人が何万となくいますが、みな律法に熱心な人たちです。'),
('JPN', '使徒行传', 44, 21, 21, 'ところが、彼らがあなたについて聞かされているのは、あなたが、異邦人の中にいるすべてのユダヤ人に、子どもに割礼を施すな、慣習にしたがって歩むなと言って、モーセに背くように教えている、ということなのです。'),
('JPN', '使徒行传', 44, 21, 22, 'それで、どうしましょうか。あなたが来たことは、必ず彼らの耳に入るでしょう。'),
('JPN', '使徒行传', 44, 21, 23, 'ですから、私たちの言うとおりにしてください。私たちの中に、誓願を立てている者が四人います。'),
('JPN', '使徒行传', 44, 21, 24, 'この人たちを連れて行って、一緒に身を清め、彼らが頭を剃る費用を出してあげてください。そうすれば、あなたについて聞かされていることは根も葉もないことで、あなたも律法を守って正しく歩んでいることが、皆に分かるでしょう。'),
('JPN', '使徒行传', 44, 21, 25, '信仰に入った異邦人に関しては、偶像に供えたものと、血と、絞め殺したものと、淫らな行いを避けるべきであると決定し、すでに書き送りました。」'),
('JPN', '使徒行传', 44, 21, 26, 'そこで、パウロはその人たちを連れて行き、翌日、彼らとともに身を清めて宮に入った。そして、いつ、清めの期間が終わって、一人ひとりのためにささげ物をすることができるかを告げた。'),
('JPN', '使徒行传', 44, 21, 27, 'ところが、その七日の期間が終わろうとしていたとき、アジアから来たユダヤ人たちは、パウロが宮にいるのを見ると、群衆をみな扇動して、彼に手をかけ、'),
('JPN', '使徒行传', 44, 21, 28, 'こう叫んだ。「イスラエルの皆さん、手を貸してください。この男は、民と律法とこの場所に逆らうことを、いたるところで皆に教えている者です。そのうえ、ギリシア人を宮の中に連れ込んで、この神聖な場所を汚しています。」'),
('JPN', '使徒行传', 44, 21, 29, '彼らは、エペソ人のトロフィモが町でパウロと一緒にいるのを以前に見かけていて、パウロが彼を宮に連れ込んだと思ったのである。'),
('JPN', '使徒行传', 44, 21, 30, 'そこで町中が大騒ぎになり、人々は殺到してパウロを捕らえ、宮の外へ引きずり出した。すると、ただちに宮の門が閉じられた。'),
('JPN', '使徒行传', 44, 21, 31, '彼らがパウロを殺そうとしていたとき、エルサレム中が混乱状態に陥っているという報告が、ローマ軍の千人隊長に届いた。'),
('JPN', '使徒行传', 44, 21, 32, '彼はただちに、兵士たちと百人隊長たちを率いて、彼らのところに駆けつけた。人々は千人隊長と兵士たちを見て、パウロを打つのをやめた。'),
('JPN', '使徒行传', 44, 21, 33, '千人隊長は近寄ってパウロを捕らえ、二本の鎖で縛るように命じた。そして、パウロが何者なのか、何をしたのかと尋ねた。'),
('JPN', '使徒行传', 44, 21, 34, 'しかし、群衆はそれぞれに違ったことを叫び続けていた。千人隊長は、騒がしくて確かなことが分からなかったので、パウロを兵営に連れて行くように命じた。'),
('JPN', '使徒行传', 44, 21, 35, 'パウロが階段にさしかかったとき、群衆の暴行を避けるために、兵士たちは彼を担ぎ上げなければならなかった。'),
('JPN', '使徒行传', 44, 21, 36, '大勢の民衆が、「殺してしまえ」と叫びながら、ついて来たからである。'),
('JPN', '使徒行传', 44, 21, 37, '兵営の中に連れ込まれようとしたとき、パウロが千人隊長に「少しお話ししてもよいでしょうか」と尋ねた。すると千人隊長は、「おまえはギリシア語を知っているのか。'),
('JPN', '使徒行传', 44, 21, 38, 'では、おまえは、近ごろ暴動を起こして、四千人の暗殺者を荒野に連れて行った、あのエジプト人ではないのか」と言った。'),
('JPN', '使徒行传', 44, 21, 39, 'パウロは答えた。「私はキリキアのタルソ出身のユダヤ人で、れっきとした町の市民です。お願いです。この人たちに話をさせてください。」'),
('JPN', '使徒行传', 44, 21, 40, '千人隊長が許したので、パウロは階段の上に立ち、静かにするよう民衆を手で制した。そして、すっかり静かになったとき、ヘブル語で次のように語りかけた。'),
('JPN', '使徒行传', 44, 22, 1, '「兄弟ならびに父である皆さん。今から申し上げる私の弁明を聞いてください。」'),
('JPN', '使徒行传', 44, 22, 2, 'パウロがヘブル語で語りかけるのを聞いて、人々はますます静かになった。そこでパウロは言った。'),
('JPN', '使徒行传', 44, 22, 3, '「私は、キリキアのタルソで生まれたユダヤ人ですが、この町で育てられ、ガマリエルのもとで先祖の律法について厳しく教育を受け、今日の皆さんと同じように、神に対して熱心な者でした。'),
('JPN', '使徒行传', 44, 22, 4, 'そしてこの道を迫害し、男でも女でも縛って牢に入れ、死にまでも至らせました。'),
('JPN', '使徒行传', 44, 22, 5, 'このことについては、大祭司や長老会全体も私のために証言してくれます。この人たちから兄弟たちに宛てた手紙まで受け取って、私はダマスコへ向かいました。そこにいる者たちも縛り上げ、エルサレムに引いて来て処罰するためでした。'),
('JPN', '使徒行传', 44, 22, 6, '私が道を進んで、真昼ごろダマスコの近くまで来たとき、突然、天からのまばゆい光が私の周りを照らしました。'),
('JPN', '使徒行传', 44, 22, 7, '私は地に倒れ、私に語りかける声を聞きました。『サウロ、サウロ、どうしてわたしを迫害するのか。』'),
('JPN', '使徒行传', 44, 22, 8, '私が答えて、『主よ、あなたはどなたですか』と言うと、その方は私に言われました。『わたしは、あなたが迫害しているナザレのイエスである。』'),
('JPN', '使徒行传', 44, 22, 9, '一緒にいた人たちは、その光は見たのですが、私に語っている方の声は聞き分けられませんでした。'),
('JPN', '使徒行传', 44, 22, 10, '私が『主よ、私はどうしたらよいでしょうか』と尋ねると、主は私に言われました。『起き上がって、ダマスコに行きなさい。あなたが行うように定められているすべてのことが、そこであなたに告げられる』と。'),
('JPN', '使徒行传', 44, 22, 11, '私はその光の輝きのために目が見えなくなっていたので、一緒にいた人たちに手を引いてもらって、ダマスコに入りました。'),
('JPN', '使徒行传', 44, 22, 12, 'すると、律法に従う敬虔な人で、そこに住んでいるすべてのユダヤ人たちに評判の良い、アナニアという人が、'),
('JPN', '使徒行传', 44, 22, 13, '私のところに来て、そばに立ち、『兄弟サウロ、再び見えるようになりなさい』と言いました。するとそのとき、私はその人が見えるようになりました。'),
('JPN', '使徒行传', 44, 22, 14, '彼はこう言いました。『私たちの父祖の神は、あなたをお選びになりました。あなたがみこころを知り、義なる方を見、その方の口から御声を聞くようになるためです。'),
('JPN', '使徒行传', 44, 22, 15, 'あなたはその方のために、すべての人に対して、見聞きしたことを証しする証人となるのです。'),
('JPN', '使徒行传', 44, 22, 16, 'さあ、何をためらっているのですか。立ちなさい。その方の名を呼んでバプテスマを受け、自分の罪を洗い流しなさい。』'),
('JPN', '使徒行传', 44, 22, 17, 'それから私がエルサレムに帰り、宮で祈っていたとき、私は夢心地になりました。'),
('JPN', '使徒行传', 44, 22, 18, 'そして主を見たのです。主は私にこう語られました。『早く、急いでエルサレムを離れなさい。わたしについてあなたがする証しを、人々は受け入れないから。』'),
('JPN', '使徒行传', 44, 22, 19, 'そこで私は答えました。『主よ。この私が会堂ごとに、あなたを信じる者たちを牢に入れたり、むちで打ったりしていたのを、彼らは知っています。'),
('JPN', '使徒行传', 44, 22, 20, 'また、あなたの証人ステパノの血が流されたとき、私自身もその場にいて、それに賛成し、彼を殺した者たちの上着の番をしていたのです。』'),
('JPN', '使徒行传', 44, 22, 21, 'すると主は私に、『行きなさい。わたしはあなたを遠く異邦人に遣わす』と言われました。」'),
('JPN', '使徒行传', 44, 22, 22, '人々は彼の話をここまで聞いていたが、声を張り上げて言った。「こんな男は、地上から除いてしまえ。生かしておくべきではない。」'),
('JPN', '使徒行传', 44, 22, 23, '人々がわめき立て、上着を放り投げ、ちりを空中にまき散らすので、'),
('JPN', '使徒行传', 44, 22, 24, '千人隊長は、パウロを兵営の中に引き入れるように命じ、なぜ人々がこのように彼に対して怒鳴っているのかを知るため、むちで打って取り調べるように言った。'),
('JPN', '使徒行传', 44, 22, 25, '彼らがむちで打とうとしてパウロの手足を広げたとき、パウロはそばに立っていた百人隊長に言った。「ローマ市民である者を、裁判にもかけずに、むちで打ってよいのですか。」'),
('JPN', '使徒行传', 44, 22, 26, 'これを聞いた百人隊長は、千人隊長のところに行って報告し、「どうなさいますか。あの人はローマ市民です」と言った。'),
('JPN', '使徒行传', 44, 22, 27, 'そこで、千人隊長はパウロのところに来て言った。「私に言いなさい。あなたはローマ市民なのか。」パウロは「そうです」と答えた。'),
('JPN', '使徒行传', 44, 22, 28, 'すると千人隊長は言った。「私は多額の金でこの市民権を手に入れたのだ。」パウロは言った。「私は生まれながらの市民です。」'),
('JPN', '使徒行传', 44, 22, 29, 'そこで、パウロを取り調べようとしていた者たちは、すぐにパウロから身を引いた。千人隊長も、パウロがローマ市民であり、その彼を縛っていたことを知って恐れた。'),
('JPN', '使徒行传', 44, 22, 30, '翌日、千人隊長は、パウロがなぜユダヤ人たちに訴えられているのか、確かなことを知りたいと思い、彼の鎖を解いた。そして、祭司長たちと最高法院全体に集まるように命じ、パウロを連れて行って、彼らの前に立たせた。'),
('JPN', '使徒行传', 44, 23, 1, 'パウロは、最高法院の人々を見つめて言った。「兄弟たち。私は今日まで、あくまでも健全な良心にしたがって、神の前に生きてきました。」'),
('JPN', '使徒行传', 44, 23, 2, 'すると、大祭司アナニアは、パウロのそばに立っていた者たちに、彼の口を打つように命じた。'),
('JPN', '使徒行传', 44, 23, 3, 'そこで、パウロはアナニアに向かって言った。「白く塗った壁よ、神があなたを打たれる。あなたは、律法にしたがって私をさばく座に着いていながら、律法に背いて私を打てと命じるのか。」'),
('JPN', '使徒行传', 44, 23, 4, 'すると、そばに立っていた者たちが「あなたは神の大祭司をののしるのか」と言ったので、'),
('JPN', '使徒行传', 44, 23, 5, 'パウロは答えた。「兄弟たち。私は彼が大祭司だとは知らなかった。確かに、『あなたの民の指導者を悪く言ってはならない』と書かれています。」'),
('JPN', '使徒行传', 44, 23, 6, 'パウロは、彼らの一部がサドカイ人で、一部がパリサイ人であるのを見てとって、最高法院の中でこう叫んだ。「兄弟たち、私はパリサイ人です。パリサイ人の子です。私は死者の復活という望みのことで、さばきを受けているのです。」'),
('JPN', '使徒行传', 44, 23, 7, 'パウロがこう言うと、パリサイ人とサドカイ人の間に論争が起こり、最高法院は二つに割れた。'),
('JPN', '使徒行传', 44, 23, 8, 'サドカイ人は復活も御使いも霊もないと言い、パリサイ人はいずれも認めているからである。'),
('JPN', '使徒行传', 44, 23, 9, '騒ぎは大きくなった。そして、パリサイ派の律法学者たちが何人か立ち上がって、激しく論じ、「この人には何の悪い点も見られない。もしかしたら、霊か御使いが彼に語りかけたのかもしれない」と言った。'),
('JPN', '使徒行传', 44, 23, 10, '論争がますます激しくなったので、千人隊長は、パウロが彼らに引き裂かれてしまうのではないかと恐れた。それで兵士たちに、降りて行ってパウロを彼らの中から引っ張り出し、兵営に連れて行くように命じた。'),
('JPN', '使徒行传', 44, 23, 11, 'その夜、主がパウロのそばに立って、「勇気を出しなさい。あなたは、エルサレムでわたしのことを証ししたように、ローマでも証しをしなければならない」と言われた。'),
('JPN', '使徒行传', 44, 23, 12, '夜が明けると、ユダヤ人たちは徒党を組み、パウロを殺すまでは食べたり飲んだりしない、と呪いをかけて誓った。'),
('JPN', '使徒行传', 44, 23, 13, 'この陰謀を企てた者たちは、四十人以上いた。'),
('JPN', '使徒行传', 44, 23, 14, '彼らは祭司長たちや長老たちのところに行って、次のように言った。「私たちは、パウロを殺すまでは何も口にしない、と呪いをかけて堅く誓いました。'),
('JPN', '使徒行传', 44, 23, 15, 'そこで、今あなたがたは、パウロのことをもっと詳しく調べるふりをして、彼をあなたがたのところに連れて来るように、最高法院と組んで千人隊長に願い出てください。私たちのほうでは、彼がこの近くに来る前に殺す手はずを整えています。」'),
('JPN', '使徒行传', 44, 23, 16, 'ところが、パウロの姉妹の息子がこの待ち伏せのことを耳にしたので、兵営に来て中に入り、そのことをパウロに知らせた。'),
('JPN', '使徒行传', 44, 23, 17, 'そこで、パウロは百人隊長の一人を呼んで、「この青年を千人隊長のところに連れて行ってください。何か知らせたいことがあるそうです」と言った。'),
('JPN', '使徒行传', 44, 23, 18, '百人隊長は彼を千人隊長のもとに連れて行き、「囚人パウロが私を呼んで、この青年をあなたのところに連れて行くように頼みました。何かあなたに話したいことがあるそうです」と言った。'),
('JPN', '使徒行传', 44, 23, 19, 'すると、千人隊長は青年の手を取り、だれもいないところに連れて行って、「私に知らせたいこととは何だ」と尋ねた。'),
('JPN', '使徒行传', 44, 23, 20, '青年は言った。「ユダヤ人たちは、パウロについてもっと詳しく調べるふりをして、明日パウロを最高法院に連れて来るよう、あなたにお願いすることを申し合わせました。'),
('JPN', '使徒行传', 44, 23, 21, 'どうか、彼らの言うことを信じないでください。彼らのうちの四十人以上の者が、パウロを殺すまでは食べたり飲んだりしないと呪いをかけて誓い、待ち伏せをしています。今、彼らは手はずを整えて、あなたの承諾を待っているのです。」'),
('JPN', '使徒行传', 44, 23, 22, 'そこで千人隊長は、「このことを私に知らせたことは、だれにも言うな」と命じて、その青年を帰した。'),
('JPN', '使徒行传', 44, 23, 23, 'それから千人隊長は二人の百人隊長を呼び、「今夜九時、カイサリアに向けて出発できるように、歩兵二百人、騎兵七十人、槍兵二百人を用意せよ」と命じた。'),
('JPN', '使徒行传', 44, 23, 24, 'また、パウロを乗せて無事に総督フェリクスのもとに送り届けるように、馬の用意もさせた。'),
('JPN', '使徒行传', 44, 23, 25, 'そして、次のような文面の手紙を書いた。'),
('JPN', '使徒行传', 44, 23, 26, '「クラウディウス・リシア、謹んで総督フェリクス閣下にごあいさつ申し上げます。'),
('JPN', '使徒行传', 44, 23, 27, 'この男がユダヤ人たちに捕らえられ、まさに殺されようとしていたときに、私は兵士たちを率いて行って彼を救い出しました。ローマ市民であることが分かったからです。'),
('JPN', '使徒行传', 44, 23, 28, 'そして、ユダヤ人たちが彼を訴えている理由を知ろうと思い、彼を彼らの最高法院に連れて行きました。'),
('JPN', '使徒行传', 44, 23, 29, 'ところが、彼が訴えられているのは、ユダヤ人の律法に関する問題のためで、死刑や投獄に当たる罪はないことが分かりました。'),
('JPN', '使徒行传', 44, 23, 30, 'しかし、この者に対する陰謀があるという情報を得ましたので、私はただちに彼を閣下のもとにお送りします。なお、訴えている者たちには、彼のことを閣下の前で訴えるように命じておきました。」'),
('JPN', '使徒行传', 44, 23, 31, 'そこで、兵士たちは命じられたとおりにパウロを引き取り、夜のうちにアンティパトリスまで連れて行き、'),
('JPN', '使徒行传', 44, 23, 32, '翌日、騎兵たちにパウロの護送を任せて、兵営に帰った。'),
('JPN', '使徒行传', 44, 23, 33, '騎兵たちはカイサリアに到着すると、総督に手紙を手渡して、パウロを引き合わせた。'),
('JPN', '使徒行传', 44, 23, 34, '総督は手紙を読んでから、パウロにどの州の者かと尋ね、キリキア出身であることを知って、'),
('JPN', '使徒行传', 44, 23, 35, '「おまえを訴える者たちが来たときに、よく聞くことにしよう」と言った。そして、ヘロデの建てた官邸に彼を保護しておくように命じた。'),
('JPN', '使徒行传', 44, 24, 1, '五日後、大祭司アナニアは、数人の長老たち、およびテルティロという弁護士と一緒に下って来て、パウロを総督に告訴した。'),
('JPN', '使徒行传', 44, 24, 2, 'パウロが呼び出され、テルティロが訴えを述べ始めた。「フェリクス閣下。閣下のおかげで、私たちはすばらしい平和を享受しております。また、閣下のご配慮により、この国に改革が進行しております。'),
('JPN', '使徒行传', 44, 24, 3, '私たちは、あらゆる面で、また、いたるところでこのことを認め、心から感謝しております。'),
('JPN', '使徒行传', 44, 24, 4, 'さて、これ以上ご迷惑をおかけしないために、私たちが手短に申し上げることを、ご寛容をもってお聞きくださるようお願いいたします。'),
('JPN', '使徒行传', 44, 24, 5, '実は、この男はまるで疫病のような人間で、世界中のユダヤ人の間に騒ぎを起こしている者であり、ナザレ人の一派の首謀者であります。'),
('JPN', '使徒行传', 44, 24, 6, 'この男は宮さえも汚そうとしましたので、私たちは彼を捕らえました。'),
('JPN', '使徒行传', 44, 24, 8, '閣下ご自身で彼をお調べくだされば、私たちが彼を訴えております事柄のすべてについて、よくお分かりいただけると思います。」'),
('JPN', '使徒行传', 44, 24, 9, 'ユダヤ人たちもこの訴えに同調し、そのとおりだと主張した。'),
('JPN', '使徒行传', 44, 24, 10, 'そのとき、総督がパウロに話すよう合図したので、パウロは次のように答えた。「閣下が長年、この民の裁判をつかさどってこられたことを存じておりますので、喜んで私自身のことを弁明いたします。'),
('JPN', '使徒行传', 44, 24, 11, 'お調べになれば分かることですが、私が礼拝のためにエルサレムに上ってから、まだ十二日しかたっていません。'),
('JPN', '使徒行传', 44, 24, 12, 'そして、宮でも会堂でも町の中でも、私がだれかと論争したり、群衆を扇動したりするのを見た者はいません。'),
('JPN', '使徒行传', 44, 24, 13, 'また、今私を訴えていることについて、彼らは閣下に証明できないはずです。'),
('JPN', '使徒行传', 44, 24, 14, 'ただ、私は閣下の前で、次のことは認めます。私は、彼らが分派と呼んでいるこの道にしたがって、私たちの先祖の神に仕えています。私は、律法にかなうことと、預言者たちの書に書かれていることを、すべて信じています。'),
('JPN', '使徒行传', 44, 24, 15, 'また私は、正しい者も正しくない者も復活するという、この人たち自身も抱いている望みを、神に対して抱いています。'),
('JPN', '使徒行传', 44, 24, 16, 'そのために、私はいつも、神の前にも人の前にも責められることのない良心を保つように、最善を尽くしています。'),
('JPN', '使徒行传', 44, 24, 17, 'さて私は、同胞に対して施しをするために、またささげ物をするために、何年ぶりかで帰って来ました。'),
('JPN', '使徒行传', 44, 24, 18, 'そのささげ物をし、私は清めを済ませて宮の中にいるのを見られたのですが、別に群衆もおらず、騒ぎもありませんでした。'),
('JPN', '使徒行传', 44, 24, 19, 'ただ、アジアから来たユダヤ人が数人いました。もしその人たちに、私に対して何か非難したいことがあるなら、彼らが閣下の前に来て訴えるべきだったのです。'),
('JPN', '使徒行传', 44, 24, 20, 'そうでなければ、ここにいる人たちが、最高法院の前に立っていたときの私に、どんな不正を見つけたのかを言うべきです。'),
('JPN', '使徒行传', 44, 24, 21, '私は彼らの中に立って、ただ一言、『死者の復活のことで、私は今日あなたがたの前でさばかれている』と叫んだにすぎません。」'),
('JPN', '使徒行传', 44, 24, 22, 'フェリクスは、この道についてかなり詳しく知っていたので、「千人隊長リシアが下って来たら、おまえたちの事件に判決を下すことにする」と言って、裁判を延期した。'),
('JPN', '使徒行传', 44, 24, 23, 'そして百人隊長に、パウロを監禁するように、しかし、ある程度の自由を与え、仲間の者たちが彼の世話をするのを妨げないように、と命じた。'),
('JPN', '使徒行传', 44, 24, 24, '数日後、フェリクスはユダヤ人である妻ドルシラとともにやって来て、パウロを呼び出し、キリスト・イエスに対する信仰について話を聞いた。'),
('JPN', '使徒行传', 44, 24, 25, 'しかし、パウロが正義と節制と来たるべきさばきについて論じたので、フェリクスは恐ろしくなり、「今は帰ってよい。折を見て、また呼ぶことにする」と言った。'),
('JPN', '使徒行传', 44, 24, 26, 'また同時に、フェリクスにはパウロから金をもらいたい下心があったので、何度もパウロを呼び出して語り合った。'),
('JPN', '使徒行传', 44, 24, 27, '二年が過ぎ、ポルキウス・フェストゥスがフェリクスの後任になった。しかし、フェリクスはユダヤ人たちの機嫌を取ろうとして、パウロを監禁したままにしておいた。'),
('JPN', '使徒行传', 44, 25, 1, 'フェストゥスは、属州に到着すると、三日後にカイサリアからエルサレムに上った。'),
('JPN', '使徒行传', 44, 25, 2, 'すると、祭司長たちとユダヤ人のおもだった者たちが、パウロのことを告訴した。'),
('JPN', '使徒行传', 44, 25, 3, 'そして、パウロの件で自分たちに好意を示し、彼をエルサレムに呼び寄せていただきたいと、フェストゥスに懇願した。待ち伏せして、途中でパウロを殺そうとしていたのである。'),
('JPN', '使徒行传', 44, 25, 4, 'しかしフェストゥスは、パウロはカイサリアに監禁されているし、自分も間もなく出発する予定であると答え、'),
('JPN', '使徒行传', 44, 25, 5, '「その男に何か問題があるなら、おまえたちの中の有力者たちが私と一緒に下って行って、彼を訴えればよい」と言った。'),
('JPN', '使徒行传', 44, 25, 6, 'フェストゥスは、彼らのところに八日か十日ほど滞在しただけで、カイサリアに下り、翌日、裁判の席に着いて、パウロの出廷を命じた。'),
('JPN', '使徒行传', 44, 25, 7, 'パウロが現れると、エルサレムから下って来たユダヤ人たちは彼を取り囲んで立ち、多くの重い罪状を申し立てた。しかし、それを立証することはできなかった。'),
('JPN', '使徒行传', 44, 25, 8, 'パウロは、「私は、ユダヤ人の律法に対しても、宮に対しても、カエサルに対しても、何の罪も犯してはいません」と弁明した。'),
('JPN', '使徒行传', 44, 25, 9, 'ところが、ユダヤ人たちの機嫌を取ろうとしたフェストゥスは、パウロに向かって、「おまえはエルサレムに上り、そこでこれらの件について、私の前で裁判を受けることを望むか」と尋ねた。'),
('JPN', '使徒行传', 44, 25, 10, 'すると、パウロは言った。「私はカエサルの法廷に立っているのですから、ここで裁判を受けるのが当然です。閣下もよくご存じのとおり、私はユダヤ人たちに何も悪いことをしていません。'),
('JPN', '使徒行传', 44, 25, 11, 'もし私が悪いことをし、死に値する何かをしたのなら、私は死を免れようとは思いません。しかし、この人たちが訴えていることに何の根拠もないとすれば、だれも私を彼らに引き渡すことはできません。私はカエサルに上訴します。」'),
('JPN', '使徒行传', 44, 25, 12, 'そこで、フェストゥスは陪席の者たちと協議したうえで、こう答えた。「おまえはカエサルに上訴したのだから、カエサルのもとに行くことになる。」'),
('JPN', '使徒行传', 44, 25, 13, '数日たって、アグリッパ王とベルニケが、フェストゥスに敬意を表するためにカイサリアに来た。'),
('JPN', '使徒行传', 44, 25, 14, '二人がそこに何日も滞在していたので、フェストゥスはパウロの件を王に持ち出して、次のように言った。「フェリクスが囚人として残して行った男が一人います。'),
('JPN', '使徒行传', 44, 25, 15, '私がエルサレムに行ったとき、祭司長たちとユダヤ人の長老たちが、その男のことを私に訴え出て、罪に定めるよう求めました。'),
('JPN', '使徒行传', 44, 25, 16, 'そこで、私は彼らにこう答えました。『訴えられている者が、告発する者たちの面前で訴えについて弁明する機会が与えられずに、引き渡されるということは、ローマ人の慣習にはない。』'),
('JPN', '使徒行传', 44, 25, 17, 'それで、訴える者たちがともにこちらに来たので、私は時を移さず、その翌日に裁判の席に着いて、その男を出廷させました。'),
('JPN', '使徒行传', 44, 25, 18, '告発者たちは立ち上がりましたが、彼について私が予測していたような犯罪についての告発理由は、何一つ申し立てませんでした。'),
('JPN', '使徒行传', 44, 25, 19, 'ただ、彼と言い争っている点は、彼ら自身の宗教に関すること、また死んでしまったイエスという者のことで、そのイエスが生きているとパウロは主張しているのです。'),
('JPN', '使徒行传', 44, 25, 20, 'このような問題をどう取り調べたらよいか、私には見当がつかないので、彼に『エルサレムに行き、そこでこの件について裁判を受けたいか』と尋ねました。'),
('JPN', '使徒行传', 44, 25, 21, 'するとパウロは、皇帝の判決を受けるまで保護してほしいと訴えたので、彼をカエサルのもとに送る時まで保護しておくように命じました。」'),
('JPN', '使徒行传', 44, 25, 22, 'アグリッパがフェストゥスに「私も、その男の話を聞いてみたいものです」と言ったので、フェストゥスは、「では、明日お聞きください」と言った。'),
('JPN', '使徒行传', 44, 25, 23, '翌日、アグリッパとベルニケは大いに威儀を正して到着し、千人隊長たちや町の有力者たちとともに謁見室に入った。そして、フェストゥスが命じると、パウロが連れて来られた。'),
('JPN', '使徒行传', 44, 25, 24, 'フェストゥスは言った。「アグリッパ王、ならびにご列席の皆さん、この者をご覧ください。多くのユダヤ人たちがみな、エルサレムでもここでも、もはや生かしておくべきではないと叫び、私に訴えてきたのは、この者です。'),
('JPN', '使徒行传', 44, 25, 25, '私の理解するところでは、彼は死罪に当たることは何一つしていません。ただ、彼自身が皇帝に上訴したので、私は彼を送ることに決めました。'),
('JPN', '使徒行传', 44, 25, 26, 'ところが、彼について、わが君に書き送るべき確かな事柄が何もありません。それで皆さんの前に、わけてもアグリッパ王、あなたの前に、彼を引き出しました。こうして取り調べることで、何か私が書き送るべきことを得たいのです。'),
('JPN', '使徒行传', 44, 25, 27, '囚人を送るのに、訴える理由を示さないのは、道理に合わないと思うのです。」'),
('JPN', '使徒行传', 44, 26, 1, 'アグリッパはパウロに向かって、「自分のことを話してよろしい」と言った。そこでパウロは、手を差し出して弁明し始めた。'),
('JPN', '使徒行传', 44, 26, 2, '「アグリッパ王よ。私がユダヤ人たちに訴えられているすべてのことについて、今日、王様の前で弁明できることを幸いに思います。'),
('JPN', '使徒行传', 44, 26, 3, '特に、王様はユダヤ人の慣習や問題に精通しておられます。ですから、どうか忍耐をもって、私の申し上げることをお聞きくださるよう、お願いいたします。'),
('JPN', '使徒行传', 44, 26, 4, 'さて、初めから同胞の間で、またエルサレムで過ごしてきた、私の若いころからの生き方は、すべてのユダヤ人が知っています。'),
('JPN', '使徒行传', 44, 26, 5, '彼らは以前から私を知っているので、証言しようと思えばできますが、私は、私たちの宗教の中で最も厳格な派にしたがって、パリサイ人として生活してきました。'),
('JPN', '使徒行传', 44, 26, 6, 'そして今、神が私たちの父祖たちに与えられた約束に望みを抱いているために、私はここに立って、さばかれているのです。'),
('JPN', '使徒行传', 44, 26, 7, '私たちの十二部族は、夜も昼も熱心に神に仕えながら、その約束のものを得たいと望んでいます。王よ。私はこの望みを抱いているために、ユダヤ人から訴えられているのです。'),
('JPN', '使徒行传', 44, 26, 8, '神が死者をよみがえらせるということを、あなたがたは、なぜ信じがたいこととお考えになるのでしょうか。'),
('JPN', '使徒行传', 44, 26, 9, '実は私自身も、ナザレ人イエスの名に対して、徹底して反対すべきであると考えていました。'),
('JPN', '使徒行传', 44, 26, 10, 'そして、それをエルサレムで実行しました。祭司長たちから権限を受けた私は、多くの聖徒たちを牢に閉じ込め、彼らが殺されるときには賛成の票を投じました。'),
('JPN', '使徒行传', 44, 26, 11, 'そして、すべての会堂で、何度も彼らに罰を科し、御名を汚すことばを無理やり言わせ、彼らに対する激しい怒りに燃えて、ついには国外の町々にまで彼らを迫害して行きました。'),
('JPN', '使徒行传', 44, 26, 12, 'このような次第で、私は祭司長たちから権限と委任を受けてダマスコへ向かいましたが、'),
('JPN', '使徒行传', 44, 26, 13, 'その途中のこと、王様、真昼に私は天からの光を見ました。それは太陽よりも明るく輝いて、私と私に同行していた者たちの周りを照らしました。'),
('JPN', '使徒行传', 44, 26, 14, '私たちはみな地に倒れましたが、そのとき私は、ヘブル語で自分に語りかける声を聞きました。『サウロ、サウロ、なぜわたしを迫害するのか。とげの付いた棒を蹴るのは、あなたには痛い。』'),
('JPN', '使徒行传', 44, 26, 15, '私が『主よ、あなたはどなたですか』と言うと、主はこう言われました。『わたしは、あなたが迫害しているイエスである。'),
('JPN', '使徒行传', 44, 26, 16, '起き上がって自分の足で立ちなさい。わたしがあなたに現れたのは、あなたがわたしを見たことや、わたしがあなたに示そうとしていることについて、あなたを奉仕者、また証人に任命するためである。'),
('JPN', '使徒行传', 44, 26, 17, 'わたしは、あなたをこの民と異邦人の中から救い出し、彼らのところに遣わす。'),
('JPN', '使徒行传', 44, 26, 18, 'それは彼らの目を開いて、闇から光に、サタンの支配から神に立ち返らせ、こうしてわたしを信じる信仰によって、彼らが罪の赦しを得て、聖なるものとされた人々とともに相続にあずかるためである。』'),
('JPN', '使徒行传', 44, 26, 19, 'こういうわけで、アグリッパ王よ、私は天からの幻に背かず、'),
('JPN', '使徒行传', 44, 26, 20, 'ダマスコにいる人々をはじめエルサレムにいる人々に、またユダヤ地方全体に、さらに異邦人にまで、悔い改めて神に立ち返り、悔い改めにふさわしい行いをするようにと宣べ伝えてきました。'),
('JPN', '使徒行传', 44, 26, 21, 'そのために、ユダヤ人たちは私を宮の中で捕らえ、殺そうとしたのです。'),
('JPN', '使徒行传', 44, 26, 22, 'このようにして、私は今日に至るまで神の助けを受けながら、堅く立って、小さい者にも大きい者にも証しをしています。そして、話してきたことは、預言者たちやモーセが後に起こるはずだと語ったことにほかなりません。'),
('JPN', '使徒行传', 44, 26, 23, 'すなわち、キリストが苦しみを受けること、また、死者の中から最初に復活し、この民にも異邦人にも光を宣べ伝えることになると話したのです。」'),
('JPN', '使徒行传', 44, 26, 24, 'パウロがこのように弁明していると、フェストゥスが大声で言った。「パウロよ、おまえは頭がおかしくなっている。博学がおまえを狂わせている。」'),
('JPN', '使徒行传', 44, 26, 25, 'パウロは言った。「フェストゥス閣下、私は頭がおかしくはありません。私は、真実で理にかなったことばを話しています。'),
('JPN', '使徒行传', 44, 26, 26, '王様はこれらのことをよくご存じですので、その王様に対して私は率直に申し上げているのです。このことは片隅で起こった出来事ではありませんから、そのうちの一つでも、王様がお気づきにならなかったことはない、と確信しています。'),
('JPN', '使徒行传', 44, 26, 27, 'アグリッパ王よ、王様は預言者たちを信じておられますか。信じておられることと思います。」'),
('JPN', '使徒行传', 44, 26, 28, 'するとアグリッパはパウロに、「おまえは、わずかな時間で私を説き伏せて、キリスト者にしようとしている」と言った。'),
('JPN', '使徒行传', 44, 26, 29, 'しかし、パウロはこう答えた。「わずかな時間であろうと長い時間であろうと、私が神に願っているのは、あなたばかりでなく今日私の話を聞いておられる方々が、この鎖は別として、みな私のようになってくださることです。」'),
('JPN', '使徒行传', 44, 26, 30, '王と総督とベルニケ、および同席の人々は立ち上がった。'),
('JPN', '使徒行传', 44, 26, 31, '彼らは退場してから話し合った。「あの人は、死や投獄に値することは何もしていない。」'),
('JPN', '使徒行传', 44, 26, 32, 'また、アグリッパはフェストゥスに、「あの人は、もしカエサルに上訴していなかったら、釈放してもらえたであろうに」と言った。'),
('JPN', '使徒行传', 44, 27, 1, 'さて、私たちが船でイタリアへ行くことが決まったとき、パウロとほかの数人の囚人は、親衛隊のユリウスという百人隊長に引き渡された。'),
('JPN', '使徒行传', 44, 27, 2, '私たちは、アジアの沿岸の各地に寄港して行く、アドラミティオの船に乗り込んで出発した。テサロニケのマケドニア人アリスタルコも同行した。'),
('JPN', '使徒行传', 44, 27, 3, '翌日、私たちはシドンに入港した。ユリウスはパウロを親切に扱い、友人たちのところへ行って、もてなしを受けることを許した。'),
('JPN', '使徒行传', 44, 27, 4, '私たちはそこから船出し、向かい風だったので、キプロスの島陰を航行した。'),
('JPN', '使徒行传', 44, 27, 5, 'そしてキリキアとパンフィリアの沖を航行して、リキアのミラに入港した。'),
('JPN', '使徒行传', 44, 27, 6, 'ここで、百人隊長はイタリアへ行くアレクサンドリアの船を見つけて、それに私たちを乗り込ませた。'),
('JPN', '使徒行传', 44, 27, 7, '何日もの間、船の進みは遅く、やっとのことでクニドの沖まで来たが、風のせいでそれ以上は進めず、サルモネ沖のクレタの島陰を航行した。'),
('JPN', '使徒行传', 44, 27, 8, 'そしてその岸に沿って進みながら、やっとのことで、ラサヤの町に近い「良い港」と呼ばれる場所に着いた。'),
('JPN', '使徒行传', 44, 27, 9, 'かなりの時が経過し、断食の日もすでに過ぎていたため、もはや航海は危険であった。そこでパウロは人々に警告して、'),
('JPN', '使徒行传', 44, 27, 10, '「皆さん。私の見るところでは、この航海は積荷や船体だけでなく、私たちのいのちにも危害と大きな損失をもたらすでしょう」と言った。'),
('JPN', '使徒行传', 44, 27, 11, 'しかし百人隊長は、パウロの言うことよりも、船長や船主のほうを信用した。'),
('JPN', '使徒行传', 44, 27, 12, 'また、この港は冬を過ごすのに適していなかったので、多数の者たちの意見により、ここから船出し、できれば、南西と北西に面しているクレタの港フェニクスに行き、そこで冬を過ごそうということになった。'),
('JPN', '使徒行传', 44, 27, 13, 'さて、穏やかな南風が吹いて来たので、人々は思いどおりになったと考え、錨を上げて、クレタの海岸に沿って航行した。'),
('JPN', '使徒行传', 44, 27, 14, 'ところが、間もなくユーラクロンという暴風が陸から吹き降ろして来た。'),
('JPN', '使徒行传', 44, 27, 15, '船はそれに巻き込まれて、風に逆らって進むことができず、私たちは流されるままとなった。'),
('JPN', '使徒行传', 44, 27, 16, 'しかし、カウダと呼ばれる小島の陰に入ったので、どうにかしっかりと小舟を引き寄せることができた。'),
('JPN', '使徒行传', 44, 27, 17, 'そして小舟を船に引き上げ、船を補強するために綱で船体を巻いた。また、シルティスの浅瀬に乗り上げるのを恐れて、船具を降ろし、流されるに任せた。'),
('JPN', '使徒行传', 44, 27, 18, '私たちは暴風に激しく翻弄されていたので、翌日、人々は積荷を捨て始め、'),
('JPN', '使徒行传', 44, 27, 19, '三日目には、自分たちの手で船具を投げ捨てた。'),
('JPN', '使徒行传', 44, 27, 20, '太陽も星も見えない日が何日も続き、暴風が激しく吹き荒れたので、私たちが助かる望みも今や完全に絶たれようとしていた。'),
('JPN', '使徒行传', 44, 27, 21, '長い間、だれも食べていなかったが、そのときパウロは彼らの中に立って言った。「皆さん。あなたがたが私の言うことを聞き入れて、クレタから船出しないでいたら、こんな危害や損失を被らなくてすんだのです。'),
('JPN', '使徒行传', 44, 27, 22, 'しかし今、あなたがたに勧めます。元気を出しなさい。あなたがたのうち、いのちを失う人は一人もありません。失われるのは船だけです。'),
('JPN', '使徒行传', 44, 27, 23, '昨夜、私の主で、私が仕えている神の御使いが私のそばに立って、'),
('JPN', '使徒行传', 44, 27, 24, 'こう言ったのです。『恐れることはありません、パウロよ。あなたは必ずカエサルの前に立ちます。見なさい。神は同船している人たちを、みなあなたに与えておられます。』'),
('JPN', '使徒行传', 44, 27, 25, 'ですから、皆さん、元気を出しなさい。私は神を信じています。私に語られたことは、そのとおりになるのです。'),
('JPN', '使徒行传', 44, 27, 26, '私たちは必ず、どこかの島に打ち上げられます。」'),
('JPN', '使徒行传', 44, 27, 27, '十四日目の夜になり、私たちはアドリア海を漂っていた。真夜中ごろ、水夫たちはどこかの陸地に近づいているのではないかと思った。'),
('JPN', '使徒行传', 44, 27, 28, '彼らが水の深さを測ってみると、二十オルギヤであることが分かった。少し進んでもう一度測ると、十五オルギヤであった。'),
('JPN', '使徒行传', 44, 27, 29, 'どこかで暗礁に乗り上げるのではないかと恐れて、人々は船尾から錨を四つ投げ降ろし、夜が明けるのを待ちわびた。'),
('JPN', '使徒行传', 44, 27, 30, 'ところが、水夫たちが船から逃げ出そうとして、船首から錨を降ろすように見せかけ、小舟を海に降ろしていたので、'),
('JPN', '使徒行传', 44, 27, 31, 'パウロは百人隊長や兵士たちに、「あの人たちが船にとどまっていなければ、あなたがたは助かりません」と言った。'),
('JPN', '使徒行传', 44, 27, 32, 'そこで兵士たちは小舟の綱を切って、それが流れるままにした。'),
('JPN', '使徒行传', 44, 27, 33, '夜が明けかけたころ、パウロは一同に食事をするように勧めて、こう言った。「今日で十四日、あなたがたはひたすら待ち続け、何も口に入れず、食べることなく過ごしてきました。'),
('JPN', '使徒行传', 44, 27, 34, 'ですから、食事をするよう勧めます。これで、あなたがたは助かります。頭から髪の毛一本失われることはありません。」'),
('JPN', '使徒行传', 44, 27, 35, 'こう言って、彼はパンを取り、一同の前で神に感謝の祈りをささげてから、それを裂いて食べ始めた。'),
('JPN', '使徒行传', 44, 27, 36, 'それで皆も元気づけられ、食事をした。'),
('JPN', '使徒行传', 44, 27, 37, '船にいた私たちは、合わせて二百七十六人であった。'),
('JPN', '使徒行传', 44, 27, 38, '十分に食べた後、人々は麦を海に投げ捨てて、船を軽くした。'),
('JPN', '使徒行传', 44, 27, 39, '夜が明けたとき、どこの陸地かよく分からなかったが、砂浜のある入江が目に留まったので、できればそこに船を乗り入れようということになった。'),
('JPN', '使徒行传', 44, 27, 40, '錨を切って海に捨て、同時に舵の綱を解き、吹く風に船首の帆を上げて、砂浜に向かって進んで行った。'),
('JPN', '使徒行传', 44, 27, 41, 'ところが、二つの潮流に挟まれた浅瀬に乗り上げて、船を座礁させてしまった。船首はめり込んで動かなくなり、船尾は激しい波によって壊れ始めた。'),
('JPN', '使徒行传', 44, 27, 42, '兵士たちは、囚人たちがだれも泳いで逃げないように、殺してしまおうと図った。'),
('JPN', '使徒行传', 44, 27, 43, 'しかし、百人隊長はパウロを助けたいと思い、彼らの計画を制止して、泳げる者たちがまず海に飛び込んで陸に上がり、'),
('JPN', '使徒行传', 44, 27, 44, '残りの者たちは、板切れや、船にある何かにつかまって行くように命じた。こうして、全員が無事に陸に上がった。'),
('JPN', '使徒行传', 44, 28, 1, 'こうして助かってから、私たちはこの島がマルタと呼ばれていることを知った。'),
('JPN', '使徒行传', 44, 28, 2, '島の人々は私たちに非常に親切にしてくれた。雨が降り出していて寒かったので、彼らは火をたいて私たちみなを迎えてくれた。'),
('JPN', '使徒行传', 44, 28, 3, 'パウロが枯れ枝を一抱え集めて火にくべると、熱気のために一匹のまむしが這い出して来て、彼の手にかみついた。'),
('JPN', '使徒行传', 44, 28, 4, '島の人々は、この生き物がパウロの手にぶら下がっているのを見て、言い合った。「この人はきっと人殺しだ。海からは救われたが、正義の女神はこの人を生かしておかないのだ。」'),
('JPN', '使徒行传', 44, 28, 5, 'しかし、パウロはその生き物を火の中に振り落として、何の害も受けなかった。'),
('JPN', '使徒行传', 44, 28, 6, '人々は、彼が今にも腫れ上がってくるか、あるいは急に倒れて死ぬだろうと待っていた。しかし、いくら待っても彼に何も変わった様子が見えないので、考えを変えて、「この人は神様だ」と言い出した。'),
('JPN', '使徒行传', 44, 28, 7, 'さて、その場所の近くに、島の長官でプブリウスという名の人の所有地があった。彼は私たちを歓迎して、三日間親切にもてなしてくれた。'),
('JPN', '使徒行传', 44, 28, 8, 'たまたまプブリウスの父が、発熱と下痢で苦しんで床についていた。パウロはその人のところに行って、彼に手を置いて祈り、癒やした。'),
('JPN', '使徒行传', 44, 28, 9, 'このことがあってから、島にいたほかの病人たちもやって来て、癒やしを受けた。'),
('JPN', '使徒行传', 44, 28, 10, 'また人々は私たちに深い尊敬を表し、私たちが船出するときには、必要な物を用意してくれた。'),
('JPN', '使徒行传', 44, 28, 11, '三か月後、私たちは、この島で冬を越していたアレクサンドリアの船で出発した。その船首にはディオスクロイの飾りが付いていた。'),
('JPN', '使徒行传', 44, 28, 12, '私たちはシラクサに寄港して、三日間そこに滞在し、'),
('JPN', '使徒行传', 44, 28, 13, 'そこから錨を上げて、レギオンに達した。一日たつと南風が吹き始めたので、二日目にはプテオリに入港した。'),
('JPN', '使徒行传', 44, 28, 14, 'その町で、私たちは兄弟たちを見つけ、勧められるままに彼らのところに七日間滞在した。こうして、私たちはローマにやって来た。'),
('JPN', '使徒行传', 44, 28, 15, 'ローマからは、私たちのことを聞いた兄弟たちが、アピイ・フォルムとトレス・タベルネまで、私たちを迎えに来てくれた。パウロは彼らに会って、神に感謝し、勇気づけられた。'),
('JPN', '使徒行传', 44, 28, 16, '私たちがローマに入ったとき、パウロは、監視の兵士が付いてはいたが、一人で生活することを許された。'),
('JPN', '使徒行传', 44, 28, 17, '三日後、パウロはユダヤ人のおもだった人たちを呼び集めた。そして、彼らが集まったとき、こう言った。「兄弟たち。私は、民に対しても先祖の慣習に対しても、何一つ背くことはしていないにもかかわらず、エルサレムで囚人としてローマ人の手に渡されました。'),
('JPN', '使徒行传', 44, 28, 18, '彼らは私を取り調べましたが、私に死に値する罪が何もなかったので、釈放しようと思いました。'),
('JPN', '使徒行传', 44, 28, 19, 'ところが、ユダヤ人たちが反対したため、私は仕方なくカエサルに上訴しました。自分の同胞を訴えようとしたわけではありません。'),
('JPN', '使徒行传', 44, 28, 20, 'そういうわけで、私はあなたがたに会ってお話ししたいと願ったのです。私がこの鎖につながれているのは、イスラエルの望みのためです。」'),
('JPN', '使徒行传', 44, 28, 21, 'すると、彼らはパウロに言った。「私たちは、あなたについて、ユダヤから何の通知も受け取っていません。また、ここに来た兄弟たちのだれかが、あなたについて何か悪いことを告げたり、話したりしたこともありません。'),
('JPN', '使徒行传', 44, 28, 22, '私たちは、あなたが考えておられることを、あなたから聞くのがよいと思っています。この宗派について、いたるところで反対があるということを、私たちは耳にしていますから。」'),
('JPN', '使徒行传', 44, 28, 23, 'そこで彼らは日を定めて、さらに大勢でパウロの宿にやって来た。パウロは、神の国のことを証しし、モーセの律法と預言者たちの書からイエスについて彼らを説得しようと、朝から晩まで説明を続けた。'),
('JPN', '使徒行传', 44, 28, 24, 'ある人たちは彼が語ることを受け入れたが、ほかの人たちは信じようとしなかった。'),
('JPN', '使徒行传', 44, 28, 25, '互いの意見が一致しないまま彼らが帰ろうとしたので、パウロは一言、次のように言った。「まさしく聖霊が、預言者イザヤを通して、あなたがたの先祖に語られたとおりです。'),
('JPN', '使徒行传', 44, 28, 26, '『この民のところに行って告げよ。あなたがたは聞くには聞くが、決して悟ることはない。見るには見るが、決して知ることはない。'),
('JPN', '使徒行传', 44, 28, 27, 'この民の心は鈍くなり、耳は遠くなり、目は閉じているからである。彼らがその目で見ることも、耳で聞くことも、心で悟ることも、立ち返ることもないように。そして、わたしが癒やすこともないように。』'),
('JPN', '使徒行传', 44, 28, 28, 'ですから、承知しておいてください。神のこの救いは、異邦人に送られました。彼らが聞き従うことになります。」'),
('JPN', '使徒行传', 44, 28, 30, 'パウロは、まる二年間、自費で借りた家に住み、訪ねて来る人たちをみな迎えて、'),
('JPN', '使徒行传', 44, 28, 31, '少しもはばかることなく、また妨げられることもなく、神の国を宣べ伝え、主イエス・キリストのことを教えた。'),
('JPN', '罗马书', 45, 1, 1, 'キリスト・イエスのしもべ、神の福音のために選び出され、使徒として召されたパウロから。'),
('JPN', '罗马书', 45, 1, 2, '──この福音は、神がご自分の預言者たちを通して、聖書にあらかじめ約束されたもので、'),
('JPN', '罗马书', 45, 1, 3, '御子に関するものです。御子は、肉によればダビデの子孫から生まれ、'),
('JPN', '罗马书', 45, 1, 4, '聖なる霊によれば、死者の中からの復活により、力ある神の子として公に示された方、私たちの主イエス・キリストです。'),
('JPN', '罗马书', 45, 1, 5, 'この方によって、私たちは恵みと使徒の務めを受けました。御名のために、すべての異邦人の中に信仰の従順をもたらすためです。'),
('JPN', '罗马书', 45, 1, 6, 'その異邦人たちの中にあって、あなたがたも召されてイエス・キリストのものとなりました──'),
('JPN', '罗马书', 45, 1, 7, 'ローマにいるすべての、神に愛され、召された聖徒たちへ。私たちの父なる神と主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '罗马书', 45, 1, 8, 'まず初めに、私はあなたがたすべてについて、イエス・キリストを通して私の神に感謝します。全世界であなたがたの信仰が語り伝えられているからです。'),
('JPN', '罗马书', 45, 1, 9, '私が御子の福音を伝えつつ心から仕えている神が証ししてくださることですが、私は絶えずあなたがたのことを思い、'),
('JPN', '罗马书', 45, 1, 10, '祈るときにはいつも、神のみこころによって、今度こそついに道が開かれ、何とかしてあなたがたのところに行けるようにと願っています。'),
('JPN', '罗马书', 45, 1, 11, '私があなたがたに会いたいと切に望むのは、御霊の賜物をいくらかでも分け与えて、あなたがたを強くしたいからです。'),
('JPN', '罗马书', 45, 1, 12, 'というより、あなたがたの間にあって、あなたがたと私の互いの信仰によって、ともに励ましを受けたいのです。'),
('JPN', '罗马书', 45, 1, 13, '兄弟たち、知らずにいてほしくはありません。私はほかの異邦人たちの間で得たように、あなたがたの間でもいくらかの実を得ようと、何度もあなたがたのところに行く計画を立てましたが、今に至るまで妨げられてきました。'),
('JPN', '罗马书', 45, 1, 14, '私は、ギリシア人にも未開の人にも、知識のある人にも知識のない人にも、負い目のある者です。'),
('JPN', '罗马书', 45, 1, 15, 'ですから私としては、ローマにいるあなたがたにも、ぜひ福音を伝えたいのです。'),
('JPN', '罗马书', 45, 1, 16, '私は福音を恥としません。福音は、ユダヤ人をはじめギリシア人にも、信じるすべての人に救いをもたらす神の力です。'),
('JPN', '罗马书', 45, 1, 17, '福音には神の義が啓示されていて、信仰に始まり信仰に進ませるからです。「義人は信仰によって生きる」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 1, 18, 'というのは、不義によって真理を阻んでいる人々のあらゆる不敬虔と不義に対して、神の怒りが天から啓示されているからです。'),
('JPN', '罗马书', 45, 1, 19, '神について知りうることは、彼らの間で明らかです。神が彼らに明らかにされたのです。'),
('JPN', '罗马书', 45, 1, 20, '神の、目に見えない性質、すなわち神の永遠の力と神性は、世界が創造されたときから被造物を通して知られ、はっきりと認められるので、彼らに弁解の余地はありません。'),
('JPN', '罗马书', 45, 1, 21, '彼らは神を知っていながら、神を神としてあがめず、感謝もせず、かえってその思いはむなしくなり、その鈍い心は暗くなったのです。'),
('JPN', '罗马书', 45, 1, 22, '彼らは、自分たちは知者であると主張しながら愚かになり、'),
('JPN', '罗马书', 45, 1, 23, '朽ちない神の栄光を、朽ちる人間や、鳥、獣、這うものに似たかたちと替えてしまいました。'),
('JPN', '罗马书', 45, 1, 24, 'そこで神は、彼らをその心の欲望のままに汚れに引き渡されました。そのため、彼らは互いに自分たちのからだを辱めています。'),
('JPN', '罗马书', 45, 1, 25, '彼らは神の真理を偽りと取り替え、造り主の代わりに、造られた物を拝み、これに仕えました。造り主こそ、とこしえにほめたたえられる方です。アーメン。'),
('JPN', '罗马书', 45, 1, 26, 'こういうわけで、神は彼らを恥ずべき情欲に引き渡されました。すなわち、彼らのうちの女たちは自然な関係を自然に反するものに替え、'),
('JPN', '罗马书', 45, 1, 27, '同じように男たちも、女との自然な関係を捨てて、男同士で情欲に燃えました。男が男と恥ずべきことを行い、その誤りに対する当然の報いをその身に受けています。'),
('JPN', '罗马书', 45, 1, 28, 'また、彼らは神を知ることに価値を認めなかったので、神は彼らを無価値な思いに引き渡されました。それで彼らは、してはならないことを行っているのです。'),
('JPN', '罗马书', 45, 1, 29, '彼らは、あらゆる不義、悪、貪欲、悪意に満ち、ねたみ、殺意、争い、欺き、悪巧みにまみれています。また彼らは陰口を言い、'),
('JPN', '罗马书', 45, 1, 30, '人を中傷し、神を憎み、人を侮り、高ぶり、大言壮語し、悪事を企み、親に逆らい、'),
('JPN', '罗马书', 45, 1, 31, '浅はかで、不誠実で、情け知らずで、無慈悲です。'),
('JPN', '罗马书', 45, 1, 32, '彼らは、そのような行いをする者たちが死に値するという神の定めを知りながら、自らそれを行っているだけでなく、それを行う者たちに同意もしているのです。'),
('JPN', '罗马书', 45, 2, 1, 'ですから、すべて他人をさばく者よ、あなたに弁解の余地はありません。あなたは他人をさばくことで、自分自身にさばきを下しています。さばくあなたが同じことを行っているからです。'),
('JPN', '罗马书', 45, 2, 2, 'そのようなことを行う者たちの上に、真理に基づいて神のさばきが下ることを、私たちは知っています。'),
('JPN', '罗马书', 45, 2, 3, 'そのようなことを行う者たちをさばきながら、同じことを行っている者よ、あなたは神のさばきを免れるとでも思っているのですか。'),
('JPN', '罗马书', 45, 2, 4, 'それとも、神のいつくしみ深さがあなたを悔い改めに導くことも知らないで、その豊かないつくしみと忍耐と寛容を軽んじているのですか。'),
('JPN', '罗马书', 45, 2, 5, 'あなたは、頑なで悔い改める心がないために、神の正しいさばきが現れる御怒りの日の怒りを、自分のために蓄えています。'),
('JPN', '罗马书', 45, 2, 6, '神は、一人ひとり、その人の行いに応じて報いられます。'),
('JPN', '罗马书', 45, 2, 7, '忍耐をもって善を行い、栄光と誉れと朽ちないものを求める者には、永遠のいのちを与え、'),
('JPN', '罗马书', 45, 2, 8, '利己的な思いから真理に従わず、不義に従う者には、怒りと憤りを下されます。'),
('JPN', '罗马书', 45, 2, 9, '悪を行うすべての者の上には、ユダヤ人をはじめギリシア人にも、苦難と苦悩が下り、'),
('JPN', '罗马书', 45, 2, 10, '善を行うすべての者には、ユダヤ人をはじめギリシア人にも、栄光と誉れと平和が与えられます。'),
('JPN', '罗马书', 45, 2, 11, '神にはえこひいきがないからです。'),
('JPN', '罗马书', 45, 2, 12, '律法なしに罪を犯した者はみな、律法なしに滅び、律法の下にあって罪を犯した者はみな、律法によってさばかれます。'),
('JPN', '罗马书', 45, 2, 13, 'なぜなら、律法を聞く者が神の前に正しいのではなく、律法を行う者が義と認められるからです。'),
('JPN', '罗马书', 45, 2, 14, '律法を持たない異邦人が、生まれつきのままで律法の命じることを行う場合は、律法を持たなくても、彼ら自身が自分に対する律法なのです。'),
('JPN', '罗马书', 45, 2, 15, '彼らは、律法の命じる行いが自分の心に記されていることを示しています。彼らの良心も証ししていて、彼らの心の思いは互いに責め合ったり、また弁明し合ったりさえするのです。'),
('JPN', '罗马书', 45, 2, 16, '私の福音によれば、神のさばきは、神がキリスト・イエスによって、人々の隠された事柄をさばかれるその日に行われるのです。'),
('JPN', '罗马书', 45, 2, 17, 'あなたが自らユダヤ人と称し、律法を頼みとし、神を誇り、'),
('JPN', '罗马书', 45, 2, 18, 'みこころを知り、律法から教えられて、大切なことをわきまえているなら、'),
('JPN', '罗马书', 45, 2, 19, 'また、律法のうちに具体的に示された知識と真理を持っているので、目の見えない人の案内人、闇の中にいる者の光、愚かな者の導き手、幼子の教師だ、と自負しているなら、'),
('JPN', '罗马书', 45, 2, 21, 'どうして、他人を教えながら、自分自身を教えないのですか。盗むなと説きながら、自分は盗むのですか。'),
('JPN', '罗马书', 45, 2, 22, '姦淫するなと言いながら、自分は姦淫するのですか。偶像を忌み嫌いながら、神殿の物をかすめ取るのですか。'),
('JPN', '罗马书', 45, 2, 23, '律法を誇りとするあなたは、律法に違反することで、神を侮っているのです。'),
('JPN', '罗马书', 45, 2, 24, '「あなたがたのゆえに、神の御名は異邦人の間で汚されている」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 2, 25, 'もしあなたが律法を行うなら、割礼には価値があります。しかし、もしあなたが律法の違反者であるなら、あなたの割礼は無割礼になったのです。'),
('JPN', '罗马书', 45, 2, 26, 'ですから、もし割礼を受けていない人が律法の規定を守るなら、その人の無割礼は割礼と見なされるのではないでしょうか。'),
('JPN', '罗马书', 45, 2, 27, 'からだは無割礼でも律法を守る人が、律法の文字と割礼がありながらも律法に違反するあなたを、さばくことになります。'),
('JPN', '罗马书', 45, 2, 28, '外見上のユダヤ人がユダヤ人ではなく、また、外見上のからだの割礼が割礼ではないからです。'),
('JPN', '罗马书', 45, 2, 29, 'かえって人目に隠れたユダヤ人がユダヤ人であり、文字ではなく、御霊による心の割礼こそ割礼だからです。その人への称賛は人からではなく、神から来ます。'),
('JPN', '罗马书', 45, 3, 1, 'それでは、ユダヤ人のすぐれている点は何ですか。割礼に何の益があるのですか。'),
('JPN', '罗马书', 45, 3, 2, 'あらゆる点から見て、それは大いにあります。第一に、彼らは神のことばを委ねられました。'),
('JPN', '罗马书', 45, 3, 3, 'では、どうですか。彼らのうちに不真実な者がいたなら、その不真実は神の真実を無にするのでしょうか。'),
('JPN', '罗马书', 45, 3, 4, '決してそんなことはありません。たとえすべての人が偽り者であるとしても、神は真実な方であるとすべきです。「それゆえ、あなたが告げるとき、あなたは正しくあられ、さばくとき、勝利を得られます」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 3, 5, 'では、もし私たちの不義が神の義を明らかにするのなら、私たちはどのように言うべきでしょうか。私は人間的な言い方をしますが、御怒りを下す神は不義なのでしょうか。'),
('JPN', '罗马书', 45, 3, 6, '決してそんなことはありません。もしそうなら、神はどのようにして世界をさばかれるのですか。'),
('JPN', '罗马书', 45, 3, 7, 'では、もし私の偽りによって神の真理がますます明らかにされて、神の栄光となるのなら、どうして私はなおも罪人としてさばかれるのですか。'),
('JPN', '罗马书', 45, 3, 8, '「善をもたらすために悪を行おう」ということになりませんか。私たちがそう言っていると、ある者たちから中傷されています。そのように中傷する者たちが、さばきを受けるのは当然です。'),
('JPN', '罗马书', 45, 3, 9, 'では、どうなのでしょう。私たちにすぐれているところはあるのでしょうか。全くありません。私たちがすでに指摘したように、ユダヤ人もギリシア人も、すべての人が罪の下にあるからです。'),
('JPN', '罗马书', 45, 3, 10, '次のように書いてあるとおりです。「義人はいない。一人もいない。'),
('JPN', '罗马书', 45, 3, 11, '悟る者はいない。神を求める者はいない。'),
('JPN', '罗马书', 45, 3, 12, 'すべての者が離れて行き、だれもかれも無用の者となった。善を行う者はいない。だれ一人いない。」'),
('JPN', '罗马书', 45, 3, 13, '「彼らの喉は開いた墓。彼らはその舌で欺く。」「彼らの唇の下にはまむしの毒がある。」'),
('JPN', '罗马书', 45, 3, 14, '「彼らの口は、呪いと苦みに満ちている。」'),
('JPN', '罗马书', 45, 3, 15, '「彼らの足は血を流すのに速く、'),
('JPN', '罗马书', 45, 3, 16, '彼らの道には破壊と悲惨がある。'),
('JPN', '罗马书', 45, 3, 17, '彼らは平和の道を知らない。」'),
('JPN', '罗马书', 45, 3, 18, '「彼らの目の前には、神に対する恐れがない。」'),
('JPN', '罗马书', 45, 3, 19, '私たちは知っています。律法が言うことはみな、律法の下にある者たちに対して語られているのです。それは、すべての口がふさがれて、全世界が神のさばきに服するためです。'),
('JPN', '罗马书', 45, 3, 20, 'なぜなら、人はだれも、律法を行うことによっては神の前に義と認められないからです。律法を通して生じるのは罪の意識です。'),
('JPN', '罗马书', 45, 3, 21, 'しかし今や、律法とは関わりなく、律法と預言者たちの書によって証しされて、神の義が示されました。'),
('JPN', '罗马书', 45, 3, 22, 'すなわち、イエス・キリストを信じることによって、信じるすべての人に与えられる神の義です。そこに差別はありません。'),
('JPN', '罗马书', 45, 3, 23, 'すべての人は罪を犯して、神の栄光を受けることができず、'),
('JPN', '罗马书', 45, 3, 24, '神の恵みにより、キリスト・イエスによる贖いを通して、価なしに義と認められるからです。'),
('JPN', '罗马书', 45, 3, 25, '神はこの方を、信仰によって受けるべき、血による宥めのささげ物として公に示されました。ご自分の義を明らかにされるためです。神は忍耐をもって、これまで犯されてきた罪を見逃してこられたのです。'),
('JPN', '罗马书', 45, 3, 26, 'すなわち、ご自分が義であり、イエスを信じる者を義と認める方であることを示すため、今この時に、ご自分の義を明らかにされたのです。'),
('JPN', '罗马书', 45, 3, 27, 'それでは、私たちの誇りはどこにあるのでしょうか。それは取り除かれました。どのような種類の律法によってでしょうか。行いの律法でしょうか。いいえ、信仰の律法によってです。'),
('JPN', '罗马书', 45, 3, 28, '人は律法の行いとは関わりなく、信仰によって義と認められると、私たちは考えているからです。'),
('JPN', '罗马书', 45, 3, 29, 'それとも、神はユダヤ人だけの神でしょうか。異邦人の神でもあるのではないでしょうか。そうです。異邦人の神でもあります。'),
('JPN', '罗马书', 45, 3, 30, '神が唯一なら、そうです。神は、割礼のある者を信仰によって義と認め、割礼のない者も信仰によって義と認めてくださるのです。'),
('JPN', '罗马书', 45, 3, 31, 'それでは、私たちは信仰によって律法を無効にすることになるのでしょうか。決してそんなことはありません。むしろ、律法を確立することになります。'),
('JPN', '罗马书', 45, 4, 1, 'それでは、肉による私たちの父祖アブラハムは何を見出した、と言えるのでしょうか。'),
('JPN', '罗马书', 45, 4, 2, 'もしアブラハムが行いによって義と認められたのであれば、彼は誇ることができます。しかし、神の御前ではそうではありません。'),
('JPN', '罗马书', 45, 4, 3, '聖書は何と言っていますか。「アブラハムは神を信じた。それで、それが彼の義と認められた」とあります。'),
('JPN', '罗马书', 45, 4, 4, '働く者にとっては、報酬は恵みによるものではなく、当然支払われるべきものと見なされます。'),
('JPN', '罗马书', 45, 4, 5, 'しかし、働きがない人であっても、不敬虔な者を義と認める方を信じる人には、その信仰が義と認められます。'),
('JPN', '罗马书', 45, 4, 6, '同じようにダビデも、行いと関わりなく、神が義とお認めになる人の幸いを、このように言っています。'),
('JPN', '罗马书', 45, 4, 7, '「幸いなことよ、不法を赦され、罪をおおわれた人たち。'),
('JPN', '罗马书', 45, 4, 8, '幸いなことよ、主が罪をお認めにならない人。」'),
('JPN', '罗马书', 45, 4, 9, 'それでは、この幸いは、割礼のある者にだけ与えられるのでしょうか。それとも、割礼のない者にも与えられるのでしょうか。私たちは、「アブラハムには、その信仰が義と認められた」と言っていますが、'),
('JPN', '罗马书', 45, 4, 10, 'どのようにして、その信仰が義と認められたのでしょうか。割礼を受けてからですか。割礼を受けていないときですか。割礼を受けてからではなく、割礼を受けていないときです。'),
('JPN', '罗马书', 45, 4, 11, '彼は、割礼を受けていないときに信仰によって義と認められたことの証印として、割礼というしるしを受けたのです。それは、彼が、割礼を受けないままで信じるすべての人の父となり、彼らも義と認められるためであり、'),
('JPN', '罗马书', 45, 4, 12, 'また、単に割礼を受けているだけではなく、私たちの父アブラハムが割礼を受けていなかったときの信仰の足跡にしたがって歩む者たちにとって、割礼の父となるためでした。'),
('JPN', '罗马书', 45, 4, 13, 'というのは、世界の相続人となるという約束が、アブラハムに、あるいは彼の子孫に与えられたのは、律法によってではなく、信仰による義によってであったからです。'),
('JPN', '罗马书', 45, 4, 14, 'もし律法による者たちが相続人であるなら、信仰は空しくなり、約束は無効になってしまいます。'),
('JPN', '罗马书', 45, 4, 15, '実際、律法は御怒りを招くものです。律法のないところには違反もありません。'),
('JPN', '罗马书', 45, 4, 16, 'そのようなわけで、すべては信仰によるのです。それは、事が恵みによるようになるためです。こうして、約束がすべての子孫に、すなわち、律法を持つ人々だけでなく、アブラハムの信仰に倣う人々にも保証されるのです。アブラハムは、私たちすべての者の父です。'),
('JPN', '罗马书', 45, 4, 17, '「わたしはあなたを多くの国民の父とした」と書いてあるとおりです。彼は、死者を生かし、無いものを有るものとして召される神を信じ、その御前で父となったのです。'),
('JPN', '罗马书', 45, 4, 18, '彼は望み得ない時に望みを抱いて信じ、「あなたの子孫は、このようになる」と言われていたとおり、多くの国民の父となりました。'),
('JPN', '罗马书', 45, 4, 19, '彼は、およそ百歳になり、自分のからだがすでに死んだも同然であること、またサラの胎が死んでいることを認めても、その信仰は弱まりませんでした。'),
('JPN', '罗马书', 45, 4, 20, '不信仰になって神の約束を疑うようなことはなく、かえって信仰が強められて、神に栄光を帰し、'),
('JPN', '罗马书', 45, 4, 21, '神には約束したことを実行する力がある、と確信していました。'),
('JPN', '罗马书', 45, 4, 22, 'だからこそ、「彼には、それが義と認められた」のです。'),
('JPN', '罗马书', 45, 4, 23, 'しかし、「彼には、それが義と認められた」と書かれたのは、ただ彼のためだけでなく、'),
('JPN', '罗马书', 45, 4, 24, '私たちのためでもあります。すなわち、私たちの主イエスを死者の中からよみがえらせた方を信じる私たちも、義と認められるのです。'),
('JPN', '罗马书', 45, 4, 25, '主イエスは、私たちの背きの罪のゆえに死に渡され、私たちが義と認められるために、よみがえられました。'),
('JPN', '罗马书', 45, 5, 1, 'こうして、私たちは信仰によって義と認められたので、私たちの主イエス・キリストによって、神との平和を持っています。'),
('JPN', '罗马书', 45, 5, 2, 'このキリストによって私たちは、信仰によって、今立っているこの恵みに導き入れられました。そして、神の栄光にあずかる望みを喜んでいます。'),
('JPN', '罗马书', 45, 5, 3, 'それだけではなく、苦難さえも喜んでいます。それは、苦難が忍耐を生み出し、'),
('JPN', '罗马书', 45, 5, 4, '忍耐が練られた品性を生み出し、練られた品性が希望を生み出すと、私たちは知っているからです。'),
('JPN', '罗马书', 45, 5, 5, 'この希望は失望に終わることがありません。なぜなら、私たちに与えられた聖霊によって、神の愛が私たちの心に注がれているからです。'),
('JPN', '罗马书', 45, 5, 6, '実にキリストは、私たちがまだ弱かったころ、定められた時に、不敬虔な者たちのために死んでくださいました。'),
('JPN', '罗马书', 45, 5, 7, '正しい人のためであっても、死ぬ人はほとんどいません。善良な人のためなら、進んで死ぬ人がいるかもしれません。'),
('JPN', '罗马书', 45, 5, 8, 'しかし、私たちがまだ罪人であったとき、キリストが私たちのために死なれたことによって、神は私たちに対するご自分の愛を明らかにしておられます。'),
('JPN', '罗马书', 45, 5, 9, 'ですから、今、キリストの血によって義と認められた私たちが、この方によって神の怒りから救われるのは、なおいっそう確かなことです。'),
('JPN', '罗马书', 45, 5, 10, '敵であった私たちが、御子の死によって神と和解させていただいたのなら、和解させていただいた私たちが、御子のいのちによって救われるのは、なおいっそう確かなことです。'),
('JPN', '罗马书', 45, 5, 11, 'それだけではなく、私たちの主イエス・キリストによって、私たちは神を喜んでいます。キリストによって、今や、私たちは和解させていただいたのです。'),
('JPN', '罗马书', 45, 5, 12, 'こういうわけで、ちょうど一人の人によって罪が世界に入り、罪によって死が入り、こうして、すべての人が罪を犯したので、死がすべての人に広がったのと同様に──'),
('JPN', '罗马书', 45, 5, 13, '実に、律法が与えられる以前にも、罪は世にあったのですが、律法がなければ罪は罪として認められないのです。'),
('JPN', '罗马书', 45, 5, 14, 'けれども死は、アダムからモーセまでの間も、アダムの違反と同じようには罪を犯さなかった人々さえも、支配しました。アダムは来たるべき方のひな型です。'),
('JPN', '罗马书', 45, 5, 15, 'しかし、恵みの賜物は違反の場合と違います。もし一人の違反によって多くの人が死んだのなら、神の恵みと、一人の人イエス・キリストの恵みによる賜物は、なおいっそう、多くの人に満ちあふれるのです。'),
('JPN', '罗马书', 45, 5, 16, 'また賜物は、一人の人が罪を犯した結果とは違います。さばきの場合は、一つの違反から不義に定められましたが、恵みの場合は、多くの違反が義と認められるからです。'),
('JPN', '罗马书', 45, 5, 17, 'もし一人の違反により、一人によって死が支配するようになったのなら、なおさらのこと、恵みと義の賜物をあふれるばかり受けている人たちは、一人の人イエス・キリストにより、いのちにあって支配するようになるのです。'),
('JPN', '罗马书', 45, 5, 18, 'こういうわけで、ちょうど一人の違反によってすべての人が不義に定められたのと同様に、一人の義の行為によってすべての人が義と認められ、いのちを与えられます。'),
('JPN', '罗马书', 45, 5, 19, 'すなわち、ちょうど一人の人の不従順によって多くの人が罪人とされたのと同様に、一人の従順によって多くの人が義人とされるのです。'),
('JPN', '罗马书', 45, 5, 20, '律法が入って来たのは、違反が増し加わるためでした。しかし、罪の増し加わるところに、恵みも満ちあふれました。'),
('JPN', '罗马书', 45, 5, 21, 'それは、罪が死によって支配したように、恵みもまた義によって支配して、私たちの主イエス・キリストにより永遠のいのちに導くためなのです。'),
('JPN', '罗马书', 45, 6, 1, 'それでは、どのように言うべきでしょうか。恵みが増し加わるために、私たちは罪にとどまるべきでしょうか。'),
('JPN', '罗马书', 45, 6, 2, '決してそんなことはありません。罪に対して死んだ私たちが、どうしてなおも罪のうちに生きていられるでしょうか。'),
('JPN', '罗马书', 45, 6, 3, 'それとも、あなたがたは知らないのですか。キリスト・イエスにつくバプテスマを受けた私たちはみな、その死にあずかるバプテスマを受けたのではありませんか。'),
('JPN', '罗马书', 45, 6, 4, '私たちは、キリストの死にあずかるバプテスマによって、キリストとともに葬られたのです。それは、ちょうどキリストが御父の栄光によって死者の中からよみがえられたように、私たちも、新しいいのちに歩むためです。'),
('JPN', '罗马书', 45, 6, 5, '私たちがキリストの死と同じようになって、キリストと一つになっているなら、キリストの復活とも同じようになるからです。'),
('JPN', '罗马书', 45, 6, 6, '私たちは知っています。私たちの古い人がキリストとともに十字架につけられたのは、罪のからだが滅ぼされて、私たちがもはや罪の奴隷でなくなるためです。'),
('JPN', '罗马书', 45, 6, 7, '死んだ者は、罪から解放されているのです。'),
('JPN', '罗马书', 45, 6, 8, '私たちがキリストとともに死んだのなら、キリストとともに生きることにもなる、と私たちは信じています。'),
('JPN', '罗马书', 45, 6, 9, '私たちは知っています。キリストは死者の中からよみがえって、もはや死ぬことはありません。死はもはやキリストを支配しないのです。'),
('JPN', '罗马书', 45, 6, 10, 'なぜなら、キリストが死なれたのは、ただ一度罪に対して死なれたのであり、キリストが生きておられるのは、神に対して生きておられるのだからです。'),
('JPN', '罗马书', 45, 6, 11, '同じように、あなたがたもキリスト・イエスにあって、自分は罪に対して死んだ者であり、神に対して生きている者だと、認めなさい。'),
('JPN', '罗马书', 45, 6, 12, 'ですから、あなたがたの死ぬべきからだを罪に支配させて、からだの欲望に従ってはいけません。'),
('JPN', '罗马书', 45, 6, 13, 'また、あなたがたの手足を不義の道具として罪に献げてはいけません。むしろ、死者の中から生かされた者としてあなたがた自身を神に献げ、また、あなたがたの手足を義の道具として神に献げなさい。'),
('JPN', '罗马书', 45, 6, 14, '罪があなたがたを支配することはないからです。あなたがたは律法の下にではなく、恵みの下にあるのです。'),
('JPN', '罗马书', 45, 6, 15, 'では、どうなのでしょう。私たちは律法の下にではなく、恵みの下にあるのだから、罪を犯そう、となるのでしょうか。決してそんなことはありません。'),
('JPN', '罗马书', 45, 6, 16, 'あなたがたは知らないのですか。あなたがたが自分自身を奴隷として献げて服従すれば、その服従する相手の奴隷となるのです。つまり、罪の奴隷となって死に至り、あるいは従順の奴隷となって義に至ります。'),
('JPN', '罗马书', 45, 6, 17, '神に感謝します。あなたがたは、かつては罪の奴隷でしたが、伝えられた教えの規範に心から服従し、'),
('JPN', '罗马书', 45, 6, 18, '罪から解放されて、義の奴隷となりました。'),
('JPN', '罗马书', 45, 6, 19, 'あなたがたの肉の弱さのために、私は人間的な言い方をしています。以前あなたがたは、自分の手足を汚れと不法の奴隷として献げて、不法に進みました。同じように、今はその手足を義の奴隷として献げて、聖潔に進みなさい。'),
('JPN', '罗马书', 45, 6, 20, 'あなたがたは、罪の奴隷であったとき、義については自由にふるまっていました。'),
('JPN', '罗马书', 45, 6, 21, 'ではそのころ、あなたがたはどんな実を得ましたか。今では恥ずかしく思っているものです。それらの行き着くところは死です。'),
('JPN', '罗马书', 45, 6, 22, 'しかし今は、罪から解放されて神の奴隷となり、聖潔に至る実を得ています。その行き着くところは永遠のいのちです。'),
('JPN', '罗马书', 45, 6, 23, '罪の報酬は死です。しかし神の賜物は、私たちの主キリスト・イエスにある永遠のいのちです。'),
('JPN', '罗马书', 45, 7, 1, 'それとも、兄弟たち、あなたがたは知らないのですか──私は律法を知っている人たちに話しています──律法が人を支配するのは、その人が生きている期間だけです。'),
('JPN', '罗马书', 45, 7, 2, '結婚している女は、夫が生きている間は、律法によって夫に結ばれています。しかし、夫が死んだら、自分を夫に結びつけていた律法から解かれます。'),
('JPN', '罗马书', 45, 7, 3, 'したがって、夫が生きている間に他の男のものとなれば、姦淫の女と呼ばれますが、夫が死んだら律法から自由になるので、他の男のものとなっても姦淫の女とはなりません。'),
('JPN', '罗马书', 45, 7, 4, 'ですから、私の兄弟たちよ。あなたがたもキリストのからだを通して、律法に対して死んでいるのです。それは、あなたがたがほかの方、すなわち死者の中からよみがえった方のものとなり、こうして私たちが神のために実を結ぶようになるためです。'),
('JPN', '罗马书', 45, 7, 5, '私たちが肉にあったときは、律法によって目覚めた罪の欲情が私たちのからだの中に働いて、死のために実を結びました。'),
('JPN', '罗马书', 45, 7, 6, 'しかし今は、私たちは自分を縛っていた律法に死んだので、律法から解かれました。その結果、古い文字にはよらず、新しい御霊によって仕えているのです。'),
('JPN', '罗马书', 45, 7, 7, 'それでは、どのように言うべきでしょうか。律法は罪なのでしょうか。決してそんなことはありません。むしろ、律法によらなければ、私は罪を知ることはなかったでしょう。実際、律法が「隣人のものを欲してはならない」と言わなければ、私は欲望を知らなかったでしょう。'),
('JPN', '罗马书', 45, 7, 8, 'しかし、罪は戒めによって機会をとらえ、私のうちにあらゆる欲望を引き起こしました。律法がなければ、罪は死んだものです。'),
('JPN', '罗马书', 45, 7, 9, '私はかつて律法なしに生きていましたが、戒めが来たとき、罪は生き、'),
('JPN', '罗马书', 45, 7, 10, '私は死にました。それで、いのちに導くはずの戒めが、死に導くものであると分かりました。'),
('JPN', '罗马书', 45, 7, 11, '罪は戒めによって機会をとらえ、私を欺き、戒めによって私を殺したのです。'),
('JPN', '罗马书', 45, 7, 12, 'ですから、律法は聖なるものです。また戒めも聖なるものであり、正しく、また良いものです。'),
('JPN', '罗马书', 45, 7, 13, 'それでは、この良いものが、私に死をもたらしたのでしょうか。決してそんなことはありません。むしろ、罪がそれをもたらしたのです。罪は、この良いもので私に死をもたらすことによって、罪として明らかにされました。罪は戒めによって、限りなく罪深いものとなりました。'),
('JPN', '罗马书', 45, 7, 14, '私たちは、律法が霊的なものであることを知っています。しかし、私は肉的な者であり、売り渡されて罪の下にある者です。'),
('JPN', '罗马书', 45, 7, 15, '私には、自分のしていることが分かりません。自分がしたいと願うことはせずに、むしろ自分が憎んでいることを行っているからです。'),
('JPN', '罗马书', 45, 7, 16, '自分のしたくないことを行っているなら、私は律法に同意し、それを良いものと認めていることになります。'),
('JPN', '罗马书', 45, 7, 17, 'ですから、今それを行っているのは、もはや私ではなく、私のうちに住んでいる罪なのです。'),
('JPN', '罗马书', 45, 7, 18, '私は、自分のうちに、すなわち、自分の肉のうちに善が住んでいないことを知っています。私には良いことをしたいという願いがいつもあるのに、実行できないからです。'),
('JPN', '罗马书', 45, 7, 19, '私は、したいと願う善を行わないで、したくない悪を行っています。'),
('JPN', '罗马书', 45, 7, 20, '私が自分でしたくないことをしているなら、それを行っているのは、もはや私ではなく、私のうちに住んでいる罪です。'),
('JPN', '罗马书', 45, 7, 21, 'そういうわけで、善を行いたいと願っている、その私に悪が存在するという原理を、私は見出します。'),
('JPN', '罗马书', 45, 7, 22, '私は、内なる人としては、神の律法を喜んでいますが、'),
('JPN', '罗马书', 45, 7, 23, '私のからだには異なる律法があって、それが私の心の律法に対して戦いを挑み、私を、からだにある罪の律法のうちにとりこにしていることが分かるのです。'),
('JPN', '罗马书', 45, 7, 24, '私は本当にみじめな人間です。だれがこの死のからだから、私を救い出してくれるのでしょうか。'),
('JPN', '罗马书', 45, 7, 25, '私たちの主イエス・キリストを通して、神に感謝します。こうして、この私は、心では神の律法に仕え、肉では罪の律法に仕えているのです。'),
('JPN', '罗马书', 45, 8, 1, 'こういうわけで、今や、キリスト・イエスにある者が罪に定められることは決してありません。'),
('JPN', '罗马书', 45, 8, 2, 'なぜなら、キリスト・イエスにあるいのちの御霊の律法が、罪と死の律法からあなたを解放したからです。'),
('JPN', '罗马书', 45, 8, 3, '肉によって弱くなったため、律法にできなくなったことを、神はしてくださいました。神はご自分の御子を、罪深い肉と同じような形で、罪のきよめのために遣わし、肉において罪を処罰されたのです。'),
('JPN', '罗马书', 45, 8, 4, 'それは、肉に従わず御霊に従って歩む私たちのうちに、律法の要求が満たされるためなのです。'),
('JPN', '罗马书', 45, 8, 5, '肉に従う者は肉に属することを考えますが、御霊に従う者は御霊に属することを考えます。'),
('JPN', '罗马书', 45, 8, 6, '肉の思いは死ですが、御霊の思いはいのちと平安です。'),
('JPN', '罗马书', 45, 8, 7, 'なぜなら、肉の思いは神に敵対するからです。それは神の律法に従いません。いや、従うことができないのです。'),
('JPN', '罗马书', 45, 8, 8, '肉のうちにある者は神を喜ばせることができません。'),
('JPN', '罗马书', 45, 8, 9, 'しかし、もし神の御霊があなたがたのうちに住んでおられるなら、あなたがたは肉のうちにではなく、御霊のうちにいるのです。もし、キリストの御霊を持っていない人がいれば、その人はキリストのものではありません。'),
('JPN', '罗马书', 45, 8, 10, 'キリストがあなたがたのうちにおられるなら、からだは罪のゆえに死んでいても、御霊が義のゆえにいのちとなっています。'),
('JPN', '罗马书', 45, 8, 11, 'イエスを死者の中からよみがえらせた方の御霊が、あなたがたのうちに住んでおられるなら、キリストを死者の中からよみがえらせた方は、あなたがたのうちに住んでおられるご自分の御霊によって、あなたがたの死ぬべきからだも生かしてくださいます。'),
('JPN', '罗马书', 45, 8, 12, 'ですから、兄弟たちよ、私たちには義務があります。肉に従って生きなければならないという、肉に対する義務ではありません。'),
('JPN', '罗马书', 45, 8, 13, 'もし肉に従って生きるなら、あなたがたは死ぬことになります。しかし、もし御霊によってからだの行いを殺すなら、あなたがたは生きます。'),
('JPN', '罗马书', 45, 8, 14, '神の御霊に導かれる人はみな、神の子どもです。'),
('JPN', '罗马书', 45, 8, 15, 'あなたがたは、人を再び恐怖に陥れる、奴隷の霊を受けたのではなく、子とする御霊を受けたのです。この御霊によって、私たちは「アバ、父」と叫びます。'),
('JPN', '罗马书', 45, 8, 16, '御霊ご自身が、私たちの霊とともに、私たちが神の子どもであることを証ししてくださいます。'),
('JPN', '罗马书', 45, 8, 17, '子どもであるなら、相続人でもあります。私たちはキリストと、栄光をともに受けるために苦難をともにしているのですから、神の相続人であり、キリストとともに共同相続人なのです。'),
('JPN', '罗马书', 45, 8, 18, '今の時の苦難は、やがて私たちに啓示される栄光に比べれば、取るに足りないと私は考えます。'),
('JPN', '罗马书', 45, 8, 19, '被造物は切実な思いで、神の子どもたちが現れるのを待ち望んでいます。'),
('JPN', '罗马书', 45, 8, 20, '被造物が虚無に服したのは、自分の意志からではなく、服従させた方によるものなので、彼らには望みがあるのです。'),
('JPN', '罗马书', 45, 8, 21, '被造物自体も、滅びの束縛から解放され、神の子どもたちの栄光の自由にあずかります。'),
('JPN', '罗马书', 45, 8, 22, '私たちは知っています。被造物のすべては、今に至るまで、ともにうめき、ともに産みの苦しみをしています。'),
('JPN', '罗马书', 45, 8, 23, 'それだけでなく、御霊の初穂をいただいている私たち自身も、子にしていただくこと、すなわち、私たちのからだが贖われることを待ち望みながら、心の中でうめいています。'),
('JPN', '罗马书', 45, 8, 24, '私たちは、この望みとともに救われたのです。目に見える望みは望みではありません。目で見ているものを、だれが望むでしょうか。'),
('JPN', '罗马书', 45, 8, 25, '私たちはまだ見ていないものを望んでいるのですから、忍耐して待ち望みます。'),
('JPN', '罗马书', 45, 8, 26, '同じように御霊も、弱い私たちを助けてくださいます。私たちは、何をどう祈ったらよいか分からないのですが、御霊ご自身が、ことばにならないうめきをもって、とりなしてくださるのです。'),
('JPN', '罗马书', 45, 8, 27, '人間の心を探る方は、御霊の思いが何であるかを知っておられます。なぜなら、御霊は神のみこころにしたがって、聖徒たちのためにとりなしてくださるからです。'),
('JPN', '罗马书', 45, 8, 28, '神を愛する人たち、すなわち、神のご計画にしたがって召された人たちのためには、すべてのことがともに働いて益となることを、私たちは知っています。'),
('JPN', '罗马书', 45, 8, 29, '神は、あらかじめ知っている人たちを、御子のかたちと同じ姿にあらかじめ定められたのです。それは、多くの兄弟たちの中で御子が長子となるためです。'),
('JPN', '罗马书', 45, 8, 30, '神は、あらかじめ定めた人たちをさらに召し、召した人たちをさらに義と認め、義と認めた人たちにはさらに栄光をお与えになりました。'),
('JPN', '罗马书', 45, 8, 31, 'では、これらのことについて、どのように言えるでしょうか。神が私たちの味方であるなら、だれが私たちに敵対できるでしょう。'),
('JPN', '罗马书', 45, 8, 32, '私たちすべてのために、ご自分の御子さえも惜しむことなく死に渡された神が、どうして、御子とともにすべてのものを、私たちに恵んでくださらないことがあるでしょうか。'),
('JPN', '罗马书', 45, 8, 33, 'だれが、神に選ばれた者たちを訴えるのですか。神が義と認めてくださるのです。'),
('JPN', '罗马书', 45, 8, 34, 'だれが、私たちを罪ありとするのですか。死んでくださった方、いや、よみがえられた方であるキリスト・イエスが、神の右の座に着き、しかも私たちのために、とりなしていてくださるのです。'),
('JPN', '罗马书', 45, 8, 35, 'だれが、私たちをキリストの愛から引き離すのですか。苦難ですか、苦悩ですか、迫害ですか、飢えですか、裸ですか、危険ですか、剣ですか。'),
('JPN', '罗马书', 45, 8, 36, 'こう書かれています。「あなたのために、私たちは休みなく殺され、屠られる羊と見なされています。」'),
('JPN', '罗马书', 45, 8, 37, 'しかし、これらすべてにおいても、私たちを愛してくださった方によって、私たちは圧倒的な勝利者です。'),
('JPN', '罗马书', 45, 8, 38, '私はこう確信しています。死も、いのちも、御使いたちも、支配者たちも、今あるものも、後に来るものも、力あるものも、'),
('JPN', '罗马书', 45, 8, 39, '高いところにあるものも、深いところにあるものも、そのほかのどんな被造物も、私たちの主キリスト・イエスにある神の愛から、私たちを引き離すことはできません。'),
('JPN', '罗马书', 45, 9, 1, '私はキリストにあって真実を語り、偽りを言いません。私の良心も、聖霊によって私に対し証ししていますが、'),
('JPN', '罗马书', 45, 9, 2, '私には大きな悲しみがあり、私の心には絶えず痛みがあります。'),
('JPN', '罗马书', 45, 9, 3, '私は、自分の兄弟たち、肉による自分の同胞のためなら、私自身がキリストから引き離されて、のろわれた者となってもよいとさえ思っています。'),
('JPN', '罗马书', 45, 9, 4, '彼らはイスラエル人です。子とされることも、栄光も、契約も、律法の授与も、礼拝も、約束も彼らのものです。'),
('JPN', '罗马书', 45, 9, 5, '父祖たちも彼らのものです。キリストも、肉によれば彼らから出ました。キリストは万物の上にあり、とこしえにほむべき神です。アーメン。'),
('JPN', '罗马书', 45, 9, 6, 'しかし、神のことばは無効になったわけではありません。イスラエルから出た者がみな、イスラエルではないからです。'),
('JPN', '罗马书', 45, 9, 7, 'アブラハムの子どもたちがみな、アブラハムの子孫だということではありません。むしろ、「イサクにあって、あなたの子孫が起こされる」からです。'),
('JPN', '罗马书', 45, 9, 8, 'すなわち、肉の子どもがそのまま神の子どもなのではなく、むしろ、約束の子どもが子孫と認められるのです。'),
('JPN', '罗马书', 45, 9, 9, '約束のみことばはこうです。「わたしは来年の今ごろ来ます。そのとき、サラには男の子が生まれています。」'),
('JPN', '罗马书', 45, 9, 10, 'それだけではありません。一人の人、すなわち私たちの父イサクによって身ごもったリベカの場合もそうです。'),
('JPN', '罗马书', 45, 9, 11, 'その子どもたちがまだ生まれもせず、善も悪も行わないうちに、選びによる神のご計画が、'),
('JPN', '罗马书', 45, 9, 12, '行いによるのではなく、召してくださる方によって進められるために、「兄が弟に仕える」と彼女に告げられました。'),
('JPN', '罗马书', 45, 9, 13, '「わたしはヤコブを愛し、エサウを憎んだ」と書かれているとおりです。'),
('JPN', '罗马书', 45, 9, 14, 'それでは、どのように言うべきでしょうか。神に不正があるのでしょうか。決してそんなことはありません。'),
('JPN', '罗马书', 45, 9, 15, '神はモーセに言われました。「わたしはあわれもうと思う者をあわれみ、いつくしもうと思う者をいつくしむ。」'),
('JPN', '罗马书', 45, 9, 16, 'ですから、これは人の願いや努力によるのではなく、あわれんでくださる神によるのです。'),
('JPN', '罗马书', 45, 9, 17, '聖書はファラオにこう言っています。「このことのために、わたしはあなたを立てておいた。わたしの力をあなたに示すため、そうして、わたしの名を全地に知らしめるためである。」'),
('JPN', '罗马书', 45, 9, 18, 'ですから、神は人をみこころのままにあわれみ、またみこころのままに頑なにされるのです。'),
('JPN', '罗马书', 45, 9, 19, 'すると、あなたは私にこう言うでしょう。「それではなぜ、神はなおも人を責められるのですか。だれが神の意図に逆らえるのですか。」'),
('JPN', '罗马书', 45, 9, 20, '人よ。神に言い返すあなたは、いったい何者ですか。造られた者が造った者に「どうして私をこのように造ったのか」と言えるでしょうか。'),
('JPN', '罗马书', 45, 9, 21, '陶器師は同じ土のかたまりから、あるものは尊いことに用いる器に、別のものは普通の器に作る権利を持っていないのでしょうか。'),
('JPN', '罗马书', 45, 9, 22, 'それでいて、もし神が、御怒りを示してご自分の力を知らせようと望んでおられたのに、滅ぼされるはずの怒りの器を、豊かな寛容をもって耐え忍ばれたとすれば、どうですか。'),
('JPN', '罗马书', 45, 9, 23, 'しかもそれが、栄光のためにあらかじめ備えられたあわれみの器に対して、ご自分の豊かな栄光を知らせるためであったとすれば、どうですか。'),
('JPN', '罗马书', 45, 9, 24, 'このあわれみの器として、神は私たちを、ユダヤ人の中からだけでなく、異邦人の中からも召してくださったのです。'),
('JPN', '罗马书', 45, 9, 25, 'それは、ホセアの書でも神が言っておられるとおりです。「わたしは、わたしの民でない者をわたしの民と呼び、愛されない者を愛される者と呼ぶ。'),
('JPN', '罗马书', 45, 9, 26, 'あなたがたはわたしの民ではない、と言われたその場所で、彼らは生ける神の子らと呼ばれる。」'),
('JPN', '罗马书', 45, 9, 27, 'イザヤはイスラエルについてこう叫んでいます。「たとえ、イスラエルの子らの数が海の砂のようであっても、残りの者だけが救われる。'),
('JPN', '罗马书', 45, 9, 28, '主が、語られたことを完全に、かつ速やかに、地の上で行おうとしておられる。」'),
('JPN', '罗马书', 45, 9, 29, 'また、イザヤがあらかじめ告げたとおりです。「もしも、万軍の主が、私たちに子孫を残されなかったなら、私たちもソドムのようになり、ゴモラと同じようになっていたであろう。」'),
('JPN', '罗马书', 45, 9, 30, 'それでは、どのように言うべきでしょうか。義を追い求めなかった異邦人が義を、すなわち、信仰による義を得ました。'),
('JPN', '罗马书', 45, 9, 31, 'しかし、イスラエルは、義の律法を追い求めていたのに、その律法に到達しませんでした。'),
('JPN', '罗马书', 45, 9, 32, 'なぜでしょうか。信仰によってではなく、行いによるかのように追い求めたからです。彼らは、つまずきの石につまずいたのです。'),
('JPN', '罗马书', 45, 9, 33, '「見よ、わたしはシオンに、つまずきの石、妨げの岩を置く。この方に信頼する者は失望させられることがない」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 10, 1, '兄弟たちよ。私の心の願い、彼らのために神にささげる祈りは、彼らの救いです。'),
('JPN', '罗马书', 45, 10, 2, '私は、彼らが神に対して熱心であることを証ししますが、その熱心は知識に基づくものではありません。'),
('JPN', '罗马书', 45, 10, 3, '彼らは神の義を知らずに、自らの義を立てようとして、神の義に従わなかったのです。'),
('JPN', '罗马书', 45, 10, 4, '律法が目指すものはキリストです。それで、義は信じる者すべてに与えられるのです。'),
('JPN', '罗马书', 45, 10, 5, 'モーセは、律法による義について、「律法の掟を行う人は、その掟によって生きる」と書いています。'),
('JPN', '罗马书', 45, 10, 6, 'しかし、信仰による義はこう言います。「あなたは心の中で、『だれが天に上るのか』と言ってはならない。」それはキリストを引き降ろすことです。'),
('JPN', '罗马书', 45, 10, 7, 'また、「『だれが深みに下るのか』と言ってはならない。」それはキリストを死者の中から引き上げることです。'),
('JPN', '罗马书', 45, 10, 8, 'では、何と言っていますか。「みことばは、あなたの近くにあり、あなたの口にあり、あなたの心にある。」これは、私たちが宣べ伝えている信仰のことばのことです。'),
('JPN', '罗马书', 45, 10, 9, 'なぜなら、もしあなたの口でイエスを主と告白し、あなたの心で神はイエスを死者の中からよみがえらせたと信じるなら、あなたは救われるからです。'),
('JPN', '罗马书', 45, 10, 10, '人は心に信じて義と認められ、口で告白して救われるのです。'),
('JPN', '罗马书', 45, 10, 11, '聖書はこう言っています。「この方に信頼する者は、だれも失望させられることがない。」'),
('JPN', '罗马书', 45, 10, 12, 'ユダヤ人とギリシア人の区別はありません。同じ主がすべての人の主であり、ご自分を呼び求めるすべての人に豊かに恵みをお与えになるからです。'),
('JPN', '罗马书', 45, 10, 13, '「主の御名を呼び求める者はみな救われる」のです。'),
('JPN', '罗马书', 45, 10, 14, 'しかし、信じたことのない方を、どのようにして呼び求めるのでしょうか。聞いたことのない方を、どのようにして信じるのでしょうか。宣べ伝える人がいなければ、どのようにして聞くのでしょうか。'),
('JPN', '罗马书', 45, 10, 15, '遣わされることがなければ、どのようにして宣べ伝えるのでしょうか。「なんと美しいことか、良い知らせを伝える人たちの足は」と書いてあるようにです。'),
('JPN', '罗马书', 45, 10, 16, 'しかし、すべての人が福音に従ったのではありません。「主よ。私たちが聞いたことを、だれが信じたか」とイザヤは言っています。'),
('JPN', '罗马书', 45, 10, 17, 'ですから、信仰は聞くことから始まります。聞くことは、キリストについてのことばを通して実現するのです。'),
('JPN', '罗马书', 45, 10, 18, 'では、私は尋ねます。彼らは聞かなかったのでしょうか。いいえ、むしろ、「その響きは全地に、そのことばは、世界の果てまで届いた」のです。'),
('JPN', '罗马书', 45, 10, 19, 'では、私は尋ねます。イスラエルは知らなかったのでしょうか。まず、モーセがこう言っています。「わたしは、民でない者たちであなたがたのねたみを引き起こし、愚かな国民であなたがたの怒りを燃えさせる。」'),
('JPN', '罗马书', 45, 10, 20, 'また、イザヤは大胆にもこう言っています。「わたしを探さなかった者たちにわたしは見出され、わたしを尋ねなかった者たちに自分を現した。」'),
('JPN', '罗马书', 45, 10, 21, 'そして、イスラエルのことをこう言っています。「わたしは終日、手を差し伸べた。不従順で反抗する民に対して。」'),
('JPN', '罗马书', 45, 11, 1, 'それでは尋ねますが、神はご自分の民を退けられたのでしょうか。決してそんなことはありません。この私もイスラエル人で、アブラハムの子孫、ベニヤミン族の出身です。'),
('JPN', '罗马书', 45, 11, 2, '神は、前から知っていたご自分の民を退けられたのではありません。それとも、聖書がエリヤの箇所で言っていることを、あなたがたは知らないのですか。エリヤはイスラエルを神に訴えています。'),
('JPN', '罗马书', 45, 11, 3, '「主よ。彼らはあなたの預言者たちを殺し、あなたの祭壇を壊しました。ただ私だけが残りましたが、彼らは私のいのちを狙っています。」'),
('JPN', '罗马书', 45, 11, 4, 'しかし、神が彼に告げられたことは何だったでしょうか。「わたしは、わたし自身のために、男子七千人を残している。これらの者は、バアルに膝をかがめなかった者たちである。」'),
('JPN', '罗马书', 45, 11, 5, 'ですから、同じように今この時にも、恵みの選びによって残された者たちがいます。'),
('JPN', '罗马书', 45, 11, 6, '恵みによるのであれば、もはや行いによるのではありません。そうでなければ、恵みが恵みでなくなります。'),
('JPN', '罗马书', 45, 11, 7, 'では、どうなのでしょうか。イスラエルは追い求めていたものを手に入れず、選ばれた者たちが手に入れました。ほかの者たちは頑なにされたのです。'),
('JPN', '罗马书', 45, 11, 8, '「神は今日に至るまで、彼らに鈍い心と見ない目と聞かない耳を与えられた」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 11, 9, 'ダビデもこう言っています。「彼らの食卓が、彼らにとって罠となり、落とし穴となり、つまずきとなり、報いとなりますように。'),
('JPN', '罗马书', 45, 11, 10, '彼らの目が暗くなり、見えなくなりますように。その腰をいつも曲げておいてください。」'),
('JPN', '罗马书', 45, 11, 11, 'それでは尋ねますが、彼らがつまずいたのは倒れるためでしょうか。決してそんなことはありません。かえって、彼らの背きによって、救いが異邦人に及び、イスラエルにねたみを起こさせました。'),
('JPN', '罗马书', 45, 11, 12, '彼らの背きが世界の富となり、彼らの失敗が異邦人の富となるのなら、彼らがみな救われることは、どんなにすばらしいものをもたらすことでしょう。'),
('JPN', '罗马书', 45, 11, 13, 'そこで、異邦人であるあなたがたに言いますが、私は異邦人への使徒ですから、自分の務めを重く受けとめています。'),
('JPN', '罗马书', 45, 11, 14, '私は何とかして自分の同胞にねたみを起こさせて、彼らのうち何人かでも救いたいのです。'),
('JPN', '罗马书', 45, 11, 15, 'もし彼らの捨てられることが世界の和解となるなら、彼らが受け入れられることは、死者の中からのいのちでなくて何でしょうか。'),
('JPN', '罗马书', 45, 11, 16, '麦の初穂が聖なるものであれば、こねた粉もそうなのです。根が聖なるものであれば、枝もそうなのです。'),
('JPN', '罗马书', 45, 11, 17, '枝の中のいくつかが折られ、野生のオリーブであるあなたがその枝の間に接ぎ木され、そのオリーブの根から豊かな養分をともに受けているのなら、'),
('JPN', '罗马书', 45, 11, 18, 'あなたはその枝に対して誇ってはいけません。たとえ誇るとしても、あなたが根を支えているのではなく、根があなたを支えているのです。'),
('JPN', '罗马书', 45, 11, 19, 'すると、あなたは「枝が折られたのは、私が接ぎ木されるためだった」と言うでしょう。'),
('JPN', '罗马书', 45, 11, 20, 'そのとおりです。彼らは不信仰によって折られましたが、あなたは信仰によって立っています。思い上がることなく、むしろ恐れなさい。'),
('JPN', '罗马书', 45, 11, 21, 'もし神が本来の枝を惜しまなかったとすれば、あなたをも惜しまれないでしょう。'),
('JPN', '罗马书', 45, 11, 22, 'ですから見なさい、神のいつくしみと厳しさを。倒れた者の上にあるのは厳しさですが、あなたの上にあるのは神のいつくしみです。ただし、あなたがそのいつくしみの中にとどまっていればであって、そうでなければ、あなたも切り取られます。'),
('JPN', '罗马书', 45, 11, 23, 'あの人たちも、もし不信仰の中に居続けないなら、接ぎ木されます。神は、彼らを再び接ぎ木することがおできになるのです。'),
('JPN', '罗马书', 45, 11, 24, 'あなたが、本来野生であるオリーブから切り取られ、元の性質に反して、栽培されたオリーブに接ぎ木されたのであれば、本来栽培された枝であった彼らは、もっとたやすく自分の元のオリーブに接ぎ木されるはずです。'),
('JPN', '罗马书', 45, 11, 25, '兄弟たち。あなたがたが自分を知恵のある者と考えないようにするために、この奥義を知らずにいてほしくはありません。イスラエル人の一部が頑なになったのは異邦人の満ちる時が来るまでであり、'),
('JPN', '罗马书', 45, 11, 26, 'こうして、イスラエルはみな救われるのです。「救い出す者がシオンから現れ、ヤコブから不敬虔を除き去る。'),
('JPN', '罗马书', 45, 11, 27, 'これこそ、彼らと結ぶわたしの契約、すなわち、わたしが彼らの罪を取り除く時である」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 11, 28, '彼らは、福音に関して言えば、あなたがたのゆえに、神に敵対している者ですが、選びに関して言えば、父祖たちのゆえに、神に愛されている者です。'),
('JPN', '罗马书', 45, 11, 29, '神の賜物と召命は、取り消されることがないからです。'),
('JPN', '罗马书', 45, 11, 30, 'あなたがたは、かつては神に不従順でしたが、今は彼らの不従順のゆえに、あわれみを受けています。'),
('JPN', '罗马书', 45, 11, 31, 'それと同じように、彼らも今は、あなたがたの受けたあわれみのゆえに不従順になっていますが、それは、彼ら自身も今あわれみを受けるためです。'),
('JPN', '罗马书', 45, 11, 32, '神は、すべての人を不従順のうちに閉じ込めましたが、それはすべての人をあわれむためだったのです。'),
('JPN', '罗马书', 45, 11, 33, 'ああ、神の知恵と知識の富は、なんと深いことでしょう。神のさばきはなんと知り尽くしがたく、神の道はなんと極めがたいことでしょう。'),
('JPN', '罗马书', 45, 11, 34, '「だれが主の心を知っているのですか。だれが主の助言者になったのですか。'),
('JPN', '罗马书', 45, 11, 35, 'だれがまず主に与え、主から報いを受けるのですか。」'),
('JPN', '罗马书', 45, 11, 36, 'すべてのものが神から発し、神によって成り、神に至るのです。この神に、栄光がとこしえにありますように。アーメン。'),
('JPN', '罗马书', 45, 12, 1, 'ですから、兄弟たち、私は神のあわれみによって、あなたがたに勧めます。あなたがたのからだを、神に喜ばれる、聖なる生きたささげ物として献げなさい。それこそ、あなたがたにふさわしい礼拝です。'),
('JPN', '罗马书', 45, 12, 2, 'この世と調子を合わせてはいけません。むしろ、心を新たにすることで、自分を変えていただきなさい。そうすれば、神のみこころは何か、すなわち、何が良いことで、神に喜ばれ、完全であるのかを見分けるようになります。'),
('JPN', '罗马书', 45, 12, 3, '私は、自分に与えられた恵みによって、あなたがた一人ひとりに言います。思うべき限度を超えて思い上がってはいけません。むしろ、神が各自に分け与えてくださった信仰の量りに応じて、慎み深く考えなさい。'),
('JPN', '罗马书', 45, 12, 4, '一つのからだには多くの器官があり、しかも、すべての器官が同じ働きをしてはいないように、'),
('JPN', '罗马书', 45, 12, 5, '大勢いる私たちも、キリストにあって一つのからだであり、一人ひとりは互いに器官なのです。'),
('JPN', '罗马书', 45, 12, 6, '私たちは、与えられた恵みにしたがって、異なる賜物を持っているので、それが預言であれば、その信仰に応じて預言し、'),
('JPN', '罗马书', 45, 12, 7, '奉仕であれば奉仕し、教える人であれば教え、'),
('JPN', '罗马书', 45, 12, 8, '勧めをする人であれば勧め、分け与える人は惜しまずに分け与え、指導する人は熱心に指導し、慈善を行う人は喜んでそれを行いなさい。'),
('JPN', '罗马书', 45, 12, 9, '愛には偽りがあってはなりません。悪を憎み、善から離れないようにしなさい。'),
('JPN', '罗马书', 45, 12, 10, '兄弟愛をもって互いに愛し合い、互いに相手をすぐれた者として尊敬し合いなさい。'),
('JPN', '罗马书', 45, 12, 11, '勤勉で怠らず、霊に燃え、主に仕えなさい。'),
('JPN', '罗马书', 45, 12, 12, '望みを抱いて喜び、苦難に耐え、ひたすら祈りなさい。'),
('JPN', '罗马书', 45, 12, 13, '聖徒たちの必要をともに満たし、努めて人をもてなしなさい。'),
('JPN', '罗马书', 45, 12, 14, 'あなたがたを迫害する者たちを祝福しなさい。祝福すべきであって、呪ってはいけません。'),
('JPN', '罗马书', 45, 12, 15, '喜んでいる者たちとともに喜び、泣いている者たちとともに泣きなさい。'),
('JPN', '罗马书', 45, 12, 16, '互いに一つ心になり、思い上がることなく、むしろ身分の低い人たちと交わりなさい。自分を知恵のある者と考えてはいけません。'),
('JPN', '罗马书', 45, 12, 17, 'だれに対しても悪に悪を返さず、すべての人が良いと思うことを行うように心がけなさい。'),
('JPN', '罗马书', 45, 12, 18, '自分に関することについては、できる限り、すべての人と平和を保ちなさい。'),
('JPN', '罗马书', 45, 12, 19, '愛する者たち、自分で復讐してはいけません。神の怒りにゆだねなさい。こう書かれているからです。「復讐はわたしのもの。わたしが報復する。」主はそう言われます。'),
('JPN', '罗马书', 45, 12, 20, '次のようにも書かれています。「もしあなたの敵が飢えているなら食べさせ、渇いているなら飲ませよ。なぜなら、こうしてあなたは彼の頭上に燃える炭火を積むことになるからだ。」'),
('JPN', '罗马书', 45, 12, 21, '悪に負けてはいけません。むしろ、善をもって悪に打ち勝ちなさい。'),
('JPN', '罗马书', 45, 13, 1, '人はみな、上に立つ権威に従うべきです。神によらない権威はなく、存在している権威はすべて、神によって立てられているからです。'),
('JPN', '罗马书', 45, 13, 2, 'したがって、権威に反抗する者は、神の定めに逆らうのです。逆らう者は自分の身にさばきを招きます。'),
('JPN', '罗马书', 45, 13, 3, '支配者を恐ろしいと思うのは、良い行いをするときではなく、悪を行うときです。権威を恐ろしいと思いたくなければ、善を行いなさい。そうすれば、権威から称賛されます。'),
('JPN', '罗马书', 45, 13, 4, '彼はあなたに益を与えるための、神のしもべなのです。しかし、もしあなたが悪を行うなら、恐れなければなりません。彼は無意味に剣を帯びてはいないからです。彼は神のしもべであって、悪を行う人には怒りをもって報います。'),
('JPN', '罗马书', 45, 13, 5, 'ですから、怒りが恐ろしいからだけでなく、良心のためにも従うべきです。'),
('JPN', '罗马书', 45, 13, 6, '同じ理由で、あなたがたは税金も納めるのです。彼らは神の公僕であり、その務めに専念しているのです。'),
('JPN', '罗马书', 45, 13, 7, 'すべての人に対して義務を果たしなさい。税金を納めるべき人には税金を納め、関税を納めるべき人には関税を納め、恐れるべき人を恐れ、敬うべき人を敬いなさい。'),
('JPN', '罗马书', 45, 13, 8, 'だれに対しても、何の借りもあってはいけません。ただし、互いに愛し合うことは別です。他の人を愛する者は、律法の要求を満たしているのです。'),
('JPN', '罗马书', 45, 13, 9, '「姦淫してはならない。殺してはならない。盗んではならない。隣人のものを欲してはならない」という戒め、またほかのどんな戒めであっても、それらは、「あなたの隣人を自分自身のように愛しなさい」ということばに要約されるからです。'),
('JPN', '罗马书', 45, 13, 10, '愛は隣人に対して悪を行いません。それゆえ、愛は律法の要求を満たすものです。'),
('JPN', '罗马书', 45, 13, 11, 'さらにあなたがたは、今がどのような時であるか知っています。あなたがたが眠りからさめるべき時刻が、もう来ているのです。私たちが信じたときよりも、今は救いがもっと私たちに近づいているのですから。'),
('JPN', '罗马书', 45, 13, 12, '夜は深まり、昼は近づいて来ました。ですから私たちは、闇のわざを脱ぎ捨て、光の武具を身に着けようではありませんか。'),
('JPN', '罗马书', 45, 13, 13, '遊興や泥酔、淫乱や好色、争いやねたみの生活ではなく、昼らしい、品位のある生き方をしようではありませんか。'),
('JPN', '罗马书', 45, 13, 14, '主イエス・キリストを着なさい。欲望を満たそうと、肉に心を用いてはいけません。'),
('JPN', '罗马书', 45, 14, 1, '信仰の弱い人を受け入れなさい。その意見をさばいてはいけません。'),
('JPN', '罗马书', 45, 14, 2, 'ある人は何を食べてもよいと信じていますが、弱い人は野菜しか食べません。'),
('JPN', '罗马书', 45, 14, 3, '食べる人は食べない人を見下してはいけないし、食べない人も食べる人をさばいてはいけません。神がその人を受け入れてくださったのです。'),
('JPN', '罗马书', 45, 14, 4, '他人のしもべをさばくあなたは何者ですか。しもべが立つか倒れるか、それは主人次第です。しかし、しもべは立ちます。主は、彼を立たせることがおできになるからです。'),
('JPN', '罗马书', 45, 14, 5, 'ある日を別の日よりも大事だと考える人もいれば、どの日も大事だと考える人もいます。それぞれ自分の心の中で確信を持ちなさい。'),
('JPN', '罗马书', 45, 14, 6, '特定の日を尊ぶ人は、主のために尊んでいます。食べる人は、主のために食べています。神に感謝しているからです。食べない人も主のために食べないのであって、神に感謝しているのです。'),
('JPN', '罗马书', 45, 14, 7, '私たちの中でだれ一人、自分のために生きている人はなく、自分のために死ぬ人もいないからです。'),
('JPN', '罗马书', 45, 14, 8, '私たちは、生きるとすれば主のために生き、死ぬとすれば主のために死にます。ですから、生きるにしても、死ぬにしても、私たちは主のものです。'),
('JPN', '罗马书', 45, 14, 9, 'キリストが死んでよみがえられたのは、死んだ人にも生きている人にも、主となるためです。'),
('JPN', '罗马书', 45, 14, 10, 'それなのに、あなたはどうして、自分の兄弟をさばくのですか。どうして、自分の兄弟を見下すのですか。私たちはみな、神のさばきの座に立つことになるのです。'),
('JPN', '罗马书', 45, 14, 11, '次のように書かれています。「わたしは生きている──主のことば──。すべての膝は、わたしに向かってかがめられ、すべての舌は、神に告白する。」'),
('JPN', '罗马书', 45, 14, 12, 'ですから、私たちはそれぞれ自分について、神に申し開きをすることになります。'),
('JPN', '罗马书', 45, 14, 13, 'こういうわけで、私たちはもう互いにさばき合わないようにしましょう。いや、むしろ、兄弟に対して妨げになるもの、つまずきになるものを置くことはしないと決心しなさい。'),
('JPN', '罗马书', 45, 14, 14, '私は主イエスにあって知り、また確信しています。それ自体で汚れているものは何一つありません。ただ、何かが汚れていると考える人には、それは汚れたものなのです。'),
('JPN', '罗马书', 45, 14, 15, 'もし、食べ物のことで、あなたの兄弟が心を痛めているなら、あなたはもはや愛によって歩んではいません。キリストが代わりに死んでくださった、そのような人を、あなたの食べ物のことで滅ぼさないでください。'),
('JPN', '罗马书', 45, 14, 16, 'ですから、あなたがたが良いとしていることで、悪く言われないようにしなさい。'),
('JPN', '罗马书', 45, 14, 17, 'なぜなら、神の国は食べたり飲んだりすることではなく、聖霊による義と平和と喜びだからです。'),
('JPN', '罗马书', 45, 14, 18, 'このようにキリストに仕える人は、神に喜ばれ、人々にも認められるのです。'),
('JPN', '罗马书', 45, 14, 19, 'ですから、私たちは、平和に役立つことと、お互いの霊的成長に役立つことを追い求めましょう。'),
('JPN', '罗马书', 45, 14, 20, '食べ物のために神のみわざを台無しにしてはいけません。すべての食べ物はきよいのです。しかし、それを食べて人につまずきを与えるような者にとっては、悪いものなのです。'),
('JPN', '罗马书', 45, 14, 21, '肉を食べず、ぶどう酒を飲まず、あなたの兄弟がつまずくようなことをしないのは良いことです。'),
('JPN', '罗马书', 45, 14, 22, 'あなたが持っている信仰は、神の御前で自分の信仰として持っていなさい。自分が良いと認めていることで自分自身をさばかない人は幸いです。'),
('JPN', '罗马书', 45, 14, 23, 'しかし、疑いを抱く人が食べるなら、罪ありとされます。なぜなら、それは信仰から出ていないからです。信仰から出ていないことは、みな罪です。'),
('JPN', '罗马书', 45, 15, 1, '私たち力のある者たちは、力のない人たちの弱さを担うべきであり、自分を喜ばせるべきではありません。'),
('JPN', '罗马书', 45, 15, 2, '私たちは一人ひとり、霊的な成長のため、益となることを図って隣人を喜ばせるべきです。'),
('JPN', '罗马书', 45, 15, 3, 'キリストもご自分を喜ばせることはなさいませんでした。むしろ、「あなたを嘲る者たちの嘲りが、わたしに降りかかった」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 15, 4, 'かつて書かれたものはすべて、私たちを教えるために書かれました。それは、聖書が与える忍耐と励ましによって、私たちが希望を持ち続けるためです。'),
('JPN', '罗马书', 45, 15, 5, 'どうか、忍耐と励ましの神があなたがたに、キリスト・イエスにふさわしく、互いに同じ思いを抱かせてくださいますように。'),
('JPN', '罗马书', 45, 15, 6, 'そうして、あなたがたが心を一つにし、声を合わせて、私たちの主イエス・キリストの父である神をほめたたえますように。'),
('JPN', '罗马书', 45, 15, 7, 'ですから、神の栄光のために、キリストがあなたがたを受け入れてくださったように、あなたがたも互いに受け入れ合いなさい。'),
('JPN', '罗马书', 45, 15, 8, '私は言います。キリストは、神の真理を現すために、割礼のある者たちのしもべとなられました。父祖たちに与えられた約束を確証するためであり、'),
('JPN', '罗马书', 45, 15, 9, 'また異邦人もあわれみのゆえに、神をあがめるようになるためです。「それゆえ、私は異邦人の間であなたをほめたたえます。あなたの御名をほめ歌います」と書いてあるとおりです。'),
('JPN', '罗马书', 45, 15, 10, 'また、こう言われています。「異邦人よ、主の民とともに喜べ。」'),
('JPN', '罗马书', 45, 15, 11, 'さらに、こうあります。「すべての異邦人よ、主をほめよ。すべての国民が、主をたたえるように。」'),
('JPN', '罗马书', 45, 15, 12, 'さらにまたイザヤは、「エッサイの根が起こる。異邦人を治めるために立ち上がる方が。異邦人はこの方に望みを置く」と言っています。'),
('JPN', '罗马书', 45, 15, 13, 'どうか、希望の神が、信仰によるすべての喜びと平安であなたがたを満たし、聖霊の力によって希望にあふれさせてくださいますように。'),
('JPN', '罗马书', 45, 15, 14, '私の兄弟たちよ。あなたがた自身、善意にあふれ、あらゆる知識に満たされ、互いに訓戒し合うことができると、この私も確信しています。'),
('JPN', '罗马书', 45, 15, 15, 'ただ、あなたがたにもう一度思い起こしてもらうために、私は所々かなり大胆に書きました。私は、神が与えてくださった恵みのゆえに、'),
('JPN', '罗马书', 45, 15, 16, '異邦人のためにキリスト・イエスに仕える者となったからです。私は神の福音をもって、祭司の務めを果たしています。それは異邦人が、聖霊によって聖なるものとされた、神に喜ばれるささげ物となるためです。'),
('JPN', '罗马书', 45, 15, 17, 'ですから、神への奉仕について、私はキリスト・イエスにあって誇りを持っています。'),
('JPN', '罗马书', 45, 15, 18, '私は、異邦人を従順にするため、キリストが私を用いて成し遂げてくださったこと以外に、何かをあえて話そうとは思いません。キリストは、ことばと行いにより、'),
('JPN', '罗马书', 45, 15, 19, 'また、しるしと不思議を行う力と、神の御霊の力によって、それらを成し遂げてくださいました。こうして、私はエルサレムから始めて、イルリコに至るまでを巡り、キリストの福音をくまなく伝えました。'),
('JPN', '罗马书', 45, 15, 20, 'このように、ほかの人が据えた土台の上に建てないように、キリストの名がまだ語られていない場所に福音を宣べ伝えることを、私は切に求めているのです。'),
('JPN', '罗马书', 45, 15, 21, 'こう書かれているとおりです。「彼のことを告げられていなかった人々が見るようになり、聞いたことのなかった人々が悟るようになる。」'),
('JPN', '罗马书', 45, 15, 22, 'そういうわけで、私は、あなたがたのところに行くのを何度も妨げられてきました。'),
('JPN', '罗马书', 45, 15, 23, 'しかし今は、もうこの地方に私が働くべき場所はありません。また、イスパニアに行く場合は、あなたがたのところに立ち寄ることを長年切望してきたので、'),
('JPN', '罗马书', 45, 15, 24, '旅の途中であなたがたを訪問し、しばらくの間あなたがたとともにいて、まず心を満たされてから、あなたがたに送られてイスパニアに行きたいと願っています。'),
('JPN', '罗马书', 45, 15, 25, 'しかし今は、聖徒たちに奉仕するために、私はエルサレムに行きます。'),
('JPN', '罗马书', 45, 15, 26, 'それは、マケドニアとアカイアの人々が、エルサレムの聖徒たちの中の貧しい人たちのために、喜んで援助をすることにしたからです。'),
('JPN', '罗马书', 45, 15, 27, '彼らは喜んでそうすることにしたのですが、聖徒たちに対してそうする義務もあります。異邦人は彼らの霊的なものにあずかったのですから、物質的なもので彼らに奉仕すべきです。'),
('JPN', '罗马书', 45, 15, 28, 'それで私はこのことを済ませ、彼らにこの実を確かに渡してから、あなたがたのところを通ってイスパニアに行くことにします。'),
('JPN', '罗马书', 45, 15, 29, 'あなたがたのところに行くときは、キリストの祝福に満ちあふれて行くことになると分かっています。'),
('JPN', '罗马书', 45, 15, 30, '兄弟たち。私たちの主イエス・キリストによって、また、御霊の愛によってお願いします。私のために、私とともに力を尽くして、神に祈ってください。'),
('JPN', '罗马书', 45, 15, 31, '私がユダヤにいる不信仰な人々から救い出され、エルサレムに対する私の奉仕が聖徒たちに受け入れられるように、'),
('JPN', '罗马书', 45, 15, 32, 'また、神のみこころにより、喜びをもってあなたがたのところに行き、あなたがたとともに、憩いを得ることができるように、祈ってください。'),
('JPN', '罗马书', 45, 15, 33, 'どうか、平和の神が、あなたがたすべてとともにいてくださいますように。アーメン。'),
('JPN', '罗马书', 45, 16, 1, '私たちの姉妹で、ケンクレアにある教会の奉仕者であるフィベを、あなたがたに推薦します。'),
('JPN', '罗马书', 45, 16, 2, 'どうか、聖徒にふさわしく、主にあって彼女を歓迎し、あなたがたの助けが必要であれば、どんなことでも助けてあげてください。彼女は、多くの人々の支援者で、私自身の支援者でもあるのです。'),
('JPN', '罗马书', 45, 16, 3, 'キリスト・イエスにある私の同労者、プリスカとアキラによろしく伝えてください。'),
('JPN', '罗马书', 45, 16, 4, '二人は、私のいのちを救うために自分のいのちを危険にさらしてくれました。彼らには、私だけでなく、異邦人のすべての教会も感謝しています。'),
('JPN', '罗马书', 45, 16, 5, 'また彼らの家の教会によろしく伝えてください。キリストに献げられたアジアの初穂である、私の愛するエパイネトによろしく。'),
('JPN', '罗马书', 45, 16, 6, 'あなたがたのために非常に労苦したマリアによろしく。'),
('JPN', '罗马书', 45, 16, 7, '私の同胞で私とともに投獄されたアンドロニコとユニアによろしく。二人は使徒たちの間でよく知られており、また私より先にキリストにある者となりました。'),
('JPN', '罗马书', 45, 16, 8, '主にあって私の愛するアンプリアトによろしく。'),
('JPN', '罗马书', 45, 16, 9, 'キリストにある私たちの同労者ウルバノと、私の愛するスタキスによろしく。'),
('JPN', '罗马书', 45, 16, 10, 'キリストにあって認められているアペレによろしく。アリストブロの家の人々によろしく。'),
('JPN', '罗马书', 45, 16, 11, '私の同胞ヘロディオンによろしく。ナルキソの家の主にある人々によろしく。'),
('JPN', '罗马书', 45, 16, 12, '主にあって労苦している、トリファイナとトリフォサによろしく。主にあって非常に労苦した愛するペルシスによろしく。'),
('JPN', '罗马书', 45, 16, 13, '主にあって選ばれた人ルフォスによろしく。また彼と私の母によろしく。'),
('JPN', '罗马书', 45, 16, 14, 'アシンクリト、フレゴン、ヘルメス、パトロバ、ヘルマス、および彼らとともにいる兄弟たちによろしく。'),
('JPN', '罗马书', 45, 16, 15, 'フィロロゴとユリア、ネレウスとその姉妹、またオリンパ、および彼らとともにいるすべての聖徒たちによろしく。'),
('JPN', '罗马书', 45, 16, 16, 'あなたがたは聖なる口づけをもって互いにあいさつを交わしなさい。すべてのキリストの教会が、あなたがたによろしくと言っています。'),
('JPN', '罗马书', 45, 16, 17, '兄弟たち、私はあなたがたに勧めます。あなたがたの学んだ教えに背いて、分裂とつまずきをもたらす者たちを警戒しなさい。彼らから遠ざかりなさい。'),
('JPN', '罗马书', 45, 16, 18, 'そのような者たちは、私たちの主キリストにではなく、自分の欲望に仕えているのです。彼らは、滑らかなことば、へつらいのことばをもって純朴な人たちの心をだましています。'),
('JPN', '罗马书', 45, 16, 19, 'あなたがたの従順は皆の耳に届いています。ですから、私はあなたがたのことを喜んでいますが、なお私が願うのは、あなたがたが善にはさとく、悪にはうとくあることです。'),
('JPN', '罗马书', 45, 16, 20, '平和の神は、速やかに、あなたがたの足の下でサタンを踏み砕いてくださいます。どうか、私たちの主イエスの恵みが、あなたがたとともにありますように。'),
('JPN', '罗马书', 45, 16, 21, '私の同労者テモテ、また私の同胞、ルキオとヤソンとソシパテロが、あなたがたによろしくと言っています。'),
('JPN', '罗马书', 45, 16, 22, 'この手紙を筆記した私テルティオも、主にあってあなたがたにごあいさつ申し上げます。'),
('JPN', '罗马书', 45, 16, 23, '私と教会全体の家主であるガイオも、あなたがたによろしくと言っています。市の会計係エラストと兄弟クアルトもよろしくと言っています。'),
('JPN', '罗马书', 45, 16, 25, '〔私の福音、すなわち、イエス・キリストを伝える宣教によって、また、世々にわたって隠されていた奥義の啓示によって──'),
('JPN', '罗马书', 45, 16, 26, '永遠の神の命令にしたがい、預言者たちの書を通して今や明らかにされ、すべての異邦人に信仰の従順をもたらすために知らされた奥義の啓示によって、あなたがたを強くすることができる方、'),
('JPN', '罗马书', 45, 16, 27, '知恵に富む唯一の神に、イエス・キリストによって、栄光がとこしえまでありますように。アーメン。〕'),
('JPN', '哥林多前书', 46, 1, 1, '神のみこころによりキリスト・イエスの使徒として召されたパウロと、兄弟ソステネから、'),
('JPN', '哥林多前书', 46, 1, 2, 'コリントにある神の教会へ。すなわち、いたるところで私たちの主イエス・キリストの名を呼び求めているすべての人とともに、キリスト・イエスにあって聖なる者とされ、聖徒として召された方々へ。主はそのすべての人の主であり、私たちの主です。'),
('JPN', '哥林多前书', 46, 1, 3, '私たちの父なる神と主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '哥林多前书', 46, 1, 4, '私は、キリスト・イエスにあってあなたがたに与えられた神の恵みのゆえに、あなたがたのことをいつも私の神に感謝しています。'),
('JPN', '哥林多前书', 46, 1, 5, 'あなたがたはすべての点で、あらゆることばとあらゆる知識において、キリストにあって豊かな者とされました。'),
('JPN', '哥林多前书', 46, 1, 6, 'キリストについての証しが、あなたがたの中で確かなものとなったからです。'),
('JPN', '哥林多前书', 46, 1, 7, 'その結果、あなたがたはどんな賜物にも欠けることがなく、熱心に私たちの主イエス・キリストの現れを待ち望むようになっています。'),
('JPN', '哥林多前书', 46, 1, 8, '主はあなたがたを最後まで堅く保って、私たちの主イエス・キリストの日に責められるところがない者としてくださいます。'),
('JPN', '哥林多前书', 46, 1, 9, '神は真実です。その神に召されて、あなたがたは神の御子、私たちの主イエス・キリストとの交わりに入れられたのです。'),
('JPN', '哥林多前书', 46, 1, 10, 'さて、兄弟たち、私たちの主イエス・キリストの名によって、あなたがたにお願いします。どうか皆が語ることを一つにして、仲間割れせず、同じ心、同じ考えで一致してください。'),
('JPN', '哥林多前书', 46, 1, 11, '私の兄弟たち。実は、あなたがたの間に争いがあると、クロエの家の者から知らされました。'),
('JPN', '哥林多前书', 46, 1, 12, 'あなたがたはそれぞれ、「私はパウロにつく」「私はアポロに」「私はケファに」「私はキリストに」と言っているとのことです。'),
('JPN', '哥林多前书', 46, 1, 13, 'キリストが分割されたのですか。パウロがあなたがたのために十字架につけられたのですか。あなたがたはパウロの名によってバプテスマを受けたのですか。'),
('JPN', '哥林多前书', 46, 1, 14, '私は神に感謝しています。私はクリスポとガイオのほか、あなたがたのだれにもバプテスマを授けませんでした。'),
('JPN', '哥林多前书', 46, 1, 15, 'ですから、あなたがたが私の名によってバプテスマを受けたとは、だれも言えないのです。'),
('JPN', '哥林多前书', 46, 1, 16, 'もっとも、ステファナの家の者たちにもバプテスマを授けましたが、そのほかにはだれにも授けた覚えはありません。'),
('JPN', '哥林多前书', 46, 1, 17, 'キリストが私を遣わされたのは、バプテスマを授けるためではなく、福音を、ことばの知恵によらずに宣べ伝えるためでした。これはキリストの十字架が空しくならないようにするためです。'),
('JPN', '哥林多前书', 46, 1, 18, '十字架のことばは、滅びる者たちには愚かであっても、救われる私たちには神の力です。'),
('JPN', '哥林多前书', 46, 1, 19, '「わたしは知恵ある者の知恵を滅ぼし、悟りある者の悟りを消し去る」と書いてあるからです。'),
('JPN', '哥林多前书', 46, 1, 20, '知恵ある者はどこにいるのですか。学者はどこにいるのですか。この世の論客はどこにいるのですか。神は、この世の知恵を愚かなものにされたではありませんか。'),
('JPN', '哥林多前书', 46, 1, 21, '神の知恵により、この世は自分の知恵によって神を知ることがありませんでした。それゆえ神は、宣教のことばの愚かさを通して、信じる者を救うことにされたのです。'),
('JPN', '哥林多前书', 46, 1, 22, 'ユダヤ人はしるしを要求し、ギリシア人は知恵を追求します。'),
('JPN', '哥林多前书', 46, 1, 23, 'しかし、私たちは十字架につけられたキリストを宣べ伝えます。ユダヤ人にとってはつまずき、異邦人にとっては愚かなことですが、'),
('JPN', '哥林多前书', 46, 1, 24, 'ユダヤ人であってもギリシア人であっても、召された者たちにとっては、神の力、神の知恵であるキリストです。'),
('JPN', '哥林多前书', 46, 1, 25, '神の愚かさは人よりも賢く、神の弱さは人よりも強いからです。'),
('JPN', '哥林多前书', 46, 1, 26, '兄弟たち、自分たちの召しのことを考えてみなさい。人間的に見れば知者は多くはなく、力ある者も多くはなく、身分の高い者も多くはありません。'),
('JPN', '哥林多前书', 46, 1, 27, 'しかし神は、知恵ある者を恥じ入らせるために、この世の愚かな者を選び、強い者を恥じ入らせるために、この世の弱い者を選ばれました。'),
('JPN', '哥林多前书', 46, 1, 28, '有るものを無いものとするために、この世の取るに足りない者や見下されている者、すなわち無に等しい者を神は選ばれたのです。'),
('JPN', '哥林多前书', 46, 1, 29, '肉なる者がだれも神の御前で誇ることがないようにするためです。'),
('JPN', '哥林多前书', 46, 1, 30, 'しかし、あなたがたは神によってキリスト・イエスのうちにあります。キリストは、私たちにとって神からの知恵、すなわち、義と聖と贖いになられました。'),
('JPN', '哥林多前书', 46, 1, 31, '「誇る者は主を誇れ」と書いてあるとおりになるためです。'),
('JPN', '哥林多前书', 46, 2, 1, '兄弟たち。私があなたがたのところに行ったとき、私は、すぐれたことばや知恵を用いて神の奥義を宣べ伝えることはしませんでした。'),
('JPN', '哥林多前书', 46, 2, 2, 'なぜなら私は、あなたがたの間で、イエス・キリスト、しかも十字架につけられたキリストのほかには、何も知るまいと決心していたからです。'),
('JPN', '哥林多前书', 46, 2, 3, 'あなたがたのところに行ったときの私は、弱く、恐れおののいていました。'),
('JPN', '哥林多前书', 46, 2, 4, 'そして、私のことばと私の宣教は、説得力のある知恵のことばによるものではなく、御霊と御力の現れによるものでした。'),
('JPN', '哥林多前书', 46, 2, 5, 'それは、あなたがたの信仰が、人間の知恵によらず、神の力によるものとなるためだったのです。'),
('JPN', '哥林多前书', 46, 2, 6, 'しかし私たちは、成熟した人たちの間では知恵を語ります。この知恵は、この世の知恵でも、この世の過ぎ去って行く支配者たちの知恵でもありません。'),
('JPN', '哥林多前书', 46, 2, 7, '私たちは、奥義のうちにある、隠された神の知恵を語るのであって、その知恵は、神が私たちの栄光のために、世界の始まる前から定めておられたものです。'),
('JPN', '哥林多前书', 46, 2, 8, 'この知恵を、この世の支配者たちは、だれ一人知りませんでした。もし知っていたら、栄光の主を十字架につけはしなかったでしょう。'),
('JPN', '哥林多前书', 46, 2, 9, 'しかし、このことは、「目が見たことのないもの、耳が聞いたことのないもの、人の心に思い浮かんだことがないものを、神は、神を愛する者たちに備えてくださった」と書いてあるとおりでした。'),
('JPN', '哥林多前书', 46, 2, 10, 'それを、神は私たちに御霊によって啓示してくださいました。御霊はすべてのことを、神の深みさえも探られるからです。'),
('JPN', '哥林多前书', 46, 2, 11, '人間のことは、その人のうちにある人間の霊のほかに、いったいだれが知っているでしょう。同じように、神のことは、神の霊のほかにはだれも知りません。'),
('JPN', '哥林多前书', 46, 2, 12, 'しかし私たちは、この世の霊を受けたのではなく、神からの霊を受けました。それで私たちは、神が私たちに恵みとして与えてくださったものを知るのです。'),
('JPN', '哥林多前书', 46, 2, 13, 'それについて語るのに、私たちは人間の知恵によって教えられたことばではなく、御霊に教えられたことばを用います。その御霊のことばによって御霊のことを説明するのです。'),
('JPN', '哥林多前书', 46, 2, 14, '生まれながらの人間は、神の御霊に属することを受け入れません。それらはその人には愚かなことであり、理解することができないのです。御霊に属することは御霊によって判断するものだからです。'),
('JPN', '哥林多前书', 46, 2, 15, '御霊を受けている人はすべてのことを判断しますが、その人自身はだれによっても判断されません。'),
('JPN', '哥林多前书', 46, 2, 16, '「だれが主の心を知り、主に助言するというのですか。」しかし、私たちはキリストの心を持っています。'),
('JPN', '哥林多前书', 46, 3, 1, '兄弟たち。私はあなたがたに、御霊に属する人に対するようには語ることができずに、肉に属する人、キリストにある幼子に対するように語りました。'),
('JPN', '哥林多前书', 46, 3, 2, '私はあなたがたには乳を飲ませ、固い食物を与えませんでした。あなたがたには、まだ無理だったからです。実は、今でもまだ無理なのです。'),
('JPN', '哥林多前书', 46, 3, 3, 'あなたがたは、まだ肉の人だからです。あなたがたの間にはねたみや争いがあるのですから、あなたがたは肉の人であり、ただの人として歩んでいることにならないでしょうか。'),
('JPN', '哥林多前书', 46, 3, 4, 'ある人は「私はパウロにつく」と言い、別の人は「私はアポロに」と言っているのであれば、あなたがたは、ただの人ではありませんか。'),
('JPN', '哥林多前书', 46, 3, 5, 'アポロとは何なのでしょう。パウロとは何なのでしょう。あなたがたが信じるために用いられた奉仕者であって、主がそれぞれに与えられたとおりのことをしたのです。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '哥林多前书', 46, 3, 6, '私が植えて、アポロが水を注ぎました。しかし、成長させたのは神です。'),
('JPN', '哥林多前书', 46, 3, 7, 'ですから、大切なのは、植える者でも水を注ぐ者でもなく、成長させてくださる神です。'),
('JPN', '哥林多前书', 46, 3, 8, '植える者と水を注ぐ者は一つとなって働き、それぞれ自分の労苦に応じて自分の報酬を受けるのです。'),
('JPN', '哥林多前书', 46, 3, 9, '私たちは神のために働く同労者であり、あなたがたは神の畑、神の建物です。'),
('JPN', '哥林多前书', 46, 3, 10, '私は、自分に与えられた神の恵みによって、賢い建築家のように土台を据えました。ほかの人がその上に家を建てるのです。しかし、どのように建てるかは、それぞれが注意しなければなりません。'),
('JPN', '哥林多前书', 46, 3, 11, 'だれも、すでに据えられている土台以外の物を据えることはできないからです。その土台とはイエス・キリストです。'),
('JPN', '哥林多前书', 46, 3, 12, 'だれかがこの土台の上に、金、銀、宝石、木、草、藁で家を建てると、'),
('JPN', '哥林多前书', 46, 3, 13, 'それぞれの働きは明らかになります。「その日」がそれを明るみに出すのです。その日は火とともに現れ、この火が、それぞれの働きがどのようなものかを試すからです。'),
('JPN', '哥林多前书', 46, 3, 14, 'だれかの建てた建物が残れば、その人は報いを受けます。'),
('JPN', '哥林多前书', 46, 3, 15, 'だれかの建てた建物が焼ければ、その人は損害を受けますが、その人自身は火の中をくぐるようにして助かります。'),
('JPN', '哥林多前书', 46, 3, 16, 'あなたがたは、自分が神の宮であり、神の御霊が自分のうちに住んでおられることを知らないのですか。'),
('JPN', '哥林多前书', 46, 3, 17, 'もし、だれかが神の宮を壊すなら、神がその人を滅ぼされます。神の宮は聖なるものだからです。あなたがたは、その宮です。'),
('JPN', '哥林多前书', 46, 3, 18, 'だれも自分を欺いてはいけません。あなたがたの中に、自分はこの世で知恵のある者だと思う者がいたら、知恵のある者となるために愚かになりなさい。'),
('JPN', '哥林多前书', 46, 3, 19, 'なぜなら、この世の知恵は神の御前では愚かだからです。「神は知恵のある者を、彼ら自身の悪巧みによって捕らえる」と書かれており、'),
('JPN', '哥林多前书', 46, 3, 20, 'また、「主は、知恵のある者の思い計ることがいかに空しいかを、知っておられる」とも書かれています。'),
('JPN', '哥林多前书', 46, 3, 21, 'ですから、だれも人間を誇ってはいけません。すべては、あなたがたのものです。'),
('JPN', '哥林多前书', 46, 3, 22, 'パウロであれ、アポロであれ、ケファであれ、また世界であれ、いのちであれ、死であれ、また現在のものであれ、未来のものであれ、すべてはあなたがたのもの、'),
('JPN', '哥林多前书', 46, 3, 23, 'あなたがたはキリストのもの、キリストは神のものです。'),
('JPN', '哥林多前书', 46, 4, 1, '人は私たちをキリストのしもべ、神の奥義の管理者と考えるべきです。'),
('JPN', '哥林多前书', 46, 4, 2, 'その場合、管理者に要求されることは、忠実だと認められることです。'),
('JPN', '哥林多前书', 46, 4, 3, 'しかし私にとって、あなたがたにさばかれたり、あるいは人間の法廷でさばかれたりすることは、非常に小さなことです。それどころか、私は自分で自分をさばくことさえしません。'),
('JPN', '哥林多前书', 46, 4, 4, '私には、やましいことは少しもありませんが、だからといって、それで義と認められているわけではありません。私をさばく方は主です。'),
('JPN', '哥林多前书', 46, 4, 5, 'ですから、主が来られるまでは、何についても先走ってさばいてはいけません。主は、闇に隠れたことも明るみに出し、心の中のはかりごとも明らかにされます。そのときに、神からそれぞれの人に称賛が与えられるのです。'),
('JPN', '哥林多前书', 46, 4, 6, '兄弟たち。私はあなたがたのために、私自身とアポロに当てはめて、以上のことを述べてきました。それは、私たちの例から、「書かれていることを越えない」ことをあなたがたが学ぶため、そして、一方にくみし、他方に反対して思い上がることのないようにするためです。'),
('JPN', '哥林多前书', 46, 4, 7, 'いったいだれが、あなたをほかの人よりもすぐれていると認めるのですか。あなたには、何か、もらわなかったものがあるのですか。もしもらったのなら、なぜ、もらっていないかのように誇るのですか。'),
('JPN', '哥林多前书', 46, 4, 8, 'あなたがたは、もう満ち足りています。すでに豊かになっています。私たち抜きで王様になっています。いっそのこと、本当に王様になっていたらよかったのです。そうすれば、私たちもあなたがたとともに、王様になれたでしょうに。'),
('JPN', '哥林多前书', 46, 4, 9, '私はこう思います。神は私たち使徒を、死罪に決まった者のように、最後の出場者として引き出されました。こうして私たちは、世界に対し、御使いたちにも人々にも見せ物になりました。'),
('JPN', '哥林多前书', 46, 4, 10, '私たちはキリストのために愚かな者ですが、あなたがたはキリストにあって賢い者です。私たちは弱いのですが、あなたがたは強いのです。あなたがたは尊ばれていますが、私たちは卑しめられています。'),
('JPN', '哥林多前书', 46, 4, 11, '今この時に至るまで、私たちは飢え、渇き、着る物もなく、ひどい扱いを受け、住む所もなく、'),
('JPN', '哥林多前书', 46, 4, 12, '労苦して自分の手で働いています。ののしられては祝福し、迫害されては耐え忍び、'),
('JPN', '哥林多前书', 46, 4, 13, '中傷されては、優しいことばをかけています。私たちはこの世の屑、あらゆるものの、かすになりました。今もそうです。'),
('JPN', '哥林多前书', 46, 4, 14, '私がこれらのことを書くのは、あなたがたに恥ずかしい思いをさせるためではなく、私の愛する子どもとして諭すためです。'),
('JPN', '哥林多前书', 46, 4, 15, 'たとえあなたがたにキリストにある養育係が一万人いても、父親が大勢いるわけではありません。この私が、福音により、キリスト・イエスにあって、あなたがたを生んだのです。'),
('JPN', '哥林多前书', 46, 4, 16, 'ですから、あなたがたに勧めます。私に倣う者となってください。'),
('JPN', '哥林多前书', 46, 4, 17, 'そのために、私はあなたがたのところにテモテを送りました。テモテは、私が愛する、主にあって忠実な子です。彼は、あらゆるところのあらゆる教会で私が教えているとおりに、キリスト・イエスにある私の生き方を、あなたがたに思い起こさせてくれるでしょう。'),
('JPN', '哥林多前书', 46, 4, 18, 'あなたがたのところに私が行くことはないだろうと考えて、思い上がっている人たちがいます。'),
('JPN', '哥林多前书', 46, 4, 19, 'しかし、主のみこころであれば、すぐにでもあなたがたのところに行きます。そして、思い上がっている人たちの、ことばではなく力を見せてもらいましょう。'),
('JPN', '哥林多前书', 46, 4, 20, '神の国は、ことばではなく力にあるのです。'),
('JPN', '哥林多前书', 46, 4, 21, 'あなたがたはどちらを望みますか。私があなたがたのところに、むちを持って行くことですか。それとも、愛をもって柔和な心で行くことですか。'),
('JPN', '哥林多前书', 46, 5, 1, '現に聞くところによれば、あなたがたの間には淫らな行いがあり、しかもそれは、異邦人の間にもないほどの淫らな行いで、父の妻を妻にしている者がいるとのことです。'),
('JPN', '哥林多前书', 46, 5, 2, 'それなのに、あなたがたは思い上がっています。むしろ、悲しんで、そのような行いをしている者を、自分たちの中から取り除くべきではなかったのですか。'),
('JPN', '哥林多前书', 46, 5, 3, '私は、からだは離れていても霊においてはそこにいて、実際にそこにいる者のように、そのような行いをした者をすでにさばきました。'),
('JPN', '哥林多前书', 46, 5, 4, 'すなわち、あなたがたと、私の霊が、私たちの主イエスの名によって、しかも私たちの主イエスの御力とともに集まり、'),
('JPN', '哥林多前书', 46, 5, 5, 'そのような者を、その肉が滅ぼされるようにサタンに引き渡したのです。それによって彼の霊が主の日に救われるためです。'),
('JPN', '哥林多前书', 46, 5, 6, 'あなたがたが誇っているのは、良くないことです。わずかなパン種が、こねた粉全体をふくらませることを、あなたがたは知らないのですか。'),
('JPN', '哥林多前书', 46, 5, 7, '新しいこねた粉のままでいられるように、古いパン種をすっかり取り除きなさい。あなたがたは種なしパンなのですから。私たちの過越の子羊キリストは、すでに屠られたのです。'),
('JPN', '哥林多前书', 46, 5, 8, 'ですから、古いパン種を用いたり、悪意と邪悪のパン種を用いたりしないで、誠実と真実の種なしパンで祭りをしようではありませんか。'),
('JPN', '哥林多前书', 46, 5, 9, '私は前の手紙で、淫らな行いをする者たちと付き合わないようにと書きました。'),
('JPN', '哥林多前书', 46, 5, 10, 'それは、この世の淫らな者、貪欲な者、奪い取る者、偶像を拝む者と、いっさい付き合わないようにという意味ではありません。そうだとしたら、この世から出て行かなければならないでしょう。'),
('JPN', '哥林多前书', 46, 5, 11, '私が今書いたのは、兄弟と呼ばれる者で、淫らな者、貪欲な者、偶像を拝む者、人をそしる者、酒におぼれる者、奪い取る者がいたなら、そのような者とは付き合ってはいけない、一緒に食事をしてもいけない、ということです。'),
('JPN', '哥林多前书', 46, 5, 12, '外部の人たちをさばくことは、私がすべきことでしょうか。あなたがたがさばくべき者は、内部の人たちではありませんか。'),
('JPN', '哥林多前书', 46, 5, 13, '外部の人たちは神がおさばきになります。「あなたがたの中からその悪い者を除き去りなさい。」'),
('JPN', '哥林多前书', 46, 6, 1, 'あなたがたのうちには、仲間と争いを起こしたら、それを聖徒たちに訴えずに、あえて、正しくない人たちに訴える人がいるのですか。'),
('JPN', '哥林多前书', 46, 6, 2, '聖徒たちが世界をさばくようになることを、あなたがたは知らないのですか。世界があなたがたによってさばかれるのに、あなたがたには、ごく小さな事件さえもさばく力がないのですか。'),
('JPN', '哥林多前书', 46, 6, 3, 'あなたがたは知らないのですか。私たちは御使いたちをさばくようになります。それなら、日常の事柄は言うまでもないではありませんか。'),
('JPN', '哥林多前书', 46, 6, 4, 'それなのに、日常の事柄で争いが起こると、教会の中で軽んじられている人たちを裁判官に選ぶのですか。'),
('JPN', '哥林多前书', 46, 6, 5, '私は、あなたがたを恥じ入らせるために、こう言っているのです。あなたがたの中には、兄弟の間を仲裁することができる賢い人が、一人もいないのですか。'),
('JPN', '哥林多前书', 46, 6, 6, 'それで兄弟が兄弟を告訴し、しかも、それを信者でない人たちの前でするのですか。'),
('JPN', '哥林多前书', 46, 6, 7, 'そもそも、互いに訴え合うことが、すでにあなたがたの敗北です。どうして、むしろ不正な行いを甘んじて受けないのですか。どうして、むしろ、だまし取られるままでいないのですか。'),
('JPN', '哥林多前书', 46, 6, 8, 'それどころか、あなたがた自身が不正を行い、だまし取っています。しかも、そのようなことを兄弟たちに対してしています。'),
('JPN', '哥林多前书', 46, 6, 9, 'あなたがたは知らないのですか。正しくない者は神の国を相続できません。思い違いをしてはいけません。淫らな行いをする者、偶像を拝む者、姦淫をする者、男娼となる者、男色をする者、'),
('JPN', '哥林多前书', 46, 6, 10, '盗む者、貪欲な者、酒におぼれる者、そしる者、奪い取る者はみな、神の国を相続することができません。'),
('JPN', '哥林多前书', 46, 6, 11, 'あなたがたのうちのある人たちは、以前はそのような者でした。しかし、主イエス・キリストの御名と私たちの神の御霊によって、あなたがたは洗われ、聖なる者とされ、義と認められたのです。'),
('JPN', '哥林多前书', 46, 6, 12, '「すべてのことが私には許されている」と言いますが、すべてが益になるわけではありません。「すべてのことが私には許されている」と言いますが、私はどんなことにも支配されはしません。'),
('JPN', '哥林多前书', 46, 6, 13, '「食物は腹のためにあり、腹は食物のためにある」と言いますが、神は、そのどちらも滅ぼされます。からだは淫らな行いのためではなく、主のためにあり、主はからだのためにおられるのです。'),
('JPN', '哥林多前书', 46, 6, 14, '神は主をよみがえらせましたが、その御力によって私たちも、よみがえらせてくださいます。'),
('JPN', '哥林多前书', 46, 6, 15, 'あなたがたは知らないのですか。あなたがたのからだはキリストのからだの一部なのです。それなのに、キリストのからだの一部を取って、遊女のからだの一部とするのですか。そんなことがあってはなりません。'),
('JPN', '哥林多前书', 46, 6, 16, 'それとも、あなたがたは知らないのですか。遊女と交わる者は、彼女と一つのからだになります。「ふたりは一体となる」と言われているからです。'),
('JPN', '哥林多前书', 46, 6, 17, 'しかし、主と交わる者は、主と一つの霊になるのです。'),
('JPN', '哥林多前书', 46, 6, 18, '淫らな行いを避けなさい。人が犯す罪はすべて、からだの外のものです。しかし、淫らなことを行う者は、自分のからだに対して罪を犯すのです。'),
('JPN', '哥林多前书', 46, 6, 19, 'あなたがたは知らないのですか。あなたがたのからだは、あなたがたのうちにおられる、神から受けた聖霊の宮であり、あなたがたはもはや自分自身のものではありません。'),
('JPN', '哥林多前书', 46, 6, 20, 'あなたがたは、代価を払って買い取られたのです。ですから、自分のからだをもって神の栄光を現しなさい。'),
('JPN', '哥林多前书', 46, 7, 1, 'さて、「男が女に触れないのは良いことだ」と、あなたがたが書いてきたことについてですが、'),
('JPN', '哥林多前书', 46, 7, 2, '淫らな行いを避けるため、男はそれぞれ自分の妻を持ち、女もそれぞれ自分の夫を持ちなさい。'),
('JPN', '哥林多前书', 46, 7, 3, '夫は自分の妻に対して義務を果たし、同じように妻も自分の夫に対して義務を果たしなさい。'),
('JPN', '哥林多前书', 46, 7, 4, '妻は自分のからだについて権利を持ってはおらず、それは夫のものです。同じように、夫も自分のからだについて権利を持ってはおらず、それは妻のものです。'),
('JPN', '哥林多前书', 46, 7, 5, '互いに相手を拒んではいけません。ただし、祈りに専心するために合意の上でしばらく離れていて、再び一緒になるというのならかまいません。これは、あなたがたの自制力の無さに乗じて、サタンがあなたがたを誘惑しないようにするためです。'),
('JPN', '哥林多前书', 46, 7, 6, '以上は譲歩として言っているのであって、命令ではありません。'),
('JPN', '哥林多前书', 46, 7, 7, '私が願うのは、すべての人が私のように独身であることです。しかし、一人ひとり神から与えられた自分の賜物があるので、人それぞれの生き方があります。'),
('JPN', '哥林多前书', 46, 7, 8, '結婚していない人とやもめに言います。私のようにしていられるなら、それが良いのです。'),
('JPN', '哥林多前书', 46, 7, 9, 'しかし、自制することができないなら、結婚しなさい。欲情に燃えるより、結婚するほうがよいからです。'),
('JPN', '哥林多前书', 46, 7, 10, 'すでに結婚した人たちに命じます。命じるのは私ではなく主です。妻は夫と別れてはいけません。'),
('JPN', '哥林多前书', 46, 7, 11, 'もし別れたのなら、再婚せずにいるか、夫と和解するか、どちらかにしなさい。また、夫は妻と離婚してはいけません。'),
('JPN', '哥林多前书', 46, 7, 12, 'そのほかの人々に言います。これを言うのは主ではなく私です。信者である夫に信者でない妻がいて、その妻が一緒にいることを承知している場合は、離婚してはいけません。'),
('JPN', '哥林多前书', 46, 7, 13, 'また、女の人に信者でない夫がいて、その夫が一緒にいることを承知している場合は、離婚してはいけません。'),
('JPN', '哥林多前书', 46, 7, 14, 'なぜなら、信者でない夫は妻によって聖なるものとされており、また、信者でない妻も信者である夫によって聖なるものとされているからです。そうでなかったら、あなたがたの子どもは汚れていることになりますが、実際には聖なるものです。'),
('JPN', '哥林多前书', 46, 7, 15, 'しかし、信者でないほうの者が離れて行くなら、離れて行かせなさい。そのような場合には、信者である夫あるいは妻は、縛られることはありません。神は、平和を得させようとして、あなたがたを召されたのです。'),
('JPN', '哥林多前书', 46, 7, 16, '妻よ。あなたが夫を救えるかどうか、どうして分かりますか。また、夫よ。あなたが妻を救えるかどうか、どうして分かりますか。'),
('JPN', '哥林多前书', 46, 7, 17, 'ただ、それぞれ主からいただいた分に応じて、また、それぞれ神から召されたときのままの状態で歩むべきです。私はすべての教会に、そのように命じています。'),
('JPN', '哥林多前书', 46, 7, 18, '召されたとき割礼を受けていたのなら、その跡をなくそうとしてはいけません。また、召されたとき割礼を受けていなかったのなら、割礼を受けてはいけません。'),
('JPN', '哥林多前书', 46, 7, 19, '割礼は取るに足りないこと、無割礼も取るに足りないことです。重要なのは神の命令を守ることです。'),
('JPN', '哥林多前书', 46, 7, 20, 'それぞれ自分が召されたときの状態にとどまっていなさい。'),
('JPN', '哥林多前书', 46, 7, 21, 'あなたが奴隷の状態で召されたのなら、そのことを気にしてはいけません。しかし、もし自由の身になれるなら、その機会を用いたらよいでしょう。'),
('JPN', '哥林多前书', 46, 7, 22, '主にあって召された奴隷は、主に属する自由人であり、同じように自由人も、召された者はキリストに属する奴隷だからです。'),
('JPN', '哥林多前书', 46, 7, 23, 'あなたがたは、代価を払って買い取られたのです。人間の奴隷となってはいけません。'),
('JPN', '哥林多前书', 46, 7, 24, '兄弟たち、それぞれ召されたときのままの状態で、神の御前にいなさい。'),
('JPN', '哥林多前书', 46, 7, 25, '未婚の人たちについて、私は主の命令を受けてはいませんが、主のあわれみにより信頼を得ている者として、意見を述べます。'),
('JPN', '哥林多前书', 46, 7, 26, '差し迫っている危機のゆえに、男はそのままの状態にとどまるのがよい、と私は思います。'),
('JPN', '哥林多前书', 46, 7, 27, 'あなたが妻と結ばれているなら、解こうとしてはいけません。妻と結ばれていないなら、妻を得ようとしてはいけません。'),
('JPN', '哥林多前书', 46, 7, 28, 'しかし、たとえあなたが結婚しても、罪を犯すわけではありません。たとえ未婚の女が結婚しても、罪を犯すわけではありません。ただ、結婚する人たちは、身に苦難を招くでしょう。私はあなたがたを、そのような目にあわせたくないのです。'),
('JPN', '哥林多前书', 46, 7, 29, '兄弟たち、私は次のことを言いたいのです。時は短くなっています。今からは、妻のいる人は妻のいない人のようにしていなさい。'),
('JPN', '哥林多前书', 46, 7, 30, '泣いている人は泣いていないかのように、喜んでいる人は喜んでいないかのように、買う人は所有していないかのようにしていなさい。'),
('JPN', '哥林多前书', 46, 7, 31, '世と関わる人は関わりすぎないようにしなさい。この世の有様は過ぎ去るからです。'),
('JPN', '哥林多前书', 46, 7, 32, 'あなたがたが思い煩わないように、と私は願います。独身の男は、どうすれば主に喜ばれるかと、主のことに心を配ります。'),
('JPN', '哥林多前书', 46, 7, 33, 'しかし、結婚した男は、どうすれば妻に喜ばれるかと世のことに心を配り、'),
('JPN', '哥林多前书', 46, 7, 34, '心が分かれるのです。独身の女や未婚の女は、身も心も聖なるものになろうとして、主のことに心を配りますが、結婚した女は、どうすれば夫に喜ばれるかと、世のことに心を配ります。'),
('JPN', '哥林多前书', 46, 7, 35, '私がこう言うのは、あなたがた自身の益のためです。あなたがたを束縛しようとしているのではありません。むしろ、あなたがたが品位ある生活を送って、ひたすら主に奉仕できるようになるためです。'),
('JPN', '哥林多前书', 46, 7, 36, 'ある人が、自分の婚約者に対して品位を欠いたふるまいをしていると思ったら、また、その婚約者が婚期を過ぎようとしていて、結婚すべきだと思うなら、望んでいるとおりにしなさい。罪を犯すわけではありません。二人は結婚しなさい。'),
('JPN', '哥林多前书', 46, 7, 37, 'しかし、心のうちに固く決意し、強いられてではなく、自分の思いを制して、婚約者をそのままにしておこうと自分の心で決意するなら、それは立派なふるまいです。'),
('JPN', '哥林多前书', 46, 7, 38, 'ですから、婚約者と結婚する人は良いことをしており、結婚しない人はもっと良いことをしているのです。'),
('JPN', '哥林多前书', 46, 7, 39, '妻は、夫が生きている間は夫に縛られています。しかし、夫が死んだら、自分が願う人と結婚する自由があります。ただし、主にある結婚に限ります。'),
('JPN', '哥林多前书', 46, 7, 40, 'しかし、そのままにしていられるなら、そのほうがもっと幸いです。これは私の意見ですが、私も神の御霊をいただいていると思います。'),
('JPN', '哥林多前书', 46, 8, 1, '次に、偶像に献げた肉についてですが、「私たちはみな知識を持っている」ということは分かっています。しかし、知識は人を高ぶらせ、愛は人を育てます。'),
('JPN', '哥林多前书', 46, 8, 2, '自分は何かを知っていると思う人がいたら、その人は、知るべきほどのことをまだ知らないのです。'),
('JPN', '哥林多前书', 46, 8, 3, 'しかし、だれかが神を愛するなら、その人は神に知られています。'),
('JPN', '哥林多前书', 46, 8, 4, 'さて、偶像に献げた肉を食べることについてですが、「世の偶像の神は実際には存在せず、唯一の神以外には神は存在しない」ことを私たちは知っています。'),
('JPN', '哥林多前书', 46, 8, 5, 'というのは、多くの神々や多くの主があるとされているように、たとえ、神々と呼ばれるものが天にも地にもあったとしても、'),
('JPN', '哥林多前书', 46, 8, 6, '私たちには、父なる唯一の神がおられるだけで、この神からすべてのものは発し、この神に私たちは至るからです。また、唯一の主なるイエス・キリストがおられるだけで、この主によってすべてのものは存在し、この主によって私たちも存在するからです。'),
('JPN', '哥林多前书', 46, 8, 7, 'しかし、すべての人にこの知識があるわけではありません。ある人たちは、今まで偶像になじんできたため、偶像に献げられた肉として食べて、その弱い良心が汚されてしまいます。'),
('JPN', '哥林多前书', 46, 8, 8, 'しかし、私たちを神の御前に立たせるのは食物ではありません。食べなくても損にならないし、食べても得になりません。'),
('JPN', '哥林多前书', 46, 8, 9, 'ただ、あなたがたのこの権利が、弱い人たちのつまずきとならないように気をつけなさい。'),
('JPN', '哥林多前书', 46, 8, 10, '知識のあるあなたが偶像の宮で食事をしているのをだれかが見たら、その人はそれに後押しされて、その良心は弱いのに、偶像の神に献げた肉を食べるようにならないでしょうか。'),
('JPN', '哥林多前书', 46, 8, 11, 'つまり、その弱い人は、あなたの知識によって滅びることになります。この兄弟のためにも、キリストは死んでくださったのです。'),
('JPN', '哥林多前书', 46, 8, 12, 'あなたがたはこのように兄弟たちに対して罪を犯し、彼らの弱い良心を傷つけるとき、キリストに対して罪を犯しているのです。'),
('JPN', '哥林多前书', 46, 8, 13, 'ですから、食物が私の兄弟をつまずかせるのなら、兄弟をつまずかせないために、私は今後、決して肉を食べません。'),
('JPN', '哥林多前书', 46, 9, 1, '私には自由がないのですか。私は使徒ではないのですか。私は私たちの主イエスを見なかったのですか。あなたがたは、主にあって私の働きの実ではありませんか。'),
('JPN', '哥林多前书', 46, 9, 2, 'たとえ私がほかの人々に対しては使徒でなくても、少なくともあなたがたに対しては使徒です。あなたがたは、私が主にあって使徒であることの証印です。'),
('JPN', '哥林多前书', 46, 9, 3, '私をさばく人たちに対して、私は次のように弁明します。'),
('JPN', '哥林多前书', 46, 9, 4, '私たちには食べたり飲んだりする権利がないのですか。'),
('JPN', '哥林多前书', 46, 9, 5, '私たちには、ほかの使徒たち、主の兄弟たちや、ケファのように、信者である妻を連れて歩く権利がないのですか。'),
('JPN', '哥林多前书', 46, 9, 6, 'あるいは、私とバルナバだけには、生活のために働かなくてもよいという権利がないのですか。'),
('JPN', '哥林多前书', 46, 9, 7, 'はたして、自分の費用で兵役に服す人がいるでしょうか。自分でぶどう園を造りながら、その実を食べない人がいるでしょうか。羊の群れを飼いながら、その乳を飲まない人がいるでしょうか。'),
('JPN', '哥林多前书', 46, 9, 8, '私がこのようなことを言うのは、人間の考えによるのでしょうか。律法も同じことを言ってはいないでしょうか。'),
('JPN', '哥林多前书', 46, 9, 9, 'モーセの律法には「脱穀をしている牛に口籠をはめてはならない」と書いてあります。はたして神は、牛のことを気にかけておられるのでしょうか。'),
('JPN', '哥林多前书', 46, 9, 10, '私たちのために言っておられるのではありませんか。そうです。私たちのために書かれているのです。なぜなら、耕す者が望みを持って耕し、脱穀する者が分配を受ける望みを持って仕事をするのは、当然だからです。'),
('JPN', '哥林多前书', 46, 9, 11, '私たちがあなたがたに御霊のものを蒔いたのなら、あなたがたから物質的なものを刈り取ることは、行き過ぎでしょうか。'),
('JPN', '哥林多前书', 46, 9, 12, 'ほかの人々があなたがたに対する権利にあずかっているのなら、私たちは、なおさらそうではありませんか。それなのに、私たちはこの権利を用いませんでした。むしろ、キリストの福音に対し何の妨げにもならないように、すべてのことを耐え忍んでいます。'),
('JPN', '哥林多前书', 46, 9, 13, 'あなたがたは、宮に奉仕している者が宮から下がる物を食べ、祭壇に仕える者が祭壇のささげ物にあずかることを知らないのですか。'),
('JPN', '哥林多前书', 46, 9, 14, '同じように主も、福音を宣べ伝える者が、福音の働きから生活の支えを得るように定めておられます。'),
('JPN', '哥林多前书', 46, 9, 15, 'しかし、私はこれらの権利を一つも用いませんでした。また、私は権利を用いたくて、このように書いているのでもありません。それを用いるよりは死んだほうがましです。私の誇りを空しいものにすることは、だれにもできません。'),
('JPN', '哥林多前书', 46, 9, 16, '私が福音を宣べ伝えても、私の誇りにはなりません。そうせずにはいられないのです。福音を宣べ伝えないなら、私はわざわいです。'),
('JPN', '哥林多前书', 46, 9, 17, '私が自発的にそれをしているなら、報いがあります。自発的にするのでないとしても、それは私に務めとして委ねられているのです。'),
('JPN', '哥林多前书', 46, 9, 18, 'では、私にどんな報いがあるのでしょう。それは、福音を宣べ伝えるときに無報酬で福音を提供し、福音宣教によって得る自分の権利を用いない、ということです。'),
('JPN', '哥林多前书', 46, 9, 19, '私はだれに対しても自由ですが、より多くの人を獲得するために、すべての人の奴隷になりました。'),
('JPN', '哥林多前书', 46, 9, 20, 'ユダヤ人にはユダヤ人のようになりました。ユダヤ人を獲得するためです。律法の下にある人たちには──私自身は律法の下にはいませんが──律法の下にある者のようになりました。律法の下にある人たちを獲得するためです。'),
('JPN', '哥林多前书', 46, 9, 21, '律法を持たない人たちには──私自身は神の律法を持たない者ではなく、キリストの律法を守る者ですが──律法を持たない者のようになりました。律法を持たない人たちを獲得するためです。'),
('JPN', '哥林多前书', 46, 9, 22, '弱い人たちには、弱い者になりました。弱い人たちを獲得するためです。すべての人に、すべてのものとなりました。何とかして、何人かでも救うためです。'),
('JPN', '哥林多前书', 46, 9, 23, '私は福音のためにあらゆることをしています。私も福音の恵みをともに受ける者となるためです。'),
('JPN', '哥林多前书', 46, 9, 24, '競技場で走る人たちはみな走っても、賞を受けるのは一人だけだということを、あなたがたは知らないのですか。ですから、あなたがたも賞を得られるように走りなさい。'),
('JPN', '哥林多前书', 46, 9, 25, '競技をする人は、あらゆることについて節制します。彼らは朽ちる冠を受けるためにそうするのですが、私たちは朽ちない冠を受けるためにそうするのです。'),
('JPN', '哥林多前书', 46, 9, 26, 'ですから、私は目標がはっきりしないような走り方はしません。空を打つような拳闘もしません。'),
('JPN', '哥林多前书', 46, 9, 27, 'むしろ、私は自分のからだを打ちたたいて服従させます。ほかの人に宣べ伝えておきながら、自分自身が失格者にならないようにするためです。'),
('JPN', '哥林多前书', 46, 10, 1, '兄弟たち。あなたがたには知らずにいてほしくありません。私たちの先祖はみな雲の下にいて、みな海を通って行きました。'),
('JPN', '哥林多前书', 46, 10, 2, 'そしてみな、雲の中と海の中で、モーセにつくバプテスマを受け、'),
('JPN', '哥林多前书', 46, 10, 3, 'みな、同じ霊的な食べ物を食べ、'),
('JPN', '哥林多前书', 46, 10, 4, 'みな、同じ霊的な飲み物を飲みました。彼らについて来た霊的な岩から飲んだのです。その岩とはキリストです。'),
('JPN', '哥林多前书', 46, 10, 5, 'しかし、彼らの大部分は神のみこころにかなわず、荒野で滅ぼされました。'),
('JPN', '哥林多前书', 46, 10, 6, 'これらのことは、私たちを戒める実例として起こったのです。彼らが貪ったように、私たちが悪を貪ることのないようにするためです。'),
('JPN', '哥林多前书', 46, 10, 7, 'あなたがたは、彼らのうちのある人たちのように、偶像礼拝者になってはいけません。聖書には「民は、座っては食べたり飲んだりし、立っては戯れた」と書いてあります。'),
('JPN', '哥林多前书', 46, 10, 8, 'また私たちは、彼らのうちのある人たちがしたように、淫らなことを行うことのないようにしましょう。彼らはそれをして一日に二万三千人が倒れて死にました。'),
('JPN', '哥林多前书', 46, 10, 9, 'また私たちは、彼らのうちのある人たちがしたように、キリストを試みることのないようにしましょう。彼らは蛇によって滅んでいきました。'),
('JPN', '哥林多前书', 46, 10, 10, 'また、彼らのうちのある人たちがしたように、不平を言ってはいけません。彼らは滅ぼす者によって滅ぼされました。'),
('JPN', '哥林多前书', 46, 10, 11, 'これらのことが彼らに起こったのは、戒めのためであり、それが書かれたのは、世の終わりに臨んでいる私たちへの教訓とするためです。'),
('JPN', '哥林多前书', 46, 10, 12, 'ですから、立っていると思う者は、倒れないように気をつけなさい。'),
('JPN', '哥林多前书', 46, 10, 13, 'あなたがたが経験した試練はみな、人の知らないものではありません。神は真実な方です。あなたがたを耐えられない試練にあわせることはなさいません。むしろ、耐えられるように、試練とともに脱出の道も備えていてくださいます。'),
('JPN', '哥林多前书', 46, 10, 14, 'ですから、私の愛する者たちよ、偶像礼拝を避けなさい。'),
('JPN', '哥林多前书', 46, 10, 15, '私は賢い人たちに話すように話します。私の言うことを判断してください。'),
('JPN', '哥林多前书', 46, 10, 16, '私たちが神をほめたたえる賛美の杯は、キリストの血にあずかることではありませんか。私たちが裂くパンは、キリストのからだにあずかることではありませんか。'),
('JPN', '哥林多前书', 46, 10, 17, 'パンは一つですから、私たちは大勢いても、一つのからだです。皆がともに一つのパンを食べるのですから。'),
('JPN', '哥林多前书', 46, 10, 18, '肉によるイスラエルのことを考えてみなさい。ささげ物を食する者は、祭壇の交わりにあずかることになるのではありませんか。'),
('JPN', '哥林多前书', 46, 10, 19, '私は何を言おうとしているのでしょうか。偶像に献げた肉に何か意味があるとか、偶像に何か意味があるとか、言おうとしているのでしょうか。'),
('JPN', '哥林多前书', 46, 10, 20, 'むしろ、彼らが献げる物は、神にではなくて悪霊に献げられている、と言っているのです。私は、あなたがたに悪霊と交わる者になってもらいたくありません。'),
('JPN', '哥林多前书', 46, 10, 21, 'あなたがたは、主の杯を飲みながら、悪霊の杯を飲むことはできません。主の食卓にあずかりながら、悪霊の食卓にあずかることはできません。'),
('JPN', '哥林多前书', 46, 10, 22, 'それとも、私たちは主のねたみを引き起こすつもりなのですか。私たちは主よりも強い者なのですか。'),
('JPN', '哥林多前书', 46, 10, 23, '「すべてのことが許されている」と言いますが、すべてのことが益になるわけではありません。「すべてのことが許されている」と言いますが、すべてのことが人を育てるとはかぎりません。'),
('JPN', '哥林多前书', 46, 10, 24, 'だれでも、自分の利益を求めず、ほかの人の利益を求めなさい。'),
('JPN', '哥林多前书', 46, 10, 25, '市場で売っている肉はどれでも、良心の問題を問うことをせずに食べなさい。'),
('JPN', '哥林多前书', 46, 10, 26, '地とそこに満ちているものは、主のものだからです。'),
('JPN', '哥林多前书', 46, 10, 27, 'あなたがたが、信仰のないだれかに招待されて、そこに行きたいと思うときには、自分の前に出される物はどれも、良心の問題を問うことをせずに食べなさい。'),
('JPN', '哥林多前书', 46, 10, 28, 'しかし、だれかがあなたがたに「これは偶像に献げた肉です」と言うなら、そう知らせてくれた人のため、また良心のために、食べてはいけません。'),
('JPN', '哥林多前书', 46, 10, 29, '良心と言っているのは、あなた自身の良心ではなく、知らせてくれた人の良心です。私の自由が、どうしてほかの人の良心によってさばかれるでしょうか。'),
('JPN', '哥林多前书', 46, 10, 30, 'もし私が感謝して食べるなら、どうして私が感謝する物のために悪く言われるのでしょうか。'),
('JPN', '哥林多前书', 46, 10, 31, 'こういうわけで、あなたがたは、食べるにも飲むにも、何をするにも、すべて神の栄光を現すためにしなさい。'),
('JPN', '哥林多前书', 46, 10, 32, 'ユダヤ人にも、ギリシア人にも、神の教会にも、つまずきを与えない者になりなさい。'),
('JPN', '哥林多前书', 46, 10, 33, '私も、人々が救われるために、自分の利益ではなく多くの人々の利益を求め、すべてのことですべての人を喜ばせようと努めているのです。'),
('JPN', '哥林多前书', 46, 11, 1, '私がキリストに倣う者であるように、あなたがたも私に倣う者でありなさい。'),
('JPN', '哥林多前书', 46, 11, 2, 'さて、私はあなたがたをほめたいと思います。あなたがたは、すべての点で私を覚え、私があなたがたに伝えたとおりに、伝えられた教えを堅く守っているからです。'),
('JPN', '哥林多前书', 46, 11, 3, 'しかし、あなたがたに次のことを知ってほしいのです。すべての男のかしらはキリストであり、女のかしらは男であり、キリストのかしらは神です。'),
('JPN', '哥林多前书', 46, 11, 4, '男はだれでも祈りや預言をするとき、頭をおおっていたら、自分の頭を辱めることになります。'),
('JPN', '哥林多前书', 46, 11, 5, 'しかし、女はだれでも祈りや預言をするとき、頭にかぶり物を着けていなかったら、自分の頭を辱めることになります。それは頭を剃っているのと全く同じことなのです。'),
('JPN', '哥林多前书', 46, 11, 6, '女は、かぶり物を着けないのなら、髪も切ってしまいなさい。髪を切り、頭を剃ることが女として恥ずかしいことなら、かぶり物を着けなさい。'),
('JPN', '哥林多前书', 46, 11, 7, '男は神のかたちであり、神の栄光の現れなので、頭にかぶり物を着けるべきではありません。一方、女は男の栄光の現れです。'),
('JPN', '哥林多前书', 46, 11, 8, '男が女から出たのではなく、女が男から出たからです。'),
('JPN', '哥林多前书', 46, 11, 9, 'また、男が女のために造られたのではなく、女が男のために造られたからです。'),
('JPN', '哥林多前书', 46, 11, 10, 'それゆえ、女は御使いたちのため、頭に権威のしるしをかぶるべきです。'),
('JPN', '哥林多前书', 46, 11, 11, 'とはいえ、主にあっては、女は男なしにあるものではなく、男も女なしにあるものではありません。'),
('JPN', '哥林多前书', 46, 11, 12, '女が男から出たのと同様に、男も女によって生まれるのだからです。しかし、すべては神から出ています。'),
('JPN', '哥林多前书', 46, 11, 13, 'あなたがたは自分自身で判断しなさい。女が何もかぶらないで神に祈るのは、ふさわしいことでしょうか。'),
('JPN', '哥林多前书', 46, 11, 14, '自然そのものが、あなたがたにこう教えていないでしょうか。男が長い髪をしていたら、それは彼にとって恥ずかしいことであり、'),
('JPN', '哥林多前书', 46, 11, 15, '女が長い髪をしていたら、それは彼女にとっては栄誉なのです。なぜなら、髪はかぶり物として女に与えられているからです。'),
('JPN', '哥林多前书', 46, 11, 16, 'たとえ、だれかがこのことに異議を唱えたくても、そのような習慣は私たちにはなく、神の諸教会にもありません。'),
('JPN', '哥林多前书', 46, 11, 17, 'ところで、次のことを命じるにあたって、私はあなたがたをほめるわけにはいきません。あなたがたの集まりが益にならず、かえって害になっているからです。'),
('JPN', '哥林多前书', 46, 11, 18, 'まず第一に、あなたがたが教会に集まる際、あなたがたの間に分裂があると聞いています。ある程度は、そういうこともあろうかと思います。'),
('JPN', '哥林多前书', 46, 11, 19, '実際、あなたがたの間で本当の信者が明らかにされるためには、分派が生じるのもやむを得ません。'),
('JPN', '哥林多前书', 46, 11, 20, 'しかし、そういうわけで、あなたがたが一緒に集まっても、主の晩餐を食べることにはなりません。'),
('JPN', '哥林多前书', 46, 11, 21, 'というのも、食事のとき、それぞれが我先にと自分の食事をするので、空腹な者もいれば、酔っている者もいるという始末だからです。'),
('JPN', '哥林多前书', 46, 11, 22, 'あなたがたには、食べたり飲んだりする家がないのですか。それとも、神の教会を軽んじて、貧しい人たちに恥ずかしい思いをさせたいのですか。私はあなたがたにどう言うべきでしょうか。ほめるべきでしょうか。このことでは、ほめるわけにはいきません。'),
('JPN', '哥林多前书', 46, 11, 23, '私は主から受けたことを、あなたがたに伝えました。すなわち、主イエスは渡される夜、パンを取り、'),
('JPN', '哥林多前书', 46, 11, 24, '感謝の祈りをささげた後それを裂き、こう言われました。「これはあなたがたのための、わたしのからだです。わたしを覚えて、これを行いなさい。」'),
('JPN', '哥林多前书', 46, 11, 25, '食事の後、同じように杯を取って言われました。「この杯は、わたしの血による新しい契約です。飲むたびに、わたしを覚えて、これを行いなさい。」'),
('JPN', '哥林多前书', 46, 11, 26, 'ですから、あなたがたは、このパンを食べ、杯を飲むたびに、主が来られるまで主の死を告げ知らせるのです。'),
('JPN', '哥林多前书', 46, 11, 27, 'したがって、もし、ふさわしくない仕方でパンを食べ、主の杯を飲む者があれば、主のからだと血に対して罪を犯すことになります。'),
('JPN', '哥林多前书', 46, 11, 28, 'だれでも、自分自身を吟味して、そのうえでパンを食べ、杯を飲みなさい。'),
('JPN', '哥林多前书', 46, 11, 29, 'みからだをわきまえないで食べ、また飲む者は、自分自身に対するさばきを食べ、また飲むことになるのです。'),
('JPN', '哥林多前书', 46, 11, 30, 'あなたがたの中に弱い者や病人が多く、死んだ者たちもかなりいるのは、そのためです。'),
('JPN', '哥林多前书', 46, 11, 31, 'しかし、もし私たちが自分をわきまえるなら、さばかれることはありません。'),
('JPN', '哥林多前书', 46, 11, 32, '私たちがさばかれるとすれば、それは、この世とともにさばきを下されることがないように、主によって懲らしめられる、ということなのです。'),
('JPN', '哥林多前书', 46, 11, 33, 'ですから、兄弟たち。食事に集まるときは、互いに待ち合わせなさい。'),
('JPN', '哥林多前书', 46, 11, 34, '空腹な人は家で食べなさい。あなたがたが集まることによって、さばきを受けないようにするためです。このほかのことについては、私が行ったときに決めることにします。'),
('JPN', '哥林多前书', 46, 12, 1, 'さて、兄弟たち。御霊の賜物については、私はあなたがたに知らずにいてほしくありません。'),
('JPN', '哥林多前书', 46, 12, 2, 'ご存じのとおり、あなたがたが異教徒であったときには、誘われるまま、ものを言えない偶像のところに引かれて行きました。'),
('JPN', '哥林多前书', 46, 12, 3, 'ですから、あなたがたに次のことを教えておきます。神の御霊によって語る者はだれも「イエスは、のろわれよ」と言うことはなく、また、聖霊によるのでなければ、だれも「イエスは主です」と言うことはできません。'),
('JPN', '哥林多前书', 46, 12, 4, 'さて、賜物はいろいろありますが、与える方は同じ御霊です。'),
('JPN', '哥林多前书', 46, 12, 5, '奉仕はいろいろありますが、仕える相手は同じ主です。'),
('JPN', '哥林多前书', 46, 12, 6, '働きはいろいろありますが、同じ神がすべての人の中で、すべての働きをなさいます。'),
('JPN', '哥林多前书', 46, 12, 7, '皆の益となるために、一人ひとりに御霊の現れが与えられているのです。'),
('JPN', '哥林多前书', 46, 12, 8, 'ある人には御霊を通して知恵のことばが、ある人には同じ御霊によって知識のことばが与えられています。'),
('JPN', '哥林多前书', 46, 12, 9, 'ある人には同じ御霊によって信仰、ある人には同一の御霊によって癒やしの賜物、'),
('JPN', '哥林多前书', 46, 12, 10, 'ある人には奇跡を行う力、ある人には預言、ある人には霊を見分ける力、ある人には種々の異言、ある人には異言を解き明かす力が与えられています。'),
('JPN', '哥林多前书', 46, 12, 11, '同じ一つの御霊がこれらすべてのことをなさるのであり、御霊は、みこころのままに、一人ひとりそれぞれに賜物を分け与えてくださるのです。'),
('JPN', '哥林多前书', 46, 12, 12, 'ちょうど、からだが一つでも、多くの部分があり、からだの部分が多くても、一つのからだであるように、キリストもそれと同様です。'),
('JPN', '哥林多前书', 46, 12, 13, '私たちはみな、ユダヤ人もギリシア人も、奴隷も自由人も、一つの御霊によってバプテスマを受けて、一つのからだとなりました。そして、みな一つの御霊を飲んだのです。'),
('JPN', '哥林多前书', 46, 12, 14, '実際、からだはただ一つの部分からではなく、多くの部分から成っています。'),
('JPN', '哥林多前书', 46, 12, 15, 'たとえ足が「私は手ではないから、からだに属さない」と言ったとしても、それで、からだに属さなくなるわけではありません。'),
('JPN', '哥林多前书', 46, 12, 16, 'たとえ耳が「私は目ではないから、からだに属さない」と言ったとしても、それで、からだに属さなくなるわけではありません。'),
('JPN', '哥林多前书', 46, 12, 17, 'もし、からだ全体が目であったら、どこで聞くのでしょうか。もし、からだ全体が耳であったら、どこでにおいを嗅ぐのでしょうか。'),
('JPN', '哥林多前书', 46, 12, 18, 'しかし実際、神はみこころにしたがって、からだの中にそれぞれの部分を備えてくださいました。'),
('JPN', '哥林多前书', 46, 12, 19, 'もし全体がただ一つの部分だとしたら、からだはどこにあるのでしょうか。'),
('JPN', '哥林多前书', 46, 12, 20, 'しかし実際、部分は多くあり、からだは一つなのです。'),
('JPN', '哥林多前书', 46, 12, 21, '目が手に向かって「あなたはいらない」と言うことはできないし、頭が足に向かって「あなたがたはいらない」と言うこともできません。'),
('JPN', '哥林多前书', 46, 12, 22, 'それどころか、からだの中でほかより弱く見える部分が、かえってなくてはならないのです。'),
('JPN', '哥林多前书', 46, 12, 23, 'また私たちは、からだの中で見栄えがほかより劣っていると思う部分を、見栄えをよくするものでおおいます。こうして、見苦しい部分はもっと良い格好になりますが、'),
('JPN', '哥林多前书', 46, 12, 24, '格好の良い部分はその必要がありません。神は、劣ったところには、見栄えをよくするものを与えて、からだを組み合わせられました。'),
('JPN', '哥林多前书', 46, 12, 25, 'それは、からだの中に分裂がなく、各部分が互いのために、同じように配慮し合うためです。'),
('JPN', '哥林多前书', 46, 12, 26, '一つの部分が苦しめば、すべての部分がともに苦しみ、一つの部分が尊ばれれば、すべての部分がともに喜ぶのです。'),
('JPN', '哥林多前书', 46, 12, 27, 'あなたがたはキリストのからだであって、一人ひとりはその部分です。'),
('JPN', '哥林多前书', 46, 12, 28, '神は教会の中に、第一に使徒たち、第二に預言者たち、第三に教師たち、そして力あるわざ、そして癒やしの賜物、援助、管理、種々の異言を備えてくださいました。'),
('JPN', '哥林多前书', 46, 12, 29, '皆が使徒でしょうか。皆が預言者でしょうか。皆が教師でしょうか。すべてが力あるわざでしょうか。'),
('JPN', '哥林多前书', 46, 12, 30, '皆が癒やしの賜物を持っているでしょうか。皆が異言を語るでしょうか。皆がその解き明かしをするでしょうか。'),
('JPN', '哥林多前书', 46, 12, 31, 'あなたがたは、よりすぐれた賜物を熱心に求めなさい。私は今、はるかにまさる道を示しましょう。'),
('JPN', '哥林多前书', 46, 13, 1, 'たとえ私が人の異言や御使いの異言で話しても、愛がなければ、騒がしいどらや、うるさいシンバルと同じです。'),
('JPN', '哥林多前书', 46, 13, 2, 'たとえ私が預言の賜物を持ち、あらゆる奥義とあらゆる知識に通じていても、たとえ山を動かすほどの完全な信仰を持っていても、愛がないなら、私は無に等しいのです。'),
('JPN', '哥林多前书', 46, 13, 3, 'たとえ私が持っている物のすべてを分け与えても、たとえ私のからだを引き渡して誇ることになっても、愛がなければ、何の役にも立ちません。'),
('JPN', '哥林多前书', 46, 13, 4, '愛は寛容であり、愛は親切です。また人をねたみません。愛は自慢せず、高慢になりません。'),
('JPN', '哥林多前书', 46, 13, 5, '礼儀に反することをせず、自分の利益を求めず、苛立たず、人がした悪を心に留めず、'),
('JPN', '哥林多前书', 46, 13, 6, '不正を喜ばずに、真理を喜びます。'),
('JPN', '哥林多前书', 46, 13, 7, 'すべてを耐え、すべてを信じ、すべてを望み、すべてを忍びます。'),
('JPN', '哥林多前书', 46, 13, 8, '愛は決して絶えることがありません。預言ならすたれます。異言ならやみます。知識ならすたれます。'),
('JPN', '哥林多前书', 46, 13, 9, '私たちが知るのは一部分、預言するのも一部分であり、'),
('JPN', '哥林多前书', 46, 13, 10, '完全なものが現れたら、部分的なものはすたれるのです。'),
('JPN', '哥林多前书', 46, 13, 11, '私は、幼子であったときには、幼子として話し、幼子として思い、幼子として考えましたが、大人になったとき、幼子のことはやめました。'),
('JPN', '哥林多前书', 46, 13, 12, '今、私たちは鏡にぼんやり映るものを見ていますが、そのときには顔と顔を合わせて見ることになります。今、私は一部分しか知りませんが、そのときには、私が完全に知られているのと同じように、私も完全に知ることになります。'),
('JPN', '哥林多前书', 46, 13, 13, 'こういうわけで、いつまでも残るのは信仰と希望と愛、これら三つです。その中で一番すぐれているのは愛です。'),
('JPN', '哥林多前书', 46, 14, 1, '愛を追い求めなさい。また、御霊の賜物、特に預言することを熱心に求めなさい。'),
('JPN', '哥林多前书', 46, 14, 2, '異言で語る人は、人に向かって語るのではなく、神に向かって語ります。だれも理解できませんが、御霊によって奥義を語るのです。'),
('JPN', '哥林多前书', 46, 14, 3, 'しかし預言する人は、人を育てることばや勧めや慰めを、人に向かって話します。'),
('JPN', '哥林多前书', 46, 14, 4, '異言で語る人は自らを成長させますが、預言する人は教会を成長させます。'),
('JPN', '哥林多前书', 46, 14, 5, '私は、あなたがたがみな異言で語ることを願いますが、それ以上に願うのは、あなたがたが預言することです。異言で語る人がその解き明かしをして教会の成長に役立つのでないかぎり、預言する人のほうがまさっています。'),
('JPN', '哥林多前书', 46, 14, 6, 'ですから、兄弟たち。私があなたがたのところに行って異言で語るとしても、啓示か知識か預言か教えによって語るのでなければ、あなたがたに何の益になるでしょう。'),
('JPN', '哥林多前书', 46, 14, 7, '笛や竪琴など、いのちのない楽器でも、変化のある音を出さなければ、何を吹いているのか、何を弾いているのか、どうして分かるでしょうか。'),
('JPN', '哥林多前书', 46, 14, 8, 'また、ラッパがはっきりしない音を出したら、だれが戦いの準備をするでしょう。'),
('JPN', '哥林多前书', 46, 14, 9, '同じようにあなたがたも、舌で明瞭なことばを語らなければ、話していることをどうして分かってもらえるでしょうか。空気に向かって話していることになります。'),
('JPN', '哥林多前书', 46, 14, 10, '世界には、おそらく非常に多くの種類のことばがあるでしょうが、意味のないことばは一つもありません。'),
('JPN', '哥林多前书', 46, 14, 11, 'それで、もし私がそのことばの意味を知らなければ、私はそれを話す人にとって外国人であり、それを話す人も私には外国人となるでしょう。'),
('JPN', '哥林多前书', 46, 14, 12, '同じようにあなたがたも、御霊の賜物を熱心に求めているのですから、教会を成長させるために、それが豊かに与えられるように求めなさい。'),
('JPN', '哥林多前书', 46, 14, 13, 'そういうわけで、異言で語る人は、それを解き明かすことができるように祈りなさい。'),
('JPN', '哥林多前书', 46, 14, 14, 'もし私が異言で祈るなら、私の霊は祈りますが、私の知性は実を結びません。'),
('JPN', '哥林多前书', 46, 14, 15, 'それでは、どうすればよいのでしょう。私は霊で祈り、知性でも祈りましょう。霊で賛美し、知性でも賛美しましょう。'),
('JPN', '哥林多前书', 46, 14, 16, 'そうでないと、あなたが霊において賛美しても、初心者の席に着いている人は、あなたの感謝について、どうしてアーメンと言えるでしょう。あなたが言っていることが分からないのですから。'),
('JPN', '哥林多前书', 46, 14, 17, 'あなたが感謝するのはけっこうですが、そのことでほかの人が育てられるわけではありません。'),
('JPN', '哥林多前书', 46, 14, 18, '私は、あなたがたのだれよりも多くの異言で語っていることを、神に感謝しています。'),
('JPN', '哥林多前书', 46, 14, 19, 'しかし教会では、異言で一万のことばを語るよりむしろ、ほかの人たちにも教えるために、私の知性で五つのことばを語りたいと思います。'),
('JPN', '哥林多前书', 46, 14, 20, '兄弟たち、考え方において子どもになってはいけません。悪事においては幼子でありなさい。けれども、考え方においては大人になりなさい。'),
('JPN', '哥林多前书', 46, 14, 21, '律法にこう書かれています。「『わたしは、異国の舌で、異なる唇でこの民に語る。それでも彼らは、わたしの言うことを聞こうとはしない』と主は言われる。」'),
('JPN', '哥林多前书', 46, 14, 22, 'それで異言は、信じている者たちのためではなく、信じていない者たちのためのしるしであり、預言は、信じていない者たちのためではなく、信じている者たちのためのしるしです。'),
('JPN', '哥林多前书', 46, 14, 23, 'ですから、教会全体が一緒に集まって、皆が異言で語るなら、初心の人か信じていない人が入って来たとき、あなたがたは気が変になっていると言われることにならないでしょうか。'),
('JPN', '哥林多前书', 46, 14, 24, 'しかし、皆が預言をするなら、信じていない人や初心の人が入って来たとき、その人は皆に誤りを指摘され、皆に問いただされ、'),
('JPN', '哥林多前书', 46, 14, 25, '心の秘密があらわにされます。こうして、「神が確かにあなたがたの中におられる」と言い、ひれ伏して神を拝むでしょう。'),
('JPN', '哥林多前书', 46, 14, 26, 'それでは、兄弟たち、どうすればよいのでしょう。あなたがたが集まるときには、それぞれが賛美したり、教えたり、啓示を告げたり、異言を話したり、解き明かしたりすることができます。そのすべてのことを、成長に役立てるためにしなさい。'),
('JPN', '哥林多前书', 46, 14, 27, 'だれかが異言で語るのであれば、二人か、多くても三人で順番に行い、一人が解き明かしをしなさい。'),
('JPN', '哥林多前书', 46, 14, 28, '解き明かす者がいなければ、教会では黙っていて、自分に対し、また神に対して語りなさい。'),
('JPN', '哥林多前书', 46, 14, 29, '預言する者たちも、二人か三人が語り、ほかの者たちはそれを吟味しなさい。'),
('JPN', '哥林多前书', 46, 14, 30, '席に着いている別の人に啓示が与えられたら、先に語っていた人は黙りなさい。'),
('JPN', '哥林多前书', 46, 14, 31, 'だれでも学び、だれでも励ましが受けられるように、だれでも一人ずつ預言することができるのです。'),
('JPN', '哥林多前书', 46, 14, 32, '預言する者たちの霊は預言する者たちに従います。'),
('JPN', '哥林多前书', 46, 14, 33, '神は混乱の神ではなく、平和の神なのです。聖徒たちのすべての教会で行われているように、'),
('JPN', '哥林多前书', 46, 14, 34, '女の人は教会では黙っていなさい。彼女たちは語ることを許されていません。律法も言っているように、従いなさい。'),
('JPN', '哥林多前书', 46, 14, 35, 'もし何かを知りたければ、家で自分の夫に尋ねなさい。教会で語ることは、女の人にとって恥ずかしいことなのです。'),
('JPN', '哥林多前书', 46, 14, 36, '神のことばは、あなたがたのところから出たのでしょうか。あるいは、あなたがたにだけ伝わったのでしょうか。'),
('JPN', '哥林多前书', 46, 14, 37, 'だれかが自分を預言者、あるいは御霊の人と思っているなら、その人は、私があなたがたに書くことが主の命令であることを認めなさい。'),
('JPN', '哥林多前书', 46, 14, 38, 'それを無視する人がいるなら、その人は無視されます。'),
('JPN', '哥林多前书', 46, 14, 39, 'ですから、私の兄弟たち、預言することを熱心に求めなさい。また、異言で語ることを禁じてはいけません。'),
('JPN', '哥林多前书', 46, 14, 40, 'ただ、すべてのことを適切に、秩序正しく行いなさい。'),
('JPN', '哥林多前书', 46, 15, 1, '兄弟たち。私があなたがたに宣べ伝えた福音を、改めて知らせます。あなたがたはその福音を受け入れ、その福音によって立っているのです。'),
('JPN', '哥林多前书', 46, 15, 2, '私がどのようなことばで福音を伝えたか、あなたがたがしっかり覚えているなら、この福音によって救われます。そうでなければ、あなたがたが信じたことは無駄になってしまいます。'),
('JPN', '哥林多前书', 46, 15, 3, '私があなたがたに最も大切なこととして伝えたのは、私も受けたことであって、次のことです。キリストは、聖書に書いてあるとおりに、私たちの罪のために死なれたこと、'),
('JPN', '哥林多前书', 46, 15, 4, 'また、葬られたこと、また、聖書に書いてあるとおりに、三日目によみがえられたこと、'),
('JPN', '哥林多前书', 46, 15, 5, 'また、ケファに現れ、それから十二弟子に現れたことです。'),
('JPN', '哥林多前书', 46, 15, 6, 'その後、キリストは五百人以上の兄弟たちに同時に現れました。その中にはすでに眠った人も何人かいますが、大多数は今なお生き残っています。'),
('JPN', '哥林多前书', 46, 15, 7, 'その後、キリストはヤコブに現れ、それからすべての使徒たちに現れました。'),
('JPN', '哥林多前书', 46, 15, 8, 'そして最後に、月足らずで生まれた者のような私にも現れてくださいました。'),
('JPN', '哥林多前书', 46, 15, 9, '私は使徒の中では最も小さい者であり、神の教会を迫害したのですから、使徒と呼ばれるに値しない者です。'),
('JPN', '哥林多前书', 46, 15, 10, 'ところが、神の恵みによって、私は今の私になりました。そして、私に対するこの神の恵みは無駄にはならず、私はほかのすべての使徒たちよりも多く働きました。働いたのは私ではなく、私とともにあった神の恵みなのですが。'),
('JPN', '哥林多前书', 46, 15, 11, 'とにかく、私にせよ、ほかの人たちにせよ、私たちはこのように宣べ伝えているのであり、あなたがたはこのように信じたのです。'),
('JPN', '哥林多前书', 46, 15, 12, 'ところで、キリストは死者の中からよみがえられたと宣べ伝えられているのに、どうして、あなたがたの中に、死者の復活はないと言う人たちがいるのですか。'),
('JPN', '哥林多前书', 46, 15, 13, 'もし死者の復活がないとしたら、キリストもよみがえらなかったでしょう。'),
('JPN', '哥林多前书', 46, 15, 14, 'そして、キリストがよみがえらなかったとしたら、私たちの宣教は空しく、あなたがたの信仰も空しいものとなります。'),
('JPN', '哥林多前书', 46, 15, 15, '私たちは神についての偽証人ということにさえなります。なぜなら、かりに死者がよみがえらないとしたら、神はキリストをよみがえらせなかったはずなのに、私たちは神がキリストをよみがえらせたと言って、神に逆らう証言をしたことになるからです。'),
('JPN', '哥林多前书', 46, 15, 16, 'もし死者がよみがえらないとしたら、キリストもよみがえらなかったでしょう。'),
('JPN', '哥林多前书', 46, 15, 17, 'そして、もしキリストがよみがえらなかったとしたら、あなたがたの信仰は空しく、あなたがたは今もなお自分の罪の中にいます。'),
('JPN', '哥林多前书', 46, 15, 18, 'そうだとしたら、キリストにあって眠った者たちは、滅んでしまったことになります。'),
('JPN', '哥林多前书', 46, 15, 19, 'もし私たちが、この地上のいのちにおいてのみ、キリストに望みを抱いているのなら、私たちはすべての人の中で一番哀れな者です。'),
('JPN', '哥林多前书', 46, 15, 20, 'しかし、今やキリストは、眠った者の初穂として死者の中からよみがえられました。'),
('JPN', '哥林多前书', 46, 15, 21, '死が一人の人を通して来たのですから、死者の復活も一人の人を通して来るのです。'),
('JPN', '哥林多前书', 46, 15, 22, 'アダムにあってすべての人が死んでいるように、キリストにあってすべての人が生かされるのです。'),
('JPN', '哥林多前书', 46, 15, 23, 'しかし、それぞれに順序があります。まず初穂であるキリスト、次にその来臨のときにキリストに属している人たちです。'),
('JPN', '哥林多前书', 46, 15, 24, 'それから終わりが来ます。そのとき、キリストはあらゆる支配と、あらゆる権威、権力を滅ぼし、王国を父である神に渡されます。'),
('JPN', '哥林多前书', 46, 15, 25, 'すべての敵をその足の下に置くまで、キリストは王として治めることになっているからです。'),
('JPN', '哥林多前书', 46, 15, 26, '最後の敵として滅ぼされるのは、死です。'),
('JPN', '哥林多前书', 46, 15, 27, '「神は万物をその方の足の下に従わせた」のです。しかし、万物が従わせられたと言うとき、そこには万物をキリストに従わせた方が含まれていないことは明らかです。'),
('JPN', '哥林多前书', 46, 15, 28, 'そして、万物が御子に従うとき、御子自身も、万物をご自分に従わせてくださった方に従われます。これは、神が、すべてにおいてすべてとなられるためです。'),
('JPN', '哥林多前书', 46, 15, 29, 'そうでなかったら、死者のためにバプテスマを受ける人たちは、何をしようとしているのですか。死者が決してよみがえらないのなら、その人たちは、なぜ死者のためにバプテスマを受けるのですか。'),
('JPN', '哥林多前书', 46, 15, 30, 'なぜ私たちも、絶えず危険にさらされているのでしょうか。'),
('JPN', '哥林多前书', 46, 15, 31, '兄弟たち。私たちの主キリスト・イエスにあって私が抱いている、あなたがたについての誇りにかけて言いますが、私は日々死んでいるのです。'),
('JPN', '哥林多前书', 46, 15, 32, 'もし私が人間の考えからエペソで獣と戦ったのなら、何の得があったでしょう。もし死者がよみがえらないのなら、「食べたり飲んだりしようではないか。どうせ、明日は死ぬのだから」ということになります。'),
('JPN', '哥林多前书', 46, 15, 33, '惑わされてはいけません。「悪い交際は良い習慣を損なう」のです。'),
('JPN', '哥林多前书', 46, 15, 34, '目を覚まして正しい生活を送り、罪を犯さないようにしなさい。神について無知な人たちがいます。私はあなたがたを恥じ入らせるために言っているのです。'),
('JPN', '哥林多前书', 46, 15, 35, 'しかし、「死者はどのようにしてよみがえるのか。どのようなからだで来るのか」と言う人がいるでしょう。'),
('JPN', '哥林多前书', 46, 15, 36, '愚かな人だ。あなたが蒔くものは、死ななければ生かされません。'),
('JPN', '哥林多前书', 46, 15, 37, 'また、あなたが蒔くものは、後にできるからだではなく、麦であれ、そのほかの穀物であれ、ただの種粒です。'),
('JPN', '哥林多前书', 46, 15, 38, 'しかし神は、みこころのままに、それにからだを与え、それぞれの種にそれ自身のからだをお与えになります。'),
('JPN', '哥林多前书', 46, 15, 39, 'どんな肉も同じではなく、人間の肉、獣の肉、鳥の肉、魚の肉、それぞれ違います。'),
('JPN', '哥林多前书', 46, 15, 40, 'また、天上のからだもあり、地上のからだもあり、天上のからだの輝きと地上のからだの輝きは異なり、'),
('JPN', '哥林多前书', 46, 15, 41, '太陽の輝き、月の輝き、星の輝き、それぞれ違います。星と星の間でも輝きが違います。'),
('JPN', '哥林多前书', 46, 15, 42, '死者の復活もこれと同じです。朽ちるもので蒔かれ、朽ちないものによみがえらされ、'),
('JPN', '哥林多前书', 46, 15, 43, '卑しいもので蒔かれ、栄光あるものによみがえらされ、弱いもので蒔かれ、力あるものによみがえらされ、'),
('JPN', '哥林多前书', 46, 15, 44, '血肉のからだで蒔かれ、御霊に属するからだによみがえらされるのです。血肉のからだがあるのですから、御霊のからだもあるのです。'),
('JPN', '哥林多前书', 46, 15, 45, 'こう書かれています。「最初の人アダムは生きるものとなった。」しかし、最後のアダムはいのちを与える御霊となりました。'),
('JPN', '哥林多前书', 46, 15, 46, '最初にあったのは、御霊のものではなく血肉のものです。御霊のものは後に来るのです。'),
('JPN', '哥林多前书', 46, 15, 47, '第一の人は地から出て、土で造られた人ですが、第二の人は天から出た方です。'),
('JPN', '哥林多前书', 46, 15, 48, '土で造られた者たちはみな、この土で造られた人に似ており、天に属する者たちはみな、この天に属する方に似ています。'),
('JPN', '哥林多前书', 46, 15, 49, '私たちは、土で造られた人のかたちを持っていたように、天に属する方のかたちも持つことになるのです。'),
('JPN', '哥林多前书', 46, 15, 50, '兄弟たち、私はこのことを言っておきます。血肉のからだは神の国を相続できません。朽ちるものは、朽ちないものを相続できません。'),
('JPN', '哥林多前书', 46, 15, 51, '聞きなさい。私はあなたがたに奥義を告げましょう。私たちはみな眠るわけではありませんが、みな変えられます。'),
('JPN', '哥林多前书', 46, 15, 52, '終わりのラッパとともに、たちまち、一瞬のうちに変えられます。ラッパが鳴ると、死者は朽ちないものによみがえり、私たちは変えられるのです。'),
('JPN', '哥林多前书', 46, 15, 53, 'この朽ちるべきものが、朽ちないものを必ず着ることになり、この死ぬべきものが、死なないものを必ず着ることになるからです。'),
('JPN', '哥林多前书', 46, 15, 54, 'そして、この朽ちるべきものが朽ちないものを着て、この死ぬべきものが死なないものを着るとき、このように記されたみことばが実現します。「死は勝利に吞み込まれた。」'),
('JPN', '哥林多前书', 46, 15, 55, '「死よ、おまえの勝利はどこにあるのか。死よ、おまえのとげはどこにあるのか。」'),
('JPN', '哥林多前书', 46, 15, 56, '死のとげは罪であり、罪の力は律法です。'),
('JPN', '哥林多前书', 46, 15, 57, 'しかし、神に感謝します。神は、私たちの主イエス・キリストによって、私たちに勝利を与えてくださいました。'),
('JPN', '哥林多前书', 46, 15, 58, 'ですから、私の愛する兄弟たち。堅く立って、動かされることなく、いつも主のわざに励みなさい。あなたがたは、自分たちの労苦が主にあって無駄でないことを知っているのですから。'),
('JPN', '哥林多前书', 46, 16, 1, 'さて、聖徒たちのための献金については、ガラテヤの諸教会に命じたとおりに、あなたがたも行いなさい。'),
('JPN', '哥林多前书', 46, 16, 2, '私がそちらに行ってから献金を集めることがないように、あなたがたはそれぞれ、いつも週の初めの日に、収入に応じて、いくらかでも手もとに蓄えておきなさい。'),
('JPN', '哥林多前书', 46, 16, 3, '私がそちらに着いたら、あなたがたの承認を得た人たちに手紙を持たせてエルサレムに派遣し、あなたがたの贈り物を届けさせましょう。'),
('JPN', '哥林多前书', 46, 16, 4, 'もし私も行くほうがよければ、その人たちは私と一緒に行くことになるでしょう。'),
('JPN', '哥林多前书', 46, 16, 5, '私はマケドニアを通って、あなたがたのところへ行きます。マケドニアはただ通過し、'),
('JPN', '哥林多前书', 46, 16, 6, 'おそらく、あなたがたのところに滞在するでしょう。冬を越すことになるかもしれません。どこに向かうにしても、あなたがたに送り出してもらうためです。'),
('JPN', '哥林多前书', 46, 16, 7, '私は今、旅のついでにあなたがたに会うようなことはしたくありません。主がお許しになるなら、あなたがたのところにしばらく滞在したいと願っています。'),
('JPN', '哥林多前书', 46, 16, 8, 'しかし、五旬節まではエペソに滞在します。'),
('JPN', '哥林多前书', 46, 16, 9, '実り多い働きをもたらす門が私のために広く開かれていますが、反対者も大勢いるからです。'),
('JPN', '哥林多前书', 46, 16, 10, 'テモテがそちらに行ったら、あなたがたのところで心配なく過ごせるようにしてあげてください。彼も私と同じように、主のみわざに励んでいるのです。'),
('JPN', '哥林多前书', 46, 16, 11, 'だれも彼を軽んじてはいけません。彼を平安のうちに送り出して、私のところに来させてください。私は、彼が兄弟たちと一緒に戻るのを待っています。'),
('JPN', '哥林多前书', 46, 16, 12, '兄弟アポロのことですが、兄弟たちと一緒にあなたがたのところに行くように、私は強く勧めました。けれども、彼は今のところ行く意志は全くありません。しかし、良い機会があれば行くでしょう。'),
('JPN', '哥林多前书', 46, 16, 13, '目を覚ましていなさい。堅く信仰に立ちなさい。雄々しく、強くありなさい。'),
('JPN', '哥林多前书', 46, 16, 14, '一切のことを、愛をもって行いなさい。'),
('JPN', '哥林多前书', 46, 16, 15, '兄弟たちよ、あなたがたに勧めます。ご存じのとおり、ステファナの一家はアカイアの初穂であり、聖徒たちのために熱心に奉仕してくれました。'),
('JPN', '哥林多前书', 46, 16, 16, 'あなたがたも、このような人たちに、また、ともに働き、労苦しているすべての人たちに従いなさい。'),
('JPN', '哥林多前书', 46, 16, 17, 'ステファナとポルトナトとアカイコが来たので、私は喜んでいます。あなたがたがいない分を、彼らが埋めてくれたからです。'),
('JPN', '哥林多前书', 46, 16, 18, '彼らは、私の心とあなたがたの心を安らがせてくれました。このような人たちを尊びなさい。'),
('JPN', '哥林多前书', 46, 16, 19, 'アジアの諸教会がよろしくと言っています。アキラとプリスカ、また彼らの家にある教会が、主にあって心から、あなたがたによろしくと言っています。'),
('JPN', '哥林多前书', 46, 16, 20, 'すべての兄弟たちが、あなたがたによろしくと言っています。聖なる口づけをもって互いにあいさつを交わしなさい。'),
('JPN', '哥林多前书', 46, 16, 21, '私パウロが、自分の手であいさつを記します。'),
('JPN', '哥林多前书', 46, 16, 22, '主を愛さない者はみな、のろわれよ。主よ、来てください。'),
('JPN', '哥林多前书', 46, 16, 23, '主イエスの恵みが、あなたがたとともにありますように。'),
('JPN', '哥林多前书', 46, 16, 24, '私の愛が、キリスト・イエスにあって、あなたがたすべてとともにありますように。'),
('JPN', '哥林多后书', 47, 1, 1, '神のみこころによるキリスト・イエスの使徒パウロと、兄弟テモテから、コリントにある神の教会、ならびにアカイア全土にいるすべての聖徒たちへ。'),
('JPN', '哥林多后书', 47, 1, 2, '私たちの父なる神と主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '哥林多后书', 47, 1, 3, '私たちの主イエス・キリストの父である神、あわれみ深い父、あらゆる慰めに満ちた神がほめたたえられますように。'),
('JPN', '哥林多后书', 47, 1, 4, '神は、どのような苦しみのときにも、私たちを慰めてくださいます。それで私たちも、自分たちが神から受ける慰めによって、あらゆる苦しみの中にある人たちを慰めることができます。'),
('JPN', '哥林多后书', 47, 1, 5, '私たちにキリストの苦難があふれているように、キリストによって私たちの慰めもあふれているからです。'),
('JPN', '哥林多后书', 47, 1, 6, '私たちが苦しみにあうとすれば、それはあなたがたの慰めと救いのためです。私たちが慰めを受けるとすれば、それもあなたがたの慰めのためです。その慰めは、私たちが受けているのと同じ苦難に耐え抜く力を、あなたがたに与えてくれます。'),
('JPN', '哥林多后书', 47, 1, 7, '私たちがあなたがたについて抱いている望みは揺るぎません。なぜなら、あなたがたが私たちと苦しみをともにしているように、慰めもともにしていることを、私たちは知っているからです。'),
('JPN', '哥林多后书', 47, 1, 8, '兄弟たち。アジアで起こった私たちの苦難について、あなたがたに知らずにいてほしくありません。私たちは、非常に激しい、耐えられないほどの圧迫を受け、生きる望みさえ失うほどでした。'),
('JPN', '哥林多后书', 47, 1, 9, '実際、私たちは死刑の宣告を受けた思いでした。それは、私たちが自分自身に頼らず、死者をよみがえらせてくださる神に頼る者となるためだったのです。'),
('JPN', '哥林多后书', 47, 1, 10, '神は、それほど大きな死の危険から私たちを救い出してくださいました。これからも救い出してくださいます。私たちはこの神に希望を置いています。'),
('JPN', '哥林多后书', 47, 1, 11, 'あなたがたも祈りによって協力してくれれば、神は私たちを救い出してくださいます。そのようにして、多くの人たちの助けを通して私たちに与えられた恵みについて、多くの人たちが感謝をささげるようになるのです。'),
('JPN', '哥林多后书', 47, 1, 12, '私たちが誇りとすること、私たちの良心が証ししていることは、私たちがこの世において、特にあなたがたに対して、神から来る純真さと誠実さをもって、肉的な知恵によらず、神の恵みによって行動してきたということです。'),
('JPN', '哥林多后书', 47, 1, 13, '私たちは、あなたがたが読んで理解できること以外は何も書いていません。あなたがたは、私たちについてすでにある程度理解しているのですから、私たちの主イエスの日には、あなたがたが私たちの誇りであるように、私たちもあなたがたの誇りであることを、完全に理解してくれるものと期待しています。'),
('JPN', '哥林多后书', 47, 1, 14, '[前節に統合]'),
('JPN', '哥林多后书', 47, 1, 15, 'この確信をもって、私はまずあなたがたのところを訪れて、あなたがたが恵みを二度得られるようにと計画しました。'),
('JPN', '哥林多后书', 47, 1, 16, 'すなわち、あなたがたのところを通ってマケドニアに赴き、そしてマケドニアから再びあなたがたのところに帰り、あなたがたに送られてユダヤに行きたいと思ったのです。'),
('JPN', '哥林多后书', 47, 1, 17, 'このように願った私は軽率だったのでしょうか。それとも、私が計画することは人間的な計画であって、そのため私には、「はい、はい」は同時に「いいえ、いいえ」になるのでしょうか。'),
('JPN', '哥林多后书', 47, 1, 18, '神の真実にかけて言いますが、あなたがたに対する私たちのことばは、「はい」であると同時に「いいえ」である、というようなものではありません。'),
('JPN', '哥林多后书', 47, 1, 19, '私たち、すなわち、私とシルワノとテモテが、あなたがたの間で宣べ伝えた神の子キリスト・イエスは、「はい」と同時に「いいえ」であるような方ではありません。この方においては「はい」だけがあるのです。'),
('JPN', '哥林多后书', 47, 1, 20, '神の約束はことごとく、この方において「はい」となりました。それで私たちは、この方によって「アーメン」と言い、神に栄光を帰するのです。'),
('JPN', '哥林多后书', 47, 1, 21, '私たちをあなたがたと一緒にキリストのうちに堅く保ち、私たちに油を注がれた方は神です。'),
('JPN', '哥林多后书', 47, 1, 22, '神はまた、私たちに証印を押し、保証として御霊を私たちの心に与えてくださいました。'),
('JPN', '哥林多后书', 47, 1, 23, '私は自分のいのちにかけ、神を証人にお呼びして言います。私がまだコリントへ行かないでいるのは、あなたがたへの思いやりからです。'),
('JPN', '哥林多后书', 47, 1, 24, '私たちは、あなたがたの信仰を支配しようとする者ではなく、あなたがたの喜びのために協力して働く者です。あなたがたは信仰に堅く立っているのですから。'),
('JPN', '哥林多后书', 47, 2, 1, 'そこで私は、あなたがたを悲しませる訪問は二度としない、と決心しました。'),
('JPN', '哥林多后书', 47, 2, 2, 'もし私があなたがたを悲しませるなら、私が悲しませているその人以外に、だれが私を喜ばせてくれるでしょう。'),
('JPN', '哥林多后书', 47, 2, 3, 'あの手紙を書いたのは、私が訪れるときに、私に喜びをもたらすはずの人たちから、悲しみを受けることがないようにするためでした。私の喜びがあなたがたすべての喜びであると、私はあなたがたすべてについて確信しています。'),
('JPN', '哥林多后书', 47, 2, 4, '私は大きな苦しみと心の嘆きから、涙ながらにあなたがたに手紙を書きました。それは、あなたがたを悲しませるためではなく、私があなたがたに対して抱いている、あふれるばかりの愛を、あなたがたに知ってもらうためでした。'),
('JPN', '哥林多后书', 47, 2, 5, 'もしある人が悲しみをもたらしたのなら、その人は私を悲しませたのではありません。むしろ、言い過ぎにならないように言えば、ある程度まで、あなたがたすべてを悲しませたのです。'),
('JPN', '哥林多后书', 47, 2, 6, 'その人にとっては、すでに多数の人から受けたあの処罰で十分ですから、'),
('JPN', '哥林多后书', 47, 2, 7, 'あなたがたは、むしろその人を赦し、慰めてあげなさい。そうしないと、その人はあまりにも深い悲しみに押しつぶされてしまうかもしれません。'),
('JPN', '哥林多后书', 47, 2, 8, 'そこで私はあなたがたに、その人へのあなたがたの愛を確認することを勧めます。'),
('JPN', '哥林多后书', 47, 2, 9, '私が手紙を書いたのは、あなたがたがすべてのことにおいて従順であるかどうか、試すためでした。'),
('JPN', '哥林多后书', 47, 2, 10, 'あなたがたが何かのことで人を赦すなら、私もそうします。私が何かのことで赦したとすれば、あなたがたのために、キリストの御前で赦したのです。'),
('JPN', '哥林多后书', 47, 2, 11, 'それは、私たちがサタンに乗じられないようにするためです。私たちはサタンの策略を知らないわけではありません。'),
('JPN', '哥林多后书', 47, 2, 12, '私がキリストの福音を伝えるためにトロアスに行ったとき、主は私のために門を開いておられましたが、'),
('JPN', '哥林多后书', 47, 2, 13, '私は、兄弟テトスに会えなかったので、心に安らぎがありませんでした。それで人々に別れを告げて、マケドニアに向けて出発しました。'),
('JPN', '哥林多后书', 47, 2, 14, 'しかし、神に感謝します。神はいつでも、私たちをキリストによる凱旋の行列に加え、私たちを通してキリストを知る知識の香りを、いたるところで放ってくださいます。'),
('JPN', '哥林多后书', 47, 2, 15, '私たちは、救われる人々の中でも、滅びる人々の中でも、神に献げられた芳しいキリストの香りなのです。'),
('JPN', '哥林多后书', 47, 2, 16, '滅びる人々にとっては、死から出て死に至らせる香りであり、救われる人々にとっては、いのちから出ていのちに至らせる香りです。このような務めにふさわしい人は、いったいだれでしょうか。'),
('JPN', '哥林多后书', 47, 2, 17, '私たちは、多くの人たちのように、神のことばに混ぜ物をして売ったりせず、誠実な者として、また神から遣わされた者として、神の御前でキリストにあって語るのです。'),
('JPN', '哥林多后书', 47, 3, 1, '私たちは、またもや自分を推薦しようとしているのでしょうか。それとも、ある人々のように、あなたがたに宛てた推薦状とか、あなたがたからの推薦状とかが、私たちに必要なのでしょうか。'),
('JPN', '哥林多后书', 47, 3, 2, '私たちの推薦状はあなたがたです。それは私たちの心に書き記されていて、すべての人に知られ、また読まれています。'),
('JPN', '哥林多后书', 47, 3, 3, 'あなたがたが、私たちの奉仕の結果としてのキリストの手紙であることは、明らかです。それは、墨によってではなく生ける神の御霊によって、石の板にではなく人の心の板に書き記されたものです。'),
('JPN', '哥林多后书', 47, 3, 4, '私たちはキリストによって、神の御前でこのような確信を抱いています。'),
('JPN', '哥林多后书', 47, 3, 5, '何かを、自分が成したことだと考える資格は、私たち自身にはありません。私たちの資格は神から与えられるものです。'),
('JPN', '哥林多后书', 47, 3, 6, '神は私たちに、新しい契約に仕える者となる資格を下さいました。文字に仕える者ではなく、御霊に仕える者となる資格です。文字は殺し、御霊は生かすからです。'),
('JPN', '哥林多后书', 47, 3, 7, '石の上に刻まれた文字による、死に仕える務めさえ栄光を帯びたものであり、イスラエルの子らはモーセの顔にあった消え去る栄光のために、モーセの顔を見つめることができないほどでした。そうであれば、'),
('JPN', '哥林多后书', 47, 3, 8, '御霊に仕える務めは、もっと栄光を帯びたものとならないでしょうか。'),
('JPN', '哥林多后书', 47, 3, 9, '罪に定める務めに栄光があるのなら、義とする務めは、なおいっそう栄光に満ちあふれます。'),
('JPN', '哥林多后书', 47, 3, 10, '実にこの点において、かつては栄光を受けたものが、それよりさらにすぐれた栄光のゆえに、栄光のないものになっているのです。'),
('JPN', '哥林多后书', 47, 3, 11, '消え去るべきものが栄光の中にあったのなら、永続するものは、なおのこと栄光に包まれているはずです。'),
('JPN', '哥林多后书', 47, 3, 12, 'このような望みを抱いているので、私たちはきわめて大胆にふるまいます。'),
('JPN', '哥林多后书', 47, 3, 13, 'モーセのようなことはしません。彼は、消え去るものの最後をイスラエルの子らに見せないように、自分の顔に覆いを掛けました。'),
('JPN', '哥林多后书', 47, 3, 14, 'しかし、イスラエルの子らの理解は鈍くなりました。今日に至るまで、古い契約が朗読されるときには、同じ覆いが掛けられたままで、取りのけられていません。それはキリストによって取り除かれるものだからです。'),
('JPN', '哥林多后书', 47, 3, 15, '確かに今日まで、モーセの書が朗読されるときはいつでも、彼らの心には覆いが掛かっています。'),
('JPN', '哥林多后书', 47, 3, 16, 'しかし、人が主に立ち返るなら、いつでもその覆いは除かれます。'),
('JPN', '哥林多后书', 47, 3, 17, '主は御霊です。そして、主の御霊がおられるところには自由があります。'),
('JPN', '哥林多后书', 47, 3, 18, '私たちはみな、覆いを取り除かれた顔に、鏡のように主の栄光を映しつつ、栄光から栄光へと、主と同じかたちに姿を変えられていきます。これはまさに、御霊なる主の働きによるのです。'),
('JPN', '哥林多后书', 47, 4, 1, 'こういうわけで、私たちは、あわれみを受けてこの務めについているので、落胆することがありません。'),
('JPN', '哥林多后书', 47, 4, 2, 'かえって、恥となるような隠し事を捨て、ずる賢い歩みをせず、神のことばを曲げず、真理を明らかにすることで、神の御前で自分自身をすべての人の良心に推薦しています。'),
('JPN', '哥林多后书', 47, 4, 3, 'それでもなお私たちの福音に覆いが掛かっているとしたら、それは、滅び行く人々に対して覆いが掛かっているということです。'),
('JPN', '哥林多后书', 47, 4, 4, '彼らの場合は、この世の神が、信じない者たちの思いを暗くし、神のかたちであるキリストの栄光に関わる福音の光を、輝かせないようにしているのです。'),
('JPN', '哥林多后书', 47, 4, 5, '私たちは自分自身を宣べ伝えているのではなく、主なるイエス・キリストを宣べ伝えています。私たち自身は、イエスのためにあなたがたに仕えるしもべなのです。'),
('JPN', '哥林多后书', 47, 4, 6, '「闇の中から光が輝き出よ」と言われた神が、キリストの御顔にある神の栄光を知る知識を輝かせるために、私たちの心を照らしてくださったのです。'),
('JPN', '哥林多后书', 47, 4, 7, '私たちは、この宝を土の器の中に入れています。それは、この測り知れない力が神のものであって、私たちから出たものではないことが明らかになるためです。'),
('JPN', '哥林多后书', 47, 4, 8, '私たちは四方八方から苦しめられますが、窮することはありません。途方に暮れますが、行き詰まることはありません。'),
('JPN', '哥林多后书', 47, 4, 9, '迫害されますが、見捨てられることはありません。倒されますが、滅びません。'),
('JPN', '哥林多后书', 47, 4, 10, '私たちは、いつもイエスの死を身に帯びています。それはまた、イエスのいのちが私たちの身に現れるためです。'),
('JPN', '哥林多后书', 47, 4, 11, '私たち生きている者は、イエスのために絶えず死に渡されています。それはまた、イエスのいのちが私たちの死ぬべき肉体において現れるためです。'),
('JPN', '哥林多后书', 47, 4, 12, 'こうして、死は私たちのうちに働き、いのちはあなたがたのうちに働いているのです。'),
('JPN', '哥林多后书', 47, 4, 13, '「私は信じています。それゆえに語ります」と書かれているとおり、それと同じ信仰の霊を持っている私たちも、信じているゆえに語ります。'),
('JPN', '哥林多后书', 47, 4, 14, '主イエスをよみがえらせた方が、私たちをもイエスとともによみがえらせ、あなたがたと一緒に御前に立たせてくださることを知っているからです。'),
('JPN', '哥林多后书', 47, 4, 15, 'すべてのことは、あなたがたのためであり、恵みがますます多くの人々に及んで感謝が満ちあふれ、神の栄光が現れるようになるためなのです。'),
('JPN', '哥林多后书', 47, 4, 16, 'ですから、私たちは落胆しません。たとえ私たちの外なる人は衰えても、内なる人は日々新たにされています。'),
('JPN', '哥林多后书', 47, 4, 17, '私たちの一時の軽い苦難は、それとは比べものにならないほど重い永遠の栄光を、私たちにもたらすのです。'),
('JPN', '哥林多后书', 47, 4, 18, '私たちは見えるものにではなく、見えないものに目を留めます。見えるものは一時的であり、見えないものは永遠に続くからです。'),
('JPN', '哥林多后书', 47, 5, 1, 'たとえ私たちの地上の住まいである幕屋が壊れても、私たちには天に、神が下さる建物、人の手によらない永遠の住まいがあることを、私たちは知っています。'),
('JPN', '哥林多后书', 47, 5, 2, '私たちはこの幕屋にあってうめき、天から与えられる住まいを着たいと切望しています。'),
('JPN', '哥林多后书', 47, 5, 3, 'その幕屋を脱いだとしても、私たちは裸の状態でいることはありません。'),
('JPN', '哥林多后书', 47, 5, 4, '確かにこの幕屋のうちにいる間、私たちは重荷を負ってうめいています。それは、この幕屋を脱ぎたいからではありません。死ぬはずのものが、いのちによって吞み込まれるために、天からの住まいを上に着たいからです。'),
('JPN', '哥林多后书', 47, 5, 5, 'そうなるのにふさわしく私たちを整えてくださったのは、神です。神はその保証として御霊を下さいました。'),
('JPN', '哥林多后书', 47, 5, 6, 'ですから、私たちはいつも心強いのです。ただし、肉体を住まいとしている間は、私たちは主から離れているということも知っています。'),
('JPN', '哥林多后书', 47, 5, 7, '私たちは見えるものによらず、信仰によって歩んでいます。'),
('JPN', '哥林多后书', 47, 5, 8, '私たちは心強いのですが、むしろ肉体を離れて、主のみもとに住むほうがよいと思っています。'),
('JPN', '哥林多后书', 47, 5, 9, 'そういうわけで、肉体を住まいとしていても、肉体を離れていても、私たちが心から願うのは、主に喜ばれることです。'),
('JPN', '哥林多后书', 47, 5, 10, '私たちはみな、善であれ悪であれ、それぞれ肉体においてした行いに応じて報いを受けるために、キリストのさばきの座の前に現れなければならないのです。'),
('JPN', '哥林多后书', 47, 5, 11, 'そのため、主を恐れることを知っている私たちは、人々を説得しようとしています。私たちのことは、神の御前に明らかです。しかしそれが、あなたがたの良心にも明らかになることが、私の望みです。'),
('JPN', '哥林多后书', 47, 5, 12, '私たちは、またしてもあなたがたに自分を推薦しているのではありません。むしろ、あなたがたに私たちのことを誇る機会を与え、心ではなくうわべを誇る人たちに応じられるようにしたいのです。'),
('JPN', '哥林多后书', 47, 5, 13, '私たちが正気でないとすれば、それは神のためであり、正気であるとすれば、それはあなたがたのためです。'),
('JPN', '哥林多后书', 47, 5, 14, 'というのは、キリストの愛が私たちを捕らえているからです。私たちはこう考えました。一人の人がすべての人のために死んだ以上、すべての人が死んだのである、と。'),
('JPN', '哥林多后书', 47, 5, 15, 'キリストはすべての人のために死なれました。それは、生きている人々が、もはや自分のためにではなく、自分のために死んでよみがえった方のために生きるためです。'),
('JPN', '哥林多后书', 47, 5, 16, 'ですから、私たちは今後、肉にしたがって人を知ろうとはしません。かつては肉にしたがってキリストを知っていたとしても、今はもうそのような知り方はしません。'),
('JPN', '哥林多后书', 47, 5, 17, 'ですから、だれでもキリストのうちにあるなら、その人は新しく造られた者です。古いものは過ぎ去って、見よ、すべてが新しくなりました。'),
('JPN', '哥林多后书', 47, 5, 18, 'これらのことはすべて、神から出ています。神は、キリストによって私たちをご自分と和解させ、また、和解の務めを私たちに与えてくださいました。'),
('JPN', '哥林多后书', 47, 5, 19, 'すなわち、神はキリストにあって、この世をご自分と和解させ、背きの責任を人々に負わせず、和解のことばを私たちに委ねられました。'),
('JPN', '哥林多后书', 47, 5, 20, 'こういうわけで、神が私たちを通して勧めておられるのですから、私たちはキリストに代わる使節なのです。私たちはキリストに代わって願います。神と和解させていただきなさい。'),
('JPN', '哥林多后书', 47, 5, 21, '神は、罪を知らない方を私たちのために罪とされました。それは、私たちがこの方にあって神の義となるためです。'),
('JPN', '哥林多后书', 47, 6, 1, '私たちは神とともに働く者として、あなたがたに勧めます。神の恵みを無駄に受けないようにしてください。'),
('JPN', '哥林多后书', 47, 6, 2, '神は言われます。「恵みの時に、わたしはあなたに答え、救いの日に、あなたを助ける。」見よ、今は恵みの時、今は救いの日です。'),
('JPN', '哥林多后书', 47, 6, 3, '私たちは、この務めがそしられないように、どんなことにおいても決してつまずきを与えず、'),
('JPN', '哥林多后书', 47, 6, 4, 'むしろ、あらゆることにおいて、自分を神のしもべとして推薦しています。すなわち、苦難にも苦悩にも困難にも、'),
('JPN', '哥林多后书', 47, 6, 5, 'むち打ちにも入獄にも騒乱にも、疲れ果てた時も眠れない時も食べられない時も、大いなる忍耐を働かせて、'),
('JPN', '哥林多后书', 47, 6, 6, 'また、純潔と知識、寛容と親切、聖霊と偽りのない愛、'),
('JPN', '哥林多后书', 47, 6, 7, '真理のことばと神の力により、また左右の手にある義の武器によって、'),
('JPN', '哥林多后书', 47, 6, 8, 'また、ほめられたりそしられたり、悪評を受けたり好評を博したりすることによって、自分を神のしもべとして推薦しているのです。私たちは人をだます者のように見えても、真実であり、'),
('JPN', '哥林多后书', 47, 6, 9, '人に知られていないようでも、よく知られており、死にかけているようでも、見よ、生きており、懲らしめられているようでも、殺されておらず、'),
('JPN', '哥林多后书', 47, 6, 10, '悲しんでいるようでも、いつも喜んでおり、貧しいようでも、多くの人を富ませ、何も持っていないようでも、すべてのものを持っています。'),
('JPN', '哥林多后书', 47, 6, 11, 'コリントの人たち、私たちはあなたがたに対して率直に話しました。私たちの心は広く開かれています。'),
('JPN', '哥林多后书', 47, 6, 12, 'あなたがたに対する私たちの愛の心は、狭くなってはいません。むしろ、あなたがたの思いの中で狭くなっているのです。'),
('JPN', '哥林多后书', 47, 6, 13, '私は子どもたちに語るように言います。私たちと同じように、あなたがたも心を広くしてください。'),
('JPN', '哥林多后书', 47, 6, 14, '不信者と、つり合わないくびきをともにしてはいけません。正義と不法に何の関わりがあるでしょう。光と闇に何の交わりがあるでしょう。'),
('JPN', '哥林多后书', 47, 6, 15, 'キリストとベリアルに何の調和があるでしょう。信者と不信者が何を共有しているでしょう。'),
('JPN', '哥林多后书', 47, 6, 16, '神の宮と偶像に何の一致があるでしょう。私たちは生ける神の宮なのです。神がこう言われるとおりです。「わたしは彼らの間に住み、また歩む。わたしは彼らの神となり、彼らはわたしの民となる。'),
('JPN', '哥林多后书', 47, 6, 17, 'それゆえ、彼らの中から出て行き、彼らから離れよ。──主は言われる──汚れたものに触れてはならない。そうすればわたしは、あなたがたを受け入れ、'),
('JPN', '哥林多后书', 47, 6, 18, 'わたしはあなたがたの父となり、あなたがたはわたしの息子、娘となる。──全能の主は言われる。」'),
('JPN', '哥林多后书', 47, 7, 1, '愛する者たち。このような約束を与えられているのですから、肉と霊の一切の汚れから自分をきよめ、神を恐れつつ聖さを全うしようではありませんか。'),
('JPN', '哥林多后书', 47, 7, 2, '私たちに対して心を開いてください。私たちはだれにも不正をしたことがなく、だれも滅ぼしたことがなく、だれからもだまし取ったことがありません。'),
('JPN', '哥林多后书', 47, 7, 3, '私はあなたがたを責めるために言っているのではありません。前にも言ったように、あなたがたは、私たちとともに死に、ともに生きるために、私たちの心のうちにあるのです。'),
('JPN', '哥林多后书', 47, 7, 4, '私には、あなたがたに対する大きな確信があり、あなたがたについて大きな誇りがあります。私は慰めに満たされ、どんな苦難にあっても喜びに満ちあふれています。'),
('JPN', '哥林多后书', 47, 7, 5, 'マケドニアに着いたとき、私たちの身には全く安らぎがなく、あらゆることで苦しんでいました。外には戦いが、内には恐れがありました。'),
('JPN', '哥林多后书', 47, 7, 6, 'しかし、気落ちした者を慰めてくださる神は、テトスが来たことで私たちを慰めてくださいました。'),
('JPN', '哥林多后书', 47, 7, 7, 'テトスが来たことだけでなく、彼があなたがたから受けた慰めによっても、私たちは慰められました。私を慕うあなたがたの思い、あなたがたの深い悲しみ、私に対する熱意を知らされて、私はますます喜びにあふれました。'),
('JPN', '哥林多后书', 47, 7, 8, 'あの手紙によってあなたがたを悲しませたとしても、私は後悔していません。あの手紙が一時的にでも、あなたがたを悲しませたことを知っています。それで後悔したとしても、'),
('JPN', '哥林多后书', 47, 7, 9, '今は喜んでいます。あなたがたが悲しんだからではなく、悲しんで悔い改めたからです。あなたがたは神のみこころに添って悲しんだので、私たちから何の害も受けなかったのです。'),
('JPN', '哥林多后书', 47, 7, 10, '神のみこころに添った悲しみは、後悔のない、救いに至る悔い改めを生じさせますが、世の悲しみは死をもたらします。'),
('JPN', '哥林多后书', 47, 7, 11, '見なさい。神のみこころに添って悲しむこと、そのことが、あなたがたに、どれほどの熱心をもたらしたことでしょう。そればかりか、どれほどの弁明、憤り、恐れ、慕う思い、熱意、処罰をもたらしたことでしょう。あの問題について、あなたがたは、自分たちがすべての点で潔白であることを証明しました。'),
('JPN', '哥林多后书', 47, 7, 12, 'ですから、私はあなたがたに手紙を書きましたが、それは不正を行った人のためでも、その被害者のためでもなく、私たちに対するあなたがたの熱心が、あなたがたのために神の御前に明らかにされるためだったのです。'),
('JPN', '哥林多后书', 47, 7, 13, 'こういうわけで、私たちは慰めを受けました。この慰めの上にテトスの喜びが加わって、私たちはなおいっそう喜びました。テトスの心が、あなたがたすべてによって安らいでいたからです。'),
('JPN', '哥林多后书', 47, 7, 14, '私はテトスに、あなたがたのことを少しばかり誇りましたが、そのことで恥をかかずにすみました。むしろ、私たちがあなたがたに語ったことがすべて真実であったように、テトスの前で誇ったことも真実となったのです。'),
('JPN', '哥林多后书', 47, 7, 15, 'テトスは、あなたがたがみな従順で、どのように恐れおののきながら自分を迎えてくれたかを思い起こし、あなたがたへの愛情をますます深めています。'),
('JPN', '哥林多后书', 47, 7, 16, '私はすべてのことにおいて、あなたがたに信頼を寄せることができることを喜んでいます。'),
('JPN', '哥林多后书', 47, 8, 1, 'さて、兄弟たち。私たちは、マケドニアの諸教会に与えられた神の恵みを、あなたがたに知らせようと思います。'),
('JPN', '哥林多后书', 47, 8, 2, '彼らの満ちあふれる喜びと極度の貧しさは、苦しみによる激しい試練の中にあってもあふれ出て、惜しみなく施す富となりました。'),
('JPN', '哥林多后书', 47, 8, 3, '私は証しします。彼らは自ら進んで、力に応じて、また力以上に献げ、'),
('JPN', '哥林多后书', 47, 8, 4, '聖徒たちを支える奉仕の恵みにあずかりたいと、大変な熱意をもって私たちに懇願しました。'),
('JPN', '哥林多后书', 47, 8, 5, 'そして、私たちの期待以上に、神のみこころにしたがって、まず自分自身を主に献げ、私たちにも委ねてくれました。'),
('JPN', '哥林多后书', 47, 8, 6, 'それで私たちは、テトスがこの恵みのわざをあなたがたの間で始めたからには、それを成し遂げるようにと、彼に勧めました。'),
('JPN', '哥林多后书', 47, 8, 7, 'あなたがたはすべてのことに、すなわち、信仰にも、ことばにも、知識にも、あらゆる熱心にも、私たちからあなたがたが受けた愛にもあふれています。そのように、この恵みのわざにもあふれるようになってください。'),
('JPN', '哥林多后书', 47, 8, 8, '私は命令として言っているのではありません。ただ、他の人々の熱心さを伝えることで、あなたがたの愛が本物であることを確かめようとしているのです。'),
('JPN', '哥林多后书', 47, 8, 9, 'あなたがたは、私たちの主イエス・キリストの恵みを知っています。すなわち、主は富んでおられたのに、あなたがたのために貧しくなられました。それは、あなたがたが、キリストの貧しさによって富む者となるためです。'),
('JPN', '哥林多后书', 47, 8, 10, 'この献金のことについて、私の意見を述べましょう。それがあなたがたの益になるからです。あなたがたは献金を実行することだけでなく、その志を持つことも、昨年から始めて他に先んじていました。'),
('JPN', '哥林多后书', 47, 8, 11, 'ですから今、それをやり遂げなさい。喜んでしようと思ったとおりに、持っているものでやり遂げてください。'),
('JPN', '哥林多后书', 47, 8, 12, '喜んでする思いがあるなら、持っていないものに応じてではなく、持っているものに応じて受け入れられるのです。'),
('JPN', '哥林多后书', 47, 8, 13, '私は、他の人々には楽をさせ、あなたがたには苦労をさせようとしているのではなく、むしろ平等になるように図っています。'),
('JPN', '哥林多后书', 47, 8, 14, '今あなたがたのゆとりが彼らの不足を補うことは、いずれ彼らのゆとりがあなたがたの不足を補うことになり、そのようにして平等になるのです。'),
('JPN', '哥林多后书', 47, 8, 15, '「たくさん集めた人にも余ることはなく、少しだけ集めた人にも足りないことはなかった」と書いてあるとおりです。'),
('JPN', '哥林多后书', 47, 8, 16, '神に感謝します。私があなたがたのことを思っているのと同じ熱心を、神はテトスの心にも与えてくださいました。'),
('JPN', '哥林多后书', 47, 8, 17, '彼は私の勧めを受け入れ、大変な熱意をもって、自分から進んであなたがたのところに行こうとしています。'),
('JPN', '哥林多后书', 47, 8, 18, '私たちはテトスと一緒に一人の兄弟を送ります。この人は福音の働きによって、すべての教会で称賛されています。'),
('JPN', '哥林多后书', 47, 8, 19, 'そればかりでなく、彼は、この恵みのわざに携わる私たちの同伴者になるようにと、諸教会の任命を受けています。私たちはそのわざに、主ご自身の栄光と私たちの熱意を現すために仕えています。'),
('JPN', '哥林多后书', 47, 8, 20, '私たちは、自分たちが携わっているこの惜しみないわざについて、だれからも非難されることがないように努めています。'),
('JPN', '哥林多后书', 47, 8, 21, '主の御前だけでなく、人々の前でも正しくあるように心がけているのです。'),
('JPN', '哥林多后书', 47, 8, 22, 'また、彼らと一緒にもう一人、私たちの兄弟を送ります。この兄弟が多くのことについて熱心であることを、私たちは何度も認めることができました。彼は今、あなたがたに深い信頼を寄せ、ますます熱心になっています。'),
('JPN', '哥林多后书', 47, 8, 23, 'テトスについて言えば、彼は私の仲間であり、あなたがたのために働く同労者です。私たちの兄弟たちについて言えば、彼らは諸教会の使者であり、キリストの栄光です。'),
('JPN', '哥林多后书', 47, 8, 24, 'ですから、あなたがたの愛の証拠と、あなたがたを私たちが誇りとしている理由を、彼らに対して、諸教会の前に示してほしいのです。'),
('JPN', '哥林多后书', 47, 9, 1, '聖徒たちのためのこの奉仕については、これ以上書く必要はありません。'),
('JPN', '哥林多后书', 47, 9, 2, '私はあなたがたの熱意を知り、そのことでマケドニアの人々にあなたがたのことを誇って、アカイアでは昨年から準備ができていると言ったのです。あなたがたの熱心は多くの人を奮い立たせました。'),
('JPN', '哥林多后书', 47, 9, 3, '私が兄弟たちを送るのは、あなたがたについての私たちの誇りが、この点で空しくならないためであり、私が言っていたとおりに準備していてもらうためです。'),
('JPN', '哥林多后书', 47, 9, 4, 'そうでないと、もしマケドニアの人々が私と一緒に行って、準備ができていないのを見たら、あなたがたはもちろんですが、私たちも、このことを確信していただけに、恥をかくことになるでしょう。'),
('JPN', '哥林多后书', 47, 9, 5, 'そこで私は、兄弟たちに頼んで先にそちらに行ってもらい、あなたがたが以前に約束していた祝福の贈り物を、あらかじめ用意しておいてもらうことが必要だと思いました。惜しみながらするのではなく、祝福の贈り物として用意してもらうためです。'),
('JPN', '哥林多后书', 47, 9, 6, '私が伝えたいことは、こうです。わずかだけ蒔く者はわずかだけ刈り入れ、豊かに蒔く者は豊かに刈り入れます。'),
('JPN', '哥林多后书', 47, 9, 7, '一人ひとり、いやいやながらでなく、強いられてでもなく、心で決めたとおりにしなさい。神は、喜んで与える人を愛してくださるのです。'),
('JPN', '哥林多后书', 47, 9, 8, '神はあなたがたに、あらゆる恵みをあふれるばかりに与えることがおできになります。あなたがたが、いつもすべてのことに満ち足りて、すべての良いわざにあふれるようになるためです。'),
('JPN', '哥林多后书', 47, 9, 9, '「彼は貧しい人々に惜しみなく分け与えた。彼の義は永遠にとどまる」と書かれているようにです。'),
('JPN', '哥林多后书', 47, 9, 10, '種蒔く人に種と食べるためのパンを与えてくださる方は、あなたがたの種を備え、増やし、あなたがたの義の実を増し加えてくださいます。'),
('JPN', '哥林多后书', 47, 9, 11, 'あなたがたは、あらゆる点で豊かになって、すべてを惜しみなく与えるようになり、それが私たちを通して神への感謝を生み出すのです。'),
('JPN', '哥林多后书', 47, 9, 12, 'なぜなら、この奉仕の務めは、聖徒たちの欠乏を満たすだけではなく、神に対する多くの感謝を通してますます豊かになるからです。'),
('JPN', '哥林多后书', 47, 9, 13, 'この務めが証拠となって、彼らは、あなたがたがキリストの福音の告白に対して従順であり、自分たちや、すべての人に惜しみなく与えていることを理解して、神をあがめるでしょう。'),
('JPN', '哥林多后书', 47, 9, 14, 'そして彼らは、あなたがたのために祈るとき、あなたがたに与えられた、神のこの上なく豊かな恵みのゆえに、あなたがたを慕うようになります。'),
('JPN', '哥林多后书', 47, 9, 15, 'ことばに表せないほどの賜物のゆえに、神に感謝します。'),
('JPN', '哥林多后书', 47, 10, 1, 'さて、あなたがたの間にいて顔を合わせているときはおとなしいのに、離れているとあなたがたに対して強気になる私パウロ自身が、キリストの柔和さと優しさをもってあなたがたにお願いします。'),
('JPN', '哥林多后书', 47, 10, 2, '私たちが肉に従って歩んでいると見なす人たちに対しては、大胆にふるまうべきだと私は考えていますが、そちらに行ったときに、その確信から強気にふるまわないですむように願います。'),
('JPN', '哥林多后书', 47, 10, 3, '私たちは肉にあって歩んではいても、肉に従って戦ってはいません。'),
('JPN', '哥林多后书', 47, 10, 4, '私たちの戦いの武器は肉のものではなく、神のために要塞を打ち倒す力があるものです。'),
('JPN', '哥林多后书', 47, 10, 5, '私たちは様々な議論と、神の知識に逆らって立つあらゆる高ぶりを打ち倒し、また、すべてのはかりごとを取り押さえて、キリストに服従させます。'),
('JPN', '哥林多后书', 47, 10, 6, 'また、あなたがたの従順が完全になったとき、あらゆる不従順を罰する用意ができています。'),
('JPN', '哥林多后书', 47, 10, 7, 'あなたがたは、うわべのことだけを見ています。もし自分はキリストに属する者だと確信している人がいるなら、その人は、自分がキリストに属しているように、私たちもキリストに属しているということを、もう一度よく考えなさい。'),
('JPN', '哥林多后书', 47, 10, 8, 'あなたがたを倒すためにではなく、建てるために主が私たちに与えてくださった権威について、私が多少誇り過ぎることがあっても、恥とはならないでしょう。'),
('JPN', '哥林多后书', 47, 10, 9, '私は、手紙であなたがたを脅しているかのように思われたくありません。'),
('JPN', '哥林多后书', 47, 10, 10, '「パウロの手紙は重みがあって力強いが、実際に会ってみると弱々しく、話は大したことはない」と言う人たちがいるからです。'),
('JPN', '哥林多后书', 47, 10, 11, 'そのような人は承知していなさい。私たちは、離れて書く手紙のことばどおりの者として、そちらに行ってもふるまいます。'),
('JPN', '哥林多后书', 47, 10, 12, '私たちは、自分自身を推薦している人たちの中のだれかと、自分を同列に置いたり比較したりしようとは思いません。彼らは自分たちの間で自分自身を量ったり、互いを比較し合ったりしていますが、愚かなことです。'),
('JPN', '哥林多后书', 47, 10, 13, '私たちは限度を超えて誇りません。神が私たちに割り当ててくださった限度の内で、あなたがたのところにまで行ったことについて、私たちは誇るのです。'),
('JPN', '哥林多后书', 47, 10, 14, '私たちは、あなたがたのところに行かなかったかのようにして、無理に手を伸ばしているのではありません。事実、私たちは他の人たちに先んじて、あなたがたのところにキリストの福音を携えて行ったのです。'),
('JPN', '哥林多后书', 47, 10, 15, '私たちは、自分の限度を超えてほかの人の労苦を誇ることはしません。ただ、あなたがたの信仰が成長し、あなたがたの間で私たちの働きが、定められた範囲の内で拡大し、あふれるほどになることを望んでいます。'),
('JPN', '哥林多后书', 47, 10, 16, 'それは、あなたがたより向こうの地域にまで福音を宣べ伝えるためであって、決して、ほかの人の領域ですでになされた働きを誇るためではありません。'),
('JPN', '哥林多后书', 47, 10, 17, '「誇る者は主を誇れ。」'),
('JPN', '哥林多后书', 47, 10, 18, '自分自身を推薦する人ではなく、主に推薦される人こそ本物です。'),
('JPN', '哥林多后书', 47, 11, 1, '私の少しばかりの愚かさを我慢してほしいと思います。いや、あなたがたは我慢しています。'),
('JPN', '哥林多后书', 47, 11, 2, '私は神の熱心をもって、あなたがたのことを熱心に思っています。私はあなたがたを清純な処女として、一人の夫キリストに献げるために婚約させたのですから。'),
('JPN', '哥林多后书', 47, 11, 3, '蛇が悪巧みによってエバを欺いたように、あなたがたの思いが汚されて、キリストに対する真心と純潔から離れてしまうのではないかと、私は心配しています。'),
('JPN', '哥林多后书', 47, 11, 4, '実際、だれかが来て、私たちが宣べ伝えなかった別のイエスを宣べ伝えたり、あるいは、あなたがたが受けたことのない異なる霊や、受け入れたことのない異なる福音を受けたりしても、あなたがたはよく我慢しています。'),
('JPN', '哥林多后书', 47, 11, 5, '私は、自分があの大使徒たちに少しも劣っていないと思います。'),
('JPN', '哥林多后书', 47, 11, 6, '話し方は素人でも、知識においてはそうではありません。私たちはすべての点で、あらゆる場合に、そのことをあなたがたに示してきました。'),
('JPN', '哥林多后书', 47, 11, 7, 'それとも、あなたがたを高めるために自分を低くして、報酬を受けずに神の福音をあなたがたに宣べ伝えたことで、私は罪を犯したのでしょうか。'),
('JPN', '哥林多后书', 47, 11, 8, '私は他の諸教会から奪い取って、あなたがたに仕えるための給料を得たのです。'),
('JPN', '哥林多后书', 47, 11, 9, 'あなたがたのところにいて困窮していたときも、私はだれにも負担をかけませんでした。マケドニアから来た兄弟たちが、私の欠乏を十分に補ってくれたからです。私は、何であれ、あなたがたの重荷にならないようにしましたし、今後もそうするつもりです。'),
('JPN', '哥林多后书', 47, 11, 10, '私のうちにある、キリストの真実にかけて言います。アカイア地方で私のこの誇りが封じられることはありません。'),
('JPN', '哥林多后书', 47, 11, 11, 'なぜでしょう。私があなたがたを愛していないからでしょうか。神はご存じです。'),
('JPN', '哥林多后书', 47, 11, 12, '私は、今していることを今後も続けるつもりです。それは、ある人たちが自分たちで誇りとしていることについて、私たちと同じだと認められる機会を求めているのを断ち切るためです。'),
('JPN', '哥林多后书', 47, 11, 13, 'こういう者たちは偽使徒、人を欺く働き人であり、キリストの使徒に変装しているのです。'),
('JPN', '哥林多后书', 47, 11, 14, 'しかし、驚くには及びません。サタンでさえ光の御使いに変装します。'),
('JPN', '哥林多后书', 47, 11, 15, 'ですから、サタンのしもべどもが義のしもべに変装したとしても、大したことではありません。彼らの最後は、その行いにふさわしいものとなるでしょう。'),
('JPN', '哥林多后书', 47, 11, 16, 'もう一度言いますが、だれも私を愚かだと思わないでください。もし愚かだと思うなら、愚か者として受け入れてください。そうすれば、私も少しばかり誇ることができます。'),
('JPN', '哥林多后书', 47, 11, 17, 'これから話すことは、主によって話すのではなく、愚か者として、自慢できると確信して話します。'),
('JPN', '哥林多后书', 47, 11, 18, '多くの人が肉によって誇っているので、私も誇ることにします。'),
('JPN', '哥林多后书', 47, 11, 19, 'あなたがたは賢いので、喜んで愚か者たちを我慢してくれるからです。'),
('JPN', '哥林多后书', 47, 11, 20, '実際あなたがたは、だれかに奴隷にされても、食い尽くされても、強奪されても、いばられても、顔をたたかれても、我慢しています。'),
('JPN', '哥林多后书', 47, 11, 21, '言うのも恥ずかしいことですが、私たちは弱かったのです。何であれ、だれかがあえて誇るのなら、私は愚かになって言いますが、私もあえて誇りましょう。'),
('JPN', '哥林多后书', 47, 11, 22, '彼らはヘブル人ですか。私もそうです。彼らはイスラエル人ですか。私もそうです。彼らはアブラハムの子孫ですか。私もそうです。'),
('JPN', '哥林多后书', 47, 11, 23, '彼らはキリストのしもべですか。私は狂気したように言いますが、私は彼ら以上にそうです。労苦したことはずっと多く、牢に入れられたこともずっと多く、むち打たれたことははるかに多く、死に直面したこともたびたびありました。'),
('JPN', '哥林多后书', 47, 11, 24, 'ユダヤ人から四十に一つ足りないむちを受けたことが五度、'),
('JPN', '哥林多后书', 47, 11, 25, 'ローマ人にむちで打たれたことが三度、石で打たれたことが一度、難船したことが三度、一昼夜、海上を漂ったこともあります。'),
('JPN', '哥林多后书', 47, 11, 26, '何度も旅をし、川の難、盗賊の難、同胞から受ける難、異邦人から受ける難、町での難、荒野での難、海上の難、偽兄弟による難にあい、'),
('JPN', '哥林多后书', 47, 11, 27, '労し苦しみ、たびたび眠らずに過ごし、飢え渇き、しばしば食べ物もなく、寒さの中に裸でいたこともありました。'),
('JPN', '哥林多后书', 47, 11, 28, 'ほかにもいろいろなことがありますが、さらに、日々私に重荷となっている、すべての教会への心づかいがあります。'),
('JPN', '哥林多后书', 47, 11, 29, 'だれかが弱くなっているときに、私は弱くならないでしょうか。だれかがつまずいていて、私は心が激しく痛まないでしょうか。'),
('JPN', '哥林多后书', 47, 11, 30, 'もし誇る必要があるなら、私は自分の弱さのことを誇ります。'),
('JPN', '哥林多后书', 47, 11, 31, '主イエスの父である神、とこしえにほめたたえられる方は、私が偽りを言っていないことをご存じです。'),
('JPN', '哥林多后书', 47, 11, 32, 'ダマスコでアレタ王の代官が、私を捕らえようとしてダマスコの人たちの町を見張りましたが、'),
('JPN', '哥林多后书', 47, 11, 33, '私は窓からかごで城壁伝いにつり降ろされ、彼の手を逃れたのでした。'),
('JPN', '哥林多后书', 47, 12, 1, '私は誇らずにはいられません。誇っても無益ですが、主の幻と啓示の話に入りましょう。'),
('JPN', '哥林多后书', 47, 12, 2, '私はキリストにある一人の人を知っています。この人は十四年前に、第三の天にまで引き上げられました。肉体のままであったのか、私は知りません。肉体を離れてであったのか、それも知りません。神がご存じです。'),
('JPN', '哥林多后书', 47, 12, 3, '私はこのような人を知っています。肉体のままであったのか、肉体を離れてであったのか、私は知りません。神がご存じです。'),
('JPN', '哥林多后书', 47, 12, 4, '彼はパラダイスに引き上げられて、言い表すこともできない、人間が語ることを許されていないことばを聞きました。'),
('JPN', '哥林多后书', 47, 12, 5, 'このような人のことを私は誇ります。しかし、私自身については、弱さ以外は誇りません。'),
('JPN', '哥林多后书', 47, 12, 6, 'たとえ私が誇りたいと思ったとしても、愚か者とはならないでしょう。本当のことを語るからです。しかし、その啓示があまりにもすばらしいために、私について見ること、私から聞くこと以上に、だれかが私を過大に評価するといけないので、私は誇ることを控えましょう。'),
('JPN', '哥林多后书', 47, 12, 7, 'その啓示のすばらしさのため高慢にならないように、私は肉体に一つのとげを与えられました。それは私が高慢にならないように、私を打つためのサタンの使いです。'),
('JPN', '哥林多后书', 47, 12, 8, 'この使いについて、私から去らせてくださるようにと、私は三度、主に願いました。'),
('JPN', '哥林多后书', 47, 12, 9, 'しかし主は、「わたしの恵みはあなたに十分である。わたしの力は弱さのうちに完全に現れるからである」と言われました。ですから私は、キリストの力が私をおおうために、むしろ大いに喜んで自分の弱さを誇りましょう。'),
('JPN', '哥林多后书', 47, 12, 10, 'ですから私は、キリストのゆえに、弱さ、侮辱、苦悩、迫害、困難を喜んでいます。というのは、私が弱いときにこそ、私は強いからです。'),
('JPN', '哥林多后书', 47, 12, 11, '私は愚か者になってしまいました。あなたがたが無理に私をそうさせたのです。私は当然、あなたがたの推薦を受けてよかったはずです。私は、たとえ取るに足りない者であっても、あの大使徒たちに少しも劣るところはなかったのですから。'),
('JPN', '哥林多后书', 47, 12, 12, '私は忍耐を尽くして、あなたがたの間で使徒としてのしるしを明らかにしました。しるしと不思議と力あるわざによってです。'),
('JPN', '哥林多后书', 47, 12, 13, 'あなたがたが他の諸教会より劣っている点は何でしょうか。この私が、あなたがたに負担をかけなかったことだけではありませんか。この不正のことは赦してください。'),
('JPN', '哥林多后书', 47, 12, 14, '見なさい。私は、あなたがたのところに三度目の訪問をする準備ができていますが、あなたがたに負担はかけません。私が求めているのは、あなたがたが持っている物ではなく、あなたがた自身なのです。子が親のために蓄える必要はなく、親が子のために蓄えるべきです。'),
('JPN', '哥林多后书', 47, 12, 15, '私は、あなたがたのたましいのために、大いに喜んで財を費やし、自分自身を使い尽くしましょう。私があなたがたを愛すれば愛するほど、私はますます愛されなくなるのでしょうか。'),
('JPN', '哥林多后书', 47, 12, 16, 'それならそれでよいとして、私はあなたがたに重荷を負わせませんでした。それでも私は、悪賢くて、あなたがたからだまし取ったと言われます。'),
('JPN', '哥林多后书', 47, 12, 17, '私はあなたがたのところに人を遣わしましたが、そのうちのだれかによって、あなたがたをだますことがあったでしょうか。'),
('JPN', '哥林多后书', 47, 12, 18, '私はテトスにそちらに行くように頼み、あの兄弟もともに遣わしました。テトスはあなたがたをだましたでしょうか。私たちは同じ心で歩んだではありませんか。同じ足跡をたどったではありませんか。'),
('JPN', '哥林多后书', 47, 12, 19, 'あなたがたは、私たちがあなたがたに対して自己弁護をしているのだと、前からずっと思っていましたか。私たちは神の御前で、キリストにあって語っているのです。愛する者たち、すべてはあなたがたが成長するためなのです。'),
('JPN', '哥林多后书', 47, 12, 20, '私は心配をしています。そちらに行ってみると、あなたがたは私が期待したような人たちでなく、私もあなたがたが期待したような者でなかった、ということにならないでしょうか。争い、ねたみ、憤り、党派心、悪口、陰口、高ぶり、混乱がありはしないでしょうか。'),
('JPN', '哥林多后书', 47, 12, 21, '私が再びそちらに行くとき、私の神があなたがたの前で、私を恥じ入らせるのではないでしょうか。そして、以前に罪を犯していながら、犯した汚れと淫らな行いと好色を悔い改めない多くの人たちのことを、私は嘆くことにならないでしょうか。'),
('JPN', '哥林多后书', 47, 13, 1, '私があなたがたのところに行くのは、これで三度目です。二人または三人の証人の証言によって、すべてのことは立証されなければなりません。'),
('JPN', '哥林多后书', 47, 13, 2, '以前に罪を犯した人たちとほかの人たち全員に、私は二度目の滞在のとき、前もって言っておきましたが、こうして離れている今も、あらかじめ言っておきます。今度そちらに行ったときには、容赦しません。'),
('JPN', '哥林多后书', 47, 13, 3, 'こう言うのは、キリストが私によって語っておられるという証拠を、あなたがたが求めているからです。キリストはあなたがたに対して弱い方ではなく、あなたがたの間にあって力ある方です。'),
('JPN', '哥林多后书', 47, 13, 4, 'キリストは弱さのゆえに十字架につけられましたが、神の力によって生きておられます。私たちもキリストにあって弱い者ですが、あなたがたに対しては、神の力によってキリストとともに生きるのです。'),
('JPN', '哥林多后书', 47, 13, 5, 'あなたがたは、信仰に生きているかどうか、自分自身を試し、吟味しなさい。それとも、あなたがたは自分自身のことを、自分のうちにイエス・キリストがおられることを、自覚していないのですか。あなたがたが不適格な者なら別ですが。'),
('JPN', '哥林多后书', 47, 13, 6, 'しかし、私たちは不適格でないことが、あなたがたに分かるように、私は望んでいます。'),
('JPN', '哥林多后书', 47, 13, 7, '私たちは、あなたがたがどんな悪も行うことのないように、神に祈っています。それは、私たちが適格であることを明らかにしたいからではなく、私たちが不適格な者のように見えたとしても、あなたがたに善を行ってもらいたいからです。'),
('JPN', '哥林多后书', 47, 13, 8, '私たちは、真理に逆らっては何もすることができませんが、真理のためならできます。'),
('JPN', '哥林多后书', 47, 13, 9, '私たちは、自分は弱くても、あなたがたが強ければ喜びます。あなたがたが完全な者になること、このことも私たちは祈っています。'),
('JPN', '哥林多后书', 47, 13, 10, 'そういうわけで、離れていてこれらのことを書いているのは、私が行ったときに、主が私に授けてくださった権威を用いて、厳しい処置をとらなくてもすむようになるためです。この権威が私に与えられたのは、建てるためであって、倒すためではありません。'),
('JPN', '哥林多后书', 47, 13, 11, '最後に兄弟たち、喜びなさい。完全になりなさい。慰めを受けなさい。思いを一つにしなさい。平和を保ちなさい。そうすれば、愛と平和の神はあなたがたとともにいてくださいます。'),
('JPN', '哥林多后书', 47, 13, 12, '聖なる口づけをもって互いにあいさつを交わしなさい。すべての聖徒たちが、あなたがたによろしくと言っています。'),
('JPN', '哥林多后书', 47, 13, 13, '主イエス・キリストの恵み、神の愛、聖霊の交わりが、あなたがたすべてとともにありますように。'),
('JPN', '加拉太书', 48, 1, 1, '人々から出たのではなく、人間を通してでもなく、イエス・キリストと、キリストを死者の中からよみがえらせた父なる神によって、使徒とされたパウロと、'),
('JPN', '加拉太书', 48, 1, 2, '私とともにいるすべての兄弟たちから、ガラテヤの諸教会へ。'),
('JPN', '加拉太书', 48, 1, 3, '私たちの父なる神と主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '加拉太书', 48, 1, 4, 'キリストは、今の悪の時代から私たちを救い出すために、私たちの罪のためにご自分を与えてくださいました。私たちの父である神のみこころにしたがったのです。'),
('JPN', '加拉太书', 48, 1, 5, 'この神に、栄光が世々限りなくありますように。アーメン。'),
('JPN', '加拉太书', 48, 1, 6, '私は驚いています。あなたがたが、キリストの恵みによって自分たちを召してくださった方から、このように急に離れて、ほかの福音に移って行くことに。'),
('JPN', '加拉太书', 48, 1, 7, 'ほかの福音といっても、もう一つ別に福音があるわけではありません。あなたがたを動揺させて、キリストの福音を変えてしまおうとする者たちがいるだけです。'),
('JPN', '加拉太书', 48, 1, 8, 'しかし、私たちであれ天の御使いであれ、もし私たちがあなたがたに宣べ伝えた福音に反することを、福音として宣べ伝えるなら、そのような者はのろわれるべきです。'),
('JPN', '加拉太书', 48, 1, 9, '私たちが以前にも言ったように、今もう一度、私は言います。もしだれかが、あなたがたが受けた福音に反する福音をあなたがたに宣べ伝えているなら、そのような者はのろわれるべきです。'),
('JPN', '加拉太书', 48, 1, 10, '今、私は人々に取り入ろうとしているのでしょうか。神に取り入ろうとしているのでしょうか。あるいは、人々を喜ばせようと努めているのでしょうか。もし今なお人々を喜ばせようとしているのなら、私はキリストのしもべではありません。'),
('JPN', '加拉太书', 48, 1, 11, '兄弟たち、私はあなたがたに明らかにしておきたいのです。私が宣べ伝えた福音は、人間によるものではありません。'),
('JPN', '加拉太书', 48, 1, 12, '私はそれを人間から受けたのではなく、また教えられたのでもありません。ただイエス・キリストの啓示によって受けたのです。'),
('JPN', '加拉太书', 48, 1, 13, 'ユダヤ教のうちにあった、かつての私の生き方を、あなたがたはすでに聞いています。私は激しく神の教会を迫害し、それを滅ぼそうとしました。'),
('JPN', '加拉太书', 48, 1, 14, 'また私は、自分の同胞で同じ世代の多くの人に比べ、はるかにユダヤ教に進んでおり、先祖の伝承に人一倍熱心でした。'),
('JPN', '加拉太书', 48, 1, 15, 'しかし、母の胎にあるときから私を選び出し、恵みをもって召してくださった神が、'),
('JPN', '加拉太书', 48, 1, 16, '異邦人の間に御子の福音を伝えるため、御子を私のうちに啓示することを良しとされたとき、私は血肉に相談することをせず、'),
('JPN', '加拉太书', 48, 1, 17, '私より先に使徒となった人たちに会うためにエルサレムに上ることもせず、すぐにアラビアに出て行き、再びダマスコに戻りました。'),
('JPN', '加拉太书', 48, 1, 18, 'それから三年後に、私はケファを訪ねてエルサレムに上り、彼のもとに十五日間滞在しました。'),
('JPN', '加拉太书', 48, 1, 19, 'しかし、主の兄弟ヤコブは別として、ほかの使徒たちにはだれにも会いませんでした。'),
('JPN', '加拉太书', 48, 1, 20, '神の御前で言いますが、私があなたがたに書いていることに偽りはありません。'),
('JPN', '加拉太书', 48, 1, 21, 'それから、私はシリアおよびキリキアの地方に行きました。'),
('JPN', '加拉太书', 48, 1, 22, 'それで私は、キリストにあるユダヤの諸教会には顔を知られることはありませんでした。'),
('JPN', '加拉太书', 48, 1, 23, 'ただ、人々は、「以前私たちを迫害した者が、そのとき滅ぼそうとした信仰を今は宣べ伝えている」と聞いて、'),
('JPN', '加拉太书', 48, 1, 24, '私のことで神をあがめていました。'),
('JPN', '加拉太书', 48, 2, 1, 'それから十四年たって、私はバルナバと一緒に、テトスも連れて、再びエルサレムに上りました。'),
('JPN', '加拉太书', 48, 2, 2, '私は啓示によって上ったのです。そして、私が今走っていること、また今まで走ってきたことが無駄にならないように、異邦人の間で私が伝えている福音を人々に示しました。おもだった人たちには個人的にそうしました。'),
('JPN', '加拉太书', 48, 2, 3, 'しかし、私と一緒にいたテトスでさえ、ギリシア人であったのに、割礼を強いられませんでした。'),
('JPN', '加拉太书', 48, 2, 4, '忍び込んだ偽兄弟たちがいたのに、強いられるということはありませんでした。彼らは私たちを奴隷にしようとして、キリスト・イエスにあって私たちが持っている自由を狙って、忍び込んでいたのです。'),
('JPN', '加拉太书', 48, 2, 5, '私たちは、一時も彼らに譲歩したり屈服したりすることはありませんでした。それは、福音の真理があなたがたのもとで保たれるためでした。'),
('JPN', '加拉太书', 48, 2, 6, 'そして、おもだった人たちからは──彼らがどれほどの者であっても、私にとって問題ではありません。神は人を分け隔てなさいません──そのおもだった人たちは、私に対して何もつけ加えはしませんでした。'),
('JPN', '加拉太书', 48, 2, 7, 'それどころか、ペテロが割礼を受けている者への福音を委ねられているように、私は割礼を受けていない者への福音を委ねられていることを理解してくれました。'),
('JPN', '加拉太书', 48, 2, 8, 'ペテロに働きかけて、割礼を受けている者への使徒とされた方が、私にも働きかけて、異邦人への使徒としてくださったからでした。'),
('JPN', '加拉太书', 48, 2, 9, 'そして、私に与えられたこの恵みを認め、柱として重んじられているヤコブとケファとヨハネが、私とバルナバに、交わりのしるしとして右手を差し出しました。それは、私たちが異邦人のところに行き、彼らが割礼を受けている人々のところに行くためでした。'),
('JPN', '加拉太书', 48, 2, 10, 'ただ、私たちが貧しい人たちのことを心に留めるようにとのことでしたが、そのことなら私も大いに努めてきました。'),
('JPN', '加拉太书', 48, 2, 11, 'ところが、ケファがアンティオキアに来たとき、彼に非難すべきことがあったので、私は面と向かって抗議しました。'),
('JPN', '加拉太书', 48, 2, 12, 'ケファは、ある人たちがヤコブのところから来る前は、異邦人と一緒に食事をしていたのに、その人たちが来ると、割礼派の人々を恐れて異邦人から身を引き、離れて行ったからです。'),
('JPN', '加拉太书', 48, 2, 13, 'そして、ほかのユダヤ人たちも彼と一緒に本心を偽った行動をとり、バルナバまで、その偽りの行動に引き込まれてしまいました。'),
('JPN', '加拉太书', 48, 2, 14, '彼らが福音の真理に向かってまっすぐに歩んでいないのを見て、私は皆の面前でケファにこう言いました。「あなた自身、ユダヤ人でありながら、ユダヤ人ではなく異邦人のように生活しているのならば、どうして異邦人に、ユダヤ人のように生活することを強いるのですか。」'),
('JPN', '加拉太书', 48, 2, 15, '私たちは、生まれながらのユダヤ人であって、「異邦人のような罪人」ではありません。'),
('JPN', '加拉太书', 48, 2, 16, 'しかし、人は律法を行うことによってではなく、ただイエス・キリストを信じることによって義と認められると知って、私たちもキリスト・イエスを信じました。律法を行うことによってではなく、キリストを信じることによって義と認められるためです。というのは、肉なる者はだれも、律法を行うことによっては義と認められないからです。'),
('JPN', '加拉太书', 48, 2, 17, 'しかし、もし、私たちがキリストにあって義と認められようとすることで、私たち自身も「罪人」であることになるのなら、キリストは罪に仕える者なのですか。決してそんなことはありません。'),
('JPN', '加拉太书', 48, 2, 18, 'もし自分が打ち壊したものを再び建てるなら、私は自分が違反者であると証明することになるのです。'),
('JPN', '加拉太书', 48, 2, 19, 'しかし私は、神に生きるために、律法によって律法に死にました。私はキリストとともに十字架につけられました。'),
('JPN', '加拉太书', 48, 2, 20, 'もはや私が生きているのではなく、キリストが私のうちに生きておられるのです。今私が肉において生きているいのちは、私を愛し、私のためにご自分を与えてくださった、神の御子に対する信仰によるのです。'),
('JPN', '加拉太书', 48, 2, 21, '私は神の恵みを無にはしません。もし義が律法によって得られるとしたら、それこそ、キリストの死は無意味になってしまいます。'),
('JPN', '加拉太书', 48, 3, 1, 'ああ、愚かなガラテヤ人。十字架につけられたイエス・キリストが、目の前に描き出されたというのに、だれがあなたがたを惑わしたのですか。'),
('JPN', '加拉太书', 48, 3, 2, 'これだけは、あなたがたに聞いておきたい。あなたがたが御霊を受けたのは、律法を行ったからですか。それとも信仰をもって聞いたからですか。'),
('JPN', '加拉太书', 48, 3, 3, 'あなたがたはそんなにも愚かなのですか。御霊によって始まったあなたがたが、今、肉によって完成されるというのですか。'),
('JPN', '加拉太书', 48, 3, 4, 'あれほどの経験をしたのは、無駄だったのでしょうか。まさか、無駄だったということはないでしょう。'),
('JPN', '加拉太书', 48, 3, 5, 'あなたがたに御霊を与え、あなたがたの間で力あるわざを行われる方は、あなたがたが律法を行ったから、そうなさるのでしょうか。それとも信仰をもって聞いたから、そうなさるのでしょうか。'),
('JPN', '加拉太书', 48, 3, 6, '「アブラハムは神を信じた。それで、それが彼の義と認められた」とあるとおりです。'),
('JPN', '加拉太书', 48, 3, 7, 'ですから、信仰によって生きる人々こそアブラハムの子である、と知りなさい。'),
('JPN', '加拉太书', 48, 3, 8, '聖書は、神が異邦人を信仰によって義とお認めになることを前から知っていたので、アブラハムに対して、「すべての異邦人が、あなたによって祝福される」と、前もって福音を告げました。'),
('JPN', '加拉太书', 48, 3, 9, 'ですから、信仰によって生きる人々が、信仰の人アブラハムとともに祝福を受けるのです。'),
('JPN', '加拉太书', 48, 3, 10, '律法の行いによる人々はみな、のろいのもとにあります。「律法の書に書いてあるすべてのことを守り行わない者はみな、のろわれる」と書いてあるからです。'),
('JPN', '加拉太书', 48, 3, 11, '律法によって神の前に義と認められる者が、だれもいないということは明らかです。「義人は信仰によって生きる」からです。'),
('JPN', '加拉太书', 48, 3, 12, '律法は、「信仰による」のではありません。「律法の掟を行う人は、その掟によって生きる」のです。'),
('JPN', '加拉太书', 48, 3, 13, 'キリストは、ご自分が私たちのためにのろわれた者となることで、私たちを律法ののろいから贖い出してくださいました。「木にかけられた者はみな、のろわれている」と書いてあるからです。'),
('JPN', '加拉太书', 48, 3, 14, 'それは、アブラハムへの祝福がキリスト・イエスによって異邦人に及び、私たちが信仰によって約束の御霊を受けるようになるためでした。'),
('JPN', '加拉太书', 48, 3, 15, '兄弟たちよ、人間の例で説明しましょう。人間の契約でも、いったん結ばれたら、だれもそれを無効にしたり、それにつけ加えたりはしません。'),
('JPN', '加拉太书', 48, 3, 16, '約束は、アブラハムとその子孫に告げられました。神は、「子孫たちに」と言って多数を指すことなく、一人を指して「あなたの子孫に」と言っておられます。それはキリストのことです。'),
('JPN', '加拉太书', 48, 3, 17, '私の言おうとしていることは、こうです。先に神によって結ばれた契約を、その後四百三十年たってできた律法が無効にし、その約束を破棄することはありません。'),
('JPN', '加拉太书', 48, 3, 18, '相続がもし律法によるなら、もはやそれは約束によるのではありません。しかし、神は約束を通して、アブラハムに相続の恵みを下さったのです。'),
('JPN', '加拉太书', 48, 3, 19, 'それでは、律法とは何でしょうか。それは、約束を受けたこの子孫が来られるときまで、違反を示すためにつけ加えられたもので、御使いたちを通して仲介者の手で定められたものです。'),
('JPN', '加拉太书', 48, 3, 20, '仲介者は、当事者が一人であれば、いりません。しかし約束をお与えになった神は唯一の方です。'),
('JPN', '加拉太书', 48, 3, 21, 'それでは、律法は神の約束に反するのでしょうか。決してそんなことはありません。もし、いのちを与えることができる律法が与えられたのであれば、義は確かに律法によるものだったでしょう。'),
('JPN', '加拉太书', 48, 3, 22, 'しかし聖書は、すべてのものを罪の下に閉じ込めました。それは約束が、イエス・キリストに対する信仰によって、信じる人たちに与えられるためでした。'),
('JPN', '加拉太书', 48, 3, 23, '信仰が現れる前、私たちは律法の下で監視され、来たるべき信仰が啓示されるまで閉じ込められていました。'),
('JPN', '加拉太书', 48, 3, 24, 'こうして、律法は私たちをキリストに導く養育係となりました。それは、私たちが信仰によって義と認められるためです。'),
('JPN', '加拉太书', 48, 3, 25, 'しかし、信仰が現れたので、私たちはもはや養育係の下にはいません。'),
('JPN', '加拉太书', 48, 3, 26, 'あなたがたはみな、信仰により、キリスト・イエスにあって神の子どもです。'),
('JPN', '加拉太书', 48, 3, 27, 'キリストにつくバプテスマを受けたあなたがたはみな、キリストを着たのです。'),
('JPN', '加拉太书', 48, 3, 28, 'ユダヤ人もギリシア人もなく、奴隷も自由人もなく、男と女もありません。あなたがたはみな、キリスト・イエスにあって一つだからです。'),
('JPN', '加拉太书', 48, 3, 29, 'あなたがたがキリストのものであれば、アブラハムの子孫であり、約束による相続人なのです。'),
('JPN', '加拉太书', 48, 4, 1, 'つまり、こういうことです。相続人は、全財産の持ち主なのに、子どもであるうちは奴隷と何も変わらず、'),
('JPN', '加拉太书', 48, 4, 2, '父が定めた日までは、後見人や管理人の下にあります。'),
('JPN', '加拉太书', 48, 4, 3, '同じように私たちも、子どもであったときには、この世のもろもろの霊の下に奴隷となっていました。'),
('JPN', '加拉太书', 48, 4, 4, 'しかし時が満ちて、神はご自分の御子を、女から生まれた者、律法の下にある者として遣わされました。'),
('JPN', '加拉太书', 48, 4, 5, 'それは、律法の下にある者を贖い出すためであり、私たちが子としての身分を受けるためでした。'),
('JPN', '加拉太书', 48, 4, 6, 'そして、あなたがたが子であるので、神は「アバ、父よ」と叫ぶ御子の御霊を、私たちの心に遣わされました。'),
('JPN', '加拉太书', 48, 4, 7, 'ですから、あなたはもはや奴隷ではなく、子です。子であれば、神による相続人です。'),
('JPN', '加拉太书', 48, 4, 8, 'あなたがたは、かつて神を知らなかったとき、本来神ではない神々の奴隷でした。'),
('JPN', '加拉太书', 48, 4, 9, 'しかし、今では神を知っているのに、いや、むしろ神に知られているのに、どうして弱くて貧弱な、もろもろの霊に逆戻りして、もう一度改めて奴隷になりたいと願うのですか。'),
('JPN', '加拉太书', 48, 4, 10, 'あなたがたは、いろいろな日、月、季節、年を守っています。'),
('JPN', '加拉太书', 48, 4, 11, '私は、あなたがたのために労したことが無駄になったのではないかと、あなたがたのことを心配しています。'),
('JPN', '加拉太书', 48, 4, 12, '兄弟たち、あなたがたに願います。私もあなたがたのようになったのですから、あなたがたも私のようになってください。あなたがたは私に悪いことを何一つしていません。'),
('JPN', '加拉太书', 48, 4, 13, 'あなたがたが知っているとおり、私が最初あなたがたに福音を伝えたのは、私の肉体が弱かったためでした。'),
('JPN', '加拉太书', 48, 4, 14, 'そして私の肉体には、あなたがたにとって試練となるものがあったのに、あなたがたは軽蔑したり嫌悪したりせず、かえって、私を神の御使いであるかのように、キリスト・イエスであるかのように、受け入れてくれました。'),
('JPN', '加拉太书', 48, 4, 15, 'それなのに、あなたがたの幸いは、今どこにあるのですか。私はあなたがたのために証ししますが、あなたがたは、できることなら、自分の目をえぐり出して私に与えようとさえしたのです。'),
('JPN', '加拉太书', 48, 4, 16, 'それでは、私はあなたがたに真理を語ったために、あなたがたの敵になったのでしょうか。'),
('JPN', '加拉太书', 48, 4, 17, 'あの人たちはあなたがたに対して熱心ですが、それは善意からではありません。彼らはあなたがたを私から引き離して、自分たちに熱心にならせようとしているのです。'),
('JPN', '加拉太书', 48, 4, 18, '善意から熱心に慕われるのは、いつでも良いことです。それは、私があなたがたと一緒にいる時だけではありません。'),
('JPN', '加拉太书', 48, 4, 19, '私の子どもたち。あなたがたのうちにキリストが形造られるまで、私は再びあなたがたのために産みの苦しみをしています。'),
('JPN', '加拉太书', 48, 4, 20, '私は今、あなたがたと一緒にいて、口調を変えて話せたらと思います。あなたがたのことで私は途方に暮れているのです。'),
('JPN', '加拉太书', 48, 4, 21, '律法の下にいたいと思う人たち、私に答えてください。あなたがたは律法の言うことを聞かないのですか。'),
('JPN', '加拉太书', 48, 4, 22, 'アブラハムには二人の息子がいて、一人は女奴隷から、一人は自由の女から生まれた、と書かれています。'),
('JPN', '加拉太书', 48, 4, 23, '女奴隷の子は肉によって生まれたのに対し、自由の女の子は約束によって生まれました。'),
('JPN', '加拉太书', 48, 4, 24, 'ここには比喩的な意味があります。この女たちは二つの契約を表しています。一方はシナイ山から出ていて、奴隷となる子を産みます。それはハガルのことです。'),
('JPN', '加拉太书', 48, 4, 25, 'このハガルは、アラビアにあるシナイ山のことで、今のエルサレムに当たります。なぜなら、今のエルサレムは、彼女の子らとともに奴隷となっているからです。'),
('JPN', '加拉太书', 48, 4, 26, 'しかし、上にあるエルサレムは自由の女であり、私たちの母です。'),
('JPN', '加拉太书', 48, 4, 27, 'なぜなら、こう書いてあるからです。「子を産まない不妊の女よ、喜び歌え。産みの苦しみを知らない女よ、喜び叫べ。夫に捨てられた女の子どもは、夫のある女の子どもよりも多いからだ。」'),
('JPN', '加拉太书', 48, 4, 28, '兄弟たち、あなたがたはイサクのように約束の子どもです。'),
('JPN', '加拉太书', 48, 4, 29, 'けれども、あのとき、肉によって生まれた者が、御霊によって生まれた者を迫害したように、今もそのとおりになっています。'),
('JPN', '加拉太书', 48, 4, 30, 'しかし、聖書は何と言っていますか。「女奴隷とその子どもを追い出してください。女奴隷の子どもは、決して自由の女の子どもとともに相続すべきではないのです。」'),
('JPN', '加拉太书', 48, 4, 31, 'こういうわけで、兄弟たち、私たちは女奴隷の子どもではなく、自由の女の子どもです。'),
('JPN', '加拉太书', 48, 5, 1, 'キリストは、自由を得させるために私たちを解放してくださいました。ですから、あなたがたは堅く立って、再び奴隷のくびきを負わされないようにしなさい。'),
('JPN', '加拉太书', 48, 5, 2, 'よく聞いてください。私パウロがあなたがたに言います。もしあなたがたが割礼を受けるなら、キリストはあなたがたに、何の益ももたらさないことになります。'),
('JPN', '加拉太书', 48, 5, 3, '割礼を受けるすべての人に、もう一度はっきり言っておきます。そういう人には律法全体を行う義務があります。'),
('JPN', '加拉太书', 48, 5, 4, '律法によって義と認められようとしているなら、あなたがたはキリストから離れ、恵みから落ちてしまったのです。'),
('JPN', '加拉太书', 48, 5, 5, '私たちは、義とされる望みの実現を、信仰により、御霊によって待ち望んでいるのですから。'),
('JPN', '加拉太书', 48, 5, 6, 'キリスト・イエスにあって大事なのは、割礼を受ける受けないではなく、愛によって働く信仰なのです。'),
('JPN', '加拉太书', 48, 5, 7, 'あなたがたはよく走っていたのに、だれがあなたがたの邪魔をして、真理に従わないようにさせたのですか。'),
('JPN', '加拉太书', 48, 5, 8, 'そのような説得は、あなたがたを召された方から出たものではありません。'),
('JPN', '加拉太书', 48, 5, 9, 'わずかなパン種が、こねた粉全体をふくらませるのです。'),
('JPN', '加拉太书', 48, 5, 10, 'あなたがたが別の考えを持つことは決してないと、私は主にあって確信しています。しかし、あなたがたを動揺させる者は、だれであろうと、さばきを受けます。'),
('JPN', '加拉太书', 48, 5, 11, '兄弟たち。もし私が今でも割礼を宣べ伝えているなら、どうして今なお迫害を受けているのですか。それを宣べ伝えているなら、十字架のつまずきはなくなっているはずです。'),
('JPN', '加拉太书', 48, 5, 12, 'あなたがたをかき乱す者たちは、いっそのこと切除してしまえばよいのです。'),
('JPN', '加拉太书', 48, 5, 13, '兄弟たち。あなたがたは自由を与えられるために召されたのです。ただ、その自由を肉の働く機会としないで、愛をもって互いに仕え合いなさい。'),
('JPN', '加拉太书', 48, 5, 14, '律法全体は、「あなたの隣人を自分自身のように愛しなさい」という一つのことばで全うされるのです。'),
('JPN', '加拉太书', 48, 5, 15, '気をつけなさい。互いに、かみつき合ったり、食い合ったりしているなら、互いの間で滅ぼされてしまいます。'),
('JPN', '加拉太书', 48, 5, 16, '私は言います。御霊によって歩みなさい。そうすれば、肉の欲望を満たすことは決してありません。'),
('JPN', '加拉太书', 48, 5, 17, '肉が望むことは御霊に逆らい、御霊が望むことは肉に逆らうからです。この二つは互いに対立しているので、あなたがたは願っていることができなくなります。'),
('JPN', '加拉太书', 48, 5, 18, '御霊によって導かれているなら、あなたがたは律法の下にはいません。'),
('JPN', '加拉太书', 48, 5, 19, '肉のわざは明らかです。すなわち、淫らな行い、汚れ、好色、'),
('JPN', '加拉太书', 48, 5, 20, '偶像礼拝、魔術、敵意、争い、そねみ、憤り、党派心、分裂、分派、'),
('JPN', '加拉太书', 48, 5, 21, 'ねたみ、泥酔、遊興、そういった類のものです。以前にも言ったように、今もあなたがたにあらかじめ言っておきます。このようなことをしている者たちは神の国を相続できません。'),
('JPN', '加拉太书', 48, 5, 22, 'しかし、御霊の実は、愛、喜び、平安、寛容、親切、善意、誠実、'),
('JPN', '加拉太书', 48, 5, 23, '柔和、自制です。このようなものに反対する律法はありません。'),
('JPN', '加拉太书', 48, 5, 24, 'キリスト・イエスにつく者は、自分の肉を、情欲や欲望とともに十字架につけたのです。'),
('JPN', '加拉太书', 48, 5, 25, '私たちは、御霊によって生きているのなら、御霊によって進もうではありませんか。'),
('JPN', '加拉太书', 48, 5, 26, 'うぬぼれて、互いに挑み合ったり、ねたみ合ったりしないようにしましょう。'),
('JPN', '加拉太书', 48, 6, 1, '兄弟たち。もしだれかが何かの過ちに陥っていることが分かったなら、御霊の人であるあなたがたは、柔和な心でその人を正してあげなさい。また、自分自身も誘惑に陥らないように気をつけなさい。'),
('JPN', '加拉太书', 48, 6, 2, '互いの重荷を負い合いなさい。そうすれば、キリストの律法を成就することになります。'),
('JPN', '加拉太书', 48, 6, 3, 'だれかが、何者でもないのに、自分を何者かであるように思うなら、自分自身を欺いているのです。'),
('JPN', '加拉太书', 48, 6, 4, 'それぞれ自分の行いを吟味しなさい。そうすれば、自分にだけは誇ることができても、ほかの人には誇ることができなくなるでしょう。'),
('JPN', '加拉太书', 48, 6, 5, '人はそれぞれ、自分自身の重荷を負うことになるのです。'),
('JPN', '加拉太书', 48, 6, 6, 'みことばを教えてもらう人は、教えてくれる人と、すべての良いものを分かち合いなさい。'),
('JPN', '加拉太书', 48, 6, 7, '思い違いをしてはいけません。神は侮られるような方ではありません。人は種を蒔けば、刈り取りもすることになります。'),
('JPN', '加拉太书', 48, 6, 8, '自分の肉に蒔く者は、肉から滅びを刈り取り、御霊に蒔く者は、御霊から永遠のいのちを刈り取るのです。'),
('JPN', '加拉太书', 48, 6, 9, '失望せずに善を行いましょう。あきらめずに続ければ、時が来て刈り取ることになります。'),
('JPN', '加拉太书', 48, 6, 10, 'ですから、私たちは機会があるうちに、すべての人に、特に信仰の家族に善を行いましょう。'),
('JPN', '加拉太书', 48, 6, 11, 'ご覧なさい。こんなに大きな字で、私はあなたがたに自分の手で書いています。'),
('JPN', '加拉太书', 48, 6, 12, '肉において外見を良くしたい者たちが、ただ、キリストの十字架のゆえに自分たちが迫害されないようにと、あなたがたに割礼を強いています。'),
('JPN', '加拉太书', 48, 6, 13, '割礼を受けている者たちは、自分自身では律法を守っていないのに、あなたがたの肉を誇るために、あなたがたに割礼を受けさせたいのです。'),
('JPN', '加拉太书', 48, 6, 14, 'しかし私には、私たちの主イエス・キリストの十字架以外に誇りとするものが、決してあってはなりません。この十字架につけられて、世は私に対して死に、私も世に対して死にました。'),
('JPN', '加拉太书', 48, 6, 15, '割礼を受けているか受けていないかは、大事なことではありません。大事なのは新しい創造です。'),
('JPN', '加拉太书', 48, 6, 16, 'この基準にしたがって進む人々の上に、そして神のイスラエルの上に、平安とあわれみがありますように。'),
('JPN', '加拉太书', 48, 6, 17, 'これからは、だれも私を煩わせないようにしてください。私は、この身にイエスの焼き印を帯びているのですから。'),
('JPN', '加拉太书', 48, 6, 18, '兄弟たち。私たちの主イエス・キリストの恵みが、あなたがたの霊とともにありますように。アーメン。'),
('JPN', '以弗所书', 49, 1, 1, '神のみこころによるキリスト・イエスの使徒パウロから、キリスト・イエスにある忠実なエペソの聖徒たちへ。'),
('JPN', '以弗所书', 49, 1, 2, '私たちの父なる神と主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '以弗所书', 49, 1, 3, '私たちの主イエス・キリストの父である神がほめたたえられますように。神はキリストにあって、天上にあるすべての霊的祝福をもって私たちを祝福してくださいました。'),
('JPN', '以弗所书', 49, 1, 4, 'すなわち神は、世界の基が据えられる前から、この方にあって私たちを選び、御前に聖なる、傷のない者にしようとされたのです。'),
('JPN', '以弗所书', 49, 1, 5, '神は、みこころの良しとするところにしたがって、私たちをイエス・キリストによってご自分の子にしようと、愛をもってあらかじめ定めておられました。'),
('JPN', '以弗所书', 49, 1, 6, 'それは、神がその愛する方にあって私たちに与えてくださった恵みの栄光が、ほめたたえられるためです。'),
('JPN', '以弗所书', 49, 1, 7, 'このキリストにあって、私たちはその血による贖い、背きの罪の赦しを受けています。これは神の豊かな恵みによることです。'),
('JPN', '以弗所书', 49, 1, 8, 'この恵みを、神はあらゆる知恵と思慮をもって私たちの上にあふれさせ、'),
('JPN', '以弗所书', 49, 1, 9, 'みこころの奥義を私たちに知らせてくださいました。その奥義とは、キリストにあって神があらかじめお立てになったみむねにしたがい、'),
('JPN', '以弗所书', 49, 1, 10, '時が満ちて計画が実行に移され、天にあるものも地にあるものも、一切のものが、キリストにあって、一つに集められることです。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '以弗所书', 49, 1, 11, 'またキリストにあって、私たちは御国を受け継ぐ者となりました。すべてをみこころによる計画のままに行う方の目的にしたがい、あらかじめそのように定められていたのです。'),
('JPN', '以弗所书', 49, 1, 12, 'それは、前からキリストに望みを置いていた私たちが、神の栄光をほめたたえるためです。'),
('JPN', '以弗所书', 49, 1, 13, 'このキリストにあって、あなたがたもまた、真理のことば、あなたがたの救いの福音を聞いてそれを信じたことにより、約束の聖霊によって証印を押されました。'),
('JPN', '以弗所书', 49, 1, 14, '聖霊は私たちが御国を受け継ぐことの保証です。このことは、私たちが贖われて神のものとされ、神の栄光がほめたたえられるためです。'),
('JPN', '以弗所书', 49, 1, 15, 'こういうわけで私も、主イエスに対するあなたがたの信仰と、すべての聖徒に対する愛を聞いているので、'),
('JPN', '以弗所书', 49, 1, 16, '祈るときには、あなたがたのことを思い、絶えず感謝しています。'),
('JPN', '以弗所书', 49, 1, 17, 'どうか、私たちの主イエス・キリストの神、栄光の父が、神を知るための知恵と啓示の御霊を、あなたがたに与えてくださいますように。'),
('JPN', '以弗所书', 49, 1, 18, 'また、あなたがたの心の目がはっきり見えるようになって、神の召しにより与えられる望みがどのようなものか、聖徒たちが受け継ぐものがどれほど栄光に富んだものか、'),
('JPN', '以弗所书', 49, 1, 19, 'また、神の大能の力の働きによって私たち信じる者に働く神のすぐれた力が、どれほど偉大なものであるかを、知ることができますように。'),
('JPN', '以弗所书', 49, 1, 20, 'この大能の力を神はキリストのうちに働かせて、キリストを死者の中からよみがえらせ、天上でご自分の右の座に着かせて、'),
('JPN', '以弗所书', 49, 1, 21, 'すべての支配、権威、権力、主権の上に、また、今の世だけでなく、次に来る世においても、となえられるすべての名の上に置かれました。'),
('JPN', '以弗所书', 49, 1, 22, 'また、神はすべてのものをキリストの足の下に従わせ、キリストを、すべてのものの上に立つかしらとして教会に与えられました。'),
('JPN', '以弗所书', 49, 1, 23, '教会はキリストのからだであり、すべてのものをすべてのもので満たす方が満ちておられるところです。'),
('JPN', '以弗所书', 49, 2, 1, 'さて、あなたがたは自分の背きと罪の中に死んでいた者であり、'),
('JPN', '以弗所书', 49, 2, 2, 'かつては、それらの罪の中にあってこの世の流れに従い、空中の権威を持つ支配者、すなわち、不従順の子らの中に今も働いている霊に従って歩んでいました。'),
('JPN', '以弗所书', 49, 2, 3, '私たちもみな、不従順の子らの中にあって、かつては自分の肉の欲のままに生き、肉と心の望むことを行い、ほかの人たちと同じように、生まれながら御怒りを受けるべき子らでした。'),
('JPN', '以弗所书', 49, 2, 4, 'しかし、あわれみ豊かな神は、私たちを愛してくださったその大きな愛のゆえに、'),
('JPN', '以弗所书', 49, 2, 5, '背きの中に死んでいた私たちを、キリストとともに生かしてくださいました。あなたがたが救われたのは恵みによるのです。'),
('JPN', '以弗所书', 49, 2, 6, '神はまた、キリスト・イエスにあって、私たちをともによみがえらせ、ともに天上に座らせてくださいました。'),
('JPN', '以弗所书', 49, 2, 7, 'それは、キリスト・イエスにあって私たちに与えられた慈愛によって、この限りなく豊かな恵みを、来たるべき世々に示すためでした。'),
('JPN', '以弗所书', 49, 2, 8, 'この恵みのゆえに、あなたがたは信仰によって救われたのです。それはあなたがたから出たことではなく、神の賜物です。'),
('JPN', '以弗所书', 49, 2, 9, '行いによるのではありません。だれも誇ることのないためです。'),
('JPN', '以弗所书', 49, 2, 10, '実に、私たちは神の作品であって、良い行いをするためにキリスト・イエスにあって造られたのです。神は、私たちが良い行いに歩むように、その良い行いをあらかじめ備えてくださいました。'),
('JPN', '以弗所书', 49, 2, 11, 'ですから、思い出してください。あなたがたはかつて、肉においては異邦人でした。人の手で肉に施された、いわゆる「割礼」を持つ人々からは、無割礼の者と呼ばれ、'),
('JPN', '以弗所书', 49, 2, 12, 'そのころは、キリストから遠く離れ、イスラエルの民から除外され、約束の契約については他国人で、この世にあって望みもなく、神もない者たちでした。'),
('JPN', '以弗所书', 49, 2, 13, 'しかし、かつては遠く離れていたあなたがたも、今ではキリスト・イエスにあって、キリストの血によって近い者となりました。'),
('JPN', '以弗所书', 49, 2, 14, '実に、キリストこそ私たちの平和です。キリストは私たち二つのものを一つにし、ご自分の肉において、隔ての壁である敵意を打ち壊し、'),
('JPN', '以弗所书', 49, 2, 15, '様々な規定から成る戒めの律法を廃棄されました。こうしてキリストは、この二つをご自分において新しい一人の人に造り上げて平和を実現し、'),
('JPN', '以弗所书', 49, 2, 16, '二つのものを一つのからだとして、十字架によって神と和解させ、敵意を十字架によって滅ぼされました。'),
('JPN', '以弗所书', 49, 2, 17, 'また、キリストは来て、遠くにいたあなたがたに平和を、また近くにいた人々にも平和を、福音として伝えられました。'),
('JPN', '以弗所书', 49, 2, 18, 'このキリストを通して、私たち二つのものが、一つの御霊によって御父に近づくことができるのです。'),
('JPN', '以弗所书', 49, 2, 19, 'こういうわけで、あなたがたは、もはや他国人でも寄留者でもなく、聖徒たちと同じ国の民であり、神の家族なのです。'),
('JPN', '以弗所书', 49, 2, 20, '使徒たちや預言者たちという土台の上に建てられていて、キリスト・イエスご自身がその要の石です。'),
('JPN', '以弗所书', 49, 2, 21, 'このキリストにあって、建物の全体が組み合わされて成長し、主にある聖なる宮となります。'),
('JPN', '以弗所书', 49, 2, 22, 'あなたがたも、このキリストにあって、ともに築き上げられ、御霊によって神の御住まいとなるのです。'),
('JPN', '以弗所书', 49, 3, 1, 'こういうわけで、あなたがた異邦人のために、私パウロはキリスト・イエスの囚人となっています。'),
('JPN', '以弗所书', 49, 3, 2, 'あなたがたのために私に与えられた神の恵みの務めについては、あなたがたはすでに聞いたことでしょう。'),
('JPN', '以弗所书', 49, 3, 3, '先に短く書いたとおり、奥義が啓示によって私に知らされました。'),
('JPN', '以弗所书', 49, 3, 4, 'それを読めば、私がキリストの奥義をどう理解しているかがよく分かるはずです。'),
('JPN', '以弗所书', 49, 3, 5, 'この奥義は、前の時代には、今のように人の子らに知らされていませんでしたが、今は御霊によって、キリストの聖なる使徒たちと預言者たちに啓示されています。'),
('JPN', '以弗所书', 49, 3, 6, 'それは、福音により、キリスト・イエスにあって、異邦人も共同の相続人になり、ともに同じからだに連なって、ともに約束にあずかる者になるということです。'),
('JPN', '以弗所书', 49, 3, 7, '私は、神の力の働きによって私に与えられた神の恵みの賜物により、この福音に仕える者になりました。'),
('JPN', '以弗所书', 49, 3, 8, 'すべての聖徒たちのうちで最も小さな私に、この恵みが与えられたのは、キリストの測り知れない富を福音として異邦人に宣べ伝えるためであり、'),
('JPN', '以弗所书', 49, 3, 9, 'また、万物を創造した神のうちに世々隠されていた奥義の実現がどのようなものなのかを、すべての人に明らかにするためです。'),
('JPN', '以弗所书', 49, 3, 10, 'これは、今、天上にある支配と権威に、教会を通して神のきわめて豊かな知恵が知らされるためであり、'),
('JPN', '以弗所书', 49, 3, 11, '私たちの主キリスト・イエスにおいて成し遂げられた、永遠のご計画によるものです。'),
('JPN', '以弗所书', 49, 3, 12, '私たちはこのキリストにあって、キリストに対する信仰により、確信をもって大胆に神に近づくことができます。'),
('JPN', '以弗所书', 49, 3, 13, 'ですから、私があなたがたのために苦難にあっていることで、落胆することのないようお願いします。私が受けている苦難は、あなたがたの栄光なのです。'),
('JPN', '以弗所书', 49, 3, 14, 'こういうわけで、私は膝をかがめて、'),
('JPN', '以弗所书', 49, 3, 15, '天と地にあるすべての家族の、「家族」という呼び名の元である御父の前に祈ります。'),
('JPN', '以弗所书', 49, 3, 16, 'どうか御父が、その栄光の豊かさにしたがって、内なる人に働く御霊により、力をもってあなたがたを強めてくださいますように。'),
('JPN', '以弗所书', 49, 3, 17, '信仰によって、あなたがたの心のうちにキリストを住まわせてくださいますように。そして、愛に根ざし、愛に基礎を置いているあなたがたが、'),
('JPN', '以弗所书', 49, 3, 18, 'すべての聖徒たちとともに、その広さ、長さ、高さ、深さがどれほどであるかを理解する力を持つようになり、'),
('JPN', '以弗所书', 49, 3, 19, '人知をはるかに超えたキリストの愛を知ることができますように。そのようにして、神の満ちあふれる豊かさにまで、あなたがたが満たされますように。'),
('JPN', '以弗所书', 49, 3, 20, 'どうか、私たちのうちに働く御力によって、私たちが願うところ、思うところのすべてをはるかに超えて行うことのできる方に、'),
('JPN', '以弗所书', 49, 3, 21, '教会において、またキリスト・イエスにあって、栄光が、世々限りなく、とこしえまでもありますように。アーメン。'),
('JPN', '以弗所书', 49, 4, 1, 'さて、主にある囚人の私はあなたがたに勧めます。あなたがたは、召されたその召しにふさわしく歩みなさい。'),
('JPN', '以弗所书', 49, 4, 2, '謙遜と柔和の限りを尽くし、寛容を示し、愛をもって互いに耐え忍び、'),
('JPN', '以弗所书', 49, 4, 3, '平和の絆で結ばれて、御霊による一致を熱心に保ちなさい。'),
('JPN', '以弗所书', 49, 4, 4, 'あなたがたが召された、その召しの望みが一つであったのと同じように、からだは一つ、御霊は一つです。'),
('JPN', '以弗所书', 49, 4, 5, '主はひとり、信仰は一つ、バプテスマは一つです。'),
('JPN', '以弗所书', 49, 4, 6, 'すべてのものの上にあり、すべてのものを貫き、すべてのもののうちにおられる、すべてのものの父である神はただひとりです。'),
('JPN', '以弗所书', 49, 4, 7, 'しかし、私たちは一人ひとり、キリストの賜物の量りにしたがって恵みを与えられました。'),
('JPN', '以弗所书', 49, 4, 8, 'そのため、こう言われています。「彼はいと高き所に上ったとき、捕虜を連れて行き、人々に贈り物を与えられた。」'),
('JPN', '以弗所书', 49, 4, 9, '「上った」ということは、彼が低い所、つまり地上に降られたということでなくて何でしょうか。'),
('JPN', '以弗所书', 49, 4, 10, 'この降られた方ご自身は、すべてのものを満たすために、もろもろの天よりも高く上られた方でもあります。'),
('JPN', '以弗所书', 49, 4, 11, 'こうして、キリストご自身が、ある人たちを使徒、ある人たちを預言者、ある人たちを伝道者、ある人たちを牧師また教師としてお立てになりました。'),
('JPN', '以弗所书', 49, 4, 12, 'それは、聖徒たちを整えて奉仕の働きをさせ、キリストのからだを建て上げるためです。'),
('JPN', '以弗所书', 49, 4, 13, '私たちはみな、神の御子に対する信仰と知識において一つとなり、一人の成熟した大人となって、キリストの満ち満ちた身丈にまで達するのです。'),
('JPN', '以弗所书', 49, 4, 14, 'こうして、私たちはもはや子どもではなく、人の悪巧みや人を欺く悪賢い策略から出た、どんな教えの風にも、吹き回されたり、もてあそばれたりすることがなく、'),
('JPN', '以弗所书', 49, 4, 15, 'むしろ、愛をもって真理を語り、あらゆる点において、かしらであるキリストに向かって成長するのです。'),
('JPN', '以弗所书', 49, 4, 16, 'キリストによって、からだ全体は、あらゆる節々を支えとして組み合わされ、つなぎ合わされ、それぞれの部分がその分に応じて働くことにより成長して、愛のうちに建てられることになります。'),
('JPN', '以弗所书', 49, 4, 17, 'ですから私は言います。主にあって厳かに勧めます。あなたがたはもはや、異邦人がむなしい心で歩んでいるように歩んではなりません。'),
('JPN', '以弗所书', 49, 4, 18, '彼らは知性において暗くなり、彼らのうちにある無知と、頑なな心のゆえに、神のいのちから遠く離れています。'),
('JPN', '以弗所书', 49, 4, 19, '無感覚になった彼らは、好色に身を任せて、あらゆる不潔な行いを貪るようになっています。'),
('JPN', '以弗所书', 49, 4, 20, 'しかしあなたがたは、キリストをそのように学んだのではありません。'),
('JPN', '以弗所书', 49, 4, 21, 'ただし、本当にあなたがたがキリストについて聞き、キリストにあって教えられているとすれば、です。真理はイエスにあるのですから。'),
('JPN', '以弗所书', 49, 4, 22, 'その教えとは、あなたがたの以前の生活について言えば、人を欺く情欲によって腐敗していく古い人を、あなたがたが脱ぎ捨てること、'),
('JPN', '以弗所书', 49, 4, 23, 'また、あなたがたが霊と心において新しくされ続け、'),
('JPN', '以弗所书', 49, 4, 24, '真理に基づく義と聖をもって、神にかたどり造られた新しい人を着ることでした。'),
('JPN', '以弗所书', 49, 4, 25, 'ですから、あなたがたは偽りを捨て、それぞれ隣人に対して真実を語りなさい。私たちは互いに、からだの一部分なのです。'),
('JPN', '以弗所书', 49, 4, 26, '怒っても、罪を犯してはなりません。憤ったままで日が暮れるようであってはいけません。'),
('JPN', '以弗所书', 49, 4, 27, '悪魔に機会を与えないようにしなさい。'),
('JPN', '以弗所书', 49, 4, 28, '盗みをしている者は、もう盗んではいけません。むしろ、困っている人に分け与えるため、自分の手で正しい仕事をし、労苦して働きなさい。'),
('JPN', '以弗所书', 49, 4, 29, '悪いことばを、いっさい口から出してはいけません。むしろ、必要なときに、人の成長に役立つことばを語り、聞く人に恵みを与えなさい。'),
('JPN', '以弗所书', 49, 4, 30, '神の聖霊を悲しませてはいけません。あなたがたは、贖いの日のために、聖霊によって証印を押されているのです。'),
('JPN', '以弗所书', 49, 4, 31, '無慈悲、憤り、怒り、怒号、ののしりなどを、一切の悪意とともに、すべて捨て去りなさい。'),
('JPN', '以弗所书', 49, 4, 32, '互いに親切にし、優しい心で赦し合いなさい。神も、キリストにおいてあなたがたを赦してくださったのです。'),
('JPN', '以弗所书', 49, 5, 1, 'ですから、愛されている子どもらしく、神に倣う者となりなさい。'),
('JPN', '以弗所书', 49, 5, 2, 'また、愛のうちに歩みなさい。キリストも私たちを愛して、私たちのために、ご自分を神へのささげ物、またいけにえとし、芳ばしい香りを献げてくださいました。'),
('JPN', '以弗所书', 49, 5, 3, 'あなたがたの間では、聖徒にふさわしく、淫らな行いも、どんな汚れも、また貪りも、口にすることさえしてはいけません。'),
('JPN', '以弗所书', 49, 5, 4, 'また、わいせつなことや、愚かなおしゃべり、下品な冗談もそうです。これらは、ふさわしくありません。むしろ、口にすべきは感謝のことばです。'),
('JPN', '以弗所书', 49, 5, 5, 'このことをよく知っておきなさい。淫らな者、汚れた者、貪る者は偶像礼拝者であって、こういう者はだれも、キリストと神との御国を受け継ぐことができません。'),
('JPN', '以弗所书', 49, 5, 6, 'だれにも空しいことばでだまされてはいけません。こういう行いのゆえに、神の怒りは不従順の子らに下るのです。'),
('JPN', '以弗所书', 49, 5, 7, 'ですから、彼らの仲間になってはいけません。'),
('JPN', '以弗所书', 49, 5, 8, 'あなたがたは以前は闇でしたが、今は、主にあって光となりました。光の子どもとして歩みなさい。'),
('JPN', '以弗所书', 49, 5, 9, 'あらゆる善意と正義と真実のうちに、光は実を結ぶのです。'),
('JPN', '以弗所书', 49, 5, 10, '何が主に喜ばれることなのかを吟味しなさい。'),
('JPN', '以弗所书', 49, 5, 11, '実を結ばない暗闇のわざに加わらず、むしろ、それを明るみに出しなさい。'),
('JPN', '以弗所书', 49, 5, 12, '彼らがひそかに行っていることは、口にするのも恥ずかしいことなのです。'),
('JPN', '以弗所书', 49, 5, 13, 'しかし、すべてのものは光によって明るみに引き出され、明らかにされます。'),
('JPN', '以弗所书', 49, 5, 14, '明らかにされるものはみな光だからです。それで、こう言われています。「眠っている人よ、起きよ。死者の中から起き上がれ。そうすれば、キリストがあなたを照らされる。」'),
('JPN', '以弗所书', 49, 5, 15, 'ですから、自分がどのように歩んでいるか、あなたがたは細かく注意を払いなさい。知恵のない者としてではなく、知恵のある者として、'),
('JPN', '以弗所书', 49, 5, 16, '機会を十分に活かしなさい。悪い時代だからです。'),
('JPN', '以弗所书', 49, 5, 17, 'ですから、愚かにならないで、主のみこころが何であるかを悟りなさい。'),
('JPN', '以弗所书', 49, 5, 18, 'また、ぶどう酒に酔ってはいけません。そこには放蕩があるからです。むしろ、御霊に満たされなさい。'),
('JPN', '以弗所书', 49, 5, 19, '詩と賛美と霊の歌をもって互いに語り合い、主に向かって心から賛美し、歌いなさい。'),
('JPN', '以弗所书', 49, 5, 20, 'いつでも、すべてのことについて、私たちの主イエス・キリストの名によって、父である神に感謝しなさい。'),
('JPN', '以弗所书', 49, 5, 21, 'キリストを恐れて、互いに従い合いなさい。'),
('JPN', '以弗所书', 49, 5, 22, '妻たちよ。主に従うように、自分の夫に従いなさい。'),
('JPN', '以弗所书', 49, 5, 23, 'キリストが教会のかしらであり、ご自分がそのからだの救い主であるように、夫は妻のかしらなのです。'),
('JPN', '以弗所书', 49, 5, 24, '教会がキリストに従うように、妻もすべてにおいて夫に従いなさい。'),
('JPN', '以弗所书', 49, 5, 25, '夫たちよ。キリストが教会を愛し、教会のためにご自分を献げられたように、あなたがたも妻を愛しなさい。'),
('JPN', '以弗所书', 49, 5, 26, 'キリストがそうされたのは、みことばにより、水の洗いをもって、教会をきよめて聖なるものとするためであり、'),
('JPN', '以弗所书', 49, 5, 27, 'ご自分で、しみや、しわや、そのようなものが何一つない、聖なるもの、傷のないものとなった栄光の教会を、ご自分の前に立たせるためです。'),
('JPN', '以弗所书', 49, 5, 28, '同様に夫たちも、自分の妻を自分のからだのように愛さなければなりません。自分の妻を愛する人は自分自身を愛しているのです。'),
('JPN', '以弗所书', 49, 5, 29, 'いまだかつて自分の身を憎んだ人はいません。むしろ、それを養い育てます。キリストも教会に対してそのようになさるのです。'),
('JPN', '以弗所书', 49, 5, 30, '私たちはキリストのからだの部分だからです。'),
('JPN', '以弗所书', 49, 5, 31, '「それゆえ、男は父と母を離れ、その妻と結ばれ、ふたりは一体となるのである。」'),
('JPN', '以弗所书', 49, 5, 32, 'この奥義は偉大です。私は、キリストと教会を指して言っているのです。'),
('JPN', '以弗所书', 49, 5, 33, 'それはそれとして、あなたがたもそれぞれ、自分の妻を自分と同じように愛しなさい。妻もまた、自分の夫を敬いなさい。'),
('JPN', '以弗所书', 49, 6, 1, '子どもたちよ。主にあって自分の両親に従いなさい。これは正しいことなのです。'),
('JPN', '以弗所书', 49, 6, 2, '「あなたの父と母を敬え。」これは約束を伴う第一の戒めです。'),
('JPN', '以弗所书', 49, 6, 3, '「そうすれば、あなたは幸せになり、その土地であなたの日々は長く続く」という約束です。'),
('JPN', '以弗所书', 49, 6, 4, '父たちよ。自分の子どもたちを怒らせてはいけません。むしろ、主の教育と訓戒によって育てなさい。'),
('JPN', '以弗所书', 49, 6, 5, '奴隷たちよ。キリストに従うように、恐れおののいて真心から地上の主人に従いなさい。'),
('JPN', '以弗所书', 49, 6, 6, 'ご機嫌取りのような、うわべだけの仕え方ではなく、キリストのしもべとして心から神のみこころを行い、'),
('JPN', '以弗所书', 49, 6, 7, '人にではなく主に仕えるように、喜んで仕えなさい。'),
('JPN', '以弗所书', 49, 6, 8, '奴隷であっても自由人であっても、良いことを行えば、それぞれ主からその報いを受けることを、あなたがたは知っています。'),
('JPN', '以弗所书', 49, 6, 9, '主人たちよ。あなたがたも奴隷に対して同じようにしなさい。脅すことはやめなさい。あなたがたは、彼らの主、またあなたがたの主が天におられ、主は人を差別なさらないことを知っているのです。'),
('JPN', '以弗所书', 49, 6, 10, '終わりに言います。主にあって、その大能の力によって強められなさい。'),
('JPN', '以弗所书', 49, 6, 11, '悪魔の策略に対して堅く立つことができるように、神のすべての武具を身に着けなさい。'),
('JPN', '以弗所书', 49, 6, 12, '私たちの格闘は血肉に対するものではなく、支配、力、この暗闇の世界の支配者たち、また天上にいるもろもろの悪霊に対するものです。'),
('JPN', '以弗所书', 49, 6, 13, 'ですから、邪悪な日に際して対抗できるように、また、一切を成し遂げて堅く立つことができるように、神のすべての武具を取りなさい。'),
('JPN', '以弗所书', 49, 6, 14, 'そして、堅く立ちなさい。腰には真理の帯を締め、胸には正義の胸当てを着け、'),
('JPN', '以弗所书', 49, 6, 15, '足には平和の福音の備えをはきなさい。'),
('JPN', '以弗所书', 49, 6, 16, 'これらすべての上に、信仰の盾を取りなさい。それによって、悪い者が放つ火矢をすべて消すことができます。'),
('JPN', '以弗所书', 49, 6, 17, '救いのかぶとをかぶり、御霊の剣、すなわち神のことばを取りなさい。'),
('JPN', '以弗所书', 49, 6, 18, 'あらゆる祈りと願いによって、どんなときにも御霊によって祈りなさい。そのために、目を覚ましていて、すべての聖徒のために、忍耐の限りを尽くして祈りなさい。'),
('JPN', '以弗所书', 49, 6, 19, 'また、私のためにも、私が口を開くときに語るべきことばが与えられて、福音の奥義を大胆に知らせることができるように、祈ってください。'),
('JPN', '以弗所书', 49, 6, 20, '私はこの福音のために、鎖につながれながらも使節の務めを果たしています。宣べ伝える際、語るべきことを大胆に語れるように、祈ってください。'),
('JPN', '以弗所书', 49, 6, 21, '私の様子や私が何をしているかを、あなたがたにも分かってもらうために、愛する兄弟、主にある忠実な奉仕者であるティキコがすべてを知らせます。'),
('JPN', '以弗所书', 49, 6, 22, 'ティキコをあなたがたのもとに遣わすのは、ほかでもなく、あなたがたが私たちの様子を知って、心に励ましを受けるためです。'),
('JPN', '以弗所书', 49, 6, 23, '信仰に伴う、平安と愛が、父なる神と主イエス・キリストから、兄弟たちにありますように。'),
('JPN', '以弗所书', 49, 6, 24, '朽ちることのない愛をもって私たちの主イエス・キリストを愛する、すべての人とともに、恵みがありますように。'),
('JPN', '腓立比书', 50, 1, 1, 'キリスト・イエスのしもべである、パウロとテモテから、ピリピにいる、キリスト・イエスにあるすべての聖徒たち、ならびに監督たちと執事たちへ。'),
('JPN', '腓立比书', 50, 1, 2, '私たちの父なる神と主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '腓立比书', 50, 1, 3, '私は、あなたがたのことを思うたびに、私の神に感謝しています。'),
('JPN', '腓立比书', 50, 1, 4, 'あなたがたすべてのために祈るたびに、いつも喜びをもって祈り、'),
('JPN', '腓立比书', 50, 1, 5, 'あなたがたが最初の日から今日まで、福音を伝えることにともに携わってきたことを感謝しています。'),
('JPN', '腓立比书', 50, 1, 6, 'あなたがたの間で良い働きを始められた方は、キリスト・イエスの日が来るまでにそれを完成させてくださると、私は確信しています。'),
('JPN', '腓立比书', 50, 1, 7, 'あなたがたすべてについて、私がこのように考えるのは正しいことです。あなたがたはみな、私が投獄されているときも、福音を弁明し立証しているときも、私とともに恵みにあずかった人たちであり、そのようなあなたがたを私は心に留めているからです。'),
('JPN', '腓立比书', 50, 1, 8, '私がキリスト・イエスの愛の心をもって、どんなにあなたがたすべてを慕っているか、その証しをしてくださるのは神です。'),
('JPN', '腓立比书', 50, 1, 9, '私はこう祈っています。あなたがたの愛が、知識とあらゆる識別力によって、いよいよ豊かになり、'),
('JPN', '腓立比书', 50, 1, 10, 'あなたがたが、大切なことを見分けることができますように。こうしてあなたがたが、キリストの日に備えて、純真で非難されるところのない者となり、'),
('JPN', '腓立比书', 50, 1, 11, 'イエス・キリストによって与えられる義の実に満たされて、神の栄光と誉れが現されますように。'),
('JPN', '腓立比书', 50, 1, 12, 'さて、兄弟たち。私の身に起こったことが、かえって福音の前進に役立ったことを知ってほしいのです。'),
('JPN', '腓立比书', 50, 1, 13, '私がキリストのゆえに投獄されていることが、親衛隊の全員と、ほかのすべての人たちに明らかになり、'),
('JPN', '腓立比书', 50, 1, 14, '兄弟たちの大多数は、私が投獄されたことで、主にあって確信を与えられ、恐れることなく、ますます大胆にみことばを語るようになりました。'),
('JPN', '腓立比书', 50, 1, 15, '人々の中には、ねたみや争いからキリストを宣べ伝える者もいますが、善意からする者もいます。'),
('JPN', '腓立比书', 50, 1, 16, 'ある人たちは、私が福音を弁証するために立てられていることを知り、愛をもってキリストを伝えていますが、'),
('JPN', '腓立比书', 50, 1, 17, 'ほかの人たちは党派心からキリストを宣べ伝えており、純粋な動機からではありません。鎖につながれている私をさらに苦しめるつもりなのです。'),
('JPN', '腓立比书', 50, 1, 18, 'しかし、それが何だというのでしょう。見せかけであれ、真実であれ、あらゆる仕方でキリストが宣べ伝えられているのですから、私はそのことを喜んでいます。そうです。これからも喜ぶでしょう。'),
('JPN', '腓立比书', 50, 1, 19, 'というのは、あなたがたの祈りとイエス・キリストの御霊の支えによって、私が切に期待し望んでいるとおりに、このことが結局は私の救いとなることを知っているからです。'),
('JPN', '腓立比书', 50, 1, 20, '私の願いは、どんな場合にも恥じることなく、今もいつものように大胆に語り、生きるにしても死ぬにしても、私の身によってキリストがあがめられることです。'),
('JPN', '腓立比书', 50, 1, 21, '私にとって生きることはキリスト、死ぬことは益です。'),
('JPN', '腓立比书', 50, 1, 22, 'しかし、肉体において生きることが続くなら、私の働きが実を結ぶことになるので、どちらを選んだらよいか、私には分かりません。'),
('JPN', '腓立比书', 50, 1, 23, '私は、その二つのことの間で板ばさみとなっています。私の願いは、世を去ってキリストとともにいることです。そのほうが、はるかに望ましいのです。'),
('JPN', '腓立比书', 50, 1, 24, 'しかし、この肉体にとどまることが、あなたがたのためにはもっと必要です。'),
('JPN', '腓立比书', 50, 1, 25, 'このことを確信しているので、あなたがたの信仰の前進と喜びのために、私が生きながらえて、あなたがたすべてとともにいるようになることを知っています。'),
('JPN', '腓立比书', 50, 1, 26, 'そうなれば、私は再びあなたがたのもとに行けるので、私に関するあなたがたの誇りは、キリスト・イエスにあって増し加わるでしょう。'),
('JPN', '腓立比书', 50, 1, 27, 'ただキリストの福音にふさわしく生活しなさい。そうすれば、私が行ってあなたがたに会うにしても、離れているにしても、あなたがたについて、こう聞くことができるでしょう。あなたがたは霊を一つにして堅く立ち、福音の信仰のために心を一つにしてともに戦っていて、'),
('JPN', '腓立比书', 50, 1, 28, 'どんなことがあっても、反対者たちに脅かされることはない、と。そのことは、彼らにとっては滅びのしるし、あなたがたにとっては救いのしるしです。それは神によることです。'),
('JPN', '腓立比书', 50, 1, 29, 'あなたがたがキリストのために受けた恵みは、キリストを信じることだけでなく、キリストのために苦しむことでもあるのです。'),
('JPN', '腓立比书', 50, 1, 30, 'かつて私について見て、今また私について聞いているのと同じ苦闘を、あなたがたは経験しているのです。'),
('JPN', '腓立比书', 50, 2, 1, 'ですから、キリストにあって励ましがあり、愛の慰めがあり、御霊の交わりがあり、愛情とあわれみがあるなら、'),
('JPN', '腓立比书', 50, 2, 2, 'あなたがたは同じ思いとなり、同じ愛の心を持ち、心を合わせ、思いを一つにして、私の喜びを満たしてください。'),
('JPN', '腓立比书', 50, 2, 3, '何事も利己的な思いや虚栄からするのではなく、へりくだって、互いに人を自分よりすぐれた者と思いなさい。'),
('JPN', '腓立比书', 50, 2, 4, 'それぞれ、自分のことだけでなく、ほかの人のことも顧みなさい。'),
('JPN', '腓立比书', 50, 2, 5, 'キリスト・イエスのうちにあるこの思いを、あなたがたの間でも抱きなさい。'),
('JPN', '腓立比书', 50, 2, 6, 'キリストは、神の御姿であられるのに、神としてのあり方を捨てられないとは考えず、'),
('JPN', '腓立比书', 50, 2, 7, 'ご自分を空しくして、しもべの姿をとり、人間と同じようになられました。人としての姿をもって現れ、'),
('JPN', '腓立比书', 50, 2, 8, '自らを低くして、死にまで、それも十字架の死にまで従われました。'),
('JPN', '腓立比书', 50, 2, 9, 'それゆえ神は、この方を高く上げて、すべての名にまさる名を与えられました。'),
('JPN', '腓立比书', 50, 2, 10, 'それは、イエスの名によって、天にあるもの、地にあるもの、地の下にあるもののすべてが膝をかがめ、'),
('JPN', '腓立比书', 50, 2, 11, 'すべての舌が「イエス・キリストは主です」と告白して、父なる神に栄光を帰するためです。'),
('JPN', '腓立比书', 50, 2, 12, 'こういうわけですから、愛する者たち、あなたがたがいつも従順であったように、私がともにいるときだけでなく、私がいない今はなおさら従順になり、恐れおののいて自分の救いを達成するよう努めなさい。'),
('JPN', '腓立比书', 50, 2, 13, '神はみこころのままに、あなたがたのうちに働いて志を立てさせ、事を行わせてくださる方です。'),
('JPN', '腓立比书', 50, 2, 14, 'すべてのことを、不平を言わずに、疑わずに行いなさい。'),
('JPN', '腓立比书', 50, 2, 15, 'それは、あなたがたが、非難されるところのない純真な者となり、また、曲がった邪悪な世代のただ中にあって傷のない神の子どもとなり、'),
('JPN', '腓立比书', 50, 2, 16, 'いのちのことばをしっかり握り、彼らの間で世の光として輝くためです。そうすれば、私は自分の努力したことが無駄ではなく、労苦したことも無駄でなかったことを、キリストの日に誇ることができます。'),
('JPN', '腓立比书', 50, 2, 17, 'たとえ私が、あなたがたの信仰の礼拝といういけにえに添えられる、注ぎのささげ物となっても、私は喜びます。あなたがたすべてとともに喜びます。'),
('JPN', '腓立比书', 50, 2, 18, '同じように、あなたがたも喜んでください。私とともに喜んでください。'),
('JPN', '腓立比书', 50, 2, 19, '私は早くテモテをあなたがたのところに送りたいと、主イエスにあって望んでいます。あなたがたのことを知って、励ましを受けるためです。'),
('JPN', '腓立比书', 50, 2, 20, 'テモテのように私と同じ心になって、真実にあなたがたのことを心配している者は、だれもいません。'),
('JPN', '腓立比书', 50, 2, 21, 'みな自分自身のことを求めていて、イエス・キリストのことを求めてはいません。'),
('JPN', '腓立比书', 50, 2, 22, 'しかし、テモテが適任であることは、あなたがたが知っています。子が父に仕えるように、テモテは私とともに福音のために奉仕してきました。'),
('JPN', '腓立比书', 50, 2, 23, 'ですから、私のことがどうなるのか分かり次第、すぐに彼を送りたいと望んでいます。'),
('JPN', '腓立比书', 50, 2, 24, 'また、私自身も近いうちに行けると、主にあって確信しています。'),
('JPN', '腓立比书', 50, 2, 25, '私は、私の兄弟、同労者、戦友であり、あなたがたの使者で、私の必要に仕えてくれたエパフロディトを、あなたがたのところに送り返す必要があると考えました。'),
('JPN', '腓立比书', 50, 2, 26, '彼はあなたがたみなを慕っており、自分が病気になったことがあなたがたに伝わったことを、気にしているからです。'),
('JPN', '腓立比书', 50, 2, 27, '本当に、彼は死ぬほどの病気にかかりました。しかし、神は彼をあわれんでくださいました。彼だけでなく私もあわれんでくださり、悲しみに悲しみが重ならないようにしてくださいました。'),
('JPN', '腓立比书', 50, 2, 28, 'そこで、私は大急ぎで彼を送ります。あなたがたが彼に再び会って喜び、私も心配が少なくなるためです。'),
('JPN', '腓立比书', 50, 2, 29, 'ですから大きな喜びをもって、主にあって彼を迎えてください。また、彼のような人たちを尊敬しなさい。'),
('JPN', '腓立比书', 50, 2, 30, '彼はキリストの働きのために、死ぬばかりになりました。あなたがたが私に仕えることができなかった分を果たすため、いのちの危険を冒したのです。'),
('JPN', '腓立比书', 50, 3, 1, '最後に、私の兄弟たち、主にあって喜びなさい。私は、また同じことをいくつか書きますが、これは私にとって面倒なことではなく、あなたがたの安全のためにもなります。'),
('JPN', '腓立比书', 50, 3, 2, '犬どもに気をつけなさい。悪い働き人たちに気をつけなさい。肉体だけの割礼の者に気をつけなさい。'),
('JPN', '腓立比书', 50, 3, 3, '神の御霊によって礼拝し、キリスト・イエスを誇り、肉に頼らない私たちこそ、割礼の者なのです。'),
('JPN', '腓立比书', 50, 3, 4, 'ただし、私には、肉においても頼れるところがあります。ほかのだれかが肉に頼れると思うなら、私はそれ以上です。'),
('JPN', '腓立比书', 50, 3, 5, '私は生まれて八日目に割礼を受け、イスラエル民族、ベニヤミン部族の出身、ヘブル人の中のヘブル人、律法についてはパリサイ人、'),
('JPN', '腓立比书', 50, 3, 6, 'その熱心については教会を迫害したほどであり、律法による義については非難されるところがない者でした。'),
('JPN', '腓立比书', 50, 3, 7, 'しかし私は、自分にとって得であったこのようなすべてのものを、キリストのゆえに損と思うようになりました。'),
('JPN', '腓立比书', 50, 3, 8, 'それどころか、私の主であるキリスト・イエスを知っていることのすばらしさのゆえに、私はすべてを損と思っています。私はキリストのゆえにすべてを失いましたが、それらはちりあくただと考えています。それは、私がキリストを得て、'),
('JPN', '腓立比书', 50, 3, 9, 'キリストにある者と認められるようになるためです。私は律法による自分の義ではなく、キリストを信じることによる義、すなわち、信仰に基づいて神から与えられる義を持つのです。'),
('JPN', '腓立比书', 50, 3, 10, '私は、キリストとその復活の力を知り、キリストの苦難にもあずかって、キリストの死と同じ状態になり、'),
('JPN', '腓立比书', 50, 3, 11, '何とかして死者の中からの復活に達したいのです。'),
('JPN', '腓立比书', 50, 3, 12, '私は、すでに得たのでもなく、すでに完全にされているのでもありません。ただ捕らえようとして追求しているのです。そして、それを得るようにと、キリスト・イエスが私を捕らえてくださったのです。'),
('JPN', '腓立比书', 50, 3, 13, '兄弟たち。私は、自分がすでに捕らえたなどと考えてはいません。ただ一つのこと、すなわち、うしろのものを忘れ、前のものに向かって身を伸ばし、'),
('JPN', '腓立比书', 50, 3, 14, 'キリスト・イエスにあって神が上に召してくださるという、その賞をいただくために、目標を目指して走っているのです。'),
('JPN', '腓立比书', 50, 3, 15, 'ですから、大人である人はみな、このように考えましょう。もしも、あなたがたが何か違う考え方をしているなら、そのことも神があなたがたに明らかにしてくださいます。'),
('JPN', '腓立比书', 50, 3, 16, 'ただし、私たちは到達したところを基準にして進むべきです。'),
('JPN', '腓立比书', 50, 3, 17, '兄弟たち。私に倣う者となってください。また、あなたがたと同じように私たちを手本として歩んでいる人たちに、目を留めてください。'),
('JPN', '腓立比书', 50, 3, 18, 'というのは、私はたびたびあなたがたに言ってきたし、今も涙ながらに言うのですが、多くの人がキリストの十字架の敵として歩んでいるからです。'),
('JPN', '腓立比书', 50, 3, 19, 'その人たちの最後は滅びです。彼らは欲望を神とし、恥ずべきものを栄光として、地上のことだけを考える者たちです。'),
('JPN', '腓立比书', 50, 3, 20, 'しかし、私たちの国籍は天にあります。そこから主イエス・キリストが救い主として来られるのを、私たちは待ち望んでいます。'),
('JPN', '腓立比书', 50, 3, 21, 'キリストは、万物をご自分に従わせることさえできる御力によって、私たちの卑しいからだを、ご自分の栄光に輝くからだと同じ姿に変えてくださいます。'),
('JPN', '腓立比书', 50, 4, 1, 'ですから、私の愛し慕う兄弟たち、私の喜び、冠よ。このように主にあって堅く立ってください。愛する者たち。'),
('JPN', '腓立比书', 50, 4, 2, 'ユウオディアに勧め、シンティケに勧めます。あなたがたは、主にあって同じ思いになってください。'),
('JPN', '腓立比书', 50, 4, 3, 'そうです、真の協力者よ、あなたにもお願いします。彼女たちを助けてあげてください。この人たちは、いのちの書に名が記されているクレメンスやそのほかの私の同労者たちとともに、福音のために私と一緒に戦ったのです。'),
('JPN', '腓立比书', 50, 4, 4, 'いつも主にあって喜びなさい。もう一度言います。喜びなさい。'),
('JPN', '腓立比书', 50, 4, 5, 'あなたがたの寛容な心が、すべての人に知られるようにしなさい。主は近いのです。'),
('JPN', '腓立比书', 50, 4, 6, '何も思い煩わないで、あらゆる場合に、感謝をもってささげる祈りと願いによって、あなたがたの願い事を神に知っていただきなさい。'),
('JPN', '腓立比书', 50, 4, 7, 'そうすれば、すべての理解を超えた神の平安が、あなたがたの心と思いをキリスト・イエスにあって守ってくれます。'),
('JPN', '腓立比书', 50, 4, 8, '最後に、兄弟たち。すべて真実なこと、すべて尊ぶべきこと、すべて正しいこと、すべて清いこと、すべて愛すべきこと、すべて評判の良いことに、また、何か徳とされることや称賛に値することがあれば、そのようなことに心を留めなさい。'),
('JPN', '腓立比书', 50, 4, 9, 'あなたがたが私から学んだこと、受けたこと、聞いたこと、見たことを行いなさい。そうすれば、平和の神があなたがたとともにいてくださいます。'),
('JPN', '腓立比书', 50, 4, 10, '私を案じてくれるあなたがたの心が、今ついによみがえってきたことを、私は主にあって大いに喜んでいます。あなたがたは案じてくれていたのですが、それを示す機会がなかったのです。'),
('JPN', '腓立比书', 50, 4, 11, '乏しいからこう言うのではありません。私は、どんな境遇にあっても満足することを学びました。'),
('JPN', '腓立比书', 50, 4, 12, '私は、貧しくあることも知っており、富むことも知っています。満ち足りることにも飢えることにも、富むことにも乏しいことにも、ありとあらゆる境遇に対処する秘訣を心得ています。'),
('JPN', '腓立比书', 50, 4, 13, '私を強くしてくださる方によって、私はどんなことでもできるのです。'),
('JPN', '腓立比书', 50, 4, 14, 'それにしても、あなたがたは、よく私と苦難を分け合ってくれました。'),
('JPN', '腓立比书', 50, 4, 15, 'ピリピの人たち。あなたがたも知っているとおり、福音を伝え始めたころ、私がマケドニアを出たときに、物をやり取りして私の働きに関わってくれた教会はあなたがただけで、ほかにはありませんでした。'),
('JPN', '腓立比书', 50, 4, 16, 'テサロニケにいたときでさえ、あなたがたは私の必要のために、一度ならず二度までも物を送ってくれました。'),
('JPN', '腓立比书', 50, 4, 17, '私は贈り物を求めているのではありません。私が求めているのは、あなたがたの霊的な口座に加えられていく実なのです。'),
('JPN', '腓立比书', 50, 4, 18, '私はすべての物を受けて、満ちあふれています。エパフロディトからあなたがたの贈り物を受け取って、満ち足りています。それは芳ばしい香りであって、神が喜んで受けてくださるささげ物です。'),
('JPN', '腓立比书', 50, 4, 19, 'また、私の神は、キリスト・イエスの栄光のうちにあるご自分の豊かさにしたがって、あなたがたの必要をすべて満たしてくださいます。'),
('JPN', '腓立比书', 50, 4, 20, '私たちの父である神に、栄光が世々限りなくありますように。アーメン。'),
('JPN', '腓立比书', 50, 4, 21, 'キリスト・イエスにある聖徒の一人ひとりに、よろしく伝えてください。私と一緒にいる兄弟たちが、あなたがたによろしくと言っています。'),
('JPN', '腓立比书', 50, 4, 22, 'すべての聖徒たち、特にカエサルの家に属する人たちが、よろしくと言っています。'),
('JPN', '腓立比书', 50, 4, 23, '主イエス・キリストの恵みが、あなたがたの霊とともにありますように。'),
('JPN', '歌罗西书', 51, 1, 1, '神のみこころによるキリスト・イエスの使徒パウロと、兄弟テモテから、'),
('JPN', '歌罗西书', 51, 1, 2, 'コロサイにいる聖徒たち、キリストにある忠実な兄弟たちへ。私たちの父なる神から、恵みと平安があなたがたにありますように。'),
('JPN', '歌罗西书', 51, 1, 3, '私たちは、あなたがたのことを祈るときにいつも、私たちの主イエス・キリストの父なる神に感謝しています。'),
('JPN', '歌罗西书', 51, 1, 4, 'キリスト・イエスに対するあなたがたの信仰と、すべての聖徒に対してあなたがたが抱いている愛について聞いたからです。'),
('JPN', '歌罗西书', 51, 1, 5, 'それらは、あなたがたのために天に蓄えられている望みに基づくもので、あなたがたはこの望みのことを、あなたがたに届いた福音の真理のことばによって聞きました。'),
('JPN', '歌罗西书', 51, 1, 6, 'この福音は、あなたがたが神の恵みを聞いて本当に理解したとき以来、世界中で起こっているように、あなたがたの間でも実を結び成長しています。'),
('JPN', '歌罗西书', 51, 1, 7, 'そういうものとして、あなたがたは私たちの同労のしもべ、愛するエパフラスから福音を学びました。彼は、あなたがたのためにキリストに忠実に仕える者であり、'),
('JPN', '歌罗西书', 51, 1, 8, '御霊によるあなたがたの愛を、私たちに知らせてくれた人です。'),
('JPN', '歌罗西书', 51, 1, 9, 'こういうわけで、私たちもそのことを聞いた日から、絶えずあなたがたのために祈り求めています。どうか、あなたがたが、あらゆる霊的な知恵と理解力によって、神のみこころについての知識に満たされますように。'),
('JPN', '歌罗西书', 51, 1, 10, 'また、主にふさわしく歩み、あらゆる点で主に喜ばれ、あらゆる良いわざのうちに実を結び、神を知ることにおいて成長しますように。'),
('JPN', '歌罗西书', 51, 1, 11, '神の栄光の支配により、あらゆる力をもって強くされ、どんなことにも忍耐し、寛容でいられますように。'),
('JPN', '歌罗西书', 51, 1, 12, 'また、光の中にある、聖徒の相続分にあずかる資格をあなたがたに与えてくださった御父に、喜びをもって感謝をささげることができますように。'),
('JPN', '歌罗西书', 51, 1, 13, '御父は、私たちを暗闇の力から救い出して、愛する御子のご支配の中に移してくださいました。'),
('JPN', '歌罗西书', 51, 1, 14, 'この御子にあって、私たちは、贖い、すなわち罪の赦しを得ているのです。'),
('JPN', '歌罗西书', 51, 1, 15, '御子は、見えない神のかたちであり、すべての造られたものより先に生まれた方です。'),
('JPN', '歌罗西书', 51, 1, 16, 'なぜなら、天と地にあるすべてのものは、見えるものも見えないものも、王座であれ主権であれ、支配であれ権威であれ、御子にあって造られたからです。万物は御子によって造られ、御子のために造られました。'),
('JPN', '歌罗西书', 51, 1, 17, '御子は万物に先立って存在し、万物は御子にあって成り立っています。'),
('JPN', '歌罗西书', 51, 1, 18, 'また、御子はそのからだである教会のかしらです。御子は初めであり、死者の中から最初に生まれた方です。こうして、すべてのことにおいて第一の者となられました。'),
('JPN', '歌罗西书', 51, 1, 19, 'なぜなら神は、ご自分の満ち満ちたものをすべて御子のうちに宿らせ、'),
('JPN', '歌罗西书', 51, 1, 20, 'その十字架の血によって平和をもたらし、御子によって、御子のために万物を和解させること、すなわち、地にあるものも天にあるものも、御子によって和解させることを良しとしてくださったからです。'),
('JPN', '歌罗西书', 51, 1, 21, 'あなたがたも、かつては神から離れ、敵意を抱き、悪い行いの中にありましたが、'),
('JPN', '歌罗西书', 51, 1, 22, '今は、神が御子の肉のからだにおいて、その死によって、あなたがたをご自分と和解させてくださいました。あなたがたを聖なる者、傷のない者、責められるところのない者として御前に立たせるためです。'),
('JPN', '歌罗西书', 51, 1, 23, 'ただし、あなたがたは信仰に土台を据え、堅く立ち、聞いている福音の望みから外れることなく、信仰にとどまらなければなりません。この福音は、天の下のすべての造られたものに宣べ伝えられており、私パウロはそれに仕える者となりました。'),
('JPN', '歌罗西书', 51, 1, 24, '今、私は、あなたがたのために受ける苦しみを喜びとしています。私は、キリストのからだ、すなわち教会のために、自分の身をもって、キリストの苦しみの欠けたところを満たしているのです。'),
('JPN', '歌罗西书', 51, 1, 25, '私は神から委ねられた務めにしたがって、教会に仕える者となりました。あなたがたに神のことばを、'),
('JPN', '歌罗西书', 51, 1, 26, 'すなわち、世々の昔から多くの世代にわたって隠されてきて、今は神の聖徒たちに明らかにされた奥義を、余すところなく伝えるためです。'),
('JPN', '歌罗西书', 51, 1, 27, 'この奥義が異邦人の間でどれほど栄光に富んだものであるか、神は聖徒たちに知らせたいと思われました。この奥義とは、あなたがたの中におられるキリスト、栄光の望みのことです。'),
('JPN', '歌罗西书', 51, 1, 28, '私たちはこのキリストを宣べ伝え、あらゆる知恵をもって、すべての人を諭し、すべての人を教えています。すべての人を、キリストにあって成熟した者として立たせるためです。'),
('JPN', '歌罗西书', 51, 1, 29, 'このために、私は自分のうちに力強く働くキリストの力によって、労苦しながら奮闘しています。'),
('JPN', '歌罗西书', 51, 2, 1, '私が、あなたがたやラオディキアの人たちのために、そのほか私と直接顔を合わせたことがない人たちのために、どんなに苦闘しているか、知ってほしいと思います。'),
('JPN', '歌罗西书', 51, 2, 2, '私が苦闘しているのは、この人たちが愛のうちに結び合わされて心に励ましを受け、さらに、理解することで豊かな全き確信に達し、神の奥義であるキリストを知るようになるためです。'),
('JPN', '歌罗西书', 51, 2, 3, 'このキリストのうちに、知恵と知識の宝がすべて隠されています。'),
('JPN', '歌罗西书', 51, 2, 4, '私がこう言うのは、まことしやかな議論によって、だれもあなたがたを惑わすことのないようにするためです。'),
('JPN', '歌罗西书', 51, 2, 5, '私は肉体においては離れていても、霊においてはあなたがたとともにいて、あなたがたの秩序と、キリストに対する堅い信仰を見て喜んでいます。'),
('JPN', '歌罗西书', 51, 2, 6, 'このように、あなたがたは主キリスト・イエスを受け入れたのですから、キリストにあって歩みなさい。'),
('JPN', '歌罗西书', 51, 2, 7, 'キリストのうちに根ざし、建てられ、教えられたとおり信仰を堅くし、あふれるばかりに感謝しなさい。'),
('JPN', '歌罗西书', 51, 2, 8, 'あの空しいだましごとの哲学によって、だれかの捕らわれの身にならないように、注意しなさい。それは人間の言い伝えによるもの、この世のもろもろの霊によるものであり、キリストによるものではありません。'),
('JPN', '歌罗西书', 51, 2, 9, 'キリストのうちにこそ、神の満ち満ちたご性質が形をとって宿っています。'),
('JPN', '歌罗西书', 51, 2, 10, 'あなたがたは、キリストにあって満たされているのです。キリストはすべての支配と権威のかしらです。'),
('JPN', '歌罗西书', 51, 2, 11, 'キリストにあって、あなたがたは人の手によらない割礼を受けました。肉のからだを脱ぎ捨てて、キリストの割礼を受けたのです。'),
('JPN', '歌罗西书', 51, 2, 12, 'バプテスマにおいて、あなたがたはキリストとともに葬られ、また、キリストとともによみがえらされたのです。キリストを死者の中からよみがえらせた神の力を信じたからです。'),
('JPN', '歌罗西书', 51, 2, 13, '背きのうちにあり、また肉の割礼がなく、死んだ者であったあなたがたを、神はキリストとともに生かしてくださいました。私たちのすべての背きを赦し、'),
('JPN', '歌罗西书', 51, 2, 14, '私たちに不利な、様々な規定で私たちを責め立てている債務証書を無効にし、それを十字架に釘付けにして取り除いてくださいました。'),
('JPN', '歌罗西书', 51, 2, 15, 'そして、様々な支配と権威の武装を解除し、それらをキリストの凱旋の行列に捕虜として加えて、さらしものにされました。'),
('JPN', '歌罗西书', 51, 2, 16, 'こういうわけですから、食べ物と飲み物について、あるいは祭りや新月や安息日のことで、だれかがあなたがたを批判することがあってはなりません。'),
('JPN', '歌罗西书', 51, 2, 17, 'これらは、来たるべきものの影であって、本体はキリストにあります。'),
('JPN', '歌罗西书', 51, 2, 18, '自己卑下や御使い礼拝を喜んでいる者が、あなたがたを断罪することがあってはなりません。彼らは自分が見た幻に拠り頼み、肉の思いによっていたずらに思い上がって、'),
('JPN', '歌罗西书', 51, 2, 19, 'かしらにしっかり結びつくことをしません。このかしらがもとになって、からだ全体は節々と筋によって支えられ、つなぎ合わされ、神に育てられて成長していくのです。'),
('JPN', '歌罗西书', 51, 2, 20, 'もしあなたがたがキリストとともに死んで、この世のもろもろの霊から離れたのなら、どうして、まだこの世に生きているかのように、'),
('JPN', '歌罗西书', 51, 2, 21, '「つかむな、味わうな、さわるな」といった定めに縛られるのですか。'),
('JPN', '歌罗西书', 51, 2, 22, 'これらはすべて、使ったら消滅するものについての定めで、人間の戒めや教えによるものです。'),
('JPN', '歌罗西书', 51, 2, 23, 'これらの定めは、人間の好き勝手な礼拝、自己卑下、肉体の苦行のゆえに知恵のあることのように見えますが、何の価値もなく、肉を満足させるだけです。'),
('JPN', '歌罗西书', 51, 3, 1, 'こういうわけで、あなたがたはキリストとともによみがえらされたのなら、上にあるものを求めなさい。そこでは、キリストが神の右の座に着いておられます。'),
('JPN', '歌罗西书', 51, 3, 2, '上にあるものを思いなさい。地にあるものを思ってはなりません。'),
('JPN', '歌罗西书', 51, 3, 3, 'あなたがたはすでに死んでいて、あなたがたのいのちは、キリストとともに神のうちに隠されているのです。'),
('JPN', '歌罗西书', 51, 3, 4, 'あなたがたのいのちであるキリストが現れると、そのときあなたがたも、キリストとともに栄光のうちに現れます。'),
('JPN', '歌罗西书', 51, 3, 5, 'ですから、地にあるからだの部分、すなわち、淫らな行い、汚れ、情欲、悪い欲、そして貪欲を殺してしまいなさい。貪欲は偶像礼拝です。'),
('JPN', '歌罗西书', 51, 3, 6, 'これらのために、神の怒りが不従順の子らの上に下ります。'),
('JPN', '歌罗西书', 51, 3, 7, 'あなたがたも以前は、そのようなものの中に生き、そのような歩みをしていました。'),
('JPN', '歌罗西书', 51, 3, 8, 'しかし今は、これらすべてを、すなわち、怒り、憤り、悪意、ののしり、あなたがたの口から出る恥ずべきことばを捨てなさい。'),
('JPN', '歌罗西书', 51, 3, 9, '互いに偽りを言ってはいけません。あなたがたは古い人をその行いとともに脱ぎ捨てて、'),
('JPN', '歌罗西书', 51, 3, 10, '新しい人を着たのです。新しい人は、それを造られた方のかたちにしたがって新しくされ続け、真の知識に至ります。'),
('JPN', '歌罗西书', 51, 3, 11, 'そこには、ギリシア人もユダヤ人もなく、割礼のある者もない者も、未開の人も、スキタイ人も、奴隷も自由人もありません。キリストがすべてであり、すべてのうちにおられるのです。'),
('JPN', '歌罗西书', 51, 3, 12, 'ですから、あなたがたは神に選ばれた者、聖なる者、愛されている者として、深い慈愛の心、親切、謙遜、柔和、寛容を着なさい。'),
('JPN', '歌罗西书', 51, 3, 13, '互いに忍耐し合い、だれかがほかの人に不満を抱いたとしても、互いに赦し合いなさい。主があなたがたを赦してくださったように、あなたがたもそうしなさい。'),
('JPN', '歌罗西书', 51, 3, 14, 'そして、これらすべての上に、愛を着けなさい。愛は結びの帯として完全です。'),
('JPN', '歌罗西书', 51, 3, 15, 'キリストの平和が、あなたがたの心を支配するようにしなさい。そのために、あなたがたも召されて一つのからだとなったのです。また、感謝の心を持つ人になりなさい。'),
('JPN', '歌罗西书', 51, 3, 16, 'キリストのことばが、あなたがたのうちに豊かに住むようにしなさい。知恵を尽くして互いに教え、忠告し合い、詩と賛美と霊の歌により、感謝をもって心から神に向かって歌いなさい。'),
('JPN', '歌罗西书', 51, 3, 17, 'ことばであれ行いであれ、何かをするときには、主イエスによって父なる神に感謝し、すべてを主イエスの名において行いなさい。'),
('JPN', '歌罗西书', 51, 3, 18, '妻たちよ。主にある者にふさわしく、夫に従いなさい。'),
('JPN', '歌罗西书', 51, 3, 19, '夫たちよ、妻を愛しなさい。妻に対して辛く当たってはいけません。'),
('JPN', '歌罗西书', 51, 3, 20, '子どもたちよ、すべてのことについて両親に従いなさい。それは主に喜ばれることなのです。'),
('JPN', '歌罗西书', 51, 3, 21, '父たちよ、子どもたちを苛立たせてはいけません。その子たちが意欲を失わないようにするためです。'),
('JPN', '歌罗西书', 51, 3, 22, '奴隷たちよ、すべてのことについて地上の主人に従いなさい。人のご機嫌取りのような、うわべだけの仕え方ではなく、主を恐れつつ、真心から従いなさい。'),
('JPN', '歌罗西书', 51, 3, 23, '何をするにも、人に対してではなく、主に対してするように、心から行いなさい。'),
('JPN', '歌罗西书', 51, 3, 24, 'あなたがたは、主から報いとして御国を受け継ぐことを知っています。あなたがたは主キリストに仕えているのです。'),
('JPN', '歌罗西书', 51, 3, 25, '不正を行う者は、自分が行った不正を報いとして受け取ることになります。不公平な扱いはありません。'),
('JPN', '歌罗西书', 51, 4, 1, '主人たちよ。あなたがたは、自分たちも天に主人を持つ者だと知っているのですから、奴隷に対して正義と公平を示しなさい。'),
('JPN', '歌罗西书', 51, 4, 2, 'たゆみなく祈りなさい。感謝をもって祈りつつ、目を覚ましていなさい。'),
('JPN', '歌罗西书', 51, 4, 3, '同時に、私たちのためにも祈ってください。神がみことばのために門を開いてくださって、私たちがキリストの奥義を語れるように祈ってください。この奥義のために、私は牢につながれています。'),
('JPN', '歌罗西书', 51, 4, 4, 'また、私がこの奥義を、語るべき語り方で明らかに示すことができるように、祈ってください。'),
('JPN', '歌罗西书', 51, 4, 5, '外部の人たちに対しては、機会を十分に活かし、知恵をもって行動しなさい。'),
('JPN', '歌罗西书', 51, 4, 6, 'あなたがたのことばが、いつも親切で、塩味の効いたものであるようにしなさい。そうすれば、一人ひとりにどのように答えたらよいかが分かります。'),
('JPN', '歌罗西书', 51, 4, 7, '私の様子はすべて、愛する兄弟、忠実な奉仕者、主にある同労のしもべであるティキコが、あなたがたに知らせます。'),
('JPN', '歌罗西书', 51, 4, 8, 'ティキコをあなたがたのもとに遣わすのは、ほかでもなく、あなたがたが私たちの様子を知って、心に励ましを受けるためです。'),
('JPN', '歌罗西书', 51, 4, 9, 'また彼は、あなたがたの仲間の一人で、忠実な、愛する兄弟オネシモと一緒に行きます。この二人がこちらの様子をすべて知らせます。'),
('JPN', '歌罗西书', 51, 4, 10, '私とともに囚人となっているアリスタルコと、バルナバのいとこであるマルコが、あなたがたによろしくと言っています。このマルコについては、もし彼があなたがたのところに行ったら迎え入れるように、という指示をあなたがたはすでに受けています。'),
('JPN', '歌罗西书', 51, 4, 11, 'ユストと呼ばれるイエスも、よろしくと言っています。割礼のある人では、この三人だけが神の国のために働く私の同労者です。彼らは私にとって慰めになりました。'),
('JPN', '歌罗西书', 51, 4, 12, 'あなたがたの仲間の一人、キリスト・イエスのしもべエパフラスが、あなたがたによろしくと言っています。彼はいつも、あなたがたが神のみこころのすべてを確信し、成熟した者として堅く立つことができるように、あなたがたのために祈りに励んでいます。'),
('JPN', '歌罗西书', 51, 4, 13, '私はエパフラスのために証言します。彼はあなたがたのため、またラオディキアとヒエラポリスにいる人々のため、たいへん苦労しています。'),
('JPN', '歌罗西书', 51, 4, 14, '愛する医者のルカ、それにデマスが、あなたがたによろしくと言っています。'),
('JPN', '歌罗西书', 51, 4, 15, 'どうか、ラオディキアの兄弟たちに、またニンパと彼女の家にある教会に、よろしく伝えてください。'),
('JPN', '歌罗西书', 51, 4, 16, 'この手紙があなたがたのところで読まれたら、ラオディキア人の教会でも読まれるようにしてください。あなたがたも、ラオディキアから回って来る手紙を読んでください。'),
('JPN', '歌罗西书', 51, 4, 17, 'アルキポに、「主にあって受けた務めを、注意してよく果たすように」と言ってください。'),
('JPN', '歌罗西书', 51, 4, 18, '私パウロが自分の手であいさつを記します。私が牢につながれていることを覚えていてください。どうか、恵みがあなたがたとともにありますように。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 1, 'パウロ、シルワノ、テモテから、父なる神と主イエス・キリストにあるテサロニケ人の教会へ。恵みと平安があなたがたにありますように。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 2, '私たちは、あなたがたのことを覚えて祈るとき、あなたがたすべてについて、いつも神に感謝しています。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 3, '私たちの父である神の御前に、あなたがたの信仰から出た働きと、愛から生まれた労苦、私たちの主イエス・キリストに対する望みに支えられた忍耐を、絶えず思い起こしているからです。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 4, '神に愛されている兄弟たち。私たちは、あなたがたが神に選ばれていることを知っています。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 5, '私たちの福音は、ことばだけでなく、力と聖霊と強い確信を伴って、あなたがたの間に届いたからです。あなたがたのところで、私たちがあなたがたのためにどのように行動していたかは、あなたがたが知っているとおりです。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 6, 'あなたがたも、多くの苦難の中で、聖霊による喜びをもってみことばを受け入れ、私たちに、そして主に倣う者になりました。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 7, 'その結果、あなたがたは、マケドニアとアカイアにいるすべての信者の模範になったのです。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 8, '主のことばがあなたがたのところから出て、マケドニアとアカイアに響き渡っただけでなく、神に対するあなたがたの信仰が、あらゆる場所に伝わっています。そのため、私たちは何も言う必要がありません。'),
('JPN', '帖撒罗尼迦前书', 52, 1, 9, '人々自身が私たちのことを知らせています。私たちがどのようにあなたがたに受け入れてもらったか、また、あなたがたがどのように偶像から神に立ち返って、生けるまことの神に仕えるようになり、'),
('JPN', '帖撒罗尼迦前书', 52, 1, 10, '御子が天から来られるのを待ち望むようになったかを、知らせているのです。この御子こそ、神が死者の中からよみがえらせた方、やがて来る御怒りから私たちを救い出してくださるイエスです。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 1, '兄弟たち。あなたがた自身が知っているとおり、私たちがあなたがたのところに行ったことは、無駄になりませんでした。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 2, 'それどころか、ご存じのように、私たちは先にピリピで苦しみにあい、辱めを受けていたのですが、私たちの神によって勇気づけられて、激しい苦闘のうちにも神の福音をあなたがたに語りました。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 3, '私たちの勧めは、誤りから出ているものでも、不純な心から出ているものでもなく、だましごとでもありません。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 4, 'むしろ私たちは、神に認められて福音を委ねられた者ですから、それにふさわしく、人を喜ばせるのではなく、私たちの心をお調べになる神に喜んでいただこうとして、語っているのです。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 5, 'あなたがたが知っているとおり、私たちは今まで、へつらいのことばを用いたり、貪りの口実を設けたりしたことはありません。神がそのことの証人です。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 6, 'また私たちは、あなたがたからも、ほかの人たちからも、人からの栄誉は求めませんでした。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 7, 'キリストの使徒として権威を主張することもできましたが、あなたがたの間では幼子になりました。私たちは、自分の子どもたちを養い育てる母親のように、'),
('JPN', '帖撒罗尼迦前书', 52, 2, 8, 'あなたがたをいとおしく思い、神の福音だけではなく、自分自身のいのちまで、喜んであなたがたに与えたいと思っています。あなたがたが私たちの愛する者となったからです。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 9, '兄弟たち。あなたがたは私たちの労苦と辛苦を覚えているでしょう。私たちは、あなたがたのだれにも負担をかけないように、夜も昼も働きながら、神の福音をあなたがたに宣べ伝えました。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 10, 'また、信者であるあなたがたに対して、私たちが敬虔に、正しく、また責められるところがないようにふるまったことについては、あなたがたが証人であり、神もまた証人です。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 11, 'また、あなたがたが知っているとおり、私たちは自分の子どもに向かう父親のように、あなたがた一人ひとりに、'),
('JPN', '帖撒罗尼迦前书', 52, 2, 12, 'ご自分の御国と栄光にあずかるようにと召してくださる神にふさわしく歩むよう、勧め、励まし、厳かに命じました。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 13, 'こういうわけで、私たちもまた、絶えず神に感謝しています。あなたがたが、私たちから聞いた神のことばを受けたとき、それを人間のことばとしてではなく、事実そのとおり神のことばとして受け入れてくれたからです。この神のことばは、信じているあなたがたのうちに働いています。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 14, '兄弟たち。あなたがたはユダヤの、キリスト・イエスにある神の諸教会に倣う者となりました。彼らがユダヤ人たちに苦しめられたように、あなたがたも自分の同胞に苦しめられたからです。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 15, 'ユダヤ人たちは、主であるイエスと預言者たちを殺し、私たちを迫害し、神に喜ばれることをせず、すべての人と対立しています。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 16, '彼らは、異邦人たちが救われるように私たちが語るのを妨げ、こうしていつも、自分たちの罪が満ちるようにしているのです。しかし、御怒りは彼らの上に臨んで極みに達しています。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 17, '兄弟たち。私たちは、しばらくの間あなたがたから引き離されていました。といっても、顔を見ないだけで、心が離れていたわけではありません。そのため、あなたがたの顔を見たいと、なおいっそう切望しました。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 18, 'それで私たちは、あなたがたのところに行こうとしました。私パウロは何度も行こうとしました。しかし、サタンが私たちを妨げたのです。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 19, '私たちの主イエスが再び来られるとき、御前で私たちの望み、喜び、誇りの冠となるのは、いったいだれでしょうか。あなたがたではありませんか。'),
('JPN', '帖撒罗尼迦前书', 52, 2, 20, 'あなたがたこそ私たちの栄光であり、喜びなのです。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 1, 'そこで、私たちはもはや耐えきれなくなり、私たちだけがアテネに残ることにして、'),
('JPN', '帖撒罗尼迦前书', 52, 3, 2, '私たちの兄弟であり、キリストの福音を伝える神の同労者であるテモテを遣わしたのです。あなたがたを信仰において強め励まし、'),
('JPN', '帖撒罗尼迦前书', 52, 3, 3, 'このような苦難の中にあっても、だれも動揺することがないようにするためでした。あなたがた自身が知っているとおり、私たちはこのような苦難にあうように定められているのです。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 4, 'あなたがたのところにいたとき、私たちは前もって、苦難にあうようになると言っておいたのですが、あなたがたが知っているとおり、それは事実となりました。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 5, 'そういうわけで、私ももはや耐えられなくなって、あなたがたの信仰の様子を知るために、テモテを遣わしたのです。それは、誘惑する者があなたがたを誘惑して、私たちの労苦が無駄にならないようにするためでした。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 6, 'ところが今、テモテがあなたがたのところから私たちのもとに帰って来て、あなたがたの信仰と愛について良い知らせを伝えてくれました。また、あなたがたが私たちのことを、いつも好意をもって思い起こし、私たちがあなたがたに会いたいと思っているように、あなたがたも私たちに会いたがっていることを知らせてくれました。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 7, 'こういうわけで、兄弟たち。私たちはあらゆる苦悩と苦難のうちにありながら、あなたがたのことでは慰めを受けました。あなたがたの信仰による慰めです。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 8, 'あなたがたが主にあって堅く立っているなら、今、私たちの心は生き返るからです。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 9, 'あなたがたのことで、どれほどの感謝を神におささげできるでしょうか。神の御前であなたがたのことを喜んでいる、そのすべての喜びのゆえに。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 10, '私たちは、あなたがたの顔を見て、あなたがたの信仰で不足しているものを補うことができるようにと、夜昼、熱心に祈っています。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 11, 'どうか、私たちの父である神ご自身と、私たちの主イエスが、私たちの道を開いて、あなたがたのところに行かせてくださいますように。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 12, '私たちがあなたがたを愛しているように、あなたがたの互いに対する愛を、またすべての人に対する愛を、主が豊かにし、あふれさせてくださいますように。'),
('JPN', '帖撒罗尼迦前书', 52, 3, 13, 'そして、あなたがたの心を強めて、私たちの主イエスがご自分のすべての聖徒たちとともに来られるときに、私たちの父である神の御前で、聖であり、責められるところのない者としてくださいますように。アーメン。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 1, '最後に兄弟たち。主イエスにあってお願いし、また勧めます。あなたがたは、神に喜ばれるためにどのように歩むべきかを私たちから学び、現にそう歩んでいるのですから、ますますそうしてください。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 2, '私たちが主イエスによって、どのような命令をあなたがたに与えたか、あなたがたは知っています。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 3, '神のみこころは、あなたがたが聖なる者となることです。あなたがたが淫らな行いを避け、'),
('JPN', '帖撒罗尼迦前书', 52, 4, 4, '一人ひとりがわきまえて、自分のからだを聖なる尊いものとして保ち、'),
('JPN', '帖撒罗尼迦前书', 52, 4, 5, '神を知らない異邦人のように情欲におぼれず、'),
('JPN', '帖撒罗尼迦前书', 52, 4, 6, 'また、そのようなことで、兄弟を踏みつけたり欺いたりしないことです。私たちが前もってあなたがたに話し、厳しく警告しておいたように、主はこれらすべてのことについて罰を与える方だからです。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 7, '神が私たちを召されたのは、汚れたことを行わせるためではなく、聖さにあずからせるためです。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 8, 'ですから、この警告を拒む者は、人を拒むのではなく、あなたがたにご自分の聖霊を与えてくださる神を拒むのです。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 9, '兄弟愛については、あなたがたに書き送る必要がありません。あなたがたこそ、互いに愛し合うことを神から教えられた人たちで、'),
('JPN', '帖撒罗尼迦前书', 52, 4, 10, 'マケドニア全土のすべての兄弟たちに対して、それを実行しているからです。兄弟たち、あなたがたに勧めます。ますます豊かにそれを行いなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 11, 'また、私たちが命じたように、落ち着いた生活をし、自分の仕事に励み、自分の手で働くことを名誉としなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 12, '外の人々に対して品位をもって歩み、だれの世話にもならずに生活するためです。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 13, '眠っている人たちについては、兄弟たち、あなたがたに知らずにいてほしくありません。あなたがたが、望みのない他の人々のように悲しまないためです。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 14, 'イエスが死んで復活された、と私たちが信じているなら、神はまた同じように、イエスにあって眠った人たちを、イエスとともに連れて来られるはずです。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 15, '私たちは主のことばによって、あなたがたに伝えます。生きている私たちは、主の来臨まで残っているなら、眠った人たちより先になることは決してありません。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 16, 'すなわち、号令と御使いのかしらの声と神のラッパの響きとともに、主ご自身が天から下って来られます。そしてまず、キリストにある死者がよみがえり、'),
('JPN', '帖撒罗尼迦前书', 52, 4, 17, 'それから、生き残っている私たちが、彼らと一緒に雲に包まれて引き上げられ、空中で主と会うのです。こうして私たちは、いつまでも主とともにいることになります。'),
('JPN', '帖撒罗尼迦前书', 52, 4, 18, 'ですから、これらのことばをもって互いに励まし合いなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 1, '兄弟たち。その時と時期については、あなたがたに書き送る必要はありません。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 2, '主の日は、盗人が夜やって来るように来ることを、あなたがた自身よく知っているからです。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 3, '人々が「平和だ、安全だ」と言っているとき、妊婦に産みの苦しみが臨むように、突然の破滅が彼らを襲います。それを逃れることは決してできません。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 4, 'しかし、兄弟たち。あなたがたは暗闇の中にいないので、その日が盗人のようにあなたがたを襲うことはありません。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 5, 'あなたがたはみな、光の子ども、昼の子どもなのです。私たちは夜の者、闇の者ではありません。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 6, 'ですから、ほかの者たちのように眠っていないで、目を覚まし、身を慎んでいましょう。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 7, '眠る者は夜眠り、酔う者は夜酔うのです。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 8, 'しかし、私たちは昼の者なので、信仰と愛の胸当てを着け、救いの望みというかぶとをかぶり、身を慎んでいましょう。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 9, '神は、私たちが御怒りを受けるようにではなく、主イエス・キリストによる救いを得るように定めてくださったからです。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 10, '主が私たちのために死んでくださったのは、私たちが、目を覚ましていても眠っていても、主とともに生きるようになるためです。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 11, 'ですからあなたがたは、現に行っているとおり、互いに励まし合い、互いを高め合いなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 12, '兄弟たち、あなたがたにお願いします。あなたがたの間で労苦し、主にあってあなたがたを指導し、訓戒している人たちを重んじ、'),
('JPN', '帖撒罗尼迦前书', 52, 5, 13, 'その働きのゆえに、愛をもって、この上ない尊敬を払いなさい。また、お互いに平和を保ちなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 14, '兄弟たち、あなたがたに勧めます。怠惰な者を諭し、小心な者を励まし、弱い者の世話をし、すべての人に対して寛容でありなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 15, 'だれも、悪に対して悪を返さないように気をつけ、互いの間で、またすべての人に対して、いつも善を行うように努めなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 16, 'いつも喜んでいなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 17, '絶えず祈りなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 18, 'すべてのことにおいて感謝しなさい。これが、キリスト・イエスにあって神があなたがたに望んでおられることです。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 19, '御霊を消してはいけません。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 20, '預言を軽んじてはいけません。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 21, 'ただし、すべてを吟味し、良いものはしっかり保ちなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 22, 'あらゆる形の悪から離れなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 23, '平和の神ご自身が、あなたがたを完全に聖なるものとしてくださいますように。あなたがたの霊、たましい、からだのすべてが、私たちの主イエス・キリストの来臨のときに、責められるところのないものとして保たれていますように。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 24, 'あなたがたを召された方は真実ですから、そのようにしてくださいます。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 25, '兄弟たち、私たちのためにも祈ってください。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 26, 'すべての兄弟たちに、聖なる口づけをもってあいさつをしなさい。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 27, 'この手紙をすべての兄弟たちに読んで聞かせるよう、私は主によって堅く命じます。'),
('JPN', '帖撒罗尼迦前书', 52, 5, 28, '私たちの主イエス・キリストの恵みが、あなたがたとともにありますように。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 1, 'パウロ、シルワノ、テモテから、私たちの父なる神と主イエス・キリストにあるテサロニケ人の教会へ。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 2, '私たちの父なる神と主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 3, '兄弟たち。あなたがたについて、私たちはいつも神に感謝しなければなりません。それは当然のことです。あなたがたの信仰が大いに成長し、あなたがたすべての間で、一人ひとりの互いに対する愛が増し加わっているからです。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 4, 'ですから私たち自身、神の諸教会の間であなたがたを誇りに思っています。あなたがたはあらゆる迫害と苦難に耐えながら、忍耐と信仰を保っています。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 5, 'それは、あなたがたを神の国にふさわしいものと認める、神の正しいさばきがあることの証拠です。あなたがたが苦しみを受けているのは、この神の国のためです。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 6, '神にとって正しいこととは、あなたがたを苦しめる者には、報いとして苦しみを与え、'),
('JPN', '帖撒罗尼迦后书', 53, 1, 7, '苦しめられているあなたがたには、私たちとともに、報いとして安息を与えることです。このことは、主イエスが、燃える炎の中に、力ある御使いたちとともに天から現れるときに起こります。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 8, '主は、神を知らない人々や、私たちの主イエスの福音に従わない人々に罰を与えられます。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 9, 'そのような者たちは、永遠の滅びという刑罰を受け、主の御前から、そして、その御力の栄光から退けられることになります。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 10, 'その日に主イエスは来て、ご自分の聖徒たちの間であがめられ、信じたすべての者たちの間で感嘆の的となられます。そうです、あなたがたに対する私たちの証しを、あなたがたは信じたのです。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 11, 'こうしたことのため、私たちはいつも、あなたがたのために祈っています。どうか私たちの神が、あなたがたを召しにふさわしい者にし、また御力によって、善を求めるあらゆる願いと、信仰から出た働きを実現してくださいますように。'),
('JPN', '帖撒罗尼迦后书', 53, 1, 12, 'それは、私たちの神であり主であるイエス・キリストの恵みによって、私たちの主イエスの名があなたがたの間であがめられ、あなたがたも主にあって栄光を受けるためです。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 1, 'さて兄弟たち。私たちの主イエス・キリストの来臨と、私たちが主のみもとに集められることに関して、あなたがたにお願いします。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 2, '霊によってであれ、ことばによってであれ、私たちから出たかのような手紙によってであれ、主の日がすでに来たかのように言われるのを聞いても、すぐに落ち着きを失ったり、心を騒がせたりしないでください。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 3, 'どんな手段によっても、だれにもだまされてはいけません。まず背教が起こり、不法の者、すなわち滅びの子が現れなければ、主の日は来ないのです。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 4, '不法の者は、すべて神と呼ばれるもの、礼拝されるものに対抗して自分を高く上げ、ついには自分こそ神であると宣言して、神の宮に座ることになります。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 5, '私がまだあなたがたのところにいたとき、これらのことをよく話していたのを覚えていませんか。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 6, '不法の者がその定められた時に現れるようにと、今はその者を引き止めているものがあることを、あなたがたは知っています。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 7, '不法の秘密はすでに働いています。ただし、秘密であるのは、今引き止めている者が取り除かれる時までのことです。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 8, 'その時になると、不法の者が現れますが、主イエスは彼を御口の息をもって殺し、来臨の輝きをもって滅ぼされます。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 9, '不法の者は、サタンの働きによって到来し、あらゆる力、偽りのしるしと不思議、'),
('JPN', '帖撒罗尼迦后书', 53, 2, 10, 'また、あらゆる悪の欺きをもって、滅びる者たちに臨みます。彼らが滅びるのは、自分を救う真理を愛をもって受け入れなかったからです。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 11, 'それで神は、惑わす力を送られ、彼らは偽りを信じるようになります。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 12, 'それは、真理を信じないで、不義を喜んでいたすべての者が、さばかれるようになるためです。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 13, 'しかし、主に愛されている兄弟たち。私たちはあなたがたのことについて、いつも神に感謝しなければなりません。神が、御霊による聖別と、真理に対する信仰によって、あなたがたを初穂として救いに選ばれたからです。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 14, 'そのために神は、私たちの福音によってあなたがたを召し、私たちの主イエス・キリストの栄光にあずからせてくださいました。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 15, 'ですから兄弟たち。堅く立って、語ったことばであれ手紙であれ、私たちから学んだ教えをしっかりと守りなさい。'),
('JPN', '帖撒罗尼迦后书', 53, 2, 16, 'どうか、私たちの主イエス・キリストと、私たちの父なる神、すなわち、私たちを愛し、永遠の慰めとすばらしい望みを恵みによって与えてくださった方ご自身が、'),
('JPN', '帖撒罗尼迦后书', 53, 2, 17, 'あなたがたの心を慰め、強めて、あらゆる良いわざとことばに進ませてくださいますように。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 1, '最後に兄弟たち、私たちのために祈ってください。主のことばが、あなたがたのところと同じように速やかに広まり、尊ばれるように。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 2, 'また、私たちが、ひねくれた悪人どもから救い出されるように祈ってください。すべての人に信仰があるわけではないからです。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 3, 'しかし、主は真実な方です。あなたがたを強くし、悪い者から守ってくださいます。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 4, '私たちが命じることを、あなたがたは実行していますし、これからも実行してくれると、私たちは主にあって確信しています。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 5, '主があなたがたの心を導いて、神の愛とキリストの忍耐に向けさせてくださいますように。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 6, '兄弟たち、私たちの主イエス・キリストの名によって命じます。怠惰な歩みをして、私たちから受け継いだ教えに従わない兄弟は、みな避けなさい。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 7, 'どのように私たちを見習うべきか、あなたがた自身が知っているのです。あなたがたの間で、私たちは怠惰に暮らすことはなく、'),
('JPN', '帖撒罗尼迦后书', 53, 3, 8, '人からただでもらったパンを食べることもしませんでした。むしろ、あなたがたのだれにも負担をかけないように、夜昼、労し苦しみながら働きました。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 9, '私たちに権利がなかったからではなく、あなたがたが私たちを見習うように、身をもって模範を示すためでした。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 10, 'あなたがたのところにいたとき、働きたくない者は食べるな、と私たちは命じました。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 11, 'ところが、あなたがたの中には、怠惰な歩みをしている人たち、何も仕事をせずにおせっかいばかり焼いている人たちがいると聞いています。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 12, 'そのような人たちに、主イエス・キリストによって命じ、勧めます。落ち着いて仕事をし、自分で得たパンを食べなさい。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 13, '兄弟たち、あなたがたは、たゆまず良い働きをしなさい。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 14, 'もし、この手紙に書いた私たちのことばに従わない者がいれば、そのような人には注意を払い、交際しないようにしなさい。その人が恥じ入るようになるためです。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 15, 'しかし、敵とは見なさないで、兄弟として諭しなさい。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 16, 'どうか、平和の主ご自身が、どんな時にも、どんな場合にも、あなたがたに平和を与えてくださいますように。どうか、主があなたがたすべてとともにいてくださいますように。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 17, '私パウロが自分の手であいさつを記します。これは、私のどの手紙にもあるしるしです。このように私は書くのです。'),
('JPN', '帖撒罗尼迦后书', 53, 3, 18, '私たちの主イエス・キリストの恵みが、あなたがたすべてとともにありますように。'),
('JPN', '提摩太前书', 54, 1, 1, '私たちの救い主である神と、私たちの望みであるキリスト・イエスの命令によって、キリスト・イエスの使徒となったパウロから、'),
('JPN', '提摩太前书', 54, 1, 2, '信仰による、真のわが子テモテへ。父なる神と私たちの主キリスト・イエスから、恵みとあわれみと平安がありますように。'),
('JPN', '提摩太前书', 54, 1, 3, '私がマケドニアに行くときに言ったように、あなたはエペソにとどまり、ある人たちが違った教えを説いたり、'),
('JPN', '提摩太前书', 54, 1, 4, '果てしない作り話と系図に心を寄せたりしないように命じなさい。そのようなものは、論議を引き起こすだけで、神に委ねられた信仰の務めを実現させることにはなりません。'),
('JPN', '提摩太前书', 54, 1, 5, 'この命令が目指す目標は、きよい心と健全な良心と偽りのない信仰から生まれる愛です。'),
('JPN', '提摩太前书', 54, 1, 6, 'ある人たちはこれらのものを見失い、むなしい議論に迷い込み、'),
('JPN', '提摩太前书', 54, 1, 7, '律法の教師でありたいと望みながら、自分の言っていることも、確信をもって主張している事柄についても理解していません。'),
('JPN', '提摩太前书', 54, 1, 8, '私たちは知っています。律法は、次のことを知っていて適切に用いるなら、良いものです。'),
('JPN', '提摩太前书', 54, 1, 9, 'すなわち、律法は正しい人のためにあるのではなく、不法な者や不従順な者、不敬虔な者や罪深い者、汚れた者や俗悪な者、父を殺す者や母を殺す者、人を殺す者、'),
('JPN', '提摩太前书', 54, 1, 10, '淫らな者、男色をする者、人を誘拐する者、噓をつく者、偽証する者のために、また、そのほかの健全な教えに反する行為のためにあるのです。'),
('JPN', '提摩太前书', 54, 1, 11, '祝福に満ちた神の、栄光の福音によれば、そうなのであって、私はその福音を委ねられたのです。'),
('JPN', '提摩太前书', 54, 1, 12, '私は、私を強くしてくださる、私たちの主キリスト・イエスに感謝しています。キリストは私を忠実な者と認めて、この務めに任命してくださったからです。'),
('JPN', '提摩太前书', 54, 1, 13, '私は以前には、神を冒瀆する者、迫害する者、暴力をふるう者でした。しかし、信じていないときに知らないでしたことだったので、あわれみを受けました。'),
('JPN', '提摩太前书', 54, 1, 14, '私たちの主の恵みは、キリスト・イエスにある信仰と愛とともに満ちあふれました。'),
('JPN', '提摩太前书', 54, 1, 15, '「キリスト・イエスは罪人を救うために世に来られた」ということばは真実であり、そのまま受け入れるに値するものです。私はその罪人のかしらです。'),
('JPN', '提摩太前书', 54, 1, 16, 'しかし、私はあわれみを受けました。それは、キリスト・イエスがこの上ない寛容をまず私に示し、私を、ご自分を信じて永遠のいのちを得ることになる人々の先例にするためでした。'),
('JPN', '提摩太前书', 54, 1, 17, 'どうか、世々の王、すなわち、朽ちることなく、目に見えない唯一の神に、誉れと栄光が世々限りなくありますように。アーメン。'),
('JPN', '提摩太前书', 54, 1, 18, '私の子テモテよ。以前あなたについてなされた預言にしたがって、私はあなたにこの命令を委ねます。それは、あなたがあの預言によって、信仰と健全な良心を保ち、立派に戦い抜くためです。'),
('JPN', '提摩太前书', 54, 1, 19, 'ある人たちは健全な良心を捨てて、信仰の破船にあいました。'),
('JPN', '提摩太前书', 54, 1, 20, 'その中には、ヒメナイとアレクサンドロがいます。私は、神を冒瀆してはならないことを学ばせるため、彼らをサタンに引き渡しました。'),
('JPN', '提摩太前书', 54, 2, 1, 'そこで、私は何よりもまず勧めます。すべての人のために、王たちと高い地位にあるすべての人のために願い、祈り、とりなし、感謝をささげなさい。'),
('JPN', '提摩太前书', 54, 2, 2, 'それは、私たちがいつも敬虔で品位を保ち、平安で落ち着いた生活を送るためです。'),
('JPN', '提摩太前书', 54, 2, 3, 'そのような祈りは、私たちの救い主である神の御前において良いことであり、喜ばれることです。'),
('JPN', '提摩太前书', 54, 2, 4, '神は、すべての人が救われて、真理を知るようになることを望んでおられます。'),
('JPN', '提摩太前书', 54, 2, 5, '神は唯一です。神と人との間の仲介者も唯一であり、それは人としてのキリスト・イエスです。'),
('JPN', '提摩太前书', 54, 2, 6, 'キリストは、すべての人の贖いの代価として、ご自分を与えてくださいました。これは、定められた時になされた証しです。'),
('JPN', '提摩太前书', 54, 2, 7, 'その証しのために、私は宣教者、使徒、そして、信仰と真理を異邦人に教える教師に任命されました。私は真実を言っていて、偽ってはいません。'),
('JPN', '提摩太前书', 54, 2, 8, 'そういうわけで、私はこう願っています。男たちは怒ったり言い争ったりせずに、どこででも、きよい手を上げて祈りなさい。'),
('JPN', '提摩太前书', 54, 2, 9, '同じように女たちも、つつましい身なりで、控えめに慎み深く身を飾り、はでな髪型や、金や真珠や高価な衣服ではなく、'),
('JPN', '提摩太前书', 54, 2, 10, '神を敬うと言っている女たちにふさわしく、良い行いで自分を飾りなさい。'),
('JPN', '提摩太前书', 54, 2, 11, '女は、よく従う心をもって静かに学びなさい。'),
('JPN', '提摩太前书', 54, 2, 12, '私は、女が教えたり男を支配したりすることを許しません。むしろ、静かにしていなさい。'),
('JPN', '提摩太前书', 54, 2, 13, 'アダムが初めに造られ、それからエバが造られたからです。'),
('JPN', '提摩太前书', 54, 2, 14, 'そして、アダムはだまされませんでしたが、女はだまされて過ちを犯したのです。'),
('JPN', '提摩太前书', 54, 2, 15, '女は、慎みをもって、信仰と愛と聖さにとどまるなら、子を産むことによって救われます。'),
('JPN', '提摩太前书', 54, 3, 1, '次のことばは真実です。「もしだれかが監督の職に就きたいと思うなら、それは立派な働きを求めることである。」'),
('JPN', '提摩太前书', 54, 3, 2, 'ですから監督は、非難されるところがなく、一人の妻の夫であり、自分を制し、慎み深く、礼儀正しく、よくもてなし、教える能力があり、'),
('JPN', '提摩太前书', 54, 3, 3, '酒飲みでなく、乱暴でなく、柔和で、争わず、金銭に無欲で、'),
('JPN', '提摩太前书', 54, 3, 4, '自分の家庭をよく治め、十分な威厳をもって子どもを従わせている人でなければなりません。'),
('JPN', '提摩太前书', 54, 3, 5, '自分自身の家庭を治めることを知らない人が、どうして神の教会を世話することができるでしょうか。'),
('JPN', '提摩太前书', 54, 3, 6, 'また、信者になったばかりの人であってはいけません。高慢になって、悪魔と同じさばきを受けることにならないようにするためです。'),
('JPN', '提摩太前书', 54, 3, 7, 'また、教会の外の人々にも評判の良い人でなければなりません。嘲られて、悪魔の罠に陥らないようにするためです。'),
('JPN', '提摩太前书', 54, 3, 8, '同じように執事たちも、品位があり、二枚舌を使わず、大酒飲みでなく、不正な利を求めず、'),
('JPN', '提摩太前书', 54, 3, 9, 'きよい良心をもって、信仰の奥義を保っている人でなければなりません。'),
('JPN', '提摩太前书', 54, 3, 10, 'この人たちも、まず審査を受けさせなさい。そして、非難される点がなければ、執事として仕えさせなさい。'),
('JPN', '提摩太前书', 54, 3, 11, 'この奉仕に就く女の人も同じように、品位があり、人を中傷する者でなく、自分を制し、すべてに忠実な人でなければなりません。'),
('JPN', '提摩太前书', 54, 3, 12, '執事は一人の妻の夫であって、子どもと家庭をよく治める人でなければなりません。'),
('JPN', '提摩太前书', 54, 3, 13, '執事として立派に仕えた人は、良い地歩を占め、また、キリスト・イエスを信じる信仰について、強い確信を持つことができるのです。'),
('JPN', '提摩太前书', 54, 3, 14, '私は、近いうちにあなたのところに行きたいと思いながら、これらのことを書いています。'),
('JPN', '提摩太前书', 54, 3, 15, 'たとえ遅くなった場合でも、神の家でどのように行動すべきかを、あなたに知っておいてもらうためです。神の家とは、真理の柱と土台である、生ける神の教会のことです。'),
('JPN', '提摩太前书', 54, 3, 16, 'だれもが認めるように、この敬虔の奥義は偉大です。「キリストは肉において現れ、霊において義とされ、御使いたちに見られ、諸国の民の間で宣べ伝えられ、世界中で信じられ、栄光のうちに上げられた。」'),
('JPN', '提摩太前书', 54, 4, 1, 'しかし、御霊が明らかに言われるように、後の時代になると、ある人たちは惑わす霊と悪霊の教えとに心を奪われ、信仰から離れるようになります。'),
('JPN', '提摩太前书', 54, 4, 2, 'それは、良心が麻痺した、偽りを語る者たちの偽善によるものです。'),
('JPN', '提摩太前书', 54, 4, 3, '彼らは結婚することを禁じたり、食物を断つことを命じたりします。しかし食物は、信仰があり、真理を知っている人々が感謝して受けるように、神が造られたものです。'),
('JPN', '提摩太前书', 54, 4, 4, '神が造られたものはすべて良いもので、感謝して受けるとき、捨てるべきものは何もありません。'),
('JPN', '提摩太前书', 54, 4, 5, '神のことばと祈りによって、聖なるものとされるからです。'),
('JPN', '提摩太前书', 54, 4, 6, 'これらのことを兄弟たちに教えるなら、あなたは、信仰のことばと、自分が従ってきた良い教えのことばで養われて、キリスト・イエスの立派な奉仕者になります。'),
('JPN', '提摩太前书', 54, 4, 7, '俗悪で愚にもつかない作り話を避けなさい。むしろ、敬虔のために自分自身を鍛錬しなさい。'),
('JPN', '提摩太前书', 54, 4, 8, '肉体の鍛錬も少しは有益ですが、今のいのちと来たるべきいのちを約束する敬虔は、すべてに有益です。'),
('JPN', '提摩太前书', 54, 4, 9, 'このことばは真実であり、そのまま受け入れるに値するものです。'),
('JPN', '提摩太前书', 54, 4, 10, '私たちが労苦し、苦闘しているのは、すべての人々、特に信じる人々の救い主である生ける神に、望みを置いているからです。'),
('JPN', '提摩太前书', 54, 4, 11, 'あなたはこれらのことを命じ、また教えなさい。'),
('JPN', '提摩太前书', 54, 4, 12, 'あなたは、年が若いからといって、だれにも軽く見られないようにしなさい。むしろ、ことば、態度、愛、信仰、純潔において信者の模範となりなさい。'),
('JPN', '提摩太前书', 54, 4, 13, '私が行くまで、聖書の朗読と勧めと教えに専念しなさい。'),
('JPN', '提摩太前书', 54, 4, 14, '長老たちによる按手を受けたとき、預言によって与えられた、あなたのうちにある賜物を軽んじてはいけません。'),
('JPN', '提摩太前书', 54, 4, 15, 'これらのことに心を砕き、ひたすら励みなさい。そうすれば、あなたの進歩はすべての人に明らかになるでしょう。'),
('JPN', '提摩太前书', 54, 4, 16, '自分自身にも、教えることにも、よく気をつけなさい。働きをあくまでも続けなさい。そうすれば、自分自身と、あなたの教えを聞く人たちとを、救うことになるのです。'),
('JPN', '提摩太前书', 54, 5, 1, '年配の男の人を叱ってはいけません。むしろ、父親に対するように勧めなさい。若い人には兄弟に対するように、'),
('JPN', '提摩太前书', 54, 5, 2, '年配の女の人には母親に対するように、若い女の人には姉妹に対するように、真に純粋な心で勧めなさい。'),
('JPN', '提摩太前书', 54, 5, 3, 'やもめの中の本当のやもめを大事にしなさい。'),
('JPN', '提摩太前书', 54, 5, 4, 'もし、やもめに子どもか孫がいるなら、まずその人たちに、自分の家の人に敬愛を示して、親の恩に報いることを学ばせなさい。それが神の御前に喜ばれることです。'),
('JPN', '提摩太前书', 54, 5, 5, '身寄りのない本当のやもめは、望みを神に置いて、夜昼、絶えず神に願いと祈りをささげていますが、'),
('JPN', '提摩太前书', 54, 5, 6, '自堕落な生活をしているやもめは、生きてはいても死んでいるのです。'),
('JPN', '提摩太前书', 54, 5, 7, '彼女たちが非難されることのないように、これらのことも命じなさい。'),
('JPN', '提摩太前书', 54, 5, 8, 'もしも親族、特に自分の家族の世話をしない人がいるなら、その人は信仰を否定しているのであって、不信者よりも劣っているのです。'),
('JPN', '提摩太前书', 54, 5, 9, 'やもめとして名簿に載せるのは、六十歳未満ではなく、一人の夫の妻であった人で、'),
('JPN', '提摩太前书', 54, 5, 10, '良い行いによって認められている人、すなわち、子どもを育て、旅人をもてなし、聖徒の足を洗い、困っている人を助けるなど、すべての良いわざに励んだ人にしなさい。'),
('JPN', '提摩太前书', 54, 5, 11, '若いやもめの登録は断りなさい。彼女たちは、キリストに背いて情欲にかられると、結婚したがり、'),
('JPN', '提摩太前书', 54, 5, 12, '初めの誓いを捨ててしまったと非難を受けることになるからです。'),
('JPN', '提摩太前书', 54, 5, 13, 'そのうえ、怠けて、家々を歩き回ることを覚えます。ただ怠けるだけでなく、うわさ話やおせっかいをして、話さなくてよいことまで話すのです。'),
('JPN', '提摩太前书', 54, 5, 14, 'ですから、私が願うのは、若いやもめは結婚し、子を産み、家庭を治め、反対者にそしる機会をいっさい与えないことです。'),
('JPN', '提摩太前书', 54, 5, 15, 'すでに道を踏み外し、サタンの後について行ったやもめたちがいるからです。'),
('JPN', '提摩太前书', 54, 5, 16, 'もし信者である女の人に、やもめの身内がいるなら、その人がそのやもめを助けて、教会に負担をかけないようにしなさい。そうすれば、教会は本当のやもめを助けることができます。'),
('JPN', '提摩太前书', 54, 5, 17, 'よく指導している長老は、二倍の尊敬を受けるにふさわしいとしなさい。みことばと教えのために労苦している長老は特にそうです。'),
('JPN', '提摩太前书', 54, 5, 18, '聖書に「脱穀をしている牛に口籠をはめてはならない」、また「働く者が報酬を受けるのは当然である」と言われているからです。'),
('JPN', '提摩太前书', 54, 5, 19, '長老に対する訴えは、二人か三人の証人がいなければ、受理してはいけません。'),
('JPN', '提摩太前书', 54, 5, 20, '罪を犯している者をすべての人の前で責めなさい。そうすれば、ほかの人たちも恐れを抱くでしょう。'),
('JPN', '提摩太前书', 54, 5, 21, '私は、神とキリスト・イエスと選ばれた御使いたちの前で、あなたに厳かに命じます。これらのことを先入観なしに守り、何事もえこひいきせずに行いなさい。'),
('JPN', '提摩太前书', 54, 5, 22, 'だれにも性急に按手をしてはいけません。また、ほかの人の罪に加担してはいけません。自分を清く保ちなさい。'),
('JPN', '提摩太前书', 54, 5, 23, 'これからは水ばかり飲まないで、胃のために、また、たびたび起こる病気のために、少量のぶどう酒を用いなさい。'),
('JPN', '提摩太前书', 54, 5, 24, 'ある人たちの罪は、さばきを受ける前から明らかですが、ほかの人たちの罪は後で明らかになります。'),
('JPN', '提摩太前书', 54, 5, 25, '同じように、良い行いも明らかですが、そうでない場合でも、隠れたままでいることはありません。'),
('JPN', '提摩太前书', 54, 6, 1, '奴隷としてくびきの下にある人はみな、自分の主人をあらゆる面で尊敬に値する人と思わなければなりません。神の御名と教えが悪く言われないようにするためです。'),
('JPN', '提摩太前书', 54, 6, 2, '信者である主人を持つ人は、主人が兄弟だからといって軽んじることなく、むしろ、ますますよく仕えなさい。その良い行いから益を受けるのは信者であり、愛されている人なのですから。あなたはこれらのことを教え、また勧めなさい。'),
('JPN', '提摩太前书', 54, 6, 3, '違ったことを教え、私たちの主イエス・キリストの健全なことばと、敬虔にかなう教えに同意しない者がいるなら、'),
('JPN', '提摩太前书', 54, 6, 4, 'その人は高慢になっていて、何一つ理解しておらず、議論やことばの争いをする病気にかかっているのです。そこから、ねたみ、争い、ののしり、邪推、絶え間ない言い争いが生じます。'),
('JPN', '提摩太前书', 54, 6, 5, 'これらは、知性が腐って真理を失い、敬虔を利得の手段と考える者たちの間に生じるのです。'),
('JPN', '提摩太前书', 54, 6, 6, 'しかし、満ち足りる心を伴う敬虔こそが、大きな利益を得る道です。'),
('JPN', '提摩太前书', 54, 6, 7, '私たちは、何もこの世に持って来なかったし、また、何かを持って出ることもできません。'),
('JPN', '提摩太前书', 54, 6, 8, '衣食があれば、それで満足すべきです。'),
('JPN', '提摩太前书', 54, 6, 9, '金持ちになりたがる人たちは、誘惑と罠と、また人を滅びと破滅に沈める、愚かで有害な多くの欲望に陥ります。'),
('JPN', '提摩太前书', 54, 6, 10, '金銭を愛することが、あらゆる悪の根だからです。ある人たちは金銭を追い求めたために、信仰から迷い出て、多くの苦痛で自分を刺し貫きました。'),
('JPN', '提摩太前书', 54, 6, 11, 'しかし、神の人よ。あなたはこれらのことを避け、義と敬虔と信仰、愛と忍耐と柔和を追い求めなさい。'),
('JPN', '提摩太前书', 54, 6, 12, '信仰の戦いを立派に戦い、永遠のいのちを獲得しなさい。あなたはこのために召され、多くの証人たちの前ですばらしい告白をしました。'),
('JPN', '提摩太前书', 54, 6, 13, '私は、すべてのものにいのちを与えてくださる神の御前で、また、ポンティオ・ピラトに対してすばらしい告白をもって証しをされたキリスト・イエスの御前で、あなたに命じます。'),
('JPN', '提摩太前书', 54, 6, 14, '私たちの主イエス・キリストの現れの時まで、あなたは汚れなく、非難されるところなく、命令を守りなさい。'),
('JPN', '提摩太前书', 54, 6, 15, 'キリストの現れを、定められた時にもたらしてくださる、祝福に満ちた唯一の主権者、王の王、主の主、'),
('JPN', '提摩太前书', 54, 6, 16, '死ぬことがない唯一の方、近づくこともできない光の中に住まわれ、人間がだれ一人見たことがなく、見ることもできない方。この方に誉れと永遠の支配がありますように。アーメン。'),
('JPN', '提摩太前书', 54, 6, 17, '今の世で富んでいる人たちに命じなさい。高慢にならず、頼りにならない富にではなく、むしろ、私たちにすべての物を豊かに与えて楽しませてくださる神に望みを置き、'),
('JPN', '提摩太前书', 54, 6, 18, '善を行い、立派な行いに富み、惜しみなく施し、喜んで分け与え、'),
('JPN', '提摩太前书', 54, 6, 19, '来たるべき世において立派な土台となるものを自分自身のために蓄え、まことのいのちを得るように命じなさい。'),
('JPN', '提摩太前书', 54, 6, 20, 'テモテよ、委ねられたものを守りなさい。そして、俗悪な無駄話や、間違って「知識」と呼ばれている反対論を避けなさい。'),
('JPN', '提摩太前书', 54, 6, 21, 'ある者たちはこの「知識」を持っていると主張して、信仰から外れてしまっています。恵みがあなたがたとともにありますように。'),
('JPN', '提摩太后书', 55, 1, 1, '神のみこころにより、またキリスト・イエスにあるいのちの約束にしたがって、キリスト・イエスの使徒となったパウロから、'),
('JPN', '提摩太后书', 55, 1, 2, '愛する子テモテへ。父なる神と、私たちの主キリスト・イエスから、恵みとあわれみと平安がありますように。'),
('JPN', '提摩太后书', 55, 1, 3, '私は夜昼、祈りの中であなたのことを絶えず思い起こし、先祖がしてきたように、私もきよい良心をもって仕えている神に感謝しています。'),
('JPN', '提摩太后书', 55, 1, 4, '私はあなたの涙を覚えているので、あなたに会って喜びに満たされたいと切望しています。'),
('JPN', '提摩太后书', 55, 1, 5, '私はあなたのうちにある、偽りのない信仰を思い起こしています。その信仰は、最初あなたの祖母ロイスと母ユニケのうちに宿ったもので、それがあなたのうちにも宿っていると私は確信しています。'),
('JPN', '提摩太后书', 55, 1, 6, 'そういうわけで、私はあなたに思い起こしてほしいのです。私の按手によってあなたのうちに与えられた神の賜物を、再び燃え立たせてください。'),
('JPN', '提摩太后书', 55, 1, 7, '神は私たちに、臆病の霊ではなく、力と愛と慎みの霊を与えてくださいました。'),
('JPN', '提摩太后书', 55, 1, 8, 'ですからあなたは、私たちの主を証しすることや、私が主の囚人であることを恥じてはいけません。むしろ、神の力によって、福音のために私と苦しみをともにしてください。'),
('JPN', '提摩太后书', 55, 1, 9, '神は私たちを救い、また、聖なる招きをもって召してくださいましたが、それは私たちの働きによるのではなく、ご自分の計画と恵みによるものでした。この恵みは、キリスト・イエスにおいて、私たちに永遠の昔に与えられ、'),
('JPN', '提摩太后书', 55, 1, 10, '今、私たちの救い主キリスト・イエスの現れによって明らかにされました。キリストは死を滅ぼし、福音によっていのちと不滅を明らかに示されたのです。'),
('JPN', '提摩太后书', 55, 1, 11, 'この福音のために、私は宣教者、使徒、また教師として任命されました。'),
('JPN', '提摩太后书', 55, 1, 12, 'そのために、私はこのような苦しみにあっています。しかし、それを恥とは思っていません。なぜなら、私は自分が信じてきた方をよく知っており、また、その方は私がお任せしたものを、かの日まで守ることがおできになると確信しているからです。'),
('JPN', '提摩太后书', 55, 1, 13, 'あなたは、キリスト・イエスにある信仰と愛のうちに、私から聞いた健全なことばを手本にしなさい。'),
('JPN', '提摩太后书', 55, 1, 14, '自分に委ねられた良いものを、私たちのうちに宿る聖霊によって守りなさい。'),
('JPN', '提摩太后书', 55, 1, 15, 'あなたが知っているとおり、アジアにいる人たちはみな、私から離れて行きました。その中にはフィゲロとヘルモゲネがいます。'),
('JPN', '提摩太后书', 55, 1, 16, 'オネシポロの家族を主があわれんでくださるように。彼はたびたび私を元気づけ、私が鎖につながれていることを恥と思わず、'),
('JPN', '提摩太后书', 55, 1, 17, 'ローマに着いたとき、熱心に私を捜して見つけ出してくれました。'),
('JPN', '提摩太后书', 55, 1, 18, 'かの日には主が、ご自分のあわれみをオネシポロに示してくださいますように。エペソで彼がどれほど多くの奉仕をしてくれたかは、あなた自身が一番よく知っています。'),
('JPN', '提摩太后书', 55, 2, 1, 'ですから、私の子よ、キリスト・イエスにある恵みによって強くなりなさい。'),
('JPN', '提摩太后书', 55, 2, 2, '多くの証人たちの前で私から聞いたことを、ほかの人にも教える力のある信頼できる人たちに委ねなさい。'),
('JPN', '提摩太后书', 55, 2, 3, 'キリスト・イエスの立派な兵士として、私と苦しみをともにしてください。'),
('JPN', '提摩太后书', 55, 2, 4, '兵役についている人はだれも、日常生活のことに煩わされることはありません。ただ、兵を募った人を喜ばせようとします。'),
('JPN', '提摩太后书', 55, 2, 5, 'また、競技をする人も、規定にしたがって競技をしなければ栄冠を得ることはできません。'),
('JPN', '提摩太后书', 55, 2, 6, '労苦している農夫こそ、最初に収穫の分け前にあずかるべきです。'),
('JPN', '提摩太后书', 55, 2, 7, '私が言っていることをよく考えなさい。主はすべてのことについて、理解する力をあなたに与えてくださいます。'),
('JPN', '提摩太后书', 55, 2, 8, 'イエス・キリストのことを心に留めていなさい。私が伝える福音によれば、この方は、ダビデの子孫として生まれ、死者の中からよみがえった方です。'),
('JPN', '提摩太后书', 55, 2, 9, 'この福音のために私は苦しみを受け、犯罪者のようにつながれています。しかし、神のことばはつながれていません。'),
('JPN', '提摩太后书', 55, 2, 10, 'ですから私はすべてのことを、選ばれた人たちのために耐え忍びます。彼らもまた、キリスト・イエスにある救いを、永遠の栄光とともに受けるようになるためです。'),
('JPN', '提摩太后书', 55, 2, 11, '次のことばは真実です。「私たちが、キリストとともに死んだのなら、キリストとともに生きるようになる。'),
('JPN', '提摩太后书', 55, 2, 12, '耐え忍んでいるなら、キリストとともに王となる。キリストを否むなら、キリストもまた、私たちを否まれる。'),
('JPN', '提摩太后书', 55, 2, 13, '私たちが真実でなくても、キリストは常に真実である。ご自分を否むことができないからである。」'),
('JPN', '提摩太后书', 55, 2, 14, 'これらのことを人々に思い起こさせなさい。そして、何の益にもならず、聞いている人々を滅ぼすことになる、ことばについての論争などをしないように、神の御前で厳かに命じなさい。'),
('JPN', '提摩太后书', 55, 2, 15, 'あなたは務めにふさわしいと認められる人として、すなわち、真理のみことばをまっすぐに説き明かす、恥じることのない働き人として、自分を神に献げるように最善を尽くしなさい。'),
('JPN', '提摩太后书', 55, 2, 16, '俗悪な無駄話を避けなさい。人々はそれによってますます不敬虔になり、'),
('JPN', '提摩太后书', 55, 2, 17, 'その人たちの話は悪性の腫れもののように広がります。彼らの中に、ヒメナイとピレトがいます。'),
('JPN', '提摩太后书', 55, 2, 18, '彼らは真理から外れてしまい、復活はすでに起こったと言って、ある人たちの信仰をくつがえしています。'),
('JPN', '提摩太后书', 55, 2, 19, 'しかし、神の堅固な土台は据えられていて、そこに次のような銘が刻まれています。「主はご自分に属する者を知っておられる。」また、「主の御名を呼ぶ者はみな、不義を離れよ。」'),
('JPN', '提摩太后书', 55, 2, 20, '大きな家には、金や銀の器だけでなく、木や土の器もあります。ある物は尊いことに、ある物は卑しいことに用いられます。'),
('JPN', '提摩太后书', 55, 2, 21, 'ですから、だれでもこれらのことから離れて自分自身をきよめるなら、その人は尊いことに用いられる器となります。すなわち、聖なるものとされ、主人にとって役に立つもの、あらゆる良い働きに備えられたものとなるのです。'),
('JPN', '提摩太后书', 55, 2, 22, 'あなたは若いときの情欲を避け、きよい心で主を呼び求める人たちとともに、義と信仰と愛と平和を追い求めなさい。'),
('JPN', '提摩太后书', 55, 2, 23, '愚かで無知な議論は、それが争いのもとであることを知っているのですから、避けなさい。'),
('JPN', '提摩太后书', 55, 2, 24, '主のしもべが争ってはいけません。むしろ、すべての人に優しくし、よく教え、よく忍耐し、'),
('JPN', '提摩太后书', 55, 2, 25, '反対する人たちを柔和に教え導きなさい。神は、彼らに悔い改めの心を与えて、真理を悟らせてくださるかもしれません。'),
('JPN', '提摩太后书', 55, 2, 26, '悪魔に捕らえられて思いのままにされている人々でも、目を覚まして、その罠を逃れるかもしれません。'),
('JPN', '提摩太后书', 55, 3, 1, '終わりの日には困難な時代が来ることを、承知していなさい。'),
('JPN', '提摩太后书', 55, 3, 2, 'そのときに人々は、自分だけを愛し、金銭を愛し、大言壮語し、高ぶり、神を冒瀆し、両親に従わず、恩知らずで、汚れた者になります。'),
('JPN', '提摩太后书', 55, 3, 3, 'また、情け知らずで、人と和解せず、中傷し、自制できず、粗野で、善を好まない者になり、'),
('JPN', '提摩太后书', 55, 3, 4, '人を裏切り、向こう見ずで、思い上がり、神よりも快楽を愛する者になり、'),
('JPN', '提摩太后书', 55, 3, 5, '見かけは敬虔であっても、敬虔の力を否定する者になります。こういう人たちを避けなさい。'),
('JPN', '提摩太后书', 55, 3, 6, '彼らの中には、家々に入り込み、愚かな女たちをたぶらかしている者たちがいます。その女たちは様々な欲望に引き回されて罪に罪を重ね、'),
('JPN', '提摩太后书', 55, 3, 7, 'いつも学んでいるのに、いつになっても真理を知ることができません。'),
('JPN', '提摩太后书', 55, 3, 8, 'たぶらかしている者たちは、ヤンネとヤンブレがモーセに逆らったように、真理に逆らっており、知性の腐った、信仰の失格者です。'),
('JPN', '提摩太后书', 55, 3, 9, 'しかし、彼らがこれ以上先に進むことはありません。彼らの愚かさは、あの二人の場合のように、すべての人にはっきり分かるからです。'),
('JPN', '提摩太后书', 55, 3, 10, 'しかしあなたは、私の教え、生き方、計画、信仰、寛容、愛、忍耐に、'),
('JPN', '提摩太后书', 55, 3, 11, 'また、アンティオキア、イコニオン、リステラで私に降りかかった迫害や苦難に、よくついて来てくれました。私はそのような迫害に耐えました。そして、主はそのすべてから私を救い出してくださいました。'),
('JPN', '提摩太后书', 55, 3, 12, 'キリスト・イエスにあって敬虔に生きようと願う者はみな、迫害を受けます。'),
('JPN', '提摩太后书', 55, 3, 13, '悪い者たちや詐欺師たちは、だましたり、だまされたりして、ますます悪に落ちて行きます。'),
('JPN', '提摩太后书', 55, 3, 14, 'けれどもあなたは、学んで確信したところにとどまっていなさい。あなたは自分がだれから学んだかを知っており、'),
('JPN', '提摩太后书', 55, 3, 15, 'また、自分が幼いころから聖書に親しんできたことも知っているからです。聖書はあなたに知恵を与えて、キリスト・イエスに対する信仰による救いを受けさせることができます。'),
('JPN', '提摩太后书', 55, 3, 16, '聖書はすべて神の霊感によるもので、教えと戒めと矯正と義の訓練のために有益です。'),
('JPN', '提摩太后书', 55, 3, 17, '神の人がすべての良い働きにふさわしく、十分に整えられた者となるためです。'),
('JPN', '提摩太后书', 55, 4, 1, '神の御前で、また、生きている人と死んだ人をさばかれるキリスト・イエスの御前で、その現れとその御国を思いながら、私は厳かに命じます。'),
('JPN', '提摩太后书', 55, 4, 2, 'みことばを宣べ伝えなさい。時が良くても悪くてもしっかりやりなさい。忍耐の限りを尽くし、絶えず教えながら、責め、戒め、また勧めなさい。'),
('JPN', '提摩太后书', 55, 4, 3, 'というのは、人々が健全な教えに耐えられなくなり、耳に心地よい話を聞こうと、自分の好みにしたがって自分たちのために教師を寄せ集め、'),
('JPN', '提摩太后书', 55, 4, 4, '真理から耳を背け、作り話にそれて行くような時代になるからです。'),
('JPN', '提摩太后书', 55, 4, 5, 'けれども、あなたはどんな場合にも慎んで、苦難に耐え、伝道者の働きをなし、自分の務めを十分に果たしなさい。'),
('JPN', '提摩太后书', 55, 4, 6, '私はすでに注ぎのささげ物となっています。私が世を去る時が来ました。'),
('JPN', '提摩太后书', 55, 4, 7, '私は勇敢に戦い抜き、走るべき道のりを走り終え、信仰を守り通しました。'),
('JPN', '提摩太后书', 55, 4, 8, 'あとは、義の栄冠が私のために用意されているだけです。その日には、正しいさばき主である主が、それを私に授けてくださいます。私だけでなく、主の現れを慕い求めている人には、だれにでも授けてくださるのです。'),
('JPN', '提摩太后书', 55, 4, 9, 'あなたは、何とかして早く私のところに来てください。'),
('JPN', '提摩太后书', 55, 4, 10, 'デマスは今の世を愛し、私を見捨ててテサロニケに行ってしまいました。また、クレスケンスはガラテヤに、テトスはダルマティアに行きました。'),
('JPN', '提摩太后书', 55, 4, 11, 'ルカだけが私とともにいます。マルコを伴って、一緒に来てください。彼は私の務めのために役に立つからです。'),
('JPN', '提摩太后书', 55, 4, 12, '私はティキコをエペソに遣わしました。'),
('JPN', '提摩太后书', 55, 4, 13, 'あなたが来るとき、トロアスでカルポのところに置いてきた外套を持って来てください。また書物、特に羊皮紙の物を持って来てください。'),
('JPN', '提摩太后书', 55, 4, 14, '銅細工人のアレクサンドロが私をひどく苦しめました。その行いに応じて、主が彼に報いられます。'),
('JPN', '提摩太后书', 55, 4, 15, 'あなたも彼を警戒しなさい。彼は私たちのことばに激しく逆らったからです。'),
('JPN', '提摩太后书', 55, 4, 16, '私の最初の弁明の際、だれも私を支持してくれず、みな私を見捨ててしまいました。どうか、その責任を彼らが負わせられることがありませんように。'),
('JPN', '提摩太后书', 55, 4, 17, 'しかし、主は私とともに立ち、私に力を与えてくださいました。それは、私を通してみことばが余すところなく宣べ伝えられ、すべての国の人々がみことばを聞くようになるためでした。こうして私は獅子の口から救い出されたのです。'),
('JPN', '提摩太后书', 55, 4, 18, '主は私を、どんな悪しきわざからも救い出し、無事、天にある御国に入れてくださいます。主に栄光が世々限りなくありますように。アーメン。'),
('JPN', '提摩太后书', 55, 4, 19, 'プリスカとアキラによろしく。また、オネシポロの家族によろしく。'),
('JPN', '提摩太后书', 55, 4, 20, 'エラストはコリントにとどまり、病気のトロフィモはミレトスに残して来ました。'),
('JPN', '提摩太后书', 55, 4, 21, '何とかして冬になる前に来てください。ユブロ、プデス、リノス、クラウディア、そしてすべての兄弟たちが、あなたによろしくと言っています。'),
('JPN', '提摩太后书', 55, 4, 22, '主があなたの霊とともにいてくださいますように。恵みがあなたがたとともにありますように。'),
('JPN', '提多书', 56, 1, 1, '神のしもべ、イエス・キリストの使徒パウロから。──私が使徒とされたのは、神に選ばれた人々が信仰に進み、敬虔にふさわしい、真理の知識を得るためで、'),
('JPN', '提多书', 56, 1, 2, 'それは、偽ることのない神が永遠の昔から約束してくださった、永遠のいのちの望みに基づくものです。'),
('JPN', '提多书', 56, 1, 3, '神は、定められた時に、みことばを宣教によって明らかにされました。私はこの宣教を、私たちの救い主である神の命令によって委ねられたのです──'),
('JPN', '提多书', 56, 1, 4, '同じ信仰による、真のわが子テトスへ。父なる神と、私たちの救い主キリスト・イエスから、恵みと平安がありますように。'),
('JPN', '提多书', 56, 1, 5, '私があなたをクレタに残したのは、残っている仕事の整理をし、私が命じたとおりに町ごとに長老たちを任命するためでした。'),
('JPN', '提多书', 56, 1, 6, '長老は、非難されるところがなく、一人の妻の夫であり、子どもたちも信者で、放蕩を責められたり、反抗的であったりしないことが条件です。'),
('JPN', '提多书', 56, 1, 7, '監督は神の家を管理する者として、非難されるところのない者であるべきです。わがままでなく、短気でなく、酒飲みでなく、乱暴でなく、不正な利を求めず、'),
('JPN', '提多书', 56, 1, 8, 'むしろ、人をよくもてなし、善を愛し、慎み深く、正しく、敬虔で、自制心があり、'),
('JPN', '提多书', 56, 1, 9, '教えにかなった信頼すべきみことばを、しっかりと守っていなければなりません。健全な教えをもって励ましたり、反対する人たちを戒めたりすることができるようになるためです。'),
('JPN', '提多书', 56, 1, 10, '実は、反抗的な者、無益な話をする者、人を惑わす者が多くいます。特に、割礼を受けている人々の中に多くいます。'),
('JPN', '提多书', 56, 1, 11, 'そのような者たちの口は封じなければなりません。彼らは、恥ずべき利益を得るために、教えてはならないことを教え、いくつかの家庭をことごとく破壊しています。'),
('JPN', '提多书', 56, 1, 12, 'クレタ人のうちの一人、彼ら自身の預言者が言いました。「クレタ人はいつも噓つき、悪い獣、怠け者の大食漢。」'),
('JPN', '提多书', 56, 1, 13, 'この証言は本当です。ですから、彼らを厳しく戒めて、その信仰を健全にし、'),
('JPN', '提多书', 56, 1, 14, 'ユダヤ人の作り話や、真理に背を向けている人たちの戒めに、心を奪われないようにさせなさい。'),
('JPN', '提多书', 56, 1, 15, 'きよい人たちには、すべてのものがきよいのです。しかし、汚れた不信仰な人たちには、何一つきよいものはなく、その知性も良心も汚れています。'),
('JPN', '提多书', 56, 1, 16, '彼らは、神を知っていると公言しますが、行いでは否定しています。彼らは忌まわしく、不従順で、どんな良いわざにも不適格です。'),
('JPN', '提多书', 56, 2, 1, 'しかし、あなたは健全な教えにふさわしいことを語りなさい。'),
('JPN', '提多书', 56, 2, 2, '年配の男の人には、自分を制し、品位を保ち、慎み深く、信仰と愛と忍耐において健全であるように。'),
('JPN', '提多书', 56, 2, 3, '同じように、年配の女の人には、神に仕えている者にふさわしくふるまい、人を中傷せず、大酒のとりこにならず、良いことを教える者であるように。'),
('JPN', '提多书', 56, 2, 4, 'そうすれば、彼女たちは若い女の人に、夫を愛し、子どもを愛し、'),
('JPN', '提多书', 56, 2, 5, '慎み深く、貞潔で、家事に励み、善良で、自分の夫に従順であるように諭すことができます。神のことばが悪く言われることのないようにするためです。'),
('JPN', '提多书', 56, 2, 6, '同じように、若い人には、あらゆる点で思慮深くあるように勧めなさい。'),
('JPN', '提多书', 56, 2, 7, 'また、あなた自身、良いわざの模範となりなさい。人を教えることにおいて偽りがなく、品位を保ち、'),
('JPN', '提多书', 56, 2, 8, '非難する余地がない健全なことばを用いなさい。そうすれば、敵対する者も、私たちについて何も悪いことが言えずに、恥じ入ることになるでしょう。'),
('JPN', '提多书', 56, 2, 9, '奴隷には、あらゆる点で自分の主人に従って、喜ばれる者となるようにし、口答えせず、'),
('JPN', '提多书', 56, 2, 10, '盗んだりせず、いつも善良で信頼できることを示すように勧めなさい。それは、彼らがあらゆる点で、私たちの救い主である神の教えを飾るようになるためです。'),
('JPN', '提多书', 56, 2, 11, '実に、すべての人に救いをもたらす神の恵みが現れたのです。'),
('JPN', '提多书', 56, 2, 12, 'その恵みは、私たちが不敬虔とこの世の欲を捨て、今の世にあって、慎み深く、正しく、敬虔に生活し、'),
('JPN', '提多书', 56, 2, 13, '祝福に満ちた望み、すなわち、大いなる神であり私たちの救い主であるイエス・キリストの、栄光ある現れを待ち望むように教えています。'),
('JPN', '提多书', 56, 2, 14, 'キリストは、私たちをすべての不法から贖い出し、良いわざに熱心な選びの民をご自分のものとしてきよめるため、私たちのためにご自分を献げられたのです。'),
('JPN', '提多书', 56, 2, 15, 'あなたは、これらのことを十分な権威をもって語り、勧め、戒めなさい。だれにも軽んじられてはいけません。'),
('JPN', '提多书', 56, 3, 1, 'あなたは人々に注意を与えて、その人々が、支配者たちと権威者たちに服し、従い、すべての良いわざを進んでする者となるようにしなさい。'),
('JPN', '提多书', 56, 3, 2, 'また、だれも中傷せず、争わず、柔和で、すべての人にあくまで礼儀正しい者となるようにしなさい。'),
('JPN', '提多书', 56, 3, 3, '私たちも以前は、愚かで、不従順で、迷っていた者であり、いろいろな欲望と快楽の奴隷になり、悪意とねたみのうちに生活し、人から憎まれ、互いに憎み合う者でした。'),
('JPN', '提多书', 56, 3, 4, 'しかし、私たちの救い主である神のいつくしみと人に対する愛が現れたとき、'),
('JPN', '提多书', 56, 3, 5, '神は、私たちが行った義のわざによってではなく、ご自分のあわれみによって、聖霊による再生と刷新の洗いをもって、私たちを救ってくださいました。'),
('JPN', '提多书', 56, 3, 6, '神はこの聖霊を、私たちの救い主イエス・キリストによって、私たちに豊かに注いでくださったのです。'),
('JPN', '提多书', 56, 3, 7, 'それは、私たちがキリストの恵みによって義と認められ、永遠のいのちの望みを抱く相続人となるためでした。'),
('JPN', '提多书', 56, 3, 8, 'このことばは真実です。私は、あなたがこれらのことを、確信をもって語るように願っています。神を信じるようになった人々が、良いわざに励むことを心がけるようになるためです。これらのことは良いことであり、人々に有益です。'),
('JPN', '提多书', 56, 3, 9, '一方、愚かな議論、系図、争い、律法についての論争は避けなさい。それらは無益で、むなしいものです。'),
('JPN', '提多书', 56, 3, 10, '分派を作る者は、一、二度訓戒した後、除名しなさい。'),
('JPN', '提多书', 56, 3, 11, 'あなたも知っているとおり、このような人はゆがんでいて、自分で悪いと知りながら罪を犯しているのです。'),
('JPN', '提多书', 56, 3, 12, '私がアルテマスかティキコをあなたのもとに送ったら、あなたは何とかして、ニコポリスにいる私のところに来てください。私はそこで冬を過ごすことにしています。'),
('JPN', '提多书', 56, 3, 13, '律法学者ゼナスとアポロが何も不足することがないように、その旅立ちをしっかりと支えてあげてください。'),
('JPN', '提多书', 56, 3, 14, '私たちの仲間も、実を結ばない者にならないように、差し迫った必要に備えて、良いわざに励むように教えられなければなりません。'),
('JPN', '提多书', 56, 3, 15, '私と一緒にいる者たちがみな、あなたによろしくと言っています。信仰を同じくし、私たちを愛してくださっている人たちに、よろしく伝えてください。恵みがあなたがたすべてとともにありますように。'),
('JPN', '腓利门书', 57, 1, 1, 'キリスト・イエスの囚人パウロと兄弟テモテから、私たちの愛する同労者ピレモンと、'),
('JPN', '腓利门书', 57, 1, 2, '姉妹アッピア、私たちの戦友アルキポ、ならびに、あなたの家にある教会へ。'),
('JPN', '腓利门书', 57, 1, 3, '私たちの父なる神と、主イエス・キリストから、恵みと平安があなたがたにありますように。'),
('JPN', '腓利门书', 57, 1, 4, '私は祈るとき、いつもあなたのことを思い、私の神に感謝しています。'),
('JPN', '腓利门书', 57, 1, 5, 'あなたが主イエスに対して抱いていて、すべての聖徒たちにも向けている、愛と信頼について聞いているからです。'),
('JPN', '腓利门书', 57, 1, 6, '私たちの間でキリストのためになされている良い行いを、すべて知ることによって、あなたの信仰の交わりが生き生きとしたものとなりますように。'),
('JPN', '腓利门书', 57, 1, 7, '私はあなたの愛によって多くの喜びと慰めを得ました。それは、兄弟よ、あなたによって聖徒たちが安心を得たからです。'),
('JPN', '腓利门书', 57, 1, 8, 'ですから、あなたがなすべきことを、私はキリストにあって、全く遠慮せずに命じることもできるのですが、'),
('JPN', '腓利门书', 57, 1, 9, 'むしろ愛のゆえに懇願します。このとおり年老いて、今またキリスト・イエスの囚人となっているパウロが、'),
('JPN', '腓利门书', 57, 1, 10, '獄中で生んだわが子オネシモのことを、あなたにお願いしたいのです。'),
('JPN', '腓利门书', 57, 1, 11, '彼は、以前はあなたにとって役に立たない者でしたが、今は、あなたにとっても私にとっても役に立つ者となっています。'),
('JPN', '腓利门书', 57, 1, 12, 'そのオネシモをあなたのもとに送り返します。彼は私の心そのものです。'),
('JPN', '腓利门书', 57, 1, 13, '私は、彼を私のもとにとどめておき、獄中にいる間、福音のためにあなたに代わって私に仕えてもらおうと思いました。'),
('JPN', '腓利门书', 57, 1, 14, 'しかし、あなたの同意なしには何も行いたくありませんでした。それは、あなたの親切が強いられたものではなく、自発的なものとなるためです。'),
('JPN', '腓利门书', 57, 1, 15, 'オネシモがしばらくの間あなたから離されたのは、おそらく、あなたが永久に彼を取り戻すためであったのでしょう。'),
('JPN', '腓利门书', 57, 1, 16, 'もはや奴隷としてではなく、奴隷以上の者、愛する兄弟としてです。特に私にとって愛する兄弟ですが、あなたにとっては、肉においても主にあっても、なおのことそうではありませんか。'),
('JPN', '腓利门书', 57, 1, 17, 'ですから、あなたが私を仲間の者だと思うなら、私を迎えるようにオネシモを迎えてください。'),
('JPN', '腓利门书', 57, 1, 18, 'もし彼があなたに何か損害を与えたか、負債を負っているなら、その請求は私にしてください。'),
('JPN', '腓利门书', 57, 1, 19, '私パウロが自分の手で、「私が償います」と書いています。あなたが、あなた自身のことで私にもっと負債があることは、言わないことにします。'),
('JPN', '腓利门书', 57, 1, 20, 'そうです、兄弟よ。私は主にあって、あなたの厚意にあずかりたいのです。私をキリストにあって安心させてください。'),
('JPN', '腓利门书', 57, 1, 21, '私はあなたの従順を確信して書いています。私が言う以上のことまで、あなたはしてくださると、分かっています。'),
('JPN', '腓利门书', 57, 1, 22, '同時に、私の宿も用意しておいてください。あなたがたの祈りによって、私はあなたがたのもとに行くことが許されると期待しているからです。'),
('JPN', '腓利门书', 57, 1, 23, 'キリスト・イエスにあって私とともに囚人となっているエパフラスが、あなたによろしくと言っています。'),
('JPN', '腓利门书', 57, 1, 24, '私の同労者たち、マルコ、アリスタルコ、デマス、ルカがよろしくと言っています。'),
('JPN', '腓利门书', 57, 1, 25, '主イエス・キリストの恵みが、あなたがたの霊とともにありますように。'),
('JPN', '希伯来书', 58, 1, 1, '神は昔、預言者たちによって、多くの部分に分け、多くの方法で先祖たちに語られましたが、'),
('JPN', '希伯来书', 58, 1, 2, 'この終わりの時には、御子にあって私たちに語られました。神は御子を万物の相続者と定め、御子によって世界を造られました。'),
('JPN', '希伯来书', 58, 1, 3, '御子は神の栄光の輝き、また神の本質の完全な現れであり、その力あるみことばによって万物を保っておられます。御子は罪のきよめを成し遂げ、いと高き所で、大いなる方の右の座に着かれました。'),
('JPN', '希伯来书', 58, 1, 4, '御子が受け継いだ御名は、御使いたちの名よりもすばらしく、それだけ御使いよりもすぐれた方となられました。'),
('JPN', '希伯来书', 58, 1, 5, '神はいったい、どの御使いに向かって言われたでしょうか。「あなたはわたしの子。わたしが今日、あなたを生んだ」と。またさらに、「わたしは彼の父となり、彼はわたしの子となる」と。'),
('JPN', '希伯来书', 58, 1, 6, 'そのうえ、この長子をこの世界に送られたとき、神はこう言われました。「神のすべての御使いよ、彼にひれ伏せ。」'),
('JPN', '希伯来书', 58, 1, 7, 'また、御使いについては、「神は御使いたちを風とし、仕える者たちを燃える炎とされる」と言われましたが、'),
('JPN', '希伯来书', 58, 1, 8, '御子については、こう言われました。「神よ。あなたの王座は世々限りなく、あなたの王国の杖は公正の杖。'),
('JPN', '希伯来书', 58, 1, 9, 'あなたは義を愛し、不法を憎む。それゆえ、神よ、あなたの神は、喜びの油で、あなたに油を注がれた。あなたに並ぶだれよりも多く。」'),
('JPN', '希伯来书', 58, 1, 10, 'またこう言われました。「主よ。あなたははじめに地の基を据えられました。天も、あなたの御手のわざです。'),
('JPN', '希伯来书', 58, 1, 11, 'これらのものは滅びます。しかし、あなたはいつまでもながらえられます。すべてのものは、衣のようにすり切れます。'),
('JPN', '希伯来书', 58, 1, 12, 'あなたがそれらを外套のように巻き上げると、それらは衣のように取り替えられてしまいます。しかし、あなたは変わることがなく、あなたの年は尽きることがありません。」'),
('JPN', '希伯来书', 58, 1, 13, 'いったいどの御使いに向かって、神はこう言われたでしょうか。「あなたは、わたしの右の座に着いていなさい。わたしがあなたの敵をあなたの足台とするまで」と。'),
('JPN', '希伯来书', 58, 1, 14, '御使いはみな、奉仕する霊であって、救いを受け継ぐことになる人々に仕えるために遣わされているのではありませんか。'),
('JPN', '希伯来书', 58, 2, 1, 'こういうわけで、私たちは聞いたことを、ますますしっかりと心に留め、押し流されないようにしなければなりません。'),
('JPN', '希伯来书', 58, 2, 2, '御使いたちを通して語られたみことばに効力があり、すべての違反と不従順が当然の処罰を受けたのなら、'),
('JPN', '希伯来书', 58, 2, 3, 'こんなにすばらしい救いをないがしろにした場合、私たちはどうして処罰を逃れることができるでしょう。この救いは、初めに主によって語られ、それを聞いた人たちが確かなものとして私たちに示したものです。'),
('JPN', '希伯来书', 58, 2, 4, 'そのうえ神も、しるしと不思議と様々な力あるわざにより、また、みこころにしたがって聖霊が分け与えてくださる賜物によって、救いを証ししてくださいました。'),
('JPN', '希伯来书', 58, 2, 5, 'というのも、神は、私たちが語っている来たるべき世を、御使いたちに従わせたのではないからです。'),
('JPN', '希伯来书', 58, 2, 6, 'ある箇所で、ある人がこう証ししています。「人とは何ものなのでしょう。あなたがこれを心に留められるとは。人の子とはいったい何ものなのでしょう。あなたがこれを顧みてくださるとは。'),
('JPN', '希伯来书', 58, 2, 7, 'あなたは、人を御使いよりわずかの間低いものとし、これに栄光と誉れの冠をかぶらせ、'),
('JPN', '希伯来书', 58, 2, 8, '万物を彼の足の下に置かれました。」神は、万物を人の下に置かれたとき、彼に従わないものを何も残されませんでした。それなのに、今なお私たちは、すべてのものが人の下に置かれているのを見てはいません。'),
('JPN', '希伯来书', 58, 2, 9, 'ただ、御使いよりもわずかの間低くされた方、すなわちイエスのことは見ています。イエスは死の苦しみのゆえに、栄光と誉れの冠を受けられました。その死は、神の恵みによって、すべての人のために味わわれたものです。'),
('JPN', '希伯来书', 58, 2, 10, '多くの子たちを栄光に導くために、彼らの救いの創始者を多くの苦しみを通して完全な者とされたのは、万物の存在の目的であり、また原因でもある神に、ふさわしいことであったのです。'),
('JPN', '希伯来书', 58, 2, 11, '聖とする方も、聖とされる者たちも、みな一人の方から出ています。それゆえ、イエスは彼らを兄弟と呼ぶことを恥とせずに、こう言われます。'),
('JPN', '希伯来书', 58, 2, 12, '「わたしは、あなたの御名を兄弟たちに語り告げ、会衆の中であなたを賛美しよう。」'),
('JPN', '希伯来书', 58, 2, 13, 'また、「わたしはこの方に信頼を置く」と言い、さらに、「見よ。わたしと、神がわたしに下さった子たち」と言われます。'),
('JPN', '希伯来书', 58, 2, 14, 'そういうわけで、子たちがみな血と肉を持っているので、イエスもまた同じように、それらのものをお持ちになりました。それは、死の力を持つ者、すなわち、悪魔をご自分の死によって滅ぼし、'),
('JPN', '希伯来书', 58, 2, 15, '死の恐怖によって一生涯奴隷としてつながれていた人々を解放するためでした。'),
('JPN', '希伯来书', 58, 2, 16, '当然ながら、イエスは御使いたちを助け出すのではなく、アブラハムの子孫を助け出してくださるのです。'),
('JPN', '希伯来书', 58, 2, 17, 'したがって、神に関わる事柄について、あわれみ深い、忠実な大祭司となるために、イエスはすべての点で兄弟たちと同じようにならなければなりませんでした。それで民の罪の宥めがなされたのです。'),
('JPN', '希伯来书', 58, 2, 18, 'イエスは、自ら試みを受けて苦しまれたからこそ、試みられている者たちを助けることができるのです。'),
('JPN', '希伯来书', 58, 3, 1, 'ですから、天の召しにあずかっている聖なる兄弟たち。私たちが告白する、使徒であり大祭司であるイエスのことを考えなさい。'),
('JPN', '希伯来书', 58, 3, 2, 'モーセが神の家全体の中で忠実であったのと同様に、イエスはご自分を立てた方に対して忠実でした。'),
('JPN', '希伯来书', 58, 3, 3, '家よりも、家を建てる人が大いなる栄誉を持つのと同じように、イエスはモーセよりも大いなる栄光を受けるにふさわしいとされました。'),
('JPN', '希伯来书', 58, 3, 4, '家はそれぞれだれかが建てるのですが、すべてのものを造られたのは神です。'),
('JPN', '希伯来书', 58, 3, 5, 'モーセは、後に語られることを証しするために、神の家全体の中でしもべとして忠実でした。'),
('JPN', '希伯来书', 58, 3, 6, 'しかしキリストは、御子として神の家を治めることに忠実でした。そして、私たちが神の家です。もし確信と、希望による誇りを持ち続けさえすれば、そうなのです。'),
('JPN', '希伯来书', 58, 3, 7, 'ですから、聖霊が言われるとおりです。「今日、もし御声を聞くなら、'),
('JPN', '希伯来书', 58, 3, 8, 'あなたがたの心を頑なにしてはならない。荒野での試みの日に神に逆らったときのように。'),
('JPN', '希伯来书', 58, 3, 9, 'あなたがたの先祖はそこでわたしを試み、わたしを試し、四十年の間、わたしのわざを見た。'),
('JPN', '希伯来书', 58, 3, 10, 'だから、わたしはその世代に憤って言った。『彼らは常に心が迷っている。彼らはわたしの道を知らない。』'),
('JPN', '希伯来书', 58, 3, 11, 'わたしは怒りをもって誓った。『彼らは決して、わたしの安息に入れない。』」'),
('JPN', '希伯来书', 58, 3, 12, '兄弟たち。あなたがたのうちに、不信仰な悪い心になって、生ける神から離れる者がないように気をつけなさい。'),
('JPN', '希伯来书', 58, 3, 13, '「今日」と言われている間、日々互いに励まし合って、だれも罪に惑わされて頑なにならないようにしなさい。'),
('JPN', '希伯来书', 58, 3, 14, '私たちはキリストにあずかる者となっているのです。もし最初の確信を終わりまでしっかり保ちさえすれば、です。'),
('JPN', '希伯来书', 58, 3, 15, '「今日、もし御声を聞くなら、あなたがたの心を頑なにしてはならない。神に逆らったときのように」と言われているとおりです。'),
('JPN', '希伯来书', 58, 3, 16, 'では、聞いていながら反抗したのは、だれでしたか。モーセに率いられてエジプトを出た、すべての者たちではありませんか。'),
('JPN', '希伯来书', 58, 3, 17, '神が四十年の間、憤っておられたのは、だれに対してですか。罪を犯して、荒野に屍をさらした者たちに対してではありませんか。'),
('JPN', '希伯来书', 58, 3, 18, 'また、神がご自分の安息に入らせないと誓われたのは、だれに対してですか。ほかでもない、従わなかった者たちに対してではありませんか。'),
('JPN', '希伯来书', 58, 3, 19, 'このように、彼らが安息に入れなかったのは、不信仰のためであったことが分かります。'),
('JPN', '希伯来书', 58, 4, 1, 'こういうわけで、私たちは恐れる心を持とうではありませんか。神の安息に入るための約束がまだ残っているのに、あなたがたのうちのだれかが、そこに入れなかったということのないようにしましょう。'),
('JPN', '希伯来书', 58, 4, 2, 'というのも、私たちにも良い知らせが伝えられていて、あの人たちと同じなのです。けれども彼らには、聞いたみことばが益となりませんでした。みことばが、聞いた人たちに信仰によって結びつけられなかったからです。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '希伯来书', 58, 4, 3, '信じた私たちは安息に入るのですが、「わたしは怒りをもって誓った。『彼らは決して、わたしの安息に入れない』」と神が言われたとおりなのです。もっとも、世界の基が据えられたときから、みわざはすでに成し遂げられています。'),
('JPN', '希伯来书', 58, 4, 4, 'なぜなら、神は第七日について、あるところで「そして神は、第七日に、すべてのわざを終えて休まれた」と言われ、'),
('JPN', '希伯来书', 58, 4, 5, 'そのうえで、この箇所で、「彼らは決して、わたしの安息に入れない」と言われたからです。'),
('JPN', '希伯来书', 58, 4, 6, 'ですから、その安息に入る人々がまだ残っていて、また、以前に良い知らせを聞いた人々が不従順のゆえに入れなかったので、'),
('JPN', '希伯来书', 58, 4, 7, '神は再び、ある日を「今日」と定め、長い年月の後、前に言われたのと同じように、ダビデを通して、「今日、もし御声を聞くなら、あなたがたの心を頑なにしてはならない」と語られたのです。'),
('JPN', '希伯来书', 58, 4, 8, 'もしヨシュアが彼らに安息を与えたのであれば、神はその後に別の日のことを話されることはなかったでしょう。'),
('JPN', '希伯来书', 58, 4, 9, 'したがって、安息日の休みは、神の民のためにまだ残されています。'),
('JPN', '希伯来书', 58, 4, 10, '神の安息に入る人は、神がご自分のわざを休まれたように、自分のわざを休むのです。'),
('JPN', '希伯来书', 58, 4, 11, 'ですから、だれも、あの不従順の悪い例に倣って落伍しないように、この安息に入るように努めようではありませんか。'),
('JPN', '希伯来书', 58, 4, 12, '神のことばは生きていて、力があり、両刃の剣よりも鋭く、たましいと霊、関節と骨髄を分けるまでに刺し貫き、心の思いやはかりごとを見分けることができます。'),
('JPN', '希伯来书', 58, 4, 13, '神の御前にあらわでない被造物はありません。神の目にはすべてが裸であり、さらけ出されています。この神に対して、私たちは申し開きをするのです。'),
('JPN', '希伯来书', 58, 4, 14, 'さて、私たちには、もろもろの天を通られた、神の子イエスという偉大な大祭司がおられるのですから、信仰の告白を堅く保とうではありませんか。'),
('JPN', '希伯来书', 58, 4, 15, '私たちの大祭司は、私たちの弱さに同情できない方ではありません。罪は犯しませんでしたが、すべての点において、私たちと同じように試みにあわれたのです。'),
('JPN', '希伯来书', 58, 4, 16, 'ですから私たちは、あわれみを受け、また恵みをいただいて、折にかなった助けを受けるために、大胆に恵みの御座に近づこうではありませんか。'),
('JPN', '希伯来书', 58, 5, 1, '大祭司はみな、人々の中から選ばれ、人々のために神に仕えるように、すなわち、ささげ物といけにえを罪のために献げるように、任命されています。'),
('JPN', '希伯来书', 58, 5, 2, '大祭司は自分自身も弱さを身にまとっているので、無知で迷っている人々に優しく接することができます。'),
('JPN', '希伯来书', 58, 5, 3, 'また、その弱さのゆえに、民のためだけでなく、自分のためにも、罪のゆえにささげ物を献げなければなりません。'),
('JPN', '希伯来书', 58, 5, 4, 'また、この栄誉は自分で得るのではなく、アロンがそうであったように、神に召されて受けるのです。'),
('JPN', '希伯来书', 58, 5, 5, '同様にキリストも、大祭司となる栄誉を自分で得たのではなく、「あなたはわたしの子。わたしが今日、あなたを生んだ」と語りかけた方が、それをお与えになったのです。'),
('JPN', '希伯来书', 58, 5, 6, '別の箇所でも、「あなたは、メルキゼデクの例に倣い、とこしえに祭司である」と言っておられるとおりです。'),
('JPN', '希伯来书', 58, 5, 7, 'キリストは、肉体をもって生きている間、自分を死から救い出すことができる方に向かって、大きな叫び声と涙をもって祈りと願いをささげ、その敬虔のゆえに聞き入れられました。'),
('JPN', '希伯来书', 58, 5, 8, 'キリストは御子であられるのに、お受けになった様々な苦しみによって従順を学び、'),
('JPN', '希伯来书', 58, 5, 9, '完全な者とされ、ご自分に従うすべての人にとって永遠の救いの源となり、'),
('JPN', '希伯来书', 58, 5, 10, 'メルキゼデクの例に倣い、神によって大祭司と呼ばれました。'),
('JPN', '希伯来书', 58, 5, 11, 'このメルキゼデクについて、私たちには話すことがたくさんありますが、説き明かすことは困難です。あなたがたが、聞くことに対して鈍くなっているからです。'),
('JPN', '希伯来书', 58, 5, 12, 'あなたがたは、年数からすれば教師になっていなければならないにもかかわらず、神が告げたことばの初歩を、もう一度だれかに教えてもらう必要があります。あなたがたは固い食物ではなく、乳が必要になっています。'),
('JPN', '希伯来书', 58, 5, 13, '乳を飲んでいる者はみな、義の教えに通じてはいません。幼子なのです。'),
('JPN', '希伯来书', 58, 5, 14, '固い食物は、善と悪を見分ける感覚を経験によって訓練された大人のものです。'),
('JPN', '希伯来书', 58, 6, 1, 'ですから私たちは、キリストについての初歩の教えを後にして、成熟を目指して進もうではありませんか。死んだ行いからの回心、神に対する信仰、'),
('JPN', '希伯来书', 58, 6, 2, 'きよめの洗いについての教えと手を置く儀式、死者の復活と永遠のさばきなど、基礎的なことをもう一度やり直したりしないようにしましょう。'),
('JPN', '希伯来书', 58, 6, 3, '神が許されるなら、先に進みましょう。'),
('JPN', '希伯来书', 58, 6, 4, '一度光に照らされ、天からの賜物を味わい、聖霊にあずかる者となって、'),
('JPN', '希伯来书', 58, 6, 5, '神のすばらしいみことばと、来たるべき世の力を味わったうえで、'),
('JPN', '希伯来书', 58, 6, 6, '堕落してしまうなら、そういう人たちをもう一度悔い改めに立ち返らせることはできません。彼らは、自分で神の子をもう一度十字架にかけて、さらしものにする者たちだからです。'),
('JPN', '希伯来书', 58, 6, 7, 'たびたび降り注ぐ雨を吸い込んで、耕す人たちに有用な作物を生じる土地は、神の祝福にあずかりますが、'),
('JPN', '希伯来书', 58, 6, 8, '茨やあざみを生えさせる土地は無用で、やがてのろわれ、最後は焼かれてしまうのです。'),
('JPN', '希伯来书', 58, 6, 9, 'だが、愛する者たち。私たちはこのように言ってはいますが、あなたがたについては、もっと良いこと、救いにつながることを確信しています。'),
('JPN', '希伯来书', 58, 6, 10, '神は不公平な方ではありませんから、あなたがたの働きや愛を忘れたりなさいません。あなたがたは、これまで聖徒たちに仕え、今も仕えることによって、神の御名のために愛を示しました。'),
('JPN', '希伯来书', 58, 6, 11, '私たちが切望するのは、あなたがた一人ひとりが同じ熱心さを示して、最後まで私たちの希望について十分な確信を持ち続け、'),
('JPN', '希伯来书', 58, 6, 12, 'その結果、怠け者とならずに、信仰と忍耐によって約束のものを受け継ぐ人たちに倣う者となることです。'),
('JPN', '希伯来书', 58, 6, 13, '神は、アブラハムに約束する際、ご自分より大いなるものにかけて誓うことができなかったので、ご自分にかけて誓い、'),
('JPN', '希伯来书', 58, 6, 14, '「確かにわたしは、あなたを大いに祝福し、あなたを大いに増やす」と言われました。'),
('JPN', '希伯来书', 58, 6, 15, 'このようにして、アブラハムは忍耐の末に約束のものを得たのです。'),
('JPN', '希伯来书', 58, 6, 16, '確かに、人間は自分より大いなるものにかけて誓います。そして、誓いはすべての論争を終わらせる保証となります。'),
('JPN', '希伯来书', 58, 6, 17, 'そこで神は、約束の相続者たちに、ご自分の計画が変わらないことをさらにはっきり示そうと思い、誓いをもって保証されました。'),
('JPN', '希伯来书', 58, 6, 18, 'それは、前に置かれている希望を捕らえようとして逃れて来た私たちが、約束と誓いという変わらない二つのものによって、力強い励ましを受けるためです。その二つについて、神が偽ることはあり得ません。'),
('JPN', '希伯来书', 58, 6, 19, '私たちが持っているこの希望は、安全で確かな、たましいの錨のようなものであり、また幕の内側にまで入って行くものです。'),
('JPN', '希伯来书', 58, 6, 20, 'イエスは、私たちのために先駆けとしてそこに入り、メルキゼデクの例に倣って、とこしえに大祭司となられたのです。'),
('JPN', '希伯来书', 58, 7, 1, 'このメルキゼデクはサレムの王で、いと高き神の祭司でしたが、アブラハムが王たちを打ち破って帰るのを出迎えて祝福しました。'),
('JPN', '希伯来书', 58, 7, 2, 'アブラハムは彼に、すべての物の十分の一を分け与えました。彼の名は訳すと、まず「義の王」、次に「サレムの王」、すなわち「平和の王」です。'),
('JPN', '希伯来书', 58, 7, 3, '父もなく、母もなく、系図もなく、生涯の初めもなく、いのちの終わりもなく、神の子に似た者とされて、いつまでも祭司としてとどまっているのです。'),
('JPN', '希伯来书', 58, 7, 4, 'さて、その人がどんなに偉大であったかを考えてみなさい。族長であるアブラハムでさえ、彼に一番良い戦利品の十分の一を与えました。'),
('JPN', '希伯来书', 58, 7, 5, 'レビの子らの中で祭司職を受ける者たちは、同じアブラハムの子孫であるのに、民から、すなわち自分の兄弟たちから、十分の一を徴収するように、律法で命じられています。'),
('JPN', '希伯来书', 58, 7, 6, 'ところが、レビの子らの系図につながっていない者が、アブラハムから十分の一を受け取り、約束を受けたアブラハムを祝福しました。'),
('JPN', '希伯来书', 58, 7, 7, '言うまでもなく、より劣った者が、よりすぐれた者から祝福を受けるものです。'),
('JPN', '希伯来书', 58, 7, 8, '十分の一を受けているのは、一方では、死ぬべき人たちですが、他方では、生きていると証しされている人です。'),
('JPN', '希伯来书', 58, 7, 9, '言うならば、十分の一を受け取るレビでさえ、アブラハムを通して十分の一を納めたのでした。'),
('JPN', '希伯来书', 58, 7, 10, 'というのは、メルキゼデクがアブラハムを出迎えたとき、レビはまだ父の腰の中にいたからです。'),
('JPN', '希伯来书', 58, 7, 11, '民はレビ族の祭司職に基づいて律法を与えられました。もしその祭司職によって完全さに到達できたのなら、それ以上何の必要があって、アロンに倣ってではなく、メルキゼデクに倣ってと言われる、別の祭司が立てられたのでしょうか。'),
('JPN', '希伯来书', 58, 7, 12, '祭司職が変われば、必ず律法も変わらなければなりません。'),
('JPN', '希伯来书', 58, 7, 13, '私たちがこれまで語ってきた方は、祭壇に仕える者が出たことのない、別の部族に属しておられます。'),
('JPN', '希伯来书', 58, 7, 14, '私たちの主がユダ族から出られたことは明らかですが、この部族について、モーセは祭司に関することを何も述べていないのです。'),
('JPN', '希伯来书', 58, 7, 15, 'もしメルキゼデクと同じような、別の祭司が立つなら、以上のことはますます明らかになります。'),
('JPN', '希伯来书', 58, 7, 16, 'その祭司は、肉についての戒めである律法にはよらず、朽ちることのない、いのちの力によって祭司となったのです。'),
('JPN', '希伯来书', 58, 7, 17, 'この方について、こう証しされています。「あなたは、メルキゼデクの例に倣い、とこしえに祭司である。」'),
('JPN', '希伯来书', 58, 7, 18, '一方で、前の戒めは、弱く無益なために廃止され、'),
('JPN', '希伯来书', 58, 7, 19, '──律法は何も全うしなかったのです──もう一方では、もっとすぐれた希望が導き入れられました。これによって私たちは神に近づくのです。'),
('JPN', '希伯来书', 58, 7, 20, 'また、神による誓いなしではありません。レビの子らの場合は、神による誓いなしに祭司となっていますが、'),
('JPN', '希伯来书', 58, 7, 21, 'この方は、ご自分に対して言われた神の誓いによって祭司となられました。「主は誓われた。思い直されることはない。『あなたはとこしえに祭司である。』」'),
('JPN', '希伯来书', 58, 7, 22, 'その分、イエスは、もっとすぐれた契約の保証となられたのです。'),
('JPN', '希伯来书', 58, 7, 23, 'また、レビの子らの場合は、死ということがあるために、務めにいつまでもとどまることができず、大勢の者が祭司となっていますが、'),
('JPN', '希伯来书', 58, 7, 24, 'イエスは永遠に存在されるので、変わることがない祭司職を持っておられます。'),
('JPN', '希伯来书', 58, 7, 25, 'したがってイエスは、いつも生きていて、彼らのためにとりなしをしておられるので、ご自分によって神に近づく人々を完全に救うことがおできになります。'),
('JPN', '希伯来书', 58, 7, 26, 'このような方、敬虔で、悪も汚れもなく、罪人から離され、また天よりも高く上げられた大祭司こそ、私たちにとってまさに必要な方です。'),
('JPN', '希伯来书', 58, 7, 27, 'イエスは、ほかの大祭司たちのように、まず自分の罪のために、次に民の罪のために、毎日いけにえを献げる必要はありません。イエスは自分自身を献げ、ただ一度でそのことを成し遂げられたからです。'),
('JPN', '希伯来书', 58, 7, 28, '律法は、弱さを持つ人間たちを大祭司に立てますが、律法の後から来た誓いのみことばは、永遠に完全な者とされた御子を立てるのです。'),
('JPN', '希伯来书', 58, 8, 1, '以上述べてきたことの要点は、私たちにはこのような大祭司がおられるということです。この方は天におられる大いなる方の御座の右に座し、'),
('JPN', '希伯来书', 58, 8, 2, '人間によってではなく、主によって設けられた、まことの幕屋、聖所で仕えておられます。'),
('JPN', '希伯来书', 58, 8, 3, '大祭司はみな、ささげ物といけにえを献げるために任命されています。したがって、この大祭司も何か献げる物を持っていなければなりません。'),
('JPN', '希伯来书', 58, 8, 4, 'もしこの方が地上におられたなら、祭司であることは決してなかったでしょう。律法にしたがってささげ物をする祭司たちがいるからです。'),
('JPN', '希伯来书', 58, 8, 5, 'この祭司たちは、天にあるものの写しと影に仕えています。それは、モーセが幕屋を設営しようとしたときに、御告げを受けたとおりのものです。神は、「よく注意して、山であなたに示された型どおりに、すべてのものを作らなければならない」と言われました。'),
('JPN', '希伯来书', 58, 8, 6, 'しかし今、この大祭司は、よりすぐれた契約の仲介者であるだけに、その分、はるかにすぐれた奉仕を得ておられます。その契約は、よりすぐれた約束に基づいて制定されたものです。'),
('JPN', '希伯来书', 58, 8, 7, 'もしあの初めの契約が欠けのないものであったなら、第二の契約が必要になる余地はなかったはずです。'),
('JPN', '希伯来书', 58, 8, 8, '神は人々の欠けを責めて、こう言われました。「見よ、その時代が来る。──主のことば──そのとき、わたしはイスラエルの家、ユダの家との新しい契約を実現させる。'),
('JPN', '希伯来书', 58, 8, 9, 'その契約は、わたしが彼らの先祖の手を握ってエジプトの地から導き出した日に、彼らと結んだ契約のようではない。彼らはわたしの契約にとどまらなかったので、わたしも彼らを顧みなかった。──主のことば──'),
('JPN', '希伯来书', 58, 8, 10, 'これらの日の後に、わたしがイスラエルの家と結ぶ契約はこうである。──主のことば──わたしは、わたしの律法を彼らの思いの中に置き、彼らの心にこれを書き記す。わたしは彼らの神となり、彼らはわたしの民となる。'),
('JPN', '希伯来书', 58, 8, 11, '彼らはもはや、それぞれ仲間に、あるいはそれぞれ兄弟に、『主を知れ』と言って教えることはない。彼らがみな、小さい者から大きい者まで、わたしを知るようになるからだ。'),
('JPN', '希伯来书', 58, 8, 12, 'わたしが彼らの不義にあわれみをかけ、もはや彼らの罪を思い起こさないからだ。」'),
('JPN', '希伯来书', 58, 8, 13, '神は、「新しい契約」と呼ぶことで、初めの契約を古いものとされました。年を経て古びたものは、すぐに消えて行くのです。'),
('JPN', '希伯来书', 58, 9, 1, 'さて、初めの契約にも、礼拝の規定と地上の聖所がありました。'),
('JPN', '希伯来书', 58, 9, 2, 'すなわち、第一の幕屋が設けられ、そこには燭台と机と臨在のパンがありました。それが聖所と呼ばれる場所です。'),
('JPN', '希伯来书', 58, 9, 3, 'また、第二の垂れ幕のうしろには、至聖所と呼ばれる幕屋があり、'),
('JPN', '希伯来书', 58, 9, 4, 'そこには金の香壇と、全面を金でおおわれた契約の箱があり、箱の中には、マナの入った金の壺、芽を出したアロンの杖、契約の板がありました。'),
('JPN', '希伯来书', 58, 9, 5, 'また、箱の上で、栄光のケルビムが「宥めの蓋」をおおっていました。しかし、これらについて、今は一つ一つ述べることはできません。'),
('JPN', '希伯来书', 58, 9, 6, 'さて、これらの物が以上のように整えられたうえで、祭司たちはいつも第一の幕屋に入って、礼拝を行います。'),
('JPN', '希伯来书', 58, 9, 7, 'しかし、第二の幕屋には年に一度、大祭司だけが入ります。そのとき、自分のため、また民が知らずに犯した罪のために献げる血を携えずに、そこに入るようなことはありません。'),
('JPN', '希伯来书', 58, 9, 8, '聖霊は、次のことを示しておられます。すなわち、第一の幕屋が存続しているかぎり、聖所への道がまだ明らかにされていないということです。'),
('JPN', '希伯来书', 58, 9, 9, 'この幕屋は今の時を示す比喩です。それにしたがって、ささげ物といけにえが献げられますが、それらは礼拝する人の良心を完全にすることができません。'),
('JPN', '希伯来书', 58, 9, 10, 'それらは、ただ食物と飲み物と種々の洗いに関するもので、新しい秩序が立てられる時まで課せられた、からだに関する規定にすぎません。'),
('JPN', '希伯来书', 58, 9, 11, 'しかしキリストは、すでに実現したすばらしい事柄の大祭司として来られ、人の手で造った物でない、すなわち、この被造世界の物でない、もっと偉大な、もっと完全な幕屋を通り、'),
('JPN', '希伯来书', 58, 9, 12, 'また、雄やぎと子牛の血によってではなく、ご自分の血によって、ただ一度だけ聖所に入り、永遠の贖いを成し遂げられました。'),
('JPN', '希伯来书', 58, 9, 13, '雄やぎと雄牛の血や、若い雌牛の灰を汚れた人々に振りかけると、それが聖なるものとする働きをして、からだをきよいものにするのなら、'),
('JPN', '希伯来书', 58, 9, 14, 'まして、キリストが傷のないご自分を、とこしえの御霊によって神にお献げになったその血は、どれだけ私たちの良心をきよめて死んだ行いから離れさせ、生ける神に仕える者にすることでしょうか。'),
('JPN', '希伯来书', 58, 9, 15, 'キリストは新しい契約の仲介者です。それは、初めの契約のときの違反から贖い出すための死が実現して、召された者たちが、約束された永遠の資産を受け継ぐためです。'),
('JPN', '希伯来书', 58, 9, 16, '遺言には、遺言者の死亡証明が必要です。'),
('JPN', '希伯来书', 58, 9, 17, '遺言は人が死んだとき初めて有効になるのであって、遺言者が生きている間には、決して効力を持ちません。'),
('JPN', '希伯来书', 58, 9, 18, 'ですから、初めの契約も、血を抜きに成立したのではありません。'),
('JPN', '希伯来书', 58, 9, 19, 'モーセは、律法にしたがってすべての戒めを民全体に語った後、水と緋色の羊の毛とヒソプとともに、子牛と雄やぎの血を取って、契約の書自体にも民全体にも振りかけ、'),
('JPN', '希伯来书', 58, 9, 20, '「これは、神があなたがたに対して命じられた契約の血である」と言いました。'),
('JPN', '希伯来书', 58, 9, 21, 'また彼は、幕屋と、礼拝に用いるすべての用具にも同様に血を振りかけました。'),
('JPN', '希伯来书', 58, 9, 22, '律法によれば、ほとんどすべてのものは血によってきよめられます。血を流すことがなければ、罪の赦しはありません。'),
('JPN', '希伯来书', 58, 9, 23, 'ですから、天にあるものの写しは、これらのものによってきよめられる必要がありますが、天上にある本体そのものは、それ以上にすぐれたいけにえによって、きよめられる必要があります。'),
('JPN', '希伯来书', 58, 9, 24, 'キリストは、本物の模型にすぎない、人の手で造られた聖所に入られたのではなく、天そのものに入られたのです。そして今、私たちのために神の御前に現れてくださいます。'),
('JPN', '希伯来书', 58, 9, 25, 'それも、年ごとに自分の血でない血を携えて聖所に入る大祭司とは違い、キリストはご自分を何度も献げるようなことはなさいません。'),
('JPN', '希伯来书', 58, 9, 26, 'もし同じだとしたら、世界の基が据えられたときから、何度も苦難を受けなければならなかったでしょう。しかし今、キリストはただ一度だけ、世々の終わりに、ご自分をいけにえとして罪を取り除くために現れてくださいました。'),
('JPN', '希伯来书', 58, 9, 27, 'そして、人間には、一度死ぬことと死後にさばきを受けることが定まっているように、'),
('JPN', '希伯来书', 58, 9, 28, 'キリストも、多くの人の罪を負うために一度ご自分を献げ、二度目には、罪を負うためではなく、ご自分を待ち望んでいる人々の救いのために現れてくださいます。'),
('JPN', '希伯来书', 58, 10, 1, '律法には来たるべき良きものの影はあっても、その実物はありません。ですから律法は、年ごとに絶えず献げられる同じいけにえによって神に近づく人々を、完全にすることができません。'),
('JPN', '希伯来书', 58, 10, 2, 'それができたのなら、礼拝する人たちは一度できよめられて、もはや罪を意識することがなくなるので、いけにえを献げることは終わったはずです。'),
('JPN', '希伯来书', 58, 10, 3, 'ところがむしろ、これらのいけにえによって罪が年ごとに思い出されるのです。'),
('JPN', '希伯来书', 58, 10, 4, '雄牛と雄やぎの血は罪を除くことができないからです。'),
('JPN', '希伯来书', 58, 10, 5, 'ですからキリストは、この世界に来てこう言われました。「あなたは、いけにえやささげ物をお求めにならないで、わたしに、からだを備えてくださいました。'),
('JPN', '希伯来书', 58, 10, 6, '全焼のささげ物や罪のきよめのささげ物をあなたは、お喜びにはなりませんでした。'),
('JPN', '希伯来书', 58, 10, 7, 'そのとき、わたしは申しました。『今、わたしはここに来ております。巻物の書にわたしのことが書いてあります。神よ、あなたのみこころを行うために。』」'),
('JPN', '希伯来书', 58, 10, 8, '以上のとおり、キリストは「あなたは、いけにえやささげ物、全焼のささげ物や罪のきよめのささげ物、すなわち、律法にしたがって献げられる、いろいろな物を望まず、またそれらをお喜びになりませんでした」と言い、'),
('JPN', '希伯来书', 58, 10, 9, 'それから、「今、わたしはあなたのみこころを行うために来ました」と言われました。第二のものを立てるために、初めのものを廃止されるのです。'),
('JPN', '希伯来书', 58, 10, 10, 'このみこころにしたがって、イエス・キリストのからだが、ただ一度だけ献げられたことにより、私たちは聖なるものとされています。'),
('JPN', '希伯来书', 58, 10, 11, 'さらに、祭司がみな、毎日立って礼拝の務めをなし、同じいけにえを繰り返し献げても、それらは決して罪を除き去ることができませんが、'),
('JPN', '希伯来书', 58, 10, 12, 'キリストは、罪のために一つのいけにえを献げた後、永遠に神の右の座に着き、'),
('JPN', '希伯来书', 58, 10, 13, 'あとは、敵がご自分の足台とされるのを待っておられます。'),
('JPN', '希伯来书', 58, 10, 14, 'なぜなら、キリストは聖なるものとされる人々を、一つのささげ物によって永遠に完成されたからです。'),
('JPN', '希伯来书', 58, 10, 15, '聖霊もまた、私たちに証ししておられます。というのも、'),
('JPN', '希伯来书', 58, 10, 16, '「これらの日の後に、わたしが彼らと結ぶ契約はこうである。──主のことば──わたしは、わたしの律法を彼らの心に置き、彼らの思いにこれを書き記す」と言った後で、'),
('JPN', '希伯来书', 58, 10, 17, '「わたしは、もはや彼らの罪と不法を思い起こさない」と言われるからです。'),
('JPN', '希伯来书', 58, 10, 18, '罪と不法が赦されるところでは、もう罪のきよめのささげ物はいりません。'),
('JPN', '希伯来书', 58, 10, 19, 'こういうわけで、兄弟たち。私たちはイエスの血によって大胆に聖所に入ることができます。'),
('JPN', '希伯来书', 58, 10, 20, 'イエスはご自分の肉体という垂れ幕を通して、私たちのために、この新しい生ける道を開いてくださいました。'),
('JPN', '希伯来书', 58, 10, 21, 'また私たちには、神の家を治める、この偉大な祭司がおられるのですから、'),
('JPN', '希伯来书', 58, 10, 22, '心に血が振りかけられて、邪悪な良心をきよめられ、からだをきよい水で洗われ、全き信仰をもって真心から神に近づこうではありませんか。'),
('JPN', '希伯来书', 58, 10, 23, '約束してくださった方は真実な方ですから、私たちは動揺しないで、しっかりと希望を告白し続けようではありませんか。'),
('JPN', '希伯来书', 58, 10, 24, 'また、愛と善行を促すために、互いに注意を払おうではありませんか。'),
('JPN', '希伯来书', 58, 10, 25, 'ある人たちの習慣に倣って自分たちの集まりをやめたりせず、むしろ励まし合いましょう。その日が近づいていることが分かっているのですから、ますます励もうではありませんか。'),
('JPN', '希伯来书', 58, 10, 26, 'もし私たちが、真理の知識を受けた後、進んで罪にとどまり続けるなら、もはや罪のきよめのためにはいけにえは残されておらず、'),
('JPN', '希伯来书', 58, 10, 27, 'ただ、さばきと、逆らう者たちを焼き尽くす激しい火を、恐れながら待つしかありません。'),
('JPN', '希伯来书', 58, 10, 28, 'モーセの律法を拒否する者は、二人または三人の証人のことばに基づいて、あわれみを受けることなく死ぬことになります。'),
('JPN', '希伯来书', 58, 10, 29, 'まして、神の御子を踏みつけ、自分を聖なるものとした契約の血を汚れたものと見なし、恵みの御霊を侮る者は、いかに重い処罰に値するかが分かるでしょう。'),
('JPN', '希伯来书', 58, 10, 30, '私たちは、「復讐はわたしのもの、わたしが報復する。」また、「主は御民をさばかれる」と言われる方を知っています。'),
('JPN', '希伯来书', 58, 10, 31, '生ける神の手の中に陥ることは恐ろしいことです。'),
('JPN', '希伯来书', 58, 10, 32, 'あなたがたは、光に照らされた後で苦難との厳しい戦いに耐えた、初めの日々を思い起こしなさい。'),
('JPN', '希伯来书', 58, 10, 33, '嘲られ、苦しい目にあわされ、見せ物にされたこともあれば、このような目にあった人たちの同志となったこともあります。'),
('JPN', '希伯来书', 58, 10, 34, 'あなたがたは、牢につながれている人々と苦しみをともにし、また、自分たちにはもっとすぐれた、いつまでも残る財産があることを知っていたので、自分の財産が奪われても、それを喜んで受け入れました。'),
('JPN', '希伯来书', 58, 10, 35, 'ですから、あなたがたの確信を投げ捨ててはいけません。その確信には大きな報いがあります。'),
('JPN', '希伯来书', 58, 10, 36, 'あなたがたが神のみこころを行って、約束のものを手に入れるために必要なのは、忍耐です。'),
('JPN', '希伯来书', 58, 10, 37, '「もうしばらくすれば、来たるべき方が来られる。遅れることはない。'),
('JPN', '希伯来书', 58, 10, 38, 'わたしの義人は信仰によって生きる。もし恐れ退くなら、わたしの心は彼を喜ばない。」'),
('JPN', '希伯来书', 58, 10, 39, 'しかし私たちは、恐れ退いて滅びる者ではなく、信じていのちを保つ者です。'),
('JPN', '希伯来书', 58, 11, 1, 'さて、信仰は、望んでいることを保証し、目に見えないものを確信させるものです。'),
('JPN', '希伯来书', 58, 11, 2, '昔の人たちは、この信仰によって称賛されました。'),
('JPN', '希伯来书', 58, 11, 3, '信仰によって、私たちは、この世界が神のことばで造られたことを悟り、その結果、見えるものが、目に見えるものからできたのではないことを悟ります。'),
('JPN', '希伯来书', 58, 11, 4, '信仰によって、アベルはカインよりもすぐれたいけにえを神に献げ、そのいけにえによって、彼が正しい人であることが証しされました。神が、彼のささげ物を良いささげ物だと証ししてくださったからです。彼は死にましたが、その信仰によって今もなお語っています。'),
('JPN', '希伯来书', 58, 11, 5, '信仰によって、エノクは死を見ることがないように移されました。神が彼を移されたので、いなくなりました。彼が神に喜ばれていたことは、移される前から証しされていたのです。'),
('JPN', '希伯来书', 58, 11, 6, '信仰がなければ、神に喜ばれることはできません。神に近づく者は、神がおられることと、神がご自分を求める者には報いてくださる方であることを、信じなければならないのです。'),
('JPN', '希伯来书', 58, 11, 7, '信仰によって、ノアはまだ見ていない事柄について神から警告を受けたときに、恐れかしこんで家族の救いのために箱舟を造り、その信仰によって世を罪ありとし、信仰による義を受け継ぐ者となりました。'),
('JPN', '希伯来书', 58, 11, 8, '信仰によって、アブラハムは相続財産として受け取るべき地に出て行くようにと召しを受けたときに、それに従い、どこに行くのかを知らずに出て行きました。'),
('JPN', '希伯来书', 58, 11, 9, '信仰によって、彼は約束された地に他国人のようにして住み、同じ約束をともに受け継ぐイサクやヤコブと天幕生活をしました。'),
('JPN', '希伯来书', 58, 11, 10, '堅い基礎の上に建てられた都を待ち望んでいたからです。その都の設計者、また建設者は神です。'),
('JPN', '希伯来书', 58, 11, 11, 'アブラハムは、すでにその年を過ぎた身であり、サラ自身も不妊の女であったのに、信仰によって、子をもうける力を得ました。彼が、約束してくださった方を真実な方と考えたからです。'),
('JPN', '希伯来书', 58, 11, 12, 'こういうわけで、一人の、しかも死んだも同然の人から、天の星のように、また海辺の数えきれない砂のように数多くの子孫が生まれたのです。'),
('JPN', '希伯来书', 58, 11, 13, 'これらの人たちはみな、信仰の人として死にました。約束のものを手に入れることはありませんでしたが、はるか遠くにそれを見て喜び迎え、地上では旅人であり、寄留者であることを告白していました。'),
('JPN', '希伯来书', 58, 11, 14, 'そのように言っている人たちは、自分の故郷を求めていることを明らかにしています。'),
('JPN', '希伯来书', 58, 11, 15, 'もし彼らが思っていたのが、出て来た故郷だったなら、帰る機会はあったでしょう。'),
('JPN', '希伯来书', 58, 11, 16, 'しかし実際には、彼らが憧れていたのは、もっと良い故郷、すなわち天の故郷でした。ですから神は、彼らの神と呼ばれることを恥となさいませんでした。神が彼らのために都を用意されたのです。'),
('JPN', '希伯来书', 58, 11, 17, '信仰によって、アブラハムは試みを受けたときにイサクを献げました。約束を受けていた彼が、自分のただひとりの子を献げようとしたのです。'),
('JPN', '希伯来书', 58, 11, 18, '神はアブラハムに「イサクにあって、あなたの子孫が起こされる」と言われましたが、'),
('JPN', '希伯来书', 58, 11, 19, '彼は、神には人を死者の中からよみがえらせることもできると考えました。それで彼は、比喩的に言えば、イサクを死者の中から取り戻したのです。'),
('JPN', '希伯来书', 58, 11, 20, '信仰によって、イサクはやがて起こることについて、ヤコブとエサウを祝福しました。'),
('JPN', '希伯来书', 58, 11, 21, '信仰によって、ヤコブは死ぬときに、ヨセフの息子たちをそれぞれ祝福し、また自分の杖の上に寄りかかって礼拝しました。'),
('JPN', '希伯来书', 58, 11, 22, '信仰によって、ヨセフは臨終のときに、イスラエルの子らの脱出について語り、自分の遺骸について指示を与えました。'),
('JPN', '希伯来书', 58, 11, 23, '信仰によって、モーセは生まれてから三か月の間、両親によって隠されていました。彼らがその子のかわいいのを見、また、王の命令を恐れなかったからです。'),
('JPN', '希伯来书', 58, 11, 24, '信仰によって、モーセは成人したときに、ファラオの娘の息子と呼ばれることを拒み、'),
('JPN', '希伯来书', 58, 11, 25, 'はかない罪の楽しみにふけるよりも、むしろ神の民とともに苦しむことを選び取りました。'),
('JPN', '希伯来书', 58, 11, 26, '彼は、キリストのゆえに受ける辱めを、エジプトの宝にまさる大きな富と考えました。それは、与えられる報いから目を離さなかったからでした。'),
('JPN', '希伯来书', 58, 11, 27, '信仰によって、彼は王の憤りを恐れることなくエジプトを立ち去りました。目に見えない方を見ているようにして、忍び通したのです。'),
('JPN', '希伯来书', 58, 11, 28, '信仰によって、彼は長子を滅ぼす者が自分たちに触れることがないように、過越の食事をし、血を振りかけました。'),
('JPN', '希伯来书', 58, 11, 29, '信仰によって、人々は乾いた陸地を行くのと同じように紅海を渡りました。エジプト人たちは同じことをしようとしましたが、水に吞み込まれてしまいました。'),
('JPN', '希伯来书', 58, 11, 30, '信仰によって、人々が七日間エリコの周囲を回ると、その城壁は崩れ落ちました。'),
('JPN', '希伯来书', 58, 11, 31, '信仰によって、遊女ラハブは、偵察に来た人たちを穏やかに受け入れたので、不従順な者たちと一緒に滅びずにすみました。'),
('JPN', '希伯来书', 58, 11, 32, 'これ以上、何を言いましょうか。もし、ギデオン、バラク、サムソン、エフタ、またダビデ、サムエル、預言者たちについても語れば、時間が足りないでしょう。'),
('JPN', '希伯来书', 58, 11, 33, '彼らは信仰によって、国々を征服し、正しいことを行い、約束のものを手に入れ、獅子の口をふさぎ、'),
('JPN', '希伯来书', 58, 11, 34, '火の勢いを消し、剣の刃を逃れ、弱い者なのに強くされ、戦いの勇士となり、他国の陣営を敗走させました。'),
('JPN', '希伯来书', 58, 11, 35, '女たちは、死んだ身内の者たちをよみがえらせていただきました。また、ほかの人たちは、もっとすぐれたよみがえりを得るために、釈放されることを拒んで拷問を受けました。'),
('JPN', '希伯来书', 58, 11, 36, 'また、ほかの人たちは嘲られ、むちで打たれ、さらに鎖につながれて牢に入れられる経験をし、'),
('JPN', '希伯来书', 58, 11, 37, 'また、石で打たれ、のこぎりで引かれ、剣で切り殺され、羊ややぎの皮を着て歩き回り、困窮し、圧迫され、虐待されました。'),
('JPN', '希伯来书', 58, 11, 38, 'この世は彼らにふさわしくありませんでした。彼らは荒野、山、洞穴、地の穴をさまよいました。'),
('JPN', '希伯来书', 58, 11, 39, 'これらの人たちはみな、その信仰によって称賛されましたが、約束されたものを手に入れることはありませんでした。'),
('JPN', '希伯来书', 58, 11, 40, '神は私たちのために、もっとすぐれたものを用意しておられたので、私たちを抜きにして、彼らが完全な者とされることはなかったのです。'),
('JPN', '希伯来书', 58, 12, 1, 'こういうわけで、このように多くの証人たちが、雲のように私たちを取り巻いているのですから、私たちも、一切の重荷とまとわりつく罪を捨てて、自分の前に置かれている競走を、忍耐をもって走り続けようではありませんか。'),
('JPN', '希伯来书', 58, 12, 2, '信仰の創始者であり完成者であるイエスから、目を離さないでいなさい。この方は、ご自分の前に置かれた喜びのために、辱めをものともせずに十字架を忍び、神の御座の右に着座されたのです。'),
('JPN', '希伯来书', 58, 12, 3, 'あなたがたは、罪人たちの、ご自分に対するこのような反抗を耐え忍ばれた方のことを考えなさい。あなたがたの心が元気を失い、疲れ果ててしまわないようにするためです。'),
('JPN', '希伯来书', 58, 12, 4, 'あなたがたは、罪と戦って、まだ血を流すまで抵抗したことがありません。'),
('JPN', '希伯来书', 58, 12, 5, 'そして、あなたがたに向かって子どもたちに対するように語られた、この励ましのことばを忘れています。「わが子よ、主の訓練を軽んじてはならない。主に叱られて気落ちしてはならない。'),
('JPN', '希伯来书', 58, 12, 6, '主はその愛する者を訓練し、受け入れるすべての子に、むちを加えられるのだから。」'),
('JPN', '希伯来书', 58, 12, 7, '訓練として耐え忍びなさい。神はあなたがたを子として扱っておられるのです。父が訓練しない子がいるでしょうか。'),
('JPN', '希伯来书', 58, 12, 8, 'もしあなたがたが、すべての子が受けている訓練を受けていないとしたら、私生児であって、本当の子ではありません。'),
('JPN', '希伯来书', 58, 12, 9, 'さらに、私たちには肉の父がいて、私たちを訓練しましたが、私たちはその父たちを尊敬していました。それなら、なおのこと、私たちは霊の父に服従して生きるべきではないでしょうか。'),
('JPN', '希伯来书', 58, 12, 10, '肉の父はわずかの間、自分が良いと思うことにしたがって私たちを訓練しましたが、霊の父は私たちの益のために、私たちをご自分の聖さにあずからせようとして訓練されるのです。'),
('JPN', '希伯来书', 58, 12, 11, 'すべての訓練は、そのときは喜ばしいものではなく、かえって苦しく思われるものですが、後になると、これによって鍛えられた人々に、義という平安の実を結ばせます。'),
('JPN', '希伯来书', 58, 12, 12, 'ですから、弱った手と衰えた膝をまっすぐにしなさい。'),
('JPN', '希伯来书', 58, 12, 13, 'また、あなたがたは自分の足のために、まっすぐな道を作りなさい。足の不自由な人が踏み外すことなく、むしろ癒やされるためです。'),
('JPN', '希伯来书', 58, 12, 14, 'すべての人との平和を追い求め、また、聖さを追い求めなさい。聖さがなければ、だれも主を見ることができません。'),
('JPN', '希伯来书', 58, 12, 15, 'だれも神の恵みから落ちないように、また、苦い根が生え出て悩ませたり、これによって多くの人が汚されたりしないように、気をつけなさい。'),
('JPN', '希伯来书', 58, 12, 16, 'また、だれも、一杯の食物と引き替えに自分の長子の権利を売ったエサウのように、淫らな者、俗悪な者にならないようにしなさい。'),
('JPN', '希伯来书', 58, 12, 17, 'あなたがたが知っているとおり、彼は後になって祝福を受け継ぎたいと思ったのですが、退けられました。涙を流して求めても、彼には悔い改めの機会が残っていませんでした。'),
('JPN', '希伯来书', 58, 12, 18, 'あなたがたが近づいているのは、手でさわれるもの、燃える火、黒雲、暗闇、嵐、'),
('JPN', '希伯来书', 58, 12, 19, 'ラッパの響き、ことばのとどろきではありません。そのことばのとどろきを聞いた者たちは、それ以上一言も自分たちに語らないでくださいと懇願しました。'),
('JPN', '希伯来书', 58, 12, 20, '彼らは、「たとえ獣でも、山に触れるものは石で打ち殺されなければならない」という命令に耐えることができませんでした。'),
('JPN', '希伯来书', 58, 12, 21, 'また、その光景があまりに恐ろしかったので、モーセは「私は怖くて震える」と言いました。'),
('JPN', '希伯来书', 58, 12, 22, 'しかし、あなたがたが近づいているのは、シオンの山、生ける神の都である天上のエルサレム、無数の御使いたちの喜びの集い、'),
('JPN', '希伯来书', 58, 12, 23, '天に登録されている長子たちの教会、すべての人のさばき主である神、完全な者とされた義人たちの霊、'),
('JPN', '希伯来书', 58, 12, 24, 'さらに、新しい契約の仲介者イエス、それに、アベルの血よりもすぐれたことを語る、注ぎかけられたイエスの血です。'),
('JPN', '希伯来书', 58, 12, 25, 'あなたがたは、語っておられる方を拒まないように気をつけなさい。地上において、警告を与える方を拒んだ彼らが処罰を免れなかったとすれば、まして、天から警告を与える方に私たちが背を向けるなら、なおのこと処罰を免れられません。'),
('JPN', '希伯来书', 58, 12, 26, 'あのときは御声が地を揺り動かしましたが、今は、こう約束しておられます。「もう一度、わたしは、地だけではなく天も揺り動かす。」'),
('JPN', '希伯来书', 58, 12, 27, 'この「もう一度」ということばは、揺り動かされないものが残るために、揺り動かされるもの、すなわち造られたものが取り除かれることを示しています。'),
('JPN', '希伯来书', 58, 12, 28, 'このように揺り動かされない御国を受けるのですから、私たちは感謝しようではありませんか。感謝しつつ、敬虔と恐れをもって、神に喜ばれる礼拝をささげようではありませんか。'),
('JPN', '希伯来书', 58, 12, 29, '私たちの神は焼き尽くす火なのです。'),
('JPN', '希伯来书', 58, 13, 1, '兄弟愛をいつも持っていなさい。'),
('JPN', '希伯来书', 58, 13, 2, '旅人をもてなすことを忘れてはいけません。そうすることで、ある人たちは、知らずに御使いたちをもてなしました。'),
('JPN', '希伯来书', 58, 13, 3, '牢につながれている人々を、自分も牢にいる気持ちで思いやりなさい。また、自分も肉体を持っているのですから、虐げられている人々を思いやりなさい。'),
('JPN', '希伯来书', 58, 13, 4, '結婚がすべての人の間で尊ばれ、寝床が汚されることのないようにしなさい。神は、淫行を行う者と姦淫を行う者をさばかれるからです。'),
('JPN', '希伯来书', 58, 13, 5, '金銭を愛する生活をせずに、今持っているもので満足しなさい。主ご自身が「わたしは決してあなたを見放さず、あなたを見捨てない」と言われたからです。'),
('JPN', '希伯来书', 58, 13, 6, 'ですから、私たちは確信をもって言います。「主は私の助け手。私は恐れない。人が私に何ができるだろうか。」'),
('JPN', '希伯来书', 58, 13, 7, '神のことばをあなたがたに話した指導者たちのことを、覚えていなさい。彼らの生き方から生まれたものをよく見て、その信仰に倣いなさい。'),
('JPN', '希伯来书', 58, 13, 8, 'イエス・キリストは、昨日も今日も、とこしえに変わることがありません。'),
('JPN', '希伯来书', 58, 13, 9, '様々な異なった教えによって迷わされてはいけません。食物の規定によらず、恵みによって心を強くするのは良いことです。食物の規定にしたがって歩んでいる者たちは、益を得ませんでした。'),
('JPN', '希伯来书', 58, 13, 10, '私たちには一つの祭壇があります。幕屋で仕えている者たちには、この祭壇から食べる権利がありません。'),
('JPN', '希伯来书', 58, 13, 11, '動物の血は、罪のきよめのささげ物として、大祭司によって聖所の中に持って行かれますが、からだは宿営の外で焼かれるのです。'),
('JPN', '希伯来书', 58, 13, 12, 'それでイエスも、ご自分の血によって民を聖なるものとするために、門の外で苦しみを受けられました。'),
('JPN', '希伯来书', 58, 13, 13, 'ですから私たちは、イエスの辱めを身に負い、宿営の外に出て、みもとに行こうではありませんか。'),
('JPN', '希伯来书', 58, 13, 14, '私たちは、いつまでも続く都をこの地上に持っているのではなく、むしろ来たるべき都を求めているのです。'),
('JPN', '希伯来书', 58, 13, 15, 'それなら、私たちはイエスを通して、賛美のいけにえ、御名をたたえる唇の果実を、絶えず神にささげようではありませんか。'),
('JPN', '希伯来书', 58, 13, 16, '善を行うことと、分かち合うことを忘れてはいけません。そのようないけにえを、神は喜ばれるのです。'),
('JPN', '希伯来书', 58, 13, 17, 'あなたがたの指導者たちの言うことを聞き、また服従しなさい。この人たちは神に申し開きをする者として、あなたがたのたましいのために見張りをしているのです。ですから、この人たちが喜んでそのことをし、嘆きながらすることにならないようにしなさい。そうでないと、あなたがたの益にはならないからです。'),
('JPN', '希伯来书', 58, 13, 18, '私たちのために祈ってください。私たちは正しい良心を持っていると確信しており、何事についても正しく行動したいと思っているからです。'),
('JPN', '希伯来书', 58, 13, 19, '私があなたがたのもとに早く戻れるように、なおいっそう祈ってくださるよう、お願いします。'),
('JPN', '希伯来书', 58, 13, 20, '永遠の契約の血による羊の大牧者、私たちの主イエスを、死者の中から導き出された平和の神が、'),
('JPN', '希伯来书', 58, 13, 21, 'あらゆる良いものをもって、あなたがたを整え、みこころを行わせてくださいますように。また、御前でみこころにかなうことを、イエス・キリストを通して、私たちのうちに行ってくださいますように。栄光が世々限りなくイエス・キリストにありますように。アーメン。'),
('JPN', '希伯来书', 58, 13, 22, '兄弟たちよ、あなたがたにお願いします。このような勧めのことばを耐え忍んでください。私は手短に書いたのです。'),
('JPN', '希伯来书', 58, 13, 23, '私たちの兄弟テモテが釈放されたことを、お知らせします。もし彼が早く来れば、私は彼と一緒にあなたがたに会えるでしょう。'),
('JPN', '希伯来书', 58, 13, 24, 'あなたがたのすべての指導者たち、また、すべての聖徒たちによろしく。イタリアから来た人たちが、あなたがたによろしくと言っています。'),
('JPN', '希伯来书', 58, 13, 25, '恵みがあなたがたすべてとともにありますように。'),
('JPN', '雅各书', 59, 1, 1, '神と主イエス・キリストのしもべヤコブが、離散している十二部族にあいさつを送ります。'),
('JPN', '雅各书', 59, 1, 2, '私の兄弟たち。様々な試練にあうときはいつでも、この上もない喜びと思いなさい。'),
('JPN', '雅各书', 59, 1, 3, 'あなたがたが知っているとおり、信仰が試されると忍耐が生まれます。'),
('JPN', '雅各书', 59, 1, 4, 'その忍耐を完全に働かせなさい。そうすれば、あなたがたは何一つ欠けたところのない、成熟した、完全な者となります。'),
('JPN', '雅各书', 59, 1, 5, 'あなたがたのうちに、知恵に欠けている人がいるなら、その人は、だれにでも惜しみなく、とがめることなく与えてくださる神に求めなさい。そうすれば与えられます。'),
('JPN', '雅各书', 59, 1, 6, 'ただし、少しも疑わずに、信じて求めなさい。疑う人は、風に吹かれて揺れ動く、海の大波のようです。'),
('JPN', '雅各书', 59, 1, 7, 'その人は、主から何かをいただけると思ってはなりません。'),
('JPN', '雅各书', 59, 1, 8, 'そういう人は二心を抱く者で、歩む道すべてにおいて心が定まっていないからです。'),
('JPN', '雅各书', 59, 1, 9, '身分の低い兄弟は、自分が高められることを誇りとしなさい。'),
('JPN', '雅各书', 59, 1, 10, '富んでいる人は、自分が低くされることを誇りとしなさい。富んでいる人は草の花のように過ぎ去って行くのです。'),
('JPN', '雅各书', 59, 1, 11, '太陽が昇って炎熱をもたらすと、草を枯らします。すると花は落ち、美しい姿は失われます。そのように、富んでいる人も旅路の途中で消えて行くのです。'),
('JPN', '雅各书', 59, 1, 12, '試練に耐える人は幸いです。耐え抜いた人は、神を愛する者たちに約束された、いのちの冠を受けるからです。'),
('JPN', '雅各书', 59, 1, 13, 'だれでも誘惑されているとき、神に誘惑されていると言ってはいけません。神は悪に誘惑されることのない方であり、ご自分でだれかを誘惑することもありません。'),
('JPN', '雅各书', 59, 1, 14, '人が誘惑にあうのは、それぞれ自分の欲に引かれ、誘われるからです。'),
('JPN', '雅各书', 59, 1, 15, 'そして、欲がはらんで罪を生み、罪が熟して死を生みます。'),
('JPN', '雅各书', 59, 1, 16, '私の愛する兄弟たち、思い違いをしてはいけません。'),
('JPN', '雅各书', 59, 1, 17, 'すべての良い贈り物、またすべての完全な賜物は、上からのものであり、光を造られた父から下って来るのです。父には、移り変わりや、天体の運行によって生じる影のようなものはありません。'),
('JPN', '雅各书', 59, 1, 18, 'この父が私たちを、いわば被造物の初穂にするために、みこころのままに真理のことばをもって生んでくださいました。'),
('JPN', '雅各书', 59, 1, 19, '私の愛する兄弟たち、このことをわきまえていなさい。人はだれでも、聞くのに早く、語るのに遅く、怒るのに遅くありなさい。'),
('JPN', '雅各书', 59, 1, 20, '人の怒りは神の義を実現しないのです。'),
('JPN', '雅各书', 59, 1, 21, 'ですから、すべての汚れやあふれる悪を捨て去り、心に植えつけられたみことばを素直に受け入れなさい。みことばは、あなたがたのたましいを救うことができます。'),
('JPN', '雅各书', 59, 1, 22, 'みことばを行う人になりなさい。自分を欺いて、ただ聞くだけの者となってはいけません。'),
('JPN', '雅各书', 59, 1, 23, 'みことばを聞いても行わない人がいるなら、その人は自分の生まれつきの顔を鏡で眺める人のようです。'),
('JPN', '雅各书', 59, 1, 24, '眺めても、そこを離れると、自分がどのようであったか、すぐに忘れてしまいます。'),
('JPN', '雅各书', 59, 1, 25, 'しかし、自由をもたらす完全な律法を一心に見つめて、それから離れない人は、すぐに忘れる聞き手にはならず、実際に行う人になります。こういう人は、その行いによって祝福されます。'),
('JPN', '雅各书', 59, 1, 26, '自分は宗教心にあついと思っても、自分の舌を制御せず、自分の心を欺いているなら、そのような人の宗教はむなしいものです。'),
('JPN', '雅各书', 59, 1, 27, '父である神の御前できよく汚れのない宗教とは、孤児ややもめたちが困っているときに世話をし、この世の汚れに染まらないよう自分を守ることです。'),
('JPN', '雅各书', 59, 2, 1, '私の兄弟たち。あなたがたは、私たちの主、栄光のイエス・キリストへの信仰を持っていながら、人をえこひいきすることがあってはなりません。'),
('JPN', '雅各书', 59, 2, 2, 'あなたがたの集会に、金の指輪をはめた立派な身なりの人が入って来て、また、みすぼらしい身なりの貧しい人も入って来たとします。'),
('JPN', '雅各书', 59, 2, 3, 'あなたがたは、立派な身なりをした人に目を留めて、「あなたはこちらの良い席にお座りください」と言い、貧しい人には、「あなたは立っていなさい。でなければ、そこに、私の足もとに座りなさい」と言うなら、'),
('JPN', '雅各书', 59, 2, 4, '自分たちの間で差別をし、悪い考えでさばく者となったのではありませんか。'),
('JPN', '雅各书', 59, 2, 5, '私の愛する兄弟たち、よく聞きなさい。神は、この世の貧しい人たちを選んで信仰に富む者とし、神を愛する者に約束された御国を受け継ぐ者とされたではありませんか。'),
('JPN', '雅各书', 59, 2, 6, 'それなのに、あなたがたは貧しい人を辱めたのです。あなたがたを虐げるのは富んでいる人たちではありませんか。また、あなたがたを裁判所に引いて行くのも彼らではありませんか。'),
('JPN', '雅各书', 59, 2, 7, 'あなたがたがその名で呼ばれている尊い御名を汚すのも、彼らではありませんか。'),
('JPN', '雅各书', 59, 2, 8, 'もし本当に、あなたがたが聖書にしたがって、「あなたの隣人を自分自身のように愛しなさい」という最高の律法を守るなら、あなたがたの行いは立派です。'),
('JPN', '雅各书', 59, 2, 9, 'しかし、もし人をえこひいきするなら、あなたがたは罪を犯しており、律法によって違反者として責められます。'),
('JPN', '雅各书', 59, 2, 10, '律法全体を守っても、一つの点で過ちを犯すなら、その人はすべてについて責任を問われるからです。'),
('JPN', '雅各书', 59, 2, 11, '「姦淫してはならない」と言われた方は、「殺してはならない」とも言われました。ですから、姦淫しなくても人殺しをすれば、あなたは律法の違反者になっているのです。'),
('JPN', '雅各书', 59, 2, 12, '自由をもたらす律法によってさばかれることになる者として、ふさわしく語り、ふさわしく行いなさい。'),
('JPN', '雅各书', 59, 2, 13, 'あわれみを示したことがない者に対しては、あわれみのないさばきが下されます。あわれみがさばきに対して勝ち誇るのです。'),
('JPN', '雅各书', 59, 2, 14, '私の兄弟たち。だれかが自分には信仰があると言っても、その人に行いがないなら、何の役に立つでしょうか。そのような信仰がその人を救うことができるでしょうか。'),
('JPN', '雅各书', 59, 2, 15, '兄弟か姉妹に着る物がなく、毎日の食べ物にも事欠いているようなときに、'),
('JPN', '雅各书', 59, 2, 16, 'あなたがたのうちのだれかが、その人たちに、「安心して行きなさい。温まりなさい。満腹になるまで食べなさい」と言っても、からだに必要な物を与えなければ、何の役に立つでしょう。'),
('JPN', '雅各书', 59, 2, 17, '同じように、信仰も行いが伴わないなら、それだけでは死んだものです。'),
('JPN', '雅各书', 59, 2, 18, 'しかし、「ある人には信仰があるが、ほかの人には行いがあります」と言う人がいるでしょう。行いのないあなたの信仰を私に見せてください。私は行いによって、自分の信仰をあなたに見せてあげます。'),
('JPN', '雅各书', 59, 2, 19, 'あなたは、神は唯一だと信じています。立派なことです。ですが、悪霊どもも信じて、身震いしています。'),
('JPN', '雅各书', 59, 2, 20, 'ああ愚かな人よ。あなたは、行いのない信仰が無益なことを知りたいのですか。'),
('JPN', '雅各书', 59, 2, 21, '私たちの父アブラハムは、その子イサクを祭壇に献げたとき、行いによって義と認められたではありませんか。'),
('JPN', '雅各书', 59, 2, 22, 'あなたが見ているとおり、信仰がその行いとともに働き、信仰は行いによって完成されました。'),
('JPN', '雅各书', 59, 2, 23, '「アブラハムは神を信じた。それで、それが彼の義と認められた」という聖書のことばが実現し、彼は神の友と呼ばれたのです。'),
('JPN', '雅各书', 59, 2, 24, '人は行いによって義と認められるのであって、信仰だけによるのではないことが分かるでしょう。'),
('JPN', '雅各书', 59, 2, 25, '同じように遊女ラハブも、使者たちを招き入れ、別の道から送り出したので、その行いによって義と認められたではありませんか。'),
('JPN', '雅各书', 59, 2, 26, 'からだが霊を欠いては死んでいるのと同じように、信仰も行いを欠いては死んでいるのです。'),
('JPN', '雅各书', 59, 3, 1, '私の兄弟たち、多くの人が教師になってはいけません。あなたがたが知っているように、私たち教師は、より厳しいさばきを受けます。'),
('JPN', '雅各书', 59, 3, 2, '私たちはみな、多くの点で過ちを犯すからです。もし、ことばで過ちを犯さない人がいたら、その人はからだ全体も制御できる完全な人です。'),
('JPN', '雅各书', 59, 3, 3, '馬を御するためには、その口にくつわをはめれば、馬のからだ全体を思いどおりに動かすことができます。'),
('JPN', '雅各书', 59, 3, 4, 'また船を見なさい。あのように大きくて、強風を受けていても、ごく小さい舵によって、舵を取る人の思いどおりのところへ導かれます。'),
('JPN', '雅各书', 59, 3, 5, '同じように、舌も小さな器官ですが、大きなことを言って自慢します。見なさい。あのように小さな火が、あのように大きな森を燃やします。'),
('JPN', '雅各书', 59, 3, 6, '舌は火です。不義の世界です。舌は私たちの諸器官の中にあってからだ全体を汚し、人生の車輪を燃やして、ゲヘナの火によって焼かれます。'),
('JPN', '雅各书', 59, 3, 7, 'どのような種類の獣も鳥も、這うものも海の生き物も、人類によって制することができ、すでに制せられています。'),
('JPN', '雅各书', 59, 3, 8, 'しかし、舌を制することができる人は、だれもいません。舌は休むことのない悪であり、死の毒で満ちています。'),
('JPN', '雅各书', 59, 3, 9, '私たちは、舌で、主であり父である方をほめたたえ、同じ舌で、神の似姿に造られた人間を呪います。'),
('JPN', '雅各书', 59, 3, 10, '同じ口から賛美と呪いが出て来るのです。私の兄弟たち、そのようなことが、あってはなりません。'),
('JPN', '雅各书', 59, 3, 11, '泉が、甘い水と苦い水を同じ穴から湧き出させるでしょうか。'),
('JPN', '雅各书', 59, 3, 12, '私の兄弟たち。いちじくの木がオリーブの実をならせたり、ぶどうの木がいちじくの実をならせたりすることができるでしょうか。塩水も甘い水を出すことはできません。'),
('JPN', '雅各书', 59, 3, 13, 'あなたがたのうちで、知恵があり、分別のある人はだれでしょうか。その人はその知恵にふさわしい柔和な行いを、立派な生き方によって示しなさい。'),
('JPN', '雅各书', 59, 3, 14, 'しかし、もしあなたがたの心の中に、苦々しいねたみや利己的な思いがあるなら、自慢したり、真理に逆らって偽ったりするのはやめなさい。'),
('JPN', '雅各书', 59, 3, 15, 'そのような知恵は上から来たものではなく、地上のもの、肉的で悪魔的なものです。'),
('JPN', '雅各书', 59, 3, 16, 'ねたみや利己的な思いのあるところには、秩序の乱れや、あらゆる邪悪な行いがあるからです。'),
('JPN', '雅各书', 59, 3, 17, 'しかし、上からの知恵は、まず第一に清いものです。それから、平和で、優しく、協調性があり、あわれみと良い実に満ち、偏見がなく、偽善もありません。'),
('JPN', '雅各书', 59, 3, 18, '義の実を結ばせる種は、平和をつくる人々によって平和のうちに蒔かれるのです。'),
('JPN', '雅各书', 59, 4, 1, 'あなたがたの間の戦いや争いは、どこから出て来るのでしょうか。ここから、すなわち、あなたがたのからだの中で戦う欲望から出て来るのではありませんか。'),
('JPN', '雅各书', 59, 4, 2, 'あなたがたは、欲しても自分のものにならないと、人殺しをします。熱望しても手に入れることができないと、争ったり戦ったりします。自分のものにならないのは、あなたがたが求めないからです。'),
('JPN', '雅各书', 59, 4, 3, '求めても得られないのは、自分の快楽のために使おうと、悪い動機で求めるからです。'),
('JPN', '雅各书', 59, 4, 4, '節操のない者たち。世を愛することは神に敵対することだと分からないのですか。世の友となりたいと思う者はだれでも、自分を神の敵としているのです。'),
('JPN', '雅各书', 59, 4, 5, 'それとも、聖書は意味もなく語っていると思いますか。「神は、私たちのうちに住まわせた御霊を、ねたむほどに慕っておられる。'),
('JPN', '雅各书', 59, 4, 6, '神は、さらに豊かな恵みを与えてくださる」と。それで、こう言われています。「神は高ぶる者には敵対し、へりくだった者には恵みを与える。」'),
('JPN', '雅各书', 59, 4, 7, 'ですから、神に従い、悪魔に対抗しなさい。そうすれば、悪魔はあなたがたから逃げ去ります。'),
('JPN', '雅各书', 59, 4, 8, '神に近づきなさい。そうすれば、神はあなたがたに近づいてくださいます。罪人たち、手をきよめなさい。二心の者たち、心を清めなさい。'),
('JPN', '雅各书', 59, 4, 9, '嘆きなさい。悲しみなさい。泣きなさい。あなたがたの笑いを悲しみに、喜びを憂いに変えなさい。'),
('JPN', '雅各书', 59, 4, 10, '主の御前でへりくだりなさい。そうすれば、主があなたがたを高く上げてくださいます。'),
('JPN', '雅各书', 59, 4, 11, '兄弟たち、互いに悪口を言い合ってはいけません。自分の兄弟について悪口を言ったり、さばいたりする者は、律法について悪口を言い、律法をさばいているのです。もしあなたが律法をさばくなら、律法を行う者ではなく、さばく者です。'),
('JPN', '雅各书', 59, 4, 12, '律法を定め、さばきを行う方はただひとりで、救うことも滅ぼすこともできる方です。隣人をさばくあなたは、いったい何者ですか。'),
('JPN', '雅各书', 59, 4, 13, '「今日か明日、これこれの町に行き、そこに一年いて、商売をしてもうけよう」と言っている者たち、よく聞きなさい。'),
('JPN', '雅各书', 59, 4, 14, 'あなたがたには、明日のことは分かりません。あなたがたのいのちとは、どのようなものでしょうか。あなたがたは、しばらくの間現れて、それで消えてしまう霧です。'),
('JPN', '雅各书', 59, 4, 15, 'あなたがたはむしろ、「主のみこころであれば、私たちは生きて、このこと、あるいは、あのことをしよう」と言うべきです。'),
('JPN', '雅各书', 59, 4, 16, 'ところが実際には、あなたがたは大言壮語して誇っています。そのような誇りはすべて悪いことです。'),
('JPN', '雅各书', 59, 4, 17, 'こういうわけで、なすべき良いことを知っていながら行わないなら、それはその人には罪です。'),
('JPN', '雅各书', 59, 5, 1, '金持ちたちよ、よく聞きなさい。迫り来る自分たちの不幸を思って、泣き叫びなさい。'),
('JPN', '雅各书', 59, 5, 2, 'あなたがたの富は腐り、あなたがたの衣は虫に食われ、'),
('JPN', '雅各书', 59, 5, 3, 'あなたがたの金銀はさびています。そのさびがあなたがたを責める証言となり、あなたがたの肉を火のように食い尽くします。あなたがたは、終わりの日に財を蓄えたのです。'),
('JPN', '雅各书', 59, 5, 4, '見なさい。あなたがたの畑の刈り入れをした労働者への未払い賃金が、叫び声をあげています。刈り入れをした人たちの叫び声は、万軍の主の耳に届いています。'),
('JPN', '雅各书', 59, 5, 5, 'あなたがたは地上でぜいたくに暮らし、快楽にふけり、屠られる日のために自分の心を太らせました。'),
('JPN', '雅各书', 59, 5, 6, 'あなたがたは、正しい人を不義に定めて殺しました。彼はあなたがたに抵抗しません。'),
('JPN', '雅各书', 59, 5, 7, 'ですから、兄弟たち。主が来られる時まで耐え忍びなさい。見なさい。農夫は大地の貴重な実りを、初めの雨や後の雨が降るまで耐え忍んで待っています。'),
('JPN', '雅各书', 59, 5, 8, 'あなたがたも耐え忍びなさい。心を強くしなさい。主が来られる時が近づいているからです。'),
('JPN', '雅各书', 59, 5, 9, '兄弟たち。さばかれることがないように、互いに文句を言い合うのはやめなさい。見なさい。さばきを行う方が戸口のところに立っておられます。'),
('JPN', '雅各书', 59, 5, 10, '兄弟たち。苦難と忍耐については、主の御名によって語った預言者たちを模範にしなさい。'),
('JPN', '雅各书', 59, 5, 11, '見なさい。耐え忍んだ人たちは幸いだと私たちは思います。あなたがたはヨブの忍耐のことを聞き、主によるその結末を知っています。主は慈愛に富み、あわれみに満ちておられます。'),
('JPN', '雅各书', 59, 5, 12, '私の兄弟たち。とりわけ、誓うことはやめなさい。天にかけても地にかけても、ほかの何にかけても誓ってはいけません。あなたがたの「はい」は「はい」、「いいえ」は「いいえ」でありなさい。そうすれば、さばきにあうことはありません。'),
('JPN', '雅各书', 59, 5, 13, 'あなたがたの中に苦しんでいる人がいれば、その人は祈りなさい。喜んでいる人がいれば、その人は賛美しなさい。'),
('JPN', '雅各书', 59, 5, 14, 'あなたがたのうちに病気の人がいれば、教会の長老たちを招き、主の御名によって、オリーブ油を塗って祈ってもらいなさい。'),
('JPN', '雅各书', 59, 5, 15, '信仰による祈りは、病んでいる人を救います。主はその人を立ち上がらせてくださいます。もしその人が罪を犯していたなら、その罪は赦されます。'),
('JPN', '雅各书', 59, 5, 16, 'ですから、あなたがたは癒やされるために、互いに罪を言い表し、互いのために祈りなさい。正しい人の祈りは、働くと大きな力があります。'),
('JPN', '雅各书', 59, 5, 17, 'エリヤは私たちと同じ人間でしたが、雨が降らないように熱心に祈ると、三年六か月の間、雨は地に降りませんでした。'),
('JPN', '雅各书', 59, 5, 18, 'それから彼は再び祈りました。すると、天は雨を降らせ、地はその実を実らせました。'),
('JPN', '雅各书', 59, 5, 19, '私の兄弟たち。あなたがたの中に真理から迷い出た者がいて、だれかがその人を連れ戻すなら、'),
('JPN', '雅各书', 59, 5, 20, '罪人を迷いの道から連れ戻す人は、罪人のたましいを死から救い出し、また多くの罪をおおうことになるのだと、知るべきです。'),
('JPN', '彼得前书', 60, 1, 1, 'イエス・キリストの使徒ペテロから、ポントス、ガラテヤ、カパドキア、アジア、ビティニアに散って寄留している選ばれた人たち、すなわち、'),
('JPN', '彼得前书', 60, 1, 2, '父なる神の予知のままに、御霊による聖別によって、イエス・キリストに従うように、またその血の注ぎかけを受けるように選ばれた人たちへ。恵みと平安が、あなたがたにますます豊かに与えられますように。'),
('JPN', '彼得前书', 60, 1, 3, '私たちの主イエス・キリストの父である神がほめたたえられますように。神は、ご自分の大きなあわれみのゆえに、イエス・キリストが死者の中からよみがえられたことによって、私たちを新しく生まれさせ、生ける望みを持たせてくださいました。'),
('JPN', '彼得前书', 60, 1, 4, 'また、朽ちることも、汚れることも、消えて行くこともない資産を受け継ぐようにしてくださいました。これらは、あなたがたのために天に蓄えられています。'),
('JPN', '彼得前书', 60, 1, 5, 'あなたがたは、信仰により、神の御力によって守られており、終わりの時に現されるように用意されている救いをいただくのです。'),
('JPN', '彼得前书', 60, 1, 6, 'そういうわけで、あなたがたは大いに喜んでいます。今しばらくの間、様々な試練の中で悲しまなければならないのですが、'),
('JPN', '彼得前书', 60, 1, 7, '試練で試されたあなたがたの信仰は、火で精錬されてもなお朽ちていく金よりも高価であり、イエス・キリストが現れるとき、称賛と栄光と誉れをもたらします。'),
('JPN', '彼得前书', 60, 1, 8, 'あなたがたはイエス・キリストを見たことはないけれども愛しており、今見てはいないけれども信じており、ことばに尽くせない、栄えに満ちた喜びに躍っています。'),
('JPN', '彼得前书', 60, 1, 9, 'あなたがたが、信仰の結果であるたましいの救いを得ているからです。'),
('JPN', '彼得前书', 60, 1, 10, 'この救いについては、あなたがたに対する恵みを預言した預言者たちも、熱心に尋ね求め、細かく調べました。'),
('JPN', '彼得前书', 60, 1, 11, '彼らは、自分たちのうちにおられるキリストの御霊が、キリストの苦難とそれに続く栄光を前もって証ししたときに、だれを、そしてどの時を指して言われたのかを調べたのです。'),
('JPN', '彼得前书', 60, 1, 12, '彼らは、自分たちのためではなく、あなたがたのために奉仕しているのだという啓示を受けました。そして彼らが調べたことが今や、天から遣わされた聖霊により福音を語った人々を通して、あなたがたに告げ知らされたのです。御使いたちもそれをはっきり見たいと願っています。'),
('JPN', '彼得前书', 60, 1, 13, 'ですから、あなたがたは心を引き締め、身を慎み、イエス・キリストが現れるときに与えられる恵みを、ひたすら待ち望みなさい。'),
('JPN', '彼得前书', 60, 1, 14, '従順な子どもとなり、以前、無知であったときの欲望に従わず、'),
('JPN', '彼得前书', 60, 1, 15, 'むしろ、あなたがたを召された聖なる方に倣い、あなたがた自身、生活のすべてにおいて聖なる者となりなさい。'),
('JPN', '彼得前书', 60, 1, 16, '「あなたがたは聖なる者でなければならない。わたしが聖だからである」と書いてあるからです。'),
('JPN', '彼得前书', 60, 1, 17, 'また、人をそれぞれのわざにしたがって公平にさばかれる方を父と呼んでいるのなら、この世に寄留している時を、恐れつつ過ごしなさい。'),
('JPN', '彼得前书', 60, 1, 18, 'ご存じのように、あなたがたが先祖伝来のむなしい生き方から贖い出されたのは、銀や金のような朽ちる物にはよらず、'),
('JPN', '彼得前书', 60, 1, 19, '傷もなく汚れもない子羊のようなキリストの、尊い血によったのです。'),
('JPN', '彼得前书', 60, 1, 20, 'キリストは、世界の基が据えられる前から知られていましたが、この終わりの時に、あなたがたのために現れてくださいました。'),
('JPN', '彼得前书', 60, 1, 21, 'あなたがたは、キリストを死者の中からよみがえらせて栄光を与えられた神を、キリストによって信じる者です。ですから、あなたがたの信仰と希望は神にかかっています。'),
('JPN', '彼得前书', 60, 1, 22, 'あなたがたは真理に従うことによって、たましいを清め、偽りのない兄弟愛を抱くようになったのですから、きよい心で互いに熱く愛し合いなさい。'),
('JPN', '彼得前书', 60, 1, 23, 'あなたがたが新しく生まれたのは、朽ちる種からではなく朽ちない種からであり、生きた、いつまでも残る、神のことばによるのです。'),
('JPN', '彼得前书', 60, 1, 24, '「人はみな草のよう。その栄えはみな草の花のようだ。草はしおれ、花は散る。'),
('JPN', '彼得前书', 60, 1, 25, 'しかし、主のことばは永遠に立つ」とあるからです。これが、あなたがたに福音として宣べ伝えられたことばです。'),
('JPN', '彼得前书', 60, 2, 1, 'ですからあなたがたは、すべての悪意、すべての偽り、偽善やねたみ、すべての悪口を捨てて、'),
('JPN', '彼得前书', 60, 2, 2, '生まれたばかりの乳飲み子のように、純粋な、霊の乳を慕い求めなさい。それによって成長し、救いを得るためです。'),
('JPN', '彼得前书', 60, 2, 3, 'あなたがたは、主がいつくしみ深い方であることを、確かに味わいました。'),
('JPN', '彼得前书', 60, 2, 4, '主のもとに来なさい。主は、人には捨てられたが神には選ばれた、尊い生ける石です。'),
('JPN', '彼得前书', 60, 2, 5, 'あなたがた自身も生ける石として霊の家に築き上げられ、神に喜ばれる霊のいけにえをイエス・キリストを通して献げる、聖なる祭司となります。'),
('JPN', '彼得前书', 60, 2, 6, '聖書にこう書いてあるからです。「見よ、わたしはシオンに、選ばれた石、尊い要石を据える。この方に信頼する者は決して失望させられることがない。」'),
('JPN', '彼得前书', 60, 2, 7, 'したがってこの石は、信じているあなたがたには尊いものですが、信じていない人々にとっては、「家を建てる者たちが捨てた石、それが要の石となった」のであり、'),
('JPN', '彼得前书', 60, 2, 8, 'それは「つまずきの石、妨げの岩」なのです。彼らがつまずくのは、みことばに従わないからであり、また、そうなるように定められていたのです。'),
('JPN', '彼得前书', 60, 2, 9, 'しかし、あなたがたは選ばれた種族、王である祭司、聖なる国民、神のものとされた民です。それは、あなたがたを闇の中から、ご自分の驚くべき光の中に召してくださった方の栄誉を、あなたがたが告げ知らせるためです。'),
('JPN', '彼得前书', 60, 2, 10, 'あなたがたは以前は神の民ではなかったのに、今は神の民であり、あわれみを受けたことがなかったのに、今はあわれみを受けています。'),
('JPN', '彼得前书', 60, 2, 11, '愛する者たち、私は勧めます。あなたがたは旅人、寄留者なのですから、たましいに戦いを挑む肉の欲を避けなさい。'),
('JPN', '彼得前书', 60, 2, 12, '異邦人の中にあって立派にふるまいなさい。そうすれば、彼らがあなたがたを悪人呼ばわりしていても、あなたがたの立派な行いを目にして、神の訪れの日に神をあがめるようになります。'),
('JPN', '彼得前书', 60, 2, 13, '人が立てたすべての制度に、主のゆえに従いなさい。それが主権者である王であっても、'),
('JPN', '彼得前书', 60, 2, 14, 'あるいは、悪を行う者を罰して善を行う者をほめるために、王から遣わされた総督であっても、従いなさい。'),
('JPN', '彼得前书', 60, 2, 15, '善を行って、愚かな者たちの無知な発言を封じることは、神のみこころだからです。'),
('JPN', '彼得前书', 60, 2, 16, '自由な者として、しかもその自由を悪の言い訳にせず、神のしもべとして従いなさい。'),
('JPN', '彼得前书', 60, 2, 17, 'すべての人を敬い、兄弟たちを愛し、神を恐れ、王を敬いなさい。'),
('JPN', '彼得前书', 60, 2, 18, 'しもべたちよ、敬意を込めて主人に従いなさい。善良で優しい主人だけでなく、意地悪な主人にも従いなさい。'),
('JPN', '彼得前书', 60, 2, 19, 'もしだれかが不当な苦しみを受けながら、神の御前における良心のゆえに悲しみに耐えるなら、それは神に喜ばれることです。'),
('JPN', '彼得前书', 60, 2, 20, '罪を犯して打ちたたかれ、それを耐え忍んでも、何の誉れになるでしょう。しかし、善を行って苦しみを受け、それを耐え忍ぶなら、それは神の御前に喜ばれることです。'),
('JPN', '彼得前书', 60, 2, 21, 'このためにこそ、あなたがたは召されました。キリストも、あなたがたのために苦しみを受け、その足跡に従うようにと、あなたがたに模範を残された。'),
('JPN', '彼得前书', 60, 2, 22, 'キリストは罪を犯したことがなく、その口には欺きもなかった。'),
('JPN', '彼得前书', 60, 2, 23, 'ののしられても、ののしり返さず、苦しめられても、脅すことをせず、正しくさばかれる方にお任せになった。'),
('JPN', '彼得前书', 60, 2, 24, 'キリストは自ら十字架の上で、私たちの罪をその身に負われた。それは、私たちが罪を離れ、義のために生きるため。その打ち傷のゆえに、あなたがたは癒やされた。'),
('JPN', '彼得前书', 60, 2, 25, 'あなたがたは羊のようにさまよっていた。しかし今や、自分のたましいの牧者であり監督者である方のもとに帰った。'),
('JPN', '彼得前书', 60, 3, 1, '同じように、妻たちよ、自分の夫に従いなさい。たとえ、みことばに従わない夫であっても、妻の無言のふるまいによって神のものとされるためです。'),
('JPN', '彼得前书', 60, 3, 2, '夫は、あなたがたの、神を恐れる純粋な生き方を目にするのです。'),
('JPN', '彼得前书', 60, 3, 3, 'あなたがたの飾りは、髪を編んだり金の飾りを付けたり、服を着飾ったりする外面的なものであってはいけません。'),
('JPN', '彼得前书', 60, 3, 4, 'むしろ、柔和で穏やかな霊という朽ちることのないものを持つ、心の中の隠れた人を飾りとしなさい。それこそ、神の御前で価値あるものです。'),
('JPN', '彼得前书', 60, 3, 5, 'かつて、神に望みを置いた敬虔な女の人たちも、そのように自分を飾って、夫に従ったのです。'),
('JPN', '彼得前书', 60, 3, 6, 'たとえば、サラはアブラハムを主と呼んで従いました。どんなことをも恐れないで善を行うなら、あなたがたはサラの子です。'),
('JPN', '彼得前书', 60, 3, 7, '同じように、夫たちよ、妻が自分より弱い器であることを理解して妻とともに暮らしなさい。また、いのちの恵みをともに受け継ぐ者として尊敬しなさい。そうすれば、あなたがたの祈りは妨げられません。'),
('JPN', '彼得前书', 60, 3, 8, '最後に言います。みな、一つ思いになり、同情し合い、兄弟愛を示し、心の優しい人となり、謙虚でありなさい。'),
('JPN', '彼得前书', 60, 3, 9, '悪に対して悪を返さず、侮辱に対して侮辱を返さず、逆に祝福しなさい。あなたがたは祝福を受け継ぐために召されたのです。'),
('JPN', '彼得前书', 60, 3, 10, '「いのちを愛し、幸せな日々を見ようと願う者は、舌に悪口を言わせず、唇に欺きを語らせるな。'),
('JPN', '彼得前书', 60, 3, 11, '悪を離れて善を行い、平和を求め、それを追え。'),
('JPN', '彼得前书', 60, 3, 12, '主の目は正しい人たちの上にあり、主の耳は彼らの叫びに傾けられる。しかし主の顔は、悪をなす者どもに敵対する。」'),
('JPN', '彼得前书', 60, 3, 13, 'もしあなたがたが良いことに対して熱心であるなら、だれがあなたがたに害を加えるでしょう。'),
('JPN', '彼得前书', 60, 3, 14, 'たとえ義のために苦しむことがあっても、あなたがたは幸いです。人々の脅かしを恐れたり、おびえたりしてはいけません。'),
('JPN', '彼得前书', 60, 3, 15, 'むしろ、心の中でキリストを主とし、聖なる方としなさい。あなたがたのうちにある希望について説明を求める人には、だれにでも、いつでも弁明できる用意をしていなさい。'),
('JPN', '彼得前书', 60, 3, 16, 'ただし、柔和な心で、恐れつつ、健全な良心をもって弁明しなさい。そうすれば、キリストにあるあなたがたの善良な生き方をののしっている人たちが、あなたがたを悪く言ったことを恥じるでしょう。'),
('JPN', '彼得前书', 60, 3, 17, '神のみこころであるなら、悪を行って苦しみを受けるより、善を行って苦しみを受けるほうがよいのです。'),
('JPN', '彼得前书', 60, 3, 18, 'キリストも一度、罪のために苦しみを受けられました。正しい方が正しくない者たちの身代わりになられたのです。それは、肉においては死に渡され、霊においては生かされて、あなたがたを神に導くためでした。'),
('JPN', '彼得前书', 60, 3, 19, 'その霊においてキリストは、捕らわれている霊たちのところに行って宣言されました。'),
('JPN', '彼得前书', 60, 3, 20, 'かつてノアの時代に、箱舟が造られていた間、神が忍耐して待っておられたときに従わなかった霊たちにです。その箱舟に入ったわずかの人たち、すなわち八人は、水を通って救われました。'),
('JPN', '彼得前书', 60, 3, 21, 'この水はまた、今あなたがたをイエス・キリストの復活を通して救うバプテスマの型なのです。バプテスマは肉の汚れを取り除くものではありません。それはむしろ、健全な良心が神に対して行う誓約です。'),
('JPN', '彼得前书', 60, 3, 22, 'イエス・キリストは天に上り、神の右におられます。御使いたちも、もろもろの権威と権力も、この方に服従しているのです。'),
('JPN', '彼得前书', 60, 4, 1, 'キリストは肉において苦しみを受けられたのですから、あなたがたも同じ心構えで自分自身を武装しなさい。肉において苦しみを受けた人は、罪との関わりを断っているのです。'),
('JPN', '彼得前书', 60, 4, 2, 'それは、あなたがたが地上での残された時を、もはや人間の欲望にではなく、神のみこころに生きるようになるためです。'),
('JPN', '彼得前书', 60, 4, 3, 'あなたがたは異邦人たちがしたいと思っていることを行い、好色、欲望、泥酔、遊興、宴会騒ぎ、律法に反する偶像礼拝などにふけりましたが、それは過ぎ去った時で十分です。'),
('JPN', '彼得前书', 60, 4, 4, '異邦人たちは、あなたがたが一緒に、度を越した同じ放蕩に走らないので不審に思い、中傷しますが、'),
('JPN', '彼得前书', 60, 4, 5, '彼らは、生きている者と死んだ者をさばこうとしておられる方に対して、申し開きをすることになります。'),
('JPN', '彼得前书', 60, 4, 6, 'このさばきがあるために、死んだ人々にも生前、福音が宣べ伝えられていたのです。彼らが肉においては人間としてさばきを受けても、霊においては神によって生きるためでした。'),
('JPN', '彼得前书', 60, 4, 7, '万物の終わりが近づきました。ですから、祈りのために、心を整え身を慎みなさい。'),
('JPN', '彼得前书', 60, 4, 8, '何よりもまず、互いに熱心に愛し合いなさい。愛は多くの罪をおおうからです。'),
('JPN', '彼得前书', 60, 4, 9, '不平を言わないで、互いにもてなし合いなさい。'),
('JPN', '彼得前书', 60, 4, 10, 'それぞれが賜物を受けているのですから、神の様々な恵みの良い管理者として、その賜物を用いて互いに仕え合いなさい。'),
('JPN', '彼得前书', 60, 4, 11, '語るのであれば、神のことばにふさわしく語り、奉仕するのであれば、神が備えてくださる力によって、ふさわしく奉仕しなさい。すべてにおいて、イエス・キリストを通して神があがめられるためです。この方に栄光と力が世々限りなくありますように。アーメン。'),
('JPN', '彼得前书', 60, 4, 12, '愛する者たち。あなたがたを試みるためにあなたがたの間で燃えさかる試練を、何か思いがけないことが起こったかのように、不審に思ってはいけません。'),
('JPN', '彼得前书', 60, 4, 13, 'むしろ、キリストの苦難にあずかればあずかるほど、いっそう喜びなさい。キリストの栄光が現れるときにも、歓喜にあふれて喜ぶためです。'),
('JPN', '彼得前书', 60, 4, 14, 'もしキリストの名のためにののしられるなら、あなたがたは幸いです。栄光の御霊、すなわち神の御霊が、あなたがたの上にとどまってくださるからです。'),
('JPN', '彼得前书', 60, 4, 15, 'あなたがたのうちのだれも、人殺し、盗人、危害を加える者、他人のことに干渉する者として、苦しみにあうことがないようにしなさい。'),
('JPN', '彼得前书', 60, 4, 16, 'しかし、キリスト者として苦しみを受けるのなら、恥じることはありません。かえって、このことのゆえに神をあがめなさい。'),
('JPN', '彼得前书', 60, 4, 17, 'さばきが神の家から始まる時が来ているからです。それが、まず私たちから始まるとすれば、神の福音に従わない者たちの結末はどうなるのでしょうか。'),
('JPN', '彼得前书', 60, 4, 18, '「正しい者がかろうじて救われるのなら、不敬虔な者や罪人はどうなるのか。」'),
('JPN', '彼得前书', 60, 4, 19, 'ですから、神のみこころにより苦しみにあっている人たちは、善を行いつつ、真実な創造者に自分のたましいをゆだねなさい。'),
('JPN', '彼得前书', 60, 5, 1, '私は、あなたがたのうちの長老たちに、同じ長老の一人として、キリストの苦難の証人、やがて現される栄光にあずかる者として勧めます。'),
('JPN', '彼得前书', 60, 5, 2, 'あなたがたのうちにいる、神の羊の群れを牧しなさい。強制されてではなく、神に従って自発的に、また卑しい利得を求めてではなく、心を込めて世話をしなさい。'),
('JPN', '彼得前书', 60, 5, 3, '割り当てられている人たちを支配するのではなく、むしろ群れの模範となりなさい。'),
('JPN', '彼得前书', 60, 5, 4, 'そうすれば、大牧者が現れるときに、あなたがたは、しぼむことのない栄光の冠をいただくことになります。'),
('JPN', '彼得前书', 60, 5, 5, '同じように、若い人たちよ、長老たちに従いなさい。みな互いに謙遜を身に着けなさい。「神は高ぶる者には敵対し、へりくだった者には恵みを与えられる」のです。'),
('JPN', '彼得前书', 60, 5, 6, 'ですから、あなたがたは神の力強い御手の下にへりくだりなさい。神は、ちょうど良い時に、あなたがたを高く上げてくださいます。'),
('JPN', '彼得前书', 60, 5, 7, 'あなたがたの思い煩いを、いっさい神にゆだねなさい。神があなたがたのことを心配してくださるからです。'),
('JPN', '彼得前书', 60, 5, 8, '身を慎み、目を覚ましていなさい。あなたがたの敵である悪魔が、吼えたける獅子のように、だれかを食い尽くそうと探し回っています。'),
('JPN', '彼得前书', 60, 5, 9, '堅く信仰に立って、この悪魔に対抗しなさい。ご存じのように、世界中で、あなたがたの兄弟たちが同じ苦難を通ってきているのです。'),
('JPN', '彼得前书', 60, 5, 10, 'あらゆる恵みに満ちた神、すなわち、あなたがたをキリストにあって永遠の栄光の中に招き入れてくださった神ご自身が、あなたがたをしばらくの苦しみの後で回復させ、堅く立たせ、強くし、不動の者としてくださいます。'),
('JPN', '彼得前书', 60, 5, 11, 'どうか、神のご支配が世々限りなくありますように。アーメン。'),
('JPN', '彼得前书', 60, 5, 12, '忠実な兄弟として私が信頼しているシルワノによって、私は簡潔に書き送り、勧めをし、これが神のまことの恵みであることを証ししました。この恵みの中にしっかりと立っていなさい。'),
('JPN', '彼得前书', 60, 5, 13, 'あなたがたとともに選ばれたバビロンの教会と、私の子マルコが、あなたがたによろしくと言っています。'),
('JPN', '彼得前书', 60, 5, 14, '愛の口づけをもって互いにあいさつを交わしなさい。キリストにあるあなたがたすべての者に、平安がありますように。'),
('JPN', '彼得后书', 61, 1, 1, 'イエス・キリストのしもべであり使徒であるシモン・ペテロから、私たちの神であり救い主であるイエス・キリストの義によって、私たちと同じ尊い信仰を受けた方々へ。'),
('JPN', '彼得后书', 61, 1, 2, '神と、私たちの主イエスを知ることによって、恵みと平安が、あなたがたにますます豊かに与えられますように。'),
('JPN', '彼得后书', 61, 1, 3, '私たちをご自身の栄光と栄誉によって召してくださった神を、私たちが知ったことにより、主イエスの、神としての御力は、いのちと敬虔をもたらすすべてのものを、私たちに与えました。'),
('JPN', '彼得后书', 61, 1, 4, 'その栄光と栄誉を通して、尊く大いなる約束が私たちに与えられています。それは、その約束によってあなたがたが、欲望がもたらすこの世の腐敗を免れ、神のご性質にあずかる者となるためです。'),
('JPN', '彼得后书', 61, 1, 5, 'だからこそ、あなたがたはあらゆる熱意を傾けて、信仰には徳を、徳には知識を、'),
('JPN', '彼得后书', 61, 1, 6, '知識には自制を、自制には忍耐を、忍耐には敬虔を、'),
('JPN', '彼得后书', 61, 1, 7, '敬虔には兄弟愛を、兄弟愛には愛を加えなさい。'),
('JPN', '彼得后书', 61, 1, 8, 'これらがあなたがたに備わり、ますます豊かになるなら、私たちの主イエス・キリストを知る点で、あなたがたが役に立たない者とか実を結ばない者になることはありません。'),
('JPN', '彼得后书', 61, 1, 9, 'これらを備えていない人は盲目です。自分の以前の罪がきよめられたことを忘れてしまって、近視眼的になっているのです。'),
('JPN', '彼得后书', 61, 1, 10, 'ですから、兄弟たち。自分たちの召しと選びを確かなものとするように、いっそう励みなさい。これらのことを行っているなら、決してつまずくことはありません。'),
('JPN', '彼得后书', 61, 1, 11, 'このようにして、私たちの主であり救い主であるイエス・キリストの永遠の御国に入る恵みを、豊かに与えられるのです。'),
('JPN', '彼得后书', 61, 1, 12, 'ですから、あなたがたがこれらのことをすでに知り、与えられた真理に堅く立っているとはいえ、私はあなたがたに、それをいつも思い起こさせるつもりです。'),
('JPN', '彼得后书', 61, 1, 13, 'それを思い起こさせて、あなたがたを奮い立たせることを、私は地上の幕屋にいるかぎり、なすべきだと思っています。'),
('JPN', '彼得后书', 61, 1, 14, '私たちの主イエス・キリストが示してくださったように、私はこの幕屋を間もなく脱ぎ捨てることを知っています。'),
('JPN', '彼得后书', 61, 1, 15, 'ですから、ぜひとも、私が去った後いつでも、あなたがたがこれらのことを思い起こせるようにしておきたいのです。'),
('JPN', '彼得后书', 61, 1, 16, '私たちはあなたがたに、私たちの主イエス・キリストの力と来臨を知らせましたが、それは、巧みな作り話によったのではありません。私たちは、キリストの威光の目撃者として伝えたのです。'),
('JPN', '彼得后书', 61, 1, 17, 'この方が父なる神から誉れと栄光を受けられたとき、厳かな栄光の中から、このような御声がありました。「これはわたしの愛する子。わたしはこれを喜ぶ。」'),
('JPN', '彼得后书', 61, 1, 18, '私たちは聖なる山で主とともにいたので、天からかかったこの御声を自分で聞きました。'),
('JPN', '彼得后书', 61, 1, 19, 'また私たちは、さらに確かな預言のみことばを持っています。夜が明けて、明けの明星があなたがたの心に昇るまでは、暗い所を照らすともしびとして、それに目を留めているとよいのです。'),
('JPN', '彼得后书', 61, 1, 20, 'ただし、聖書のどんな預言も勝手に解釈するものではないことを、まず心得ておきなさい。'),
('JPN', '彼得后书', 61, 1, 21, '預言は、決して人間の意志によってもたらされたものではなく、聖霊に動かされた人たちが神から受けて語ったものです。'),
('JPN', '彼得后书', 61, 2, 1, 'しかし、御民の中には偽預言者も出ました。同じように、あなたがたの中にも偽教師が現れます。彼らは、滅びをもたらす異端をひそかに持ち込むようになります。自分たちを買い取ってくださった主さえも否定し、自分たちの身に速やかな滅びを招くのです。'),
('JPN', '彼得后书', 61, 2, 2, 'また、多くの者が彼らの放縦に倣い、彼らのせいで真理の道が悪く言われることになります。'),
('JPN', '彼得后书', 61, 2, 3, '彼らは貪欲で、うまくこしらえた話であなたがたを食い物にします。彼らに対するさばきは昔から怠りなく行われていて、彼らの滅びが遅くなることはありません。'),
('JPN', '彼得后书', 61, 2, 4, '神は、罪を犯した御使いたちを放置せず、地獄に投げ入れ、暗闇の縄目につないで、さばきの日まで閉じ込められました。'),
('JPN', '彼得后书', 61, 2, 5, 'また、かつての世界を放置せず、不敬虔な者たちの世界に洪水をもたらし、義を宣べ伝えたノアたち八人を保護されました。'),
('JPN', '彼得后书', 61, 2, 6, 'また、ソドムとゴモラの町を破滅に定めて灰にし、不敬虔な者たちに起こることの実例とされました。'),
('JPN', '彼得后书', 61, 2, 7, 'そして、不道徳な者たちの放縦なふるまいによって悩まされていた正しい人、ロトを救い出されました。'),
('JPN', '彼得后书', 61, 2, 8, 'この正しい人は彼らの間に住んでいましたが、不法な行いを見聞きして、日々その正しい心を痛めていたのです。'),
('JPN', '彼得后书', 61, 2, 9, '主はこのようにされたのですから、敬虔な者たちを誘惑から救い出し、正しくない者たちを処罰し、さばきの日まで閉じ込めておくことを、心得ておられるのです。'),
('JPN', '彼得后书', 61, 2, 10, '特に、汚れた欲望のまま肉に従って歩み、権威を侮る者たちに対して、主はそうされます。この者たちは厚かましく、わがままで、栄光ある人たちをののしって恐れません。'),
('JPN', '彼得后书', 61, 2, 11, '御使いたちは勢いも力も彼らにまさっているのに、主の御前で彼らをそしって訴えたりしません。'),
('JPN', '彼得后书', 61, 2, 12, 'この者たちは、本能に支配されていて、捕らえられ殺されるために生まれてきた、理性のない動物のようです。自分が知りもしないことを悪く言い、動物が滅びるように滅ぼされることになります。'),
('JPN', '彼得后书', 61, 2, 13, '彼らは不義の報酬として損害を受けるのです。彼らは昼間から飲み騒ぐことを楽しみとしています。彼らはしみや傷であり、あなたがたと一緒に宴席に連なるとき、自分たちのだましごとにふけるのです。'),
('JPN', '彼得后书', 61, 2, 14, 'その目は姦淫に満ち、罪に飽くことがなく、心が定まらない人たちを誘惑し、心は貪欲で鍛えられています。彼らはのろいの子です。'),
('JPN', '彼得后书', 61, 2, 15, '彼らは正しい道を捨てて、さまよっています。ベオルの子バラムの道に従ったのです。バラムは不義の報酬を愛しましたが、'),
('JPN', '彼得后书', 61, 2, 16, '自分の不法な行いをとがめられました。口のきけないろばが人間の声で話して、この預言者の正気を失ったふるまいをやめさせたのです。'),
('JPN', '彼得后书', 61, 2, 17, 'この者たちは水がない泉、突風で吹き払われる霧です。彼らには深い闇が用意されています。'),
('JPN', '彼得后书', 61, 2, 18, '彼らは、むなしいことを大げさに語り、迷いの中に生きている人々の間から現に逃げ出しつつある人たちを、肉欲と好色によって誘惑しています。'),
('JPN', '彼得后书', 61, 2, 19, 'その人たちに自由を約束しながら、自分自身は滅びの奴隷となっています。人は自分を打ち負かした人の奴隷となるのです。'),
('JPN', '彼得后书', 61, 2, 20, '主であり、救い主であるイエス・キリストを知ることによって世の汚れから逃れたのに、再びそれに巻き込まれて打ち負かされるなら、そのような人たちの終わりの状態は、初めの状態よりももっと悪くなります。'),
('JPN', '彼得后书', 61, 2, 21, '義の道を知っていながら、自分たちに伝えられた聖なる戒めから再び離れるよりは、義の道を知らなかったほうがよかったのです。'),
('JPN', '彼得后书', 61, 2, 22, '「犬は自分が吐いた物に戻る」、「豚は身を洗って、また泥の中を転がる」という、ことわざどおりのことが、彼らに起こっているのです。'),
('JPN', '彼得后书', 61, 3, 1, '愛する者たち、私はすでに二通目となる手紙を、あなたがたに書いています。これらの手紙により、私はあなたがたの記憶を呼び覚まして、純真な心を奮い立たせたいのです。'),
('JPN', '彼得后书', 61, 3, 2, 'それは、聖なる預言者たちにより前もって語られたみことばと、あなたがたの使徒たちにより伝えられた、主であり救い主である方の命令を思い出させるためです。'),
('JPN', '彼得后书', 61, 3, 3, 'まず第一に、心得ておきなさい。終わりの時に、嘲る者たちが現れて嘲り、自分たちの欲望に従いながら、'),
('JPN', '彼得后书', 61, 3, 4, 'こう言います。「彼の来臨の約束はどこにあるのか。父たちが眠りについた後も、すべてが創造のはじめからのままではないか。」'),
('JPN', '彼得后书', 61, 3, 5, 'こう主張する彼らは、次のことを見落としています。天は大昔からあり、地は神のことばによって、水から出て、水を通して成ったのであり、'),
('JPN', '彼得后书', 61, 3, 6, 'そのみことばのゆえに、当時の世界は水におおわれて滅びました。'),
('JPN', '彼得后书', 61, 3, 7, 'しかし、今ある天と地は、同じみことばによって、火で焼かれるために取っておかれ、不敬虔な者たちのさばきと滅びの日まで保たれているのです。'),
('JPN', '彼得后书', 61, 3, 8, 'しかし、愛する人たち、あなたがたはこの一つのことを見落としてはいけません。主の御前では、一日は千年のようであり、千年は一日のようです。'),
('JPN', '彼得后书', 61, 3, 9, '主は、ある人たちが遅れていると思っているように、約束したことを遅らせているのではなく、あなたがたに対して忍耐しておられるのです。だれも滅びることがなく、すべての人が悔い改めに進むことを望んでおられるのです。'),
('JPN', '彼得后书', 61, 3, 10, 'しかし、主の日は盗人のようにやって来ます。その日、天は大きな響きを立てて消え去り、天の万象は焼けて崩れ去り、地と地にある働きはなくなってしまいます。'),
('JPN', '彼得后书', 61, 3, 11, 'このように、これらすべてのものが崩れ去るのだとすれば、あなたがたは、どれほど聖なる敬虔な生き方をしなければならないことでしょう。'),
('JPN', '彼得后书', 61, 3, 12, 'そのようにして、神の日が来るのを待ち望み、到来を早めなければなりません。その日の到来によって、天は燃え崩れ、天の万象は焼け溶けてしまいます。'),
('JPN', '彼得后书', 61, 3, 13, 'しかし私たちは、神の約束にしたがって、義の宿る新しい天と新しい地を待ち望んでいます。'),
('JPN', '彼得后书', 61, 3, 14, 'ですから、愛する者たち。これらのことを待ち望んでいるのなら、しみも傷もない者として平安のうちに神に見出していただけるように努力しなさい。'),
('JPN', '彼得后书', 61, 3, 15, 'また、私たちの主の忍耐は救いであると考えなさい。愛する、私たちの兄弟パウロも、自分に与えられた知恵にしたがって、あなたがたに書き送ったとおりです。'),
('JPN', '彼得后书', 61, 3, 16, 'その手紙でパウロは、ほかのすべての手紙でもしているように、このことについて語っています。その中には理解しにくいところがあります。無知な、心の定まらない人たちは、聖書の他の箇所と同様、それらを曲解して、自分自身に滅びを招きます。'),
('JPN', '彼得后书', 61, 3, 17, 'ですから、愛する者たち。あなたがたは前もって分かっているのですから、不道徳な者たちの惑わしに誘い込まれて、自分自身の堅実さを失わないよう、よく気をつけなさい。'),
('JPN', '彼得后书', 61, 3, 18, '私たちの主であり、救い主であるイエス・キリストの恵みと知識において成長しなさい。イエス・キリストに栄光が、今も永遠の日に至るまでもありますように。'),
('JPN', '约翰一书', 62, 1, 1, '初めからあったもの、私たちが聞いたもの、自分の目で見たもの、じっと見つめ、自分の手でさわったもの、すなわち、いのちのことばについて。'),
('JPN', '约翰一书', 62, 1, 2, 'このいのちが現れました。御父とともにあり、私たちに現れたこの永遠のいのちを、私たちは見たので証しして、あなたがたに伝えます。'),
('JPN', '约翰一书', 62, 1, 3, '私たちが見たこと、聞いたことを、あなたがたにも伝えます。あなたがたも私たちと交わりを持つようになるためです。私たちの交わりとは、御父また御子イエス・キリストとの交わりです。'),
('JPN', '约翰一书', 62, 1, 4, 'これらのことを書き送るのは、私たちの喜びが満ちあふれるためです。'),
('JPN', '约翰一书', 62, 1, 5, '私たちがキリストから聞き、あなたがたに伝える使信は、神は光であり、神には闇が全くないということです。'),
('JPN', '约翰一书', 62, 1, 6, 'もし私たちが、神と交わりがあると言いながら、闇の中を歩んでいるなら、私たちは偽りを言っているのであり、真理を行っていません。'),
('JPN', '约翰一书', 62, 1, 7, 'もし私たちが、神が光の中におられるように、光の中を歩んでいるなら、互いに交わりを持ち、御子イエスの血がすべての罪から私たちをきよめてくださいます。'),
('JPN', '约翰一书', 62, 1, 8, 'もし自分には罪がないと言うなら、私たちは自分自身を欺いており、私たちのうちに真理はありません。'),
('JPN', '约翰一书', 62, 1, 9, 'もし私たちが自分の罪を告白するなら、神は真実で正しい方ですから、その罪を赦し、私たちをすべての不義からきよめてくださいます。'),
('JPN', '约翰一书', 62, 1, 10, 'もし罪を犯したことがないと言うなら、私たちは神を偽り者とすることになり、私たちのうちに神のことばはありません。'),
('JPN', '约翰一书', 62, 2, 1, '私の子どもたち。私がこれらのことを書き送るのは、あなたがたが罪を犯さないようになるためです。しかし、もしだれかが罪を犯したなら、私たちには、御父の前でとりなしてくださる方、義なるイエス・キリストがおられます。'),
('JPN', '约翰一书', 62, 2, 2, 'この方こそ、私たちの罪のための、いや、私たちの罪だけでなく、世全体の罪のための宥めのささげ物です。'),
('JPN', '约翰一书', 62, 2, 3, 'もし私たちが神の命令を守っているなら、それによって、自分が神を知っていることが分かります。'),
('JPN', '约翰一书', 62, 2, 4, '神を知っていると言いながら、その命令を守っていない人は、偽り者であり、その人のうちに真理はありません。'),
('JPN', '约翰一书', 62, 2, 5, 'しかし、だれでも神のことばを守っているなら、その人のうちには神の愛が確かに全うされているのです。それによって、自分が神のうちにいることが分かります。'),
('JPN', '约翰一书', 62, 2, 6, '神のうちにとどまっていると言う人は、自分もイエスが歩まれたように歩まなければなりません。'),
('JPN', '约翰一书', 62, 2, 7, '愛する者たち。私があなたがたに書いているのは、新しい命令ではなく、あなたがたが初めから持っていた古い命令です。その古い命令とは、あなたがたがすでに聞いているみことばです。'),
('JPN', '约翰一书', 62, 2, 8, '私は、それを新しい命令として、もう一度あなたがたに書いているのです。それはイエスにおいて真理であり、あなたがたにおいても真理です。闇が消え去り、まことの光がすでに輝いているからです。'),
('JPN', '约翰一书', 62, 2, 9, '光の中にいると言いながら自分の兄弟を憎んでいる人は、今でもまだ闇の中にいるのです。'),
('JPN', '约翰一书', 62, 2, 10, '自分の兄弟を愛している人は光の中にとどまり、その人のうちにはつまずきがありません。'),
('JPN', '约翰一书', 62, 2, 11, 'しかし、自分の兄弟を憎んでいる人は闇の中にいて、闇の中を歩み、自分がどこへ行くのかが分かりません。闇が目を見えなくしたからです。'),
('JPN', '约翰一书', 62, 2, 12, '子どもたち。私があなたがたに書いているのは、イエスの名によって、あなたがたの罪が赦されたからです。'),
('JPN', '约翰一书', 62, 2, 13, '父たち。私があなたがたに書いているのは、初めからおられる方を、あなたがたが知るようになったからです。若者たち。私があなたがたに書いているのは、あなたがたが悪い者に打ち勝ったからです。'),
('JPN', '约翰一书', 62, 2, 14, '幼子たち。私があなたがたに書いてきたのは、あなたがたが御父を知るようになったからです。父たち。私があなたがたに書いてきたのは、初めからおられる方を、あなたがたが知るようになったからです。若者たち。私があなたがたに書いてきたのは、あなたがたが強い者であり、あなたがたのうちに神のことばがとどまり、悪い者に打ち勝ったからです。'),
('JPN', '约翰一书', 62, 2, 15, 'あなたがたは世も世にあるものも、愛してはいけません。もしだれかが世を愛しているなら、その人のうちに御父の愛はありません。'),
('JPN', '约翰一书', 62, 2, 16, 'すべて世にあるもの、すなわち、肉の欲、目の欲、暮らし向きの自慢は、御父から出るものではなく、世から出るものだからです。'),
('JPN', '约翰一书', 62, 2, 17, '世と、世の欲は過ぎ去ります。しかし、神のみこころを行う者は永遠に生き続けます。'),
('JPN', '约翰一书', 62, 2, 18, '幼子たち、今は終わりの時です。反キリストが来るとあなたがたが聞いていたとおり、今や多くの反キリストが現れています。それによって、今が終わりの時であると分かります。'),
('JPN', '约翰一书', 62, 2, 19, '彼らは私たちの中から出て行きましたが、もともと私たちの仲間ではなかったのです。もし仲間であったなら、私たちのもとに、とどまっていたでしょう。しかし、出て行ったのは、彼らがみな私たちの仲間でなかったことが明らかにされるためだったのです。'),
('JPN', '约翰一书', 62, 2, 20, 'あなたがたには聖なる方からの注ぎの油があるので、みな真理を知っています。'),
('JPN', '约翰一书', 62, 2, 21, '私がこのように書いてきたのは、あなたがたが真理を知らないからではなく、真理を知っているからです。また、偽りはすべて、真理から出ていないからです。'),
('JPN', '约翰一书', 62, 2, 22, '偽り者とは、イエスがキリストであることを否定する者でなくてだれでしょう。御父と御子を否定する者、それが反キリストです。'),
('JPN', '约翰一书', 62, 2, 23, 'だれでも御子を否定する者は御父を持たず、御子を告白する者は御父も持っているのです。'),
('JPN', '约翰一书', 62, 2, 24, 'あなたがたは、初めから聞いていることを自分のうちにとどまらせなさい。もし初めから聞いていることがとどまっているなら、あなたがたも御子と御父のうちにとどまります。'),
('JPN', '约翰一书', 62, 2, 25, 'これこそ、御子が私たちに約束してくださったもの、永遠のいのちです。'),
('JPN', '约翰一书', 62, 2, 26, '私はあなたがたを惑わす者たちについて、以上のことを書いてきました。'),
('JPN', '约翰一书', 62, 2, 27, 'しかし、あなたがたのうちには、御子から受けた注ぎの油がとどまっているので、だれかに教えてもらう必要はありません。その注ぎの油が、すべてについてあなたがたに教えてくれます。それは真理であって偽りではありませんから、あなたがたは教えられたとおり、御子のうちにとどまりなさい。'),
('JPN', '约翰一书', 62, 2, 28, 'さあ、子どもたち、キリストのうちにとどまりなさい。そうすれば、キリストが現れるとき、私たちは確信を持つことができ、来臨のときに御前で恥じることはありません。'),
('JPN', '约翰一书', 62, 2, 29, 'あなたがたは、神が正しい方であると知っているなら、義を行う者もみな神から生まれたことが分かるはずです。'),
('JPN', '约翰一书', 62, 3, 1, '私たちが神の子どもと呼ばれるために、御父がどんなにすばらしい愛を与えてくださったかを、考えなさい。事実、私たちは神の子どもです。世が私たちを知らないのは、御父を知らないからです。'),
('JPN', '约翰一书', 62, 3, 2, '愛する者たち、私たちは今すでに神の子どもです。やがてどのようになるのか、まだ明らかにされていません。しかし、私たちは、キリストが現れたときに、キリストに似た者になることは知っています。キリストをありのままに見るからです。'),
('JPN', '约翰一书', 62, 3, 3, 'キリストにこの望みを置いている者はみな、キリストが清い方であるように、自分を清くします。'),
('JPN', '约翰一书', 62, 3, 4, '罪を犯している者はみな、律法に違反しています。罪とは律法に違反することです。'),
('JPN', '约翰一书', 62, 3, 5, 'あなたがたが知っているとおり、キリストは罪を取り除くために現れたのであり、この方のうちに罪はありません。'),
('JPN', '约翰一书', 62, 3, 6, 'キリストにとどまる者はだれも、罪を犯しません。罪を犯す者はだれも、キリストを見たこともなく、知ってもいません。'),
('JPN', '约翰一书', 62, 3, 7, '幼子たち、だれにも惑わされてはいけません。義を行う者は、キリストが正しい方であるように、正しい人です。'),
('JPN', '约翰一书', 62, 3, 8, '罪を犯している者は、悪魔から出た者です。悪魔は初めから罪を犯しているからです。その悪魔のわざを打ち破るために、神の御子が現れました。'),
('JPN', '约翰一书', 62, 3, 9, '神から生まれた者はだれも、罪を犯しません。神の種がその人のうちにとどまっているからです。その人は神から生まれたので、罪を犯すことができないのです。'),
('JPN', '约翰一书', 62, 3, 10, 'このことによって、神の子どもと悪魔の子どもの区別がはっきりします。義を行わない者はだれであれ、神から出た者ではありません。兄弟を愛さない者もそうです。'),
('JPN', '约翰一书', 62, 3, 11, '互いに愛し合うべきであること、それが、あなたがたが初めから聞いている使信です。'),
('JPN', '约翰一书', 62, 3, 12, 'カインのようになってはいけません。彼は悪い者から出た者で、自分の兄弟を殺しました。なぜ殺したのでしょうか。自分の行いが悪く、兄弟の行いが正しかったからです。'),
('JPN', '约翰一书', 62, 3, 13, '兄弟たち。世があなたがたを憎んでも、驚いてはいけません。'),
('JPN', '约翰一书', 62, 3, 14, '私たちは、自分が死からいのちに移ったことを知っています。兄弟を愛しているからです。愛さない者は死のうちにとどまっています。'),
('JPN', '约翰一书', 62, 3, 15, '兄弟を憎む者はみな、人殺しです。あなたがたが知っているように、だれでも人を殺す者に、永遠のいのちがとどまることはありません。'),
('JPN', '约翰一书', 62, 3, 16, 'キリストは私たちのために、ご自分のいのちを捨ててくださいました。それによって私たちに愛が分かったのです。ですから、私たちも兄弟のために、いのちを捨てるべきです。'),
('JPN', '约翰一书', 62, 3, 17, 'この世の財を持ちながら、自分の兄弟が困っているのを見ても、その人に対してあわれみの心を閉ざすような者に、どうして神の愛がとどまっているでしょうか。'),
('JPN', '约翰一书', 62, 3, 18, '子どもたち。私たちは、ことばや口先だけではなく、行いと真実をもって愛しましょう。'),
('JPN', '约翰一书', 62, 3, 19, 'そうすることによって、私たちは自分が真理に属していることを知り、神の御前に心安らかでいられます。'),
('JPN', '约翰一书', 62, 3, 20, 'たとえ自分の心が責めたとしても、安らかでいられます。神は私たちの心よりも大きな方であり、すべてをご存じだからです。'),
('JPN', '约翰一书', 62, 3, 21, '愛する者たち。自分の心が責めないなら、私たちは神の御前に確信を持つことができます。'),
('JPN', '约翰一书', 62, 3, 22, 'そして、求めるものを何でも神からいただくことができます。私たちが神の命令を守り、神に喜ばれることを行っているからです。'),
('JPN', '约翰一书', 62, 3, 23, '私たちが御子イエス・キリストの名を信じ、キリストが命じられたとおりに互いに愛し合うこと、それが神の命令です。'),
('JPN', '约翰一书', 62, 3, 24, '神の命令を守る者は神のうちにとどまり、神もまた、その人のうちにとどまります。神が私たちのうちにとどまっておられることは、神が私たちに与えてくださった御霊によって分かります。'),
('JPN', '约翰一书', 62, 4, 1, '愛する者たち、霊をすべて信じてはいけません。偽預言者がたくさん世に出て来たので、その霊が神からのものかどうか、吟味しなさい。'),
('JPN', '约翰一书', 62, 4, 2, '神からの霊は、このようにして分かります。人となって来られたイエス・キリストを告白する霊はみな、神からのものです。'),
('JPN', '约翰一书', 62, 4, 3, 'イエスを告白しない霊はみな、神からのものではありません。それは反キリストの霊です。あなたがたはそれが来ることを聞いていましたが、今すでに世に来ているのです。'),
('JPN', '约翰一书', 62, 4, 4, '子どもたち。あなたがたは神から出た者であり、彼らに勝ちました。あなたがたのうちにおられる方は、この世にいる者よりも偉大だからです。'),
('JPN', '约翰一书', 62, 4, 5, '彼らはこの世の者です。ですから、世のことを話し、世も彼らの言うことを聞きます。'),
('JPN', '约翰一书', 62, 4, 6, '私たちは神から出た者です。神を知っている者は私たちの言うことを聞き、神から出ていない者は私たちの言うことを聞きません。それによって私たちは、真理の霊と偽りの霊を見分けます。'),
('JPN', '约翰一书', 62, 4, 7, '愛する者たち。私たちは互いに愛し合いましょう。愛は神から出ているのです。愛がある者はみな神から生まれ、神を知っています。'),
('JPN', '约翰一书', 62, 4, 8, '愛のない者は神を知りません。神は愛だからです。'),
('JPN', '约翰一书', 62, 4, 9, '神はそのひとり子を世に遣わし、その方によって私たちにいのちを得させてくださいました。それによって神の愛が私たちに示されたのです。'),
('JPN', '约翰一书', 62, 4, 10, '私たちが神を愛したのではなく、神が私たちを愛し、私たちの罪のために、宥めのささげ物としての御子を遣わされました。ここに愛があるのです。'),
('JPN', '约翰一书', 62, 4, 11, '愛する者たち。神がこれほどまでに私たちを愛してくださったのなら、私たちもまた、互いに愛し合うべきです。'),
('JPN', '约翰一书', 62, 4, 12, 'いまだかつて神を見た者はいません。私たちが互いに愛し合うなら、神は私たちのうちにとどまり、神の愛が私たちのうちに全うされるのです。'),
('JPN', '约翰一书', 62, 4, 13, '神が私たちに御霊を与えてくださったことによって、私たちが神のうちにとどまり、神も私たちのうちにとどまっておられることが分かります。'),
('JPN', '约翰一书', 62, 4, 14, '私たちは、御父が御子を世の救い主として遣わされたのを見て、その証しをしています。'),
('JPN', '约翰一书', 62, 4, 15, 'だれでも、イエスが神の御子であると告白するなら、神はその人のうちにとどまり、その人も神のうちにとどまっています。'),
('JPN', '约翰一书', 62, 4, 16, '私たちは自分たちに対する神の愛を知り、また信じています。神は愛です。愛のうちにとどまる人は神のうちにとどまり、神もその人のうちにとどまっておられます。'),
('JPN', '约翰一书', 62, 4, 17, 'こうして、愛が私たちにあって全うされました。ですから、私たちはさばきの日に確信を持つことができます。この世において、私たちもキリストと同じようであるからです。'),
('JPN', '约翰一书', 62, 4, 18, '愛には恐れがありません。全き愛は恐れを締め出します。恐れには罰が伴い、恐れる者は、愛において全きものとなっていないのです。'),
('JPN', '约翰一书', 62, 4, 19, '私たちは愛しています。神がまず私たちを愛してくださったからです。'),
('JPN', '约翰一书', 62, 4, 20, '神を愛すると言いながら兄弟を憎んでいるなら、その人は偽り者です。目に見える兄弟を愛していない者に、目に見えない神を愛することはできません。'),
('JPN', '约翰一书', 62, 4, 21, '神を愛する者は兄弟も愛すべきです。私たちはこの命令を神から受けています。'),
('JPN', '约翰一书', 62, 5, 1, 'イエスがキリストであると信じる者はみな、神から生まれたのです。生んでくださった方を愛する者はみな、その方から生まれた者も愛します。'),
('JPN', '约翰一书', 62, 5, 2, 'このことから分かるように、神を愛し、その命令を守るときはいつでも、私たちは神の子どもたちを愛するのです。'),
('JPN', '约翰一书', 62, 5, 3, '神の命令を守ること、それが、神を愛することです。神の命令は重荷とはなりません。'),
('JPN', '约翰一书', 62, 5, 4, '神から生まれた者はみな、世に勝つからです。私たちの信仰、これこそ、世に打ち勝った勝利です。'),
('JPN', '约翰一书', 62, 5, 5, '世に勝つ者とはだれでしょう。イエスを神の御子と信じる者ではありませんか。'),
('JPN', '约翰一书', 62, 5, 6, 'この方は、水と血によって来られた方、イエス・キリストです。水によるだけではなく、水と血によって来られました。御霊はこのことを証しする方です。御霊は真理だからです。'),
('JPN', '约翰一书', 62, 5, 7, '三つのものが証しをします。'),
('JPN', '约翰一书', 62, 5, 8, '御霊と水と血です。この三つは一致しています。'),
('JPN', '约翰一书', 62, 5, 9, '私たちが人の証しを受け入れるのであれば、神の証しはそれにまさるものです。御子について証しされたことが、神の証しなのですから。'),
('JPN', '约翰一书', 62, 5, 10, '神の御子を信じる者は、その証しを自分のうちに持っています。神を信じない者は、神を偽り者としています。神が御子について証しされた証言を信じていないからです。'),
('JPN', '约翰一书', 62, 5, 11, 'その証しとは、神が私たちに永遠のいのちを与えてくださったということ、そして、そのいのちが御子のうちにあるということです。'),
('JPN', '约翰一书', 62, 5, 12, '御子を持つ者はいのちを持っており、神の御子を持たない者はいのちを持っていません。'),
('JPN', '约翰一书', 62, 5, 13, '神の御子の名を信じているあなたがたに、これらのことを書いたのは、永遠のいのちを持っていることを、あなたがたに分からせるためです。'),
('JPN', '约翰一书', 62, 5, 14, '何事でも神のみこころにしたがって願うなら、神は聞いてくださるということ、これこそ神に対して私たちが抱いている確信です。'),
('JPN', '约翰一书', 62, 5, 15, '私たちが願うことは何でも神が聞いてくださると分かるなら、私たちは、神に願い求めたことをすでに手にしていると分かります。'),
('JPN', '约翰一书', 62, 5, 16, 'だれでも、兄弟が死に至らない罪を犯しているのを見たなら、神に求めなさい。そうすれば、神はその人にいのちを与えてくださいます。これは、死に至らない罪を犯している人たちの場合です。しかし、死に至る罪があります。これについては、願うようにとは言いません。'),
('JPN', '约翰一书', 62, 5, 17, '不義はすべて罪ですが、死に至らない罪もあります。'),
('JPN', '约翰一书', 62, 5, 18, '神から生まれた者はみな罪を犯さないこと、神から生まれた方がその人を守っておられ、悪い者はその人に触れることができないことを、私たちは知っています。'),
('JPN', '约翰一书', 62, 5, 19, '私たちは神に属していますが、世全体は悪い者の支配下にあることを、私たちは知っています。'),
('JPN', '约翰一书', 62, 5, 20, 'また、神の御子が来て、真実な方を知る理解力を私たちに与えてくださったことも、知っています。私たちは真実な方のうちに、その御子イエス・キリストのうちにいるのです。この方こそ、まことの神、永遠のいのちです。'),
('JPN', '约翰一书', 62, 5, 21, '子どもたち、偶像から自分を守りなさい。'),
('JPN', '约翰二书', 63, 1, 1, '長老から、選ばれた婦人とその子どもたちへ。私はあなたがたを本当に愛しています。私だけでなく、真理を知っている人々はみな、愛しています。'),
('JPN', '约翰二书', 63, 1, 2, '真理は私たちのうちにとどまり、いつまでも私たちとともにあるからです。'),
('JPN', '约翰二书', 63, 1, 3, '父なる神と、その御父の子イエス・キリストから、恵みとあわれみと平安が、真理と愛のうちに、私たちとともにありますように。'),
('JPN', '约翰二书', 63, 1, 4, '御父から私たちが受けた命令のとおりに、真理のうちを歩んでいる人たちが、あなたの子どもたちの中にいるのを知って、私は大いに喜んでいます。'),
('JPN', '约翰二书', 63, 1, 5, 'そこで婦人よ、今あなたにお願いします。それは、新しい命令としてあなたに書くのではなく、私たちが初めから持っていた命令です。私たちは互いに愛し合いましょう。'),
('JPN', '约翰二书', 63, 1, 6, '私たちが御父の命令にしたがって歩むこと、それが愛です。あなたがたが初めから聞いているように、愛のうちを歩むこと、それが命令です。'),
('JPN', '约翰二书', 63, 1, 7, 'こう命じるのは、人を惑わす者たち、イエス・キリストが人となって来られたことを告白しない者たちが、大勢世に出て来たからです。こういう者は惑わす者であり、反キリストです。'),
('JPN', '约翰二书', 63, 1, 8, '気をつけて、私たちが労して得たものを失わないように、むしろ豊かな報いを受けられるようにしなさい。'),
('JPN', '约翰二书', 63, 1, 9, 'だれでも、「先を行って」キリストの教えにとどまらない者は、神を持っていません。その教えにとどまる者こそ、御父も御子も持っています。'),
('JPN', '约翰二书', 63, 1, 10, 'あなたがたのところに来る人で、この教えを携えていない者は、家に受け入れてはいけません。あいさつのことばをかけてもいけません。'),
('JPN', '约翰二书', 63, 1, 11, 'そういう人にあいさつすれば、その悪い行いをともにすることになります。'),
('JPN', '约翰二书', 63, 1, 12, 'あなたがたにはたくさん書くべきことがありますが、紙と墨ではしたくありません。私たちの喜びが満ちあふれるために、あなたがたのところに行って、直接話したいと思います。'),
('JPN', '约翰二书', 63, 1, 13, '選ばれたあなたの姉妹の子どもたちが、あなたによろしくと言っています。'),
('JPN', '约翰三书', 64, 1, 1, '長老から、愛するガイオへ。私はあなたを本当に愛しています。'),
('JPN', '约翰三书', 64, 1, 2, '愛する者よ。あなたのたましいが幸いを得ているように、あなたがすべての点で幸いを得、また健康であるように祈ります。'),
('JPN', '约翰三书', 64, 1, 3, '兄弟たちがやって来ては、あなたが真理に歩んでいることを証ししてくれるので、私は大いに喜んでいます。実際、あなたは真理のうちに歩んでいます。'),
('JPN', '约翰三书', 64, 1, 4, '私にとって、自分の子どもたちが真理のうちに歩んでいることを聞くこと以上の大きな喜びはありません。'),
('JPN', '约翰三书', 64, 1, 5, '愛する者よ。あなたは、兄弟たちのための、それもよそから来た人たちのための働きを忠実に行っています。'),
('JPN', '约翰三书', 64, 1, 6, '彼らは教会の集まりで、あなたの愛について証ししました。あなたが彼らを、神にふさわしい仕方で送り出してくれるなら、それは立派な行いです。'),
('JPN', '约翰三书', 64, 1, 7, '彼らは御名のために、異邦人からは何も受けずに出て行ったのです。'),
('JPN', '约翰三书', 64, 1, 8, '私たちはこのような人々を受け入れるべきです。そうすれば、私たちは真理のために働く同労者となれます。'),
('JPN', '约翰三书', 64, 1, 9, '私は教会に少しばかり書き送りましたが、彼らの中でかしらになりたがっているディオテレペスが、私たちを受け入れません。'),
('JPN', '约翰三书', 64, 1, 10, 'ですから、私が行ったなら、彼のしている行為を指摘するつもりです。彼は意地悪なことばで私たちをののしっています。それでも満足せず、兄弟たちを受け入れないばかりか、受け入れたいと思う人たちの邪魔をし、教会から追い出しています。'),
('JPN', '约翰三书', 64, 1, 11, '愛する者よ。悪を見習わないで、善を見習いなさい。善を行う者は神から出た者であり、悪を行う者は神を見たことがない者です。'),
('JPN', '约翰三书', 64, 1, 12, 'デメテリオについては、すべての人たちが、また真理そのものが証ししています。私たちも証しします。私たちの証しが真実であることは、あなたも知っています。'),
('JPN', '约翰三书', 64, 1, 13, 'あなたに書き送るべきことがたくさんありますが、墨と筆で書きたくありません。'),
('JPN', '约翰三书', 64, 1, 14, '近いうちにあなたに会いたいと思います。そうしたら、直接話し合いましょう。'),
('JPN', '约翰三书', 64, 1, 15, '平安があなたにありますように。友人たちが、あなたによろしくと言っています。そちらの友人たち一人ひとりによろしく伝えてください。'),
('JPN', '犹大书', 65, 1, 1, 'イエス・キリストのしもべ、ヤコブの兄弟ユダから、父なる神にあって愛され、イエス・キリストによって守られている、召された方々へ。'),
('JPN', '犹大书', 65, 1, 2, 'あわれみと平安と愛が、あなたがたにますます豊かに与えられますように。'),
('JPN', '犹大书', 65, 1, 3, '愛する者たち。私たちがともにあずかっている救いについて、私はあなたがたに手紙を書こうと心から願っていましたが、聖徒たちにひとたび伝えられた信仰のために戦うよう、あなたがたに勧める手紙を書く必要が生じました。'),
('JPN', '犹大书', 65, 1, 4, 'それは、ある者たちが忍び込んできたからです。彼らは不敬虔な者たちで、私たちの神の恵みを放縦に変え、唯一の支配者であり私たちの主であるイエス・キリストを否定しているので、以下のようなさばきにあうと昔から記されています。'),
('JPN', '犹大书', 65, 1, 5, 'あなたがたはすべてのことをよく知っていますが、思い起こしてほしいのです。イエスは民をエジプトの地から救い出しましたが、その後、信じなかった者たちを滅ぼされました。'),
('JPN', '犹大书', 65, 1, 6, 'またイエスは、自分の領分を守らずに自分のいるべき所を捨てた御使いたちを、大いなる日のさばきのために、永遠の鎖につないで暗闇の下に閉じ込められました。'),
('JPN', '犹大书', 65, 1, 7, 'その御使いたちと同じように、ソドムやゴモラ、および周辺の町々も、淫行にふけって不自然な肉欲を追い求めたため、永遠の火の刑罰を受けて見せしめにされています。'),
('JPN', '犹大书', 65, 1, 8, 'それにもかかわらず、この人たちは同じように夢想にふけって、肉体を汚し、権威を認めず、栄光ある者たちをののしっています。'),
('JPN', '犹大书', 65, 1, 9, '御使いのかしらミカエルは、モーセのからだについて悪魔と論じて言い争ったとき、ののしってさばきを宣言することはあえてせず、むしろ「主がおまえをとがめてくださるように」と言いました。'),
('JPN', '犹大书', 65, 1, 10, 'しかし、この人たちは自分が知りもしないことを悪く言い、わきまえのない動物のように、本能で知るような事柄によって滅びるのです。'),
('JPN', '犹大书', 65, 1, 11, 'わざわいだ。彼らはカインの道を行き、利益のためにバラムの迷いに陥り、コラのように背いて滅びます。'),
('JPN', '犹大书', 65, 1, 12, 'この人たちは、あなたがたの愛餐のしみです。恐れる心もなく一緒に食事をしますが、自分を養っているだけです。彼らは、風に吹き流される雨無し雲、枯れに枯れて根こそぎにされた、実りなき秋の木、'),
('JPN', '犹大书', 65, 1, 13, '自分の恥を泡立たせる海の荒波、真っ暗な闇が永遠に用意されている、さまよえる星です。'),
('JPN', '犹大书', 65, 1, 14, 'アダムから七代目のエノクも、彼らについてこう預言しました。「見よ、主は何万もの聖徒を引き連れて来られる。'),
('JPN', '犹大书', 65, 1, 15, 'すべての者にさばきを行い、不敬虔に生きる者たちのすべての不敬虔な行いと、不敬虔な罪人たちが主に逆らって語ったすべての暴言について、皆を罪に定めるためである。」'),
('JPN', '犹大书', 65, 1, 16, '彼らは、ぶつぶつ不満を並べる者たちで、自らの欲望のままに生きています。その口は大げさなことを語り、利益のために人にへつらいます。'),
('JPN', '犹大书', 65, 1, 17, '愛する者たち。あなたがたは、私たちの主イエス・キリストの使徒たちが前もって語ったことばを思い起こしなさい。'),
('JPN', '犹大书', 65, 1, 18, '彼らはあなたがたにこう言いました。「終わりの時には、嘲る者たちが現れて、自分の不敬虔な欲望のままにふるまう。」'),
('JPN', '犹大书', 65, 1, 19, 'この人たちは、分裂を引き起こす、生まれつきのままの人間で、御霊を持っていません。'),
('JPN', '犹大书', 65, 1, 20, 'しかし、愛する者たち。あなたがたは自分たちの最も聖なる信仰の上に、自分自身を築き上げなさい。聖霊によって祈りなさい。'),
('JPN', '犹大书', 65, 1, 21, '神の愛のうちに自分自身を保ち、永遠のいのちに導く、私たちの主イエス・キリストのあわれみを待ち望みなさい。'),
('JPN', '犹大书', 65, 1, 22, 'ある人々が疑いを抱くなら、その人たちをあわれみなさい。'),
('JPN', '犹大书', 65, 1, 23, 'ほかの人たちは、火の中からつかみ出して救いなさい。また、ほかの人たちは、肉によって汚された下着さえ忌み嫌い、神を恐れつつあわれみなさい。'),
('JPN', '犹大书', 65, 1, 24, 'あなたがたを、つまずかないように守ることができ、傷のない者として、大きな喜びとともに栄光の御前に立たせることができる方、'),
('JPN', '犹大书', 65, 1, 25, '私たちの救い主である唯一の神に、私たちの主イエス・キリストを通して、栄光、威厳、支配、権威が、永遠の昔も今も、世々限りなくありますように。アーメン。'),
('JPN', '启示录', 66, 1, 1, 'イエス・キリストの黙示。神はすぐに起こるべきことをしもべたちに示すため、これをキリストに与えられた。そしてキリストは、御使いを遣わして、これをしもべヨハネに告げられた。'),
('JPN', '启示录', 66, 1, 2, 'ヨハネは、神のことばとイエス・キリストの証し、すなわち、自分が見たすべてのことを証しした。'),
('JPN', '启示录', 66, 1, 3, 'この預言のことばを朗読する者と、それを聞いて、そこに書かれていることを守る者たちは、幸いである。時が近づいているからである。'),
('JPN', '启示录', 66, 1, 4, 'ヨハネから、アジアにある七つの教会へ。今おられ、昔おられ、やがて来られる方から、また、その御座の前におられる七つの御霊から、'),
('JPN', '启示录', 66, 1, 5, 'また、確かな証人、死者の中から最初に生まれた方、地の王たちの支配者であるイエス・キリストから、恵みと平安があなたがたにあるように。私たちを愛し、その血によって私たちを罪から解き放ち、'),
('JPN', '启示录', 66, 1, 6, 'また、ご自分の父である神のために、私たちを王国とし、祭司としてくださった方に、栄光と力が世々限りなくあるように。アーメン。'),
('JPN', '启示录', 66, 1, 7, '見よ、その方は雲とともに来られる。すべての目が彼を見る。彼を突き刺した者たちさえも。地のすべての部族は彼のゆえに胸をたたいて悲しむ。しかり、アーメン。'),
('JPN', '启示录', 66, 1, 8, '神である主、今おられ、昔おられ、やがて来られる方、全能者がこう言われる。「わたしはアルファであり、オメガである。」'),
('JPN', '启示录', 66, 1, 9, '私ヨハネは、あなたがたの兄弟で、あなたがたとともにイエスにある苦難と御国と忍耐にあずかっている者であり、神のことばとイエスの証しのゆえに、パトモスという島にいた。'),
('JPN', '启示录', 66, 1, 10, '私は主の日に御霊に捕らえられ、私のうしろにラッパのような大きな声を聞いた。'),
('JPN', '启示录', 66, 1, 11, 'その声はこう言った。「あなたが見たことを巻物に記して、七つの教会、すなわち、エペソ、スミルナ、ペルガモン、ティアティラ、サルディス、フィラデルフィア、ラオディキアに送りなさい。」'),
('JPN', '启示录', 66, 1, 12, '私は、自分に語りかける声を見ようとして振り向いた。振り向くと、七つの金の燭台が見えた。'),
('JPN', '启示录', 66, 1, 13, 'また、その燭台の真ん中に、人の子のような方が見えた。その方は、足まで垂れた衣をまとい、胸に金の帯を締めていた。'),
('JPN', '启示录', 66, 1, 14, 'その頭と髪は白い羊毛のように、また雪のように白く、その目は燃える炎のようであった。'),
('JPN', '启示录', 66, 1, 15, 'その足は、炉で精錬された、光り輝く真鍮のようで、その声は大水のとどろきのようであった。'),
('JPN', '启示录', 66, 1, 16, 'また、右手に七つの星を持ち、口から鋭い両刃の剣が出ていて、顔は強く照り輝く太陽のようであった。'),
('JPN', '启示录', 66, 1, 17, 'この方を見たとき、私は死んだ者のように、その足もとに倒れ込んだ。すると、その方は私の上に右手を置いて言われた。「恐れることはない。わたしは初めであり、終わりであり、'),
('JPN', '启示录', 66, 1, 18, '生きている者である。わたしは死んだが、見よ、世々限りなく生きている。また、死とよみの鍵を持っている。'),
('JPN', '启示录', 66, 1, 19, 'それゆえ、あなたが見たこと、今あること、この後起ころうとしていることを書き記せ。'),
('JPN', '启示录', 66, 1, 20, 'あなたがわたしの右手に見た七つの星と、七つの金の燭台の、秘められた意味について。七つの星は七つの教会の御使いたち、七つの燭台は七つの教会である。'),
('JPN', '启示录', 66, 2, 1, 'エペソにある教会の御使いに書き送れ。『右手に七つの星を握る方、七つの金の燭台の間を歩く方が、こう言われる──。'),
('JPN', '启示录', 66, 2, 2, 'わたしは、あなたの行い、あなたの労苦と忍耐を知っている。また、あなたが悪者たちに我慢がならず、使徒と自称しているが実はそうでない者たちを試して、彼らを偽り者だと見抜いたことも知っている。'),
('JPN', '启示录', 66, 2, 3, 'あなたはよく忍耐して、わたしの名のために耐え忍び、疲れ果てなかった。'),
('JPN', '启示录', 66, 2, 4, 'けれども、あなたには責めるべきことがある。あなたは初めの愛から離れてしまった。'),
('JPN', '启示录', 66, 2, 5, 'だから、どこから落ちたのか思い起こし、悔い改めて初めの行いをしなさい。そうせず、悔い改めないなら、わたしはあなたのところに行って、あなたの燭台をその場所から取り除く。'),
('JPN', '启示录', 66, 2, 6, 'しかし、あなたにはこのことがある。あなたはニコライ派の人々の行いを憎んでいる。わたしもそれを憎んでいる。'),
('JPN', '启示录', 66, 2, 7, '耳のある者は、御霊が諸教会に告げることを聞きなさい。勝利を得る者には、わたしはいのちの木から食べることを許す。それは神のパラダイスにある。』'),
('JPN', '启示录', 66, 2, 8, 'また、スミルナにある教会の御使いに書き送れ。『初めであり終わりである方、死んでよみがえられた方が、こう言われる──。'),
('JPN', '启示录', 66, 2, 9, 'わたしは、あなたの苦難と貧しさを知っている。だが、あなたは富んでいるのだ。ユダヤ人だと自称しているが実はそうでない者たち、サタンの会衆である者たちから、ののしられていることも、わたしは知っている。'),
('JPN', '启示录', 66, 2, 10, 'あなたが受けようとしている苦しみを、何も恐れることはない。見よ。悪魔は試すために、あなたがたのうちのだれかを牢に投げ込もうとしている。あなたがたは十日の間、苦難にあう。死に至るまで忠実でありなさい。そうすれば、わたしはあなたにいのちの冠を与える。'),
('JPN', '启示录', 66, 2, 11, '耳のある者は、御霊が諸教会に告げることを聞きなさい。勝利を得る者は、決して第二の死によって害を受けることはない。』'),
('JPN', '启示录', 66, 2, 12, 'また、ペルガモンにある教会の御使いに書き送れ。『鋭い両刃の剣を持つ方が、こう言われる──。'),
('JPN', '启示录', 66, 2, 13, 'わたしは、あなたが住んでいるところを知っている。そこにはサタンの王座がある。しかしあなたは、わたしの名を堅く保って、わたしの確かな証人アンティパスが、サタンが住むあなたがたのところで殺されたときでさえ、わたしに対する信仰を捨てなかった。'),
('JPN', '启示录', 66, 2, 14, 'けれども、あなたには少しばかり責めるべきことがある。あなたのところに、バラムの教えを頑なに守る者たちがいる。バラムはバラクに教えて、偶像に献げたいけにえをイスラエルの子らが食べ、淫らなことを行うように、彼らの前につまずきを置かせた。'),
('JPN', '启示录', 66, 2, 15, '同じように、あなたのところにもニコライ派の教えを頑なに守っている者たちがいる。'),
('JPN', '启示录', 66, 2, 16, 'だから、悔い改めなさい。そうしないなら、わたしはすぐにあなたのところに行き、わたしの口の剣をもって彼らと戦う。'),
('JPN', '启示录', 66, 2, 17, '耳のある者は、御霊が諸教会に告げることを聞きなさい。勝利を得る者には、わたしは隠されているマナを与える。また、白い石を与える。その石には、それを受ける者のほかはだれも知らない、新しい名が記されている。』'),
('JPN', '启示录', 66, 2, 18, 'また、ティアティラにある教会の御使いに書き送れ。『燃える炎のような目を持ち、その足は光り輝く真鍮のような神の子が、こう言われる──。'),
('JPN', '启示录', 66, 2, 19, 'わたしは、あなたの行い、あなたの愛と信仰と奉仕と忍耐を知っている。また、初めの行いにまさる、近ごろの行いも知っている。'),
('JPN', '启示录', 66, 2, 20, 'けれども、あなたには責めるべきことがある。あなたは、あの女、イゼベルをなすがままにさせている。この女は、預言者だと自称しているが、わたしのしもべたちを教えて惑わし、淫らなことを行わせ、偶像に献げた物を食べさせている。'),
('JPN', '启示录', 66, 2, 21, 'わたしは悔い改める機会を与えたが、この女は淫らな行いを悔い改めようとしない。'),
('JPN', '启示录', 66, 2, 22, '見よ、わたしはこの女を病の床に投げ込む。また、この女と姦淫を行う者たちも、この女の行いを離れて悔い改めないなら、大きな患難の中に投げ込む。'),
('JPN', '启示录', 66, 2, 23, 'また、この女の子どもたちを死病で殺す。こうしてすべての教会は、わたしが人の思いと心を探る者であることを知る。わたしは、あなたがたの行いに応じて一人ひとりに報いる。'),
('JPN', '启示录', 66, 2, 24, 'しかし、ティアティラにいる残りの者たち、この教えを受け入れず、いわゆる「サタンの深み」を知らないあなたがたに言う。わたしはあなたがたに、ほかの重荷を負わせない。'),
('JPN', '启示录', 66, 2, 25, 'ただ、あなたがたが持っているものを、わたしが行くまで、しっかり保ちなさい。'),
('JPN', '启示录', 66, 2, 26, '勝利を得る者、最後までわたしのわざを守る者には、諸国の民を支配する権威を与える。'),
('JPN', '启示录', 66, 2, 27, '彼は鉄の杖で彼らを牧する。土の器を砕くように。'),
('JPN', '启示录', 66, 2, 28, 'わたしも父から支配する権威を受けたが、それと同じである。また、勝利を得る者には、わたしは明けの明星を与える。'),
('JPN', '启示录', 66, 2, 29, '耳のある者は、御霊が諸教会に告げることを聞きなさい。』'),
('JPN', '启示录', 66, 3, 1, 'また、サルディスにある教会の御使いに書き送れ。『神の七つの御霊と七つの星を持つ方が、こう言われる──。わたしはあなたの行いを知っている。あなたは、生きているとは名ばかりで、実は死んでいる。'),
('JPN', '启示录', 66, 3, 2, '目を覚まし、死にかけている残りの者たちを力づけなさい。わたしは、あなたの行いがわたしの神の御前に完了したとは見ていない。'),
('JPN', '启示录', 66, 3, 3, 'だから、どのように受け、聞いたのか思い起こし、それを守り、悔い改めなさい。目を覚まさないなら、わたしは盗人のように来る。わたしがいつあなたのところに来るか、あなたには決して分からない。'),
('JPN', '启示录', 66, 3, 4, 'しかし、サルディスには、わずかだが、その衣を汚さなかった者たちがいる。彼らは白い衣を着て、わたしとともに歩む。彼らがそれにふさわしい者たちだからである。'),
('JPN', '启示录', 66, 3, 5, '勝利を得る者は、このように白い衣を着せられる。またわたしは、その者の名をいのちの書から決して消しはしない。わたしはその名を、わたしの父の御前と御使いたちの前で言い表す。'),
('JPN', '启示录', 66, 3, 6, '耳のある者は、御霊が諸教会に告げることを聞きなさい。』'),
('JPN', '启示录', 66, 3, 7, 'また、フィラデルフィアにある教会の御使いに書き送れ。『聖なる方、真実な方、ダビデの鍵を持っている方、彼が開くと、だれも閉じることがなく、彼が閉じると、だれも開くことがない。その方がこう言われる──。'),
('JPN', '启示录', 66, 3, 8, 'わたしはあなたの行いを知っている。見よ。わたしは、だれも閉じることができない門を、あなたの前に開いておいた。あなたには少しばかりの力があって、わたしのことばを守り、わたしの名を否まなかったからである。'),
('JPN', '启示录', 66, 3, 9, '見よ。サタンの会衆に属する者、すなわち、ユダヤ人だと自称しているが、実はそうではなく、噓を言っている者たちに、わたしはこうする。見よ。彼らをあなたの足もとに来させてひれ伏させ、わたしがあなたを愛していることを知らせる。'),
('JPN', '启示录', 66, 3, 10, 'あなたは忍耐についてのわたしのことばを守ったので、地上に住む者たちを試みるために全世界に来ようとしている試練の時には、わたしもあなたを守る。'),
('JPN', '启示录', 66, 3, 11, 'わたしはすぐに来る。あなたは、自分の冠をだれにも奪われないように、持っているものをしっかり保ちなさい。'),
('JPN', '启示录', 66, 3, 12, 'わたしは、勝利を得る者を、わたしの神の神殿の柱とする。彼はもはや決して外に出て行くことはない。わたしは彼の上に、わたしの神の御名と、わたしの神の都、すなわち、わたしの神のもとを出て天から下って来る新しいエルサレムの名と、わたしの新しい名とを書き記す。'),
('JPN', '启示录', 66, 3, 13, '耳のある者は、御霊が諸教会に告げることを聞きなさい。』'),
('JPN', '启示录', 66, 3, 14, 'また、ラオディキアにある教会の御使いに書き送れ。『アーメンである方、確かで真実な証人、神による創造の源である方がこう言われる──。'),
('JPN', '启示录', 66, 3, 15, 'わたしはあなたの行いを知っている。あなたは冷たくもなく、熱くもない。むしろ、冷たいか熱いかであってほしい。'),
('JPN', '启示录', 66, 3, 16, 'そのように、あなたは生ぬるく、熱くも冷たくもないので、わたしは口からあなたを吐き出す。'),
('JPN', '启示录', 66, 3, 17, 'あなたは、自分は富んでいる、豊かになった、足りないものは何もないと言っているが、実はみじめで、哀れで、貧しくて、盲目で、裸であることが分かっていない。'),
('JPN', '启示录', 66, 3, 18, 'わたしはあなたに忠告する。豊かな者となるために、火で精錬された金をわたしから買い、あなたの裸の恥をあらわにしないために着る白い衣を買い、目が見えるようになるために目に塗る目薬を買いなさい。'),
('JPN', '启示录', 66, 3, 19, 'わたしは愛する者をみな、叱ったり懲らしめたりする。だから熱心になって悔い改めなさい。'),
('JPN', '启示录', 66, 3, 20, '見よ、わたしは戸の外に立ってたたいている。だれでも、わたしの声を聞いて戸を開けるなら、わたしはその人のところに入って彼とともに食事をし、彼もわたしとともに食事をする。'),
('JPN', '启示录', 66, 3, 21, '勝利を得る者を、わたしとともにわたしの座に着かせる。それは、わたしが勝利を得て、わたしの父とともに父の御座に着いたのと同じである。'),
('JPN', '启示录', 66, 3, 22, '耳のある者は、御霊が諸教会に告げることを聞きなさい。』」'),
('JPN', '启示录', 66, 4, 1, 'その後、私は見た。すると見よ、開かれた門が天にあった。そして、ラッパのような音で私に語りかけるのが聞こえた、あの最初の声が言った。「ここに上れ。この後必ず起こることを、あなたに示そう。」'),
('JPN', '启示录', 66, 4, 2, 'たちまち私は御霊に捕らえられた。すると見よ。天に御座があり、その御座に着いている方がおられた。'),
('JPN', '启示录', 66, 4, 3, 'その方は碧玉や赤めのうのように見え、御座の周りには、エメラルドのように見える虹があった。'),
('JPN', '启示录', 66, 4, 4, 'また、御座の周りには二十四の座があった。これらの座には、白い衣をまとい、頭に金の冠をかぶった二十四人の長老たちが座っていた。'),
('JPN', '启示录', 66, 4, 5, '御座からは稲妻がひらめき、声と雷鳴がとどろいていた。御座の前では、火のついた七つのともしびが燃えていた。神の七つの御霊である。'),
('JPN', '启示录', 66, 4, 6, '御座の前は、水晶に似た、ガラスの海のようであった。そして、御座のあたり、御座の周りに、前もうしろも目で満ちた四つの生き物がいた。'),
('JPN', '启示录', 66, 4, 7, '第一の生き物は獅子のようであり、第二の生き物は雄牛のようであり、第三の生き物は人間のような顔を持ち、第四の生き物は飛んでいる鷲のようであった。'),
('JPN', '启示录', 66, 4, 8, 'この四つの生き物には、それぞれ六つの翼があり、その周りと内側は目で満ちていた。そして、昼も夜も休みなく言い続けていた。「聖なる、聖なる、聖なる、主なる神、全能者。昔おられ、今もおられ、やがて来られる方。」'),
('JPN', '启示录', 66, 4, 9, 'また、これらの生き物が栄光と誉れと感謝を、御座に着いて世々限りなく生きておられる方にささげるとき、'),
('JPN', '启示录', 66, 4, 10, '二十四人の長老たちは、御座に着いておられる方の前にひれ伏して、世々限りなく生きておられる方を礼拝した。また、自分たちの冠を御座の前に投げ出して言った。'),
('JPN', '启示录', 66, 4, 11, '「主よ、私たちの神よ。あなたこそ栄光と誉れと力を受けるにふさわしい方。あなたが万物を創造されました。みこころのゆえに、それらは存在し、また創造されたのです。」'),
('JPN', '启示录', 66, 5, 1, 'また私は、御座に着いておられる方の右の手に巻物を見た。それは内側にも外側にも字が書かれていて、七つの封印で封じられていた。'),
('JPN', '启示录', 66, 5, 2, 'また私は、一人の強い御使いが「巻物を開き、封印を解くのにふさわしい者はだれか」と大声で告げているのを見た。'),
('JPN', '启示录', 66, 5, 3, 'しかし、天でも地でも地の下でも、だれ一人その巻物を開くことのできる者、見ることのできる者はいなかった。'),
('JPN', '启示录', 66, 5, 4, '私は激しく泣いた。その巻物を開くにも、見るにも、ふさわしい者がだれも見つからなかったからである。'),
('JPN', '启示录', 66, 5, 5, 'すると、長老の一人が私に言った。「泣いてはいけません。ご覧なさい。ユダ族から出た獅子、ダビデの根が勝利したので、彼がその巻物を開き、七つの封印を解くことができます。」'),
('JPN', '启示录', 66, 5, 6, 'また私は、御座と四つの生き物の真ん中、長老たちの真ん中に、屠られた姿で子羊が立っているのを見た。それは七つの角と七つの目を持っていた。その目は、全地に遣わされた神の七つの御霊であった。'),
('JPN', '启示录', 66, 5, 7, '子羊は来て、御座に着いておられる方の右の手から巻物を受け取った。'),
('JPN', '启示录', 66, 5, 8, '巻物を受け取ったとき、四つの生き物と二十四人の長老たちは子羊の前にひれ伏した。彼らはそれぞれ、竪琴と、香に満ちた金の鉢を持っていた。香は聖徒たちの祈りであった。'),
('JPN', '启示录', 66, 5, 9, '彼らは新しい歌を歌った。「あなたは、巻物を受け取り、封印を解くのにふさわしい方です。あなたは屠られて、すべての部族、言語、民族、国民の中から、あなたの血によって人々を神のために贖い、'),
('JPN', '启示录', 66, 5, 10, '私たちの神のために、彼らを王国とし、祭司とされました。彼らは地を治めるのです。」'),
('JPN', '启示录', 66, 5, 11, 'また私は見た。そして御座と生き物と長老たちの周りに、多くの御使いたちの声を聞いた。その数は万の数万倍、千の数千倍であった。'),
('JPN', '启示录', 66, 5, 12, '彼らは大声で言った。「屠られた子羊は、力と富と知恵と勢いと誉れと栄光と賛美を受けるにふさわしい方です。」'),
('JPN', '启示录', 66, 5, 13, 'また私は、天と地と地の下と海にいるすべての造られたもの、それらの中にあるすべてのものがこう言うのを聞いた。「御座に着いておられる方と子羊に、賛美と誉れと栄光と力が世々限りなくあるように。」'),
('JPN', '启示录', 66, 5, 14, 'すると、四つの生き物は「アーメン」と言い、長老たちはひれ伏して礼拝した。'),
('JPN', '启示录', 66, 6, 1, 'また私は、子羊が七つの封印の一つを解くのを見た。そして、四つの生き物の一つが、雷のような声で「来なさい」と言うのを聞いた。'),
('JPN', '启示录', 66, 6, 2, '私は見た。すると見よ、白い馬がいた。それに乗っている者は弓を持っていた。彼は冠を与えられ、勝利の上にさらに勝利を得るために出て行った。'),
('JPN', '启示录', 66, 6, 3, '子羊が第二の封印を解いたとき、私は、第二の生き物が「来なさい」と言うのを聞いた。'),
('JPN', '启示录', 66, 6, 4, 'すると別の、火のように赤い馬が出て来た。それに乗っている者は、地から平和を奪い取ることが許された。人々が互いに殺し合うようになるためである。また、彼に大きな剣が与えられた。'),
('JPN', '启示录', 66, 6, 5, '子羊が第三の封印を解いたとき、私は、第三の生き物が「来なさい」と言うのを聞いた。私は見た。すると見よ、黒い馬がいた。これに乗っている者は秤を手に持っていた。'),
('JPN', '启示录', 66, 6, 6, '私は、一つの声のようなものが、四つの生き物の真ん中でこう言うのを聞いた。「小麦一コイニクスが一デナリ。大麦三コイニクスが一デナリ。オリーブ油とぶどう酒に害を与えてはいけない。」'),
('JPN', '启示录', 66, 6, 7, '子羊が第四の封印を解いたとき、私は、第四の生き物の声が「来なさい」と言うのを聞いた。'),
('JPN', '启示录', 66, 6, 8, '私は見た。すると見よ、青ざめた馬がいた。これに乗っている者の名は「死」で、よみがそれに従っていた。彼らに、地上の四分の一を支配して、剣と飢饉と死病と地の獣によって殺す権威が与えられた。'),
('JPN', '启示录', 66, 6, 9, '子羊が第五の封印を解いたとき、私は、神のことばと、自分たちが立てた証しのゆえに殺された者たちのたましいが、祭壇の下にいるのを見た。'),
('JPN', '启示录', 66, 6, 10, '彼らは大声で叫んだ。「聖なるまことの主よ。いつまでさばきを行わず、地に住む者たちに私たちの血の復讐をなさらないのですか。」'),
('JPN', '启示录', 66, 6, 11, 'すると、彼ら一人ひとりに白い衣が与えられた。そして、彼らのしもべ仲間で、彼らと同じように殺されようとしている兄弟たちの数が満ちるまで、もうしばらくの間、休んでいるように言い渡された。'),
('JPN', '启示录', 66, 6, 12, 'また私は見た。子羊が第六の封印を解いたとき、大きな地震が起こった。太陽は毛織りの粗布のように黒くなり、月の全面が血のようになった。'),
('JPN', '启示录', 66, 6, 13, 'そして天の星が地上に落ちた。それは、いちじくが大風に揺さぶられて、青い実を落とすようであった。'),
('JPN', '启示录', 66, 6, 14, '天は、巻物が巻かれるように消えてなくなり、すべての山と島は、かつてあった場所から移された。'),
('JPN', '启示录', 66, 6, 15, '地の王たち、高官たち、千人隊長たち、金持ちたち、力ある者たち、すべての奴隷と自由人が、洞穴と山の岩間に身を隠した。'),
('JPN', '启示录', 66, 6, 16, 'そして、山々や岩に向かって言った。「私たちの上に崩れ落ちて、御座に着いておられる方の御顔と、子羊の御怒りから私たちを隠してくれ。'),
('JPN', '启示录', 66, 6, 17, '神と子羊の御怒りの、大いなる日が来たからだ。だれがそれに耐えられよう。」'),
('JPN', '启示录', 66, 7, 1, 'その後、私は四人の御使いを見た。彼らは地の四隅に立ち、地の四方の風をしっかりと押さえて、地にも海にもどんな木にも吹きつけないようにしていた。'),
('JPN', '启示录', 66, 7, 2, 'また私は、もう一人の御使いが、日の昇る方から、生ける神の印を持って上って来るのを見た。彼は、地にも海にも害を加えることを許された四人の御使いたちに、大声で叫んだ。'),
('JPN', '启示录', 66, 7, 3, '「私たちが神のしもべたちの額に印を押してしまうまで、地にも海にも木にも害を加えてはいけない。」'),
('JPN', '启示录', 66, 7, 4, '私は、印を押された者たちの数を耳にした。それは十四万四千人で、イスラエルの子らのあらゆる部族の者が印を押されていた。'),
('JPN', '启示录', 66, 7, 5, 'ユダ族から一万二千人が印を押され、ルベン族から一万二千人、ガド族から一万二千人、')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '启示录', 66, 7, 6, 'アシェル族から一万二千人、ナフタリ族から一万二千人、マナセ族から一万二千人、'),
('JPN', '启示录', 66, 7, 7, 'シメオン族から一万二千人、レビ族から一万二千人、イッサカル族から一万二千人、'),
('JPN', '启示录', 66, 7, 8, 'ゼブルン族から一万二千人、ヨセフ族から一万二千人、ベニヤミン族から一万二千人が印を押されていた。'),
('JPN', '启示录', 66, 7, 9, 'その後、私は見た。すると見よ。すべての国民、部族、民族、言語から、だれも数えきれないほどの大勢の群衆が御座の前と子羊の前に立ち、白い衣を身にまとい、手になつめ椰子の枝を持っていた。'),
('JPN', '启示录', 66, 7, 10, '彼らは大声で叫んだ。「救いは、御座に着いておられる私たちの神と、子羊にある。」'),
('JPN', '启示录', 66, 7, 11, '御使いたちはみな、御座と長老たちと四つの生き物の周りに立っていたが、御座の前にひれ伏し、神を礼拝して言った。'),
('JPN', '启示录', 66, 7, 12, '「アーメン。賛美と栄光と知恵と感謝と誉れと力と勢いが、私たちの神に世々限りなくあるように。アーメン。」'),
('JPN', '启示录', 66, 7, 13, 'すると、長老の一人が私に話しかけて、「この白い衣を身にまとった人たちはだれですか。どこから来たのですか」と言った。'),
('JPN', '启示录', 66, 7, 14, 'そこで私が「私の主よ、あなたこそご存じです」と言うと、長老は私に言った。「この人たちは大きな患難を経てきた者たちで、その衣を洗い、子羊の血で白くしたのです。'),
('JPN', '启示录', 66, 7, 15, 'それゆえ、彼らは神の御座の前にあって、昼も夜もその神殿で神に仕えている。御座に着いておられる方も、彼らの上に幕屋を張られる。'),
('JPN', '启示录', 66, 7, 16, '彼らは、もはや飢えることも渇くこともなく、太陽もどんな炎熱も、彼らを襲うことはない。'),
('JPN', '启示录', 66, 7, 17, '御座の中央におられる子羊が彼らを牧し、いのちの水の泉に導かれる。また、神は彼らの目から涙をことごとくぬぐい取ってくださる。」'),
('JPN', '启示录', 66, 8, 1, '子羊が第七の封印を解いたとき、天に半時間ほどの静けさがあった。'),
('JPN', '启示录', 66, 8, 2, 'それから私は、神の御前に立っている七人の御使いたちを見た。彼らに七つのラッパが与えられた。'),
('JPN', '启示录', 66, 8, 3, 'また、別の御使いが来て、金の香炉を持って祭壇のそばに立った。すると、たくさんの香が彼に与えられた。すべての聖徒たちの祈りに添えて、御座の前にある金の祭壇の上で献げるためであった。'),
('JPN', '启示录', 66, 8, 4, '香の煙は、聖徒たちの祈りとともに、御使いの手から神の御前に立ち上った。'),
('JPN', '启示录', 66, 8, 5, 'それから御使いは、その香炉を取り、それを祭壇の火で満たしてから地に投げつけた。すると、雷鳴と声がとどろき、稲妻がひらめき、地震が起こった。'),
('JPN', '启示录', 66, 8, 6, 'また、七つのラッパを持った七人の御使いたちは、ラッパを吹く用意をした。'),
('JPN', '启示录', 66, 8, 7, '第一の御使いがラッパを吹いた。すると、血の混じった雹と火が現れて、地に投げ込まれた。そして地の三分の一が焼かれ、木々の三分の一も焼かれ、すべての青草も焼かれてしまった。'),
('JPN', '启示录', 66, 8, 8, '第二の御使いがラッパを吹いた。すると、火の燃えている大きな山のようなものが、海に投げ込まれた。そして海の三分の一が血になった。'),
('JPN', '启示录', 66, 8, 9, 'また、海の中にいる被造物で、いのちのあるものの三分の一が死に、船の三分の一が壊された。'),
('JPN', '启示录', 66, 8, 10, '第三の御使いがラッパを吹いた。すると、天から、たいまつのように燃えている大きな星が落ちて来て、川の三分の一とその水源の上に落ちた。'),
('JPN', '启示录', 66, 8, 11, 'この星の名は「苦よもぎ」と呼ばれ、水の三分の一は苦よもぎのようになった。水が苦くなったので、その水のために多くの人が死んだ。'),
('JPN', '启示录', 66, 8, 12, '第四の御使いがラッパを吹いた。すると太陽の三分の一と、月の三分の一、また星の三分の一が打たれたので、それらの三分の一は暗くなり、昼の三分の一は光を失い、夜も同じようになった。'),
('JPN', '启示录', 66, 8, 13, 'また私は見た。そして、一羽の鷲が中天を飛びながら、大声でこう言うのを聞いた。「わざわいだ、わざわいだ、わざわいが来る。地上に住む者たちに。三人の御使いが吹こうとしている残りのラッパの音によって。」'),
('JPN', '启示录', 66, 9, 1, '第五の御使いがラッパを吹いた。すると私は、一つの星が天から地に落ちるのを見た。その星には、底知れぬ所に通じる穴の鍵が与えられた。'),
('JPN', '启示录', 66, 9, 2, 'それが底知れぬ所に通じる穴を開くと、穴から大きなかまどの煙のような煙が立ち上り、太陽と空はこの穴の煙のために暗くなった。'),
('JPN', '启示录', 66, 9, 3, 'その煙の中からいなごが地上に出て来た。それらには、地のサソリが持っているような力が与えられた。'),
('JPN', '启示录', 66, 9, 4, 'そして彼らは、地の草やどんな青草、どんな木にも害を加えてはならないが、額に神の印を持たない人たちには加えてよい、と言い渡された。'),
('JPN', '启示录', 66, 9, 5, 'その人たちを殺すことは許されなかったが、五か月間苦しめることは許された。彼らの苦痛は、サソリが人を刺したときの苦痛のようだった。'),
('JPN', '启示录', 66, 9, 6, 'その期間、人々は死を探し求めるが、決して見出すことはない。死ぬことを切に願うが、死は彼らから逃げて行く。'),
('JPN', '启示录', 66, 9, 7, 'いなごたちの姿は、出陣の用意が整った馬に似ていた。頭には金の冠のようなものをかぶり、顔は人間の顔のようであった。'),
('JPN', '启示录', 66, 9, 8, 'また、女の髪のような毛があり、歯は獅子の歯のようであった。'),
('JPN', '启示录', 66, 9, 9, 'また、鉄の胸当てのような胸当てを着け、その羽の音は、馬に引かれた多くの戦車が戦いに急ぐときの音のようであった。'),
('JPN', '启示录', 66, 9, 10, '彼らはサソリのような尾と針を持っていて、その尾には、五か月間、人々に害を加える力があった。'),
('JPN', '启示录', 66, 9, 11, 'いなごたちは、底知れぬ所の使いを王としている。その名はヘブル語でアバドン、ギリシア語でアポリュオンという。'),
('JPN', '启示录', 66, 9, 12, '第一のわざわいは過ぎ去った。見よ、この後、なお二つのわざわいが来る。'),
('JPN', '启示录', 66, 9, 13, '第六の御使いがラッパを吹いた。すると、神の御前にある金の祭壇の四本の角から、一つの声が聞こえた。'),
('JPN', '启示录', 66, 9, 14, 'その声は、ラッパを持っている第六の御使いに言った。「大河ユーフラテスのほとりにつながれている、四人の御使いを解き放て。」'),
('JPN', '启示录', 66, 9, 15, 'すると、その時、その日、その月、その年のために用意されていた、四人の御使いが解き放たれた。人間の三分の一を殺すためであった。'),
('JPN', '启示录', 66, 9, 16, '騎兵の数は二億で、私はその数を耳にした。'),
('JPN', '启示录', 66, 9, 17, '私が幻の中で見た馬と、それに乗っている者たちの様子はこうであった。彼らは、燃えるような赤と紫と硫黄の色の胸当てを着けており、馬の頭は獅子の頭のようで、口からは火と煙と硫黄が出ていた。'),
('JPN', '启示录', 66, 9, 18, 'これら三つの災害、すなわち、彼らの口から出る火と煙と硫黄によって、人間の三分の一が殺された。'),
('JPN', '启示录', 66, 9, 19, '馬の力は口と尾にあって、その尾は蛇に似て頭を持ち、その頭で害を加えるのである。'),
('JPN', '启示录', 66, 9, 20, 'これらの災害によって殺されなかった、人間の残りの者たちは、悔い改めて自分たちの手で造った物から離れるということをせず、悪霊どもや、金、銀、銅、石、木で造られた偶像、すなわち見ることも聞くことも歩くこともできないものを、拝み続けた。'),
('JPN', '启示录', 66, 9, 21, 'また彼らは、自分たちが行っている殺人、魔術、淫らな行いや盗みを悔い改めなかった。'),
('JPN', '启示录', 66, 10, 1, 'また私は、もう一人の強い御使いが、雲に包まれて天から下って来るのを見た。その頭上には虹があり、その顔は太陽のよう、その足は火の柱のようで、'),
('JPN', '启示录', 66, 10, 2, '手には開かれた小さな巻物を持っていた。御使いは右足を海の上、左足を地の上に置いて、'),
('JPN', '启示录', 66, 10, 3, '獅子が吼えるように大声で叫んだ。彼が叫んだとき、七つの雷がそれぞれの声を発した。'),
('JPN', '启示录', 66, 10, 4, '七つの雷が語ったとき、私は書き留めようとした。すると、天からの声がこう言うのを聞いた。「七つの雷が語ったことは封じておけ。それを書き記すな。」'),
('JPN', '启示录', 66, 10, 5, 'それから、海の上と地の上に立っているのを私が見たあの御使いは、右手を天に上げ、'),
('JPN', '启示录', 66, 10, 6, '天とその中にあるもの、地とその中にあるもの、海とその中にあるものを造って、世々限りなく生きておられる方にかけて誓った。「もはや時は残されておらず、'),
('JPN', '启示录', 66, 10, 7, '第七の御使いが吹こうとしているラッパの音が響くその日に、神の奥義は、神がご自分のしもべである預言者たちに告げたとおりに実現する。」'),
('JPN', '启示录', 66, 10, 8, 'それから、前に天から聞こえた声が、再び私に語りかけた。「行って、海の上と地の上に立っている御使いの手にある、開かれた巻物を受け取りなさい。」'),
('JPN', '启示录', 66, 10, 9, '私はその御使いのところに行き、「私にその小さな巻物を下さい」と言った。すると彼は言った。「それを取って食べてしまいなさい。それはあなたの腹には苦いが、あなたの口には蜜のように甘い。」'),
('JPN', '启示录', 66, 10, 10, 'そこで、私はその小さな巻物を御使いの手から受け取って食べた。口には蜜のように甘かったが、それを食べてしまうと、私の腹は苦くなった。'),
('JPN', '启示录', 66, 10, 11, 'すると私はこう告げられた。「あなたはもう一度、多くの民族、国民、言語、王たちについて預言しなければならない。」'),
('JPN', '启示录', 66, 11, 1, 'それから、杖のような測り竿が私に与えられて、こう告げられた。「立って、神の神殿と祭壇と、そこで礼拝している人々を測りなさい。'),
('JPN', '启示录', 66, 11, 2, '神殿の外の庭はそのままにしておきなさい。それを測ってはいけない。それは異邦人に与えられているからだ。彼らは聖なる都を四十二か月の間、踏みにじることになる。'),
('JPN', '启示录', 66, 11, 3, 'わたしがそれを許すので、わたしの二人の証人は、粗布をまとって千二百六十日間、預言する。」'),
('JPN', '启示录', 66, 11, 4, '彼らは、地を治める主の御前に立っている二本のオリーブの木、また二つの燭台である。'),
('JPN', '启示录', 66, 11, 5, 'もしだれかが彼らに害を加えようとするなら、彼らの口から火が出て、敵を焼き尽くす。もしだれかが彼らに害を加えようとするなら、必ずこのように殺される。'),
('JPN', '启示录', 66, 11, 6, 'この二人は、預言をしている期間、雨が降らないように天を閉じる権威を持っている。また、水を血に変える権威、さらに、思うままに何度でも、あらゆる災害で地を打つ権威を持っている。'),
('JPN', '启示录', 66, 11, 7, '二人が証言を終えると、底知れぬ所から上って来る獣が、彼らと戦って勝ち、彼らを殺してしまう。'),
('JPN', '启示录', 66, 11, 8, '彼らの死体は大きな都の大通りにさらされる。その都は、霊的な理解ではソドムやエジプトと呼ばれ、そこで彼らの主も十字架にかけられたのである。'),
('JPN', '启示录', 66, 11, 9, 'もろもろの民族、部族、言語、国民に属する人々が、三日半の間、彼らの死体を眺めていて、その死体を墓に葬ることを許さない。'),
('JPN', '启示录', 66, 11, 10, '地に住む者たちは、彼らのことで喜び祝って、互いに贈り物を交わす。この二人の預言者たちが、地に住む者たちを苦しめたからである。'),
('JPN', '启示录', 66, 11, 11, 'しかし、三日半の後、いのちの息が神から出て二人のうちに入り、彼らは自分たちの足で立った。見ていた者たちは大きな恐怖に襲われた。'),
('JPN', '启示录', 66, 11, 12, '二人は、天から大きな声が「ここに上れ」と言うのを聞いた。そして、彼らは雲に包まれて天に上った。彼らの敵たちはそれを見た。'),
('JPN', '启示录', 66, 11, 13, 'そのとき、大きな地震が起こって、都の十分の一が倒れた。この地震のために七千人が死んだ。残った者たちは恐れを抱き、天の神に栄光を帰した。'),
('JPN', '启示录', 66, 11, 14, '第二のわざわいが過ぎ去った。見よ、第三のわざわいがすぐに来る。'),
('JPN', '启示录', 66, 11, 15, '第七の御使いがラッパを吹いた。すると大きな声が天に起こって、こう言った。「この世の王国は、私たちの主と、そのキリストのものとなった。主は世々限りなく支配される。」'),
('JPN', '启示录', 66, 11, 16, 'すると、神の御前で自分たちの座に着いていた二十四人の長老たちが、ひれ伏し、神を礼拝して言った。'),
('JPN', '启示录', 66, 11, 17, '「私たちはあなたに感謝します。今おられ、昔おられた全能者、神である主よ。あなたは偉大な力を働かせて、王となられました。'),
('JPN', '启示录', 66, 11, 18, '諸国の民は怒りました。しかし、あなたの御怒りが来ました。死者がさばかれる時、あなたのしもべである預言者たちと聖徒たち、御名を恐れる者たち、小さい者にも大きい者にも報いが与えられる時、地を滅ぼす者たちが滅ぼされる時です。」'),
('JPN', '启示录', 66, 11, 19, 'それから、天にある神の神殿が開かれ、神の契約の箱が神殿の中に見えた。すると稲妻がひらめき、雷鳴がとどろき、地震が起こり、大粒の雹が降った。'),
('JPN', '启示录', 66, 12, 1, 'また、大きなしるしが天に現れた。一人の女が太陽をまとい、月を足の下にし、頭に十二の星の冠をかぶっていた。'),
('JPN', '启示录', 66, 12, 2, '女は身ごもっていて、子を産む痛みと苦しみのために、叫び声をあげていた。'),
('JPN', '启示录', 66, 12, 3, 'また、別のしるしが天に現れた。見よ、炎のように赤い大きな竜。それは、七つの頭と十本の角を持ち、その頭に七つの王冠をかぶっていた。'),
('JPN', '启示录', 66, 12, 4, 'その尾は天の星の三分の一を引き寄せて、それらを地に投げ落とした。また竜は、子を産もうとしている女の前に立ち、産んだら、その子を食べてしまおうとしていた。'),
('JPN', '启示录', 66, 12, 5, '女は男の子を産んだ。この子は、鉄の杖をもってすべての国々の民を牧することになっていた。その子は神のみもとに、その御座に引き上げられた。'),
('JPN', '启示录', 66, 12, 6, '女は荒野に逃れた。そこには、千二百六十日の間、人々が彼女を養うようにと、神によって備えられた場所があった。'),
('JPN', '启示录', 66, 12, 7, 'さて、天に戦いが起こって、ミカエルとその御使いたちは竜と戦った。竜とその使いたちも戦ったが、'),
('JPN', '启示录', 66, 12, 8, '勝つことができず、天にはもはや彼らのいる場所がなくなった。'),
('JPN', '启示录', 66, 12, 9, 'こうして、その大きな竜、すなわち、古い蛇、悪魔とかサタンとか呼ばれる者、全世界を惑わす者が地に投げ落とされた。また、彼の使いたちも彼とともに投げ落とされた。'),
('JPN', '启示录', 66, 12, 10, '私は、大きな声が天でこう言うのを聞いた。「今や、私たちの神の救いと力と王国と、神のキリストの権威が現れた。私たちの兄弟たちの告発者、昼も夜も私たちの神の御前で訴える者が、投げ落とされたからである。'),
('JPN', '启示录', 66, 12, 11, '兄弟たちは、子羊の血と、自分たちの証しのことばのゆえに竜に打ち勝った。彼らは死に至るまでも自分のいのちを惜しまなかった。'),
('JPN', '启示录', 66, 12, 12, 'それゆえ、天とそこに住む者たちよ、喜べ。しかし、地と海はわざわいだ。悪魔が自分の時が短いことを知って激しく憤り、おまえたちのところへ下ったからだ。」'),
('JPN', '启示录', 66, 12, 13, '竜は、自分が地へ投げ落とされたのを知ると、男の子を産んだ女を追いかけた。'),
('JPN', '启示录', 66, 12, 14, 'しかし、女には大きな鷲の翼が二つ与えられた。荒野にある自分の場所に飛んで行って、そこで一時と二時と半時の間、蛇の前から逃れて養われるためであった。'),
('JPN', '启示录', 66, 12, 15, 'すると蛇はその口から、女のうしろへ水を川のように吐き出し、彼女を大水で押し流そうとした。'),
('JPN', '启示录', 66, 12, 16, 'しかし、地は女を助け、その口を開けて、竜が口から吐き出した川を飲み干した。'),
('JPN', '启示录', 66, 12, 17, 'すると竜は女に対して激しく怒り、女の子孫の残りの者、すなわち、神の戒めを守り、イエスの証しを堅く保っている者たちと戦おうとして出て行った。'),
('JPN', '启示录', 66, 12, 18, 'そして、竜は海辺の砂の上に立った。'),
('JPN', '启示录', 66, 13, 1, 'また私は、海から一頭の獣が上って来るのを見た。これには十本の角と七つの頭があった。その角には十の王冠があり、その頭には神を冒瀆する様々な名があった。'),
('JPN', '启示录', 66, 13, 2, '私が見たその獣は豹に似ていて、足は熊の足のよう、口は獅子の口のようであった。竜はこの獣に、自分の力と自分の王座と大きな権威を与えた。'),
('JPN', '启示录', 66, 13, 3, 'その頭のうちの一つは打たれて死んだと思われたが、その致命的な傷は治った。全地は驚いてその獣に従い、'),
('JPN', '启示录', 66, 13, 4, '竜を拝んだ。竜が獣に権威を与えたからである。また人々は獣も拝んで言った。「だれがこの獣に比べられるだろうか。だれがこれと戦うことができるだろうか。」'),
('JPN', '启示录', 66, 13, 5, 'この獣には、大言壮語して冒瀆のことばを語る口が与えられ、四十二か月の間、活動する権威が与えられた。'),
('JPN', '启示录', 66, 13, 6, '獣は神を冒瀆するために口を開いて、神の御名と神の幕屋、また天に住む者たちを冒瀆した。'),
('JPN', '启示录', 66, 13, 7, '獣は、聖徒たちに戦いを挑んで打ち勝つことが許された。また、あらゆる部族、民族、言語、国民を支配する権威が与えられた。'),
('JPN', '启示录', 66, 13, 8, '地に住む者たちで、世界の基が据えられたときから、屠られた子羊のいのちの書にその名が書き記されていない者はみな、この獣を拝むようになる。'),
('JPN', '启示录', 66, 13, 9, '耳のある者は聞きなさい。'),
('JPN', '启示录', 66, 13, 10, '捕らわれの身になるべき者は捕らわれ、剣で殺されるべき者は剣で殺される。ここに、聖徒たちの忍耐と信仰が必要である。'),
('JPN', '启示录', 66, 13, 11, 'また私は、別の獣が地から上って来るのを見た。それは、子羊の角に似た二本の角を持ち、竜が語るように語っていた。'),
('JPN', '启示录', 66, 13, 12, 'この獣は、最初の獣が持っていたすべての権威を、その獣の前で働かせた。また、地と地に住む者たちに、致命的な傷が治った最初の獣を拝ませた。'),
('JPN', '启示录', 66, 13, 13, 'また、大きなしるしを行い、人々の前で火を天から地に降らせることさえした。'),
('JPN', '启示录', 66, 13, 14, 'また、この獣は、あの獣の前で行うことが許されたしるしによって、地に住む者たちを惑わし、剣の傷を受けながらも生き返ったあの獣の像を造るように、地に住む者たちに命じた。'),
('JPN', '启示录', 66, 13, 15, 'それから、その獣の像に息を吹き込んで、獣の像がものを言うことさえできるようにし、また、その像を拝まない者たちをみな殺すようにした。'),
('JPN', '启示录', 66, 13, 16, 'また獣は、すべての者に、すなわち、小さい者にも大きい者にも、富んでいる者にも貧しい者にも、自由人にも奴隷にも、その右の手あるいは額に刻印を受けさせた。'),
('JPN', '启示录', 66, 13, 17, 'また、その刻印を持っている者以外は、だれも物を売り買いできないようにした。刻印とは、あの獣の名、またはその名が表す数字である。'),
('JPN', '启示录', 66, 13, 18, 'ここに、知恵が必要である。思慮ある者はその獣の数字を数えなさい。それは人間を表す数字であるから。その数字は六百六十六である。'),
('JPN', '启示录', 66, 14, 1, 'また私は見た。すると見よ、子羊がシオンの山の上に立っていた。また、子羊とともに十四万四千人の人たちがいて、その額には子羊の名と、子羊の父の名が記されていた。'),
('JPN', '启示录', 66, 14, 2, 'また、私は天からの声を聞いた。それは大水のとどろきのようであり、激しい雷鳴のようでもあった。しかも、私が聞いたその声は、竪琴を弾く人たちが竪琴に合わせて歌う声のようであった。'),
('JPN', '启示录', 66, 14, 3, '彼らは御座の前と、四つの生き物および長老たちの前で、新しい歌を歌った。しかし、地上から贖われた十四万四千人のほかは、この歌を学ぶことができなかった。'),
('JPN', '启示录', 66, 14, 4, 'この人たちは、女に触れて汚れたことがない者たちで、童貞である。彼らは、子羊が行く所、どこにでもついて行く。彼らは、神と子羊に献げられる初穂として、人々の中から贖い出されたのである。'),
('JPN', '启示录', 66, 14, 5, '彼らの口には偽りが見出されなかった。彼らは傷のない者たちである。'),
('JPN', '启示录', 66, 14, 6, 'また私は、もう一人の御使いが中天を飛ぶのを見た。彼は地に住む人々、すなわち、あらゆる国民、部族、言語、民族に宣べ伝えるために、永遠の福音を携えていた。'),
('JPN', '启示录', 66, 14, 7, '彼は大声で言った。「神を恐れよ。神に栄光を帰せよ。神のさばきの時が来たからだ。天と地と海と水の源を創造した方を礼拝せよ。」'),
('JPN', '启示录', 66, 14, 8, 'また、その御使いの後にもう一人、第二の御使いが来て言った。「倒れた、倒れた、大バビロンが。御怒りを招く淫行のぶどう酒を、すべての国々の民に飲ませた都が。」'),
('JPN', '启示录', 66, 14, 9, 'また、彼らの後にもう一人、第三の御使いがやって来て、大声で言った。「もしだれかが獣とその像を拝み、自分の額か手に刻印を受けるなら、'),
('JPN', '启示录', 66, 14, 10, 'その者は、神の怒りの杯に混ぜ物なしに注がれた、神の憤りのぶどう酒を飲み、聖なる御使いたちと子羊の前で火と硫黄によって苦しめられる。'),
('JPN', '启示录', 66, 14, 11, '彼らの苦しみの煙は、世々限りなく立ち上る。獣とその像を拝む者たち、また、だれでも獣の名の刻印を受ける者には、昼も夜も安らぎがない。」'),
('JPN', '启示录', 66, 14, 12, 'ここに、聖徒たち、すなわち神の戒めを守り、イエスに対する信仰を持ち続ける者たちの忍耐が必要である。'),
('JPN', '启示录', 66, 14, 13, 'また私は、天からの声がこう言うのを聞いた。「書き記せ、『今から後、主にあって死ぬ死者は幸いである』と。」御霊も言われる。「しかり。その人たちは、その労苦から解き放たれて安らぐことができる。彼らの行いが、彼らとともについて行くからである。」'),
('JPN', '启示录', 66, 14, 14, 'また私は見た。すると見よ。白い雲が起こり、その雲の上に人の子のような方が座っておられた。その頭には金の冠、手には鋭い鎌があった。'),
('JPN', '启示录', 66, 14, 15, 'すると、別の御使いが神殿から出て来て、雲の上に座っておられる方に大声で叫んだ。「あなたの鎌を送って、刈り取ってください。刈り入れの時が来ましたから。地の穀物は実っています。」'),
('JPN', '启示录', 66, 14, 16, '雲の上に座っておられる方が地上に鎌を投げると、地は刈り取られた。'),
('JPN', '启示录', 66, 14, 17, 'それから、もう一人の御使いが天の神殿から出て来たが、彼もまた、鋭い鎌を持っていた。'),
('JPN', '启示录', 66, 14, 18, 'すると、火をつかさどる権威を持つ別の御使いが祭壇から出て来て、鋭い鎌を持つ御使いに大声で呼びかけた。「あなたの鋭い鎌を送って、地のぶどうの房を刈り集めよ。ぶどうはすでに熟している。」'),
('JPN', '启示录', 66, 14, 19, '御使いは地上に鎌を投げて、地のぶどうを刈り集め、神の憤りの大きな踏み場に投げ入れた。'),
('JPN', '启示录', 66, 14, 20, '都の外にあるその踏み場でぶどうが踏まれた。すると、血がその踏み場から流れ出て、馬のくつわの高さに届くほどになり、千六百スタディオンに広がった。'),
('JPN', '启示录', 66, 15, 1, 'また私は、天にもう一つの大きな驚くべきしるしを見た。七人の御使いが、最後の七つの災害を携えていた。ここに神の憤りは極まるのである。'),
('JPN', '启示录', 66, 15, 2, '私は、火が混じった、ガラスの海のようなものを見た。獣とその像とその名を示す数字に打ち勝った人々が、神の竪琴を手にしてガラスの海のほとりに立っていた。'),
('JPN', '启示录', 66, 15, 3, '彼らは神のしもべモーセの歌と子羊の歌を歌った。「主よ、全能者なる神よ。あなたのみわざは偉大で、驚くべきものです。諸国の民の王よ。あなたの道は正しく真実です。'),
('JPN', '启示录', 66, 15, 4, '主よ、あなたを恐れず、御名をあがめない者がいるでしょうか。あなただけが聖なる方です。すべての国々の民は来て、あなたの御前にひれ伏します。あなたの正しいさばきが明らかにされたからです。」'),
('JPN', '启示录', 66, 15, 5, 'その後、私は見た。天にある、あかしの幕屋である神殿が開かれた。'),
('JPN', '启示录', 66, 15, 6, 'そして七人の御使いが、七つの災害を携えて神殿から出て来た。彼らは、きよく光り輝く亜麻布を着て、胸には金の帯を締めていた。'),
('JPN', '启示录', 66, 15, 7, 'また、四つの生き物の一つが、七人の御使いたちに七つの金の鉢を渡したが、それには世々限りなく生きておられる神の憤りが満ちていた。'),
('JPN', '启示录', 66, 15, 8, '神殿は、神の栄光とその御力から立ち上る煙で満たされ、七人の御使いたちの七つの災害が終わるまでは、だれもその神殿に入ることができなかった。'),
('JPN', '启示录', 66, 16, 1, 'また私は、大きな声が神殿から出て、七人の御使いに、「行って、七つの鉢から神の憤りを地に注げ」と言うのを聞いた。'),
('JPN', '启示录', 66, 16, 2, '第一の御使いが出て行き、鉢の中身を地に注いだ。すると、獣の刻印を受けている者たちと獣の像を拝む者たちに、ひどい悪性の腫れものができた。'),
('JPN', '启示录', 66, 16, 3, '第二の御使いが鉢の中身を海に注いだ。すると、海は死者の血のようになった。海の中にいる生き物はみな死んだ。'),
('JPN', '启示录', 66, 16, 4, '第三の御使いが鉢の中身を川と水の源に注いだ。すると、それらは血になった。'),
('JPN', '启示录', 66, 16, 5, 'また私は、水をつかさどる御使いがこう言うのを聞いた。「今おられ、昔おられた聖なる方、あなたは正しい方です。このようなさばきを行われたからです。'),
('JPN', '启示录', 66, 16, 6, '彼らは聖徒たちや預言者たちの血を流しましたが、あなたは彼らに血を飲ませられました。彼らにはそれがふさわしいからです。」'),
('JPN', '启示录', 66, 16, 7, 'また私は、祭壇がこう言うのを聞いた。「しかり。主よ、全能者なる神よ。あなたのさばきは真実で正しいさばきです。」'),
('JPN', '启示录', 66, 16, 8, '第四の御使いが鉢の中身を太陽に注いだ。すると、太陽は人々を火で焼くことを許された。'),
('JPN', '启示录', 66, 16, 9, 'こうして人々は激しい炎熱で焼かれ、これらの災害を支配する権威を持つ神の御名を冒瀆した。彼らが悔い改めて神に栄光を帰することはなかった。'),
('JPN', '启示录', 66, 16, 10, '第五の御使いが鉢の中身を獣の座に注いだ。すると、獣の王国は闇におおわれ、人々は苦しみのあまり舌をかんだ。'),
('JPN', '启示录', 66, 16, 11, 'そして、その苦しみと腫れもののゆえに天の神を冒瀆し、自分の行いを悔い改めようとしなかった。'),
('JPN', '启示录', 66, 16, 12, '第六の御使いが鉢の中身を大河ユーフラテスに注いだ。すると、その水は涸れてしまい、日の昇る方から来る王たちの道を備えることになった。'),
('JPN', '启示录', 66, 16, 13, 'また、私は竜の口と獣の口、また偽預言者の口から、蛙のような三つの汚れた霊が出て来るのを見た。'),
('JPN', '启示录', 66, 16, 14, 'これらは、しるしを行う悪霊どもの霊であり、全世界の王たちのところに出て行く。全能者なる神の大いなる日の戦いに備えて、彼らを召集するためである。'),
('JPN', '启示录', 66, 16, 15, '──見よ、わたしは盗人のように来る。裸で歩き回って、恥ずかしい姿を人々に見られることのないように、目を覚まして衣を着ている者は幸いである──'),
('JPN', '启示录', 66, 16, 16, 'こうして汚れた霊どもは、ヘブル語でハルマゲドンと呼ばれる場所に王たちを集めた。'),
('JPN', '启示录', 66, 16, 17, '第七の御使いが鉢の中身を空中に注いだ。すると大きな声が神殿の中から、御座から出て、「事は成就した」と言った。'),
('JPN', '启示录', 66, 16, 18, 'そして稲妻がひらめき、雷鳴がとどろき、大きな地震が起こった。これは人間が地上に現れて以来、いまだかつてなかったほどの、大きな強い地震であった。'),
('JPN', '启示录', 66, 16, 19, 'あの大きな都は三つの部分に裂かれ、諸国の民の町々は倒れた。神は大バビロンを忘れず、ご自分の激しい憤りのぶどう酒の杯を与えられた。'),
('JPN', '启示录', 66, 16, 20, '島はすべて逃げ去り、山々は見えなくなった。'),
('JPN', '启示录', 66, 16, 21, 'また、一タラントほどの大きな雹が、天から人々の上に降った。この雹の災害のために、人々は神を冒瀆した。その災害が非常に激しかったからである。'),
('JPN', '启示录', 66, 17, 1, 'また、七つの鉢を持つ七人の御使いの一人が来て、私に語りかけた。「ここに来なさい。大水の上に座している大淫婦に対するさばきを見せましょう。'),
('JPN', '启示录', 66, 17, 2, '地の王たちは、この女と淫らなことを行い、地に住む人々は、この女の淫行のぶどう酒に酔いました。」'),
('JPN', '启示录', 66, 17, 3, 'それから、御使いは私を御霊によって荒野へ連れて行った。私は、一人の女が緋色の獣に乗っているのを見た。その獣は神を冒瀆する名で満ちていて、七つの頭と十本の角を持っていた。'),
('JPN', '启示录', 66, 17, 4, 'その女は紫と緋色の衣をまとい、金と宝石と真珠で身を飾り、忌まわしいものと、自らの淫行の汚れで満ちた金の杯を手に持っていた。'),
('JPN', '启示录', 66, 17, 5, 'その額には、意味の秘められた名、「大バビロン、淫婦たちと地上の忌まわしいものの母」という名が記されていた。'),
('JPN', '启示录', 66, 17, 6, '私は、この女が聖徒たちの血とイエスの証人たちの血に酔っているのを見た。私はこの女を見て、非常に驚いた。'),
('JPN', '启示录', 66, 17, 7, 'すると、御使いは私に言った。「なぜ驚くのですか。私は、この女の秘められた意味と、この女を乗せている、七つの頭と十本の角を持つ獣の秘められた意味を、あなたに話しましょう。'),
('JPN', '启示录', 66, 17, 8, 'あなたが見た獣は、昔はいたが、今はいません。やがて底知れぬ所から上って来ますが、滅びることになります。地に住む者たちで、世界の基が据えられたときからいのちの書に名が書き記されていない者たちは、その獣が昔はいたが今はおらず、やがて現れるのを見て驚くでしょう。'),
('JPN', '启示录', 66, 17, 9, 'ここに、知恵のある考え方が必要です。七つの頭とは、この女が座している七つの山で、それは七人の王たちのことです。'),
('JPN', '启示录', 66, 17, 10, '五人はすでに倒れましたが、一人は今いて、もう一人はまだ来ていません。彼が来れば、しばらくとどまるはずです。'),
('JPN', '启示录', 66, 17, 11, 'また、昔はいたが今はいないあの獣は八番目の王ですが、七人のうちの一人でもあり、滅びることになります。'),
('JPN', '启示录', 66, 17, 12, 'あなたが見た十本の角は十人の王たちです。彼らはまだ王権を受けていませんが、獣とともに、一時だけ王としての権威を受けます。'),
('JPN', '启示录', 66, 17, 13, 'これらの王たちは一つ思いとなり、自分たちの力と権威をその獣に委ねます。'),
('JPN', '启示录', 66, 17, 14, '彼らは子羊に戦いを挑みますが、子羊は彼らに打ち勝ちます。子羊は主の主、王の王だからです。子羊とともにいる者たちは、召されて選ばれた忠実な者たちです。」'),
('JPN', '启示录', 66, 17, 15, 'また、御使いは私に言った。「あなたが見た水、淫婦が座しているところは、もろもろの民族、群衆、国民、言語です。'),
('JPN', '启示录', 66, 17, 16, 'あなたが見た十本の角と獣は、やがて淫婦を憎み、はぎ取って裸にし、その肉を食らって火で焼き尽くすことになります。'),
('JPN', '启示录', 66, 17, 17, 'それは、神のことばが成る時まで、神はみこころが実現するように王たちの心を動かし、彼らが一つ思いとなって、自分たちの支配権を獣に委ねるようにされたからです。'),
('JPN', '启示录', 66, 17, 18, 'あなたが見たあの女は、地の王たちを支配する大きな都のことです。」'),
('JPN', '启示录', 66, 18, 1, 'その後、私は、もう一人の御使いが、大きな権威を持って天から下って来るのを見た。地はその栄光によって照らされた。'),
('JPN', '启示录', 66, 18, 2, '彼は力強い声で叫んだ。「倒れた。大バビロンは倒れた。それは、悪霊の住みか、あらゆる汚れた霊の巣窟、あらゆる汚れた鳥の巣窟、あらゆる汚れた憎むべき獣の巣窟となった。'),
('JPN', '启示录', 66, 18, 3, 'すべての国々の民は、御怒りを招く彼女の淫行のぶどう酒を飲み、地の王たちは彼女と淫らなことを行い、地の商人たちは、彼女の過度のぜいたくによって富を得たからだ。」'),
('JPN', '启示录', 66, 18, 4, 'それから私は、天からもう一つの声がこう言うのを聞いた。「わたしの民は、この女の罪に関わらないように、その災害に巻き込まれないように、彼女のところから出て行きなさい。'),
('JPN', '启示录', 66, 18, 5, '彼女の罪は積み重なって天に達し、神は彼女の不正を覚えておられるからです。'),
('JPN', '启示录', 66, 18, 6, 'あなたがたは、彼女が支払ったとおりに彼女に報いなさい。彼女の行いに応じて倍にして返しなさい。彼女が混ぜ合わせた杯の中に、彼女のために倍のものを混ぜ合わせなさい。'),
('JPN', '启示录', 66, 18, 7, '彼女が自分を誇り、ぜいたくにふけった分だけ、苦しみと悲しみを彼女に与えなさい。彼女は心の中で『私は女王として座し、やもめではない。だから悲しみにあうことはない』と言っているからです。'),
('JPN', '启示录', 66, 18, 8, 'これらのことのため、一日のうちに、様々な災害、死病と悲しみと飢えが彼女を襲います。そして、彼女は火で焼き尽くされます。彼女をさばく神である主は、力ある方なのです。」'),
('JPN', '启示录', 66, 18, 9, '彼女と淫らなことを行い、ぜいたくをした地の王たちは、彼女が焼かれる煙を見ると、彼女のことで泣いて胸を打ちたたく。'),
('JPN', '启示录', 66, 18, 10, '彼らは遠く離れて立ち、彼女の苦しみに恐れをなして、「わざわいだ、わざわいだ、大きな都、力強い都バビロンよ。あなたのさばきは一瞬にしてなされた」と言う。'),
('JPN', '启示录', 66, 18, 11, 'また、地の商人たちは彼女のことで泣き悲しむ。彼らの商品を買う者が、もはやだれもいないからである。'),
('JPN', '启示录', 66, 18, 12, '商品とは、金、銀、宝石、真珠、亜麻布、紫布、絹、緋色の布、あらゆる香木、あらゆる象牙細工、高価な木材や青銅や鉄や大理石で造ったあらゆる器具、'),
('JPN', '启示录', 66, 18, 13, 'シナモン、香料、香、香油、乳香、ぶどう酒、オリーブ油、小麦粉、小麦、家畜、羊、馬、馬車、奴隷、それに人のいのちである。'),
('JPN', '启示录', 66, 18, 14, '「おまえの心が欲しがる果物は、おまえから遠ざかり、ぜいたくな物や華やかな物は、すべておまえから消え失せて、もはや決して見出すことはできない。」'),
('JPN', '启示录', 66, 18, 15, 'これらの物を商って彼女から富を得ていた商人たちは、彼女の苦しみに恐れをなして、遠く離れて立ち、泣き悲しんで言う。'),
('JPN', '启示录', 66, 18, 16, '「わざわいだ、わざわいだ、大きな都よ。亜麻布、紫布、緋色の布をまとい、金、宝石、真珠で身を飾っていたが、'),
('JPN', '启示录', 66, 18, 17, 'あれほどの富が、一瞬にして荒廃に帰してしまった。」また、すべての船長、その場所を航海するすべての者たち、水夫たち、海で働く者たちもみな、遠く離れて立ち、'),
('JPN', '启示录', 66, 18, 18, '彼女が焼かれる煙を見て、「これほどの大きな都がほかにあっただろうか」と叫んだ。'),
('JPN', '启示录', 66, 18, 19, '彼らは頭にちりをかぶり、泣き悲しんで叫んだ。「わざわいだ、わざわいだ、大きな都よ。海に船を持つ者たちはみな、ここでその繁栄から富を得ていたのに、その都が一瞬にして荒れ果ててしまうとは。」'),
('JPN', '启示录', 66, 18, 20, '「天よ、この都のことで喜べ。聖徒たちも使徒たちも預言者たちも喜べ。神があなたがたのために、この都をさばかれたのだから。」'),
('JPN', '启示录', 66, 18, 21, 'また、一人の強い御使いが、大きいひき臼のような石を取り上げ、海に投げ込んで言った。「大きな都バビロンは、このように荒々しく投げ捨てられ、もはや決して見出されることはない。'),
('JPN', '启示录', 66, 18, 22, '竪琴を弾く者たち、歌を歌う者たち、笛を吹く者たち、ラッパを鳴らす者たちの奏でる音が、おまえのうちで、もはや決して聞かれることはない。あらゆる技術を持つ職人たちも、おまえのうちで、もはや決して見出されることはない。石臼の音も、おまえのうちで、もはや決して聞かれることはない。'),
('JPN', '启示录', 66, 18, 23, 'ともしびの光も、おまえのうちで、もはや決して輝くことはない。花婿と花嫁の声も、おまえのうちで、もはや決して聞かれることはない。というのは、おまえの商人たちが地上で権力を握り、おまえの魔術によってすべての国々の民が惑わされ、'),
('JPN', '启示录', 66, 18, 24, 'この都の中に、預言者たちや聖徒たちの血、また地上で屠られたすべての人々の血が見出されたからである。」'),
('JPN', '启示录', 66, 19, 1, 'その後、私は、大群衆の大きな声のようなものが、天でこう言うのを聞いた。「ハレルヤ。救いと栄光と力は私たちの神のもの。'),
('JPN', '启示录', 66, 19, 2, '神のさばきは真実で正しいからである。神は、淫行で地を腐敗させた大淫婦をさばき、ご自分のしもべたちの血の報復を彼女にされた。」'),
('JPN', '启示录', 66, 19, 3, 'もう一度、彼らは言った。「ハレルヤ。彼女が焼かれる煙は、世々限りなく立ち上る。」'),
('JPN', '启示录', 66, 19, 4, 'すると、二十四人の長老たちと四つの生き物はひれ伏して、御座に着いておられる神を礼拝して言った。「アーメン。ハレルヤ。」'),
('JPN', '启示录', 66, 19, 5, 'また、御座から声が出て、こう言った。「神のすべてのしもべたちよ、神を恐れる者たちよ、小さい者も大きい者も私たちの神を賛美せよ。」'),
('JPN', '启示录', 66, 19, 6, 'また私は、大群衆の声のような、大水のとどろきのような、激しい雷鳴のようなものがこう言うのを聞いた。「ハレルヤ。私たちの神である主、全能者が王となられた。'),
('JPN', '启示录', 66, 19, 7, '私たちは喜び楽しみ、神をほめたたえよう。子羊の婚礼の時が来て、花嫁は用意ができたのだから。'),
('JPN', '启示录', 66, 19, 8, '花嫁は、輝くきよい亜麻布をまとうことが許された。その亜麻布とは、聖徒たちの正しい行いである。」'),
('JPN', '启示录', 66, 19, 9, '御使いは私に、「子羊の婚宴に招かれている者たちは幸いだ、と書き記しなさい」と言い、また「これらは神の真実なことばである」と言った。'),
('JPN', '启示录', 66, 19, 10, '私は御使いの足もとにひれ伏して、礼拝しようとした。すると、御使いは私に言った。「いけません。私はあなたや、イエスの証しを堅く保っている、あなたの兄弟たちと同じしもべです。神を礼拝しなさい。イエスの証しは預言の霊なのです。」'),
('JPN', '启示录', 66, 19, 11, 'また私は、天が開かれているのを見た。すると見よ、白い馬がいた。それに乗っている方は「確かで真実な方」と呼ばれ、義をもってさばき、戦いをされる。'),
('JPN', '启示录', 66, 19, 12, 'その目は燃える炎のようであり、その頭には多くの王冠があり、ご自分のほかはだれも知らない名が記されていた。'),
('JPN', '启示录', 66, 19, 13, 'その方は血に染まった衣をまとい、その名は「神のことば」と呼ばれていた。'),
('JPN', '启示录', 66, 19, 14, '天の軍勢は白くきよい亜麻布を着て、白い馬に乗って彼に従っていた。'),
('JPN', '启示录', 66, 19, 15, 'この方の口からは、諸国の民を打つために鋭い剣が出ていた。鉄の杖で彼らを牧するのは、この方である。また、全能者なる神の激しい憤りのぶどうの踏み場を踏まれるのは、この方である。'),
('JPN', '启示录', 66, 19, 16, 'その衣と、もものところには、「王の王、主の主」という名が記されていた。'),
('JPN', '启示录', 66, 19, 17, 'また私は、一人の御使いが太陽の中に立っているのを見た。彼は大声で叫び、中天を飛んでいるすべての鳥たちに言った。「さあ、神の大宴会に集まれ。'),
('JPN', '启示录', 66, 19, 18, '王たちの肉、千人隊長の肉、力ある者たちの肉、馬とそれに乗っている者たちの肉、すべての自由人と奴隷たち、また小さい者や大きい者たちの肉を食べよ。」'),
('JPN', '启示录', 66, 19, 19, 'また私は、獣と地の王たちとその軍勢が集まって、馬に乗る方とその軍勢に戦いを挑むのを見た。'),
('JPN', '启示录', 66, 19, 20, 'しかし、獣は捕らえられた。また、獣の前でしるしを行い、それによって獣の刻印を受けた者たちと、獣の像を拝む者たちを惑わした偽預言者も、獣とともに捕らえられた。この両者は生きたまま、硫黄の燃える火の池に投げ込まれた。'),
('JPN', '启示录', 66, 19, 21, '残りの者たちは、馬に乗っている方の口から出る剣によって殺され、すべての鳥が彼らの肉を飽きるほど食べた。'),
('JPN', '启示录', 66, 20, 1, 'また私は、御使いが底知れぬ所の鍵と大きな鎖を手にして、天から下って来るのを見た。'),
('JPN', '启示录', 66, 20, 2, '彼は、竜、すなわち、悪魔でありサタンである古い蛇を捕らえて、これを千年の間縛り、'),
('JPN', '启示录', 66, 20, 3, '千年が終わるまで、これ以上諸国の民を惑わすことのないように、底知れぬ所に投げ込んで鍵をかけ、その上に封印をした。その後、竜はしばらくの間、解き放たれることになる。'),
('JPN', '启示录', 66, 20, 4, 'また私は多くの座を見た。それらの上に座っている者たちがいて、彼らにはさばきを行う権威が与えられた。また私は、イエスの証しと神のことばのゆえに首をはねられた人々のたましいを見た。彼らは獣もその像も拝まず、額にも手にも獣の刻印を受けていなかった。彼らは生き返って、キリストとともに千年の間、王として治めた。'),
('JPN', '启示录', 66, 20, 5, '残りの死者は、千年が終わるまでは生き返らなかった。これが第一の復活である。'),
('JPN', '启示录', 66, 20, 6, 'この第一の復活にあずかる者は幸いな者、聖なる者である。この人々に対して、第二の死は何の力も持っていない。彼らは神とキリストの祭司となり、キリストとともに千年の間、王として治める。'),
('JPN', '启示录', 66, 20, 7, 'しかし、千年が終わると、サタンはその牢から解き放たれ、'),
('JPN', '启示录', 66, 20, 8, '地の四方にいる諸国の民を、すなわちゴグとマゴグを惑わすために出て行き、戦いのために彼らを召集する。彼らの数は海の砂のようである。'),
('JPN', '启示录', 66, 20, 9, '彼らは地の広いところに上って行き、聖徒たちの陣営と、愛された都を包囲した。すると天から火が下って来て、彼らを焼き尽くした。'),
('JPN', '启示录', 66, 20, 10, '彼らを惑わした悪魔は火と硫黄の池に投げ込まれた。そこには獣も偽預言者もいる。彼らは昼も夜も、世々限りなく苦しみを受ける。'),
('JPN', '启示录', 66, 20, 11, 'また私は、大きな白い御座と、そこに着いておられる方を見た。地と天はその御前から逃げ去り、跡形もなくなった。'),
('JPN', '启示录', 66, 20, 12, 'また私は、死んだ人々が大きい者も小さい者も御座の前に立っているのを見た。数々の書物が開かれた。書物がもう一つ開かれたが、それはいのちの書であった。死んだ者たちは、これらの書物に書かれていることにしたがい、自分の行いに応じてさばかれた。'),
('JPN', '启示录', 66, 20, 13, '海はその中にいる死者を出した。死とよみも、その中にいる死者を出した。彼らはそれぞれ自分の行いに応じてさばかれた。'),
('JPN', '启示录', 66, 20, 14, 'それから、死とよみは火の池に投げ込まれた。これが、すなわち火の池が、第二の死である。'),
('JPN', '启示录', 66, 20, 15, 'いのちの書に記されていない者はみな、火の池に投げ込まれた。'),
('JPN', '启示录', 66, 21, 1, 'また私は、新しい天と新しい地を見た。以前の天と以前の地は過ぎ去り、もはや海もない。'),
('JPN', '启示录', 66, 21, 2, '私はまた、聖なる都、新しいエルサレムが、夫のために飾られた花嫁のように整えられて、神のみもとから、天から降って来るのを見た。'),
('JPN', '启示录', 66, 21, 3, '私はまた、大きな声が御座から出て、こう言うのを聞いた。「見よ、神の幕屋が人々とともにある。神は人々とともに住み、人々は神の民となる。神ご自身が彼らの神として、ともにおられる。'),
('JPN', '启示录', 66, 21, 4, '神は彼らの目から涙をことごとくぬぐい取ってくださる。もはや死はなく、悲しみも、叫び声も、苦しみもない。以前のものが過ぎ去ったからである。」'),
('JPN', '启示录', 66, 21, 5, 'すると、御座に座っておられる方が言われた。「見よ、わたしはすべてを新しくする。」また言われた。「書き記せ。これらのことばは真実であり、信頼できる。」'),
('JPN', '启示录', 66, 21, 6, 'また私に言われた。「事は成就した。わたしはアルファであり、オメガである。初めであり、終わりである。わたしは渇く者に、いのちの水の泉からただで飲ませる。'),
('JPN', '启示录', 66, 21, 7, '勝利を得る者は、これらのものを相続する。わたしは彼の神となり、彼はわたしの子となる。'),
('JPN', '启示录', 66, 21, 8, 'しかし、臆病な者、不信仰な者、忌まわしい者、人を殺す者、淫らなことを行う者、魔術を行う者、偶像を拝む者、すべて偽りを言う者たちが受ける分は、火と硫黄の燃える池の中にある。これが第二の死である。」'),
('JPN', '启示录', 66, 21, 9, 'また、最後の七つの災害で満ちた、あの七つの鉢を持っていた七人の御使いの一人がやって来て、私に語りかけた。「ここに来なさい。あなたに子羊の妻である花嫁を見せましょう。」'),
('JPN', '启示录', 66, 21, 10, 'そして、御使いは御霊によって私を大きな高い山に連れて行き、聖なる都エルサレムが神のみもとから、天から降って来るのを見せた。'),
('JPN', '启示录', 66, 21, 11, '都には神の栄光があった。その輝きは最高の宝石に似ていて、透き通った碧玉のようであった。'),
('JPN', '启示录', 66, 21, 12, '都には、大きな高い城壁があり、十二の門があった。門の上には十二人の御使いがいた。また、名前が刻まれていたが、それはイスラエルの子らの十二部族の名前であった。'),
('JPN', '启示录', 66, 21, 13, '東に三つの門、北に三つの門、南に三つの門、西に三つの門があった。'),
('JPN', '启示录', 66, 21, 14, '都の城壁には十二の土台石があり、それには、子羊の十二使徒の、十二の名が刻まれていた。'),
('JPN', '启示录', 66, 21, 15, 'また、私に語りかけた御使いは、都とその門と城壁を測るために金の測り竿を持っていた。'),
('JPN', '启示录', 66, 21, 16, '都は四角形で、長さと幅は同じである。御使いが都をその竿で測ると、一万二千スタディオンあった。長さも幅も高さも同じである。'),
('JPN', '启示录', 66, 21, 17, 'また城壁を測ると、百四十四ペキスあった。これは人間の尺度であるが、御使いの尺度も同じであった。'),
('JPN', '启示录', 66, 21, 18, '都の城壁は碧玉で造られ、都は透き通ったガラスに似た純金でできていた。'),
('JPN', '启示录', 66, 21, 19, '都の城壁の土台石はあらゆる宝石で飾られていた。第一の土台石は碧玉、第二はサファイア、第三はめのう、第四はエメラルド、'),
('JPN', '启示录', 66, 21, 20, '第五は赤縞めのう、第六は赤めのう、第七は貴かんらん石、第八は緑柱石、第九はトパーズ、第十はひすい、第十一は青玉、第十二は紫水晶であった。'),
('JPN', '启示录', 66, 21, 21, '十二の門は十二の真珠であり、どの門もそれぞれ一つの真珠からできていた。都の大通りは純金で、透明なガラスのようであった。'),
('JPN', '启示录', 66, 21, 22, '私は、この都の中に神殿を見なかった。全能の神である主と子羊が、都の神殿だからである。'),
('JPN', '启示录', 66, 21, 23, '都は、これを照らす太陽も月も必要としない。神の栄光が都を照らし、子羊が都の明かりだからである。'),
('JPN', '启示录', 66, 21, 24, '諸国の民は都の光によって歩み、地の王たちは自分たちの栄光を都に携えて来る。'),
('JPN', '启示录', 66, 21, 25, '都の門は一日中、決して閉じられない。そこには夜がないからである。'),
('JPN', '启示录', 66, 21, 26, 'こうして人々は、諸国の民の栄光と誉れを都に携えて来ることになる。'),
('JPN', '启示录', 66, 21, 27, 'しかし、すべての汚れたもの、また忌まわしいことや偽りを行う者は、決して都に入れない。入ることができるのは、子羊のいのちの書に記されている者たちだけである。'),
('JPN', '启示录', 66, 22, 1, '御使いはまた、水晶のように輝く、いのちの水の川を私に見せた。川は神と子羊の御座から出て、'),
('JPN', '启示录', 66, 22, 2, '都の大通りの中央を流れていた。こちら側にも、あちら側にも、十二の実をならせるいのちの木があって、毎月一つの実を結んでいた。その木の葉は諸国の民を癒やした。'),
('JPN', '启示录', 66, 22, 3, 'もはや、のろわれるものは何もない。神と子羊の御座が都の中にあり、神のしもべたちは神に仕え、'),
('JPN', '启示录', 66, 22, 4, '御顔を仰ぎ見る。また、彼らの額には神の御名が記されている。'),
('JPN', '启示录', 66, 22, 5, 'もはや夜がない。神である主が彼らを照らされるので、ともしびの光も太陽の光もいらない。彼らは世々限りなく王として治める。'),
('JPN', '启示录', 66, 22, 6, '御使いは私に言った。「これらのことばは真実であり、信頼できます。」預言者たちに霊を授ける神である主は、御使いを遣わして、すぐに起こるべきことをしもべたちに示された。'),
('JPN', '启示录', 66, 22, 7, '「見よ、わたしはすぐに来る。この書の預言のことばを守る者は幸いである。」'),
('JPN', '启示录', 66, 22, 8, 'これらのことを聞き、また見たのは、私ヨハネである。私は、聞いたり見たりした後に、これらのことを示してくれた御使いの足もとにひれ伏して、礼拝しようとした。'),
('JPN', '启示录', 66, 22, 9, 'すると、御使いは私に言った。「いけません。私はあなたや、預言者であるあなたの兄弟たち、この書のことばを守る人々と同じしもべです。神を礼拝しなさい。」'),
('JPN', '启示录', 66, 22, 10, 'また私に言った。「この書の預言のことばを封じてはなりません。時が近いからです。'),
('JPN', '启示录', 66, 22, 11, '不正を行う者には、ますます不正を行わせ、汚れた者は、ますます汚れた者とならせなさい。正しい者には、ますます正しいことを行わせ、聖なる者は、ますます聖なる者とならせなさい。」'),
('JPN', '启示录', 66, 22, 12, '「見よ、わたしはすぐに来る。それぞれの行いに応じて報いるために、わたしは報いを携えて来る。'),
('JPN', '启示录', 66, 22, 13, 'わたしはアルファであり、オメガである。最初であり、最後である。初めであり、終わりである。」'),
('JPN', '启示录', 66, 22, 14, '自分の衣を洗う者たちは幸いである。彼らはいのちの木の実を食べる特権が与えられ、門を通って都に入れるようになる。'),
('JPN', '启示录', 66, 22, 15, '犬ども、魔術を行う者、淫らなことを行う者、人を殺す者、偶像を拝む者、すべて偽りを好み、また行う者は、外にとどめられる。'),
('JPN', '启示录', 66, 22, 16, '「わたしイエスは御使いを遣わし、諸教会について、これらのことをあなたがたに証しした。わたしはダビデの根、また子孫、輝く明けの明星である。」'),
('JPN', '启示录', 66, 22, 17, '御霊と花嫁が言う。「来てください。」これを聞く者も「来てください」と言いなさい。渇く者は来なさい。いのちの水が欲しい者は、ただで受けなさい。'),
('JPN', '启示录', 66, 22, 18, '私は、この書の預言のことばを聞くすべての者に証しする。もし、だれかがこれにつけ加えるなら、神がその者に、この書に書かれている災害を加えられる。'),
('JPN', '启示录', 66, 22, 19, 'また、もし、だれかがこの預言の書のことばから何かを取り除くなら、神は、この書に書かれているいのちの木と聖なる都から、その者の受ける分を取り除かれる。'),
('JPN', '启示录', 66, 22, 20, 'これらのことを証しする方が言われる。「しかり、わたしはすぐに来る。」アーメン。主イエスよ、来てください。'),
('JPN', '启示录', 66, 22, 21, '主イエスの恵みが、すべての者とともにありますように。')
on conflict (version, book, chapter, verse) do nothing;
